class GitHubApiError(RuntimeError):
    def __init__(self, method: str, path: str, status: int, detail: str):
        super().__init__(f"GitHub API {method} {path} failed: {detail}")
        self.method = method
        self.path = path
        self.status = status
        self.detail = detail
