def database_state_files() -> dict[str, Path]:
    from storage.retired_state import RETIRED_BOOTSTRAP_KEYS

    files = {
        "postRecords": POST_RECORDS_FILE,
        "chapterLedger": CHAPTER_LEDGER_FILE,
        "approvalCleared": APPROVAL_INBOX_CLEARED_FILE,
        "recoveryLog": RECOVERY_LOG_FILE,
        "chapterPath": CHAPTER_PATH_FILE,
        "chapterReleaseQueue": CHAPTER_RELEASE_QUEUE_FILE,
        # Phase 2 single-blob state -> state_snapshots kv (DB-first + dual-write)
        "storyHookStatus": STORY_HOOK_STATUS_FILE,
        "imageLab": IMAGE_LAB_FILE,
        "imageFeedback": IMAGE_FEEDBACK_FILE,
        "youtubePostDrafts": YOUTUBE_POST_DRAFTS_FILE,
        "contentExperiments": CONTENT_EXPERIMENTS_FILE,
        # Phase 2C: growth/strategy state
        "growthControlCenter": GROWTH_CONTROL_CENTER_FILE,
        "growthOptimizerPlan": GROWTH_OPTIMIZER_FILE,
        "growthWeeklyReport": GROWTH_WEEKLY_REPORT_FILE,
        "weeklyGrowthSettings": WEEKLY_GROWTH_SETTINGS_FILE,
        "predictiveGrowthPlan": PREDICTIVE_GROWTH_PLAN_FILE,
        "instagramGrowthBlueprint": INSTAGRAM_GROWTH_BLUEPRINT_FILE,
        "conversionTracking": CONVERSION_TRACKING_FILE,
        "profileConversionAudit": PROFILE_AUDIT_FILE,
        "brandBrain": BRAND_BRAIN_FILE,
        "arcCampaigns": ARC_CAMPAIGN_FILE,
        "commentAssistant": COMMENT_ASSISTANT_FILE,
        "commentGatherResults": COMMENT_GATHER_RAW_FILE,
        "metricsGatherResults": METRICS_GATHER_FILE,
        "growthStatsHistory": GROWTH_STATS_HISTORY_FILE,
        "automationStrategy": AUTOMATION_STRATEGY_FILE,
        # Phase 2D: job-state / YouTube / app-ops
        "youtubePendingUpload": YOUTUBE_PENDING_UPLOAD_FILE,
        "youtubeMetadataExperiments": YOUTUBE_METADATA_EXPERIMENTS_FILE,
        "chatgptChapterStatus": CHATGPT_CHAPTER_STATUS_FILE,
        "chatgptChapterResult": CHATGPT_CHAPTER_RESULT_FILE,
        "thumbnailTests": THUMBNAIL_TESTS_FILE,
        "googleAiImageUsage": GOOGLE_AI_IMAGE_USAGE_FILE,
        "patreonPendingDraft": PATREON_PENDING_DRAFT_FILE,
        "backgroundVideoUsage": BACKGROUND_VIDEO_USAGE_FILE,
        "clickupSync": CLICKUP_SYNC_FILE,
        "monetizationStatus": MONETIZATION_STATUS_FILE,
        # NOTE: releaseStatus, creatorBenchmarks, youtubeCommentQueue, and
        # youtubePinnedCommentVerified were removed from the JSON bootstrap
        # (Phase-3 retirement, 2026-07-23). They are sourced from SQLite
        # (release_status table / state_snapshots), and their root JSON mirrors
        # are dead and quarantined.
    }
    # Enforcement: block re-registration of retired bootstrap keys. If any
    # retired key is re-added here, startup must fail loudly rather than
    # silently re-import a dead mirror.
    leaked = RETIRED_BOOTSTRAP_KEYS & set(files.keys())
    if leaked:
        raise RuntimeError(
            f"database_state_files() re-registered retired Phase-3 keys: {sorted(leaked)}. "
            f"These are SQLite-backed; do not restore their JSON bootstrap."
        )
    return files


def ensure_state_database() -> dict[str, Any]:
    return automation_db.database_status(ROOT)


def bootstrap_state_database_from_json() -> dict[str, Any]:
    from storage.retired_state import RETIRED_BOOTSTRAP_KEYS

    files = database_state_files()
    # Enforcement: block re-registration of retired bootstrap keys. This runs
    # here (not only inside database_state_files) so any caller-supplied map is
    # also validated, and a monkeypatched map cannot silently re-introduce a
    # dead mirror.
    leaked = RETIRED_BOOTSTRAP_KEYS & set(files.keys())
    if leaked:
        raise RuntimeError(
            f"bootstrap received retired Phase-3 keys: {sorted(leaked)}. "
            f"These are SQLite-backed; do not restore their JSON bootstrap."
        )
    return automation_db.bootstrap_from_json_files(ROOT, files)


