def load_recovery_log() -> dict[str, Any]:
    # Phase 3/Phase-1-retirement: SQLite (state_snapshots kv) is the source of
    # truth. The JSON mirror is retired.
    data = load_state_snapshot_from_database("recoveryLog")
    if not isinstance(data, dict):
        data = {"events": [], "updatedAt": ""}
    data.setdefault("events", [])
    return data


def save_recovery_log(data: dict[str, Any]) -> None:
    data.setdefault("events", [])
    data["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    # Persist the assembled list to SQLite (kv) as the sole store. The per-event
    # DB table insert (mirror_recovery_event_to_database) is kept as a bonus
    # structured audit trail.
    mirror_state_snapshot_to_database("recoveryLog", data)


def recovery_retry_path(error_type: str) -> str:
    return {
        "openai_tts_quota": "Use Windows .NET speech, then Windows SAPI, then a non-silent fallback audio bed with burned subtitles.",
        "buffer_queue_full": "Open the Buffer Playwright/manual scheduling cockpit and queue after reviewing.",
        "github_conflict": "Refresh the latest GitHub file SHA and retry the PUT request.",
        "image_exists": "Reuse the existing chapter image pack instead of regenerating.",
        "chapter_exists_online": "Open the existing online chapter editor and update instead of creating a new chapter.",
        "quality_gate_failed": "Fix the listed media/text issue, then rerun the same push/build step.",
    }.get(error_type, "Review the saved error, then rerun the failed step.")


def record_recovery_event(
    step: str,
    reason: str,
    *,
    retry_path: str = "",
    error_type: str = "",
    folder: str | Path | None = None,
    abbr: str = "",
    chapter: int | str = "",
    details: dict[str, Any] | None = None,
) -> dict[str, Any]:
    event = {
        "time": time.strftime("%Y-%m-%d %H:%M:%S"),
        "step": step,
        "errorType": error_type or step,
        "reason": str(reason),
        "retryPath": retry_path or recovery_retry_path(error_type or step),
        "folder": str(folder or ""),
        "abbr": story_key(abbr),
        "chapter": str(chapter or ""),
        "details": details or {},
    }
    log = load_recovery_log()
    events = list(log.get("events") or [])
    events.append(event)
    log["events"] = events[-250:]
    save_recovery_log(log)
    mirror_recovery_event_to_database(event)
    target_folder = Path(folder).resolve() if folder else None
    if target_folder and target_folder.exists():
        metadata_path = target_folder / "metadata.json"
        metadata = json.loads(metadata_path.read_text(encoding="utf-8")) if metadata_path.exists() else {}
        metadata.setdefault("recovery_events", []).append(event)
        metadata["last_recovery"] = event
        metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
        if not event["abbr"] or not event["chapter"]:
            detected_abbr, detected_chapter, _ = chapter_ledger_updates_for_folder(target_folder, metadata)
            event["abbr"] = event["abbr"] or detected_abbr
            event["chapter"] = event["chapter"] or (str(detected_chapter) if detected_chapter else "")
    if event["abbr"] and str(event["chapter"]).isdigit():
        entry = chapter_ledger_entry(event["abbr"], int(event["chapter"]))
        failed_steps = list(entry.get("failedSteps") or [])
        failed_steps.append(event)
        update_chapter_ledger(
            event["abbr"],
            int(event["chapter"]),
            {
                "lastFailure": event,
                "retryPath": event["retryPath"],
                "failedSteps": failed_steps[-25:],
            },
        )
    return event


def find_ffmpeg_executable() -> str:
    configured = os.environ.get("FFMPEG_EXE")
    if configured and Path(configured).exists():
        return configured
    local = LOCAL_FFMPEG_DIR / "bin" / "ffmpeg.exe"
    if local.exists():
        return str(local)
    tools = ROOT / "tools"
    if tools.exists():
        for path in tools.rglob("ffmpeg.exe"):
            return str(path)
    return "ffmpeg"


def file_signature(path: Path) -> tuple[str, int, int] | None:
    try:
        stat = path.stat()
        return (str(path.resolve()).lower(), int(stat.st_size), int(stat.st_mtime_ns))
    except OSError:
        return None


def media_probe_info(path: Path) -> dict[str, Any]:
    signature = file_signature(path)
    if not signature or signature[1] < 1024:
        return {"exists": False, "duration": 0.0, "width": 0, "height": 0, "streamTypes": []}
    cached = MEDIA_PROBE_CACHE.get(signature)
    if cached is not None:
        return cached
    ffprobe = Path(find_ffmpeg_executable()).with_name("ffprobe.exe")
    command = [
        str(ffprobe if ffprobe.exists() else "ffprobe"),
        "-v",
        "error",
        "-show_entries",
        "format=duration",
        "-show_streams",
        "-of",
        "json",
        str(path),
    ]
    info: dict[str, Any] = {"exists": True, "duration": 0.0, "width": 0, "height": 0, "streamTypes": []}
    try:
        run = subprocess.run(command, capture_output=True, text=True, timeout=20, check=False)
        data = json.loads(run.stdout or "{}") if run.returncode == 0 else {}
        streams = data.get("streams") if isinstance(data.get("streams"), list) else []
        stream_types: list[str] = []
        for stream in streams:
            if not isinstance(stream, dict):
                continue
            codec_type = str(stream.get("codec_type") or "").strip().lower()
            if codec_type:
                stream_types.append(codec_type)
            if codec_type == "video" and not info["width"]:
                info["width"] = int(stream.get("width") or 0)
                info["height"] = int(stream.get("height") or 0)
        info["streamTypes"] = stream_types
        format_info = data.get("format") if isinstance(data.get("format"), dict) else {}
        info["duration"] = float(str(format_info.get("duration") or "0").strip() or 0)
    except Exception:
        pass
    if len(MEDIA_PROBE_CACHE) > 2000:
        MEDIA_PROBE_CACHE.clear()
    MEDIA_PROBE_CACHE[signature] = info
    return info


def media_file_valid(path: Path, kind: str = "v:0") -> bool:
    info = media_probe_info(path)
    stream_types = set(info.get("streamTypes") or [])
    if not stream_types:
        return False
    if not kind:
        return True
    if str(kind).startswith("v"):
        return "video" in stream_types
    if str(kind).startswith("a"):
        return "audio" in stream_types
    return True


def media_duration_seconds(path: Path) -> float:
    return float(media_probe_info(path).get("duration") or 0.0)


def video_meets_minimum_duration(path: Path, minimum_seconds: float = 3.0) -> bool:
    return media_file_valid(path, "v:0") and media_duration_seconds(path) >= minimum_seconds


def wait_for_video_ready(path: Path, minimum_duration: float = 0.0, timeout_seconds: float = 90.0) -> tuple[bool, float]:
    deadline = time.time() + max(1.0, timeout_seconds)
    last_size = -1
    stable_seen_at = 0.0
    duration = 0.0
    while time.time() < deadline:
        if path.exists() and path.stat().st_size > 1024:
            size = path.stat().st_size
            if size == last_size:
                stable_seen_at = stable_seen_at or time.time()
            else:
                stable_seen_at = 0.0
                last_size = size
            if stable_seen_at and time.time() - stable_seen_at >= 1.5 and media_file_valid(path, "v:0"):
                duration = media_duration_seconds(path)
                if duration >= minimum_duration:
                    return True, duration
                if minimum_duration <= 0:
                    return True, duration
        time.sleep(2)
    if media_file_valid(path, "v:0"):
        duration = media_duration_seconds(path)
        return duration >= minimum_duration, duration
    return False, 0.0


def expected_youtube_min_duration(folder: Path) -> float:
    text_path = folder / "chapter-text.txt"
    if not text_path.exists():
        return 45.0
    try:
        words = len(text_path.read_text(encoding="utf-8").split())
    except OSError:
        return 45.0
    if words < 100:
        return 15.0
    estimated_seconds = words / 180 * 60
    return max(45.0, estimated_seconds * 0.55)


