def openai_api_key_diagnostics() -> dict[str, Any]:
    load_env_file()
    key = os.environ.get("OPENAI_API_KEY", "").strip()
    malformed_lines: list[str] = []
    if ENV_FILE.exists():
        try:
            for line_number, line in enumerate(ENV_FILE.read_text(encoding="utf-8").splitlines(), start=1):
                stripped = line.strip()
                if not stripped or stripped.startswith("#") or "=" in stripped:
                    continue
                if stripped.startswith(("sk-", "sk_")) or len(stripped) > 40:
                    malformed_lines.append(f"line {line_number}")
        except OSError:
            pass
    looks_complete = bool(
        key
        and key.startswith(("sk-", "sk_"))
        and len(key) >= 100
        and not re.search(r"\s", key)
        and not malformed_lines
    )
    issue = ""
    if key and malformed_lines:
        issue = "OPENAI_API_KEY appears to be split across multiple lines in .env.local. Re-save it as one single line."
    elif key and not looks_complete:
        issue = "OPENAI_API_KEY is saved, but it looks incomplete or malformed."
    elif not key:
        issue = "OPENAI_API_KEY is not saved."
    return {
        "saved": bool(key),
        "looksComplete": looks_complete,
        "length": len(key),
        "malformedEnvLines": malformed_lines,
        "issue": issue,
    }


def openai_image_configured() -> bool:
    return bool(openai_api_key_diagnostics().get("looksComplete"))


