def load_monetization_status() -> dict[str, Any]:
    data = _phase2_load_blob("monetizationStatus", MONETIZATION_STATUS_FILE)
    default = default_monetization_status()
    if not isinstance(data, dict):
        data = default
    data.setdefault("schemaVersion", 1)
    data.setdefault("updatedAt", "")
    data.setdefault("monthlyPatreonRevenue", 0)
    data.setdefault("bufferUpgradeMonthlyBudget", 0)
    data.setdefault("monthlyExpenseTarget", 100)
    data.setdefault("imageGenerationToolBudget", 20)
    data.setdefault("priorityMode", "auto")
    platforms = data.setdefault("platforms", {})
    for key, value in default["platforms"].items():
        platform = platforms.setdefault(key, {})
        for field, fallback in value.items():
            platform.setdefault(field, fallback)
            if platform.get(field) in ("", None) and not isinstance(fallback, bool):
                platform[field] = fallback
    if not MONETIZATION_STATUS_FILE.exists():
        _phase2_save_blob("monetizationStatus", MONETIZATION_STATUS_FILE, data)
    return data


def save_monetization_status(data: dict[str, Any]) -> dict[str, Any]:
    current = load_monetization_status()
    platforms = current.setdefault("platforms", {})
    incoming_platforms = data.get("platforms") if isinstance(data.get("platforms"), dict) else {}
    for key, incoming in incoming_platforms.items():
        if key not in platforms or not isinstance(incoming, dict):
            continue
        for field, value in incoming.items():
            if isinstance(platforms[key].get(field), bool):
                if isinstance(value, str):
                    platforms[key][field] = value.strip().lower() in {"1", "true", "yes", "on"}
                else:
                    platforms[key][field] = bool(value)
            else:
                if value in ("", None):
                    continue
                try:
                    platforms[key][field] = float(value) if "." in str(value) else int(value)
                except (TypeError, ValueError):
                    continue
    for field in ["monthlyPatreonRevenue", "bufferUpgradeMonthlyBudget"]:
        if field in data:
            try:
                current[field] = float(data.get(field) or 0)
            except (TypeError, ValueError):
                current[field] = 0
    if str(data.get("priorityMode") or "").strip():
        current["priorityMode"] = str(data.get("priorityMode")).strip()
    current["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    _phase2_save_blob("monetizationStatus", MONETIZATION_STATUS_FILE, current)
    return current


def numeric_metric(value: Any, default: float = 0.0) -> float:
    if isinstance(value, bool):
        return 1.0 if value else 0.0
    if value in ("", None):
        return default
    try:
        return float(str(value).replace(",", "").strip())
    except (TypeError, ValueError):
        return default


def monetization_gap(current: float, target: float) -> dict[str, Any]:
    current = max(0.0, numeric_metric(current))
    target = max(1.0, numeric_metric(target, 1.0))
    return {
        "current": current,
        "target": target,
        "remaining": max(0.0, target - current),
        "percent": round(min(100.0, current / target * 100.0), 1),
        "met": current >= target,
    }


def platform_growth_score(platform: dict[str, Any], view_key: str = "views30Days") -> float:
    followers = numeric_metric(platform.get("followers") or platform.get("subscribers"))
    views = numeric_metric(platform.get(view_key))
    avg = numeric_metric(platform.get("avgViewsPerPost"))
    return views * 0.65 + followers * 0.25 + avg * 0.10


def x_metrics_reliable(x: dict[str, Any]) -> bool:
    return any(
        numeric_metric(x.get(key)) > 0
        for key in ["organicImpressions90Days", "verifiedFollowers", "followers", "views30Days"]
    ) or bool(x.get("premiumActive"))


def platform_display_name(platform: str) -> str:
    key = str(platform or "").lower()
    return {
        "tiktok": "TikTok",
        "youtube": "YouTube",
        "x": "X",
        "instagram": "Instagram",
        "facebook": "Facebook",
        "patreon": "Patreon",
        "royalroad": "Royal Road",
    }.get(key, key.title())


def monetization_dashboard() -> dict[str, Any]:
    status = load_monetization_status()
    platforms = status.get("platforms", {})
    tiktok = platforms.get("tiktok", {})
    instagram = platforms.get("instagram", {})
    youtube = platforms.get("youtube", {})
    x = platforms.get("x", {})
    facebook = platforms.get("facebook", {})
    patreon = platforms.get("patreon", {})
    monthly_revenue = max(numeric_metric(status.get("monthlyPatreonRevenue")), numeric_metric(patreon.get("monthlyRevenue")))
    expense_target = numeric_metric(status.get("monthlyExpenseTarget") or 100) or 100
    image_budget = numeric_metric(status.get("imageGenerationToolBudget") or 20) or 20
    income_gap = max(0, expense_target - monthly_revenue)
    revenue_plan = {
        "monthlyExpenseTarget": expense_target,
        "currentMonthlyRevenue": monthly_revenue,
        "incomeGap": income_gap,
        "imageGenerationToolBudget": image_budget,
        "targetMix": [
            {"label": "10 members at $10/month", "membersNeeded": max(0, math.ceil(income_gap / 10)) if income_gap else 0},
            {"label": "20 members at $5/month", "membersNeeded": max(0, math.ceil(income_gap / 5)) if income_gap else 0},
            {"label": "5 supporters at $20/month", "membersNeeded": max(0, math.ceil(income_gap / 20)) if income_gap else 0},
        ],
        "focus": "Use every high-performing Short/Reel and full YouTube chapter to push one clear action: follow for the next chapter or join Patreon to read ahead.",
    }
    youtube_long = [
        monetization_gap(youtube.get("subscribers", 0), 1000),
        monetization_gap(youtube.get("publicWatchHours12Months", 0), 4000),
    ]
    youtube_shorts = [
        monetization_gap(youtube.get("subscribers", 0), 1000),
        monetization_gap(youtube.get("shortsViews90Days", 0), 10000000),
    ]
    goals = {
        "monthlyToolBudget": {
            "label": "$100/month tool budget",
            "gaps": {
                "recurringRevenue": monetization_gap(monthly_revenue, expense_target),
                "imageGenerationTool": monetization_gap(monthly_revenue, image_budget),
            },
            "note": "This is the near-term business target: cover image generation, scheduling, and growth tooling before expanding paid services.",
        },
        "tiktokCreatorRewards": {
            "label": "TikTok Creator Rewards path",
            "gaps": {
                "followers": monetization_gap(tiktok.get("followers", 0), 10000),
                "views30Days": monetization_gap(tiktok.get("views30Days", 0), 100000),
                "oneMinutePostsPerDay": monetization_gap(tiktok.get("oneMinutePostsPerDay", 0), 1),
            },
            "note": "Use TikTok for reach. Add at least one 61-75 second original cut per active novel when quota allows.",
        },
        "youtubeLongFormYpp": {
            "label": "YouTube long-form YPP path",
            "gaps": {
                "subscribers": youtube_long[0],
                "watchHours": youtube_long[1],
                "publicVideosLast90Days": monetization_gap(youtube.get("publicVideosLast90Days", 0), 3),
            },
            "note": "Full chapter videos help watch hours. Shorts views do not count toward the 4,000 public watch hours path.",
        },
        "youtubeShortsYpp": {
            "label": "YouTube Shorts YPP path",
            "gaps": {
                "subscribers": youtube_shorts[0],
                "shortsViews90Days": youtube_shorts[1],
                "publicVideosLast90Days": monetization_gap(youtube.get("publicVideosLast90Days", 0), 3),
            },
            "note": "This is a harder volume path, so avoid burning the 10/day limit on weak variants.",
        },
        "xRevenueSharing": {
            "label": "X creator revenue path",
            "gaps": {
                "premiumActive": {"met": bool(x.get("premiumActive")), "current": bool(x.get("premiumActive")), "target": True, "remaining": 0 if x.get("premiumActive") else 1, "percent": 100 if x.get("premiumActive") else 0},
                "verifiedFollowers": monetization_gap(x.get("verifiedFollowers", 0), 500),
                "organicImpressions90Days": monetization_gap(x.get("organicImpressions90Days", 0), 5000000),
            },
            "note": "Use X for visibility and conversations, but do not make it the main revenue path until verified follower and impression gaps shrink.",
        },
        "bufferUpgrade": {
            "label": "Paid Buffer readiness",
            "gaps": {
                "monthlyPatreonRevenue": monetization_gap(status.get("monthlyPatreonRevenue", 0), status.get("bufferUpgradeMonthlyBudget", 0) or 1),
            },
            "note": "Set your target monthly Buffer budget here. The app will treat this as ready once Patreon or creator revenue covers it.",
        },
    }
    scores = {
        "tiktok": platform_growth_score(tiktok),
        "instagram": platform_growth_score(instagram),
        "youtube": numeric_metric(youtube.get("publicWatchHours12Months")) * 2 + numeric_metric(youtube.get("shortsViews90Days")) * 0.01 + numeric_metric(youtube.get("subscribers")) * 5,
        "facebook": platform_growth_score(facebook),
    }
    if x_metrics_reliable(x):
        scores["x"] = numeric_metric(x.get("organicImpressions90Days")) * 0.08 + numeric_metric(x.get("verifiedFollowers") or x.get("followers")) * 10
    priority_mode = str(status.get("priorityMode") or "auto")
    if priority_mode == "auto":
        primary = max(scores.items(), key=lambda item: item[1])[0] if scores else "tiktok"
        if scores.get("tiktok", 0) >= scores.get("instagram", 0):
            primary = "tiktok"
        elif scores.get("instagram", 0) > 0:
            primary = "instagram"
    else:
        primary = priority_mode
        if primary == "x" and not x_metrics_reliable(x):
            primary = "tiktok"
    recommendations = []
    recommendations.append({
        "platform": primary,
        "action": {
            "tiktok": "Prioritize 2-3 TikTok/Reel test variants per active chapter, plus one 61-75 second monetization cut when possible.",
            "instagram": "Prioritize Reels plus conversion posts. Use Instagram follower strength to push Royal Road and Patreon.",
            "youtube": "Prioritize one full chapter video per novel queue and protect the 10/day Shorts limit.",
            "x": "Prioritize conversation posts and replies. Verification/impressions are the bottleneck.",
            "facebook": "Use the Page for public trust and repost strongest Instagram/Facebook-ready variants.",
        }.get(primary, "Prioritize TikTok and Instagram until another platform clearly outperforms them."),
    })
    if not goals["tiktokCreatorRewards"]["gaps"]["followers"]["met"]:
        recommendations.append({"platform": "tiktok", "action": "Follower gap remains. Use hooks that ask readers to follow for the next chapter, not just to like."})
    if not goals["youtubeLongFormYpp"]["gaps"]["watchHours"]["met"]:
        recommendations.append({"platform": "youtube", "action": "Watch-hour gap remains. Keep full chapter videos separate from the main promo workflow and post consistently."})
    if numeric_metric(instagram.get("followers")) >= numeric_metric(tiktok.get("followers")):
        recommendations.append({"platform": "instagram", "action": "Instagram is your trust/follower anchor. Use it for carousels, reels, and profile-to-Patreon conversion."})
    weekly_report = _phase2_load_blob("growthWeeklyReport", GROWTH_WEEKLY_REPORT_FILE)
    if not isinstance(weekly_report, dict):
        weekly_report = write_growth_weekly_report()
    youtube_conversion = youtube_subscriber_conversion_plan(20)
    return {
        "status": status,
        "goals": goals,
        "scores": scores,
        "primaryPlatform": primary,
        "ignoredPlatforms": ["x"] if not x_metrics_reliable(x) else [],
        "recommendations": recommendations,
        "revenuePlan": revenue_plan,
        "youtubeSubscriberConversion": youtube_conversion,
        "weeklyOptimization": weekly_report,
        "file": str(MONETIZATION_STATUS_FILE),
    }


def upsert_env_values(values: dict[str, str]) -> None:
    existing: dict[str, str] = {}
    if ENV_FILE.exists():
        for line in ENV_FILE.read_text(encoding="utf-8").splitlines():
            if line.strip() and not line.lstrip().startswith("#") and "=" in line:
                key, value = line.split("=", 1)
                existing[key.strip()] = value.strip()
    for key, value in values.items():
        if value:
            existing[key] = value
            os.environ[key] = value
    ordered = [
        "OPENAI_API_KEY",
        "GOOGLE_AI_API_KEY",
        "GOOGLE_AI_MODEL",
        "GOOGLE_AI_IMAGE_MODEL",
        "YOUTUBE_DATA_API_KEY",
        "YOUTUBE_CHANNEL_HANDLE",
        "YOUTUBE_CHANNEL_ID",
        "GEMINI_MARKETING_TEMPERATURE",
        "PEXELS_API_KEY",
        "PIXABAY_API_KEY",
        "INSTAGRAM_ACCOUNT_ID",
        "INSTAGRAM_ACCESS_TOKEN",
        "INSTAGRAM_PUBLIC_BASE_URL",
        "META_GRAPH_API_VERSION",
        "X_ACCESS_TOKEN",
        "BUFFER_API_KEY",
        "BUFFER_PUBLIC_BASE_URL",
        "BUFFER_CHANNEL_IDS",
        "CLOUDFLARE_R2_ACCOUNT_ID",
        "CLOUDFLARE_R2_ACCESS_KEY_ID",
        "CLOUDFLARE_R2_SECRET_ACCESS_KEY",
        "CLOUDFLARE_R2_BUCKET",
        "CLOUDFLARE_R2_PUBLIC_BASE_URL",
        "GITHUB_PAGES_MEDIA_BASE_URL",
        "GITHUB_REMOTE_URL",
        "GITHUB_MEDIA_REMOTE_URL",
        "GITHUB_TOKEN",
        "GITHUB_AUTO_PUBLISH_MEDIA",
        "CLICKUP_API_TOKEN",
        "CLICKUP_TASK_LIST_ID",
        "CLICKUP_TASK_LIST_NAME",
        "AUTO_RENDER_VIDEOS",
        "CHROME_DEBUG_URL",
        "BACKGROUND_VIDEO_DIR",
        "PROMO_IMAGES_DIR",
    ]
    lines: list[str] = []
    for key in ordered:
        if key in existing:
            lines.append(f"{key}={existing[key]}")
    for key, value in existing.items():
        if key not in ordered:
            lines.append(f"{key}={value}")
    ENV_FILE.write_text("\n".join(lines).strip() + "\n", encoding="utf-8")


def normalize_public_base_url(value: str) -> str:
    value = value.strip().rstrip("/")
    if not value:
        return ""
    if not value.lower().startswith(("http://", "https://")):
        value = f"https://{value}"
    return value


def chrome_debug_url() -> str:
    return os.environ.get("CHROME_DEBUG_URL", "http://127.0.0.1:9222").strip()


def chrome_debug_available() -> tuple[bool, str]:
    url = chrome_debug_url().rstrip("/")
    if not url:
        return False, "Chrome bridge URL is empty."
    try:
        req = urllib.request.Request(f"{url}/json/version", headers={"User-Agent": "AutomationTool/1.0"})
        with urllib.request.urlopen(req, timeout=3) as response:
            data = json.loads(response.read().decode("utf-8"))
        browser_name = str(data.get("Browser") or "Chrome")
        return True, f"Connected to {browser_name} at {url}."
    except Exception as exc:
        return False, f"Existing Chrome is not reachable at {url}. Close Chrome, restart it with --remote-debugging-port=9222, then retry. Details: {exc}"


def open_url_once(url: str) -> bool:
    parsed = None
    target_host = ""
    try:
        parsed = urllib.parse.urlparse(url)
        target_host = parsed.hostname or ""
    except Exception:
        target_host = ""
    base = chrome_debug_url().rstrip("/")
    if base and target_host:
        try:
            with urllib.request.urlopen(f"{base}/json", timeout=3) as response:
                pages = json.loads(response.read().decode("utf-8"))
            target_path = (parsed.path or "/") if parsed else "/"
            target_needs_path = target_path not in {"", "/"}
            same_host_fallback = ""
            for page in pages if isinstance(pages, list) else []:
                page_url = str(page.get("url") or "")
                page_parsed = urllib.parse.urlparse(page_url)
                page_host = page_parsed.hostname or ""
                if page_host.replace("www.", "") != target_host.replace("www.", ""):
                    continue
                page_id = urllib.parse.quote(str(page.get("id") or ""), safe="")
                if not page_id:
                    continue
                if not target_needs_path or page_parsed.path == target_path:
                    urllib.request.urlopen(f"{base}/json/activate/{page_id}", timeout=3).read()
                    return True
                if not same_host_fallback:
                    same_host_fallback = page_id
            if same_host_fallback and not target_needs_path:
                urllib.request.urlopen(f"{base}/json/activate/{same_host_fallback}", timeout=3).read()
                return True
        except Exception:
            pass
        if parsed and parsed.scheme in {"http", "https"}:
            encoded_url = urllib.parse.quote(url, safe=":/?&=%#")
            for method in ("PUT", "GET"):
                try:
                    request = urllib.request.Request(f"{base}/json/new?{encoded_url}", method=method)
                    with urllib.request.urlopen(request, timeout=3) as response:
                        page = json.loads(response.read().decode("utf-8"))
                    page_id = urllib.parse.quote(str(page.get("id") or ""), safe="")
                    if page_id:
                        urllib.request.urlopen(f"{base}/json/activate/{page_id}", timeout=3).read()
                    return True
                except Exception:
                    continue
    try:
        os.startfile(url)
        return True
    except Exception:
        return False


def browser_image_provider_url(provider: str = "") -> str:
    provider = str(provider or "").strip().lower()
    if provider in {"gemini", "google", "google_ai"}:
        return "https://gemini.google.com/app"
    if provider in {"chatgpt", "gpt", "openai"}:
        return "https://chatgpt.com/"
    return "https://gemini.google.com/app" if google_ai_configured() else "https://chatgpt.com/"


def write_browser_image_assist_script(prompt: str, provider: str = "") -> Path:
    target_url = browser_image_provider_url(provider)
    prompt_text = str(prompt or "").strip()
    script = BROWSER_IMAGE_ASSIST_SCRIPT_FILE
    script.write_text(
        f"""const {{ chromium }} = require('playwright');

const cdpUrl = {json.dumps(chrome_debug_url())};
const targetUrl = {json.dumps(target_url)};
const promptText = {json.dumps(prompt_text)};

async function findPromptBox(page) {{
  const selectors = [
    'textarea',
    'div[contenteditable="true"]',
    '[role="textbox"]',
    'rich-textarea div[contenteditable="true"]',
    'ms-autosize-textarea textarea'
  ];
  for (const selector of selectors) {{
    try {{
      const locator = page.locator(selector).last();
      if (await locator.count()) return locator;
    }} catch (error) {{}}
  }}
  return null;
}}

(async () => {{
  const browser = await chromium.connectOverCDP(cdpUrl);
  const context = browser.contexts()[0] || await browser.newContext();
  let page = context.pages().find(candidate => {{
    try {{
      const host = new URL(candidate.url()).hostname.replace(/^www\\./, '');
      return ['gemini.google.com', 'chatgpt.com', 'chat.openai.com'].includes(host);
    }} catch (error) {{
      return false;
    }}
  }});
  if (!page) page = await context.newPage();
  await page.goto(targetUrl, {{ waitUntil: 'domcontentloaded', timeout: 60000 }});
  await page.waitForTimeout(2500);
  const box = await findPromptBox(page);
  if (!box) {{
    console.log('Browser image prompt is copied below. Prompt box was not found, likely because login is needed.');
    console.log(promptText);
    return;
  }}
  await box.click({{ timeout: 10000 }});
  await page.keyboard.insertText(promptText);
  await page.keyboard.press('Enter');
  console.log('Browser image generation prompt submitted.');
}})().catch(error => {{
  console.error(error);
  process.exit(1);
}});
""",
        encoding="utf-8",
    )
    return script


def start_browser_image_assist(
    *,
    prompt: str,
    folder: Path,
    target: Path,
    purpose: str,
    import_endpoint: str = "",
    provider: str = "",
    errors: list[str] | None = None,
) -> dict[str, Any]:
    folder = Path(folder).resolve()
    target = Path(target).resolve()
    chrome_ready, chrome_message = chrome_debug_available()
    launched = False
    script = ""
    if chrome_ready and playwright_available():
        script_path = write_browser_image_assist_script(prompt, provider)
        script = str(script_path)
        try:
            launched = launch_playwright_script(script_path, ROOT)
        except Exception:
            launched = False
    assist = {
        "ok": True,
        "purpose": purpose,
        "provider": "gemini" if "gemini" in browser_image_provider_url(provider) else "chatgpt",
        "prompt": str(prompt or ""),
        "folder": str(folder),
        "target": str(target),
        "importEndpoint": import_endpoint,
        "chromeReady": chrome_ready,
        "chromeMessage": chrome_message,
        "playwrightAvailable": playwright_available(),
        "playwrightLaunched": launched,
        "playwrightScript": script,
        "errors": errors or [],
        "createdAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "instructions": "Review the browser-generated image, save it locally, then use the matching Import button in this pack to load it into the proper place.",
    }
    write_json_atomic(BROWSER_IMAGE_ASSIST_FILE, assist)
    try:
        (folder / "browser-image-assist.json").write_text(json.dumps(assist, indent=2), encoding="utf-8")
    except Exception:
        pass
    return assist


