def youtube_links_block(story: str = "") -> str:
    # Public descriptions should point to the profile hub without exposing raw URLs.
    lines = ["All links and next chapters are in bio."]
    royal_road_url = royal_road_url_for_story(story)
    if royal_road_url:
        lines.append(f"Read {NOVEL_NAMES.get(story_key(story), 'this web novel')} free on Royal Road through the link in bio.")
    lines.append("Support the release schedule on Patreon through the link in bio.")
    return "\n".join(lines)


def youtube_midroll_narration(chapter_text: str) -> str:
    """Insert the support CTA near a sentence boundary without changing source prose."""
    body = normalize_story_text(chapter_text).strip()
    if not body or YOUTUBE_MIDROLL_CTA.lower() in body.lower():
        return body
    midpoint = len(body) // 2
    lower = max(0, int(len(body) * 0.35))
    upper = min(len(body), int(len(body) * 0.65))
    boundaries = [match.end() for match in re.finditer(r"[.!?][\"']?(?:\s+|$)", body[lower:upper])]
    split_at = lower + min(boundaries, key=lambda value: abs((lower + value) - midpoint)) if boundaries else midpoint
    return f"{body[:split_at].rstrip()}\n\n{YOUTUBE_MIDROLL_CTA}\n\n{body[split_at:].lstrip()}".strip()


def youtube_pinned_comment_text(metadata: dict[str, Any]) -> str:
    custom = str(
        metadata.get("pinned_comment")
        or metadata.get("youtubePinnedComment")
        or metadata.get("youtube_pinned_comment")
        or ""
    ).strip()
    if custom:
        return custom
    abbr = story_key(str(metadata.get("abbr") or metadata.get("novel") or ""))
    novel = str(metadata.get("novel") or NOVEL_NAMES.get(abbr, abbr)).strip()
    chapter = str(metadata.get("chapter") or "").strip()
    rr_url = royal_road_url_for_story(abbr)
    heading = f"Thanks for listening to {novel}"
    if chapter:
        heading += " Prologue" if chapter in {"0", "prologue", "Prologue"} else f" Chapter {chapter}"
    lines = [heading + "!", ""]
    lines.append("Subscribe for the next chapter and tell me which moment you want animated next.")
    lines.append("")
    if rr_url:
        lines.append(f"Continue reading on Royal Road: {rr_url}")
    lines.append(f"Read ahead on Patreon: {PATREON_URL}")
    lines.extend(["", "Question: what moment from this chapter stood out to you?"])
    return "\n".join(lines).strip()


def load_youtube_comment_queue() -> dict[str, Any]:
    data = load_state_snapshot_from_database("youtubeCommentQueue")
    if not isinstance(data, dict):
        data = {"schemaVersion": 1, "items": []}
    if not isinstance(data.get("items"), list):
        data["items"] = []
    return data


def load_verified_pinned_comments() -> dict[str, Any]:
    data = load_state_snapshot_from_database("youtubePinnedCommentVerified")
    if not isinstance(data, dict):
        data = {"schemaVersion": 1, "videos": {}}
    if not isinstance(data.get("videos"), dict):
        data["videos"] = {}
    return data


def save_youtube_comment_queue(queue: dict[str, Any]) -> None:
    automation_db.upsert_state_snapshot(ROOT, "youtubeCommentQueue", queue)


def save_verified_pinned_comments(data: dict[str, Any]) -> None:
    automation_db.upsert_state_snapshot(ROOT, "youtubePinnedCommentVerified", data)


def verified_pinned_video_ids() -> set[str]:
    data = load_verified_pinned_comments()
    return {
        str(video_id)
        for video_id, item in data.get("videos", {}).items()
        if re.fullmatch(r"[A-Za-z0-9_-]{11}", str(video_id))
        and isinstance(item, dict)
        and item.get("status") == "pinned"
    }


def mark_youtube_comment_verified_pinned(item: dict[str, Any]) -> None:
    video_id = str(item.get("videoId") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_-]{11}", video_id):
        return
    data = load_verified_pinned_comments()
    data.setdefault("videos", {})[video_id] = {
        "status": "pinned",
        "verifiedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "commentId": str(item.get("id") or ""),
        "uploadId": str(item.get("uploadId") or ""),
        "title": str(item.get("title") or ""),
        "folder": str(item.get("folder") or ""),
        "watchUrl": str(item.get("watchUrl") or f"https://www.youtube.com/watch?v={video_id}"),
    }
    data["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    save_verified_pinned_comments(data)


def backfill_verified_pinned_comments_from_queue() -> int:
    count = 0
    queue = load_youtube_comment_queue()
    before = verified_pinned_video_ids()
    for item in queue.get("items", []):
        if isinstance(item, dict) and item.get("status") == "pinned":
            mark_youtube_comment_verified_pinned(item)
    after = verified_pinned_video_ids()
    count = len(after - before)
    return count


def queue_youtube_pinned_comment(*args, **kwargs):
    return youtube_pipeline.queue_youtube_pinned_comment(*args, **kwargs)
def youtube_comment_capture_video(upload_id: str, video_id: str = "", video_url: str = "") -> dict[str, Any] | None:
    match = re.search(r"(?:youtu\.be/|[?&]v=|/video/)([A-Za-z0-9_-]{11})", video_url)
    video_id = str(video_id or (match.group(1) if match else "")).strip()
    if not re.fullmatch(r"[A-Za-z0-9_-]{11}", video_id):
        return None
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    with YOUTUBE_COMMENT_QUEUE_LOCK:
        queue = load_youtube_comment_queue()
        item = next((entry for entry in queue["items"] if str(entry.get("uploadId") or "") == str(upload_id)), None)
        if not item:
            return None
        item["videoId"] = video_id
        item["watchUrl"] = f"https://www.youtube.com/watch?v={video_id}"
        if item.get("status") not in {"posted", "pinned"}:
            item["status"] = "waiting_public"
        item["updatedAt"] = now
        queue["updatedAt"] = now
        save_youtube_comment_queue(queue)
        return dict(item)


def youtube_comment_mark_release(folder: Path, upload_id: str, status: str) -> dict[str, Any] | None:
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    with YOUTUBE_COMMENT_QUEUE_LOCK:
        queue = load_youtube_comment_queue()
        item = next(
            (entry for entry in queue["items"] if upload_id and str(entry.get("uploadId") or "") == str(upload_id)),
            None,
        )
        if not item:
            item = next((entry for entry in queue["items"] if str(entry.get("folder") or "") == str(folder)), None)
        if not item:
            return None
        item["releaseStatus"] = status
        if item.get("status") not in {"posted", "pinned"}:
            item["status"] = "ready" if status == "published" and item.get("videoId") else (
                "waiting_public" if item.get("videoId") else "waiting_video_id"
            )
        item["updatedAt"] = now
        queue["updatedAt"] = now
        save_youtube_comment_queue(queue)
        return dict(item)


def youtube_comment_helper_pending(video_id: str = "") -> dict[str, Any]:
    queue = load_youtube_comment_queue()
    verified_ids = verified_pinned_video_ids()
    items = [
        item for item in queue["items"]
        if item.get("status") in {"waiting_public", "ready", "posted"}
        and (item.get("status") != "posted" or int(item.get("pinAttempts") or 0) < 3)
        and (item.get("status") != "waiting_public" or item.get("watchUrl") or item.get("videoId"))
        and str(item.get("videoId") or "") not in verified_ids
    ]
    if video_id:
        items = [item for item in items if str(item.get("videoId") or "") == str(video_id)]
    priority = {"ready": 0, "waiting_public": 1, "posted": 2}
    items.sort(key=lambda item: (
        priority.get(str(item.get("status") or ""), 9),
        int(item.get("pinAttempts") or 0),
        str(item.get("updatedAt") or item.get("createdAt") or ""),
    ))
    return {"item": dict(items[0]) if items else None, "count": len(items)}


def youtube_comment_helper_start_backfill() -> dict[str, Any]:
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    reset = 0
    verified_ids = verified_pinned_video_ids()
    with YOUTUBE_COMMENT_QUEUE_LOCK:
        queue = load_youtube_comment_queue()
        for item in queue.get("items", []):
            video_id = str(item.get("videoId") or "")
            if video_id in verified_ids:
                item["status"] = "pinned"
                item["updatedAt"] = now
                continue
            last_error = str(item.get("lastError") or "")
            permanent = any(needle in last_error.lower() for needle in ["pin menu", "comments may be disabled", "comment box was not available"])
            if item.get("status") == "failed" and not permanent and (item.get("videoId") or item.get("watchUrl")):
                item["status"] = "ready"
                item["lastError"] = ""
                item["pinAttempts"] = 0
                item["updatedAt"] = now
                reset += 1
        if reset:
            queue["updatedAt"] = now
            save_youtube_comment_queue(queue)
    pending = youtube_comment_helper_pending()
    item = pending.get("item")
    launched = False
    launch_error = ""
    if item and playwright_available() and chrome_debug_available()[0]:
        try:
            script = write_youtube_comment_pin_script()
            node = bundled_node_executable()
            node_modules = ROOT / "node_modules"
            browsers_path = ROOT / "ms-playwright"
            subprocess.Popen(
                [str(node), str(script)],
                cwd=str(ROOT),
                env={**os.environ, "NODE_PATH": str(node_modules), "PLAYWRIGHT_BROWSERS_PATH": str(browsers_path)},
                creationflags=subprocess.CREATE_NO_WINDOW if hasattr(subprocess, "CREATE_NO_WINDOW") else 0,
            )
            launched = True
        except Exception as exc:
            launch_error = str(exc)
    return {
        "ok": True,
        "reset": reset,
        "item": item,
        "count": pending.get("count", 0),
        "watchUrl": (item or {}).get("watchUrl", ""),
        "playwrightLaunched": launched,
        "playwrightError": launch_error,
        "message": (
            "Pinned-comment worker started in helper Chrome." if launched else
            ("Pinned-comment backfill is ready, but the worker could not be launched." if item else "No scanned YouTube comments need pinning.")
        ),
    }


def write_youtube_comment_pin_script() -> Path:
    YOUTUBE_COMMENT_PIN_SCRIPT_FILE.write_text(
        f'''const fs = require('fs');
const {{ chromium }} = require('playwright');

const cdpUrl = {json.dumps(chrome_debug_url())};
const resultPath = {json.dumps(str(YOUTUBE_COMMENT_PIN_RESULT_FILE))};
const apiBases = ['http://127.0.0.1:{PORT}', 'http://localhost:{PORT}', 'http://127.0.0.1:8765', 'http://localhost:8765', 'http://127.0.0.1:8766', 'http://localhost:8766'];
let activeBase = '';
const results = [];

function wait(ms) {{ return new Promise((resolve) => setTimeout(resolve, ms)); }}
function cleanText(value) {{ return String(value || '').replace(/\\s+/g, ' ').trim(); }}
function visible(el) {{
  if (!el) return false;
  const box = el.getBoundingClientRect();
  const style = window.getComputedStyle(el);
  return box.width > 0 && box.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
}}
async function api(path, options = {{}}) {{
  const bases = activeBase ? [activeBase, ...apiBases.filter((base) => base !== activeBase)] : apiBases;
  let lastError = null;
  for (const base of bases) {{
    try {{
      const response = await fetch(`${{base}}${{path}}`, {{ cache: 'no-store', ...options }});
      if (response.ok) {{
        activeBase = base;
        return await response.json();
      }}
      lastError = new Error(`Automation tool at ${{base}} returned ${{response.status}}: ${{await response.text()}}`);
    }} catch (error) {{
      lastError = error;
    }}
  }}
  throw lastError || new Error('Automation tool is not reachable.');
}}
async function ack(item, status, error = '') {{
  return api('/api/youtube-comment-helper/ack', {{
    method: 'POST',
    headers: {{'Content-Type': 'application/json'}},
    body: JSON.stringify({{commentId: item.id, status, error}})
  }});
}}
async function pending(videoId = '') {{
  const suffix = videoId ? `?videoId=${{encodeURIComponent(videoId)}}` : '';
  return api(`/api/youtube-comment-helper/pending${{suffix}}`);
}}
async function getText(page, locator) {{
  try {{ return cleanText(await locator.innerText({{ timeout: 1500 }})); }} catch (_) {{ return ''; }}
}}
async function existingMatchingComment(page, item) {{
  const needle = cleanText(item.comment).slice(0, 70).toLowerCase();
  if (!needle) return null;
  const threads = page.locator('ytd-comment-thread-renderer');
  const count = await threads.count().catch(() => 0);
  for (let i = 0; i < count; i += 1) {{
    const thread = threads.nth(i);
    const text = (await getText(page, thread)).toLowerCase();
    if (text.includes(needle)) return thread;
  }}
  return null;
}}
async function scrollToComments(page) {{
  for (let attempt = 0; attempt < 18; attempt += 1) {{
    const comments = page.locator('ytd-comments').first();
    if (await comments.count().catch(() => 0)) {{
      await comments.scrollIntoViewIfNeeded().catch(() => null);
      await page.waitForTimeout(900);
      if (await page.locator('#placeholder-area, #simplebox-placeholder, #contenteditable-root[contenteditable="true"]').count().catch(() => 0)) return;
    }}
    await page.mouse.wheel(0, 900);
    await page.waitForTimeout(700);
  }}
}}
async function findCommentEditor(page) {{
  await scrollToComments(page);
  for (let attempt = 0; attempt < 30; attempt += 1) {{
    const placeholder = page.locator('#placeholder-area:visible, #simplebox-placeholder:visible, ytd-comment-simplebox-renderer').first();
    if (await placeholder.count().catch(() => 0)) {{
      await placeholder.click({{ timeout: 3000 }}).catch(() => null);
      await page.waitForTimeout(500);
    }}
    const editor = page.locator('ytd-comment-simplebox-renderer #contenteditable-root[contenteditable="true"]:visible, #contenteditable-root[contenteditable="true"]:visible').first();
    if (await editor.count().catch(() => 0)) return editor;
    await page.keyboard.press('PageDown').catch(() => null);
    await page.waitForTimeout(700);
  }}
  return null;
}}
async function clickCommentSubmit(page) {{
  const clicked = await page.evaluate(() => {{
    const visible = (el) => {{
      if (!el) return false;
      const box = el.getBoundingClientRect();
      const style = window.getComputedStyle(el);
      return box.width > 0 && box.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
    }};
    const boxes = Array.from(document.querySelectorAll('ytd-comment-simplebox-renderer'));
    for (const box of boxes) {{
      const buttons = Array.from(box.querySelectorAll('button, #submit-button, [role="button"]'));
      for (const button of buttons) {{
        const text = String(button.innerText || button.textContent || button.getAttribute('aria-label') || '').trim().toLowerCase();
        const disabled = button.disabled || button.getAttribute('disabled') !== null || button.getAttribute('aria-disabled') === 'true';
        if (visible(button) && !disabled && /comment|submit|post/.test(text)) {{
          button.click();
          return true;
        }}
      }}
    }}
    return false;
  }}).catch(() => false);
  if (clicked) return true;
  const submit = page.locator('ytd-comment-simplebox-renderer button:visible:not([disabled]), ytd-comment-simplebox-renderer [role="button"]:visible').filter({{ hasText: /Comment|Submit|Post/i }}).first();
  if (await submit.count().catch(() => 0)) {{
    await submit.click({{ timeout: 5000 }});
    return true;
  }}
  return false;
}}
async function postComment(page, item) {{
  if (await existingMatchingComment(page, item)) {{
    await ack(item, 'posted');
    return true;
  }}
  const editor = await findCommentEditor(page);
  if (!editor) throw new Error('YouTube comment box was not available. The video may not be public, or comments may be disabled.');
  await editor.click({{ timeout: 5000 }});
  await page.keyboard.press(process.platform === 'darwin' ? 'Meta+A' : 'Control+A').catch(() => null);
  await page.keyboard.type(item.comment || '', {{ delay: 1 }}).catch(async () => {{
    await editor.evaluate((el, value) => {{
      el.textContent = value;
      el.dispatchEvent(new InputEvent('input', {{ bubbles: true, inputType: 'insertText', data: value }}));
    }}, item.comment || '');
  }});
  await page.waitForTimeout(700);
  if (!(await clickCommentSubmit(page))) throw new Error('YouTube comment submit button was not available after entering text.');
  for (let attempt = 0; attempt < 20; attempt += 1) {{
    await page.waitForTimeout(1000);
    await page.reload({{ waitUntil: 'domcontentloaded', timeout: 60000 }}).catch(() => null);
    await scrollToComments(page);
    if (await existingMatchingComment(page, item)) {{
      await ack(item, 'posted');
      return true;
    }}
  }}
  await ack(item, 'posted', 'Comment submitted, but it was not visible yet for pinning.');
  return true;
}}
async function pinComment(page, item) {{
  for (let attempt = 0; attempt < 24; attempt += 1) {{
    await scrollToComments(page);
    const thread = await existingMatchingComment(page, item);
    if (thread) {{
      const text = await getText(page, thread);
      if (/pinned by/i.test(text)) return true;
      await thread.hover().catch(() => null);
      const menu = thread.locator('#action-menu button:visible, #action-menu [role="button"]:visible, yt-icon-button button:visible').first();
      if (await menu.count().catch(() => 0)) {{
        await menu.click({{ timeout: 5000 }}).catch(() => null);
        await page.waitForTimeout(700);
        const pin = page.locator('ytd-menu-service-item-renderer:visible, tp-yt-paper-item:visible, [role="menuitem"]:visible').filter({{ hasText: /^\\s*Pin\\b/i }}).first();
        if (await pin.count().catch(() => 0)) {{
          await pin.click({{ timeout: 5000 }});
          await page.waitForTimeout(700);
          const confirm = page.locator('yt-confirm-dialog-renderer button:visible, tp-yt-paper-dialog button:visible').filter({{ hasText: /^\\s*Pin\\s*$/i }}).first();
          if (await confirm.count().catch(() => 0)) await confirm.click({{ timeout: 5000 }});
          await page.waitForTimeout(1500);
          return true;
        }}
      }}
    }}
    await page.mouse.wheel(0, 700);
    await page.waitForTimeout(1000);
  }}
  if (await existingMatchingComment(page, item)) throw new Error('The posted comment is visible, but the pin menu was not available.');
  throw new Error('The posted comment was not found for pinning.');
}}

(async () => {{
  const browser = await chromium.connectOverCDP(cdpUrl);
  const context = browser.contexts()[0] || await browser.newContext();
  let page = context.pages().find((candidate) => {{
    try {{ return new URL(candidate.url()).hostname.endsWith('youtube.com'); }} catch (_) {{ return false; }}
  }});
  if (!page) page = await context.newPage();
  for (let index = 0; index < 80; index += 1) {{
    const data = await pending();
    const item = data.item;
    if (!item || !item.watchUrl) break;
    try {{
      await page.goto(item.watchUrl, {{ waitUntil: 'domcontentloaded', timeout: 60000 }});
      await page.bringToFront().catch(() => null);
      await page.waitForTimeout(2500);
      if (item.status !== 'posted') await postComment(page, item);
      await pinComment(page, item);
      await ack(item, 'pinned');
      results.push({{ id: item.id, title: item.title, videoId: item.videoId, status: 'pinned' }});
    }} catch (error) {{
      const failedStatus = /not visible yet/i.test(error.message) ? 'posted' : 'failed';
      await ack(item, failedStatus, error.message).catch(() => null);
      results.push({{ id: item.id, title: item.title, videoId: item.videoId, status: failedStatus, error: error.message }});
    }}
    fs.writeFileSync(resultPath, JSON.stringify({{ updatedAt: new Date().toISOString(), results }}, null, 2), 'utf8');
    await page.waitForTimeout(800);
  }}
  fs.writeFileSync(resultPath, JSON.stringify({{ finishedAt: new Date().toISOString(), results }}, null, 2), 'utf8');
  process.exit(0);
}})().catch((error) => {{
  fs.writeFileSync(resultPath, JSON.stringify({{ finishedAt: new Date().toISOString(), error: error.message, stack: error.stack, results }}, null, 2), 'utf8');
  process.exit(1);
}});
''',
        encoding="utf-8",
    )
    return YOUTUBE_COMMENT_PIN_SCRIPT_FILE


def youtube_comment_helper_ack(comment_id: str, status: str, error: str = "") -> dict[str, Any]:
    status = str(status or "").strip().lower()
    if status not in {"posted", "pinned", "failed", "retry"}:
        raise RuntimeError("Use posted, pinned, failed, or retry for YouTube comment status.")
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    with YOUTUBE_COMMENT_QUEUE_LOCK:
        queue = load_youtube_comment_queue()
        item = next((entry for entry in queue["items"] if str(entry.get("id") or "") == str(comment_id)), None)
        if not item:
            raise RuntimeError("YouTube comment queue item was not found.")
        item["attempts"] = int(item.get("attempts") or 0) + (1 if status in {"failed", "posted"} else 0)
        if status == "posted" and error:
            item["pinAttempts"] = int(item.get("pinAttempts") or 0) + 1
        if status == "pinned":
            item["pinAttempts"] = int(item.get("pinAttempts") or 0)
        item["status"] = "ready" if status == "retry" else status
        item["updatedAt"] = now
        item["lastError"] = str(error or "")
        if status == "posted":
            item["postedAt"] = now
        if status == "pinned":
            item["pinnedAt"] = now
            mark_youtube_comment_verified_pinned(item)
        queue["updatedAt"] = now
        save_youtube_comment_queue(queue)
    try:
        folder = Path(str(item.get("folder") or "")).resolve()
        metadata = read_metadata(folder)
        abbr, chapter_number, updates = chapter_ledger_updates_for_folder(folder, metadata, "youtubePinnedComment")
        if abbr and chapter_number:
            updates.update(
                {
                    "youtubeCommentStatus": item["status"],
                    "youtubeCommentPosted": item["status"] in {"posted", "pinned"},
                    "youtubeCommentPinned": item["status"] == "pinned",
                    "youtubeCommentUpdatedAt": now,
                    "youtubeVideoId": str(item.get("videoId") or ""),
                }
            )
            update_chapter_ledger(abbr, chapter_number, updates)
    except Exception:
        pass
    return {"ok": True, "item": item}


def youtube_library_title_match(title: str) -> tuple[str, int | None, str]:
    cleaned = re.sub(r"\s+", " ", str(title or "")).strip()
    lowered = cleaned.lower()
    aliases = {
        "EN": ["eternal nexus", "en"],
        "HA": ["heavenly ascension system", "heavenly ascension", "ha"],
        "SF": ["soul forge era", "soulforge era", "soul forge", "soulforge", "sf"],
        "HP": ["the hundredfold path", "hundredfold path", "hp"],
    }
    matches: list[str] = []
    for abbr, names in aliases.items():
        if any(
            name in lowered if len(name) > 3 else bool(re.search(rf"(?:^|[^a-z0-9]){re.escape(name)}(?:[^a-z0-9]|$)", lowered))
            for name in names
        ):
            matches.append(abbr)
    if len(matches) != 1:
        return "", None, "Novel could not be identified uniquely from the title."
    if re.search(r"\bprologue\b", lowered):
        return matches[0], 0, ""
    chapter_match = re.search(r"\b(?:chapter|ch\.?)(?:\s*#?\s*)(\d+)[a-z]?\b", lowered, re.IGNORECASE)
    if not chapter_match:
        return matches[0], None, "Chapter number was not found in the title."
    return matches[0], int(chapter_match.group(1)), ""


def youtube_folder_for_chapter(abbr: str, chapter: int) -> Path | None:
    ledger = load_chapter_ledger()
    entry = ledger.get("chapters", {}).get(f"{abbr}-{chapter}", {})
    folders = entry.get("folders") if isinstance(entry.get("folders"), dict) else {}
    folder_text = str(entry.get("youtubeFolder") or folders.get("youtube") or "").strip()
    if folder_text:
        folder = Path(folder_text).resolve()
        if str(folder).startswith(str(YOUTUBE_OUTPUT_DIR.resolve())):
            return folder
    prefix = f"{abbr.lower()}-{chapter}-"
    candidates = sorted(
        [path for path in YOUTUBE_OUTPUT_DIR.glob(f"{abbr.lower()}-{chapter}*") if path.is_dir()],
        key=lambda path: (0 if path.name.lower().startswith(prefix) else 1, path.name.lower()),
    )
    return candidates[0].resolve() if candidates else None


def write_youtube_library_scan_script() -> Path:
    verified_ids = sorted(verified_pinned_video_ids())
    YOUTUBE_LIBRARY_SCAN_SCRIPT_FILE.write_text(
        f'''const fs = require('fs');
const {{ chromium }} = require('playwright');

const cdpUrl = {json.dumps(chrome_debug_url())};
const outputPath = {json.dumps(str(YOUTUBE_LIBRARY_SCAN_FILE))};
const configuredChannelId = {json.dumps(YOUTUBE_SOCIAL_URL.rstrip('/').split('/')[-1])};
const verifiedPinnedIds = new Set({json.dumps(verified_ids)});

function durationSeconds(value) {{
  const match = String(value || '').match(/(?:^|\\s)(\\d{{1,2}}:)?(\\d{{1,2}}):(\\d{{2}})(?:\\s|$)/);
  if (!match) return 0;
  const parts = match[0].trim().split(':').map(Number);
  if (parts.length === 3) return parts[0] * 3600 + parts[1] * 60 + parts[2];
  return parts[0] * 60 + parts[1];
}}

function normalizeVideoRows(rows) {{
  return rows.map((row) => {{
    const titleElement = row.querySelector('a#video-title, #video-title');
    const linkElement = titleElement || row.querySelector('a[href*="/video/"]');
    const title = String(titleElement?.getAttribute('aria-label') || titleElement?.getAttribute('title') || titleElement?.textContent || '').trim();
    const href = String(linkElement?.href || linkElement?.getAttribute('href') || '');
    const idMatch = href.match(/\\/video\\/([A-Za-z0-9_-]{{11}})/);
    const text = String(row.innerText || row.textContent || '').replace(/\\s+/g, ' ').trim();
    return {{ title, videoId: idMatch ? idMatch[1] : '', editUrl: href, text }};
  }}).filter((video) => video.title && video.videoId);
}}

async function collectVisibleRows(page, byId) {{
  const rows = await page.locator('ytcp-video-row').evaluateAll(normalizeVideoRows).catch(() => []);
  for (const row of rows) byId.set(row.videoId, row);
  return rows.length;
}}

async function scrollStudioVideoTable(page) {{
  await page.evaluate(() => {{
    const candidates = [
      document.querySelector('ytcp-app'),
      document.querySelector('#main'),
      document.querySelector('#scroll-container'),
      document.querySelector('ytcp-video-section'),
      document.scrollingElement,
      document.documentElement,
      document.body
    ].filter(Boolean);
    for (const element of candidates) {{
      try {{
        const step = Math.max(900, Math.floor((element.clientHeight || window.innerHeight || 900) * 1.35));
        element.scrollTop = Math.min(element.scrollHeight || element.scrollTop + step, (element.scrollTop || 0) + step);
      }} catch (_) {{}}
    }}
  }}).catch(() => null);
  await page.mouse.wheel(0, 1400).catch(() => null);
}}

(async () => {{
  const browser = await chromium.connectOverCDP(cdpUrl);
  const context = browser.contexts()[0] || await browser.newContext();
  let page = context.pages().find((candidate) => {{
    try {{ return new URL(candidate.url()).hostname === 'studio.youtube.com'; }} catch (_) {{ return false; }}
  }});
  if (!page) {{
    page = await context.newPage();
    await page.goto('https://studio.youtube.com', {{ waitUntil: 'domcontentloaded', timeout: 60000 }});
  }}
  await page.bringToFront().catch(() => null);
  await page.waitForTimeout(2500);
  const channelMatch = page.url().match(/\\/channel\\/([^/]+)/);
  const channelId = channelMatch ? channelMatch[1] : configuredChannelId;
  if (channelId) {{
    await page.goto(`https://studio.youtube.com/channel/${{channelId}}/videos/upload`, {{ waitUntil: 'domcontentloaded', timeout: 60000 }}).catch(() => null);
  }} else {{
    const content = page.getByText('Content', {{ exact: true }}).first();
    if (await content.count()) await content.click().catch(() => null);
  }}
  await page.waitForTimeout(3500);
  const videosTab = page.getByText('Videos', {{ exact: true }}).first();
  if (await videosTab.count()) await videosTab.click().catch(() => null);
  await page.waitForTimeout(2500);

  const byId = new Map();
  let stablePasses = 0;
  let previousTotal = 0;
  for (let pass = 0; pass < 90 && stablePasses < 8; pass += 1) {{
    await collectVisibleRows(page, byId);
    stablePasses = byId.size === previousTotal ? stablePasses + 1 : 0;
    previousTotal = byId.size;
    await scrollStudioVideoTable(page);
    await page.waitForTimeout(800);
  }}

  const videos = Array.from(byId.values());
  const skippedVerifiedPinned = videos
    .filter((video) => verifiedPinnedIds.has(video.videoId))
    .map((video) => ({{ ...video, reason: 'Pinned comment already verified.' }}));
  const normalized = videos
    .filter((video) => video.title && video.videoId)
    .map((video) => ({{
      ...video,
      duration: durationSeconds(video.text),
      visibility: /\\bpublic\\b/i.test(video.text) ? 'public' : (/\\bscheduled\\b/i.test(video.text) ? 'scheduled' : (/\\bprivate\\b/i.test(video.text) ? 'private' : 'unknown')),
      madeForKids: /\\bmade for kids\\b/i.test(video.text),
      watchUrl: `https://www.youtube.com/watch?v=${{video.videoId}}`
    }}));
  fs.writeFileSync(outputPath, JSON.stringify({{ scannedAt: new Date().toISOString(), studioUrl: page.url(), videos: normalized, skippedVerifiedPinned }}, null, 2), 'utf8');
  process.exit(0);
}})().catch((error) => {{
  fs.writeFileSync(outputPath, JSON.stringify({{ scannedAt: new Date().toISOString(), error: error.message, stack: error.stack, videos: [] }}, null, 2), 'utf8');
  process.exit(1);
}});
''',
        encoding="utf-8",
    )
    return YOUTUBE_LIBRARY_SCAN_SCRIPT_FILE


def scan_existing_youtube_videos() -> dict[str, Any]:
    backfilled = backfill_verified_pinned_comments_from_queue()
    chrome_ready, chrome_message = chrome_debug_available()
    if not chrome_ready:
        return {"ok": False, "error": chrome_message, "matched": [], "unmatched": []}
    if not playwright_available():
        return {"ok": False, "error": "Playwright is not installed or not reachable in this workspace.", "matched": [], "unmatched": []}
    script = write_youtube_library_scan_script()
    node = bundled_node_executable()
    run = subprocess.run(
        [str(node), str(script)],
        cwd=str(ROOT),
        env={**os.environ, "NODE_PATH": str(ROOT / "node_modules"), "PLAYWRIGHT_BROWSERS_PATH": str(ROOT / "ms-playwright")},
        capture_output=True,
        text=True,
        timeout=180,
        check=False,
    )
    raw = read_json_safe(YOUTUBE_LIBRARY_SCAN_FILE)
    if not isinstance(raw, dict):
        raw = {}
    if raw.get("error"):
        return {"ok": False, "error": str(raw.get("error")), "details": (run.stderr or run.stdout)[-1200:], "matched": [], "unmatched": []}

    matched: list[dict[str, Any]] = []
    unmatched: list[dict[str, Any]] = []
    skipped_shorts: list[dict[str, Any]] = []
    skipped_verified_pinned = raw.get("skippedVerifiedPinned", []) if isinstance(raw.get("skippedVerifiedPinned"), list) else []
    verified_ids = verified_pinned_video_ids()
    for video in raw.get("videos", []) if isinstance(raw.get("videos"), list) else []:
        title = str(video.get("title") or "")
        video_id = str(video.get("videoId") or "")
        if video_id in verified_ids:
            skipped_verified_pinned.append({**video, "reason": "Pinned comment already verified."})
            continue
        duration = float(video.get("duration") or 0)
        if duration and duration < 180:
            skipped_shorts.append({**video, "reason": "Video is under three minutes and was treated as a Short."})
            continue
        abbr, chapter, reason = youtube_library_title_match(title)
        if not abbr or chapter is None:
            unmatched.append({**video, "reason": reason})
            continue
        folder = youtube_folder_for_chapter(abbr, chapter)
        metadata = read_metadata(folder) if folder and (folder / "metadata.json").exists() else {
            "abbr": abbr,
            "novel": NOVEL_NAMES.get(abbr, abbr),
            "chapter": chapter,
            "title": title,
        }
        upload_id = f"library-{video.get('videoId')}"
        queued = queue_youtube_pinned_comment(
            {
                "id": upload_id,
                "folder": str(folder or (YOUTUBE_OUTPUT_DIR / f"{abbr.lower()}-{chapter}")),
                "title": title,
                "metadata": metadata,
            }
        )
        captured = youtube_comment_capture_video(upload_id, str(video.get("videoId") or ""), str(video.get("watchUrl") or "")) or queued
        visibility = str(video.get("visibility") or "unknown").lower()
        release_status = "published" if visibility == "public" else ("scheduled" if visibility == "scheduled" else "uploaded")
        comment_item = youtube_comment_mark_release(Path(str(captured.get("folder") or "")), upload_id, release_status) or captured
        matched.append(
            {
                **video,
                "abbr": abbr,
                "novel": NOVEL_NAMES.get(abbr, abbr),
                "chapter": chapter,
                "folder": str(folder or ""),
                "commentId": comment_item.get("id", ""),
                "commentStatus": comment_item.get("status", ""),
                "alreadyPinned": comment_item.get("status") == "pinned",
            }
        )
    return {
        "ok": True,
        "message": f"Scanned {len(raw.get('videos', []))} unverified YouTube video(s); skipped {len(skipped_verified_pinned)} already-pinned video(s); matched {len(matched)} full chapter video(s).",
        "scannedAt": raw.get("scannedAt", ""),
        "studioUrl": raw.get("studioUrl", ""),
        "matched": matched,
        "unmatched": unmatched,
        "skippedShorts": skipped_shorts,
        "skippedVerifiedPinned": skipped_verified_pinned,
        "verifiedPinnedFile": None,
        "storage": "sqlite",
        "resource": "state_snapshots",
        "verifiedPinnedStateKey": "youtubePinnedCommentVerified",
        "verifiedPinnedBackfilled": backfilled,
        "commentQueue": load_youtube_comment_queue(),
    }


def write_youtube_audience_fix_script(videos: list[dict[str, Any]]) -> Path:
    targets = [
        {
            "videoId": str(video.get("videoId") or ""),
            "title": str(video.get("title") or ""),
            "editUrl": str(video.get("editUrl") or f"https://studio.youtube.com/video/{video.get('videoId')}/edit"),
        }
        for video in videos
        if re.fullmatch(r"[A-Za-z0-9_-]{11}", str(video.get("videoId") or ""))
    ]
    YOUTUBE_AUDIENCE_FIX_SCRIPT_FILE.write_text(
        f'''const fs = require('fs');
const {{ chromium }} = require('playwright');

const cdpUrl = {json.dumps(chrome_debug_url())};
const outputPath = {json.dumps(str(YOUTUBE_AUDIENCE_FIX_FILE))};
const targets = {json.dumps(targets, ensure_ascii=False)};

(async () => {{
  const browser = await chromium.connectOverCDP(cdpUrl);
  const context = browser.contexts()[0] || await browser.newContext();
  let page = context.pages().find((candidate) => {{
    try {{ return new URL(candidate.url()).hostname === 'studio.youtube.com'; }} catch (_) {{ return false; }}
  }});
  if (!page) page = await context.newPage();
  const results = [];
  for (const target of targets) {{
    try {{
      await page.goto(target.editUrl, {{ waitUntil: 'domcontentloaded', timeout: 60000 }});
      const noKids = page.locator('[name="VIDEO_MADE_FOR_KIDS_NOT_MFK"]').first();
      await noKids.waitFor({{ state: 'visible', timeout: 30000 }});
      const before = await noKids.getAttribute('aria-checked');
      if (before !== 'true') {{
        await noKids.scrollIntoViewIfNeeded();
        await noKids.click({{ timeout: 5000 }});
        await page.waitForFunction(() => document.querySelector('[name="VIDEO_MADE_FOR_KIDS_NOT_MFK"]')?.getAttribute('aria-checked') === 'true', null, {{ timeout: 10000 }});
        const save = page.locator('#save button, button[aria-label="Save"]').first();
        await save.waitFor({{ state: 'visible', timeout: 10000 }});
        await page.waitForFunction(() => {{
          const button = document.querySelector('#save');
          return button && !button.hasAttribute('disabled') && button.getAttribute('aria-disabled') !== 'true';
        }}, null, {{ timeout: 10000 }});
        const savedResponse = page.waitForResponse(
          (response) => response.url().includes('/youtubei/v1/video_manager/metadata_update') && response.request().method() === 'POST' && response.ok(),
          {{ timeout: 45000 }}
        );
        await save.click({{ timeout: 5000 }});
        await savedResponse;
        await page.waitForFunction(() => document.querySelector('#save')?.getAttribute('aria-disabled') === 'true', null, {{ timeout: 30000 }});
        await page.waitForTimeout(2500);
      }}
      await page.reload({{ waitUntil: 'domcontentloaded', timeout: 60000 }});
      const verifyNoKids = page.locator('[name="VIDEO_MADE_FOR_KIDS_NOT_MFK"]').first();
      await verifyNoKids.waitFor({{ state: 'visible', timeout: 30000 }});
      const verified = await verifyNoKids.getAttribute('aria-checked') === 'true';
      results.push({{ ...target, ok: verified, changed: before !== 'true', audience: verified ? 'not_made_for_kids' : 'unknown' }});
    }} catch (error) {{
      results.push({{ ...target, ok: false, changed: false, error: error.message }});
    }}
  }}
  fs.writeFileSync(outputPath, JSON.stringify({{ finishedAt: new Date().toISOString(), results }}, null, 2), 'utf8');
  process.exit(0);
}})().catch((error) => {{
  fs.writeFileSync(outputPath, JSON.stringify({{ finishedAt: new Date().toISOString(), error: error.message, stack: error.stack, results: [] }}, null, 2), 'utf8');
  process.exit(1);
}});
''',
        encoding="utf-8",
    )
    return YOUTUBE_AUDIENCE_FIX_SCRIPT_FILE


def fix_existing_youtube_audience() -> dict[str, Any]:
    chrome_ready, chrome_message = chrome_debug_available()
    if not chrome_ready:
        return {"ok": False, "error": chrome_message, "results": []}
    raw = read_json_safe(YOUTUBE_LIBRARY_SCAN_FILE)
    videos = raw.get("videos", []) if isinstance(raw, dict) and isinstance(raw.get("videos"), list) else []
    targets = [video for video in videos if bool(video.get("madeForKids")) or "made for kids" in str(video.get("text") or "").lower()]
    if not targets:
        return {"ok": True, "message": "No scanned videos are marked made for kids.", "changed": 0, "results": []}
    script = write_youtube_audience_fix_script(targets)
    node = bundled_node_executable()
    run = subprocess.run(
        [str(node), str(script)],
        cwd=str(ROOT),
        env={**os.environ, "NODE_PATH": str(ROOT / "node_modules"), "PLAYWRIGHT_BROWSERS_PATH": str(ROOT / "ms-playwright")},
        capture_output=True,
        text=True,
        timeout=420,
        check=False,
    )
    result = read_json_safe(YOUTUBE_AUDIENCE_FIX_FILE)
    if not isinstance(result, dict):
        result = {}
    if result.get("error"):
        return {"ok": False, "error": str(result.get("error")), "details": (run.stderr or run.stdout)[-1200:], "results": result.get("results", [])}
    rows = result.get("results", []) if isinstance(result.get("results"), list) else []
    changed = [row for row in rows if row.get("ok") and row.get("changed")]
    failed = [row for row in rows if not row.get("ok")]
    return {
        "ok": not failed,
        "message": f"Updated {len(changed)} YouTube video(s) to No, it's not made for kids. {len(failed)} failed.",
        "changed": len(changed),
        "failed": len(failed),
        "results": rows,
    }


