def recent_pack_duplicate_warnings(days: int = 30) -> list[dict[str, Any]]:
    warnings: list[dict[str, Any]] = []
    seen_keys: set[str] = set()
    try:
        for item in automation_db.recent_duplicate_post_groups(ROOT, days):
            warnings.append(item)
            seen_keys.add(str(item.get("key") or ""))
    except Exception as exc:
        print(f"Database read failed for duplicate post groups: {exc}", file=sys.stderr)
    cutoff = time.time() - max(1, int(days or 30)) * 86400
    roots = [
        ("social", SOCIAL_OUTPUT_DIR),
        ("tiktok", TIKTOK_OUTPUT_DIR),
        ("experiment", EXPERIMENT_OUTPUT_DIR),
        ("youtube", YOUTUBE_OUTPUT_DIR),
        ("storyHook", STORY_HOOK_OUTPUT_DIR),
    ]
    seen: dict[str, list[dict[str, Any]]] = {}
    for kind, root in roots:
        if not root.exists():
            continue
        for metadata_path in root.glob("*/metadata.json"):
            try:
                if metadata_path.stat().st_mtime < cutoff:
                    continue
                metadata = read_metadata(metadata_path.parent)
            except Exception:
                continue
            abbr = story_key(str(metadata.get("abbr") or ""))
            chapter = str(metadata.get("chapter") or metadata.get("chapter_number") or "").strip()
            content_type = str(metadata.get("kind") or metadata.get("contentType") or kind).strip().lower()
            if not abbr or not chapter:
                continue
            if chapter.lower() == "general":
                continue
            if "experiment-post-packs" in str(metadata_path.parent).replace("\\", "/").lower():
                continue
            if content_type.startswith("experiment") or content_type == "variant-test":
                continue
            key = f"{abbr}:{chapter}:{content_type}"
            seen.setdefault(key, []).append(
                {
                    "kind": kind,
                    "abbr": abbr,
                    "chapter": chapter,
                    "contentType": content_type,
                    "folder": str(metadata_path.parent),
                    "createdAt": metadata.get("createdAt") or time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(metadata_path.stat().st_mtime)),
                }
            )
    for key, items in seen.items():
        if len(items) <= 1:
            continue
        if key in seen_keys:
            continue
        newest = sorted(items, key=lambda item: str(item.get("createdAt") or ""), reverse=True)[0]
        warnings.append(
            {
                "key": key,
                "count": len(items),
                "abbr": newest.get("abbr"),
                "chapter": newest.get("chapter"),
                "contentType": newest.get("contentType"),
                "folders": [item.get("folder") for item in sorted(items, key=lambda item: str(item.get("createdAt") or ""), reverse=True)[:8]],
                "recommendation": "Reuse or rebuild the newest valid pack instead of creating another duplicate folder.",
            }
        )
    warnings.sort(key=lambda item: int(item.get("count") or 0), reverse=True)
    return warnings[:20]


def growth_control_chapter_path() -> dict[str, Any]:
    path_state = load_chapter_path_state()
    release_status = load_release_status()
    next_selections = release_status.get("nextSelections") if isinstance(release_status.get("nextSelections"), dict) else {}
    tools = ["promo", "social", "patreon", "royalRoad", "variants", "write"]
    novels = []
    for abbr, novel in NOVEL_NAMES.items():
        row: dict[str, Any] = {
            "abbr": abbr,
            "novel": novel,
            "locked": bool(path_state.get("active")),
            "pathNextChapter": active_chapter_path_next(abbr, "promo") or active_chapter_path_next(abbr, "social") or "",
            "tools": {},
        }
        for tool in tools:
            selection = next_selections.get(tool, {}).get(abbr, {}) if isinstance(next_selections.get(tool), dict) else {}
            row["tools"][tool] = {
                "nextChapter": active_chapter_path_next(abbr, tool) or selection.get("nextChapter") or "",
                "lastChapter": selection.get("lastChapter") or "",
                "updatedAt": selection.get("updatedAt") or "",
            }
        novels.append(row)
    return {
        "active": bool(path_state.get("active")),
        "updatedAt": path_state.get("updatedAt", ""),
        "novels": novels,
    }


def growth_control_recommended_actions(
    approval: dict[str, Any],
    weekly_stats: dict[str, Any],
    ready_youtube: list[dict[str, Any]],
    duplicate_warnings: list[dict[str, Any]],
    winners: list[dict[str, Any]],
    blueprint: dict[str, Any],
) -> list[dict[str, Any]]:
    actions: list[dict[str, Any]] = []
    if weekly_stats.get("due"):
        actions.append(
            {
                "priority": 0,
                "area": "metrics",
                "title": "Collect growth stats",
                "reason": weekly_stats.get("message") or "Weekly growth stats are due.",
                "button": "Collect Growth Stats",
                "existingAction": "collect-growth-stats",
            }
        )
    failure_count = int((approval.get("counts") or {}).get("failures") or 0)
    if failure_count:
        actions.append(
            {
                "priority": 1,
                "area": "reliability",
                "title": "Clear or retry unresolved failures",
                "reason": f"{failure_count} unresolved failure(s) are still visible in the approval inbox.",
                "button": "Approval Inbox",
                "existingAction": "approval-inbox",
            }
        )
    if duplicate_warnings:
        actions.append(
            {
                "priority": 2,
                "area": "media",
                "title": "Review duplicate pack risk",
                "reason": f"{len(duplicate_warnings)} possible duplicate pack group(s) were found from recent media.",
                "button": "Growth Control Center",
                "existingAction": "growth-control-center",
            }
        )
    if ready_youtube:
        first = ready_youtube[0]
        actions.append(
            {
                "priority": 3,
                "area": "youtube",
                "title": "Upload ready full YouTube videos",
                "reason": f"{len(ready_youtube)} full video(s) are created but not marked uploaded. Next: {first.get('novel') or first.get('abbr')} Ch. {first.get('chapter')}.",
                "button": "Daily YouTube Queue",
                "existingAction": "daily-youtube-status",
            }
        )
    if int(approval.get("total") or 0) > failure_count:
        actions.append(
            {
                "priority": 4,
                "area": "approval",
                "title": "Review pending manual actions",
                "reason": f"{int(approval.get('total') or 0) - failure_count} item(s) need publishing/review attention.",
                "button": "Approval Inbox",
                "existingAction": "approval-inbox",
            }
        )
    top_pillar = (blueprint.get("contentPillars") or [{}])[0]
    if winners:
        best = winners[0]
        actions.append(
            {
                "priority": 5,
                "area": "content",
                "title": f"Reuse winning {best.get('hookType') or 'hook'} structure",
                "reason": f"{best.get('novel') or best.get('abbr')} Ch. {best.get('chapter')} has the strongest measured variant signal.",
                "button": "Make Variants",
                "existingAction": "content-experiment",
            }
        )
    elif top_pillar:
        actions.append(
            {
                "priority": 5,
                "area": "content",
                "title": f"Build today's post around {top_pillar.get('name')}",
                "reason": top_pillar.get("purpose") or "Use the Instagram blueprint's strongest conflict-first pillar.",
                "button": "Build Daily Posts",
                "existingAction": "daily-posts",
            }
        )
    actions.append(
        {
            "priority": 6,
            "area": "growth",
            "title": "Keep full YouTube separate from daily packs",
            "reason": "Long video rendering is slow and should not block the daily short/social workflow.",
            "button": "Daily YouTube Queue",
            "existingAction": "daily-youtube-status",
        }
    )
    return sorted(actions, key=lambda item: int(item.get("priority") or 99))


