def image_lab_score_summary() -> dict[str, Any]:
    cache_key = ""
    try:
        stat = IMAGE_LAB_FILE.stat()
        cache_key = f"{stat.st_mtime_ns}:{stat.st_size}"
    except OSError:
        cache_key = "missing"
    if IMAGE_LAB_SUMMARY_CACHE.get("key") == cache_key:
        return IMAGE_LAB_SUMMARY_CACHE.get("value", {})
    data = _phase2_load_blob("imageLab", IMAGE_LAB_FILE)
    runs = data.get("runs", []) if isinstance(data, dict) and isinstance(data.get("runs"), list) else []
    by_novel: dict[str, dict[str, Any]] = {}
    recent_winners: list[dict[str, Any]] = []
    for run in runs:
        if not isinstance(run, dict):
            continue
        abbr = story_key(str(run.get("abbr") or ""))
        if not abbr:
            continue
        bucket = by_novel.setdefault(abbr, {"abbr": abbr, "novel": NOVEL_NAMES.get(abbr, abbr), "winner": 0, "good": 0, "reject": 0, "total": 0})
        for scored in run.get("scoredImages", []) or []:
            if not isinstance(scored, dict):
                continue
            score = str(scored.get("score") or "").lower()
            if score not in {"winner", "good", "reject"}:
                continue
            bucket[score] += 1
            bucket["total"] += 1
            if score == "winner":
                recent_winners.append({"abbr": abbr, "novel": bucket["novel"], "chapter": run.get("chapter"), "image": scored.get("image"), "scoredAt": scored.get("scoredAt")})
    for bucket in by_novel.values():
        total = max(1, int(bucket.get("total") or 0))
        bucket["winnerRate"] = round(int(bucket.get("winner") or 0) / total, 3)
        bucket["rejectRate"] = round(int(bucket.get("reject") or 0) / total, 3)
        if bucket["rejectRate"] >= 0.45:
            bucket["recommendation"] = "Tighten prompts for this novel before generating more images."
        elif bucket["winnerRate"] >= 0.35:
            bucket["recommendation"] = "Reuse the visual language from recent winners, but keep cooldown rules."
        else:
            bucket["recommendation"] = "Keep testing fresh chapter-specific image prompts."
    recent_winners.sort(key=lambda item: str(item.get("scoredAt") or ""), reverse=True)
    value = {"byNovel": sorted(by_novel.values(), key=lambda item: item["abbr"]), "recentWinners": recent_winners[:12]}
    IMAGE_LAB_SUMMARY_CACHE["key"] = cache_key
    IMAGE_LAB_SUMMARY_CACHE["value"] = value
    return value


def growth_optimizer_plan() -> dict[str, Any]:
    dashboard = monetization_dashboard()
    weekly = write_growth_weekly_report()
    velocity = growth_velocity_summary()
    winners = analytics_winner_recommendations(False).get("recommendations", [])
    image_scores = image_lab_score_summary()
    instagram_blueprint = instagram_growth_blueprint()
    creator_benchmarks = creator_benchmark_dashboard()
    resurfacing = resurfacing_and_repost_candidates()
    novel_strategy = novel_level_strategy()
    ready_youtube = youtube_created_not_uploaded()
    weekly_stats = weekly_growth_stats_status()
    primary = str(dashboard.get("primaryPlatform") or "tiktok")
    moves: list[dict[str, Any]] = []
    if weekly_stats.get("due"):
        moves.append({"priority": 0, "type": "metrics", "title": "Collect growth stats first", "reason": "The weekly stats cadence is due, so current platform weighting may be stale.", "action": "Run Collect Growth Stats before building the next batch."})
    top_pillar = (instagram_blueprint.get("contentPillars") or [{}])[0]
    if top_pillar:
        moves.append({
            "priority": 1,
            "type": "instagram_blueprint",
            "title": f"Instagram pillar: {top_pillar.get('name')}",
            "reason": "The 30-day blueprint prioritizes conflict-first content that can convert viewers into readers.",
            "action": f"Use this structure today: {top_pillar.get('hookStructure') or 'conflict first, consequence second, one CTA.'}",
            "destination": top_pillar.get("destination") or "Royal Road",
        })
    top_velocity = (velocity.get("platforms") or [{}])[0] if velocity.get("available") else {}
    if top_velocity:
        moves.append(
            {
                "priority": 1,
                "type": "platform_focus",
                "title": f"Lean into {platform_display_name(str(top_velocity.get('platform') or primary))} today",
                "reason": f"Highest recent growth velocity: {top_velocity.get('deltas', {})}.",
                "action": "Use the strongest hook pattern on this platform, then route viewers to Royal Road or YouTube depending on the content.",
            }
        )
    else:
        moves.append({"priority": 1, "type": "platform_focus", "title": f"Default focus: {platform_display_name(primary)}", "reason": "Not enough snapshot history for velocity yet.", "action": "Collect another growth snapshot after today's posts to unlock trend decisions."})
    if winners:
        best = winners[0]
        moves.append(
            {
                "priority": 2,
                "type": "hook_reuse",
                "title": f"Reuse a proven {best.get('hookType') or 'high-performing'} hook",
                "reason": f"{best.get('novel') or best.get('abbr')} Ch. {best.get('chapter')} scored {best.get('score')} from {best.get('views')} views.",
                "action": "Use the hook structure, not the same image. Generate a fresh chapter-specific visual.",
                "source": best,
            }
        )
    else:
        moves.append({"priority": 2, "type": "experiment", "title": "Create measured variants", "reason": "No variant has enough measured views to be a reliable winner.", "action": "Run one 3-variant test on a back-catalog chapter and push only supported channels."})
    benchmark_recs = creator_benchmarks.get("recommendations") if isinstance(creator_benchmarks.get("recommendations"), list) else []
    if benchmark_recs:
        rec = benchmark_recs[0]
        moves.append({
            "priority": 2,
            "type": "creator_benchmark",
            "title": str(rec.get("title") or "Test creator benchmark pattern"),
            "reason": str(rec.get("reason") or "Public benchmark videos suggest this pattern is worth testing."),
            "action": str(rec.get("action") or "Turn the pattern into one fresh caption/image test without copying source content."),
            "source": rec.get("pattern") or {},
        })
    else:
        moves.append({
            "priority": 3,
            "type": "creator_benchmark",
            "title": "Collect creator benchmarks",
            "reason": "No public creator pattern data has been collected yet.",
            "action": "Run Collect Creator Benchmarks from the Growth panel to compare public YouTube patterns against Azure Inkblade results.",
        })
    weak_novels = [item for item in novel_strategy.get("novels", []) if numeric_metric(item.get("avgScore")) < 0.5 or not numeric_metric(item.get("experiments"))]
    if weak_novels:
        moves.append({"priority": 3, "type": "novel_balance", "title": "Fill weak-novel data gaps", "reason": "Some novels have low or missing measured performance.", "action": "Run the next variant cycle on these novels before repeating winners.", "novels": [item.get("abbr") for item in weak_novels[:4]]})
    if ready_youtube:
        moves.append({"priority": 4, "type": "youtube_conversion", "title": "Upload ready full YouTube videos", "reason": f"{len(ready_youtube)} full videos are created but not marked uploaded/scheduled.", "action": "Prepare YouTube uploads, add pinned comments/end screens, then mark status so tracking stays correct."})
    if resurfacing.get("backCatalog"):
        first = resurfacing["backCatalog"][0]
        moves.append({"priority": 5, "type": "resurface", "title": f"Resurface {first.get('novel')} Ch. {first.get('chapter')}", "reason": first.get("reason") or "Back-catalog candidate is outside cooldown.", "action": "Create a fresh hook and image without rebuilding the full campaign.", "candidate": first})
    image_risks = [item for item in image_scores.get("byNovel", []) if numeric_metric(item.get("rejectRate")) >= 0.45]
    if image_risks:
        moves.append({"priority": 6, "type": "image_quality", "title": "Tighten image prompts before more generation", "reason": "Recent Image Lab rejects are high for at least one novel.", "action": "Use Image Lab winners as references and avoid generic landscape/sunset prompts.", "novels": [item.get("abbr") for item in image_risks]})
    content_mix = [
        {"slot": "daily_short", "count": 4, "platforms": ["tiktok", "instagram_reels", "youtube_shorts"], "goal": "reach and follower growth", "rule": "Fresh chapter-specific image set, no recycled weekly image unless fallback is needed."},
        {"slot": "deep_tiktok", "count": 1, "platforms": ["tiktok"], "goal": "monetization and retention testing", "rule": "60-75 seconds, one chapter scene, strong moral question."},
        {"slot": "experiment_variants", "count": 3, "platforms": ["tiktok", "instagram", "x", "facebook"], "goal": "learn hook/image winners", "rule": "Do not send variants to YouTube long-form."},
        {"slot": "full_youtube", "count": min(4, len(ready_youtube)) if ready_youtube else 1, "platforms": ["youtube"], "goal": "watch hours and subscriber conversion", "rule": "Upload only completed videos, then pin comment and add end screens."},
    ]
    payload = {
        "generatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "primaryPlatform": primary,
        "moves": sorted(moves, key=lambda item: int(item.get("priority") or 99)),
        "contentMix": content_mix,
        "velocity": velocity,
        "imageScores": image_scores,
        "instagramBlueprint": {
            "positioning": instagram_blueprint.get("positioning", {}),
            "topPillars": (instagram_blueprint.get("contentPillars") or [])[:4],
            "today": (instagram_blueprint.get("thirtyDayCalendar") or [])[:1],
            "file": instagram_blueprint.get("file"),
        },
        "creatorBenchmarks": creator_benchmarks,
        "weeklyReport": weekly,
        "resurfacing": resurfacing,
        "readyYoutubeCount": len(ready_youtube),
        "file": str(GROWTH_OPTIMIZER_FILE),
        "note": "Local optimizer only. It uses saved metrics, Image Lab scores, and experiment results; it does not create or publish posts by itself.",
    }
    _phase2_save_blob("growthOptimizerPlan", GROWTH_OPTIMIZER_FILE, payload)
    return payload


def collect_growth_stats_with_playwright(open_missing: bool = False) -> dict[str, Any]:
    gathered = gather_experiment_metrics_with_playwright(True, open_missing)
    youtube_api = gather_youtube_api_metrics()
    if youtube_api.get("normalized"):
        existing_results = gathered.setdefault("results", [])
        existing_results.extend(youtube_api["normalized"])
        raw = _phase2_load_blob("metricsGatherResults", METRICS_GATHER_FILE)
        if not isinstance(raw, dict):
            raw = {}
        normalized = raw.get("normalized") if isinstance(raw.get("normalized"), list) else []
        normalized.extend(youtube_api["normalized"])
        raw["normalized"] = normalized
        raw["youtubeApi"] = youtube_api
        raw["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
        _phase2_save_blob("metricsGatherResults", METRICS_GATHER_FILE, raw)
    growth = apply_growth_stats_from_metrics(gathered.get("results") or [])
    optimizer = growth_optimizer_plan()
    platform_results = gathered.get("results") or []
    successful = [item for item in platform_results if item.get("metrics")]
    skipped = [item for item in platform_results if item.get("skipped") or not item.get("metrics")]
    return {
        **gathered,
        "message": f"Growth stats collection finished. Updated {len(growth['updatedPlatforms'])} platform(s); {len(skipped)} need review.",
        "growth": growth,
        "dashboard": monetization_dashboard(),
        "weeklyGrowthStats": weekly_growth_stats_status(),
        "growthOptimizer": optimizer,
        "successfulPlatforms": [item.get("platform") for item in successful],
        "reviewPlatforms": [item.get("platform") for item in skipped],
    }


