def load_comment_assistant() -> dict[str, Any]:
    data = _phase2_load_blob("commentAssistant", COMMENT_ASSISTANT_FILE)
    if not isinstance(data, dict):
        data = {"schemaVersion": 2, "comments": [], "lastGatheredAt": "", "lastError": ""}
    data["schemaVersion"] = max(2, int(data.get("schemaVersion") or 1))
    data.setdefault("comments", [])
    data.setdefault("lastGatheredAt", "")
    data.setdefault("lastError", "")
    return data


def save_comment_assistant(data: dict[str, Any]) -> None:
    data["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    _phase2_save_blob("commentAssistant", COMMENT_ASSISTANT_FILE, data)


def comment_novel(text: str) -> str:
    lowered = text.lower()
    names = {
        "EN": ["eternal nexus", "kael"],
        "HA": ["heavenly ascension", "liang"],
        "SF": ["soul forge", "soulforge", "jarek"],
        "HP": ["hundredfold", "hundredfold path"],
    }
    for abbr, needles in names.items():
        if any(needle in lowered for needle in needles):
            return abbr
    return ""


def clean_comment_text(raw: str) -> str:
    text = re.sub(r"[\u200b-\u200d\ufeff]", "", str(raw or ""))
    text = re.sub(r"\s+", " ", text).strip()
    remove = ["reply", "like", "view replies", "translate", "hide", "report", "more actions"]
    for token in remove:
        text = re.sub(rf"\b{re.escape(token)}\b", " ", text, flags=re.IGNORECASE)
    text = re.sub(r"\s+", " ", text).strip(" |")
    return text[:700]


def comment_is_solicitation(text: str) -> bool:
    lowered = str(text or "").lower()
    phrases = [
        "help your story stand out", "help you promote", "marketing expert", "promotion expert",
        "grow your audience", "reach more readers", "check your dm", "check your inbox", "paid promotion",
    ]
    return any(phrase in lowered for phrase in phrases)


def engagement_is_interface_noise(text: str) -> bool:
    normalized = re.sub(r"[\u200b-\u200d\ufeff]", "", str(text or ""))
    normalized = re.sub(r"\s+", " ", normalized).strip().lower()
    exact = {
        "moremoremore", "create messaging ad", "automations", "messaging insights",
        "message settings", "priority", "ad replies", "follow up", "assign this conversation",
        "move to spam", "delete conversation", "new message", "all messages", "primary",
        "done", "unread", "spam", "search", "settings", "inbox", "more items",
        "collapse contact details", "add details", "new customer", "add note",
        "sent an attachment",
    }
    if normalized in exact:
        return True
    if re.fullmatch(r"today'?s date\s*\(\d{1,2}/\d{1,2}\)", normalized):
        return True
    prefixes = ("mark as ", "move to ", "assign to ", "filter by ", "sort by ")
    if re.fullmatch(r"@?[\w.]{3,30}", normalized):
        return True
    if normalized.endswith(" expert") and len(normalized.split()) <= 3:
        return True
    return any(normalized.startswith(prefix) for prefix in prefixes)


def comment_priority(text: str) -> tuple[int, str]:
    lowered = text.lower()
    score = 1
    reasons = []
    if "?" in text:
        score += 4
        reasons.append("question")
    if any(word in lowered for word in ["theory", "think", "wonder", "what if", "prediction"]):
        score += 3
        reasons.append("reader theory")
    if any(word in lowered for word in ["love", "favorite", "amazing", "great", "hooked", "more"]):
        score += 2
        reasons.append("strong engagement")
    if any(word in lowered for word in ["confused", "error", "wrong", "issue", "problem", "doesn't", "does not"]):
        score += 4
        reasons.append("needs attention")
    if len(text) >= 90:
        score += 1
        reasons.append("detailed comment")
    return min(score, 10), ", ".join(reasons) or "reader engagement"


def engagement_item_type(result: dict[str, Any], candidate: dict[str, Any]) -> str:
    item_type = str(result.get("itemType") or "comment").strip().lower()
    if item_type in {"comment", "message"}:
        return item_type
    text = str(candidate.get("text") or "").lower()
    comment_markers = ["commented", "replied to", "mentioned you", "left a comment", "liked your reply"]
    return "comment" if any(marker in text for marker in comment_markers) else "message"


def draft_comment_reply(text: str, abbr: str = "", item_type: str = "comment", variation: int = 0) -> str:
    lowered = text.lower()
    novel = NOVEL_NAMES.get(abbr, "the story")
    opening = "Thanks for reaching out." if item_type == "message" else "Thanks for reading!"
    if any(phrase in lowered for phrase in ["where can i read", "where do i read", "start reading", "read this", "story link"]):
        story_url = royal_road_url_for_story(abbr) if abbr else ""
        if story_url:
            return f"{opening} You can start reading {novel} on Royal Road here: {story_url} Early-access chapters are also available on Patreon: {PATREON_URL}"
        return f"{opening} The current novels are available on Royal Road, with early-access chapters on Patreon: {PATREON_URL}"
    if any(word in lowered for word in ["patreon", "early access", "read ahead", "membership", "tier"]):
        return f"{opening} Early-access chapters and bonus updates are available on Patreon here: {PATREON_URL}"
    if any(word in lowered for word in ["youtube", "audiobook", "audio chapter", "listen"]):
        return f"{opening} Full chapter videos and Shorts are available on YouTube here: {YOUTUBE_SOCIAL_URL}"
    if any(phrase in lowered for phrase in ["when is", "when will", "upload schedule", "next chapter", "new chapter"]):
        return f"{opening} New chapters and release updates are posted regularly. The latest public chapter is on Royal Road, and Patreon receives early access first."
    if item_type == "message" and any(phrase in lowered for phrase in ["hello", "hi ", "hey", "hope you're", "hope you are", "doing awesome", "how are you"]):
        greeting_drafts = [
            "Hi, thanks for reaching out. What can I help you with?",
            "Hello, thanks for the message. What did you want to ask about?",
            "Hi, I appreciate you reaching out. Let me know what you need.",
        ]
        return greeting_drafts[int(content_hash(f"{text}|{variation}")[:8], 16) % len(greeting_drafts)]
    if any(word in lowered for word in ["theory", "what if", "prediction", "i think"]):
        theory_drafts = [
            "I love seeing theories like this. I will not confirm anything yet, but you noticed an important detail. Thanks for reading!",
            "That is a sharp theory. I cannot confirm it without spoilers, but you are paying attention to the right details.",
            "I really enjoy reading predictions like this. Keep that idea in mind as the next chapters unfold.",
        ]
        return theory_drafts[int(content_hash(f"{text}|{variation}")[:8], 16) % len(theory_drafts)]
    if "?" in text:
        question_drafts = [
            f"{opening} Great question. I am keeping the answer spoiler-free for now, but the upcoming chapters will reveal more.",
            f"{opening} I cannot answer that fully without spoiling what comes next, but the story will return to it soon.",
            f"{opening} That question touches one of the threads still unfolding. The next chapters should give you more to work with.",
        ]
        return question_drafts[int(content_hash(f"{text}|{variation}")[:8], 16) % len(question_drafts)]
    if any(word in lowered for word in ["confused", "error", "wrong", "issue", "problem"]):
        return "Thank you for pointing that out. I am checking it so the chapter and future updates stay consistent."
    if any(word in lowered for word in ["love", "favorite", "amazing", "great", "hooked"]):
        praise_drafts = [
            f"Thank you! I am glad this moment in {novel} landed for you. More is on the way.",
            f"I really appreciate that. It means a lot to know {novel} has you hooked.",
            f"Thank you for the support. I had a lot of fun building this part of {novel}.",
        ]
        return praise_drafts[int(content_hash(f"{text}|{variation}")[:8], 16) % len(praise_drafts)]
    if item_type == "message":
        message_drafts = [
            f"Thanks for reaching out and for your interest in {novel}. I appreciate the support!",
            f"Thank you for the message. I am glad you found {novel}, and I appreciate you taking the time to reach out.",
            f"I appreciate the message and your support for {novel}. Thanks for being here!",
        ]
        return message_drafts[int(content_hash(f"{text}|{variation}")[:8], 16) % len(message_drafts)]
    comment_drafts = [
        f"Thank you for reading {novel} and taking the time to comment. I really appreciate the support!",
        f"I appreciate you reading {novel} and sharing your reaction. Thanks for being part of the journey!",
        f"Thank you for following {novel}. Reader comments like this genuinely help keep the story moving.",
        f"I am glad you stopped by to read {novel}. Thank you for the support!",
    ]
    return comment_drafts[int(content_hash(f"{text}|{variation}")[:8], 16) % len(comment_drafts)]


def normalize_gathered_comments(raw: dict[str, Any]) -> list[dict[str, Any]]:
    items = []
    seen: set[str] = set()
    used_drafts: set[str] = set()
    ignored = {"notifications", "mentions", "comments", "inbox", "all", "unread", "filter"}
    for result in raw.get("results", []) if isinstance(raw.get("results"), list) else []:
        platform = str(result.get("platform") or "unknown")
        for candidate in result.get("candidates", []) if isinstance(result.get("candidates"), list) else []:
            text = clean_comment_text(str(candidate.get("text") or ""))
            if len(text) < 8 or text.lower() in ignored or text.lower().startswith(("no comments", "sign in", "log in")):
                continue
            if comment_is_solicitation(text):
                continue
            if engagement_is_interface_noise(text):
                continue
            author = clean_comment_text(str(candidate.get("author") or ""))[:100]
            item_type = engagement_item_type(result, candidate)
            comment_id = content_hash(f"{platform}|{item_type}|{author}|{text}")
            if comment_id in seen:
                continue
            seen.add(comment_id)
            abbr = comment_novel(text)
            priority, reason = comment_priority(text)
            variation = 0
            reply_draft = draft_comment_reply(text, abbr, item_type, variation)
            while reply_draft in used_drafts and variation < 12:
                variation += 1
                reply_draft = draft_comment_reply(text, abbr, item_type, variation)
            used_drafts.add(reply_draft)
            items.append(
                {
                    "commentId": comment_id,
                    "itemType": item_type,
                    "platform": platform,
                    "author": author,
                    "text": text,
                    "sourceUrl": str(result.get("url") or result.get("targetUrl") or ""),
                    "novel": NOVEL_NAMES.get(abbr, ""),
                    "abbr": abbr,
                    "priority": priority,
                    "priorityReason": reason,
                    "replyDraft": reply_draft,
                    "replyDraftVersion": 2,
                    "replyDraftRefreshCount": variation,
                    "status": "pending",
                    "gatheredAt": str(result.get("gatheredAt") or raw.get("gatheredAt") or time.strftime("%Y-%m-%d %H:%M:%S")),
                }
            )
    items.sort(key=lambda item: (-int(item.get("priority") or 0), str(item.get("platform") or "")))
    return items


def comment_assistant_status() -> dict[str, Any]:
    data = load_comment_assistant()
    changed = False
    comments = []
    for item in list(data.get("comments") or []):
        text = str(item.get("text") or "")
        if comment_is_solicitation(text) or engagement_is_interface_noise(text):
            if item.get("status") in {"pending", "prepared", None, ""}:
                item["status"] = "dismissed"
                item["dismissedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
                item["dismissReason"] = "Filtered solicitation or interface text."
                changed = True
            continue
        if not item.get("itemType"):
            source_url = str(item.get("sourceUrl") or "").lower()
            item["itemType"] = "message" if "/messages" in source_url or "inbox/all" in source_url else "comment"
            changed = True
        if item.get("status") == "pending" and int(item.get("replyDraftVersion") or 0) < 2:
            item["replyDraft"] = draft_comment_reply(text, str(item.get("abbr") or ""), str(item.get("itemType") or "comment"))
            item["replyDraftVersion"] = 2
            changed = True
        comments.append(item)
    if changed:
        save_comment_assistant(data)
    pending = [item for item in comments if item.get("status") in {"pending", "prepared"}]
    pending_messages = [item for item in pending if item.get("itemType") == "message"]
    pending_comments = [item for item in pending if item.get("itemType") != "message"]
    return {
        **data,
        "comments": sorted(comments, key=lambda item: (-int(item.get("priority") or 0), str(item.get("gatheredAt") or "")))[:200],
        "pendingCount": len(pending),
        "pendingMessageCount": len(pending_messages),
        "pendingCommentCount": len(pending_comments),
        "highPriorityCount": len([item for item in pending if int(item.get("priority") or 0) >= 6]),
        "autoEnabled": COMMENT_ASSISTANT_AUTO_ENABLED,
        "intervalHours": COMMENT_ASSISTANT_INTERVAL_HOURS,
        "file": str(COMMENT_ASSISTANT_FILE),
    }


def gather_comments_with_playwright(open_missing: bool = True) -> dict[str, Any]:
    if not COMMENT_ASSISTANT_LOCK.acquire(blocking=False):
        return {"ok": False, "busy": True, "error": "A comment refresh is already running."}
    try:
        chrome_ready, chrome_message = chrome_debug_available()
        if not chrome_ready:
            state = load_comment_assistant()
            state["lastAttemptAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
            state["lastError"] = chrome_message
            save_comment_assistant(state)
            return {"ok": False, "error": chrome_message, "chromeReady": False}
        if not playwright_available():
            state = load_comment_assistant()
            state["lastAttemptAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
            state["lastError"] = "The bundled Playwright helper is unavailable."
            save_comment_assistant(state)
            return {"ok": False, "error": "The bundled Playwright helper is unavailable.", "chromeReady": True}
        script = write_comment_gather_playwright_script(open_missing)
        run = subprocess.run(
            [str(bundled_node_executable()), str(script)],
            cwd=str(ROOT),
            env={**os.environ, "NODE_PATH": str(ROOT / "node_modules"), "PLAYWRIGHT_BROWSERS_PATH": str(ROOT / "ms-playwright")},
            capture_output=True,
            text=True,
            timeout=180,
            check=False,
        )
        raw = _phase2_load_blob("commentGatherResults", COMMENT_GATHER_RAW_FILE)
        if not isinstance(raw, dict):
            raw = {}
        gathered = normalize_gathered_comments(raw)
        data = load_comment_assistant()
        existing = {str(item.get("commentId") or ""): item for item in data.get("comments", [])}
        added = 0
        for item in gathered:
            previous = existing.get(item["commentId"])
            if previous:
                item["status"] = previous.get("status") or item["status"]
                if previous.get("status") in {"prepared", "replied"} or previous.get("replyDraftEdited"):
                    item["replyDraft"] = previous.get("replyDraft") or item["replyDraft"]
                    item["replyDraftVersion"] = previous.get("replyDraftVersion") or item["replyDraftVersion"]
                item["preparedAt"] = previous.get("preparedAt", "")
            else:
                added += 1
            existing[item["commentId"]] = {**(previous or {}), **item}
        data["comments"] = list(existing.values())[-500:]
        data["lastAttemptAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
        if run.returncode == 0 and not raw.get("error"):
            data["lastGatheredAt"] = data["lastAttemptAt"]
        data["lastError"] = str(raw.get("error") or (run.stderr.strip() if run.returncode else ""))
        save_comment_assistant(data)
        return {
            "ok": run.returncode == 0 and not raw.get("error"),
            "message": f"Inbox refresh finished. Added {added} new message/comment item(s).",
            "added": added,
            "gathered": len(gathered),
            "chromeMessage": chrome_message,
            "status": comment_assistant_status(),
            "error": raw.get("error") or (run.stderr.strip() if run.returncode else ""),
        }
    finally:
        COMMENT_ASSISTANT_LOCK.release()


def write_comment_reply_playwright_script(comment: dict[str, Any], reply: str) -> Path:
    platform = str(comment.get("platform") or "")
    item_type = str(comment.get("itemType") or "comment")
    snippet = clean_comment_text(str(comment.get("text") or ""))[:90]
    COMMENT_REPLY_SCRIPT_FILE.write_text(
        rf"""const fs = require('fs');
const {{ chromium }} = require('playwright');
const cdpUrl = {json.dumps(chrome_debug_url())};
const platform = {json.dumps(platform)};
const itemType = {json.dumps(item_type)};
const sourceUrl = {json.dumps(str(comment.get('sourceUrl') or ''))};
const snippet = {json.dumps(snippet)};
const reply = {json.dumps(reply)};
const outputPath = {json.dumps(str(COMMENT_REPLY_RESULT_FILE))};

function hostForPlatform(value) {{
  return {{ youtube: 'studio.youtube.com', tiktok: 'tiktok.com', meta: 'business.facebook.com', x: 'x.com', patreon: 'patreon.com', royalroad: 'royalroad.com' }}[value] || '';
}}

(async () => {{
  const browser = await chromium.connectOverCDP(cdpUrl);
  const context = browser.contexts()[0] || await browser.newContext();
  const host = hostForPlatform(platform);
  let page = context.pages().find(candidate => {{
    try {{ const h = new URL(candidate.url()).hostname.replace(/^www\./, ''); return h === host || h.endsWith('.' + host); }} catch (_) {{ return false; }}
  }});
  if (!page) {{
    page = await context.newPage();
    await page.goto(sourceUrl, {{ waitUntil: 'domcontentloaded', timeout: 30000 }}).catch(() => null);
  }}
  await page.bringToFront();
  await page.waitForLoadState('domcontentloaded', {{ timeout: 15000 }}).catch(() => null);
  await page.waitForTimeout(1200);
  const textHit = page.getByText(snippet, {{ exact: false }}).first();
  if (!(await textHit.count())) throw new Error(`The selected ${{itemType}} is not visible on the current page. Open its inbox page and retry.`);
  await textHit.scrollIntoViewIfNeeded().catch(() => null);
  const container = textHit.locator('xpath=ancestor-or-self::*[self::article or @role="article" or self::ytcp-comment-thread or contains(@data-e2e,"comment")][1]');
  const scope = (await container.count()) ? container : textHit.locator('xpath=..');
  const replyButton = scope.getByRole('button', {{ name: /reply/i }}).first();
  if (itemType === 'comment' && await replyButton.count()) await replyButton.click();
  else await textHit.click();
  await page.waitForTimeout(700);
  const editors = [
    page.locator('textarea[aria-label*="reply" i]:visible').last(),
    page.locator('textarea[aria-label*="message" i]:visible').last(),
    page.locator('[contenteditable="true"][aria-label*="reply" i]:visible').last(),
    page.locator('[contenteditable="true"][aria-label*="message" i]:visible').last(),
    page.locator('[contenteditable="true"]:visible').last(),
    page.locator('textarea:visible').last()
  ];
  let editor = null;
  for (const candidate of editors) {{ if (await candidate.count()) {{ editor = candidate; break; }} }}
  if (!editor) throw new Error(`A ${{itemType}} reply editor did not open. Open the conversation and retry.`);
  const tag = await editor.evaluate(node => node.tagName.toLowerCase());
  if (tag === 'textarea' || tag === 'input') await editor.fill(reply);
  else {{ await editor.click(); await page.keyboard.press('Control+A'); await page.keyboard.insertText(reply); }}
  fs.writeFileSync(outputPath, JSON.stringify({{ ok: true, platform, itemType, sourceUrl: page.url(), filled: true, submitted: false }}, null, 2));
  process.exit(0);
}})().catch(error => {{
  fs.writeFileSync(outputPath, JSON.stringify({{ ok: false, error: error.message, platform }}, null, 2));
  process.exit(1);
}});
""",
        encoding="utf-8",
    )
    return COMMENT_REPLY_SCRIPT_FILE


def prepare_comment_reply(comment_id: str, reply: str = "") -> dict[str, Any]:
    data = load_comment_assistant()
    comment = next((item for item in data.get("comments", []) if str(item.get("commentId") or "") == str(comment_id)), None)
    if not comment:
        raise RuntimeError("Comment was not found in the assistant queue.")
    reply = str(reply or comment.get("replyDraft") or "").strip()
    if not reply:
        raise RuntimeError("Reply text is empty.")
    chrome_ready, chrome_message = chrome_debug_available()
    if not chrome_ready:
        raise RuntimeError(chrome_message)
    script = write_comment_reply_playwright_script(comment, reply)
    run = subprocess.run(
        [str(bundled_node_executable()), str(script)],
        cwd=str(ROOT),
        env={**os.environ, "NODE_PATH": str(ROOT / "node_modules"), "PLAYWRIGHT_BROWSERS_PATH": str(ROOT / "ms-playwright")},
        capture_output=True,
        text=True,
        timeout=90,
        check=False,
    )
    result = read_json_safe(COMMENT_REPLY_RESULT_FILE)
    if not isinstance(result, dict):
        result = {"ok": False, "error": run.stderr.strip() or "The browser helper did not return a result."}
    generated_reply = draft_comment_reply(
        str(comment.get("text") or ""),
        str(comment.get("abbr") or ""),
        str(comment.get("itemType") or "comment"),
        int(comment.get("replyDraftRefreshCount") or 0),
    )
    comment["replyDraft"] = reply
    comment["replyDraftEdited"] = reply != generated_reply
    comment["replyDraftVersion"] = 2
    if result.get("ok"):
        comment["status"] = "prepared"
        comment["preparedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    else:
        comment["lastPrepareError"] = str(result.get("error") or "Reply preparation failed.")
    save_comment_assistant(data)
    return {**result, "comment": comment, "chromeMessage": chrome_message, "message": "Reply filled for review. It was not submitted." if result.get("ok") else str(result.get("error") or "Reply preparation failed.")}


def redraft_comment_reply(comment_id: str) -> dict[str, Any]:
    data = load_comment_assistant()
    comment = next((item for item in data.get("comments", []) if str(item.get("commentId") or "") == str(comment_id)), None)
    if not comment:
        raise RuntimeError("Message or comment was not found.")
    refresh_count = int(comment.get("replyDraftRefreshCount") or 0) + 1
    comment["replyDraftRefreshCount"] = refresh_count
    comment["replyDraft"] = draft_comment_reply(
        str(comment.get("text") or ""),
        str(comment.get("abbr") or ""),
        str(comment.get("itemType") or "comment"),
        refresh_count,
    )
    comment["replyDraftEdited"] = False
    comment["replyDraftVersion"] = 2
    comment["status"] = "pending"
    save_comment_assistant(data)
    return {"ok": True, "comment": comment, "replyDraft": comment["replyDraft"], "status": comment_assistant_status()}


def update_comment_status(comment_id: str, status: str) -> dict[str, Any]:
    allowed = {"pending", "prepared", "replied", "dismissed"}
    status = str(status or "").strip().lower()
    if status not in allowed:
        raise RuntimeError("Choose pending, prepared, replied, or dismissed.")
    data = load_comment_assistant()
    comment = next((item for item in data.get("comments", []) if str(item.get("commentId") or "") == str(comment_id)), None)
    if not comment:
        raise RuntimeError("Comment was not found.")
    comment["status"] = status
    comment[f"{status}At"] = time.strftime("%Y-%m-%d %H:%M:%S")
    save_comment_assistant(data)
    return {"ok": True, "comment": comment, "status": comment_assistant_status()}


def pending_deep_tiktok_items(
    fast: bool = True,
    ledger: dict[str, Any] | None = None,
    active_paths: dict[str, int | None] | None = None,
) -> list[dict[str, Any]]:
    ledger = ledger if isinstance(ledger, dict) else load_chapter_ledger()
    items: list[dict[str, Any]] = []
    for entry in ledger.get("chapters", {}).values() if isinstance(ledger.get("chapters"), dict) else []:
        if (
            not isinstance(entry, dict)
            or not entry.get("deepTikTokBuilt")
            or entry.get("deepTikTokQueued")
            or entry.get("deepTikTokPosted")
        ):
            continue
        if not approval_item_matches_active_chapter(entry, active_paths):
            continue
        folder = Path(str(entry.get("deepTikTokFolder") or ""))
        if not folder.exists():
            continue
        metadata = read_metadata(folder) if fast else repair_deep_tiktok_metadata(folder)
        if deep_tiktok_pack_completed(folder, metadata, entry):
            continue
        gate = folder_quality_gate(str(folder), "tiktok")
        items.append(
            {
                "abbr": metadata.get("abbr") or entry.get("abbr"),
                "novel": metadata.get("novel") or entry.get("novel"),
                "chapter": metadata.get("chapter") or entry.get("chapter"),
                "title": metadata.get("title") or entry.get("title"),
                "folder": str(folder),
                "duration": media_duration_seconds(folder / "tiktok-video.mp4"),
                "qualityGate": gate,
                "createdAt": metadata.get("createdAt") or entry.get("deepTikTokBuiltAt"),
            }
        )
    items.sort(key=lambda item: str(item.get("createdAt") or ""), reverse=True)
    return items


def deep_tiktok_pack_completed(folder: Path, metadata: dict[str, Any] | None = None, ledger_entry: dict[str, Any] | None = None) -> bool:
    metadata = metadata if isinstance(metadata, dict) else read_metadata(folder) if (folder / "metadata.json").exists() else {}
    ledger_entry = ledger_entry if isinstance(ledger_entry, dict) else {}
    if ledger_entry.get("deepTikTokQueued") or ledger_entry.get("deepTikTokPosted"):
        return True
    if metadata.get("manual_tiktok_posted") or metadata.get("manual_buffer_queued"):
        return True
    if metadata.get("deepTikTokQueued") or metadata.get("deepTikTokPosted"):
        return True
    if (folder / "manual-tiktok-posted.txt").exists() or (folder / "manual-buffer-queued.txt").exists():
        return True
    buffer_result = metadata.get("buffer_result") or metadata.get("buffer") or metadata.get("deepTikTokBufferResult")
    if isinstance(buffer_result, dict):
        posts = buffer_result.get("posts") if isinstance(buffer_result.get("posts"), list) else []
        if any(post and not post.get("skipped") for post in posts):
            return True
    return False


def existing_deep_tiktok_packs(include_completed: bool = False, limit: int = 8, fast: bool = True) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    seen: set[str] = set()
    ledger = load_chapter_ledger()
    ledger_by_folder = {}
    for entry in ledger.get("chapters", {}).values() if isinstance(ledger.get("chapters"), dict) else []:
        folder_value = str(entry.get("deepTikTokFolder") or "")
        if folder_value:
            ledger_by_folder[str(Path(folder_value).resolve()).lower()] = entry
    for folder in sorted(TIKTOK_OUTPUT_DIR.glob("*-deep"), key=lambda item: item.stat().st_mtime if item.exists() else 0, reverse=True):
        if not folder.is_dir():
            continue
        metadata = read_metadata(folder) if fast else repair_deep_tiktok_metadata(folder)
        if fast:
            abbr, chapter = deep_tiktok_folder_selection(folder, metadata)
            if abbr:
                metadata.setdefault("abbr", abbr)
                metadata.setdefault("novel", NOVEL_NAMES.get(abbr, abbr))
            if chapter:
                metadata.setdefault("chapter", str(chapter))
                metadata.setdefault("title", "Prologue" if str(chapter) == "0" else f"Chapter {chapter}")
        gate = {} if fast else folder_quality_gate(str(folder), "tiktok")
        key = str(folder.resolve()).lower()
        entry = ledger_by_folder.get(key, {})
        completed = deep_tiktok_pack_completed(folder, metadata, entry)
        if completed and not include_completed:
            continue
        video = folder / "tiktok-video.mp4"
        seen.add(key)
        duration = numeric_metric(metadata.get("duration")) if fast else (media_duration_seconds(video) if video.exists() else numeric_metric(metadata.get("duration")))
        quality_gate = gate
        if fast:
            quality_gate = {
                "ok": bool(video.exists()),
                "errors": [],
                "imageQuality": {
                    "score": metadata.get("imageReviewScore")
                    or metadata.get("imageQualityScore")
                    or metadata.get("qualityScore")
                    or "",
                },
            }
        images = [str(item) for item in metadata.get("images", []) or [] if str(item or "").strip()]
        items.append(
            {
                "abbr": metadata.get("abbr"),
                "novel": metadata.get("novel"),
                "chapter": metadata.get("chapter"),
                "title": metadata.get("title"),
                "folder": str(folder),
                "video": str(video) if video.exists() else str(metadata.get("video") or ""),
                "duration": duration,
                "quality_gate": quality_gate,
                "ready": bool((quality_gate.get("ok") if quality_gate else True) and video.exists()),
                "completed": completed,
                "updatedAt": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(folder.stat().st_mtime)),
                "images": images[:1],
                "caption": str(metadata.get("caption") or metadata.get("description") or "")[:320],
            }
        )
        if limit and len(items) >= limit:
            break
    for item in pending_deep_tiktok_items():
        key = str(Path(str(item.get("folder") or "")).resolve()).lower()
        if key in seen:
            continue
        folder = Path(str(item.get("folder") or ""))
        metadata = read_metadata(folder) if fast and folder.exists() else repair_deep_tiktok_metadata(folder) if folder.exists() else {}
        if fast and folder.exists():
            abbr, chapter = deep_tiktok_folder_selection(folder, metadata)
            if abbr:
                metadata.setdefault("abbr", abbr)
                metadata.setdefault("novel", NOVEL_NAMES.get(abbr, abbr))
            if chapter:
                metadata.setdefault("chapter", str(chapter))
                metadata.setdefault("title", "Prologue" if str(chapter) == "0" else f"Chapter {chapter}")
        gate = item.get("qualityGate") if isinstance(item.get("qualityGate"), dict) else {}
        if deep_tiktok_pack_completed(folder, metadata) and not include_completed:
            continue
        items.append({**metadata, **item, "quality_gate": gate, "ready": bool(gate.get("ok")), "completed": False})
        if limit and len(items) >= limit:
            break
    return items


def deep_tiktok_pack_from_folder(folder: str) -> dict[str, Any]:
    target = Path(folder).resolve()
    if not str(target).startswith(str(TIKTOK_OUTPUT_DIR.resolve())) or not target.name.lower().endswith("-deep"):
        raise RuntimeError("Deep TikTok folder is not valid.")
    if not target.exists():
        raise RuntimeError("Deep TikTok folder was not found.")
    metadata = repair_deep_tiktok_metadata(target)
    gate = folder_quality_gate(str(target), "tiktok")
    candidate_images = [str(path) for path in sorted(target.glob("deep-scene-*.png"), key=lambda path: [int(value) if value.isdigit() else value for value in re.split(r"(\d+)", path.name)])]
    promo_card = target / "novel-promo-card.png"
    if promo_card.exists():
        candidate_images.append(str(promo_card))
    metadata["quality_gate"] = gate
    metadata["candidate_images"] = candidate_images
    metadata["included_images"] = list(metadata.get("images") or [])
    metadata["video"] = str(target / "tiktok-video.mp4") if (target / "tiktok-video.mp4").exists() else str(metadata.get("video") or "")
    metadata["duration"] = media_duration_seconds(target / "tiktok-video.mp4") if (target / "tiktok-video.mp4").exists() else numeric_metric(metadata.get("duration"))
    metadata["folder"] = str(target)
    metadata["ready"] = bool(gate.get("ok") and metadata.get("video"))
    return metadata


def rebuild_deep_tiktok_video_from_metadata(target: Path, metadata: dict[str, Any]) -> dict[str, Any]:
    images = [str(Path(str(item)).resolve()) for item in metadata.get("images", []) or [] if Path(str(item)).exists()]
    if not images:
        raise RuntimeError("No approved deep TikTok images are selected for the video.")
    overlays = list(metadata.get("video_overlays") or [])
    if len(overlays) < len(images):
        overlays.extend([str(metadata.get("title") or "Deep chapter scene")] * (len(images) - len(overlays)))
    sound_value = str(metadata.get("sound") or "").strip()
    sound = Path(sound_value).resolve() if sound_value else None
    if not sound or not sound.is_file() or sound.suffix.lower() not in AUDIO_EXTENSIONS:
        sound = next((path for path in target.iterdir() if path.is_file() and path.suffix.lower() in AUDIO_EXTENSIONS), None)
    if not sound:
        sound_source = choose_rotating_weekly_promo_audio()
        if sound_source and sound_source.is_file() and sound_source.suffix.lower() in AUDIO_EXTENSIONS:
            sound = target / sound_source.name
            if sound.resolve() != sound_source.resolve():
                shutil.copy2(sound_source, sound)
    if not sound or not sound.is_file():
        raise RuntimeError("No audio file is available for this deep TikTok.")
    metadata["sound"] = str(sound)
    draw_overlays = not (
        bool(metadata.get("browser_images_have_text"))
        or str(metadata.get("overlay_mode") or "").strip().lower() == "image_embedded_text"
    )
    narration_target = generate_deep_tiktok_narration(
        target, story_key(str(metadata.get("abbr") or "")),
        tiktok_narration_text(metadata, overlays),
    ) if metadata.get("caption") else None
    write_deep_tiktok_video_helper(
        target, images, sound, overlays[: len(images)], draw_overlays=draw_overlays,
        narration=narration_target,
    )
    build = run_generated_video_builder(target, "make_tiktok_video.py", "tiktok-video.mp4", timeout=900)
    metadata["video_build"] = build
    metadata["video"] = str(target / "tiktok-video.mp4") if (target / "tiktok-video.mp4").exists() else ""
    metadata["duration"] = media_duration_seconds(target / "tiktok-video.mp4") if (target / "tiktok-video.mp4").exists() else 0.0
    metadata["videoRebuiltAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    metadata["videoNeedsRebuild"] = False
    (target / "metadata.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    if not build.get("created"):
        raise RuntimeError(str(build.get("message") or "Deep TikTok MP4 rebuild finished, but no valid video was created."))
    return build


def deep_tiktok_browser_prompt_sheet(folder: str) -> dict[str, Any]:
    target = Path(folder).resolve()
    if not str(target).startswith(str(TIKTOK_OUTPUT_DIR.resolve())) or not target.name.lower().endswith("-deep"):
        raise RuntimeError("Deep TikTok folder is not valid.")
    metadata = repair_deep_tiktok_metadata(target)
    abbr = story_key(str(metadata.get("abbr") or ""))
    novel = str(metadata.get("novel") or NOVEL_NAMES.get(abbr, "Azure Inkblade"))
    title = str(metadata.get("title") or "")
    overlays = list(metadata.get("video_overlays") or [])
    existing_prompts = list(metadata.get("image_prompts") or [])
    style_rules = (
        "Vertical 9:16 cinematic anime web novel panel, premium mobile-first composition, "
        "dark atmospheric lighting, sharp foreground character emotion, readable scene action, "
        "blue holographic system UI where useful, no watermark, no logo, no extra random typography. "
        "If adding text boxes, use short exact phrases only and keep them clean, large, and legible."
    )
    prompts: list[dict[str, Any]] = []
    scene_count = max(8, min(10, len(overlays) or len(existing_prompts) or 8))
    for index in range(scene_count):
        overlay = overlays[index] if index < len(overlays) else ""
        base = existing_prompts[index] if index < len(existing_prompts) else f"Scene from {novel} {title}: {overlay}"
        prompt = (
            f"{style_rules}\n\n"
            f"Novel: {novel}\n"
            f"Video: 60-75 second TikTok chapter dive\n"
            f"Scene {index + 1}: {overlay or base}\n"
            f"Chapter context: {base}\n\n"
            "Make it feel like a high-performing fantasy/LitRPG TikTok still: dramatic, specific, emotional, "
            "and not a generic landscape. Keep the character and setting consistent across the set."
        )
        prompts.append({"scene": index + 1, "overlay": overlay, "prompt": prompt})
    sheet = [
        f"Deep TikTok browser image prompts",
        f"Pack: {target}",
        f"Novel: {novel}",
        f"Title: {title}",
        "",
        "Use these in ChatGPT or Gemini image generation. Save the images, then paste the image folder or file paths into Import Browser Images in the app.",
        "",
    ]
    for item in prompts:
        sheet.append(f"SCENE {item['scene']}")
        if item["overlay"]:
            sheet.append(f"Target text/hook: {item['overlay']}")
        sheet.append(item["prompt"])
        sheet.append("")
    output = target / "browser-image-prompts.txt"
    output.write_text("\n".join(sheet).strip() + "\n", encoding="utf-8")
    metadata["browser_image_prompt_file"] = str(output)
    metadata["browser_image_prompts"] = prompts
    metadata["browserPromptUpdatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    (target / "metadata.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    return {"ok": True, "folder": str(target), "promptFile": str(output), "prompts": prompts, "message": f"Created {len(prompts)} browser image prompt(s)."}


def import_deep_tiktok_browser_images(
    folder: str,
    image_input: str,
    *,
    embedded_text: bool = True,
    max_images: int = 9,
) -> dict[str, Any]:
    target = Path(folder).resolve()
    if not str(target).startswith(str(TIKTOK_OUTPUT_DIR.resolve())) or not target.name.lower().endswith("-deep"):
        raise RuntimeError("Deep TikTok folder is not valid.")
    metadata = repair_deep_tiktok_metadata(target)
    abbr = story_key(str(metadata.get("abbr") or ""))
    title = str(metadata.get("title") or "")
    source_images = discover_manual_video_images(image_input)
    if not source_images:
        raise RuntimeError("No browser-created images were found.")
    scored = sorted(
        [(float(manual_video_image_score(path, title, abbr).get("score") or 0), path) for path in source_images],
        key=lambda item: item[0],
        reverse=True,
    )
    selected = scored[: max(1, min(12, int(max_images or 9)))]
    bank_dir = MANUAL_VIDEO_IMAGE_BANK_DIR / "deep-tiktok" / (abbr or "general")
    bank_dir.mkdir(parents=True, exist_ok=True)
    imported: list[dict[str, Any]] = []
    candidate_images = [str(Path(str(item)).resolve()) for item in metadata.get("candidate_images", []) or [] if Path(str(item)).exists()]
    candidate_sources = list(metadata.get("candidate_image_sources") or [])
    prompts = list(metadata.get("image_prompts") or [])
    for index, (score, source) in enumerate(selected, start=1):
        digest = content_hash(str(source.resolve()) + str(source.stat().st_mtime) + str(source.stat().st_size))[:10]
        bank_name = f"{abbr.lower() if abbr else 'deep'}-{int(score):03d}-browser-{digest}-{slugify(source.stem)[:38]}{source.suffix.lower()}"
        banked = bank_dir / bank_name
        if not banked.exists():
            shutil.copy2(source, banked)
        pack_image = target / f"browser-scene-{index:02d}{source.suffix.lower()}"
        shutil.copy2(banked, pack_image)
        item = {
            "index": index,
            "score": round(score, 2),
            "source": str(source),
            "banked": str(banked),
            "packImage": str(pack_image),
        }
        imported.append(item)
        candidate_images.append(str(pack_image))
        candidate_sources.append(f"browser_import:score:{round(score, 2)}")
        if len(prompts) < len(candidate_images):
            prompts.append(f"Browser-created approved image for {metadata.get('novel', '')} {metadata.get('title', '')}.")
    promo = [path for path in metadata.get("images", []) or [] if Path(str(path)).name.lower() == "novel-promo-card.png" and Path(str(path)).exists()]
    selected_pack_images = [item["packImage"] for item in imported]
    if promo:
        selected_pack_images.append(str(Path(str(promo[0])).resolve()))
    metadata["candidate_images"] = candidate_images
    metadata["candidate_image_sources"] = candidate_sources
    metadata["image_prompts"] = prompts
    metadata["images"] = selected_pack_images
    metadata["approved_images"] = selected_pack_images[:]
    metadata["browser_imported_images"] = imported
    metadata["browser_images_have_text"] = bool(embedded_text)
    metadata["overlay_mode"] = "image_embedded_text" if embedded_text else "app_overlay"
    metadata["approvalManual"] = True
    metadata["videoNeedsRebuild"] = True
    metadata["browserImagesImportedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    for item in imported:
        record_image_feedback(
            image_path=Path(item["packImage"]),
            action="approve",
            metadata=metadata,
            note="Imported from ChatGPT/Gemini browser generation for high-value deep TikTok imagery.",
        )
    (target / "metadata.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    return deep_tiktok_pack_from_folder(str(target))


def record_image_feedback(
    *,
    image_path: Path,
    action: str,
    metadata: dict[str, Any],
    note: str = "",
) -> dict[str, Any]:
    data = _phase2_load_blob("imageFeedback", IMAGE_FEEDBACK_FILE)
    if not isinstance(data, dict):
        data = {"schemaVersion": 1, "records": []}
    records = data.setdefault("records", [])
    image_text = str(image_path.resolve())
    candidate_images = [str(Path(str(item)).resolve()) for item in metadata.get("candidate_images", []) or [] if str(item or "").strip()]
    try:
        index = next(i for i, value in enumerate(candidate_images) if value.lower() == image_text.lower())
    except StopIteration:
        index = -1
    prompts = metadata.get("image_prompts") if isinstance(metadata.get("image_prompts"), list) else []
    sources = metadata.get("candidate_image_sources") if isinstance(metadata.get("candidate_image_sources"), list) else metadata.get("image_sources") if isinstance(metadata.get("image_sources"), list) else []
    provider_trace = read_image_provider_trace(image_path)
    fingerprint = ""
    try:
        fingerprint = image_file_fingerprint(image_path) if image_path.exists() else ""
    except Exception:
        fingerprint = ""
    user_score = numeric_metric(metadata.get("qualityScore") or metadata.get("userScore"), -1)
    if user_score < 0 and note:
        score_match = re.search(r"\b(\d{1,3})(?:\s*/\s*100|\s*points?)\b", note, re.IGNORECASE)
        if score_match:
            user_score = numeric_metric(score_match.group(1), -1)
    user_score = max(0, min(100, user_score)) if user_score >= 0 else None
    training_eligible = bool(action == "approve" and user_score is not None and user_score >= IMAGE_TRAINING_SCORE)
    passable = bool(action == "approve" and (user_score is None or user_score >= IMAGE_PASSABLE_SCORE))
    record = {
        "image": image_text,
        "filename": image_path.name,
        "fingerprint": fingerprint,
        "action": action,
        "score": "trainable" if training_eligible else "passable" if passable else "needs_improvement" if action == "approve" else "reject",
        "qualityScore": user_score,
        "passableThreshold": IMAGE_PASSABLE_SCORE,
        "trainingThreshold": IMAGE_TRAINING_SCORE,
        "trainingEligible": training_eligible,
        "note": note or ("Approved for deep TikTok video." if action == "approve" else "Unapproved as a bad/weak deep TikTok image."),
        "abbr": story_key(str(metadata.get("abbr") or "")),
        "novel": str(metadata.get("novel") or ""),
        "chapter": str(metadata.get("chapter") or ""),
        "title": str(metadata.get("title") or ""),
        "source": sources[index] if 0 <= index < len(sources) else "",
        "provider": provider_trace.get("selectedSource") or (sources[index] if 0 <= index < len(sources) else ""),
        "providerTrace": provider_trace,
        "prompt": prompts[index] if 0 <= index < len(prompts) else "",
        "folder": str(metadata.get("folder") or image_path.parent),
        "recordedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    records.append(record)
    data["records"] = records[-1000:]
    data["updatedAt"] = record["recordedAt"]
    _phase2_save_blob("imageFeedback", IMAGE_FEEDBACK_FILE, data)
    return record


def retire_rejected_image_from_bank(image_path: Path, metadata: dict[str, Any]) -> list[dict[str, Any]]:
    retired: list[dict[str, Any]] = []
    try:
        fingerprint = image_file_fingerprint(image_path) if image_path.exists() else ""
    except Exception:
        fingerprint = ""
    source_values = [str(metadata.get("image_source") or "")]
    source_values.extend(str(item) for item in metadata.get("image_sources", []) or [])
    source_values.extend(str(item) for item in metadata.get("candidate_image_sources", []) or [])
    candidates: list[Path] = []
    for value in source_values:
        for match in re.findall(r"(?:bank|banked|source):([^;]+)", value, re.IGNORECASE):
            candidate = Path(match.strip().strip('"').strip("'"))
            if candidate.exists():
                candidates.append(candidate.resolve())
    if fingerprint:
        for banked in image_bank_images(story_key(str(metadata.get("abbr") or ""))):
            try:
                if banked.exists() and image_file_fingerprint(banked) == fingerprint:
                    candidates.append(banked.resolve())
            except Exception:
                continue
    bank_roots = [root.resolve() for root in [GENERATED_PROMO_IMAGES_DIR, PROMO_IMAGES_DIR, MANUAL_VIDEO_IMAGE_BANK_DIR] if root.exists()]
    reject_root = GENERATED_PROMO_IMAGES_DIR / "Rejected"
    reject_root.mkdir(parents=True, exist_ok=True)
    seen: set[str] = set()
    for candidate in candidates:
        key = str(candidate).lower()
        if key in seen or not candidate.exists() or not candidate.is_file():
            continue
        seen.add(key)
        try:
            if bank_roots and not path_is_within(candidate, bank_roots):
                continue
        except Exception:
            continue
        target = reject_root / f"{time.strftime('%Y%m%d-%H%M%S')}-{content_hash(str(candidate))[:8]}-{candidate.name}"
        try:
            shutil.move(str(candidate), str(target))
            retired.append({"source": str(candidate), "retiredTo": str(target), "ok": True})
        except OSError as exc:
            retired.append({"source": str(candidate), "ok": False, "error": str(exc)})
    return retired


def set_deep_tiktok_image_approval(folder: str, image: str, approved: bool = True) -> dict[str, Any]:
    target = Path(folder).resolve()
    if not str(target).startswith(str(TIKTOK_OUTPUT_DIR.resolve())) or not target.name.lower().endswith("-deep"):
        raise RuntimeError("Deep TikTok folder is not valid.")
    image_path = Path(image)
    if not image_path.is_absolute():
        image_path = target / image_path
    image_path = image_path.resolve()
    if not str(image_path).startswith(str(target)) or not image_path.exists():
        raise RuntimeError("Deep TikTok image is not valid.")
    metadata = repair_deep_tiktok_metadata(target)
    def normalized_existing_paths(values: Any) -> list[str]:
        paths: list[str] = []
        seen: set[str] = set()
        for item in values or []:
            if not str(item or "").strip():
                continue
            path = Path(str(item)).resolve()
            if not path.exists():
                continue
            key = str(path).lower()
            if key in seen:
                continue
            seen.add(key)
            paths.append(str(path))
        return paths

    approved_images = normalized_existing_paths(metadata.get("approved_images", []))
    selected_images = normalized_existing_paths(metadata.get("images", []))
    rejected_images = normalized_existing_paths(metadata.get("rejected_images", []))
    approved_keys = {str(Path(item).resolve()).lower() for item in approved_images}
    selected_keys = {str(Path(item).resolve()).lower() for item in selected_images}
    rejected_keys = {str(Path(item).resolve()).lower() for item in rejected_images}
    image_text = str(image_path)
    image_key = str(image_path).lower()
    if approved:
        rejected_images = [item for item in rejected_images if str(Path(item).resolve()).lower() != image_key]
        rejected_keys.discard(image_key)
        if image_key not in approved_keys:
            approved_images.append(image_text)
            approved_keys.add(image_key)
        if image_key not in selected_keys:
            promo = [item for item in selected_images if Path(item).name.lower() == "novel-promo-card.png"]
            selected_images = [item for item in selected_images if Path(item).name.lower() != "novel-promo-card.png"]
            selected_images.append(image_text)
            selected_images.extend(promo)
    else:
        approved_images = [item for item in approved_images if str(Path(item).resolve()).lower() != image_key]
        if image_path.name.lower() != "novel-promo-card.png":
            selected_images = [item for item in selected_images if str(Path(item).resolve()).lower() != image_key]
        if image_key not in rejected_keys:
            rejected_images.append(image_text)
    metadata["approved_images"] = approved_images
    metadata["images"] = selected_images
    metadata["rejected_images"] = rejected_images
    metadata["approvalManual"] = True
    metadata["lastApprovalAction"] = {
        "image": image_text,
        "approved": bool(approved),
        "updatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    metadata["lastImageFeedback"] = record_image_feedback(
        image_path=image_path,
        action="approve" if approved else "unapprove",
        metadata=metadata,
    )
    if not approved:
        deleted_images = metadata.get("deleted_images") if isinstance(metadata.get("deleted_images"), list) else []
        deleted_record = {
            "image": image_text,
            "filename": image_path.name,
            "deletedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
            "reason": "unapproved_bad_image",
            "feedback": metadata["lastImageFeedback"],
        }
        deleted_record["retiredBankImages"] = retire_rejected_image_from_bank(image_path, metadata)
        if image_path.exists() and image_path.is_file() and image_path.suffix.lower() in IMAGE_EXTENSIONS:
            try:
                image_path.unlink()
                deleted_record["deleted"] = True
            except OSError as exc:
                deleted_record["deleted"] = False
                deleted_record["error"] = str(exc)
        else:
            deleted_record["deleted"] = False
            deleted_record["error"] = "Image file was already missing."
        deleted_images.append(deleted_record)
        metadata["deleted_images"] = deleted_images[-250:]
        old_candidates = list(metadata.get("candidate_images", []) or [])
        old_sources = list(metadata.get("candidate_image_sources") or []) if isinstance(metadata.get("candidate_image_sources"), list) else []
        kept_candidates: list[str] = []
        kept_sources: list[str] = []
        for index, path in enumerate(old_candidates):
            if str(Path(str(path)).resolve()).lower() == image_key:
                continue
            kept_candidates.append(path)
            kept_sources.append(old_sources[index] if index < len(old_sources) else "")
        metadata["candidate_images"] = kept_candidates
        metadata["rejected_images"] = [
            path for path in metadata.get("rejected_images", []) or []
            if str(Path(str(path)).resolve()).lower() != image_key
        ]
        metadata["candidate_image_sources"] = kept_sources
    metadata["imageApprovalUpdatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    metadata["videoNeedsRebuild"] = True
    (target / "metadata.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    return deep_tiktok_pack_from_folder(str(target))


def set_pack_image_approval(folder: str, image: str, approved: bool = True) -> dict[str, Any]:
    target = resolve_approved_daily_upload_folder(folder)
    metadata = read_metadata(target)
    if str(target).startswith(str(TIKTOK_OUTPUT_DIR.resolve())) and (
        str(metadata.get("kind") or "") == "deep_tiktok" or target.name.lower().endswith("-deep")
    ):
        return set_deep_tiktok_image_approval(str(target), image, approved)
    image_path = Path(image)
    if not image_path.is_absolute():
        image_path = target / image_path
    image_path = image_path.resolve()
    if not path_is_within(image_path, [target.resolve()]) or not image_path.exists():
        raise RuntimeError("Pack image is not valid.")

    def normalized_existing_paths(values: Any) -> list[str]:
        paths: list[str] = []
        seen: set[str] = set()
        for item in values or []:
            if not str(item or "").strip():
                continue
            path = Path(str(item)).resolve()
            if not path.exists():
                continue
            key = str(path).lower()
            if key in seen:
                continue
            seen.add(key)
            paths.append(str(path))
        return paths

    approved_images = normalized_existing_paths(metadata.get("approved_images", []))
    rejected_images = normalized_existing_paths(metadata.get("rejected_images", []))
    approved_keys = {str(Path(item).resolve()).lower() for item in approved_images}
    rejected_keys = {str(Path(item).resolve()).lower() for item in rejected_images}
    image_text = str(image_path)
    image_key = str(image_path).lower()
    if approved:
        rejected_images = [item for item in rejected_images if str(Path(item).resolve()).lower() != image_key]
        rejected_keys.discard(image_key)
        if image_key not in approved_keys:
            approved_images.append(image_text)
    else:
        approved_images = [item for item in approved_images if str(Path(item).resolve()).lower() != image_key]
        if image_key not in rejected_keys:
            rejected_images.append(image_text)
        selected_images = [
            str(Path(str(item)).resolve())
            for item in metadata.get("images", []) or []
            if str(item or "").strip() and Path(str(item)).exists() and str(Path(str(item)).resolve()).lower() != image_key
        ]
        candidate_images = [
            str(Path(str(item)).resolve())
            for item in metadata.get("candidate_images", []) or []
            if str(item or "").strip() and Path(str(item)).exists() and str(Path(str(item)).resolve()).lower() != image_key
        ]
        deleted_images = metadata.get("deleted_images") if isinstance(metadata.get("deleted_images"), list) else []
        deleted_record = {
            "image": image_text,
            "filename": image_path.name,
            "deletedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
            "reason": "rejected_bad_image",
        }
        deleted_record["retiredBankImages"] = retire_rejected_image_from_bank(image_path, metadata)
        if image_path.exists() and image_path.is_file() and image_path.suffix.lower() in IMAGE_EXTENSIONS:
            try:
                image_path.unlink()
                deleted_record["deleted"] = True
            except OSError as exc:
                deleted_record["deleted"] = False
                deleted_record["error"] = str(exc)
        else:
            deleted_record["deleted"] = False
            deleted_record["error"] = "Image file was already missing."
        deleted_images.append(deleted_record)
        metadata["images"] = selected_images
        metadata["candidate_images"] = candidate_images
        metadata["deleted_images"] = deleted_images[-250:]
    metadata["approved_images"] = approved_images
    metadata["rejected_images"] = [
        path for path in rejected_images
        if str(Path(str(path)).resolve()).lower() != image_key or Path(str(path)).exists()
    ]
    metadata["approvalManual"] = True
    metadata["imageReviewApprovedAt"] = time.strftime("%Y-%m-%d %H:%M:%S") if approved else metadata.get("imageReviewApprovedAt", "")
    metadata["lastApprovalAction"] = {
        "image": image_text,
        "approved": bool(approved),
        "updatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    metadata["lastImageFeedback"] = record_image_feedback(
        image_path=image_path,
        action="approve" if approved else "unapprove",
        metadata=metadata,
        note="Pack image approved for posting." if approved else "Pack image rejected during review.",
    )
    if str(target).startswith(str(TIKTOK_OUTPUT_DIR.resolve())):
        metadata["videoNeedsRebuild"] = True
        metadata["packStatusOverride"] = "needs_video_build" if not approved else ""
    else:
        metadata["packStatusOverride"] = "ready_to_queue" if approved and str(target).startswith(str(SOCIAL_OUTPUT_DIR.resolve())) else metadata.get("packStatusOverride", "")
    metadata["imageApprovalUpdatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    metadata.pop("github_media_publish", None)
    metadata.pop("public_media_urls", None)
    metadata.pop("public_image_url", None)
    write_json_atomic(target / "metadata.json", metadata)
    return pack_preview(str(target))


def push_pending_deep_tiktoks_to_buffer(limit: int = 10, mode: str = "addToQueue") -> dict[str, Any]:
    channels = [channel["id"] for channel in configured_buffer_channels() if channel.get("id") and channel.get("service") == "tiktok"]
    if not channels:
        raise RuntimeError("No TikTok Buffer channel is configured.")
    pushed: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    for item in pending_deep_tiktok_items()[: max(1, int(limit or 10))]:
        folder = Path(str(item.get("folder") or ""))
        gate = item.get("qualityGate") if isinstance(item.get("qualityGate"), dict) else folder_quality_gate(str(folder), "tiktok")
        if not gate.get("ok"):
            skipped.append({**item, "reason": "; ".join(gate.get("errors") or []) or "Quality gate failed."})
            continue
        try:
            response = buffer_post_from_folder(str(folder), channels, "tiktok", mode)
            posts = response.get("posts") if isinstance(response, dict) else []
            if any(post and not post.get("skipped") for post in posts):
                metadata = read_metadata(folder)
                abbr = story_key(str(metadata.get("abbr") or item.get("abbr") or ""))
                try:
                    chapter_number = int(metadata.get("chapter") or item.get("chapter") or 0)
                except (TypeError, ValueError):
                    chapter_number = 0
                if abbr and chapter_number >= 0:
                    update_chapter_ledger(
                        abbr,
                        chapter_number,
                        {
                            "deepTikTokQueued": True,
                            "deepTikTokQueuedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
                            "deepTikTokBufferResult": response,
                        },
                    )
                pushed.append({**item, "buffer": response})
            else:
                skipped.append({**item, "reason": "Buffer returned only skipped posts.", "buffer": response})
        except Exception as exc:
            errors.append({**item, "error": str(exc)})
    return {
        "ok": not errors,
        "pushed": pushed,
        "skipped": skipped,
        "errors": errors,
        "remaining": pending_deep_tiktok_items(),
        "message": f"Pushed {len(pushed)} deep TikTok item(s); {len(skipped)} skipped; {len(errors)} failed.",
    }


def reconcile_approval_inbox_items() -> dict[str, Any]:
    cleared: list[dict[str, Any]] = []
    queue = load_youtube_comment_queue()
    changed = False
    for item in queue.get("items", []):
        status = str(item.get("status") or "")
        if status == "posted" and item.get("videoId"):
            continue
        if status == "waiting_video_id" and str(item.get("folder") or "").lower().find("\\campaigns\\") >= 0:
            item["status"] = "archived_missing_video"
            item["clearedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
            cleared.append({"type": "youtubeComment", "id": item.get("id"), "reason": "Campaign placeholder had no uploaded YouTube video ID."})
            changed = True
    if changed:
        queue["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
        save_youtube_comment_queue(queue)
    comments = load_comment_assistant()
    before = len(comments.get("comments", []))
    comments["comments"] = [
        item for item in comments.get("comments", [])
        if str(item.get("status") or "") in {"pending", "prepared", "replied"}
    ]
    removed = before - len(comments["comments"])
    if removed:
        comments["cleanedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
        save_comment_assistant(comments)
        cleared.append({"type": "engagement", "count": removed, "reason": "Removed dismissed/noise items from the active queue."})
    return {"ok": True, "cleared": cleared, "message": f"Cleared {len(cleared)} stale approval bucket(s).", "approvalInbox": approval_inbox()}


