def pending_daily_shorts_items(ledger: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for abbr, novel in NOVEL_NAMES.items():
        chapter = active_chapter_path_next(abbr, "daily-shorts") or 0
        if chapter <= 0:
            continue
        entry = {}
        if isinstance(ledger, dict) and isinstance(ledger.get("chapters"), dict):
            entry = ledger["chapters"].get(f"{abbr}-{chapter}", {})
        if not entry:
            entry = chapter_ledger_entry(abbr, chapter)
        folders = entry.get("folders") if isinstance(entry.get("folders"), dict) else {}
        folder = Path(str(folders.get("shorts") or entry.get("shortsFolder") or TIKTOK_OUTPUT_DIR / f"{abbr.lower()}-{chapter}")).resolve()
        if not folder.exists():
            continue
        metadata = read_metadata(folder) if (folder / "metadata.json").exists() else {}
        if str(metadata.get("kind") or "") == "deep_tiktok" or folder.name.lower().endswith("-deep"):
            continue
        video = folder / "tiktok-video.mp4"
        shorts_built = bool((entry.get("shortsReelsBuilt") or entry.get("shortsPackBuilt")) and video.exists())
        shorts_queued = bool(
            entry.get("shortsReelsQueued")
            or entry.get("shortsQueued")
            or entry.get("tiktokQueued")
            or entry.get("instagramReelQueued")
            or entry.get("youtubeShortQueued")
        )
        if shorts_built and shorts_queued:
            continue
        gate = (
            folder_quality_gate(str(folder), "tiktok", full_duplicate_scan=False)
            if video.exists()
            else {"ok": False, "errors": ["tiktok-video.mp4 is missing."]}
        )
        items.append(
            {
                "abbr": abbr,
                "novel": novel,
                "chapter": chapter,
                "title": str(metadata.get("title") or entry.get("title") or f"Chapter {chapter}"),
                "folder": str(folder),
                "video": str(video) if video.exists() else "",
                "packStatus": str(metadata.get("packStatus") or ("ready_to_queue" if shorts_built else "needs_video_build")),
                "packType": str(metadata.get("packType") or "short_reel"),
                "packId": str(metadata.get("packId") or f"daily-shorts-{abbr.lower()}-{chapter}"),
                "qualityGate": gate,
                "needsRebuild": not video.exists() or bool(entry.get("shortsNeedsRebuild")),
                "needsBufferPush": bool(video.exists() and not shorts_queued),
                "reason": str(entry.get("shortsMissingReason") or ("Video exists locally but was not queued/pushed to Buffer." if video.exists() else "Shorts video is missing.")),
            }
        )
    return items


def unresolved_recovery_items(
    ledger: dict[str, Any] | None = None,
    active_paths: dict[str, int | None] | None = None,
) -> list[dict[str, Any]]:
    ledger = ledger if isinstance(ledger, dict) else load_chapter_ledger()
    result = []
    for entry in ledger.get("chapters", {}).values() if isinstance(ledger.get("chapters"), dict) else []:
        if not isinstance(entry, dict) or not isinstance(entry.get("lastFailure"), dict):
            continue
        if not approval_item_matches_active_chapter(entry, active_paths):
            continue
        failure = entry["lastFailure"]
        error_type = str(failure.get("errorType") or "")
        if error_type in {"openai_tts_quota", "youtube_text_build", "quality_gate_failed"} and entry.get("youtubeFullVideoBuilt"):
            continue
        if error_type in {"buffer_queue_full", "github_conflict"} and entry.get("bufferQueued"):
            continue
        if error_type == "chapter_exists_online" and entry.get("royalRoadReviewed"):
            continue
        result.append(
            {
                "abbr": entry.get("abbr"),
                "novel": entry.get("novel"),
                "chapter": entry.get("chapter"),
                "title": entry.get("title"),
                "time": failure.get("time"),
                "reason": failure.get("reason"),
                "retryPath": failure.get("retryPath"),
                "folder": failure.get("folder"),
                "errorType": error_type,
            }
        )
    result.sort(key=lambda item: str(item.get("time") or ""), reverse=True)
    return result[:20]


def pending_manual_social_items(active_paths: dict[str, int | None] | None = None) -> list[dict[str, Any]]:
    items = []
    cutoff = time.time() - 45 * 86400
    metadata_paths: list[Path] = []
    active_prefixes = {
        f"{abbr.lower()}-{chapter}"
        for abbr in NOVEL_NAMES
        for chapter in [active_paths.get(abbr) if isinstance(active_paths, dict) else active_chapter_path_next(abbr, "approval")]
        if chapter
    }
    for root in [SOCIAL_OUTPUT_DIR, EXPERIMENT_OUTPUT_DIR]:
        if not root.exists():
            continue
        try:
            recent_folders, _candidate_count = recent_metadata_folders(root, 80)
            metadata_paths.extend(
                folder / "metadata.json"
                for folder in recent_folders
                if not active_prefixes or any(folder.name.lower().startswith(prefix) for prefix in active_prefixes)
            )
        except Exception:
            for metadata_path in root.glob("*/metadata.json"):
                if active_prefixes and not any(metadata_path.parent.name.lower().startswith(prefix) for prefix in active_prefixes):
                    continue
                metadata_paths.append(metadata_path)
    metadata_paths.sort(key=lambda path: path.stat().st_mtime if path.exists() else 0, reverse=True)
    for metadata_path in metadata_paths[:120]:
            try:
                if metadata_path.stat().st_mtime < cutoff:
                    continue
                metadata = read_metadata(metadata_path.parent)
            except OSError:
                continue
            if is_chapter_upload_release_artifact(metadata_path.parent, metadata):
                continue
            for platform, text_name, posted_key, endpoint in [
                ("x", "x.txt", "manual_x_posted", "/api/x-manual-assist"),
                ("facebook", "facebook.txt", "manual_facebook_posted", "/api/facebook-manual-assist"),
            ]:
                if not (metadata_path.parent / text_name).exists() or metadata.get(posted_key):
                    continue
                item = {
                    "platform": platform,
                    "folder": str(metadata_path.parent),
                    "endpoint": endpoint,
                    "abbr": metadata.get("abbr"),
                    "novel": metadata.get("novel"),
                    "chapter": metadata.get("chapter"),
                    "title": metadata.get("title"),
                    "createdAt": metadata.get("createdAt") or time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(metadata_path.stat().st_mtime)),
                    "image": metadata.get("image"),
                    "_metadata": metadata,
                }
                if not approval_item_matches_active_chapter(item, active_paths):
                    continue
                items.append(item)
                if len(items) >= 40:
                    break
    cleaned_items = []
    for item in items:
        cleaned = dict(item)
        cleaned.pop("_metadata", None)
        cleaned_items.append(cleaned)
    items.sort(key=lambda item: str(item.get("createdAt") or ""), reverse=True)
    daily: dict[str, dict[str, Any]] = {}
    experiments = []
    for item in items:
        metadata = item.get("_metadata") if isinstance(item.get("_metadata"), dict) else {}
        if metadata.get("experimentId"):
            experiments.append(item)
            continue
        key = f"{item.get('platform')}:{story_key(str(item.get('abbr') or ''))}"
        visible = dict(item)
        visible.pop("_metadata", None)
        daily.setdefault(key, visible)
    cleaned_experiments = []
    for item in experiments[:6]:
        visible = dict(item)
        visible.pop("_metadata", None)
        cleaned_experiments.append(visible)
    return (list(daily.values()) + cleaned_experiments)[:16]


def pending_patreon_items(
    ledger: dict[str, Any] | None = None,
    active_paths: dict[str, int | None] | None = None,
) -> list[dict[str, Any]]:
    ledger = ledger if isinstance(ledger, dict) else load_chapter_ledger()
    items = []
    for entry in ledger.get("chapters", {}).values() if isinstance(ledger.get("chapters"), dict) else []:
        if not isinstance(entry, dict) or not entry.get("patreonDraftPrepared") or entry.get("postedToPatreon"):
            continue
        if not approval_item_matches_active_chapter(entry, active_paths):
            continue
        folders = entry.get("folders") if isinstance(entry.get("folders"), dict) else {}
        folder = str(entry.get("patreonDraftFolder") or entry.get("campaignFolder") or folders.get("campaign") or folders.get("social") or "")
        if not folder or not Path(folder).exists():
            continue
        metadata = read_metadata(Path(folder))
        if metadata.get("patreonSkipReason") or metadata.get("patreon_skipped"):
            continue
        item = {
            "abbr": entry.get("abbr"),
            "novel": entry.get("novel"),
            "chapter": entry.get("chapter"),
            "title": entry.get("title"),
            "folder": folder,
            "endpoint": "/api/patreon-draft",
            "preparedAt": entry.get("patreonDraftPreparedAt"),
        }
        items.append(item)
    items.sort(key=lambda item: str(item.get("preparedAt") or ""), reverse=True)
    latest: dict[str, dict[str, Any]] = {}
    for item in items:
        latest.setdefault(story_key(str(item.get("abbr") or "")), item)
    return list(latest.values())[:4]


