def clickup_request(method: str, path: str, payload: dict[str, Any] | None = None) -> dict[str, Any]:
    load_env_file()
    token = os.environ.get("CLICKUP_API_TOKEN", "").strip()
    if not token:
        raise RuntimeError("ClickUp API token is not configured.")
    url = "https://api.clickup.com/api/v2/" + path.lstrip("/")
    data = json.dumps(payload or {}).encode("utf-8") if payload is not None else None
    request = urllib.request.Request(
        url,
        data=data,
        method=method.upper(),
        headers={
            "Authorization": token,
            "Content-Type": "application/json",
            "Accept": "application/json",
            "User-Agent": "AzureInkbladeAutomationTool/1.0",
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=45) as response:
            raw = response.read().decode("utf-8")
        return json.loads(raw) if raw.strip() else {}
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"ClickUp API {method.upper()} {path} failed: HTTP {exc.code} {detail}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"ClickUp API is not reachable: {exc}") from exc


def clickup_invalid_list_error(error: Exception | str) -> bool:
    text = str(error).lower()
    return "validatelistid" in text or "list id invalid" in text or "input_003" in text


def clickup_target_list_name() -> str:
    return os.environ.get("CLICKUP_TASK_LIST_NAME", CLICKUP_DEFAULT_LIST_NAME).strip() or CLICKUP_DEFAULT_LIST_NAME


def clickup_saved_list_id() -> str:
    load_env_file()
    return os.environ.get("CLICKUP_TASK_LIST_ID", "").strip()


def clickup_resolve_list_by_name(name: str | None = None) -> dict[str, Any]:
    target = (name or clickup_target_list_name()).strip()
    if not target:
        raise RuntimeError("ClickUp list name is not configured.")
    teams = clickup_request("GET", "team").get("teams") or []
    matches: list[dict[str, Any]] = []
    for team in teams:
        team_id = str(team.get("id") or "").strip()
        if not team_id:
            continue
        spaces = clickup_request("GET", f"team/{team_id}/space?archived=false").get("spaces") or []
        for space in spaces:
            space_id = str(space.get("id") or "").strip()
            if not space_id:
                continue
            try:
                folderless_lists = clickup_request("GET", f"space/{space_id}/list?archived=false").get("lists") or []
            except Exception:
                folderless_lists = []
            for item in folderless_lists:
                if str(item.get("name") or "").strip().lower() == target.lower():
                    matches.append({"id": str(item.get("id") or ""), "name": item.get("name"), "space": space.get("name"), "folder": ""})
            folders = clickup_request("GET", f"space/{space_id}/folder?archived=false").get("folders") or []
            for folder in folders:
                folder_id = str(folder.get("id") or "").strip()
                if not folder_id:
                    continue
                try:
                    lists = clickup_request("GET", f"folder/{folder_id}/list?archived=false").get("lists") or []
                except Exception:
                    continue
                for item in lists:
                    if str(item.get("name") or "").strip().lower() == target.lower():
                        matches.append({"id": str(item.get("id") or ""), "name": item.get("name"), "space": space.get("name"), "folder": folder.get("name")})
    matches = [match for match in matches if match.get("id")]
    if not matches:
        raise RuntimeError(f"ClickUp list named {target!r} was not found for the current token.")
    if len(matches) > 1:
        choices = ", ".join(f"{match.get('name')} ({match.get('id')})" for match in matches[:6])
        raise RuntimeError(f"ClickUp found multiple lists named {target!r}; choose the exact list ID in Connections. Matches: {choices}")
    return matches[0]


def clickup_recover_list_id() -> str:
    match = clickup_resolve_list_by_name()
    list_id = str(match.get("id") or "").strip()
    if not list_id:
        raise RuntimeError("ClickUp list lookup did not return an ID.")
    upsert_env_values({"CLICKUP_TASK_LIST_ID": list_id, "CLICKUP_TASK_LIST_NAME": str(match.get("name") or clickup_target_list_name())})
    state = clickup_sync_state()
    state["list"] = {
        "id": list_id,
        "name": match.get("name"),
        "space": match.get("space"),
        "folder": match.get("folder"),
        "resolvedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "reason": "Recovered after ClickUp rejected the saved list ID.",
    }
    save_clickup_sync_state(state)
    return list_id


def clickup_create_task_in_list(list_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    try:
        return clickup_request("POST", f"list/{list_id}/task", payload)
    except Exception as exc:
        if not clickup_invalid_list_error(exc):
            raise
        recovered = clickup_recover_list_id()
        return clickup_request("POST", f"list/{recovered}/task", payload)


def clickup_sync_state() -> dict[str, Any]:
    data = _phase2_load_blob("clickupSync", CLICKUP_SYNC_FILE)
    if not isinstance(data, dict):
        data = {"schemaVersion": 1, "records": {}}
    data.setdefault("records", {})
    return data


def save_clickup_sync_state(data: dict[str, Any]) -> None:
    data["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    _phase2_save_blob("clickupSync", CLICKUP_SYNC_FILE, data)


def approval_item_record_id(kind: str, item: dict[str, Any]) -> str:
    parts = [
        "approval",
        kind,
        story_key(str(item.get("abbr") or "")) or "general",
        str(item.get("chapter") or ""),
        str(item.get("platform") or ""),
        str(item.get("commentId") or item.get("id") or ""),
        str(item.get("folder") or item.get("video") or item.get("watchUrl") or ""),
    ]
    raw = "|".join(parts)
    digest = content_hash(raw)[:10]
    readable = "-".join(slugify(part) for part in parts[:5] if slugify(part))
    return f"{readable}-{digest}"[:120]


def approval_item_clickup_task(kind: str, item: dict[str, Any]) -> dict[str, Any]:
    abbr = story_key(str(item.get("abbr") or ""))
    novel = str(item.get("novel") or NOVEL_NAMES.get(abbr, "") or "Azure Inkblade")
    chapter = str(item.get("chapter") or "").strip()
    platform = str(item.get("platform") or kind).strip()
    title = str(item.get("title") or item.get("reason") or item.get("text") or "").strip()
    record_id = approval_item_record_id(kind, item)
    name_parts = ["Review", kind.replace("_", " ").title()]
    if platform and platform.lower() != kind.lower():
        name_parts.append(platform.title())
    if abbr:
        name_parts.append(abbr)
    if chapter:
        name_parts.append(f"Ch. {chapter}")
    name = " - ".join(name_parts)
    lines = [
        f"Automation Record ID: {record_id}",
        f"Kind: {kind}",
        f"Novel: {novel}",
        f"Chapter: {chapter or 'General'}",
        f"Platform: {platform or 'N/A'}",
        f"Title: {title or 'N/A'}",
        "",
        "Needed Action:",
        {
            "comments": "Review and send or dismiss the prepared reply.",
            "messages": "Review and send or dismiss the prepared inbox reply.",
            "youtube": "Upload or verify the ready full YouTube video.",
            "deep_tiktoks": "Push the ready deep TikTok video or clear it if already handled.",
            "patreon": "Review the Patreon draft, tiers, and schedule date before publishing.",
            "manual_social": "Prepare/post the manual social item and mark it complete in the app.",
            "failures": "Resolve the failed automation step, then rerun or clear it.",
            "youtube_comments": "Verify the pinned comment/end-screen step or clear the item.",
        }.get(kind, "Review this app approval item."),
        "",
        "Failure / Retry:",
        str(item.get("reason") or item.get("retryPath") or item.get("error") or "None recorded."),
        "",
        "Local/App Data:",
    ]
    for key in ["folder", "image", "video", "watchUrl", "endpoint", "preparedAt", "createdAt", "time"]:
        value = item.get(key)
        if value:
            lines.append(f"- {key}: {value}")
    return {
        "recordId": record_id,
        "name": name[:250],
        "description": "\n".join(lines).strip(),
        "kind": kind,
        "item": item,
    }


def clickup_upsert_task(record: dict[str, Any], state: dict[str, Any]) -> dict[str, Any]:
    list_id = clickup_saved_list_id()
    if not list_id:
        list_id = clickup_recover_list_id()
    records = state.setdefault("records", {})
    record_id = str(record.get("recordId") or "")
    existing = records.get(record_id) if isinstance(records.get(record_id), dict) else {}
    payload = {
        "name": record["name"],
        "description": record["description"],
    }
    if existing.get("taskId"):
        response = clickup_request("PUT", f"task/{existing['taskId']}", payload)
        task_id = str(existing["taskId"])
        action = "updated"
    else:
        response = clickup_create_task_in_list(list_id, payload)
        task_id = str(response.get("id") or "")
        if not task_id:
            raise RuntimeError(f"ClickUp did not return a task id for {record_id}.")
        action = "created"
    records[record_id] = {
        "taskId": task_id,
        "name": record["name"],
        "kind": record.get("kind"),
        "lastSyncedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    return {"recordId": record_id, "taskId": task_id, "action": action, "name": record["name"], "url": response.get("url")}


def sync_approval_inbox_to_clickup() -> dict[str, Any]:
    if not clickup_configured():
        raise RuntimeError("Add CLICKUP_API_TOKEN and CLICKUP_TASK_LIST_ID in Connections first.")
    inbox = approval_inbox()
    candidates: list[dict[str, Any]] = []
    bucket_map = {
        "comments": "comments",
        "messages": "messages",
        "youtube": "youtube",
        "deepTikToks": "deep_tiktoks",
        "patreon": "patreon",
        "manualSocial": "manual_social",
        "failures": "failures",
        "youtubeComments": "youtube_comments",
    }
    for bucket, kind in bucket_map.items():
        for item in inbox.get(bucket, []) if isinstance(inbox.get(bucket), list) else []:
            candidates.append(approval_item_clickup_task(kind, item))
    state = clickup_sync_state()
    synced: list[dict[str, Any]] = []
    errors: list[dict[str, str]] = []
    for record in candidates:
        try:
            synced_task = clickup_upsert_task(record, state)
            synced.append(synced_task)
            item = record.get("item") if isinstance(record.get("item"), dict) else {}
            folder_value = str(item.get("folder") or "").strip()
            if folder_value:
                folder_path = Path(folder_value).resolve()
                if folder_path.exists():
                    metadata = read_metadata(folder_path)
                    platform = str(item.get("platform") or record.get("kind") or metadata.get("platform") or "app")
                    post_record = post_record_from_folder(
                        folder_path,
                        platform,
                        metadata,
                        clickupTaskId=synced_task.get("taskId", ""),
                    )
                    save_post_record(post_record)
        except Exception as exc:
            errors.append({"recordId": str(record.get("recordId") or ""), "error": str(exc)})
    save_clickup_sync_state(state)
    return {
        "ok": not errors,
        "message": f"Synced {len(synced)} approval item(s) to ClickUp." + (f" {len(errors)} failed." if errors else ""),
        "synced": synced,
        "errors": errors,
        "file": str(CLICKUP_SYNC_FILE),
    }


def clickup_connection_test() -> dict[str, Any]:
    if not os.environ.get("CLICKUP_API_TOKEN", "").strip():
        raise RuntimeError("Add CLICKUP_API_TOKEN in Connections first.")
    list_id = clickup_saved_list_id()
    recovered = False
    if not list_id:
        list_id = clickup_recover_list_id()
        recovered = True
    try:
        data = clickup_request("GET", f"list/{list_id}")
    except Exception as exc:
        if not clickup_invalid_list_error(exc):
            raise
        list_id = clickup_recover_list_id()
        data = clickup_request("GET", f"list/{list_id}")
        recovered = True
    return {
        "ok": True,
        "listId": list_id,
        "name": data.get("name"),
        "space": data.get("space", {}).get("name") if isinstance(data.get("space"), dict) else "",
        "recovered": recovered,
        "message": f"ClickUp connected to list: {data.get('name') or list_id}" + (" Saved list ID was repaired." if recovered else ""),
    }


