def google_ai_request(payload: dict[str, Any]) -> dict[str, Any]:
    if not EXTERNAL_AI_ENABLED:
        raise RuntimeError("External AI disabled (ENABLE_EXTERNAL_AI not set); using local/fallback path.")
    key = os.environ.get("GOOGLE_AI_API_KEY", "").strip()
    if not key:
        raise RuntimeError("GOOGLE_AI_API_KEY is not configured.")
    request = urllib.request.Request(
        "https://generativelanguage.googleapis.com/v1beta/interactions",
        data=json.dumps(payload).encode("utf-8"),
        method="POST",
        headers={
            "x-goog-api-key": key,
            "Content-Type": "application/json",
            "Accept": "application/json",
            "User-Agent": "AzureInkbladeAutomationTool/1.0",
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=90) as response:
            raw = response.read().decode("utf-8")
        return json.loads(raw) if raw.strip() else {}
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"Google AI API failed: HTTP {exc.code} {detail}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Google AI API is not reachable: {exc}") from exc


def google_ai_extract_text(response: dict[str, Any]) -> str:
    direct = response.get("output_text")
    if isinstance(direct, str) and direct.strip():
        return direct.strip()
    pieces: list[str] = []
    for step in response.get("steps", []) if isinstance(response.get("steps"), list) else []:
        if not isinstance(step, dict):
            continue
        for key in ["output", "content", "contents"]:
            value = step.get(key)
            if isinstance(value, str):
                pieces.append(value)
            elif isinstance(value, list):
                for item in value:
                    if isinstance(item, str):
                        pieces.append(item)
                    elif isinstance(item, dict):
                        text = item.get("text")
                        if isinstance(text, str):
                            pieces.append(text)
    return "\n".join(part.strip() for part in pieces if part and part.strip()).strip()


def google_ai_extract_image_data(response: dict[str, Any]) -> tuple[str, str]:
    def walk(value: Any) -> tuple[str, str]:
        if isinstance(value, dict):
            output_image = value.get("output_image")
            if isinstance(output_image, dict):
                data = str(output_image.get("data") or "")
                mime_type = str(output_image.get("mime_type") or output_image.get("mimeType") or "image/png")
                if data:
                    return data, mime_type
            data = str(value.get("data") or "")
            mime_type = str(value.get("mime_type") or value.get("mimeType") or "")
            if data and mime_type.startswith("image/"):
                return data, mime_type
            for child in value.values():
                found = walk(child)
                if found[0]:
                    return found
        elif isinstance(value, list):
            for item in value:
                found = walk(item)
                if found[0]:
                    return found
        return "", ""

    return walk(response)


def load_google_ai_image_usage() -> dict[str, Any]:
    today = time.strftime("%Y-%m-%d")
    minute = time.strftime("%Y-%m-%d %H:%M")
    data = _phase2_load_blob("googleAiImageUsage", GOOGLE_AI_IMAGE_USAGE_FILE)
    if not isinstance(data, dict):
        data = {"schemaVersion": 1}
    if data.get("date") != today:
        data["date"] = today
        data["dailyCount"] = 0
        data["minutes"] = {}
    data.setdefault("minutes", {})
    if not isinstance(data["minutes"], dict):
        data["minutes"] = {}
    data["currentMinute"] = minute
    return data


def seconds_until_next_minute(buffer_seconds: float = 1.25) -> float:
    return max(0.0, 60.0 - (time.time() % 60.0) + buffer_seconds)


def reserve_google_ai_image_quota(wait_for_slot: bool = False, max_wait_seconds: float = 75.0) -> dict[str, Any]:
    strategy = load_automation_strategy()
    rules = strategy.get("quotaRules") if isinstance(strategy.get("quotaRules"), dict) else {}
    daily_limit = int(rules.get("googleAiDailyImageLimit") or 100)
    per_minute = int(rules.get("googleAiImagesPerMinute") or 2)
    started = time.time()
    waited = 0.0
    while True:
        usage = load_google_ai_image_usage()
        minute = str(usage.get("currentMinute") or time.strftime("%Y-%m-%d %H:%M"))
        daily_count = int(usage.get("dailyCount") or 0)
        minute_count = int(usage.get("minutes", {}).get(minute) or 0)
        if daily_count >= daily_limit:
            raise RuntimeError(f"Google AI daily image quota reached ({daily_count}/{daily_limit}).")
        if minute_count < per_minute:
            usage["dailyCount"] = daily_count + 1
            usage["minutes"][minute] = minute_count + 1
            usage["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
            _phase2_save_blob("googleAiImageUsage", GOOGLE_AI_IMAGE_USAGE_FILE, usage)
            return {
                "dailyCount": usage["dailyCount"],
                "dailyLimit": daily_limit,
                "minuteCount": usage["minutes"][minute],
                "minuteLimit": per_minute,
                "minute": minute,
                "waitedSeconds": round(waited, 2),
            }
        if not wait_for_slot:
            raise RuntimeError(f"Google AI image rate limit reached for this minute ({minute_count}/{per_minute}).")
        wait_seconds = seconds_until_next_minute()
        if time.time() - started + wait_seconds > max_wait_seconds:
            raise RuntimeError(f"Google AI image rate limit reached for this minute ({minute_count}/{per_minute}); waited {round(time.time() - started, 1)}s.")
        time.sleep(wait_seconds)
        waited = time.time() - started


def refund_google_ai_image_quota(quota: dict[str, Any]) -> None:
    minute = str(quota.get("minute") or "")
    usage = load_google_ai_image_usage()
    if int(usage.get("dailyCount") or 0) > 0:
        usage["dailyCount"] = int(usage.get("dailyCount") or 0) - 1
    if minute and isinstance(usage.get("minutes"), dict) and int(usage["minutes"].get(minute) or 0) > 0:
        usage["minutes"][minute] = int(usage["minutes"].get(minute) or 0) - 1
    usage["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    _phase2_save_blob("googleAiImageUsage", GOOGLE_AI_IMAGE_USAGE_FILE, usage)


def create_google_ai_image(prompt: str, target: Path, *, orientation: str = "vertical") -> dict[str, Any]:
    if not google_ai_configured():
        raise RuntimeError("GOOGLE_AI_API_KEY is not configured.")
    quota = reserve_google_ai_image_quota(wait_for_slot=True)
    aspect_ratio = "9:16" if orientation == "vertical" else "16:9" if orientation == "horizontal" else "1:1"
    payload = {
        "model": google_ai_image_model(),
        "input": [{"type": "text", "text": prompt}],
        "response_format": {
            "type": "image",
            "mime_type": "image/jpeg",
            "aspect_ratio": aspect_ratio,
        },
    }
    try:
        response = google_ai_request(payload)
    except Exception:
        refund_google_ai_image_quota(quota)
        raise
    data, mime_type = google_ai_extract_image_data(response)
    if not data:
        refund_google_ai_image_quota(quota)
        raise RuntimeError("Google AI image response did not include image data.")
    raw_image = base64.b64decode(data)
    if target.suffix.lower() == ".png":
        try:
            from PIL import Image

            with Image.open(io.BytesIO(raw_image)) as image:
                image.convert("RGB").save(target, "PNG")
        except Exception:
            target.write_bytes(raw_image)
    else:
        target.write_bytes(raw_image)
    state = mark_image_used(target)
    save_promo_rotation_state(state)
    return {"provider": "google_ai", "model": payload["model"], "mimeType": mime_type or "image/jpeg", "quota": quota}


def local_stable_diffusion_configured() -> bool:
    if str(os.environ.get("LOCAL_SD_ENABLED", "1")).strip().lower() in {"0", "false", "no", "off"}:
        return False
    if not LOCAL_IMAGE_GENERATOR_SCRIPT.exists():
        return False
    try:
        import importlib.util

        return all(importlib.util.find_spec(name) is not None for name in ["torch", "diffusers", "transformers", "PIL"])
    except Exception:
        return False


def local_stable_diffusion_default_model() -> str:
    configured = os.environ.get("LOCAL_SD_MODEL", "").strip()
    if configured:
        return configured
    local_model = ROOT / "models" / "sdxl-base"
    if (local_model / "model_index.json").exists():
        return str(local_model)
    return "stabilityai/stable-diffusion-xl-base-1.0"


def local_stable_diffusion_quality_mode() -> str:
    return os.environ.get("LOCAL_SD_QUALITY_MODE", "premium").strip() or "premium"


def ensure_lora_training_layout() -> dict[str, Any]:
    tracks: dict[str, Any] = {}
    for key, spec in LORA_STYLE_TRACKS.items():
        training_root = LORA_TRAINING_DIR / key
        model_root = LORA_MODEL_DIR / key
        folders = {
            "approved": training_root / "approved",
            "rejected": training_root / "rejected",
            "captions": training_root / "captions",
            "datasets": training_root / "datasets",
            "output": training_root / "output",
            "models": model_root,
        }
        for folder in folders.values():
            folder.mkdir(parents=True, exist_ok=True)
        config_path = training_root / "config.json"
        if not config_path.exists():
            write_json_atomic(
                config_path,
                {
                    "schemaVersion": 1,
                    "track": key,
                    "label": spec.get("label", key),
                    "triggerToken": spec.get("trigger", ""),
                    "promptSuffix": spec.get("promptSuffix", ""),
                    "use": spec.get("use", ""),
                    "sourceFolders": {
                        "approved": str(folders["approved"]),
                        "rejected": str(folders["rejected"]),
                        "captions": str(folders["captions"]),
                        "datasets": str(folders["datasets"]),
                    },
                    "outputFolder": str(folders["output"]),
                    "modelFolder": str(model_root),
                    "notes": "Put approved training images and matching captions here. Drop trained LoRA weights in the model folder or output folder.",
                },
            )
        readme_path = training_root / "README.md"
        if not readme_path.exists():
            readme_path.write_text(
                "\n".join(
                    [
                        f"# {spec.get('label', key)} LoRA Track",
                        "",
                        str(spec.get("use", "")),
                        "",
                        f"Trigger token: `{spec.get('trigger', '')}`",
                        "",
                        "- `approved/`: curated images that should influence future training.",
                        "- `rejected/`: examples to avoid; keep for review, not training.",
                        "- `captions/`: one caption text file per approved image.",
                        "- `datasets/`: prepared training datasets.",
                        "- `output/`: training output or exported weights.",
                        f"- `{model_root}`: active LoRA weights the app can load.",
                        "",
                    ]
                ),
                encoding="utf-8",
            )
        weights = find_lora_weights_for_track(key)
        tracks[key] = {
            "track": key,
            "label": spec.get("label", key),
            "triggerToken": spec.get("trigger", ""),
            "trainingFolder": str(training_root),
            "modelFolder": str(model_root),
            "activeWeight": str(weights) if weights else "",
            "hasModel": bool(weights),
            "folders": {name: str(path) for name, path in folders.items()},
        }
    return {
        "enabled": os.environ.get("LOCAL_SD_LORA_ENABLED", "1").strip().lower() not in {"0", "false", "no", "off"},
        "trainingRoot": str(LORA_TRAINING_DIR),
        "modelRoot": str(LORA_MODEL_DIR),
        "tracks": tracks,
    }


def find_lora_weights_for_track(track: str) -> Path | None:
    roots = [LORA_MODEL_DIR / track, LORA_TRAINING_DIR / track / "output"]
    suffixes = {".safetensors", ".pt", ".bin"}
    candidates: list[Path] = []
    for root in roots:
        if not root.exists():
            continue
        candidates.extend(path for path in root.rglob("*") if path.is_file() and path.suffix.lower() in suffixes)
    if not candidates:
        return None
    return sorted(candidates, key=lambda path: path.stat().st_mtime, reverse=True)[0]


def lora_track_for_prompt(prompt: str, *, purpose: str = "", orientation: str = "vertical") -> str:
    text = f"{prompt} {purpose} {orientation}".lower()
    if any(term in text for term in ["realistic", "photoreal", "photo-real", "live action", "cinematic realism", "real world"]):
        return "realistic-posts"
    if any(term in text for term in ["comic", "manhwa", "manga", "webtoon", "panel", "deep tiktok", "story hook", "shorts", "reels"]):
        return "comic-style"
    return "main-posts"


def local_lora_status() -> dict[str, Any]:
    return ensure_lora_training_layout()


def enhance_local_sd_prompt(prompt: str, *, orientation: str = "vertical", lora_track: str = "") -> str:
    if os.environ.get("LOCAL_SD_PROMPT_BOOST_ENABLED", "1").strip().lower() in {"0", "false", "no", "off"}:
        return prompt
    prompt = re.sub(r"\s+", " ", str(prompt or "")).strip()
    orientation_hint = "vertical 9:16" if orientation == "vertical" else "cinematic 16:9" if orientation == "horizontal" else "square"
    track = lora_track if lora_track in LORA_STYLE_TRACKS else lora_track_for_prompt(prompt, orientation=orientation)
    track_spec = LORA_STYLE_TRACKS.get(track, LORA_STYLE_TRACKS["main-posts"])
    quality_bits = [
        str(track_spec.get("trigger") or ""),
        str(track_spec.get("promptSuffix") or ""),
        f"{orientation_hint} web novel promotional illustration",
        "modern manhwa and anime-influenced fantasy art",
        "clear focal character or story object",
        "dramatic lighting, readable composition, strong foreground and background separation",
        "chapter-specific scene, not a generic landscape",
        "high detail, polished digital painting",
    ]
    lower = prompt.lower()
    missing_bits = [bit for bit in quality_bits if bit.lower() not in lower]
    if missing_bits:
        prompt = f"{prompt}. " + ", ".join(missing_bits)
    return prompt


# ============================================================================
# AIVSB Reasoning Layer - DORMANT integration boundary (Phase B)
# ----------------------------------------------------------------------------
# Flag:  AIVSB_REASONING_ENABLED  (default "0" = disabled)
# This function is intentionally NOT called by any live generation path yet
# (Phase C is not enabled). It exists so the reasoning layer can be opted in
# later without restructuring. When disabled it returns None and the caller
# keeps the legacy prompt unchanged (byte-for-byte where practical).
#
# Robustness contract:
#   - Import failure / missing Bible / ComposerError -> returns None (never raises).
#   - No GPU libraries imported (the reasoning package uses only PyYAML).
#   - Does not restart the server, touch _LOCAL_SD_GPU_LOCK, or write state.
#   - Structured log line records enabled / skipped / failed.
# ============================================================================
def compose_aivsb_scene_prompt(
    novel: str,
    beat: str,
    character: str,
    *,
    platform: str = "youtube_short",
    asset_type: str = "chapter_still",
    orientation: str = "vertical",
    legacy_prompt: str = "",
) -> dict | None:
    """Return a ComposedScenePrompt dict (or None) from the AIVSB reasoning layer.

    Returns None when:
      - the feature flag is off,
      - the reasoning package or Bible is unavailable,
      - the SceneRequest/SceneDecision is invalid (ComposerError).
    The caller should fall back to legacy_prompt when None is returned.
    """
    enabled = os.environ.get("AIVSB_REASONING_ENABLED", "0").strip().lower()
    if enabled in ("", "0", "false", "no", "off"):
        print("[aivsb-reasoning] skipped: AIVSB_REASONING_ENABLED is off (default)")
        return None

    # Resolve the reasoning package (sibling of this app, NOT co-located).
    aivsb_reasoning = (
        ROOT.parent
        / "Inkblade Author Studio"
        / "scripts"
        / "aivsb"
        / "reasoning"
    )
    if not aivsb_reasoning.exists():
        print(f"[aivsb-reasoning] failed: reasoning package not found at {aivsb_reasoning}")
        return None

    # The aivsb package uses flat sibling imports: `reasoning`, `retrieval`,
    # and bare `from models import` (retrieval/models.py) all resolve as
    # top-level modules. Adding only `aivsb/reasoning` was insufficient and
    # caused "No module named 'retrieval'/'models'" -> silent fallback to the
    # legacy prompt. Register the three path roots the package expects.
    aivsb_root = aivsb_reasoning.parent  # scripts/aivsb
    aivsb_retrieval = aivsb_root / "retrieval"
    for entry in (str(aivsb_reasoning), str(aivsb_retrieval), str(aivsb_root)):
        if entry not in sys.path:
            sys.path.insert(0, entry)

    try:
        from director_engine import direct_scene
        from prompt_composer import compose_prompt, ComposerError
        from scene_request import SceneRequest
    except Exception as exc:  # import or dependency failure
        print(f"[aivsb-reasoning] failed: cannot import reasoning layer ({exc})")
        return None

    try:
        scene = direct_scene(novel, beat, character)
        req = SceneRequest(
            novel_id=novel,
            character_ids=(character,),
            platform=platform,
            asset_type=asset_type,
            orientation=orientation,
        )
        result = compose_prompt(scene, req)
        print(
            f"[aivsb-reasoning] enabled: composed for {novel}/{beat}/{character} "
            f"lora={result.lora_track} source={result.lora_source} "
            f"rules={len(result.applied_rule_ids)}"
        )
        return result.to_dict()
    except ComposerError as exc:
        print(f"[aivsb-reasoning] failed: composer rejected request ({exc})")
        return None
    except Exception as exc:  # defensive: never break legacy image production
        print(f"[aivsb-reasoning] failed: unexpected error ({exc})")
        return None


def local_sd_python() -> Path:
    """Resolve the Python interpreter used to run the local Stable Diffusion / diffusers
    generator. Kept separate from the app's main interpreter so the heavy GPU stack
    (torch/diffusers) lives in its own .venv-gpu and a Codex runtime refresh can't
    wipe it. Order: LOCAL_SD_PYTHON env -> project .venv-gpu -> main interpreter."""
    configured = os.environ.get("LOCAL_SD_PYTHON", "").strip()
    if configured:
        return Path(configured)
    project_python = ROOT / ".venv-gpu" / "Scripts" / "python.exe"
    if project_python.exists():
        return project_python
    return Path(sys.executable)


_SD_PROBE_CACHE: dict[str, Any] = {"key": None, "at": 0.0, "deps": None, "cuda": False, "gpu": ""}
_SD_PROBE_TTL_SECONDS = 300

# Serialize diffusers image generation on the GPU. HeavyJobLimiter is a shared
# semaphore that also admits ffmpeg and allows parallel heavy jobs, so it does NOT
# prevent two Stable Diffusion subprocesses from contending for VRAM. This lock
# guarantees only one diffusers GPU job runs at a time. A second call blocks until
# the GPU clears (auto-queues the next), and local_sd_busy() reports the state.
_LOCAL_SD_GPU_LOCK = threading.Lock()


def _probe_local_sd_dependencies() -> tuple[dict[str, bool], bool, str]:
    """Probe torch/diffusers deps + CUDA in the GPU interpreter via a subprocess.
    Cached for _SD_PROBE_TTL_SECONDS keyed on the interpreter path, because the
    subprocess imports torch (~seconds) and the result is stable during a run.
    Build All Posts calls status once per image, so caching avoids re-importing
    torch on every generation."""
    default_deps = {name: False for name in ["torch", "diffusers", "transformers", "PIL"]}
    interp = str(local_sd_python())
    now = time.time()
    if (
        _SD_PROBE_CACHE["key"] == interp
        and _SD_PROBE_CACHE["deps"] is not None
        and (now - _SD_PROBE_CACHE["at"]) < _SD_PROBE_TTL_SECONDS
    ):
        return _SD_PROBE_CACHE["deps"], _SD_PROBE_CACHE["cuda"], _SD_PROBE_CACHE["gpu"]

    dependencies = dict(default_deps)
    cuda_available = False
    gpu_name = ""
    # Run the probe inline via `python -c` so no temp .py file is ever written.
    # (Writing a probe file into ROOT previously orphaned hundreds of
    # hermes-sd-probe-*.py when the server was killed mid-probe before cleanup.)
    probe_src = (
        "import importlib.util as u,json\n"
        "mods=['torch','diffusers','transformers','PIL']\n"
        "deps={m:(u.find_spec(m) is not None) for m in mods}\n"
        "cuda=False;gpu=''\n"
        "try:\n"
        " import torch\n"
        " cuda=torch.cuda.is_available()\n"
        " gpu=torch.cuda.get_device_name(0) if cuda else ''\n"
        "except Exception:\n"
        " pass\n"
        "print(json.dumps({'deps':deps,'cuda':cuda,'gpu':gpu}))\n"
    )
    try:
        env = {k: v for k, v in os.environ.items() if k not in ("PYTHONPATH", "PYTHONHOME")}
        completed = subprocess.run(
            [interp, "-c", probe_src],
            capture_output=True, text=True, timeout=60, env=env,
        )
        if completed.returncode == 0 and completed.stdout.strip():
            payload = json.loads(completed.stdout.strip().splitlines()[-1])
            dependencies = payload.get("deps", dependencies)
            cuda_available = payload.get("cuda", False)
            gpu_name = payload.get("gpu", "")
            # Only cache a successful probe; failures fall through and retry next call.
            _SD_PROBE_CACHE.update({"key": interp, "at": now, "deps": dependencies, "cuda": cuda_available, "gpu": gpu_name})
    except Exception:
        dependencies = dict(default_deps)
    return dependencies, cuda_available, gpu_name


def local_stable_diffusion_status() -> dict[str, Any]:
    enabled = str(os.environ.get("LOCAL_SD_ENABLED", "1")).strip().lower() not in {"0", "false", "no", "off"}
    dependencies, cuda_available, gpu_name = _probe_local_sd_dependencies()
    return {
        "ready": enabled and LOCAL_IMAGE_GENERATOR_SCRIPT.exists() and all(dependencies.values()),
        "enabled": enabled,
        "script": str(LOCAL_IMAGE_GENERATOR_SCRIPT),
        "model": local_stable_diffusion_default_model(),
        "refinerModel": os.environ.get("LOCAL_SD_REFINER_MODEL", ""),
        "qualityMode": local_stable_diffusion_quality_mode(),
        "scheduler": os.environ.get("LOCAL_SD_SCHEDULER", "dpm"),
        "lora": local_lora_status(),
        "timeoutSeconds": int(os.environ.get("LOCAL_SD_TIMEOUT_SECONDS", "360")),
        "dependencies": dependencies,
        "cudaAvailable": cuda_available,
        "gpuName": gpu_name,
        "use": "primary local SDXL/diffusers image pipeline before external quota providers",
    }


def local_sd_busy() -> bool:
    """True when a diffusers image generation is currently holding the GPU lock.

    Callers (UI/CLI/weekend builder) can check this to report 'image gen already
    in progress' instead of launching a contending job. A second generation call
    auto-queues behind the lock and runs once the GPU clears."""
    return _LOCAL_SD_GPU_LOCK.locked()


def create_local_stable_diffusion_image(
    prompt: str,
    target: Path,
    *,
    orientation: str = "vertical",
    seed: int = 0,
    input_image: Path | None = None,
    strength: float | None = None,
    quality_mode: str = "",
) -> dict[str, Any]:
    status = local_stable_diffusion_status()
    if not status.get("ready"):
        missing = [name for name, ready in (status.get("dependencies") or {}).items() if not ready]
        raise RuntimeError(f"Local Stable Diffusion is not ready. Missing: {', '.join(missing) or 'generator script'}")
    if orientation == "horizontal":
        width = int(os.environ.get("LOCAL_SD_HORIZONTAL_WIDTH", "1344"))
        height = int(os.environ.get("LOCAL_SD_HORIZONTAL_HEIGHT", "768"))
    elif orientation == "square":
        width = int(os.environ.get("LOCAL_SD_SQUARE_SIZE", "1024"))
        height = width
    else:
        width = int(os.environ.get("LOCAL_SD_VERTICAL_WIDTH", "768"))
        height = int(os.environ.get("LOCAL_SD_VERTICAL_HEIGHT", "1344"))
    target.parent.mkdir(parents=True, exist_ok=True)
    lora_track = lora_track_for_prompt(prompt, orientation=orientation)
    lora_path = find_lora_weights_for_track(lora_track) if os.environ.get("LOCAL_SD_LORA_ENABLED", "1").strip().lower() not in {"0", "false", "no", "off"} else None
    prompt = enhance_local_sd_prompt(prompt, orientation=orientation, lora_track=lora_track)
    metadata_path = target.with_suffix(target.suffix + ".local-sd.json")
    negative = os.environ.get(
        "LOCAL_SD_NEGATIVE_PROMPT",
        "text, typography, watermark, logo, blurry, low quality, distorted hands, extra fingers, duplicate face, duplicate body, bad anatomy, flat lighting, generic stock photo, unrelated landscape",
    )
    command = [
        str(local_sd_python()),
        str(LOCAL_IMAGE_GENERATOR_SCRIPT),
        "--prompt",
        prompt,
        "--output",
        str(target),
        "--negative-prompt",
        negative,
        "--model",
        str(status.get("model") or "stabilityai/stable-diffusion-xl-base-1.0"),
        "--refiner-model",
        str(status.get("refinerModel") or ""),
        "--quality-mode",
        quality_mode or str(status.get("qualityMode") or "premium"),
        "--scheduler",
        str(status.get("scheduler") or "dpm"),
        "--width",
        str(width),
        "--height",
        str(height),
        "--steps",
        os.environ.get("LOCAL_SD_STEPS", "0"),
        "--guidance-scale",
        os.environ.get("LOCAL_SD_GUIDANCE_SCALE", "0"),
        "--seed",
        str(seed or random.randint(1, 2_147_483_000)),
        "--metadata",
        str(metadata_path),
    ]
    if lora_path:
        command.extend(["--lora-path", str(lora_path), "--lora-scale", os.environ.get("LOCAL_SD_LORA_SCALE", "0.75")])
    if input_image and input_image.exists():
        command.extend(["--input-image", str(input_image), "--strength", str(strength if strength is not None else os.environ.get("LOCAL_SD_IMG2IMG_STRENGTH", "0.52"))])
    with _LOCAL_SD_GPU_LOCK:
        timeout = int(status.get("timeoutSeconds") or 360)
        gen_env = {k: v for k, v in os.environ.items() if k not in ("PYTHONPATH", "PYTHONHOME")}
        with HeavyJobLimiter():
            completed = subprocess.run(command, cwd=str(ROOT), capture_output=True, text=True, timeout=timeout, env=gen_env)
        if completed.returncode != 0:
            detail = (completed.stderr or completed.stdout or "").strip()
            raise RuntimeError(detail[-800:] or f"Local Stable Diffusion exited with code {completed.returncode}.")
        if not target.exists() or target.stat().st_size < 1024:
            raise RuntimeError("Local Stable Diffusion did not create a valid image file.")
        try:
            metadata = json.loads(metadata_path.read_text(encoding="utf-8")) if metadata_path.exists() else {}
        except Exception:
            metadata = {}
        state = mark_image_used(target)
        save_promo_rotation_state(state)
        metadata.setdefault("provider", "local_stable_diffusion")
        metadata.setdefault("model", status.get("model", ""))
        metadata.setdefault("loraTrack", lora_track)
        metadata.setdefault("loraPath", str(lora_path) if lora_path else "")
        return metadata


def google_ai_generate_text(prompt: str, system_instruction: str = "", model: str = "", temperature: float | None = None) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "model": model.strip() if model else google_ai_model(),
        "input": prompt,
    }
    if system_instruction.strip():
        payload["system_instruction"] = system_instruction.strip()
    if temperature is not None:
        payload["generation_config"] = {"temperature": float(temperature)}
    response = google_ai_request(payload)
    return {
        "model": payload["model"],
        "text": google_ai_extract_text(response),
        "raw": response,
    }


def google_ai_generate_json(prompt: str, system_instruction: str = "", model: str = "", temperature: float | None = None) -> dict[str, Any]:
    result = google_ai_generate_text(prompt, system_instruction=system_instruction, model=model, temperature=temperature)
    text = str(result.get("text") or "").strip()
    match = re.search(r"\{.*\}", text, re.DOTALL)
    if match:
        text = match.group(0)
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise RuntimeError(f"Google AI did not return valid JSON: {exc}") from exc
    data["_google_ai_model"] = result.get("model")
    return data


def google_ai_connection_test() -> dict[str, Any]:
    result = google_ai_generate_text(
        "Reply with exactly: Google AI connected.",
        system_instruction="You are testing an API connection. Keep the response short.",
        temperature=0.0,
    )
    text = result.get("text", "")
    return {
        "ok": True,
        "model": result.get("model"),
        "message": "Google AI connected.",
        "preview": text[:200],
    }


def youtube_data_api_configured() -> bool:
    return bool(os.environ.get("YOUTUBE_DATA_API_KEY", "").strip())


def youtube_video_id_from_value(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    if re.fullmatch(r"[A-Za-z0-9_-]{11}", text):
        return text
    patterns = [
        r"[?&]v=([A-Za-z0-9_-]{11})",
        r"youtu\.be/([A-Za-z0-9_-]{11})",
        r"/shorts/([A-Za-z0-9_-]{11})",
        r"/video/([A-Za-z0-9_-]{11})",
        r"/embed/([A-Za-z0-9_-]{11})",
    ]
    for pattern in patterns:
        match = re.search(pattern, text)
        if match:
            return match.group(1)
    return ""


def youtube_data_api_request(resource: str, params: dict[str, Any]) -> dict[str, Any]:
    key = os.environ.get("YOUTUBE_DATA_API_KEY", "").strip()
    if not key:
        raise RuntimeError("YOUTUBE_DATA_API_KEY is not configured.")
    query = {key_name: str(value) for key_name, value in params.items() if value not in {None, ""}}
    query["key"] = key
    url = f"https://www.googleapis.com/youtube/v3/{resource.lstrip('/')}?{urllib.parse.urlencode(query)}"
    request = urllib.request.Request(url, headers={"Accept": "application/json", "User-Agent": "AzureInkbladeAutomationTool/1.0"})
    try:
        with urllib.request.urlopen(request, timeout=45) as response:
            raw = response.read().decode("utf-8")
        return json.loads(raw) if raw.strip() else {}
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"YouTube Data API {resource} failed: HTTP {exc.code} {detail}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"YouTube Data API is not reachable: {exc}") from exc


def youtube_channel_stats(handle: str = "", channel_id: str = "") -> dict[str, Any]:
    channel_id = str(channel_id or os.environ.get("YOUTUBE_CHANNEL_ID") or "").strip()
    handle = str(handle or os.environ.get("YOUTUBE_CHANNEL_HANDLE") or "@AzureInkblade").strip()
    params: dict[str, Any] = {"part": "snippet,statistics"}
    if channel_id:
        params["id"] = channel_id
    else:
        params["forHandle"] = handle if handle.startswith("@") else f"@{handle}"
    data = youtube_data_api_request("channels", params)
    items = data.get("items") if isinstance(data.get("items"), list) else []
    if len(items) != 1:
        raise RuntimeError(f"YouTube channel lookup returned {len(items)} result(s). Use the permanent channel ID if the handle is ambiguous.")
    item = items[0]
    stats = item.get("statistics") if isinstance(item.get("statistics"), dict) else {}
    snippet = item.get("snippet") if isinstance(item.get("snippet"), dict) else {}
    return {
        "platform": "youtube",
        "channelId": str(item.get("id") or channel_id),
        "handle": handle,
        "title": str(snippet.get("title") or ""),
        "description": str(snippet.get("description") or ""),
        "metrics": {
            "subscribers": numeric_metric(stats.get("subscriberCount")),
            "views": numeric_metric(stats.get("viewCount")),
            "videoCount": numeric_metric(stats.get("videoCount")),
        },
        "raw": item,
    }


def youtube_video_stats(video_id: str) -> dict[str, Any]:
    video_id = youtube_video_id_from_value(video_id)
    if not video_id:
        raise RuntimeError("A valid YouTube video ID or watch URL is required.")
    data = youtube_data_api_request("videos", {"part": "snippet,statistics,contentDetails,status", "id": video_id})
    items = data.get("items") if isinstance(data.get("items"), list) else []
    if len(items) != 1:
        raise RuntimeError(f"YouTube video lookup returned {len(items)} result(s) for {video_id}.")
    item = items[0]
    stats = item.get("statistics") if isinstance(item.get("statistics"), dict) else {}
    snippet = item.get("snippet") if isinstance(item.get("snippet"), dict) else {}
    metrics = {
        "views": numeric_metric(stats.get("viewCount")),
        "likes": numeric_metric(stats.get("likeCount")),
        "comments": numeric_metric(stats.get("commentCount")),
    }
    metrics["engagements"] = metrics["likes"] + metrics["comments"]
    metrics["engagementRate"] = round(metrics["engagements"] / metrics["views"], 4) if metrics["views"] else 0.0
    return {
        "platform": "youtube",
        "videoId": video_id,
        "watchUrl": f"https://www.youtube.com/watch?v={video_id}",
        "title": str(snippet.get("title") or ""),
        "publishedAt": str(snippet.get("publishedAt") or ""),
        "metrics": metrics,
        "raw": item,
    }


def parse_youtube_duration_seconds(value: str) -> int:
    text = str(value or "").strip()
    match = re.fullmatch(r"PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?", text)
    if not match:
        return 0
    hours = int(match.group(1) or 0)
    minutes = int(match.group(2) or 0)
    seconds = int(match.group(3) or 0)
    return hours * 3600 + minutes * 60 + seconds


def youtube_video_stats_bulk(video_ids: list[str]) -> list[dict[str, Any]]:
    clean_ids: list[str] = []
    for value in video_ids:
        video_id = youtube_video_id_from_value(value)
        if video_id and video_id not in clean_ids:
            clean_ids.append(video_id)
    if not clean_ids:
        return []
    results: list[dict[str, Any]] = []
    for index in range(0, len(clean_ids), 50):
        batch = clean_ids[index:index + 50]
        data = youtube_data_api_request("videos", {"part": "snippet,statistics,contentDetails,status", "id": ",".join(batch)})
        for item in data.get("items", []) if isinstance(data.get("items"), list) else []:
            stats = item.get("statistics") if isinstance(item.get("statistics"), dict) else {}
            snippet = item.get("snippet") if isinstance(item.get("snippet"), dict) else {}
            details = item.get("contentDetails") if isinstance(item.get("contentDetails"), dict) else {}
            video_id = str(item.get("id") or "")
            metrics = {
                "views": numeric_metric(stats.get("viewCount")),
                "likes": numeric_metric(stats.get("likeCount")),
                "comments": numeric_metric(stats.get("commentCount")),
            }
            metrics["engagements"] = metrics["likes"] + metrics["comments"]
            metrics["engagementRate"] = round(metrics["engagements"] / metrics["views"], 4) if metrics["views"] else 0.0
            duration_seconds = parse_youtube_duration_seconds(str(details.get("duration") or ""))
            results.append({
                "platform": "youtube",
                "videoId": video_id,
                "watchUrl": f"https://www.youtube.com/watch?v={video_id}",
                "title": str(snippet.get("title") or ""),
                "description": str(snippet.get("description") or ""),
                "channelId": str(snippet.get("channelId") or ""),
                "channelTitle": str(snippet.get("channelTitle") or ""),
                "publishedAt": str(snippet.get("publishedAt") or ""),
                "durationSeconds": duration_seconds,
                "durationBucket": youtube_duration_bucket(duration_seconds),
                "metrics": metrics,
                "raw": item,
            })
    return results


def load_youtube_end_screen_state() -> dict[str, Any]:
    data = rsr.load(ROOT, "youtubeEndScreenState", default={})
    return data if isinstance(data, dict) else {"schemaVersion": 1, "videos": {}}


def youtube_videos_with_end_screens() -> set[str]:
    data = load_youtube_end_screen_state()
    videos = data.get("videos") if isinstance(data.get("videos"), dict) else {}
    return {
        str(video_id)
        for video_id, item in videos.items()
        if re.fullmatch(r"[A-Za-z0-9_-]{11}", str(video_id))
        and isinstance(item, dict)
        and str(item.get("status") or "").lower() in {"applied", "done", "verified"}
    }


def youtube_subscriber_conversion_plan(limit: int = 30) -> dict[str, Any]:
    verified_pinned = verified_pinned_video_ids()
    end_screened = youtube_videos_with_end_screens()
    ids = youtube_video_ids_for_metrics(max(10, min(50, int(limit or 30))))
    videos: list[dict[str, Any]] = []
    errors: list[str] = []
    channel: dict[str, Any] = {}
    if youtube_data_api_configured():
        try:
            channel = youtube_channel_stats()
        except Exception as exc:
            errors.append(f"channel: {exc}")
        try:
            videos = youtube_video_stats_bulk(ids[:50])
        except Exception as exc:
            errors.append(f"videos: {exc}")
    else:
        errors.append("YOUTUBE_DATA_API_KEY is not configured.")
    targets: list[dict[str, Any]] = []
    for video in videos:
        video_id = str(video.get("videoId") or "")
        metrics = video.get("metrics") if isinstance(video.get("metrics"), dict) else {}
        views = numeric_metric(metrics.get("views"))
        engagement_rate = numeric_metric(metrics.get("engagementRate"))
        duration_bucket = str(video.get("durationBucket") or "")
        title = str(video.get("title") or "")
        description = str(video.get("description") or "")
        has_subscribe_text = "subscribe" in f"{title}\n{description}".lower()
        has_pinned = video_id in verified_pinned
        has_end_screen = video_id in end_screened
        missing = []
        if not has_subscribe_text:
            missing.append("subscribe wording in title/description")
        if not has_pinned:
            missing.append("pinned subscriber comment")
        if duration_bucket != "short_under_60" and not has_end_screen:
            missing.append("end screen")
        opportunity = views
        if not has_pinned:
            opportunity += views * 0.35
        if not has_subscribe_text:
            opportunity += views * 0.25
        if duration_bucket != "short_under_60" and not has_end_screen:
            opportunity += views * 0.4
        if engagement_rate >= 0.04:
            opportunity += views * 0.2
        if missing:
            targets.append(
                {
                    "videoId": video_id,
                    "title": title,
                    "watchUrl": video.get("watchUrl"),
                    "views": int(views),
                    "engagementRate": engagement_rate,
                    "durationBucket": duration_bucket,
                    "missing": missing,
                    "subscriberOpportunityScore": round(opportunity, 2),
                    "recommendedAction": "Add pinned comment and end screen, then refresh metadata CTA." if duration_bucket != "short_under_60" else "Add/verify pinned comment and stronger Shorts description CTA.",
                }
            )
    targets = sorted(targets, key=lambda item: item["subscriberOpportunityScore"], reverse=True)
    subscribers = numeric_metric((channel.get("metrics") or {}).get("subscribers") if isinstance(channel.get("metrics"), dict) else 0)
    views_total = numeric_metric((channel.get("metrics") or {}).get("views") if isinstance(channel.get("metrics"), dict) else 0)
    return {
        "generatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "configured": youtube_data_api_configured(),
        "channel": {key: value for key, value in channel.items() if key != "raw"},
        "subscribers": subscribers,
        "channelViews": views_total,
        "viewsPerSubscriber": round(views_total / subscribers, 2) if subscribers else 0,
        "videosChecked": len(videos),
        "targets": targets[: max(1, min(30, int(limit or 30)))],
        "errors": errors,
        "rules": [
            "Every full video needs a subscribe CTA in description text.",
            "Every eligible full video needs an end screen with subscribe and next-video path.",
            "Every video should have a pinned comment that asks for a reply and points to the next chapter/reading path.",
            "Videos with views but missing conversion assets get fixed first.",
        ],
    }


def youtube_search_public_videos(query: str, max_results: int = 8, channel_id: str = "", order: str = "viewCount") -> list[str]:
    params = {
        "part": "snippet",
        "type": "video",
        "q": str(query or "").strip(),
        "maxResults": max(1, min(25, int(max_results or 8))),
        "order": order,
        "safeSearch": "none",
    }
    if channel_id:
        params["channelId"] = str(channel_id).strip()
        params["order"] = "date"
        params.pop("q", None)
    data = youtube_data_api_request("search", params)
    ids: list[str] = []
    for item in data.get("items", []) if isinstance(data.get("items"), list) else []:
        id_data = item.get("id") if isinstance(item.get("id"), dict) else {}
        video_id = youtube_video_id_from_value(id_data.get("videoId"))
        if video_id and video_id not in ids:
            ids.append(video_id)
    return ids


def youtube_duration_bucket(seconds: int) -> str:
    seconds = int(seconds or 0)
    if seconds <= 0:
        return "unknown"
    if seconds < 60:
        return "short_under_60"
    if seconds <= 90:
        return "deep_short_60_90"
    if seconds < 8 * 60:
        return "mid_form"
    return "long_form"


