def update_conversion_tracking(results: list[dict[str, Any]]) -> dict[str, Any]:
    data = _phase2_load_blob("conversionTracking", CONVERSION_TRACKING_FILE)
    if not isinstance(data, dict):
        data = {"schemaVersion": 1, "snapshots": [], "platforms": {}}
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    snapshot = {"capturedAt": now, "platforms": {}}
    for item in results:
        platform = str(item.get("platform") or "unknown")
        metrics = item.get("metrics") if isinstance(item.get("metrics"), dict) else {}
        if not metrics:
            continue
        previous = data.get("platforms", {}).get(platform, {}).get("metrics", {})
        deltas = {}
        for key, value in metrics.items():
            try:
                deltas[key] = round(float(value) - float(previous.get(key) or 0), 4)
            except (TypeError, ValueError):
                continue
        snapshot["platforms"][platform] = {"metrics": metrics, "deltas": deltas}
        data.setdefault("platforms", {})[platform] = {"metrics": metrics, "deltas": deltas, "updatedAt": now}
    if snapshot["platforms"]:
        data.setdefault("snapshots", []).append(snapshot)
        data["snapshots"] = data["snapshots"][-90:]
    data["updatedAt"] = now
    _phase2_save_blob("conversionTracking", CONVERSION_TRACKING_FILE, data)
    return data


def chapter_performance_rows() -> list[dict[str, Any]]:
    store = load_content_experiments()
    rows = []
    for experiment in store.get("experiments", []):
        variants = [item for item in experiment.get("variants", []) if item.get("score") is not None]
        if not variants:
            continue
        score = sum(float(item.get("score") or 0) for item in variants) / len(variants)
        views = []
        for variant in variants:
            for metrics in (variant.get("metricsByPlatform") or {}).values():
                if isinstance(metrics, dict) and metrics.get("views") is not None:
                    views.append(float(metrics.get("views") or 0))
        rows.append(
            {
                "experimentId": experiment.get("experimentId"),
                "abbr": story_key(str(experiment.get("abbr") or "")),
                "novel": experiment.get("novel"),
                "chapter": experiment.get("chapter"),
                "title": experiment.get("title"),
                "score": round(score, 4),
                "views": round(sum(views) / len(views), 2) if views else None,
                "lastUsedAt": max([str(item.get("lastUsedAt") or "") for item in variants] or [str(experiment.get("createdAt") or "")]),
                "bestVariant": max(variants, key=lambda item: float(item.get("score") or 0)),
            }
        )
    return rows


def load_growth_automation_state() -> dict[str, Any]:
    data = read_json_safe(GROWTH_AUTOMATION_FILE)
    if not isinstance(data, dict):
        data = {"schemaVersion": 1, "resurfaced": {}}
    data.setdefault("resurfaced", {})
    return data


def save_growth_automation_state(data: dict[str, Any]) -> None:
    data["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    write_json_atomic(GROWTH_AUTOMATION_FILE, data)


def resurfacing_and_repost_candidates() -> dict[str, Any]:
    rows = chapter_performance_rows()
    state = load_growth_automation_state()
    view_values = sorted([float(item["views"]) for item in rows if item.get("views") is not None])
    score_values = sorted([float(item["score"]) for item in rows])
    median_views = view_values[len(view_values) // 2] if view_values else None
    median_score = score_values[len(score_values) // 2] if score_values else None
    weak = []
    strong = []
    now = datetime.now()
    for row in rows:
        used_at = experiment_timestamp(row.get("lastUsedAt"))
        age_days = (now - used_at).days if used_at else 0
        item = {**row, "ageDays": age_days}
        previous = state.get("resurfaced", {}).get(f"{row.get('abbr')}-{row.get('chapter')}", {})
        previous_at = experiment_timestamp(previous.get("builtAt")) if isinstance(previous, dict) else None
        if previous_at and now - previous_at < timedelta(days=30):
            continue
        if 30 <= age_days <= 45 and median_views is not None and row.get("views") is not None and float(row["views"]) < median_views:
            item["reason"] = "Below median reach and outside the 30-day cooldown."
            weak.append(item)
        if 30 <= age_days <= 90 and median_score is not None and float(row["score"]) >= median_score:
            item["reason"] = "Above median score and outside the repost cooldown."
            strong.append(item)
    return {
        "generatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "medianViews": median_views,
        "medianScore": median_score,
        "backCatalog": sorted(weak, key=lambda item: (item.get("views") or 0, -item["ageDays"])),
        "reposts": sorted(strong, key=lambda item: (-float(item.get("score") or 0), -item["ageDays"])),
    }


def build_resurfacing_post(abbr: str, chapter: int | str, reason: str = "back_catalog") -> dict[str, Any]:
    abbr = story_key(abbr)
    chapter_number = int(chapter)
    data = docs_chapter_text(abbr, chapter_number)
    title = str(data.get("title") or f"Chapter {chapter_number}")
    text = str(data.get("text") or data.get("raw_text") or "")
    hook = compact_chapter_hook(title, text, story=abbr)
    folder = SOCIAL_OUTPUT_DIR / f"resurface-{abbr.lower()}-{chapter_number}-{time.strftime('%Y%m%d')}"
    reset_generated_folder(folder)
    material = {"abbr": abbr, "novel": NOVEL_NAMES.get(abbr, abbr), "chapter": str(chapter_number), "phrases": [hook]}
    # Optional Hermes agent post copy (dynamic, research-aware). Default OFF.
    # Flip ENABLE_AGENT_POSTS=1 to replace template prose with agent-generated copy.
    # Any failure returns None -> build_platform_posts uses the template engine (fail-soft).
    agent_copy = None
    if str(os.environ.get("ENABLE_AGENT_POSTS", "0")).strip().lower() not in {"", "0", "false", "no", "off"} and abbr:
        try:
            from tools.agent_post_writer import generate_post_copy as _agent_gen
            _agent_hook = " ".join(str(p) for p in material.get("phrases", [])[:3]).strip()
            agent_copy = _agent_gen(
                abbr,
                title,
                str(material.get("chapter", chapter_number) or chapter_number),
                _agent_hook,
                material,
            )
        except Exception as _agent_exc:  # never let the agent block a post build
            agent_copy = None
            material.setdefault("warnings", []).append(
                f"agent_post_writer skipped: {_agent_exc}"
            )
    copy = build_platform_posts(title, text, material, "catch_up_archive", agent_copy=agent_copy)
    image = folder / f"{abbr}_{chapter_number}_resurface.png"
    image_source = create_fresh_social_image_from_caption(
        image,
        abbr=abbr,
        novel=NOVEL_NAMES.get(abbr, abbr),
        title=title,
        caption=copy["caption"],
        hook=hook,
        index=chapter_number,
    )
    payload = {
        "kind": "resurfacing_post",
        "reason": reason,
        "abbr": abbr,
        "novel": NOVEL_NAMES.get(abbr, abbr),
        "chapter": chapter_number,
        "title": title,
        "hook": hook,
        "folder": str(folder),
        "image": str(image),
        "image_source": image_source,
        "instagram": copy["caption"],
        "x": copy["x_post"],
        "facebook": copy["facebook_post"],
        "createdAt": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    (folder / "instagram.txt").write_text(payload["instagram"] + "\n", encoding="utf-8")
    (folder / "x.txt").write_text(payload["x"] + "\n", encoding="utf-8")
    (folder / "facebook.txt").write_text(payload["facebook"] + "\n", encoding="utf-8")
    (folder / "metadata.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")
    published = auto_publish_generated_media(folder, payload)
    state = load_growth_automation_state()
    state.setdefault("resurfaced", {})[f"{abbr}-{chapter_number}"] = {
        "builtAt": payload["createdAt"],
        "folder": str(folder),
        "reason": reason,
    }
    save_growth_automation_state(state)
    return published


def pinned_content_plan() -> dict[str, Any]:
    store = load_content_experiments()
    best = []
    for experiment in store.get("experiments", []):
        abbr = story_key(str(experiment.get("abbr") or ""))
        for variant in experiment.get("variants", []):
            if variant.get("score") is None or variant.get("status") == "retired":
                continue
            best.append({"experiment": experiment, "variant": variant, "abbr": abbr, "score": numeric_metric(variant.get("score"))})
    best.sort(key=lambda item: item["score"], reverse=True)
    strongest = best[0] if best else None
    start_abbr = story_key(str(strongest["abbr"] or "")) if strongest else "EN"
    start_destination = royal_road_url_for_story(start_abbr) or next(iter(ROYAL_ROAD_URLS.values()))
    profiles = {}
    for platform in ["tiktok", "instagram", "youtube", "x", "facebook"]:
        platform_candidates = platform_pinned_candidates(platform)
        selected: list[dict[str, Any]] = []
        seen_sources: set[str] = set()
        for candidate in platform_candidates:
            source = str(candidate.get("source") or candidate.get("title") or "")
            if source in seen_sources:
                continue
            seen_sources.add(source)
            selected.append(candidate)
            if len(selected) >= 3:
                break
        if len(selected) < 3:
            for candidate in platform_pinned_candidates("all"):
                source = str(candidate.get("source") or candidate.get("title") or "")
                if source in seen_sources:
                    continue
                candidate = {**candidate, "reason": f"Diversity fallback: not enough unique {platform.title()} measured pins yet. {candidate.get('reason') or ''}".strip()}
                seen_sources.add(source)
                selected.append(candidate)
                if len(selected) >= 3:
                    break
        if len(selected) < 3:
            used_abbrs = {story_key(str(item.get("abbr") or "")) for item in selected}
            for fallback_abbr, fallback_novel in NOVEL_NAMES.items():
                if fallback_abbr in used_abbrs and len(used_abbrs) < len(NOVEL_NAMES):
                    continue
                source = f"fallback-{platform}-{fallback_abbr}-{len(selected) + 1}"
                selected.append(
                    {
                        "type": "start_here",
                        "title": f"Start reading {fallback_novel}",
                        "abbr": fallback_abbr,
                        "novel": fallback_novel,
                        "chapter": "",
                        "source": source,
                        "experimentId": "",
                        "score": 0,
                        "variantScore": None,
                        "views": 0,
                        "follows": 0,
                        "destination": royal_road_url_for_story(fallback_abbr) or PATREON_URL,
                        "hook": f"Start {fallback_novel} from the beginning.",
                        "reason": f"Novel-diversity fallback until {platform.title()} has more measured high-performing posts.",
                        "hasPlatformMetrics": False,
                    }
                )
                used_abbrs.add(fallback_abbr)
                if len(selected) >= 3:
                    break
        if selected:
            start_candidate = selected[0]
            start_pin = {
                **start_candidate,
                "type": "start_here_growth",
                "title": f"Start reading {start_candidate.get('novel') or NOVEL_NAMES.get(start_abbr, 'Azure Inkblade')}",
                "reason": f"Start-here slot follows the highest current {platform.title()} growth candidate.",
                "destination": royal_road_url_for_story(str(start_candidate.get("abbr") or "")) or start_destination,
            }
            teaser_pin = {
                **(selected[1] if len(selected) > 1 else selected[0]),
                "type": "strongest_teaser",
                "reason": (selected[1] if len(selected) > 1 else selected[0]).get("reason") or "Strongest measured teaser candidate.",
            }
            support_source = selected[2] if len(selected) > 2 else selected[0]
            support_pin = {
                **support_source,
                "type": "support_and_listen",
                "title": "Read ahead on Patreon or listen on YouTube",
                "destination": f"{PATREON_URL} | {YOUTUBE_SOCIAL_URL}",
                "reason": f"Support/listen slot uses the current {platform.title()} winner as the creative angle.",
            }
            profiles[platform] = [start_pin, teaser_pin, support_pin]
        else:
            teaser = {
                "type": "strongest_teaser",
                "title": str(strongest["experiment"].get("title") or "Strongest chapter teaser") if strongest else "Strongest measured chapter teaser",
                "source": str(strongest["variant"].get("variantId") or "") if strongest else "waiting_for_metrics",
                "score": strongest["variant"].get("score") if strongest else None,
                "reason": "Fallback until this platform has measured post performance.",
            }
            profiles[platform] = [
                {"type": "start_here", "title": f"Start reading {NOVEL_NAMES.get(start_abbr, 'Azure Inkblade')}", "destination": start_destination, "reason": "Fallback start-here pin."},
                teaser,
                {"type": "support_and_listen", "title": "Read ahead on Patreon or listen on YouTube", "destination": f"{PATREON_URL} | {YOUTUBE_SOCIAL_URL}", "reason": "Fallback support pin."},
            ]
    result = {
        "generatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "profiles": profiles,
        "rotationRule": "Each platform chooses pinned profile posts from measured candidates for that platform, weighted by views, follower gains, engagement, completion, and experiment score.",
        "file": None,
        "storage": "sqlite",
        "resource": "state_snapshots",
        "state_key": "pinnedContentPlan",
    }
    rsr.save(ROOT, "pinnedContentPlan", result)
    return result


def comment_content_ideas() -> list[dict[str, Any]]:
    ideas = []
    for item in comment_assistant_status().get("comments", []):
        if item.get("itemType") == "message":
            continue
        if int(item.get("priority") or 0) < 5 or item.get("status") == "dismissed":
            continue
        ideas.append(
            {
                "ideaId": f"comment-{item.get('commentId')}",
                "commentId": item.get("commentId"),
                "platform": item.get("platform"),
                "abbr": item.get("abbr"),
                "novel": item.get("novel"),
                "hook": clean_teaser_text(str(item.get("text") or ""), 140, max_words=22),
                "format": "reader_question" if "?" in str(item.get("text") or "") else "reader_reaction",
                "status": "needs_approval",
            }
        )
    return ideas[:20]


def build_comment_content_post(comment_id: str) -> dict[str, Any]:
    comment = next((item for item in load_comment_assistant().get("comments", []) if str(item.get("commentId")) == str(comment_id)), None)
    if not comment:
        raise RuntimeError("Comment was not found.")
    abbr = story_key(str(comment.get("abbr") or ""))
    novel = NOVEL_NAMES.get(abbr, "Azure Inkblade")
    hook = clean_teaser_text(str(comment.get("text") or ""), 150, max_words=24)
    folder = SOCIAL_OUTPUT_DIR / f"comment-content-{(abbr or 'azureinkblade').lower()}-{str(comment_id)[:10]}"
    reset_generated_folder(folder)
    prompt = f"Reader question inspired social artwork for {novel}: {hook}. No text or typography."
    image = folder / f"{abbr or 'AzureInkblade'}_reader_question.png"
    source = create_fresh_social_image_from_caption(image, abbr=abbr, novel=novel, title="Reader Question", caption=hook, hook=hook, visual_brief=prompt)
    links = "Find the story and all reader links in bio."
    instagram = f"Reader question: {hook}\n\nWhat do you think?\n\n{links}\n\n{social_profile(abbr)['hashtags']}"
    x_destination = "Read now: link in bio."
    x_text = f"Reader question: {hook}\n{x_destination}\n#AzureInkblade"
    if len(x_text) > 275:
        x_text = f"{hook[:100]}\n{x_destination}"
    facebook = f"Reader question about {novel}:\n\n{hook}\n\nWhat is your theory?\n\n{links}"
    payload = {"kind": "comment_content", "commentId": comment_id, "abbr": abbr, "novel": novel, "folder": str(folder), "image": str(image), "image_source": source, "instagram": instagram, "x": x_text, "facebook": facebook, "createdAt": time.strftime("%Y-%m-%d %H:%M:%S")}
    for name, value in [("instagram.txt", instagram), ("x.txt", x_text), ("facebook.txt", facebook)]:
        (folder / name).write_text(value + "\n", encoding="utf-8")
    (folder / "metadata.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")
    return auto_publish_generated_media(folder, payload)


def variant_platform_metrics(variant: dict[str, Any], platform: str) -> dict[str, Any]:
    platform = str(platform or "").lower()
    metrics_by_platform = variant.get("metricsByPlatform") if isinstance(variant.get("metricsByPlatform"), dict) else {}
    for key, metrics in metrics_by_platform.items():
        if str(key or "").lower() == platform and isinstance(metrics, dict):
            return metrics
    metrics = variant.get("metrics") if isinstance(variant.get("metrics"), dict) else {}
    return metrics


def pinned_growth_score(metrics: dict[str, Any], variant: dict[str, Any]) -> float:
    views = numeric_metric(metrics.get("views") or metrics.get("reach") or metrics.get("impressions"))
    follows = numeric_metric(metrics.get("follows") or metrics.get("followsProduced") or metrics.get("followers_gained"))
    saves = numeric_metric(metrics.get("saves"))
    shares = numeric_metric(metrics.get("shares"))
    comments = numeric_metric(metrics.get("comments"))
    completion = metric_rate(metrics.get("completion_rate") or metrics.get("completionRate") or metrics.get("average_watch_percentage") or metrics.get("averageWatchPercentage"), views)
    base_score = numeric_metric(variant.get("score"))
    view_signal = math.log10(max(0.0, views) + 1.0)
    follow_signal = follows * 2.5 if follows else 0.0
    engagement_signal = shares * 0.9 + saves * 0.7 + comments * 0.25
    return round(base_score * 35 + view_signal * 18 + completion * 25 + follow_signal + engagement_signal, 4)


def platform_pinned_candidates(platform: str) -> list[dict[str, Any]]:
    platform = str(platform or "").lower()
    store = load_content_experiments()
    candidates: list[dict[str, Any]] = []
    for experiment in store.get("experiments", []):
        abbr = story_key(str(experiment.get("abbr") or ""))
        if not abbr:
            continue
        for variant in experiment.get("variants", []):
            if variant.get("status") == "retired":
                continue
            metrics = variant_platform_metrics(variant, platform)
            has_platform_metrics = bool(metrics)
            if not has_platform_metrics and platform in {"facebook", "x"}:
                metrics = variant_platform_metrics(variant, "instagram")
            if not metrics and variant.get("score") is None:
                continue
            score = pinned_growth_score(metrics, variant)
            if score <= 0:
                continue
            title = str(experiment.get("title") or f"{NOVEL_NAMES.get(abbr, abbr)} Chapter {experiment.get('chapter') or ''}").strip()
            opening = str(variant.get("openingText") or variant.get("caption") or variant.get("hook") or title)
            views = numeric_metric(metrics.get("views") or metrics.get("reach") or metrics.get("impressions"))
            follows = numeric_metric(metrics.get("follows") or metrics.get("followsProduced") or metrics.get("followers_gained"))
            candidates.append(
                {
                    "type": "growth_rotation",
                    "title": title,
                    "abbr": abbr,
                    "novel": NOVEL_NAMES.get(abbr, abbr),
                    "chapter": experiment.get("chapter"),
                    "source": str(variant.get("variantId") or ""),
                    "experimentId": str(experiment.get("experimentId") or ""),
                    "score": score,
                    "variantScore": variant.get("score"),
                    "views": int(views) if views else 0,
                    "follows": int(follows) if follows else 0,
                    "destination": royal_road_url_for_story(abbr) or PATREON_URL,
                    "hook": clean_teaser_text(opening, 130, max_words=20),
                    "reason": (
                        f"{platform.title()} measured candidate: {int(views) if views else 0} views"
                        + (f", {int(follows)} follows" if follows else "")
                        + f", rotation score {score}."
                    ),
                    "hasPlatformMetrics": has_platform_metrics,
                }
            )
    candidates.sort(key=lambda item: (numeric_metric(item.get("score")), numeric_metric(item.get("views"))), reverse=True)
    return candidates


def arc_campaign_plans(build_drafts: bool = False, only_abbr: str = "") -> dict[str, Any]:
    plans = []
    drafts = []
    for abbr, novel in NOVEL_NAMES.items():
        if only_abbr and abbr != story_key(only_abbr):
            continue
        continuity = load_continuity_snapshot(abbr)
        arc = str(continuity.get("current_arc") or "Current Story Arc").strip()
        setup = str(continuity.get("next_chapter_setup") or continuity.get("last_chapter_summary") or "The next major confrontation is taking shape.").strip()
        plan = {"abbr": abbr, "novel": novel, "arc": arc, "hook": clean_teaser_text(setup, 160, max_words=24), "destination": royal_road_url_for_story(abbr)}
        plans.append(plan)
        if build_drafts:
            folder = SOCIAL_OUTPUT_DIR / f"arc-{abbr.lower()}-{slugify(arc)[:35]}"
            reset_generated_folder(folder)
            image = folder / f"{abbr}_arc.png"
            source = create_fresh_social_image_from_caption(image, abbr=abbr, novel=novel, title=arc, caption=plan["hook"], hook=plan["hook"])
            links = "Start the arc through the link in bio."
            instagram = f"{novel}: {arc}\n\n{plan['hook']}\n\nStart the arc on Royal Road.\n\n{links}\n\n{social_profile(abbr)['hashtags']}"
            payload = {**plan, "kind": "arc_campaign", "folder": str(folder), "image": str(image), "image_source": source, "instagram": instagram, "x": f"{novel}: {arc}\n{plan['hook']}\nRead now: link in bio.", "facebook": instagram, "createdAt": time.strftime("%Y-%m-%d %H:%M:%S")}
            for name, value in [("instagram.txt", payload["instagram"]), ("x.txt", payload["x"]), ("facebook.txt", payload["facebook"])]:
                (folder / name).write_text(value + "\n", encoding="utf-8")
            (folder / "metadata.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")
            drafts.append(auto_publish_generated_media(folder, payload))
    result = {"generatedAt": time.strftime("%Y-%m-%d %H:%M:%S"), "plans": plans, "drafts": drafts, "file": str(ARC_CAMPAIGN_FILE)}
    _phase2_save_blob("arcCampaigns", ARC_CAMPAIGN_FILE, result)
    return result


def profile_conversion_audit() -> dict[str, Any]:
    raw = _phase2_load_blob("metricsGatherResults", METRICS_GATHER_FILE)
    gathered = {str(item.get("platform") or ""): str(item.get("textSample") or "") for item in (raw or {}).get("results", [])} if isinstance(raw, dict) else {}
    audits = []
    for platform in ["tiktok", "instagram", "youtube", "x", "facebook", "patreon", "royalroad"]:
        text = gathered.get(platform, "").lower()
        checks = {
            "profileInspected": bool(text),
            "azureInkbladeNamed": "azure" in text and "inkblade" in text,
            "royalRoadMentioned": "royal road" in text or "royalroad" in text,
            "patreonMentioned": "patreon" in text,
            "youtubeMentioned": "youtube" in text,
        }
        missing = [key for key, value in checks.items() if not value]
        audits.append({"platform": platform, "checks": checks, "missing": missing, "status": "review_needed" if missing else "complete"})
    result = {"generatedAt": time.strftime("%Y-%m-%d %H:%M:%S"), "audits": audits, "file": str(PROFILE_AUDIT_FILE), "note": "Browser text checks are approximate and never edit profiles automatically."}
    _phase2_save_blob("profileConversionAudit", PROFILE_AUDIT_FILE, result)
    return result


