def pinned_profile_asset_plan() -> dict[str, Any]:
    pinned = pinned_content_plan()
    existing = rsr.load(ROOT, "pinnedProfileAssets", default={})
    existing_by_id = {
        str(item.get("id") or ""): item
        for item in (existing.get("prompts", []) if isinstance(existing, dict) and isinstance(existing.get("prompts"), list) else [])
        if item.get("id")
    }
    platform_urls = {
        "tiktok": TIKTOK_URL,
        "instagram": INSTAGRAM_URL,
        "youtube": YOUTUBE_SOCIAL_URL,
        "x": X_URL,
        "facebook": "https://www.facebook.com/",
        "patreon": PATREON_URL,
        "royalroad": "https://www.royalroad.com/author-dashboard",
    }
    prompts = []
    for platform, items in (pinned.get("profiles") or {}).items():
        for index, item in enumerate(items[:3], start=1):
            title = str(item.get("title") or "")
            asset_id = content_hash(f"{platform}|{index}|{title}|{item.get('source') or item.get('type') or ''}")
            existing_item = existing_by_id.get(asset_id, {})
            output_folder = PINNED_ASSET_OUTPUT_DIR / asset_id
            image_path = output_folder / "pinned-asset.png"
            prompts.append(
                {
                    **{key: value for key, value in existing_item.items() if key in {"status", "plannedAt", "appliedAt", "skippedAt", "builtAt", "folder", "image", "captionFile", "instructionsFile", "public_image_url", "public_media_urls", "github_media_publish", "pinHelperAt", "pinHelperStatus", "pinHelperScript", "pinHelperLaunched", "pinAutomationLevel", "pinAutomationNote"}},
                    "id": asset_id,
                    "platform": platform,
                    "slot": index,
                    "title": title,
                    "url": platform_urls.get(platform, ""),
                    "destination": str(item.get("destination") or ""),
                    "assetType": str(item.get("type") or ""),
                    "rotationScore": item.get("score"),
                    "views": item.get("views", 0),
                    "follows": item.get("follows", 0),
                    "reason": str(item.get("reason") or ""),
                    "source": str(item.get("source") or ""),
                    "prompt": f"Azure Inkblade branded social graphic for {platform}: {title}. Dark cinematic web novel brand, high contrast, clean title area, no small text.",
                    "folder": str(existing_item.get("folder") or (str(output_folder) if image_path.exists() else "")),
                    "image": str(existing_item.get("image") or (str(image_path) if image_path.exists() else "")),
                    "captionFile": str(existing_item.get("captionFile") or ""),
                    "instructionsFile": str(existing_item.get("instructionsFile") or ""),
                    **pinned_asset_pin_capability(platform),
                    "quota": "Local branded image. Building this asset does not use OpenAI image quota.",
                }
            )
    payload = {"generatedAt": time.strftime("%Y-%m-%d %H:%M:%S"), "prompts": prompts, "pinned": pinned}
    rsr.save(ROOT, "pinnedProfileAssets", payload)
    return {
        **payload,
        "file": None,
        "storage": "sqlite",
        "resource": "state_snapshots",
        "state_key": "pinnedProfileAssets",
    }


def pinned_asset_platform_size(platform: str) -> tuple[int, int]:
    platform = str(platform or "").lower()
    if platform in {"tiktok", "instagram"}:
        return (1080, 1920)
    if platform == "youtube":
        return (1280, 720)
    if platform == "x":
        return (1600, 900)
    if platform == "facebook":
        return (1200, 1500)
    return (1200, 1200)


def pinned_asset_caption(asset: dict[str, Any]) -> str:
    platform = str(asset.get("platform") or "").lower()
    title = str(asset.get("title") or "Start reading Azure Inkblade").strip()
    destination = str(asset.get("destination") or "").strip()
    if "patreon.com" in destination and "youtube.com" in destination:
        base = "Read ahead on Patreon or listen to full chapter narrations on YouTube."
    elif "patreon.com" in destination:
        base = "Read ahead with early access chapters on Patreon."
    elif "youtube.com" in destination:
        base = "Listen to full chapter narrations and story hooks on YouTube."
    else:
        base = title
    if platform == "x":
        text = f"{base}\nRead now: link in bio.\n#AzureInkblade"
        return text[:275]
    if platform == "youtube":
        return f"{base}\n\nStart here through the link in bio.\n\nWhich series should get the next spotlight?"
    return f"{base}\n\nStart here through the link in bio.\n\n#AzureInkblade #RoyalRoadFantasy #WebNovelCommunity #ProgressionFantasy"


def draw_centered_wrapped_text(draw: Any, box: tuple[int, int, int, int], text: str, font: Any, fill: tuple[int, int, int], spacing: int = 12) -> None:
    left, top, right, bottom = box
    width = right - left
    words = text.split()
    lines: list[str] = []
    current = ""
    for word in words:
        candidate = f"{current} {word}".strip()
        bbox = draw.textbbox((0, 0), candidate, font=font)
        if bbox[2] - bbox[0] <= width or not current:
            current = candidate
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    line_heights = [draw.textbbox((0, 0), line, font=font)[3] - draw.textbbox((0, 0), line, font=font)[1] for line in lines]
    total_height = sum(line_heights) + spacing * max(0, len(lines) - 1)
    y = top + max(0, (bottom - top - total_height) // 2)
    for line, height in zip(lines, line_heights):
        bbox = draw.textbbox((0, 0), line, font=font)
        x = left + max(0, (width - (bbox[2] - bbox[0])) // 2)
        draw.text((x, y), line, font=font, fill=fill)
        y += height + spacing


def create_pinned_asset_image(asset: dict[str, Any], target: Path) -> None:
    from PIL import Image, ImageDraw, ImageFont

    platform = str(asset.get("platform") or "")
    width, height = pinned_asset_platform_size(platform)
    target.parent.mkdir(parents=True, exist_ok=True)
    digest = hashlib.sha256(json.dumps(asset, sort_keys=True).encode("utf-8")).digest()
    palettes = [
        ((16, 23, 32), (35, 125, 135), (239, 204, 117)),
        ((23, 18, 34), (117, 74, 150), (242, 190, 94)),
        ((20, 31, 28), (73, 140, 112), (232, 217, 165)),
        ((34, 22, 20), (178, 80, 58), (240, 205, 134)),
    ]
    bg, accent, gold = palettes[digest[0] % len(palettes)]
    image = Image.new("RGB", (width, height), bg)
    draw = ImageDraw.Draw(image, "RGBA")
    for y in range(height):
        blend = y / max(1, height - 1)
        color = (
            int(bg[0] * (1 - blend) + max(0, bg[0] - 10) * blend),
            int(bg[1] * (1 - blend) + max(0, bg[1] - 12) * blend),
            int(bg[2] * (1 - blend) + max(0, bg[2] - 16) * blend),
        )
        draw.line((0, y, width, y), fill=(*color, 255))
    for i in range(10):
        x = int((digest[i] / 255) * width)
        y = int((digest[(i + 8) % len(digest)] / 255) * height)
        radius = int(min(width, height) * (0.12 + digest[(i + 16) % len(digest)] / 255 * 0.18))
        color = accent if i % 2 else gold
        draw.ellipse((x - radius, y - radius, x + radius, y + radius), fill=(*color, 22 + digest[(i + 3) % len(digest)] % 38))
    margin = int(width * 0.08)
    card_top = int(height * 0.20)
    card_bottom = int(height * 0.80)
    draw.rounded_rectangle((margin, card_top, width - margin, card_bottom), radius=max(22, width // 42), fill=(5, 8, 12, 205), outline=(*gold, 120), width=max(3, width // 260))
    font_path_bold = "C:/Windows/Fonts/bahnschrift.ttf"
    font_path = "C:/Windows/Fonts/segoeui.ttf"
    try:
        brand_font = ImageFont.truetype(font_path_bold, max(32, width // 32))
        title_font = ImageFont.truetype(font_path_bold, max(48, width // 15))
        small_font = ImageFont.truetype(font_path, max(28, width // 34))
    except OSError:
        brand_font = title_font = small_font = ImageFont.load_default()
    draw.text((margin, int(height * 0.07)), "AZURE INKBLADE", font=brand_font, fill=(*gold, 255))
    title = str(asset.get("title") or "Start Reading").upper()
    draw_centered_wrapped_text(draw, (margin + 45, card_top + 55, width - margin - 45, card_bottom - 115), title, title_font, (255, 255, 245), spacing=max(10, height // 130))
    destination = str(asset.get("destination") or "")
    cta = "START ON ROYAL ROAD" if "royalroad" in destination.lower() else "READ AHEAD / LISTEN NOW" if destination else "FOLLOW FOR MORE"
    cta_box = (margin + 70, card_bottom - 92, width - margin - 70, card_bottom - 35)
    draw.rounded_rectangle(cta_box, radius=18, fill=(*accent, 225))
    draw_centered_wrapped_text(draw, cta_box, cta, small_font, (255, 255, 255), spacing=4)
    footer = platform_display_name(platform)
    draw.text((margin, height - int(height * 0.08)), footer, font=small_font, fill=(220, 230, 230, 230))
    image.save(target)


def build_pinned_profile_asset(asset_id: str) -> dict[str, Any]:
    data = rsr.load(ROOT, "pinnedProfileAssets", default={})
    if not isinstance(data, dict) or not isinstance(data.get("prompts"), list):
        data = pinned_profile_asset_plan()
    asset = next((item for item in data.get("prompts", []) if str(item.get("id") or "") == str(asset_id)), None)
    if not asset:
        raise RuntimeError("Pinned asset was not found.")
    folder = PINNED_ASSET_OUTPUT_DIR / str(asset_id)
    folder.mkdir(parents=True, exist_ok=True)
    image = folder / "pinned-asset.png"
    create_pinned_asset_image(asset, image)
    caption = pinned_asset_caption(asset)
    instructions = "\n".join(
        [
            f"Platform: {platform_display_name(str(asset.get('platform') or ''))}",
            f"Profile slot: {asset.get('slot')}",
            f"Recommended use: {asset.get('assetType')}",
            "",
            "What to do:",
            "1. Post this image using the caption below.",
            "2. After it is live, pin it to the profile if the platform supports pinned posts.",
            "3. Mark this asset Applied in the Automation Tool.",
            "",
            f"Destination: {asset.get('destination') or ''}",
            "",
            "Caption:",
            caption,
        ]
    )
    (folder / "caption.txt").write_text(caption + "\n", encoding="utf-8")
    (folder / "instructions.txt").write_text(instructions + "\n", encoding="utf-8")
    payload = {**asset, "folder": str(folder), "image": str(image), "caption": caption, "captionFile": str(folder / "caption.txt"), "instructionsFile": str(folder / "instructions.txt"), "builtAt": time.strftime("%Y-%m-%d %H:%M:%S")}
    (folder / "metadata.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")
    payload = auto_publish_generated_media(folder, payload)
    asset.update(
        {
            "status": asset.get("status") or "built",
            "builtAt": payload["builtAt"],
            "folder": str(folder),
            "image": str(image),
            "captionFile": str(folder / "caption.txt"),
            "instructionsFile": str(folder / "instructions.txt"),
            "public_image_url": payload.get("public_image_url", ""),
            "public_media_urls": payload.get("public_media_urls", []),
            "github_media_publish": payload.get("github_media_publish", {}),
        }
    )
    data["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    rsr.save(ROOT, "pinnedProfileAssets", data)
    return {"ok": True, "asset": asset, "folder": str(folder), "image": str(image), "caption": caption, "instructions": instructions, "file": None, "storage": "sqlite", "resource": "state_snapshots", "state_key": "pinnedProfileAssets"}


def pinned_asset_pin_capability(platform: str) -> dict[str, str]:
    platform_key = str(platform or "").strip().lower()
    if platform_key == "x":
        return {
            "pinAutomationLevel": "best_effort",
            "pinAutomationNote": "Can prepare an X post with image and text in the helper browser. Final post/pin may still require confirmation if X changes the menu flow.",
        }
    if platform_key == "facebook":
        return {
            "pinAutomationLevel": "best_effort",
            "pinAutomationNote": "Can prepare a Facebook post with image and text in the helper browser. Pinning depends on the selected page/profile menu.",
        }
    if platform_key in {"instagram", "tiktok"}:
        return {
            "pinAutomationLevel": "limited",
            "pinAutomationNote": "Web upload/pin support is limited. The helper opens the upload/profile page and attaches the asset when the browser exposes a file picker.",
        }
    if platform_key == "youtube":
        return {
            "pinAutomationLevel": "manual_or_unsupported",
            "pinAutomationNote": "YouTube profile pinning/community posts may be unavailable on this channel. The helper opens Studio with the caption and asset ready.",
        }
    return {
        "pinAutomationLevel": "manual",
        "pinAutomationNote": "No reliable web pin flow is known for this platform yet.",
    }


def pinned_asset_pin_url(platform: str) -> str:
    platform_key = str(platform or "").strip().lower()
    if platform_key == "x":
        return "https://x.com/compose/post"
    if platform_key == "facebook":
        return "https://www.facebook.com/"
    if platform_key == "instagram":
        return "https://www.instagram.com/"
    if platform_key == "tiktok":
        return "https://www.tiktok.com/upload"
    if platform_key == "youtube":
        return "https://studio.youtube.com/"
    return ""


def write_pinned_asset_pin_playwright_script(asset: dict[str, Any], folder: Path, image: Path, caption_file: Path) -> Path:
    script = folder / "prepare-pinned-asset-playwright.js"
    debug_url = chrome_debug_url().rstrip("/")
    platform = str(asset.get("platform") or "").strip().lower()
    target_url = pinned_asset_pin_url(platform) or str(asset.get("url") or "")
    caption = caption_file.read_text(encoding="utf-8") if caption_file.exists() else pinned_asset_caption(asset)
    script.write_text(
        f"""const fs = require('fs');
const {{ chromium }} = require('playwright');

const chromeDebugUrl = {json.dumps(debug_url)};
const platform = {json.dumps(platform)};
const targetUrl = {json.dumps(target_url)};
const imagePath = {json.dumps(str(image))};
const captionText = {json.dumps(caption)};
const resultFile = 'pin-helper-result.json';
const runLog = [];

function record(event) {{
  runLog.push({{ at: new Date().toISOString(), platform, ...event }});
  try {{
    fs.writeFileSync(resultFile, JSON.stringify(runLog, null, 2), 'utf8');
  }} catch (_) {{}}
}}

async function firstVisible(locator) {{
  const count = await locator.count().catch(() => 0);
  for (let i = count - 1; i >= 0; i--) {{
    const item = locator.nth(i);
    if (await item.isVisible().catch(() => false)) return item;
  }}
  return null;
}}

async function fillText(page, text) {{
  const selectors = [
    '[data-testid="tweetTextarea_0"]',
    '[aria-label="Post text"]',
    'div[role="dialog"] div[role="textbox"][contenteditable="true"]',
    'div[role="textbox"][contenteditable="true"]',
    '[contenteditable="true"]',
    'textarea',
    '[role="textbox"]'
  ];
  for (const selector of selectors) {{
    const target = await firstVisible(page.locator(selector));
    if (!target) continue;
    try {{
      await target.click({{ timeout: 5000 }});
      try {{
        await target.fill(text, {{ timeout: 3000 }});
      }} catch (_) {{
        await page.keyboard.insertText(text);
      }}
      record({{ action: 'filled_text', selector }});
      return true;
    }} catch (error) {{
      record({{ action: 'fill_text_failed', selector, error: String(error.message || error).slice(0, 400) }});
    }}
  }}
  return false;
}}

async function attachImage(page, imagePath) {{
  const inputs = page.locator('input[type="file"]');
  const count = await inputs.count().catch(() => 0);
  for (let i = count - 1; i >= 0; i--) {{
    const input = inputs.nth(i);
    try {{
      await input.setInputFiles(imagePath);
      record({{ action: 'attached_image', index: i, imagePath }});
      return true;
    }} catch (error) {{
      record({{ action: 'attach_image_failed', index: i, error: String(error.message || error).slice(0, 400) }});
    }}
  }}

  const addMediaSelectors = [
    '[aria-label*="Add photos" i]',
    '[aria-label*="Photo/video" i]',
    '[aria-label*="Media" i]',
    '[data-testid="fileInput"]',
    'button:has-text("Photo/video")',
    'button:has-text("Photo")',
    'button:has-text("Upload")'
  ];
  for (const selector of addMediaSelectors) {{
    try {{
      const button = await firstVisible(page.locator(selector));
      if (!button) continue;
      await button.click({{ timeout: 4000 }});
      await page.waitForTimeout(1000);
      const afterClick = page.locator('input[type="file"]');
      const afterCount = await afterClick.count().catch(() => 0);
      if (afterCount) {{
        await afterClick.nth(afterCount - 1).setInputFiles(imagePath);
        record({{ action: 'attached_image_after_media_click', selector, imagePath }});
        return true;
      }}
    }} catch (error) {{
      record({{ action: 'media_click_failed', selector, error: String(error.message || error).slice(0, 400) }});
    }}
  }}
  return false;
}}

async function openFacebookComposer(page) {{
  if (platform !== 'facebook') return;
  const selectors = [
    '[aria-label*="Create a post" i]',
    '[aria-label*="What\\'s on your mind" i]',
    'div[role="button"]:has-text("What\\'s on your mind")',
    'span:has-text("What\\'s on your mind")',
    'button:has-text("Create post")'
  ];
  for (const selector of selectors) {{
    try {{
      const target = await firstVisible(page.locator(selector));
      if (!target) continue;
      await target.click({{ timeout: 4000 }});
      await page.waitForTimeout(1800);
      record({{ action: 'opened_facebook_composer', selector }});
      return;
    }} catch (error) {{
      record({{ action: 'facebook_composer_open_failed', selector, error: String(error.message || error).slice(0, 400) }});
    }}
  }}
}}

(async () => {{
  try {{
    const browser = await chromium.connectOverCDP(chromeDebugUrl);
    const context = browser.contexts()[0] || await browser.newContext();
    const page = await context.newPage();
    if (targetUrl) {{
      await page.goto(targetUrl, {{ waitUntil: 'domcontentloaded', timeout: 60000 }});
      record({{ action: 'opened_platform', url: page.url() }});
    }}
    await page.waitForTimeout(2000);
    await openFacebookComposer(page);
    const textFilled = await fillText(page, captionText);
    const imageAttached = fs.existsSync(imagePath) ? await attachImage(page, imagePath) : false;
    record({{
      action: 'prepared',
      textFilled,
      imageAttached,
      note: 'Review the prepared post. Publish and pin from the platform UI if the site requires final confirmation.'
    }});
  }} catch (error) {{
    record({{ action: 'failed', error: String(error.stack || error.message || error).slice(0, 1200) }});
    process.exitCode = 1;
  }}
}})();
""",
        encoding="utf-8",
    )
    return script


def prepare_pinned_profile_asset_pin(asset_id: str) -> dict[str, Any]:
    data = rsr.load(ROOT, "pinnedProfileAssets", default={})
    if not isinstance(data, dict) or not isinstance(data.get("prompts"), list):
        data = pinned_profile_asset_plan()
    asset = next((item for item in data.get("prompts", []) if str(item.get("id") or "") == str(asset_id)), None)
    if not asset:
        raise RuntimeError("Pinned asset was not found.")
    if not asset.get("image") or not Path(str(asset.get("image"))).exists():
        built = build_pinned_profile_asset(asset_id)
        data = rsr.load(ROOT, "pinnedProfileAssets", default={})
        asset = next((item for item in data.get("prompts", []) if str(item.get("id") or "") == str(asset_id)), built.get("asset"))
    folder = Path(str(asset.get("folder") or (PINNED_ASSET_OUTPUT_DIR / str(asset_id)))).resolve()
    if not str(folder).startswith(str(PINNED_ASSET_OUTPUT_DIR.resolve())):
        raise RuntimeError("Pinned asset folder is not valid.")
    image = Path(str(asset.get("image") or folder / "pinned-asset.png")).resolve()
    if not image.exists():
        raise RuntimeError("Pinned asset image does not exist yet.")
    caption_file = Path(str(asset.get("captionFile") or folder / "caption.txt")).resolve()
    if not caption_file.exists():
        caption_file.write_text(pinned_asset_caption(asset) + "\n", encoding="utf-8")
    try:
        subprocess.run(["powershell", "-NoProfile", "-Command", f"Get-Content -Raw -LiteralPath '{caption_file}' | Set-Clipboard"], check=False)
    except Exception:
        pass
    script = write_pinned_asset_pin_playwright_script(asset, folder, image, caption_file)
    chrome_ok, chrome_message = chrome_debug_available()
    launched = False
    message = ""
    if chrome_ok:
        launched = launch_playwright_script(script, folder)
        message = "Pinned asset helper launched. Review the prepared post, then publish and pin if the platform asks for confirmation."
    else:
        target_url = pinned_asset_pin_url(str(asset.get("platform") or "")) or str(asset.get("url") or "")
        if target_url:
            open_url_once(target_url)
        message = f"Chrome helper bridge is not reachable. Caption was copied and the asset folder is ready. {chrome_message}"
    asset.update(
        {
            **pinned_asset_pin_capability(str(asset.get("platform") or "")),
            "pinHelperAt": time.strftime("%Y-%m-%d %H:%M:%S"),
            "pinHelperStatus": "launched" if launched else "needs_chrome_helper",
            "pinHelperScript": str(script),
            "pinHelperLaunched": launched,
            "folder": str(folder),
            "image": str(image),
            "captionFile": str(caption_file),
        }
    )
    data["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    rsr.save(ROOT, "pinnedProfileAssets", data)
    return {
        "ok": launched,
        "asset": asset,
        "folder": str(folder),
        "image": str(image),
        "captionFile": str(caption_file),
        "script": str(script),
        "chrome": chrome_message,
        "message": message,
    }


def mark_pinned_asset_applied(asset_id: str, status: str = "planned") -> dict[str, Any]:
    data = rsr.load(ROOT, "pinnedProfileAssets", default={})
    if not isinstance(data, dict):
        data = pinned_profile_asset_plan()
    status = str(status or "planned").strip().lower()
    if status not in {"planned", "applied", "skipped"}:
        raise RuntimeError("Choose planned, applied, or skipped.")
    asset = next((item for item in data.get("prompts", []) if str(item.get("id") or "") == str(asset_id)), None)
    if not asset:
        raise RuntimeError("Pinned asset was not found.")
    asset["status"] = status
    asset[f"{status}At"] = time.strftime("%Y-%m-%d %H:%M:%S")
    data["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    rsr.save(ROOT, "pinnedProfileAssets", data)
    return {"ok": True, "asset": asset, "plan": data, "file": None, "storage": "sqlite", "resource": "state_snapshots", "state_key": "pinnedProfileAssets"}


