def youtube_end_screen_plan(metadata: dict[str, Any], duration: float = 0.0, next_video: dict[str, Any] | None = None) -> dict[str, Any]:
    strategy = load_automation_strategy().get("youtube", {})
    abbr = story_key(str(metadata.get("abbr") or ""))
    chapter = str(metadata.get("chapter") or "").strip()
    novel = str(metadata.get("novel") or NOVEL_NAMES.get(abbr, "Azure Inkblade"))
    eligible = bool(strategy.get("endScreensEnabled", True)) and float(duration or 0) >= 25
    same_novel = f"{novel} playlist"
    next_chapter = ""
    try:
        if chapter and str(chapter).isdigit():
            next_chapter = f"{novel} Chapter {int(chapter) + 1}"
    except ValueError:
        next_chapter = ""
    next_video = next_video if isinstance(next_video, dict) else {}
    video_element = {"type": "video", "label": next_chapter or "Latest full chapter"}
    if next_video.get("videoId"):
        video_element.update(
            {
                "label": str(next_video.get("title") or next_chapter or "Next chapter"),
                "targetVideoId": str(next_video.get("videoId") or ""),
                "targetTitle": str(next_video.get("title") or ""),
                "targetWatchUrl": str(next_video.get("watchUrl") or f"https://www.youtube.com/watch?v={next_video.get('videoId')}"),
            }
        )
    elements = [
        {"type": "subscribe", "label": "Subscribe to Azure Inkblade"},
        {"type": "best_for_viewer", "label": "Best video for this viewer"},
        {"type": "playlist", "label": same_novel},
        video_element,
    ]
    return {
        "eligible": eligible,
        "reason": "" if eligible else "YouTube end screens need a non-kids video at least 25 seconds long.",
        "startSecondsFromEnd": 20,
        "elements": elements[:4],
        "instructions": "During YouTube Studio review, add Subscribe, Best for viewer, same-novel playlist, and next/latest chapter video.",
    }


def load_youtube_end_screen_state() -> dict[str, Any]:
    data = rsr.load(ROOT, "youtubeEndScreenState", default={})
    if not isinstance(data, dict):
        data = {"schemaVersion": 1, "videos": {}}
    if not isinstance(data.get("videos"), dict):
        data["videos"] = {}
    return data


def save_youtube_end_screen_state(data: dict[str, Any]) -> None:
    data["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    rsr.save(ROOT, "youtubeEndScreenState", data)


def youtube_end_screen_excluded_ids(retry_after_hours: int = 24) -> set[str]:
    state = load_youtube_end_screen_state()
    excluded: set[str] = set()
    now_ts = time.time()
    retry_seconds = max(1, int(retry_after_hours or 24)) * 3600
    for video_id, item in state.get("videos", {}).items():
        video_id = str(video_id)
        if not re.fullmatch(r"[A-Za-z0-9_-]{11}", video_id) or not isinstance(item, dict):
            continue
        status = str(item.get("status") or "").lower()
        if status in {"saved", "manual_review", "attempted"}:
            excluded.add(video_id)
            continue
        if status == "failed":
            attempted_at = str(item.get("attemptedAt") or item.get("updatedAt") or "")
            try:
                attempted_ts = time.mktime(time.strptime(attempted_at[:19], "%Y-%m-%d %H:%M:%S"))
            except Exception:
                attempted_ts = now_ts
            if now_ts - attempted_ts < retry_seconds:
                excluded.add(video_id)
    return excluded


def mark_youtube_end_screen_batch(targets: list[dict[str, Any]], status: str = "attempted") -> None:
    state = load_youtube_end_screen_state()
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    for item in targets:
        video_id = str(item.get("videoId") or "").strip()
        if not re.fullmatch(r"[A-Za-z0-9_-]{11}", video_id):
            continue
        current = state.setdefault("videos", {}).get(video_id, {}) if isinstance(state.setdefault("videos", {}).get(video_id, {}), dict) else {}
        attempts = int(current.get("attempts") or 0)
        state["videos"][video_id] = {
            **current,
            "status": status,
            "attempts": attempts + (1 if status == "attempted" else 0),
            "attemptedAt": now if status == "attempted" else current.get("attemptedAt", now),
            "title": str(item.get("title") or current.get("title") or ""),
            "abbr": str(item.get("abbr") or current.get("abbr") or ""),
            "novel": str(item.get("novel") or current.get("novel") or ""),
            "chapter": item.get("chapter", current.get("chapter")),
            "editUrl": str(item.get("editUrl") or current.get("editUrl") or ""),
        }
    save_youtube_end_screen_state(state)


def update_youtube_end_screen_state_from_results() -> dict[str, Any]:
    result = read_json_safe(YOUTUBE_END_SCREEN_RESULT_FILE)
    rows = result.get("results", []) if isinstance(result, dict) and isinstance(result.get("results"), list) else []
    if not rows:
        return {"updated": 0, "saved": 0, "manualReview": 0, "failed": 0}
    state = load_youtube_end_screen_state()
    counts = {"updated": 0, "saved": 0, "manualReview": 0, "failed": 0}
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    for row in rows:
        video_id = str(row.get("videoId") or "").strip()
        if not re.fullmatch(r"[A-Za-z0-9_-]{11}", video_id):
            continue
        current = state.setdefault("videos", {}).get(video_id, {}) if isinstance(state.setdefault("videos", {}).get(video_id, {}), dict) else {}
        if row.get("saved"):
            status = "saved"
            counts["saved"] += 1
        elif row.get("needsManualReview") and row.get("steps"):
            status = "manual_review"
            counts["manualReview"] += 1
        else:
            status = "failed"
            counts["failed"] += 1
        state["videos"][video_id] = {
            **current,
            "status": status,
            "updatedAt": now,
            "savedAt": now if status == "saved" else current.get("savedAt", ""),
            "lastError": str(row.get("error") or row.get("note") or ""),
            "lastSteps": row.get("steps", []),
            "debugScreenshot": str(row.get("debugScreenshot") or ""),
            "currentUrl": str(row.get("currentUrl") or ""),
        }
        counts["updated"] += 1
    save_youtube_end_screen_state(state)
    return counts


def youtube_end_screen_targets(limit: int = 80, refresh_scan: bool = False) -> dict[str, Any]:
    if refresh_scan or not YOUTUBE_LIBRARY_SCAN_FILE.exists():
        if chrome_debug_available()[0]:
            scan_existing_youtube_videos()
    update_youtube_end_screen_state_from_results()
    excluded_ids = youtube_end_screen_excluded_ids()
    raw = read_json_safe(YOUTUBE_LIBRARY_SCAN_FILE)
    if (
        isinstance(raw, dict)
        and isinstance(raw.get("videos"), list)
        and isinstance(raw.get("skippedVerifiedPinned"), list)
        and len(raw.get("videos", [])) < 10
        and len(raw.get("skippedVerifiedPinned", [])) >= 10
        and chrome_debug_available()[0]
    ):
        scan_existing_youtube_videos()
        raw = read_json_safe(YOUTUBE_LIBRARY_SCAN_FILE)
    videos = raw.get("videos", []) if isinstance(raw, dict) and isinstance(raw.get("videos"), list) else []
    uploaded_by_chapter: dict[tuple[str, int], dict[str, Any]] = {}
    for candidate in videos:
        candidate_title = str(candidate.get("title") or "")
        candidate_id = str(candidate.get("videoId") or "")
        if not re.fullmatch(r"[A-Za-z0-9_-]{11}", candidate_id):
            continue
        candidate_abbr, candidate_chapter, _ = youtube_library_title_match(candidate_title)
        if candidate_abbr and candidate_chapter is not None:
            uploaded_by_chapter.setdefault(
                (candidate_abbr, int(candidate_chapter)),
                {
                    **candidate,
                    "abbr": candidate_abbr,
                    "chapter": int(candidate_chapter),
                    "watchUrl": str(candidate.get("watchUrl") or f"https://www.youtube.com/watch?v={candidate_id}"),
                },
            )
    targets: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    for video in videos:
        title = str(video.get("title") or "").strip()
        video_id = str(video.get("videoId") or "").strip()
        if not re.fullmatch(r"[A-Za-z0-9_-]{11}", video_id):
            continue
        if video_id in excluded_ids:
            skipped.append({"videoId": video_id, "title": title, "reason": "End screen already attempted or saved; skipped for this pass."})
            continue
        duration = float(video.get("duration") or 0)
        if duration and duration < 180:
            skipped.append({"videoId": video_id, "title": title, "reason": "Short or short-form video."})
            continue
        if bool(video.get("madeForKids")) or "made for kids" in str(video.get("text") or "").lower():
            skipped.append({"videoId": video_id, "title": title, "reason": "Marked made for kids; comments/end-screen growth features should not be applied."})
            continue
        abbr, chapter, reason = youtube_library_title_match(title)
        if not abbr or chapter is None:
            skipped.append({"videoId": video_id, "title": title, "reason": reason or "Could not match novel/chapter."})
            continue
        folder = youtube_folder_for_chapter(abbr, chapter)
        metadata = read_metadata(folder) if folder and (folder / "metadata.json").exists() else {
            "abbr": abbr,
            "novel": NOVEL_NAMES.get(abbr, abbr),
            "chapter": chapter,
            "title": title,
        }
        assumed_duration = duration or 180
        next_video = uploaded_by_chapter.get((abbr, int(chapter) + 1), {})
        plan = youtube_end_screen_plan({**metadata, "abbr": abbr, "chapter": chapter}, assumed_duration, next_video)
        if not plan.get("eligible"):
            skipped.append({"videoId": video_id, "title": title, "reason": str(plan.get("reason") or "Not eligible.")})
            continue
        targets.append(
            {
                "videoId": video_id,
                "title": title,
                "abbr": abbr,
                "novel": NOVEL_NAMES.get(abbr, abbr),
                "chapter": chapter,
                "duration": assumed_duration,
                "watchUrl": str(video.get("watchUrl") or f"https://www.youtube.com/watch?v={video_id}"),
                "editUrl": str(video.get("editUrl") or f"https://studio.youtube.com/video/{video_id}/edit"),
                "folder": str(folder or ""),
                "plan": plan,
            }
        )
        if len(targets) >= max(1, int(limit or 80)):
            break
    payload = {
        "generatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "scannedAt": raw.get("scannedAt", "") if isinstance(raw, dict) else "",
        "targets": targets,
        "skipped": skipped[:120],
        "stateFile": None,
        "file": None,
        "storage": "sqlite",
        "resource": "state_snapshots",
        "state_key": "youtubeEndScreenPlan",
        "state_key_state": "youtubeEndScreenState",
        "message": f"Prepared {len(targets)} old YouTube video(s) for end-screen backfill; skipped {len(excluded_ids)} already attempted/saved video(s).",
    }
    rsr.save(ROOT, "youtubeEndScreenPlan", payload)
    return payload


def write_youtube_end_screen_script(targets: list[dict[str, Any]]) -> Path:
    safe_targets = [
        {
            "videoId": str(item.get("videoId") or ""),
            "title": str(item.get("title") or ""),
            "editUrl": str(item.get("editUrl") or f"https://studio.youtube.com/video/{item.get('videoId')}/edit"),
            "novel": str(item.get("novel") or ""),
            "chapter": item.get("chapter"),
            "elements": (item.get("plan") or {}).get("elements") or [],
            "targetVideo": next(
                (
                    element for element in ((item.get("plan") or {}).get("elements") or [])
                    if isinstance(element, dict) and element.get("type") == "video"
                ),
                {},
            ),
        }
        for item in targets
        if re.fullmatch(r"[A-Za-z0-9_-]{11}", str(item.get("videoId") or ""))
    ]
    YOUTUBE_END_SCREEN_SCRIPT_FILE.write_text(
        f'''const fs = require('fs');
const {{ chromium }} = require('playwright');

const cdpUrl = {json.dumps(chrome_debug_url())};
const outputPath = {json.dumps(str(YOUTUBE_END_SCREEN_RESULT_FILE))};
const targets = {json.dumps(safe_targets, ensure_ascii=False)};
const screenshotDir = {json.dumps(str((ROOT / "youtube-end-screen-debug").resolve()))};
fs.mkdirSync(screenshotDir, {{ recursive: true }});

async function clickFirst(page, labels, timeout = 3500) {{
  for (const label of labels) {{
    for (const role of ['button', 'tab', 'link', 'menuitem']) {{
      const byRole = page.getByRole(role, {{ name: label }}).first();
      if (await byRole.count().catch(() => 0)) {{
        try {{
          await byRole.click({{ timeout }});
          return `${{role}}:${{label}}`;
        }} catch (_) {{}}
      }}
    }}
    const byText = page.getByText(label, {{ exact: false }}).first();
    if (await byText.count().catch(() => 0)) {{
      try {{
        await byText.click({{ timeout }});
        return `text:${{label}}`;
      }} catch (_) {{}}
    }}
  }}
  return '';
}}

async function clickVisibleSelector(page, selectors, timeout = 3500) {{
  for (const selector of selectors) {{
    const locator = page.locator(selector).first();
    if (!(await locator.count().catch(() => 0))) continue;
    try {{
      await locator.scrollIntoViewIfNeeded().catch(() => null);
      await locator.click({{ timeout }});
      return selector;
    }} catch (_) {{}}
  }}
  return '';
}}

async function clickTextDom(page, needles) {{
  return await page.evaluate((rawNeedles) => {{
    const wanted = rawNeedles.map((value) => String(value || '').toLowerCase()).filter(Boolean);
    const visible = (el) => {{
      const box = el.getBoundingClientRect();
      const style = window.getComputedStyle(el);
      return box.width > 0 && box.height > 0 && style.display !== 'none' && style.visibility !== 'hidden';
    }};
    const nodes = Array.from(document.querySelectorAll('ytcp-button, ytcp-icon-button, tp-yt-paper-item, yt-formatted-string, button, a, div, span'));
    for (const node of nodes) {{
      if (!visible(node)) continue;
      const text = String(node.innerText || node.textContent || '').replace(/\\s+/g, ' ').trim().toLowerCase();
      if (!text || !wanted.some((needle) => text.includes(needle))) continue;
      const clickable = node.closest('button, a, ytcp-button, ytcp-icon-button, tp-yt-paper-item') || node;
      clickable.click();
      return text.slice(0, 120);
    }}
    return '';
  }}, needles).catch(() => '');
}}

async function pageTextSample(page) {{
  return await page.evaluate(() => String(document.body?.innerText || '').replace(/\\s+/g, ' ').trim().slice(0, 1800)).catch(() => '');
}}

async function debugCapture(page, row, label) {{
  const safeId = String(row.videoId || 'unknown').replace(/[^A-Za-z0-9_-]/g, '_');
  const path = `${{screenshotDir}}/${{safeId}}-${{label}}.png`;
  await page.screenshot({{ path, fullPage: true }}).catch(() => null);
  row.debugScreenshot = path;
  row.pageText = await pageTextSample(page);
  row.currentUrl = page.url();
}}

async function chooseSpecificEndScreenVideo(page, target) {{
  const targetVideo = target.targetVideo || {{}};
  const targetId = String(targetVideo.targetVideoId || '');
  const targetTitle = String(targetVideo.targetTitle || targetVideo.label || '');
  if (!targetId && !targetTitle) return 'no specific target video';
  const addVideo = await clickFirst(page, ['Add Video', 'Video'], 5000)
    || await clickTextDom(page, ['add video', 'video']);
  if (!addVideo) return 'add video control not found';
  await page.waitForTimeout(1500);
  const chooseSpecific = await clickFirst(page, ['Choose specific video', 'Specific video', 'Choose video'], 5000)
    || await clickTextDom(page, ['choose specific video', 'specific video', 'choose video']);
  await page.waitForTimeout(1500);
  const search = page.locator('input[placeholder*="Search" i], input[aria-label*="Search" i], ytcp-search-box input, input[type="text"]').first();
  if (await search.count().catch(() => 0)) {{
    await search.click({{ timeout: 3000 }}).catch(() => null);
    await page.keyboard.press(process.platform === 'darwin' ? 'Meta+A' : 'Control+A').catch(() => null);
    await page.keyboard.press('Backspace').catch(() => null);
    await page.keyboard.insertText(targetId || targetTitle);
    await page.waitForTimeout(2500);
  }}
  const selected = await clickVisibleSelector(page, [
    `a[href*="${{targetId}}"]`,
    `ytcp-video-list-cell-video-renderer:has-text("${{targetTitle.replace(/"/g, '\\"')}}")`,
    `ytcp-video-row:has-text("${{targetTitle.replace(/"/g, '\\"')}}")`,
    `tp-yt-paper-item:has-text("${{targetTitle.replace(/"/g, '\\"')}}")`
  ], 5000) || await clickTextDom(page, [targetTitle, targetId]);
  if (!selected) return `specific target not found: ${{targetTitle || targetId}}`;
  await page.waitForTimeout(1000);
  const apply = await clickFirst(page, ['Apply', 'Save', 'Done'], 5000)
    || await clickTextDom(page, ['apply', 'save', 'done']);
  await page.waitForTimeout(1500);
  return `selected specific video ${{targetId || targetTitle}} via ${{selected}}${{apply ? '; applied' : ''}}${{chooseSpecific ? '; specific mode' : ''}}`;
}}

async function saveIfPossible(page) {{
  const save = page.locator('#save button, button[aria-label="Save"], ytcp-button:has-text("Save")').first();
  if (!(await save.count().catch(() => 0))) return false;
  try {{
    await save.scrollIntoViewIfNeeded().catch(() => null);
    const disabled = await save.getAttribute('disabled').catch(() => null);
    const ariaDisabled = await save.getAttribute('aria-disabled').catch(() => null);
    if (disabled !== null || ariaDisabled === 'true') return false;
    const response = page.waitForResponse(
      (res) => res.request().method() === 'POST' && /youtubei\\/v1\\//.test(res.url()) && res.ok(),
      {{ timeout: 45000 }}
    ).catch(() => null);
    await save.click({{ timeout: 5000 }});
    await response;
    await page.waitForTimeout(2500);
    return true;
  }} catch (_) {{
    return false;
  }}
}}

(async () => {{
  const browser = await chromium.connectOverCDP(cdpUrl);
  const context = browser.contexts()[0] || await browser.newContext();
  const results = [];
  for (const target of targets) {{
    const page = await context.newPage();
    const row = {{ ...target, ok: false, steps: [], saved: false, needsManualReview: true }};
    try {{
      await page.goto(target.editUrl, {{ waitUntil: 'domcontentloaded', timeout: 60000 }});
      await page.bringToFront().catch(() => null);
      await page.waitForLoadState('networkidle', {{ timeout: 15000 }}).catch(() => null);
      await page.waitForTimeout(2500);
      row.steps.push('opened_edit_page');

      const editorUrl = `https://studio.youtube.com/video/${{target.videoId}}/editor`;
      await page.goto(editorUrl, {{ waitUntil: 'domcontentloaded', timeout: 60000 }}).catch(() => null);
      await page.waitForLoadState('networkidle', {{ timeout: 15000 }}).catch(() => null);
      await page.waitForTimeout(4500);
      row.steps.push('opened_editor_url');

      const editorClick = await clickFirst(page, [/^Editor$/i, 'Editor', 'Video editor'], 4000)
        || await clickTextDom(page, ['editor', 'video editor']);
      if (editorClick) {{
        row.steps.push(`opened_editor:${{editorClick}}`);
        await page.waitForTimeout(4500);
      }}

      const endScreenClick = await clickFirst(page, [/End screen/i, 'End screen', 'Add an end screen', 'Add end screen'], 5000)
        || await clickVisibleSelector(page, [
          'ytcp-ve-expansion-panel:has-text("End screen")',
          'ytcp-button:has-text("End screen")',
          'button:has-text("End screen")',
          '[aria-label*="End screen" i]',
          '[test-id*="end" i]',
          '[id*="end" i]'
        ], 5000)
        || await clickTextDom(page, ['end screen', 'add an end screen']);
      if (endScreenClick) {{
        row.steps.push(`opened_end_screen:${{endScreenClick}}`);
        await page.waitForTimeout(3500);
      }} else {{
        await debugCapture(page, row, 'no-end-screen-control');
        throw new Error('Could not find the YouTube Studio End screen control.');
      }}

      const specificVideoResult = await chooseSpecificEndScreenVideo(page, target);
      row.steps.push(`specific_video:${{specificVideoResult}}`);
      const specificVideoSelected = specificVideoResult.startsWith('selected specific video');

      const importClick = specificVideoSelected ? '' : await clickFirst(page, ['Import from video', 'Import from latest video', 'Use template', 'Apply template', 'Import'], 5000)
        || await clickTextDom(page, ['import from video', 'import from latest video', 'use template', 'apply template', 'import']);
      if (importClick) {{
        row.steps.push(`attempted_template:${{importClick}}`);
        await page.waitForTimeout(3000);
        const dialogChoice = await clickVisibleSelector(page, [
          'ytcp-video-list-cell-video-renderer:visible',
          'tp-yt-paper-dialog ytcp-entity-card:visible',
          'tp-yt-paper-dialog ytcp-video-row:visible'
        ], 4000);
        if (dialogChoice) {{
          row.steps.push(`selected_template_source:${{dialogChoice}}`);
          await page.waitForTimeout(1200);
        }}
        const applyTemplate = await clickFirst(page, ['Import', 'Apply', 'Done', 'Save'], 5000)
          || await clickTextDom(page, ['import', 'apply', 'done']);
        if (applyTemplate) {{
          row.steps.push(`applied_template:${{applyTemplate}}`);
          await page.waitForTimeout(2500);
        }}
      }}

      for (const label of ['Subscribe', 'Best for viewer', 'Video', 'Playlist', 'Most recent upload']) {{
        if (specificVideoSelected && label === 'Video') continue;
        const clicked = await clickFirst(page, [`Add ${{label}}`, label], 2500);
        if (clicked) {{
          row.steps.push(`attempted_element:${{label}}`);
          await page.waitForTimeout(1200);
        }}
      }}

      row.saved = await saveIfPossible(page);
      row.ok = row.saved || row.steps.some((step) => step.startsWith('opened_end_screen'));
      row.needsManualReview = !row.saved;
      if (!row.saved) {{
        await debugCapture(page, row, 'not-saved');
        row.note = 'YouTube Studio opened the end-screen workflow, but the app could not verify a saved end-screen. Review this video manually.';
      }}
    }} catch (error) {{
      row.error = error.message;
      await debugCapture(page, row, 'error').catch(() => null);
    }} finally {{
      if (row.saved || row.error) {{
        await page.close().catch(() => null);
      }} else {{
        row.steps.push('left_open_for_manual_review');
      }}
    }}
    results.push(row);
    fs.writeFileSync(outputPath, JSON.stringify({{ updatedAt: new Date().toISOString(), results }}, null, 2), 'utf8');
    await new Promise((resolve) => setTimeout(resolve, 1200));
  }}
  fs.writeFileSync(outputPath, JSON.stringify({{ finishedAt: new Date().toISOString(), results }}, null, 2), 'utf8');
  process.exit(0);
}})().catch((error) => {{
  fs.writeFileSync(outputPath, JSON.stringify({{ finishedAt: new Date().toISOString(), error: error.message, stack: error.stack, results: [] }}, null, 2), 'utf8');
  process.exit(1);
}});
''',
        encoding="utf-8",
    )
    return YOUTUBE_END_SCREEN_SCRIPT_FILE


def apply_youtube_end_screens(limit: int = 80, dry_run: bool = False) -> dict[str, Any]:
    requested_limit = max(1, int(limit or 80))
    worker_limit = requested_limit if dry_run else min(requested_limit, 5)
    plan = youtube_end_screen_targets(limit=worker_limit, refresh_scan=False)
    targets = plan.get("targets", []) if isinstance(plan.get("targets"), list) else []
    if dry_run:
        return {**plan, "ok": True, "dryRun": True, "message": plan.get("message", "End-screen plan prepared.")}
    if not targets:
        return {**plan, "ok": False, "error": "No eligible old YouTube videos were found. Run the library scan first if this looks wrong."}
    chrome_ready, chrome_message = chrome_debug_available()
    if not chrome_ready:
        return {**plan, "ok": False, "error": chrome_message}
    if not playwright_available():
        return {**plan, "ok": False, "error": "Playwright is not installed or not reachable in this workspace."}
    mark_youtube_end_screen_batch(targets, "attempted")
    script = write_youtube_end_screen_script(targets)
    node = bundled_node_executable()
    subprocess.Popen(
        [str(node), str(script)],
        cwd=str(ROOT),
        env={**os.environ, "NODE_PATH": str(ROOT / "node_modules"), "PLAYWRIGHT_BROWSERS_PATH": str(ROOT / "ms-playwright")},
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    return {
        **plan,
        "ok": True,
        "launched": True,
        "script": str(script),
        "resultsFile": str(YOUTUBE_END_SCREEN_RESULT_FILE),
        "message": f"YouTube end-screen backfill started for {len(targets)} video(s). Review the results file after it finishes. Runs are capped at 5 videos per click for stability.",
    }


def predictive_growth_recommendations() -> dict[str, Any]:
    dashboard = monetization_dashboard()
    weekly = write_growth_weekly_report()
    optimizer = growth_optimizer_plan()
    instagram_blueprint = instagram_growth_blueprint()
    creator_benchmarks = creator_benchmark_dashboard()
    weekly_stats = weekly_growth_stats_status()
    experiments = load_content_experiments()
    conversions = _phase2_load_blob("conversionTracking", CONVERSION_TRACKING_FILE)
    if not isinstance(conversions, dict):
        conversions = {"platforms": {}, "snapshots": []}
    scores = dashboard.get("scores", {}) if isinstance(dashboard.get("scores"), dict) else {}
    total = sum(max(0.0, numeric_metric(value)) for value in scores.values()) or 1.0
    platform_weights = [
        {
            "platform": platform,
            "score": round(numeric_metric(value), 2),
            "weight": round(max(0.0, numeric_metric(value)) / total, 4),
        }
        for platform, value in sorted(scores.items(), key=lambda item: numeric_metric(item[1]), reverse=True)
    ]
    winner_rows = analytics_winner_recommendations(False).get("recommendations", [])
    weak_novels = [
        item for item in novel_level_strategy().get("novels", [])
        if numeric_metric(item.get("avgScore")) < 0.5 or not numeric_metric(item.get("experiments"))
    ]
    ready_full_youtube = youtube_created_not_uploaded()
    end_screen_plan = rsr.load(ROOT, "youtubeEndScreenPlan", default={})
    end_screen_count = len(end_screen_plan.get("targets", [])) if isinstance(end_screen_plan, dict) and isinstance(end_screen_plan.get("targets"), list) else 0
    actions = []
    primary = str(dashboard.get("primaryPlatform") or "tiktok")
    first_calendar_item = (instagram_blueprint.get("thirtyDayCalendar") or [{}])[0]
    if first_calendar_item:
        actions.append({
            "priority": 1,
            "area": "instagram",
            "action": f"Instagram blueprint first move: {first_calendar_item.get('format')} for {first_calendar_item.get('novel')} using {first_calendar_item.get('pillar')} with hook: {first_calendar_item.get('hook')}",
        })
    actions.append({"priority": 1, "area": primary, "action": "Build the next daily short-form post with a fresh image and a direct follow/read CTA."})
    actions.append({"priority": 2, "area": "youtube", "action": "Keep full YouTube rendering separate, then add end screens and pinned comments before marking uploads complete."})
    if ready_full_youtube:
        actions.append({"priority": 3, "area": "youtube", "action": f"{len(ready_full_youtube)} full YouTube video(s) are ready to upload or verify."})
    if end_screen_count:
        actions.append({"priority": 4, "area": "youtube", "action": f"{end_screen_count} old full video(s) are ready for end-screen backfill."})
    if weak_novels:
        actions.append({"priority": 5, "area": "experiments", "action": "Run variants for weaker novels before repeating winning novels.", "novels": [item.get("abbr") for item in weak_novels[:4]]})
    if not winner_rows:
        actions.append({"priority": 6, "area": "metrics", "action": "Gather metrics before changing the rotation. The app does not have enough winners yet."})
    else:
        actions.append({"priority": 6, "area": "experiments", "action": "Use winning hook patterns, but force fresh scene images so posts do not look recycled."})
    benchmark_recs = creator_benchmarks.get("recommendations") if isinstance(creator_benchmarks.get("recommendations"), list) else []
    if benchmark_recs:
        best = benchmark_recs[0]
        actions.append({
            "priority": 7,
            "area": "creator_benchmark",
            "action": f"{best.get('title') or 'Test a benchmark pattern'}: {best.get('action') or 'Use the pattern in one variant without copying the source.'}",
        })
    else:
        actions.append({"priority": 7, "area": "creator_benchmark", "action": "Run Creator Benchmarks to learn which public hook/title/duration patterns are working in adjacent niches."})
    if weekly_stats.get("due"):
        actions.insert(0, {"priority": 0, "area": "metrics", "action": "Collect weekly growth stats before building the next batch so the rotation uses current platform signals."})
    follower_funnels = [
        "Shorts/Reels/TikTok: hook the chapter scene, then CTA to follow for the next chapter.",
        "YouTube full chapters: mid-chapter like/subscribe note, end screen to same-novel playlist, pinned comment with Royal Road and Patreon.",
        "Instagram/X/Facebook: rotate Royal Road-first, Patreon early, and YouTube full-chapter CTAs so every post is not the same ad.",
        "Royal Road: author notes should push readers to YouTube/TikTok/Patreon after the chapter, not before the story.",
    ]
    payload = {
        "generatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "primaryPlatform": primary,
        "platformWeights": platform_weights,
        "actions": actions,
        "followerFunnels": follower_funnels,
        "growthOptimizer": optimizer,
        "creatorBenchmarks": creator_benchmarks,
        "instagramBlueprint": {
            "positioning": instagram_blueprint.get("positioning", {}),
            "firstSevenDays": instagram_blueprint.get("firstSevenDays", {}),
            "contentPillars": (instagram_blueprint.get("contentPillars") or [])[:6],
            "calendar": (instagram_blueprint.get("thirtyDayCalendar") or [])[:7],
            "file": instagram_blueprint.get("file"),
        },
        "winners": winner_rows[:10],
        "weakNovels": weak_novels[:4],
        "weeklyReport": weekly,
        "weeklyGrowthStats": weekly_stats,
        "conversions": conversions,
        "experiments": {"count": len(experiments.get("experiments", [])) if isinstance(experiments, dict) else 0},
        "quota": quota_usage_summary(),
        "file": str(PREDICTIVE_GROWTH_PLAN_FILE),
    }
    _phase2_save_blob("predictiveGrowthPlan", PREDICTIVE_GROWTH_PLAN_FILE, payload)
    return payload


def youtube_poll_draft_options() -> list[dict[str, Any]]:
    dashboard = growth_automation_dashboard()
    resurfacing = dashboard.get("resurfacing", {})
    candidates = (resurfacing.get("backCatalog") or [])[:2] + (resurfacing.get("reposts") or [])[:2]
    options = []
    for item in candidates:
        options.append({
            "label": f"{item.get('novel') or item.get('abbr')} Ch. {item.get('chapter')}",
            "reason": item.get("reason") or "eligible growth candidate",
        })
    for abbr, novel in NOVEL_NAMES.items():
        if len(options) >= 4:
            break
        label = novel
        if not any(option["label"] == label for option in options):
            options.append({"label": label, "reason": "novel rotation option"})
    return options[:4]


def build_youtube_post_drafts() -> dict[str, Any]:
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    options = youtube_poll_draft_options()
    scan = read_json_safe(YOUTUBE_LIBRARY_SCAN_FILE)
    videos = []
    if isinstance(scan, dict):
        for video in scan.get("videos", [])[:10]:
            if not video.get("madeForKids") and video.get("watchUrl"):
                videos.append({
                    "title": video.get("title"),
                    "videoId": video.get("videoId"),
                    "watchUrl": video.get("watchUrl"),
                    "editUrl": video.get("editUrl"),
                })
    draft = {
        "id": content_hash(f"youtube-poll|{now}")[:12],
        "createdAt": now,
        "platform": "youtube_posts",
        "type": "poll",
        "title": "Reader poll",
        "text": "Which Azure Inkblade story should get the next longer lore or character spotlight?",
        "options": [item["label"] for item in options],
        "notes": [f"{item['label']}: {item['reason']}" for item in options],
        "videoTargets": videos,
        "status": "draft",
    }
    data = _phase2_load_blob("youtubePostDrafts", YOUTUBE_POST_DRAFTS_FILE)
    if not isinstance(data, dict):
        data = {"schemaVersion": 1, "drafts": []}
    data.setdefault("drafts", []).append(draft)
    data["drafts"] = data["drafts"][-80:]
    data["updatedAt"] = now
    _phase2_save_blob("youtubePostDrafts", YOUTUBE_POST_DRAFTS_FILE, data)
    return {"ok": True, "draft": draft, "drafts": data["drafts"], "file": str(YOUTUBE_POST_DRAFTS_FILE), "message": "YouTube poll draft created for review."}


def target_youtube_poll_draft(draft_id: str, video_id: str) -> dict[str, Any]:
    data = _phase2_load_blob("youtubePostDrafts", YOUTUBE_POST_DRAFTS_FILE)
    if not isinstance(data, dict):
        raise RuntimeError("YouTube poll drafts were not found.")
    draft = next((item for item in data.get("drafts", []) if str(item.get("id") or "") == str(draft_id)), None)
    if not draft:
        raise RuntimeError("YouTube poll draft was not found.")
    target = next((item for item in draft.get("videoTargets", []) if str(item.get("videoId") or "") == str(video_id)), None)
    if not target:
        raise RuntimeError("Video target was not found for this draft.")
    draft["selectedVideoTarget"] = target
    draft["status"] = "targeted"
    draft["targetedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    data["updatedAt"] = draft["targetedAt"]
    _phase2_save_blob("youtubePostDrafts", YOUTUBE_POST_DRAFTS_FILE, data)
    return {"ok": True, "draft": draft, "file": str(YOUTUBE_POST_DRAFTS_FILE)}


def analytics_winner_recommendations(apply: bool = False) -> dict[str, Any]:
    store = load_content_experiments()
    strategy = load_automation_strategy()
    minimum_score = float(strategy.get("analytics", {}).get("minimumVariantScoreForWinner") or 0.65)
    minimum_views = float(strategy.get("analytics", {}).get("minimumViewsForDecision") or 100)
    recommendations = []
    changed = []
    for experiment in store.get("experiments", []):
        variants = list(experiment.get("variants") or [])
        scored = []
        for variant in variants:
            metrics = variant.get("metrics") if isinstance(variant.get("metrics"), dict) else {}
            views = float(metrics.get("views") or 0)
            score = variant.get("score")
            if score is not None and views >= minimum_views:
                scored.append((float(score), views, variant))
        if not scored:
            continue
        score, views, variant = max(scored, key=lambda item: item[0])
        action = "watch"
        if score >= minimum_score:
            action = "winner"
            if apply and variant.get("status") != "winner":
                variant["status"] = "winner"
                variant["winnerAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
                experiment["status"] = "has_winner"
                changed.append({"experimentId": experiment.get("experimentId"), "variantId": variant.get("variantId")})
        recommendations.append(
            {
                "experimentId": experiment.get("experimentId"),
                "variantId": variant.get("variantId"),
                "abbr": experiment.get("abbr"),
                "novel": experiment.get("novel"),
                "chapter": experiment.get("chapter"),
                "hookType": variant.get("hookType"),
                "openingText": variant.get("openingText"),
                "score": round(score, 4),
                "views": views,
                "action": action,
            }
        )
    if changed:
        save_content_experiments(store)
        write_growth_weekly_report(store)
    return {"ok": True, "applied": apply, "changed": changed, "recommendations": recommendations[:30], "strategy": strategy}


