def load_automatic_metrics_state() -> dict[str, Any]:
    data = rsr.load(ROOT, "automaticMetricsState", default={})
    if not isinstance(data, dict):
        data = {}
    data.setdefault("enabled", AUTO_METRICS_ENABLED)
    data.setdefault("lastAttemptAt", "")
    data.setdefault("lastSuccessAt", "")
    data.setdefault("lastResult", {})
    return data


def save_automatic_metrics_state(data: dict[str, Any]) -> None:
    data["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    rsr.save(ROOT, "automaticMetricsState", data)


def experiment_timestamp(value: Any) -> datetime | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00")).replace(tzinfo=None)
    except ValueError:
        return None


def automatic_metrics_due_variants() -> list[dict[str, str]]:
    cutoff = datetime.now() - timedelta(hours=AUTO_METRICS_MIN_AGE_HOURS)
    due: list[dict[str, str]] = []
    for experiment in load_content_experiments().get("experiments", []):
        for variant in experiment.get("variants", []):
            if int(variant.get("timesUsed") or 0) < 1:
                continue
            used_at = experiment_timestamp(variant.get("lastUsedAt"))
            measured_at = experiment_timestamp(variant.get("lastMeasuredAt"))
            if not used_at or used_at > cutoff or (measured_at and measured_at >= used_at):
                continue
            due.append(
                {
                    "experimentId": str(experiment.get("experimentId") or ""),
                    "variantId": str(variant.get("variantId") or ""),
                    "novel": str(experiment.get("novel") or ""),
                    "chapter": str(experiment.get("chapter") or ""),
                    "lastUsedAt": str(variant.get("lastUsedAt") or ""),
                }
            )
    return due


def automatic_metrics_status() -> dict[str, Any]:
    state = load_automatic_metrics_state()
    due = automatic_metrics_due_variants()
    report = _phase2_load_blob("growthWeeklyReport", GROWTH_WEEKLY_REPORT_FILE)
    if not isinstance(report, dict):
        report = write_growth_weekly_report()
    return {
        **state,
        "enabled": AUTO_METRICS_ENABLED,
        "minimumAgeHours": AUTO_METRICS_MIN_AGE_HOURS,
        "intervalHours": AUTO_METRICS_INTERVAL_HOURS,
        "dueCount": len(due),
        "due": due[:20],
        "weeklyReport": report,
    }


def automatic_metrics_worker() -> None:
    time.sleep(30)
    while AUTO_METRICS_ENABLED:
        state = load_automatic_metrics_state()
        due = automatic_metrics_due_variants()
        clickup_kpi_due = kpi_sync_due_count()
        last_attempt = experiment_timestamp(state.get("lastAttemptAt"))
        last_result = state.get("lastResult") if isinstance(state.get("lastResult"), dict) else {}
        retry_hours = AUTO_METRICS_INTERVAL_HOURS if last_result.get("ok") else AUTO_METRICS_RETRY_HOURS
        ready_by_time = not last_attempt or datetime.now() - last_attempt >= timedelta(hours=retry_hours)
        if (due or clickup_kpi_due) and ready_by_time:
            state["lastAttemptAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
            state["dueAtAttempt"] = len(due)
            state["clickupKpiDueAtAttempt"] = clickup_kpi_due
            save_automatic_metrics_state(state)
            try:
                result = gather_experiment_metrics_with_playwright(True, True)
            except Exception as exc:
                result = {"ok": False, "error": str(exc), "results": [], "applied": []}
                record_recovery_event(
                    "automatic_metrics",
                    str(exc),
                    error_type="metrics_gather_failed",
                    retry_path="The automatic metrics worker will retry on the next retry interval.",
                )
            kpi_24h_result = run_kpi_check("24h") if clickup_kpi_due else {"checked": 0, "updated": [], "failures": []}
            kpi_7d_result = run_kpi_check("7d") if clickup_kpi_due else {"checked": 0, "updated": [], "failures": []}
            weekly_report = write_growth_weekly_report()
            try:
                audit_age = time.time() - PROFILE_AUDIT_FILE.stat().st_mtime if PROFILE_AUDIT_FILE.exists() else 31 * 86400
                if audit_age >= 30 * 86400:
                    profile_conversion_audit()
                pinned_content_plan()
            except Exception:
                pass
            state = load_automatic_metrics_state()
            state["lastResult"] = {
                "ok": bool(result.get("ok")),
                "message": str(result.get("message") or result.get("error") or ""),
                "appliedCount": len(result.get("applied") or []),
                "resultCount": len(result.get("results") or []),
                "weeklyMeasurementCount": int(weekly_report.get("measurementCount") or 0),
                "clickupKpi24h": {
                    "checked": int(kpi_24h_result.get("checked") or 0),
                    "updated": len(kpi_24h_result.get("updated") or []),
                    "failures": len(kpi_24h_result.get("failures") or []),
                },
                "clickupKpi7d": {
                    "checked": int(kpi_7d_result.get("checked") or 0),
                    "updated": len(kpi_7d_result.get("updated") or []),
                    "failures": len(kpi_7d_result.get("failures") or []),
                },
            }
            if result.get("ok"):
                state["lastSuccessAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
            save_automatic_metrics_state(state)
        time.sleep(900)


def start_automatic_metrics_worker() -> None:
    global AUTO_METRICS_THREAD
    if not AUTO_METRICS_ENABLED or (AUTO_METRICS_THREAD and AUTO_METRICS_THREAD.is_alive()):
        return
    AUTO_METRICS_THREAD = threading.Thread(target=automatic_metrics_worker, daemon=True, name="automatic-metrics")
