def select_test_variants(experiment: dict[str, Any], limit: int = 3) -> list[dict[str, Any]]:
    variants = [
        variant for variant in experiment.get("variants", [])
        if str(variant.get("status") or "draft") not in {"rejected", "retired"}
    ]
    if not variants:
        return []

    def variant_weight(variant: dict[str, Any]) -> float:
        status = str(variant.get("status") or "draft")
        status_bonus = {"winner": 2.0, "approved": 1.5, "use_later": 1.2, "selected_for_test": 0.75}.get(status, 1.0)
        try:
            score = float(variant.get("score") or 0)
        except (TypeError, ValueError):
            score = 0.0
        try:
            times_used = int(variant.get("timesUsed") or 0)
        except (TypeError, ValueError):
            times_used = 0
        performance = max(0.2, 1.0 + max(-0.5, min(score, 5.0)) / 5.0)
        reuse_penalty = 1.0 / (1.0 + times_used)
        return max(0.05, status_bonus * performance * reuse_penalty)

    selected: list[dict[str, Any]] = []
    used_types: set[str] = set()
    pool = list(variants)
    while pool and len(selected) < limit:
        diverse_pool = [variant for variant in pool if str(variant.get("hookType") or "") not in used_types]
        draw_pool = diverse_pool or pool
        weights = [variant_weight(variant) for variant in draw_pool]
        variant = random.choices(draw_pool, weights=weights, k=1)[0]
        selected.append(variant)
        used_types.add(str(variant.get("hookType") or ""))
        pool.remove(variant)
    return selected


def variant_links_block(abbr: str) -> str:
    return platform_links_block(abbr)


def variant_platform_copy(experiment: dict[str, Any], variant: dict[str, Any]) -> dict[str, str]:
    abbr = story_key(str(experiment.get("abbr") or ""))
    novel = str(experiment.get("novel") or NOVEL_NAMES.get(abbr, abbr))
    chapter = str(experiment.get("chapter") or "")
    title = str(experiment.get("title") or f"Chapter {chapter}")
    opening = str(variant.get("openingText") or "").strip()
    caption = str(variant.get("caption") or opening).strip()
    profile = social_profile(abbr)
    links = variant_links_block(abbr)
    variant_id = str(variant.get("variantId") or "variant")
    campaign_key = f"experiment-{abbr}-{chapter}-{str(experiment.get('experimentId') or '')[-8:]}"
    focus_options = ["royal_road_live", "patreon_early", "youtube_release", "catch_up_archive"]
    focus = focus_options[int(content_hash(variant_id)[:4], 16) % len(focus_options)]
    cta_name = focus
    primary_cta = focused_social_cta(abbr, focus, f"variant_{variant_id}", "variant")
    instagram = "\n".join(
        [
            f"{novel} - {title}",
            "",
            opening,
            caption if caption != opening else "",
            primary_cta,
            "",
            links,
            "",
            profile["hashtags"],
        ]
    ).replace("\n\n\n", "\n\n").strip()
    x_destination = "Read now: link in bio."
    x = "\n\n".join([opening, x_destination, profile["x_hashtags"]]).strip()
    if len(x) > 275:
        available = max(24, 275 - len(x_destination) - len("\n#AzureInkblade") - 1)
        compact_opening = clean_teaser_text(opening, available, max_words=16)
        x = f"{compact_opening}\n{x_destination}\n#AzureInkblade"
    if len(x) > 275:
        x = f"{x_destination}\n#AzureInkblade"
    facebook = "\n\n".join(
        [
            f"{novel} - {title}",
            opening,
            caption if caption != opening else "",
            primary_cta,
            "Read the chapter and follow Azure Inkblade across the main story channels.",
            links,
            "#webnovel #royalroad #serialfiction #progressionfantasy",
        ]
    ).replace("\n\n\n", "\n\n").strip()
    short_caption = "\n".join(
        [
            opening,
            short_destination_copy(abbr, chapter)["links"],
            "",
            profile["hashtags"],
        ]
    ).strip()
    return {
        "instagram": track_copy_links(instagram, abbr, "instagram", campaign_key, variant_id),
        "x": x,
        "facebook": track_copy_links(facebook, abbr, "facebook", campaign_key, variant_id),
        "tiktok": track_copy_links(short_caption, abbr, "tiktok", campaign_key, variant_id),
        "instagram_reel": track_copy_links(short_caption, abbr, "instagram-reel", campaign_key, variant_id),
        "alt_text": f"Variant promo image for {novel} Chapter {chapter}: {opening}",
        "primary_cta": cta_name,
        "tracking_campaign": campaign_key,
    }


def variant_visual_seed(experiment: dict[str, Any], variant: dict[str, Any]) -> str:
    candidates = [
        str(variant.get("quote") or ""),
        str(variant.get("openingText") or ""),
        str(variant.get("caption") or ""),
        str(variant.get("visual") or ""),
        str(variant.get("visualPrompt") or ""),
        str(experiment.get("strongest_moment") or ""),
    ]
    for candidate in candidates:
        cleaned = clean_teaser_text(candidate, 180, max_words=28)
        if len(cleaned.split()) >= 4:
            return cleaned
    return clean_teaser_text(str(experiment.get("title") or "chapter scene"), 140, max_words=18)


def variant_visual_brief(experiment: dict[str, Any], variant: dict[str, Any], *, vertical: bool = True) -> str:
    abbr = story_key(str(experiment.get("abbr") or ""))
    novel = str(experiment.get("novel") or NOVEL_NAMES.get(abbr, abbr))
    chapter = str(experiment.get("chapter") or "")
    title = str(experiment.get("title") or f"Chapter {chapter}").strip()
    seed = variant_visual_seed(experiment, variant)
    hook_type = str(variant.get("hookType") or "chapter teaser").replace("_", " ")
    ratio = "Vertical 9:16" if vertical else "Square social"
    return " ".join(
        [
            "variant_visual_first.",
            f"{ratio} cinematic web novel artwork for {novel}.",
            f"Specific quoted moment to depict: {seed}.",
            f"Chapter context only if needed: {title}.",
            f"Hook emotion: {hook_type}.",
            "Show the concrete action, object, setting, emotion, magic, danger, or character implied by that quoted moment.",
            "Avoid generic landscapes unless the quoted moment is mainly landscape.",
            "No text, no typography, no logos, no UI, no watermark.",
        ]
    )


def experiment_variant_visual_prompt(experiment: dict[str, Any], variant: dict[str, Any], *, vertical: bool = True) -> str:
    return variant_visual_brief(experiment, variant, vertical=vertical)


def create_fresh_social_image_from_caption(
    target: Path,
    *,
    abbr: str,
    novel: str,
    title: str,
    caption: str,
    hook: str = "",
    visual_brief: str = "",
    index: int = 1,
) -> str:
    prompt = visual_brief.strip() or " ".join(
        [
            "variant_visual_first.",
            f"Social promo artwork for {novel}.",
            f"Specific quoted moment to depict: {clean_teaser_text(hook or caption, 180, max_words=28)}",
            f"Chapter/title context only if needed: {title}.",
            "Create a fresh chapter-specific cinematic web novel image with one clear focal subject and readable mobile composition.",
            "No text, no typography, no logos, no UI, no watermark.",
        ]
    ).strip()
    target.parent.mkdir(parents=True, exist_ok=True)
    try:
        create_openai_image(prompt, target)
        archive_generated_promo_image(target, abbr, title, f"social-{index}")
        return "openai"
    except Exception as openai_exc:
        source = create_prompt_fallback_image(prompt, target, index, abbr, allow_banked=False, fresh=True)
        archive_generated_promo_image(target, abbr, title, f"social-{index}")
        return f"{source}; openai:{openai_exc}"


def write_variant_social_pack(experiment: dict[str, Any], variant: dict[str, Any], index: int) -> dict[str, Any]:
    abbr = story_key(str(experiment.get("abbr") or ""))
    chapter = str(experiment.get("chapter") or "")
    day = DAYS[(index - 1) % len(DAYS)]
    folder = EXPERIMENT_OUTPUT_DIR / f"{abbr.lower()}-{chapter}-{slugify(str(variant.get('hookType') or 'variant'))}-{content_hash(str(variant.get('variantId') or ''))[:8]}"
    reset_generated_folder(folder)
    copy = variant_platform_copy(experiment, variant)
    novel = str(experiment.get("novel") or NOVEL_NAMES.get(abbr, abbr))
    title = str(experiment.get("title") or f"Chapter {chapter}")
    image_target = folder / f"{abbr}_{chapter}_variant_{index}.png"
    visual_brief = experiment_variant_visual_prompt(experiment, variant, vertical=False)
    image_source = create_fresh_social_image_from_caption(
        image_target,
        abbr=abbr,
        novel=novel,
        title=title,
        caption=str(variant.get("caption") or ""),
        hook=str(variant.get("openingText") or ""),
        visual_brief=visual_brief,
        index=index,
    )
    payload = {
        "kind": "experiment_social_pack",
        "experimentId": experiment.get("experimentId"),
        "variantId": variant.get("variantId"),
        "variantStatus": variant.get("status"),
        "hookType": variant.get("hookType"),
        "openingText": variant.get("openingText"),
        "abbr": abbr,
        "novel": experiment.get("novel"),
        "chapter": chapter,
        "title": experiment.get("title"),
        "day": day,
        "folder": str(folder),
        "image": str(image_target),
        "image_source": image_source,
        "visual_prompt": visual_brief,
        "visual_seed": variant_visual_seed(experiment, variant),
        **copy,
    }
    (folder / "instagram.txt").write_text(copy["instagram"] + "\n", encoding="utf-8")
    (folder / "x.txt").write_text(copy["x"] + "\n", encoding="utf-8")
    (folder / "facebook.txt").write_text(copy["facebook"] + "\n", encoding="utf-8")
    (folder / "alt-text.txt").write_text(copy["alt_text"] + "\n", encoding="utf-8")
    (folder / "metadata.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")
    return payload


def write_variant_short_pack(experiment: dict[str, Any], variant: dict[str, Any], index: int) -> dict[str, Any]:
    abbr = story_key(str(experiment.get("abbr") or ""))
    chapter = str(experiment.get("chapter") or "")
    opening = str(variant.get("openingText") or "")
    novel = str(experiment.get("novel") or NOVEL_NAMES.get(abbr, abbr))
    visual_prompt = experiment_variant_visual_prompt(experiment, variant, vertical=True)
    target_folder = TIKTOK_OUTPUT_DIR / f"{abbr.lower()}-{chapter}-{slugify(str(variant.get('hookType') or 'variant'))}-{content_hash(str(variant.get('variantId') or ''))[:8]}"
    if target_folder.exists():
        shutil.rmtree(target_folder)
    target_folder.mkdir(parents=True, exist_ok=True)
    copy = variant_platform_copy(experiment, variant)
    images: list[str] = []
    prompts = [
        f"{visual_prompt}. Scene variation {slot}: keep the same quoted moment, change camera angle and composition."
        for slot in range(1, 4)
    ]
    used_image_hashes: set[str] = set()
    for slot, prompt in enumerate(prompts, start=1):
        target = target_folder / f"variant-{slot}.png"
        try:
            create_unique_prompt_fallback_image(
                prompt,
                target,
                slot,
                abbr,
                used_hashes=used_image_hashes,
                allow_banked=False,
                fresh=True,
            )
        except Exception:
            create_fallback_image(f"{prompt} fresh-build-{time.time_ns()}", target, slot)
            used_image_hashes.add(image_file_fingerprint(target))
        images.append(str(target))
    outro_image = prepare_tiktok_outro_image(
        target_folder, abbr, novel, chapter,
        style=experiment.get("style") or experiment.get("loraTrack") or "comic-style",
    )
    images.append(outro_image)
    sounds = list_tiktok_assets().get("sounds", [])
    if not sounds:
        raise RuntimeError("No TikTok sound files were found.")
    sound_source = Path(random.choice(sounds)["path"])
    sound_target = target_folder / sound_source.name
    shutil.copy2(sound_source, sound_target)
    overlays = [
        reel_overlay_text(opening, limit=48),
        reel_overlay_text(str(variant.get("caption") or opening), limit=48),
        reel_overlay_text(f"{novel} Chapter {chapter}", limit=48),
        reel_overlay_text(f"Read {novel} on Royal Road", limit=58),
    ]
    metadata = {}
    metadata.update(
        {
            "kind": "experiment_short_pack",
            "experimentId": experiment.get("experimentId"),
            "variantId": variant.get("variantId"),
            "variantStatus": variant.get("status"),
            "hookType": variant.get("hookType"),
            "openingText": opening,
            "abbr": abbr,
            "novel": novel,
            "chapter": chapter,
            "images": images,
            "sound": str(sound_target),
            "folder": str(target_folder),
            "caption": copy["tiktok"],
            "instagram_reel_caption": copy["instagram_reel"],
            "youtube_shorts_disabled": True,
            "youtube_shorts_reason": "Experiment variants skip YouTube Shorts to preserve the daily YouTube upload limit.",
            "visual_prompt": visual_prompt,
            "visual_seed": variant_visual_seed(experiment, variant),
            "image_generation_mode": "fresh_caption_based",
            "video_overlays": overlays,
        }
    )
    (target_folder / "caption.txt").write_text(copy["tiktok"] + "\n", encoding="utf-8")
    (target_folder / "instagram-reel-caption.txt").write_text(copy["instagram_reel"] + "\n", encoding="utf-8")
    (target_folder / "youtube-shorts-disabled.txt").write_text(
        "Experiment variant packs intentionally skip YouTube Shorts to preserve the daily YouTube upload limit.\n",
        encoding="utf-8",
    )
    (target_folder / "sound.txt").write_text(str(sound_target) + "\n", encoding="utf-8")
    (target_folder / "metadata.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    write_tiktok_video_helper(target_folder, images, sound_target, overlays=overlays)
    return metadata


def build_posts_from_approved_experiment_variants(experiment_id: str, limit: int = 3) -> dict[str, Any]:
    store = load_content_experiments()
    experiment = next((item for item in store.get("experiments", []) if item.get("experimentId") == experiment_id), None)
    if not experiment:
        raise RuntimeError("Experiment was not found.")
    selected = select_test_variants(experiment, max(1, min(int(limit or 3), 3)))
    if not selected:
        raise RuntimeError("No usable variants found. Generate or keep at least one variant that is not rejected or retired.")
    packs = []
    errors = []
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    for index, variant in enumerate(selected, start=1):
        entry = {"variantId": variant.get("variantId"), "hookType": variant.get("hookType"), "status": variant.get("status")}
        try:
            entry["social"] = write_variant_social_pack(experiment, variant, index)
        except Exception as exc:
            errors.append({"variantId": variant.get("variantId"), "step": "social", "error": str(exc)})
        try:
            entry["shorts"] = write_variant_short_pack(experiment, variant, index)
        except Exception as exc:
            errors.append({"variantId": variant.get("variantId"), "step": "shorts", "error": str(exc)})
        variant.setdefault("postPacks", []).append(
            {
                "builtAt": now,
                "socialFolder": entry.get("social", {}).get("folder", ""),
                "shortsFolder": entry.get("shorts", {}).get("folder", ""),
            }
        )
        try:
            previous_uses = int(variant.get("timesUsed") or 0)
        except (TypeError, ValueError):
            previous_uses = 0
        variant["timesUsed"] = previous_uses + 1
        variant["lastUsedAt"] = now
        variant["selectionWeight"] = round(1.0 / (1.0 + int(variant["timesUsed"])), 4)
        variant["status"] = "selected_for_test" if variant.get("status") == "draft" else variant.get("status")
        packs.append(entry)
    experiment["lastTestSetBuiltAt"] = now
    experiment["lastTestSetVariantIds"] = [str(variant.get("variantId") or "") for variant in selected]
    experiment["lastTestSetSelectionMode"] = "weighted_random_three_with_reuse_penalty"
    save_content_experiments(store)
    return {
        "message": f"Built {len(packs)} weighted random variant test pack(s). Review before posting.",
        "experimentId": experiment_id,
        "packs": packs,
        "errors": errors,
        "store": content_experiment_overview(),
    }


def experiment_recommendations(store: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    store = store or load_content_experiments()
    buckets: dict[str, dict[str, Any]] = {}
    for experiment in store.get("experiments", []):
        abbr = story_key(str(experiment.get("abbr") or ""))
        if not abbr:
            continue
        bucket = buckets.setdefault(
            abbr,
            {
                "abbr": abbr,
                "novel": NOVEL_NAMES.get(abbr, abbr),
                "winnerTypes": {},
                "approvedCount": 0,
                "rejectedCount": 0,
                "bestVariant": None,
                "fatigueFlags": [],
                "nextAction": "",
            },
        )
        bucket["fatigueFlags"].extend(experiment.get("package", {}).get("fatigue_flags", [])[:3])
        for variant in experiment.get("variants", []):
            status = str(variant.get("status") or "draft")
            hook_type = str(variant.get("hookType") or "unknown")
            if status == "winner":
                bucket["winnerTypes"][hook_type] = bucket["winnerTypes"].get(hook_type, 0) + 1
            if status == "approved":
                bucket["approvedCount"] += 1
            if status == "rejected":
                bucket["rejectedCount"] += 1
            if variant.get("score") is not None:
                current = bucket.get("bestVariant")
                if not current or float(variant.get("score") or 0) > float(current.get("score") or 0):
                    bucket["bestVariant"] = {
                        "variantId": variant.get("variantId"),
                        "hookType": hook_type,
                        "openingText": variant.get("openingText"),
                        "score": variant.get("score"),
                    }
    recommendations = []
    for bucket in buckets.values():
        winners = sorted(bucket["winnerTypes"].items(), key=lambda item: item[1], reverse=True)
        if winners:
            bucket["nextAction"] = f"Favor {winners[0][0]} hooks, but keep one experimental variant in rotation."
        elif bucket.get("bestVariant"):
            bucket["nextAction"] = f"Use the highest scoring {bucket['bestVariant']['hookType']} variant as the next style reference."
        elif bucket["approvedCount"]:
            bucket["nextAction"] = "Use approved variants next, then collect metrics."
        else:
            bucket["nextAction"] = "Review variants and mark at least one approved or winner."
        bucket["fatigueFlags"] = list(dict.fromkeys(bucket["fatigueFlags"]))[:5]
        recommendations.append(bucket)
    recommendations.sort(key=lambda item: item["abbr"])
    return recommendations


def content_experiment_overview() -> dict[str, Any]:
    store = load_content_experiments()
    experiments = sorted(store.get("experiments", []), key=lambda item: str(item.get("createdAt") or ""), reverse=True)
    compact = []
    for experiment in experiments[:40]:
        variants = experiment.get("variants", [])
        best = None
        scored = [variant for variant in variants if variant.get("score") is not None]
        if scored:
            best = max(scored, key=lambda item: float(item.get("score") or 0))
        compact.append(
            {
                "experimentId": experiment.get("experimentId"),
                "status": experiment.get("status"),
                "abbr": experiment.get("abbr"),
                "novel": experiment.get("novel"),
                "chapter": experiment.get("chapter"),
                "title": experiment.get("title"),
                "createdAt": experiment.get("createdAt"),
                "source": experiment.get("package", {}).get("source"),
                "variantCount": len(variants),
                "fatigueFlags": experiment.get("package", {}).get("fatigue_flags", []),
                "bestVariant": best,
                "variants": variants[:10],
            }
        )
    return {
        "schemaVersion": store.get("schemaVersion", 1),
        "experiments": compact,
        "weights": store.get("weights", DEFAULT_EXPERIMENT_WEIGHTS),
        "metricsCount": len(store.get("metrics", [])),
        "recommendations": experiment_recommendations(store),
        "file": str(CONTENT_EXPERIMENTS_FILE),
        "brandBrainFile": str(BRAND_BRAIN_FILE),
    }


def stable_chapter_folder(root: Path, kind: str, title: str, abbr: str = "", chapter: str | int = "") -> Path:
    abbr_part = slugify(abbr) if abbr else "manual"
    chapter_part = slugify(str(chapter)) if str(chapter).strip() else "chapter"
    title_part = slugify(title)[:42]
    if kind == "tiktok":
        return root / f"{abbr_part}-{chapter_part}"
    return root / f"{abbr_part}-{chapter_part}-{title_part}"


def normalize_chapter_id(*args, **kwargs):
    return promo_copy.normalize_chapter_id(*args, **kwargs)
def path_is_within(path: Path, roots: list[Path]) -> bool:
    try:
        resolved = path.resolve()
    except OSError:
        resolved = path.absolute()
    for root in roots:
        try:
            root_resolved = root.resolve()
            if os.path.commonpath([str(resolved), str(root_resolved)]) == str(root_resolved):
                return True
        except (OSError, ValueError):
            continue
    return False


def resolve_youtube_pack_folder(folder_value: str, *, include_campaigns: bool = False) -> Path:
    raw = urllib.parse.unquote(str(folder_value or "")).strip().strip('"').strip("'")
    if raw.startswith("file:///"):
        raw = urllib.request.url2pathname(urllib.parse.urlparse(raw).path)
    raw = raw.replace("/", os.sep) if re.match(r"^[A-Za-z]:/", raw) else raw
    allowed_roots = [YOUTUBE_OUTPUT_DIR.resolve(), STORY_HOOK_OUTPUT_DIR.resolve(), MANUAL_VIDEO_OUTPUT_DIR.resolve()]
    if include_campaigns:
        allowed_roots.append(OUTPUT_DIR.resolve())
    candidates: list[Path] = []
    if raw:
        path = Path(raw)
        candidates.append(path)
        if not path.is_absolute():
            candidates.extend(root / raw for root in allowed_roots)
    for candidate in candidates:
        try:
            resolved = candidate.resolve()
        except OSError:
            resolved = candidate.absolute()
        if path_is_within(resolved, allowed_roots):
            return resolved
    raise RuntimeError("YouTube folder is not valid.")


def story_hook_folder_has_rebuild_source(folder: Path) -> bool:
    if (folder / "build_youtube_video.py").exists():
        return True
    for name in ["story-script.txt", "chapter-text.txt", "youtube-narration-source.txt", "story.txt", "script.txt"]:
        source = folder / name
        if source.exists():
            try:
                if len(source.read_text(encoding="utf-8", errors="replace").strip().split()) >= 80:
                    return True
            except OSError:
                pass
    metadata = read_json_safe(folder / "metadata.json")
    if isinstance(metadata, dict):
        for key in ["story", "storyText", "fullStory", "narration", "youtubeNarration"]:
            value = metadata.get(key)
            if isinstance(value, str) and len(value.strip().split()) >= 80:
                return True
    return False


def latest_ready_story_hook_folder() -> Path | None:
    status = _phase2_load_blob("storyHookStatus", STORY_HOOK_STATUS_FILE)
    if not isinstance(status, dict):
        status = {}
    folder_value = str(status.get("folder") or "")
    if status.get("ready") and folder_value:
        try:
            folder = Path(folder_value).resolve()
            if (
                path_is_within(folder, [STORY_HOOK_OUTPUT_DIR.resolve()])
                and (folder / "metadata.json").exists()
                and story_hook_folder_has_rebuild_source(folder)
            ):
                return folder
        except Exception:
            pass
    if STORY_HOOK_OUTPUT_DIR.exists():
        folders = sorted(
            [
                path for path in STORY_HOOK_OUTPUT_DIR.iterdir()
                if path.is_dir() and (path / "metadata.json").exists() and story_hook_folder_has_rebuild_source(path)
            ],
            key=lambda path: path.stat().st_mtime,
            reverse=True,
        )
        return folders[0].resolve() if folders else None
    return None


def resolve_youtube_pack_folder_or_latest_story_hook(folder_value: str) -> Path:
    raw = str(folder_value or "").strip()
    if raw:
        folder = resolve_youtube_pack_folder(raw)
        if path_is_within(folder, [STORY_HOOK_OUTPUT_DIR.resolve()]) and not story_hook_folder_has_rebuild_source(folder):
            latest = latest_ready_story_hook_folder()
            if latest:
                return latest
        return folder
    latest = latest_ready_story_hook_folder()
    if latest:
        return latest
    return resolve_youtube_pack_folder(raw)


def read_metadata(folder: Path) -> dict[str, Any]:
    metadata_path = folder / "metadata.json"
    if not metadata_path.exists():
        return {}
    try:
        data = json.loads(metadata_path.read_text(encoding="utf-8-sig"))
        return normalize_pack_metadata(folder, data, persist=False)
    except Exception:
        return {}


PACK_ACTIONABLE_STATUSES = {
    "needs_image_review",
    "needs_video_build",
    "ready_to_queue",
    "manual_review_ready",
    "failed",
}


PACK_DONE_STATUSES = {"queued", "posted", "uploaded", "dismissed", "archived"}


def pack_root_label(folder: Path) -> str:
    roots = [
        ("campaign", OUTPUT_DIR),
        ("social", SOCIAL_OUTPUT_DIR),
        ("tiktok", TIKTOK_OUTPUT_DIR),
        ("youtube", YOUTUBE_OUTPUT_DIR),
        ("story-hook", STORY_HOOK_OUTPUT_DIR),
        ("manual-video", MANUAL_VIDEO_OUTPUT_DIR),
        ("experiment", EXPERIMENT_OUTPUT_DIR),
    ]
    for label, root in roots:
        try:
            if path_is_within(folder.resolve(), [root.resolve()]):
                return label
        except Exception:
            continue
    return "pack"


def pack_type_for_folder(folder: Path, metadata: dict[str, Any]) -> str:
    kind = str(metadata.get("kind") or "").strip()
    if kind:
        return kind
    label = pack_root_label(folder)
    if label == "campaign":
        return "campaign_promo"
    if label == "social":
        return "daily_social"
    if label == "tiktok":
        return "deep_tiktok" if folder.name.lower().endswith("-deep") else "short_reel"
    if label == "youtube":
        return "full_youtube"
    if label == "story-hook":
        return "story_hook_video"
    if label == "manual-video":
        return "manual_video"
    if label == "experiment":
        return "experiment"
    return "pack"


def pack_id_for_folder(folder: Path, metadata: dict[str, Any]) -> str:
    existing = str(metadata.get("packId") or metadata.get("pack_id") or "").strip()
    if existing:
        return existing
    abbr = story_key(str(metadata.get("abbr") or ""))
    chapter = str(metadata.get("chapter") or metadata.get("chapter_number") or "").strip()
    pack_type = slugify(pack_type_for_folder(folder, metadata)) or "pack"
    readable = "-".join(part for part in [pack_type, abbr.lower(), slugify(chapter), slugify(folder.name)[:42]] if part)
    digest = content_hash(str(folder.resolve()).lower())[:10]
    return f"{readable}-{digest}"[:140]


def buffer_success_count(metadata: dict[str, Any]) -> int:
    total = 0
    for entry in metadata.get("buffer_posts", []) or []:
        for post in entry.get("responses", []) or []:
            if isinstance(post, dict) and not post.get("skipped"):
                total += 1
    for entry in metadata.get("one_click_daily_uploads", []) or []:
        for post in entry.get("buffer_posts", []) or []:
            if isinstance(post, dict) and not post.get("skipped"):
                total += 1
        for extra in entry.get("extra_buffer_results", []) or []:
            result = extra.get("result") if isinstance(extra, dict) else {}
            for post in (result or {}).get("posts", []) or []:
                if isinstance(post, dict) and not post.get("skipped"):
                    total += 1
    return total


def pack_status_for_folder(folder: Path, metadata: dict[str, Any]) -> str:
    explicit = str(metadata.get("packStatusOverride") or "").strip()
    if explicit:
        return explicit
    if metadata.get("dismissed") or metadata.get("archived"):
        return "archived"
    if metadata.get("lastFailure") or metadata.get("buildError") or metadata.get("error"):
        return "failed"
    pack_type = pack_type_for_folder(folder, metadata)
    if any(metadata.get(key) for key in ["manual_x_posted", "manual_facebook_posted", "manual_patreon_posted", "manual_tiktok_posted"]):
        return "posted"
    if metadata.get("youtubeUploaded") or metadata.get("youtubeScheduled") or metadata.get("uploadId"):
        return "uploaded"
    if buffer_success_count(metadata) > 0 or metadata.get("manual_buffer_queued"):
        return "queued"
    if pack_type == "deep_tiktok":
        selected = [Path(str(item)).name.lower() for item in metadata.get("images", []) or [] if str(item or "").strip()]
        approved = {Path(str(item)).name.lower() for item in metadata.get("approved_images", []) or [] if str(item or "").strip()}
        rejected = {Path(str(item)).name.lower() for item in metadata.get("rejected_images", []) or [] if str(item or "").strip()}
        if metadata.get("videoNeedsRebuild") or not (folder / "tiktok-video.mp4").exists():
            return "needs_video_build"
        if selected and (any(name in rejected for name in selected) or any(name not in approved for name in selected)):
            return "needs_image_review"
        return "ready_to_queue"
    if pack_type in {"short_reel", "experiment_short"}:
        selected = [Path(str(item)).name.lower() for item in metadata.get("images", []) or [] if str(item or "").strip()]
        rejected = {Path(str(item)).name.lower() for item in metadata.get("rejected_images", []) or [] if str(item or "").strip()}
        if metadata.get("videoNeedsRebuild") or not (folder / "tiktok-video.mp4").exists():
            return "needs_video_build"
        if selected and any(name in rejected for name in selected):
            return "needs_image_review"
        return "ready_to_queue"
    if pack_type in {"full_youtube", "story_hook_video", "manual_video"}:
        video = folder / "youtube-video.mp4"
        if not video.exists():
            return "needs_video_build"
        if not media_file_valid(video, "v:0") or not media_file_valid(video, "a:0"):
            return "needs_video_build"
        return "ready_to_upload"
    if pack_type in {"daily_social", "experiment_social_pack"}:
        return "ready_to_queue" if metadata.get("image") else "needs_image_review"
    if pack_type == "campaign_promo":
        return "manual_review_ready" if metadata.get("images") else "needs_image_review"
    return "manual_review_ready"


def normalize_pack_metadata(folder: Path, metadata: dict[str, Any], *, persist: bool = False) -> dict[str, Any]:
    if not isinstance(metadata, dict):
        return {}
    try:
        resolved = folder.resolve()
    except Exception:
        resolved = folder
    roots = [OUTPUT_DIR, SOCIAL_OUTPUT_DIR, TIKTOK_OUTPUT_DIR, YOUTUBE_OUTPUT_DIR, STORY_HOOK_OUTPUT_DIR, MANUAL_VIDEO_OUTPUT_DIR, EXPERIMENT_OUTPUT_DIR]
    if not path_is_within(resolved, [root.resolve() for root in roots]):
        return metadata
    normalized = dict(metadata)
    normalized["packId"] = pack_id_for_folder(resolved, normalized)
    normalized["packType"] = pack_type_for_folder(resolved, normalized)
    normalized["packStatus"] = pack_status_for_folder(resolved, normalized)
    normalized["packFolder"] = str(resolved)
    normalized.setdefault("folder", str(resolved))
    if persist:
        current = read_json_safe(resolved / "metadata.json")
        if isinstance(current, dict):
            current.update({key: normalized[key] for key in ["packId", "packType", "packStatus", "packFolder", "folder"] if key in normalized})
            current["packStatusUpdatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
            write_json_atomic(resolved / "metadata.json", current)
    return normalized


def pack_control_summary(folder: str, *, include_quality: bool = False) -> dict[str, Any]:
    if not str(folder or "").strip():
        recent = pack_health_panel(10, fast=True)
        return {
            "folder": "",
            "packId": "",
            "packType": "",
            "packStatus": "no_pack_selected",
            "actionable": False,
            "message": "No pack selected. Showing recent pack health so the UI can choose one.",
            "recent": recent,
        }
    target = Path(folder).resolve()
    metadata_path = target / "metadata.json"
    if not metadata_path.exists():
        raise RuntimeError("This folder does not contain pack metadata.")
    metadata = normalize_pack_metadata(target, read_json_safe(metadata_path), persist=True)
    text_kind = "tiktok" if str(target).startswith(str(TIKTOK_OUTPUT_DIR.resolve())) else "instagram"
    gate = folder_quality_gate(str(target), text_kind) if include_quality else {}
    return {
        "folder": str(target),
        "packId": metadata.get("packId"),
        "packType": metadata.get("packType"),
        "packStatus": metadata.get("packStatus"),
        "abbr": metadata.get("abbr"),
        "novel": metadata.get("novel"),
        "chapter": metadata.get("chapter") or metadata.get("chapter_number"),
        "title": metadata.get("title"),
        "qualityGate": gate,
        "actionable": metadata.get("packStatus") in PACK_ACTIONABLE_STATUSES,
    }


def active_chapter_path_status() -> dict[str, Any]:
    state = load_chapter_path_state()
    novels = []
    for abbr, novel in NOVEL_NAMES.items():
        item = state.get("novels", {}).get(abbr, {}) if isinstance(state.get("novels"), dict) else {}
        next_chapter = active_chapter_path_next(abbr, "banner")
        novels.append(
            {
                "abbr": abbr,
                "novel": novel,
                "nextChapter": next_chapter or item.get("nextChapter") or state.get("nextChapter") or "",
                "lastCompletedChapter": item.get("lastCompletedChapter") or state.get("lastCompletedChapter") or "",
                "updatedAt": item.get("updatedAt") or state.get("updatedAt") or "",
            }
        )
    return {
        "active": bool(state.get("active")),
        "nextChapter": state.get("nextChapter") or "",
        "updatedAt": state.get("updatedAt") or "",
        "anchorDate": state.get("anchorDate") or "",
        "releaseDays": state.get("releaseDays") or CHAPTER_RELEASE_DAYS,
        "novels": novels,
    }


def pack_health_item(folder: Path, fast: bool = True) -> dict[str, Any]:
    metadata = read_metadata(folder)
    summary = pack_control_summary(str(folder), include_quality=False)
    is_tiktok_pack = str(folder.resolve()).startswith(str(TIKTOK_OUTPUT_DIR.resolve()))
    is_social_pack = str(folder.resolve()).startswith(str(SOCIAL_OUTPUT_DIR.resolve()))
    is_campaign_pack = str(folder.resolve()).startswith(str(OUTPUT_DIR.resolve()))
    buffer_text_kind = "tiktok" if is_tiktok_pack else "instagram"
    has_required_buffer_media = not is_tiktok_pack or (folder / "tiktok-video.mp4").exists()
    media_paths = media_files_for_folder(folder)
    media = []
    public_url_count = 0
    for path in media_paths:
        url = "" if fast else (public_url_for_generated_file(path) or "")
        if url:
            public_url_count += 1
        suffix = path.suffix.lower()
        if fast:
            valid_media = path.exists() and path.stat().st_size > 0
        elif suffix in VIDEO_EXTENSIONS:
            valid_media = media_file_valid(path, "v:0")
        elif suffix in AUDIO_EXTENSIONS:
            valid_media = media_file_valid(path, "a:0")
        else:
            valid_media = path.exists() and path.stat().st_size > 0
        media.append(
            {
                "path": str(path),
                "name": path.name,
                "exists": path.exists(),
                "sizeMB": round(path.stat().st_size / 1024 / 1024, 2) if path.exists() else 0,
                "publicUrl": url,
                "valid": valid_media,
            }
        )
    errors: list[str] = []
    warnings: list[str] = []
    if not metadata:
        errors.append("metadata.json is missing or unreadable.")
    if not media:
        warnings.append("No media files were found for this pack.")
    elif not fast and public_url_count < len(media):
        warnings.append(f"{len(media) - public_url_count} media file(s) do not have a known public URL yet.")
    abbr = story_key(str(summary.get("abbr") or ""))
    chapter = summary.get("chapter")
    active_next = active_chapter_path_next(abbr, "health") if abbr else None
    try:
        chapter_int = int(chapter or 0)
    except (TypeError, ValueError):
        chapter_int = 0
    if active_next and chapter_int and chapter_int != active_next and not metadata.get("experimentId"):
        warnings.append(f"Chapter path mismatch: active path is Ch. {active_next}, this pack is Ch. {chapter_int}.")
    status = str(summary.get("packStatus") or "")
    text_kind = daily_upload_text_kind(folder, metadata)
    if fast:
        review_gate = {"ok": True, "warnings": [], "errors": []}
        review_required = {
            "required": bool(status == "needs_image_review" and not metadata.get("imageReviewApprovedAt")),
            "reason": "Saved pack status says image review is needed." if status == "needs_image_review" else "",
            "score": metadata.get("imageQualityScore") or metadata.get("qualityScore") or "",
        }
    else:
        review_gate = approved_image_upload_gate(folder, metadata, text_kind) if (is_tiktok_pack or is_social_pack or is_campaign_pack) and metadata else {"ok": True}
        review_required = image_review_required_for_buffer(folder, metadata, review_gate) if (is_tiktok_pack or is_social_pack or is_campaign_pack) and metadata else {"required": False}
    if errors:
        next_action = "Repair metadata or rebuild this pack."
    elif status in PACK_DONE_STATUSES:
        next_action = "No action needed."
    elif status == "needs_image_review":
        next_action = "Review or regenerate images."
    elif status == "needs_video_build":
        next_action = "Build or rebuild video."
    elif not fast and public_url_count < len(media):
        next_action = "Publish media before pushing to Buffer."
    elif review_required.get("required"):
        next_action = "Open the pack, review images, then approve the pack before Buffer."
    elif status in {"ready_to_queue", "manual_review_ready", "ready_to_upload"}:
        next_action = "Ready for the next platform action."
    else:
        next_action = "Review pack state."
    last_failure = metadata.get("lastFailure") or metadata.get("last_recovery") or metadata.get("buildError") or metadata.get("error") or ""
    return {
        **summary,
        "mediaCount": len(media),
        "publicUrlCount": public_url_count,
        "bufferTextKind": buffer_text_kind,
        "bufferLabel": "Push Shorts/Reels to Buffer" if is_tiktok_pack else "Push Instagram to Buffer",
        "canPushToBuffer": bool(
            (is_tiktok_pack or is_social_pack or is_campaign_pack)
            and has_required_buffer_media
            and status in {"ready_to_queue", "manual_review_ready"}
            and not review_required.get("required")
            and not errors
        ),
        "imageReviewRequired": review_required,
        "media": media[:12],
        "errors": errors,
        "warnings": warnings,
        "lastError": last_failure,
        "nextAction": next_action,
        "activeChapter": active_next or "",
        "chapterPathMatch": not active_next or not chapter_int or chapter_int == active_next or bool(metadata.get("experimentId")),
        "modifiedAt": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(folder.stat().st_mtime)),
    }


def recent_metadata_folders(root: Path, max_count: int) -> tuple[list[Path], int]:
    if not root.exists():
        return [], 0
    candidates: list[tuple[float, Path]] = []
    seen = 0
    try:
        with os.scandir(root) as entries:
            for entry in entries:
                if not entry.is_dir():
                    continue
                metadata_path = Path(entry.path) / "metadata.json"
                if not metadata_path.exists():
                    continue
                seen += 1
                try:
                    modified = entry.stat().st_mtime
                except OSError:
                    modified = 0.0
                candidates.append((modified, Path(entry.path)))
    except OSError:
        return [], 0
    newest = heapq.nlargest(max(1, max_count), candidates, key=lambda item: item[0])
    return [path for _, path in newest], seen


def pack_health_panel(limit: int = 30, folder: str = "", fast: bool = True) -> dict[str, Any]:
    roots = [OUTPUT_DIR, SOCIAL_OUTPUT_DIR, TIKTOK_OUTPUT_DIR, YOUTUBE_OUTPUT_DIR, STORY_HOOK_OUTPUT_DIR, MANUAL_VIDEO_OUTPUT_DIR, EXPERIMENT_OUTPUT_DIR]
    folders: list[Path] = []
    selected_folder: Path | None = None
    total_candidates = 0
    if folder:
        try:
            candidate = Path(str(folder)).resolve()
            if candidate.exists() and candidate.is_dir() and any(candidate.is_relative_to(root.resolve()) for root in roots):
                selected_folder = candidate
        except Exception:
            selected_folder = None
    limit_value = max(1, int(limit or 30))
    if fast:
        per_root_limit = max(4, min(12, math.ceil(limit_value / 2)))
        for root in roots:
            root_folders, root_total = recent_metadata_folders(root, per_root_limit)
            total_candidates += root_total
            folders.extend(root_folders)
    else:
        for root in roots:
            if not root.exists():
                continue
            root_folders, root_total = recent_metadata_folders(root, max(1, min(300, limit_value * 4)))
            total_candidates += root_total
            folders.extend(root_folders)
    folders = sorted(folders, key=lambda path: path.stat().st_mtime, reverse=True)
    if selected_folder:
        folders = [selected_folder] + [path for path in folders if path.resolve() != selected_folder]
    folders = folders[: max(1, min(80 if fast else 200, limit_value))]
    items = []
    for folder in folders:
        try:
            items.append(pack_health_item(folder, fast=fast))
        except Exception as exc:
            items.append({"folder": str(folder), "errors": [str(exc)], "warnings": [], "nextAction": "Open folder and inspect metadata."})
    needs_attention = [
        item for item in items
        if item.get("errors") or item.get("warnings") or item.get("packStatus") in {"failed", "needs_image_review", "needs_video_build"}
    ]
    return {
        "generatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "chapterPath": active_chapter_path_status(),
        "count": len(items),
        "candidateCount": total_candidates,
        "fast": fast,
        "selectedFolder": str(selected_folder or ""),
        "needsAttention": len(needs_attention),
        "items": items,
    }


def button_preflight(folder: str, action: str = "") -> dict[str, Any]:
    action = str(action or "").strip() or "generic"
    target = Path(str(folder or "")).resolve()
    result: dict[str, Any] = {
        "ok": True,
        "action": action,
        "folder": str(target),
        "errors": [],
        "warnings": [],
        "repairs": [],
        "nextAction": "Continue.",
    }
    allowed_roots = [
        OUTPUT_DIR.resolve(),
        SOCIAL_OUTPUT_DIR.resolve(),
        TIKTOK_OUTPUT_DIR.resolve(),
        YOUTUBE_OUTPUT_DIR.resolve(),
        STORY_HOOK_OUTPUT_DIR.resolve(),
        MANUAL_VIDEO_OUTPUT_DIR.resolve(),
        EXPERIMENT_OUTPUT_DIR.resolve(),
    ]
    if not target.exists() or not path_is_within(target, allowed_roots):
        latest = None
        if action in {"youtube_build", "youtube_upload"} and not str(folder or "").strip():
            latest = latest_ready_story_hook_folder()
        if latest:
            result["warnings"].append("Requested folder was stale or missing. Switched to the newest valid story-hook pack.")
            result["repairs"].append({"type": "folder_fallback", "from": str(target), "to": str(latest)})
            target = latest
            result["folder"] = str(target)
        else:
            result["ok"] = False
            result["errors"].append("Folder is missing or outside the app workspace.")
            result["nextAction"] = "Open the pack list and choose a valid pack."
            return result
    metadata = read_metadata(target)
    if not metadata:
        result["ok"] = False
        result["errors"].append("metadata.json is missing or unreadable.")
    if str(target).startswith(str(STORY_HOOK_OUTPUT_DIR.resolve())) and action in {"youtube_build", "youtube_upload"}:
        if not story_hook_folder_has_rebuild_source(target):
            latest = latest_ready_story_hook_folder()
            if latest and latest != target:
                result["warnings"].append("Story-hook pack had no source text. Switched to the newest valid pack.")
                result["repairs"].append({"type": "story_hook_fallback", "from": str(target), "to": str(latest)})
                target = latest
                result["folder"] = str(target)
                metadata = read_metadata(target)
            else:
                result["ok"] = False
                result["errors"].append("Story-hook pack has no builder or story text.")
        if action == "youtube_build" and not (target / "build_youtube_video.py").exists() and story_hook_folder_has_rebuild_source(target):
            try:
                repair = ensure_youtube_builder_for_folder(target)
                result["repairs"].append({"type": "youtube_builder", **repair})
            except Exception as exc:
                result["ok"] = False
                result["errors"].append(str(exc))
    abbr = story_key(str(metadata.get("abbr") or ""))
    chapter = metadata.get("chapter") or metadata.get("chapter_number")
    try:
        chapter_int = int(chapter or 0)
    except (TypeError, ValueError):
        chapter_int = 0
    active_next = active_chapter_path_next(abbr, action) if abbr else None
    if active_next and chapter_int and chapter_int != active_next and not metadata.get("experimentId"):
        result["warnings"].append(f"This pack is Ch. {chapter_int}, but the active path is Ch. {active_next}.")
    if action in {"buffer", "one_click", "youtube_upload"}:
        media = media_files_for_folder(target)
        if not media:
            result["ok"] = False
            result["errors"].append("No media file was found for this action.")
        missing_urls = [path.name for path in media if not public_url_for_generated_file(path)]
        if missing_urls and action == "buffer":
            result["warnings"].append("Some media still needs publishing before Buffer can use it: " + ", ".join(missing_urls[:5]))
    if action == "youtube_upload":
        video = target / "youtube-video.mp4"
        if not media_file_valid(video, "v:0"):
            result["ok"] = False
            result["errors"].append("No valid YouTube MP4 exists yet.")
    result["health"] = pack_health_item(target) if (target / "metadata.json").exists() else {}
    if result["errors"]:
        result["ok"] = False
        result["nextAction"] = "Fix the listed issue before continuing."
    elif result["warnings"]:
        result["nextAction"] = "Review warning, then continue if intentional."
    return result


def current_pack_test(folder: str) -> dict[str, Any]:
    target = Path(str(folder or "")).resolve()
    allowed_roots = [
        OUTPUT_DIR.resolve(),
        SOCIAL_OUTPUT_DIR.resolve(),
        TIKTOK_OUTPUT_DIR.resolve(),
        YOUTUBE_OUTPUT_DIR.resolve(),
        STORY_HOOK_OUTPUT_DIR.resolve(),
        MANUAL_VIDEO_OUTPUT_DIR.resolve(),
        EXPERIMENT_OUTPUT_DIR.resolve(),
    ]
    generated_at = time.strftime("%Y-%m-%d %H:%M:%S")
    result: dict[str, Any] = {
        "ok": False,
        "folder": str(target),
        "generatedAt": generated_at,
        "summary": "",
        "checks": [],
        "blockers": [],
        "warnings": [],
        "nextAction": "Open a valid pack before testing.",
    }

    def dedupe(values: list[Any]) -> list[str]:
        seen: set[str] = set()
        output: list[str] = []
        for value in values:
            text = str(value or "").strip()
            if not text or text in seen:
                continue
            seen.add(text)
            output.append(text)
        return output

    def add_check(name: str, ok: bool, detail: str = "", severity: str = "info", data: dict[str, Any] | None = None) -> None:
        item = {
            "name": name,
            "ok": bool(ok),
            "detail": str(detail or ""),
            "severity": severity,
        }
        if data:
            item["data"] = data
        result["checks"].append(item)
        if not ok and severity == "blocker":
            result["blockers"].append(item["detail"] or name)
        elif not ok:
            result["warnings"].append(item["detail"] or name)

    if not str(folder or "").strip():
        add_check("Pack selected", False, "No pack is currently selected.", "blocker")
        result["summary"] = "No pack selected."
        return result
    if not target.exists() or not target.is_dir() or not path_is_within(target, allowed_roots):
        add_check("Pack folder", False, "Folder is missing or outside the app workspace.", "blocker")
        result["summary"] = "Pack folder is not valid."
        return result
    metadata_path = target / "metadata.json"
    metadata = read_metadata(target)
    add_check("Metadata", bool(metadata_path.exists() and metadata), "metadata.json loaded." if metadata else "metadata.json is missing or unreadable.", "blocker")
    if not metadata:
        result["summary"] = "Pack metadata is missing."
        result["nextAction"] = "Rebuild or reopen a valid pack."
        return result

    pack_type = pack_type_for_folder(target, metadata)
    text_kind = daily_upload_text_kind(target, metadata)
    gate = folder_quality_gate(str(target), text_kind)
    health = pack_health_item(target, fast=False)
    images = pack_review_images(target, metadata)
    media = media_files_for_folder(target)
    is_tiktok = path_is_within(target, [TIKTOK_OUTPUT_DIR.resolve()])
    is_social = path_is_within(target, [SOCIAL_OUTPUT_DIR.resolve()])
    is_campaign = path_is_within(target, [OUTPUT_DIR.resolve()])
    is_youtube = path_is_within(target, [YOUTUBE_OUTPUT_DIR.resolve(), STORY_HOOK_OUTPUT_DIR.resolve(), MANUAL_VIDEO_OUTPUT_DIR.resolve()])
    is_buffer_pack = is_tiktok or is_social or is_campaign or path_is_within(target, [EXPERIMENT_OUTPUT_DIR.resolve()])
    add_check("Pack identity", True, f"{pack_type} | {metadata.get('abbr', '')} Ch. {metadata.get('chapter') or metadata.get('chapter_number') or ''}".strip())
    add_check("Caption/text", not any("Post text/caption is blank" in str(item) for item in gate.get("errors") or []), "Text exists." if not any("Post text/caption is blank" in str(item) for item in gate.get("errors") or []) else "Post text or caption is blank.", "blocker")
    add_check("Quality gate", bool(gate.get("ok")), "Quality gate passed." if gate.get("ok") else "; ".join(gate.get("errors") or ["Quality gate failed."]), "blocker")

    rejected_names = {
        Path(str(item)).name.lower()
        for item in metadata.get("rejected_images", []) or []
        if str(item or "").strip()
    }
    image_names = {Path(image).name.lower() for image in images}
    selected_rejected = sorted(name for name in image_names if name in rejected_names)
    approved_names = {
        Path(str(item)).name.lower()
        for item in metadata.get("approved_images", []) or []
        if str(item or "").strip()
    }
    if images:
        missing_approval = sorted(name for name in image_names if name not in approved_names)
        needs_image_review = bool(health.get("imageReviewRequired", {}).get("required")) or bool(selected_rejected)
        approval_ok = not needs_image_review and not selected_rejected
        detail = "Images are approved." if approval_ok else "Review images before posting."
        if selected_rejected:
            detail = "Rejected image(s) are still selected: " + ", ".join(selected_rejected[:5])
        elif missing_approval and (is_tiktok or str(metadata.get("kind") or "") == "deep_tiktok"):
            detail = "Approve or reject all selected images before posting: " + ", ".join(missing_approval[:5])
            approval_ok = False
        add_check("Image approval", approval_ok, detail, "blocker" if not approval_ok else "info", {"approved": len(approved_names), "images": len(image_names)})
    else:
        add_check("Image approval", not (is_social or is_campaign), "No reviewable images were found." if not images else "Images found.", "blocker" if (is_social or is_campaign) else "warning")

    if is_tiktok:
        video = target / "tiktok-video.mp4"
        video_ok = video.exists() and media_file_valid(video, "v:0")
        duration = media_duration_seconds(video) if video.exists() else 0
        add_check("Short/Reel MP4", video_ok and duration >= 3, f"Duration: {duration:.2f}s" if video.exists() else "tiktok-video.mp4 is missing.", "blocker")
    elif is_youtube:
        video = target / "youtube-video.mp4"
        captions = target / "youtube-captions.srt"
        video_ok = video.exists() and media_file_valid(video, "v:0")
        add_check("YouTube MP4", video_ok, "youtube-video.mp4 exists and is valid." if video_ok else "youtube-video.mp4 is missing or invalid.", "blocker")
        add_check("YouTube captions", captions.exists(), "Captions file exists." if captions.exists() else "youtube-captions.srt is missing.", "blocker")
    else:
        add_check("Media files", bool(media), f"{len(media)} media file(s) found." if media else "No media files found.", "blocker")

    duplicate_folders = duplicate_folders_for_gate(target, metadata)
    add_check("Duplicate pack folders", not duplicate_folders, "No duplicate pack folders found." if not duplicate_folders else "Duplicate folder exists: " + duplicate_folders[0], "warning")
    duplicate_media = duplicate_media_inside_folder(target)
    add_check("Duplicate media", not duplicate_media, "No duplicate media inside this pack." if not duplicate_media else "Duplicate media: " + ", ".join(duplicate_media[:3]), "warning")

    if is_buffer_pack:
        public_media = [path for path in media if public_url_for_generated_file(path)]
        needs_public_url = is_tiktok or is_social
        public_ok = not needs_public_url or bool(public_media)
        add_check("Buffer media URL", public_ok, f"{len(public_media)} public media URL(s) available." if public_media else "Publish media to GitHub/R2 before Buffer can use it.", "blocker" if not public_ok else "info")
        preflight = button_preflight(str(target), "buffer")
        add_check("Buffer preflight", bool(preflight.get("ok")), preflight.get("nextAction") or "Buffer preflight passed.", "blocker" if not preflight.get("ok") else "info")
    else:
        add_check("Buffer media URL", True, "This pack is not a Buffer pack.")

    errors = list(gate.get("errors") or [])
    warnings = list(gate.get("warnings") or []) + list(health.get("warnings") or [])
    result["qualityGate"] = gate
    result["health"] = health
    result["media"] = [
        {
            "name": path.name,
            "path": str(path),
            "sizeMB": round(path.stat().st_size / 1024 / 1024, 2) if path.exists() else 0,
            "publicUrl": public_url_for_generated_file(path) or "",
        }
        for path in media[:12]
    ]
    result["blockers"] = dedupe([*result["blockers"], *errors])
    result["warnings"] = dedupe([*result["warnings"], *warnings])
    result["ok"] = not result["blockers"]
    result["summary"] = "Current pack is ready for the next action." if result["ok"] else "Current pack needs attention before posting."
    result["nextAction"] = "Use the pack action buttons when ready." if result["ok"] else (
        "Fix blockers above, then rerun Test This Pack."
    )
    return result


def reusable_pack_result(folder: Path, expected_hash: str = "", required_files: list[str] | None = None) -> dict[str, Any] | None:
    metadata = read_metadata(folder)
    if not metadata:
        return None
    if expected_hash and metadata.get("chapter_hash") != expected_hash:
        return None
    for name in required_files or []:
        if not (folder / name).exists():
            return None
    metadata["folder"] = str(folder)
    metadata["reused_existing_pack"] = True
    return metadata


def reset_generated_folder(folder: Path, keep_existing_media: bool = False) -> None:
    folder.mkdir(parents=True, exist_ok=True)
    if keep_existing_media:
        return
    for path in folder.iterdir():
        if path.is_file():
            path.unlink()
        elif path.is_dir():
            shutil.rmtree(path)


def iso_today() -> date:
    return date.today()


def ensure_schedule_file() -> dict[str, Any]:
    # SC-3 cutover: SQLite (state_snapshots.postingSchedule) is the source of
    # truth. Fail-soft to the legacy JSON if the DB read fails, so the live app
    # never breaks if the database is unavailable.
    try:
        stored = sr.load(ROOT)
        if stored is not None:
            config = stored.payload
        else:
            config = sr.create_default()
            sr.save(ROOT, config)
    except Exception as exc:  # pragma: no cover - defensive fallback
        print(f"[schedule] SQLite load failed, falling back to JSON: {exc}", file=sys.stderr)
        return _ensure_schedule_file_from_json()

    config.setdefault("patreonEarlyAccessDays", [14, 7])
    config.setdefault("chapterReleaseTime", "09:00")
    for novel in config.get("novels", []):
        novel.setdefault("currentRoyalRoadChapter", max(0, int(novel.get("nextChapter", 1)) - 1))
        novel.setdefault("nextRoyalRoadDate", novel.get("startDate", iso_today().isoformat()))
    return config


def _ensure_schedule_file_from_json() -> dict[str, Any]:
    if SCHEDULE_FILE.exists():
        config = json.loads(SCHEDULE_FILE.read_text(encoding="utf-8"))
        config.setdefault("patreonEarlyAccessDays", [14, 7])
        config.setdefault("chapterReleaseTime", "09:00")
        for novel in config.get("novels", []):
            novel.setdefault("currentRoyalRoadChapter", max(0, int(novel.get("nextChapter", 1)) - 1))
            novel.setdefault("nextRoyalRoadDate", novel.get("startDate", iso_today().isoformat()))
        return config
    today = iso_today()
    config = {
        "chapterReleaseDays": CHAPTER_RELEASE_DAYS,
        "generalPromoDays": GENERAL_PROMO_DAYS,
        "royalRoadDelayDays": 14,
        "releaseQueueStartDate": today.isoformat(),
        "chapterReleaseTime": "09:00",
        "patreonEarlyAccessDays": [14, 7],
        "generalPromoRotation": ["YouTube", "Royal Road", "TikTok"],
        "novels": [
            {
                "abbr": abbr,
                "name": name,
                "currentRoyalRoadChapter": 0,
                "nextChapter": 1,
                "nextRoyalRoadDate": today.isoformat(),
                "startDate": today.isoformat(),
                "releaseDays": CHAPTER_RELEASE_DAYS,
            }
            for abbr, name in NOVEL_NAMES.items()
        ],
    }
    SCHEDULE_FILE.write_text(json.dumps(config, indent=2), encoding="utf-8")
    return config


def next_dates(start: date, day_names: list[str], count: int) -> list[date]:
    results: list[date] = []
    cursor = start
    wanted = set(day_names)
    while len(results) < count:
        if cursor.strftime("%A") in wanted:
            results.append(cursor)
        cursor += timedelta(days=1)
    return results


def early_access_label(days: int) -> str:
    if days == 14:
        return "Inner Disciple"
    if days == 7:
        return "Path Initiate"
    if days % 7 == 0:
        return f"{days // 7} weeks early"
    return f"{days} days early"


def early_access_description(days: int) -> str:
    if days == 14:
        return "2 weeks early"
    if days == 7:
        return "1 week early"
    if days % 7 == 0:
        return f"{days // 7} weeks early"
    return f"{days} days early"


def platform_copy(
    platform: str,
    novel: str,
    chapter: int,
    release_date: date,
    target: str,
    early_access_days: int | None = None,
) -> dict[str, str]:
    profile = social_profile(novel)
    royal_road_url = royal_road_url_for_story(novel)
    abbr = story_key(novel)
    focus = "patreon_early" if target == "Patreon" else "royal_road_live"
    style = rotating_caption_style(abbr or novel, f"release_{target}_{chapter}")
    early_label = early_access_label(int(early_access_days or 14))
    early_description = early_access_description(int(early_access_days or 14))
    chapter_label = f"{profile['name']} Ch. {chapter}"
    status_line = (
        f"{chapter_label} is live for {early_label} on Patreon ({early_description})."
        if target == "Patreon"
        else f"{chapter_label} is live on Royal Road now."
    )
    cta = focused_social_cta(abbr or novel, focus, f"release_{target}_{chapter}", "release")
    hook_seed = {
        "scene_hook": f"{chapter_label}: the next scene pushes the story forward.",
        "reader_question": f"What would you do if {profile['name']} put the next choice in your hands?",
        "stakes": f"{chapter_label} raises the cost of the path ahead.",
        "character_moment": f"{chapter_label} turns on a character choice that matters.",
        "worldbuilding": f"{chapter_label} opens another piece of the world.",
        "catch_up": f"Catch up on {profile['name']} before the next release lands.",
    }.get(style, f"{chapter_label} is ready.")
    lines, x_hook = caption_style_lines(abbr or novel, profile["name"], f"Chapter {chapter}", hook_seed, focus, style, cta, status_line, f"release_{target}_{chapter}", "release")
    instagram = "\n".join(lines + ["", "Read now. Link in bio.", "", profile["hashtags"]])
    x_link = "Read now: link in bio."
    x_text = f"{profile['emoji']} {x_hook}\n{x_link}\n{profile['x_hashtags']}"
    if len(x_text) > 260:
        x_text = x_text[:257].rsplit(" ", 1)[0] + "..."
    return {"instagram": instagram, "x": x_text, "caption_style": style, "post_focus": focus}
    if platform == "chapter":
        if target == "Patreon":
            early_label = early_access_label(int(early_access_days or 14))
            early_description = early_access_description(int(early_access_days or 14))
            instagram = (
                f"{profile['emoji']} {profile['patreon']} — {profile['name']} Ch. {chapter} is live now for {early_label} on Patreon ({early_description})!\n"
                f"RR {royal_road_url}\n"
                f"Patreon {PATREON_URL}\n"
                f"YouTube {YOUTUBE_SOCIAL_URL}\n"
                f"TikTok {TIKTOK_URL}\n\n"
                f"{profile['hashtags']}"
            )
            x_text = f"{profile['emoji']} {profile['name']} Ch. {chapter} is live for {early_label} on Patreon.\n👉 {PATREON_URL}\n{profile['x_hashtags']}"
        else:
            instagram = (
                f"{profile['emoji']} {profile['name']} Chapter {chapter} is live on Royal Road!\n"
                "🎥 YouTube release included.\n"
                f"RR {royal_road_url}\n"
                f"Patreon {PATREON_URL}\n"
                f"YouTube {YOUTUBE_SOCIAL_URL}\n"
                f"TikTok {TIKTOK_URL}\n\n"
                f"{profile['hashtags']}"
            )
            x_text = f"{profile['emoji']} {profile['name']} Ch. {chapter} live on Royal Road! 🎥 YouTube included.\n👉 {royal_road_url}\n{profile['x_hashtags']}"
    else:
        instagram = (
            f"{profile['emoji']} {profile['patreon']} — {profile['name']} has chapters waiting on Patreon!\n"
            f"RR {royal_road_url}\n"
            f"Patreon {PATREON_URL}\n"
            f"YouTube {YOUTUBE_SOCIAL_URL}\n"
            f"TikTok {TIKTOK_URL}\n\n"
            f"{profile['hashtags']}"
        )
        x_text = f"{profile['emoji']} {profile['name']} early chapters are on Patreon.\n👉 {PATREON_URL}\n{profile['x_hashtags']}"
    if len(x_text) > 260:
        x_text = x_text[:257].rsplit(" ", 1)[0] + "..."
    return {"instagram": instagram, "x": x_text}


def build_schedule(days_ahead: int = 28) -> list[dict[str, Any]]:
    config = ensure_schedule_file()
    start = iso_today()
    end = start + timedelta(days=days_ahead)
    tasks: list[dict[str, Any]] = []
    rotation = config.get("generalPromoRotation") or ["YouTube", "Royal Road", "TikTok"]
    early_access_days = [int(value) for value in config.get("patreonEarlyAccessDays", [14, 7])]

    for novel in config.get("novels", []):
        abbr = novel["abbr"]
        name = novel["name"]
        current_royal_road_chapter = int(novel.get("currentRoyalRoadChapter", max(0, int(novel.get("nextChapter", 1)) - 1)))
        next_chapter = current_royal_road_chapter + 1
        next_royal_road_date = datetime.fromisoformat(
            novel.get("nextRoyalRoadDate") or novel.get("startDate", start.isoformat())
        ).date()
        release_days = novel.get("releaseDays") or CHAPTER_RELEASE_DAYS
        royal_road_dates = next_dates(next_royal_road_date, release_days, 160)
        for index, royal_date in enumerate(royal_road_dates):
            chapter = next_chapter + index
            for early_days in sorted(early_access_days, reverse=True):
                patreon_date = royal_date - timedelta(days=early_days)
                if start <= patreon_date <= end:
                    copy = platform_copy("chapter", name, chapter, patreon_date, "Patreon", early_days)
                    tasks.append(
                        {
                            "date": patreon_date.isoformat(),
                            "day": patreon_date.strftime("%A"),
                            "type": "chapter",
                            "platform": "Patreon",
                            "tier": early_access_label(early_days),
                            "earlyAccessDays": early_days,
                            "royalRoadDate": royal_date.isoformat(),
                            "abbr": abbr,
                            "novel": name,
                            "chapter": chapter,
                            **copy,
                        }
                    )
            if start <= royal_date <= end:
                copy = platform_copy("chapter", name, chapter, royal_date, "Royal Road")
                tasks.append(
                    {
                        "date": royal_date.isoformat(),
                        "day": royal_date.strftime("%A"),
                        "type": "chapter",
                        "platform": "Royal Road",
                        "tier": "public",
                        "earlyAccessDays": 0,
                        "royalRoadDate": royal_date.isoformat(),
                        "abbr": abbr,
                        "novel": name,
                        "chapter": chapter,
                        **copy,
                    }
                )

        promo_dates = next_dates(start, GENERAL_PROMO_DAYS, days_ahead)
        novel_offset = list(NOVEL_NAMES.keys()).index(abbr) if abbr in NOVEL_NAMES else 0
        for index, promo_date in enumerate(promo_dates):
            if promo_date > end:
                continue
            target = rotation[(index + novel_offset) % len(rotation)]
            copy = platform_copy("promo", name, 0, promo_date, target)
            tasks.append(
                {
                    "date": promo_date.isoformat(),
                    "day": promo_date.strftime("%A"),
                    "type": "promo",
                    "platform": target,
                    "abbr": abbr,
                    "novel": name,
                    "chapter": None,
                    **copy,
                }
            )

    tasks.sort(key=lambda item: (item["date"], item["abbr"], item["platform"]))
    return tasks


def schedule_tasks_for(date_text: str | None = None) -> list[dict[str, Any]]:
    target = datetime.fromisoformat(date_text).date() if date_text else iso_today()
    return [task for task in build_schedule(35) if task["date"] == target.isoformat()]


def read_json_body(handler: BaseHTTPRequestHandler) -> dict[str, Any]:
    size = int(handler.headers.get("Content-Length", "0"))
    raw = handler.rfile.read(size).decode("utf-8")
    return json.loads(raw or "{}")


def chapter_body_for_marketing(*args, **kwargs):
    return promo_copy.chapter_body_for_marketing(*args, **kwargs)
def repair_text_encoding(*args, **kwargs):
    return promo_copy.repair_text_encoding(*args, **kwargs)
def normalize_story_text(*args, **kwargs):
    return promo_copy.normalize_story_text(*args, **kwargs)
def normalize_story_body_text(text: str) -> str:
    text = repair_text_encoding(str(text or ""))
    text = text.replace("\\r\\n", "\n").replace("\\n", "\n").replace("\\t", " ")
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    text = text.replace("\u2018", "'").replace("\u2019", "'").replace("\u201c", '"').replace("\u201d", '"')
    text = text.replace("\u2013", "-").replace("\u2014", "-")
    text = re.sub(r"([.!?])([A-Z\"'])", r"\1 \2", text)
    text = re.sub(r"([a-z0-9])([A-Z][a-z])", r"\1 \2", text)
    paragraphs = []
    for part in re.split(r"\n\s*\n+", text):
        cleaned = re.sub(r"[ \t]+", " ", part)
        cleaned = re.sub(r"\n+", " ", cleaned).strip()
        cleaned = re.sub(r'\s+([,.!?;:])', r"\1", cleaned)
        cleaned = re.sub(r'"\s+([,.!?;:])', r'"\1', cleaned)
        if cleaned:
            paragraphs.append(cleaned)
    return "\n\n".join(paragraphs).strip()


def cleanup_platform_paragraphs(paragraphs: list[str]) -> list[str]:
    cleaned: list[str] = []
    for raw in paragraphs:
        paragraph = re.sub(r"\s+", " ", repair_text_encoding(str(raw or ""))).strip()
        if not paragraph:
            continue
        paragraph = paragraph.replace("\u2018", "'").replace("\u2019", "'").replace("\u201c", '"').replace("\u201d", '"')
        paragraph = paragraph.replace("\u2013", "-").replace("\u2014", "-")
        if cleaned and re.fullmatch(r'["\']?[,.!?;:]["\']?', paragraph):
            cleaned[-1] = (cleaned[-1].rstrip() + paragraph).strip()
            continue
        if cleaned and re.fullmatch(r'["\']', paragraph):
            cleaned[-1] = cleaned[-1].rstrip() + paragraph
            continue
        if cleaned and paragraph.startswith(('"', "'")) and len(paragraph.split()) <= 3 and not cleaned[-1].endswith(('"', "'")):
            cleaned[-1] = (cleaned[-1].rstrip() + " " + paragraph).strip()
            continue
        cleaned.append(paragraph)
    joined = "\n\n".join(cleaned)
    joined = re.sub(r"\n\n([\"'])(?=[,.;:!?])", r"\1", joined)
    joined = re.sub(r"\n\n([,.;:!?][\"']?)", r"\1", joined)
    return [part.strip() for part in re.split(r"\n\s*\n+", joined) if part.strip()]


def remove_leading_chapter_heading(text: str, title: str, chapter: int) -> str:
    text = text.strip()
    if chapter == 0 or title.strip().lower() == "prologue":
        return re.sub(r"^\s*Prologue\s*", "", text, count=1, flags=re.IGNORECASE).strip()
    title_tail = ""
    title_match = re.match(rf"^Chapter\s+{chapter}[A-Za-z]?\s*[:.\-\u2013\u2014]?\s*(.*)$", title.strip(), re.IGNORECASE)
    if title_match:
        title_tail = title_match.group(1).strip()
    if title_tail:
        tail_pattern = re.escape(title_tail).replace(r"\ ", r"\s+")
        text = re.sub(
            rf"^\s*Chapter\s+{chapter}[A-Za-z]?\s*[:.\-\u2013\u2014]?\s*{tail_pattern}\s*",
            "",
            text,
            count=1,
            flags=re.IGNORECASE,
        ).strip()
    text = re.sub(
        rf"^\s*Chapter\s+{chapter}[A-Za-z]?\s*[:.\-\u2013\u2014]?\s*",
        "",
        text,
        count=1,
        flags=re.IGNORECASE,
    ).strip()
    return text


def post_chapter_author_note(current_abbr: str = "") -> str:
    current_title = NOVEL_NAMES.get(story_key(current_abbr), "").strip() or "[Novel Title]"
    series_links = [
        ("⚔️", "The Hundredfold Path", ROYAL_ROAD_URLS["HP"]),
        ("🌌", "Eternal Nexus", ROYAL_ROAD_URLS["EN"]),
        ("🔥", "Soulforge Era", ROYAL_ROAD_URLS["SF"]),
        ("🌠", "Heavenly Ascension System", ROYAL_ROAD_URLS["HA"]),
    ]
    series_lines = "\n".join(
        f"{icon} {name} → Read on Royal Road: {url}"
        for icon, name, url in series_links
    )
    return f"""A note from azure inkblade

✦ Author's Note ✦
Thanks for reading this chapter of {current_title}!

If you're enjoying the story, don't forget to check out my other ongoing series:

{series_lines}

For early access chapters, exclusive lore, and bonus content, join us on Patreon:
👉 Patreon - Azure Inkblade: {PATREON_URL}

Stay connected and catch news, teasers, and updates here:
🎥 YouTube: {YOUTUBE_SOCIAL_URL}
🎵 TikTok: {TIKTOK_URL}
📸 Instagram: {INSTAGRAM_URL}
✦ X (Twitter): {X_URL}

Your support-whether through comments, ratings, or favorites-keeps these stories alive. Let's continue this journey together toward ascension! ✨"""


def royal_road_chapter_rating_cta(abbr: str, chapter: int | str = "", title: str = "", text: str = "") -> str:
    abbr = story_key(abbr)
    title = str(title or "").strip() or "this chapter"
    chapter_text = str(text or "").strip()
    if google_ai_configured() and chapter_text:
        try:
            data = google_ai_generate_json(
                "\n".join(
                    [
                        "Return JSON only with a single key named cta.",
                        "Write one gentle Royal Road post-chapter call-to-action.",
                        "It should ask readers to rate, favorite, or comment if they enjoyed a specific moment from this chapter.",
                        "Keep it under 45 words. Avoid guilt, hype, and em dashes.",
                        f"Novel: {NOVEL_NAMES.get(abbr, abbr)}",
                        f"Chapter: {chapter}",
                        f"Title: {title}",
                        f"Chapter text: {chapter_text[:9000]}",
                    ]
                ),
                system_instruction="You write concise author notes for web novel readers. Return strict JSON only.",
                temperature=marketing_temperature("accurate"),
            )
            cta = clean_teaser_text(str(data.get("cta") or ""), 360, max_words=55)
            if cta:
                return cta
        except Exception:
            pass
    beats = visual_sentences(chapter_text, 2, title) if chapter_text else []
    moment = clean_teaser_text(beats[0] if beats else title, 120, max_words=18)
    return f"If you enjoyed {moment}, a quick rating, favorite, or comment on Royal Road helps more readers find the story. Thank you for reading."


def enhanced_post_chapter_author_note(current_abbr: str = "", chapter: int | str = "", title: str = "", text: str = "") -> str:
    base = post_chapter_author_note(current_abbr).strip()
    cta = royal_road_chapter_rating_cta(current_abbr, chapter, title, text)
    return f"{cta}\n\n{base}"


def load_royal_road_growth_state() -> dict[str, Any]:
    data = read_json_safe(ROYAL_ROAD_GROWTH_FILE)
    if not isinstance(data, dict):
        data = {"schemaVersion": 1, "launchPlans": [], "shoutouts": [], "blurbLabs": [], "authorNotes": []}
    for key in ["launchPlans", "shoutouts", "blurbLabs", "authorNotes"]:
        data.setdefault(key, [])
    return data


def save_royal_road_growth_state(data: dict[str, Any]) -> None:
    data["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    write_json_atomic(ROYAL_ROAD_GROWTH_FILE, data)


def build_royal_road_author_note_pack(abbr: str, chapter: int | str) -> dict[str, Any]:
    abbr = story_key(abbr)
    if not abbr:
        raise RuntimeError("Choose a novel for the Royal Road author note.")
    chapter_number = int(chapter)
    data = docs_chapter_text(abbr, chapter_number)
    title = str(data.get("title") or f"Chapter {chapter_number}")
    text = str(data.get("raw_text") or data.get("text") or "")
    note = enhanced_post_chapter_author_note(abbr, chapter_number, title, text)
    folder = SOCIAL_OUTPUT_DIR / f"royal-road-growth-{abbr.lower()}-{chapter_number}"
    folder.mkdir(parents=True, exist_ok=True)
    note_file = folder / "chapter-author-note.txt"
    note_file.write_text(royal_road_editor_spacing(note), encoding="utf-8")
    payload = {
        "kind": "royal_road_author_note",
        "abbr": abbr,
        "novel": NOVEL_NAMES.get(abbr, abbr),
        "chapter": chapter_number,
        "title": title,
        "note": note,
        "noteFile": str(note_file),
        "createdAt": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    state = load_royal_road_growth_state()
    state["authorNotes"] = [item for item in state["authorNotes"] if not (item.get("abbr") == abbr and int(item.get("chapter") or -1) == chapter_number)]
    state["authorNotes"].append(payload)
    save_royal_road_growth_state(state)
    return payload


def royal_road_launch_manager_plan(abbr: str, chapter_count: int = 8, start_date: str = "", words_target: int = 20000) -> dict[str, Any]:
    abbr = story_key(abbr)
    if not abbr:
        raise RuntimeError("Choose a novel for the launch plan.")
    chapter_count = max(1, min(12, int(chapter_count or 8)))
    index = docs_chapter_index(abbr)
    chapters = sorted(index.get("chapters", []), key=lambda item: int(item.get("number") or 0))[:chapter_count]
    if not chapters:
        raise RuntimeError("No chapters were found for this novel.")
    start = datetime.fromisoformat(start_date).date() if str(start_date or "").strip() else iso_today()
    slots = ["07:15", "10:30", "13:45", "17:00", "20:15", "08:45", "12:15", "18:30", "21:00", "09:30", "14:30", "19:30"]
    planned = []
    total_words = 0
    for idx, chapter in enumerate(chapters):
        number = int(chapter.get("number") or 0)
        try:
            chapter_data = docs_chapter_text(abbr, number)
            words = int(chapter_data.get("word_count") or 0)
            title = str(chapter_data.get("title") or chapter.get("title") or f"Chapter {number}")
        except Exception:
            words = 0
            title = str(chapter.get("title") or f"Chapter {number}")
        total_words += words
        day_offset = 0 if idx < 5 else 1 + ((idx - 5) // 3)
        planned_date = start + timedelta(days=day_offset)
        planned.append(
            {
                "abbr": abbr,
                "novel": NOVEL_NAMES.get(abbr, abbr),
                "chapter": number,
                "title": title,
                "wordCount": words,
                "plannedAt": f"{planned_date.isoformat()} {slots[idx % len(slots)]}",
                "goal": "Keep the fiction visible on Latest Updates while building early reader velocity.",
            }
        )
    payload = {
        "kind": "royal_road_launch_plan",
        "abbr": abbr,
        "novel": NOVEL_NAMES.get(abbr, abbr),
        "createdAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "startDate": start.isoformat(),
        "chapterCount": len(planned),
        "totalWords": total_words,
        "targetWords": int(words_target or 20000),
        "ready": total_words >= int(words_target or 20000),
        "chapters": planned,
        "recommendation": "Launch word target met." if total_words >= int(words_target or 20000) else "Add more chapters before treating this as a full launch push.",
        "nextActions": [
            "Prepare Royal Road chapter drafts for each planned slot.",
            "Build social packs for each launch chapter.",
            "Prepare one shout-out swap block before launch week.",
            "Track views/follows after each slot and after 24 hours.",
        ],
    }
    state = load_royal_road_growth_state()
    state["launchPlans"] = [item for item in state["launchPlans"] if item.get("abbr") != abbr]
    state["launchPlans"].append(payload)
    save_royal_road_growth_state(state)
    return payload


def royal_road_shoutout_html(abbr: str, hook: str = "", partner_title: str = "", partner_url: str = "", cover_url: str = "") -> dict[str, Any]:
    abbr = story_key(abbr)
    novel = NOVEL_NAMES.get(abbr, abbr or "Azure Inkblade")
    rr_url = partner_url.strip() or royal_road_url_for_story(abbr)
    title = partner_title.strip() or novel
    if not hook.strip():
        try:
            first_chapter = docs_chapter_text(abbr, 1)
            hook = compact_chapter_hook(str(first_chapter.get("title") or title), str(first_chapter.get("text") or ""), story=abbr)
        except Exception:
            hook = f"Start {title} on Royal Road and follow the next step of the journey."
    hook = clean_teaser_text(hook, 220, max_words=34)
    escaped_title = html.escape(title)
    escaped_hook = html.escape(hook)
    escaped_url = html.escape(rr_url, quote=True)
    escaped_cover = html.escape(cover_url.strip(), quote=True)
    image_html = f'<p><a href="{escaped_url}"><img src="{escaped_cover}" alt="{escaped_title}" style="max-width:240px;width:100%;height:auto;" /></a></p>\n' if escaped_cover else ""
    snippet = (
        '<div class="azureinkblade-shoutout">\n'
        f"{image_html}"
        f'<p><strong>{escaped_title}</strong></p>\n'
        f"<p>{escaped_hook}</p>\n"
        f'<p><a href="{escaped_url}">Read {escaped_title} on Royal Road</a></p>\n'
        "</div>"
    )
    folder = SOCIAL_OUTPUT_DIR / f"royal-road-shoutout-{abbr.lower() or slugify(title)}"
    folder.mkdir(parents=True, exist_ok=True)
    html_file = folder / "shoutout-swap.html"
    html_file.write_text(snippet + "\n", encoding="utf-8")
    payload = {
        "kind": "royal_road_shoutout",
        "abbr": abbr,
        "novel": novel,
        "title": title,
        "hook": hook,
        "url": rr_url,
        "coverUrl": cover_url,
        "html": snippet,
        "htmlFile": str(html_file),
        "createdAt": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    state = load_royal_road_growth_state()
    state["shoutouts"].append(payload)
    state["shoutouts"] = state["shoutouts"][-50:]
    save_royal_road_growth_state(state)
    return payload


def royal_road_blurb_variant_lab(abbr: str) -> dict[str, Any]:
    abbr = story_key(abbr)
    if not abbr:
        raise RuntimeError("Choose a novel for the blurb lab.")
    novel = NOVEL_NAMES.get(abbr, abbr)
    samples = []
    for number in [1, 2, 3]:
        try:
            chapter = docs_chapter_text(abbr, number)
            samples.append(f"{chapter.get('title')}\n{str(chapter.get('text') or '')[:3500]}")
        except Exception:
            continue
    context = "\n\n---\n\n".join(samples)
    variants: list[dict[str, Any]]
    if google_ai_configured() and context:
        try:
            data = google_ai_generate_json(
                "\n".join(
                    [
                        "Return JSON only.",
                        "Create three Royal Road fiction blurb variants for this web novel.",
                        "Schema: {\"variants\":[{\"style\":\"hook-heavy|progression-system|synopsis\",\"headline\":\"\",\"blurb\":\"\",\"bestFor\":\"\",\"trackingNote\":\"\"}]}",
                        "Rules: No spoilers past the included opening chapters. Avoid em dashes. Make the blurbs distinct.",
                        f"Novel: {novel}",
                        f"Opening chapter context:\n{context[:18000]}",
                    ]
                ),
                system_instruction="You write Royal Road blurbs for conversion testing. Return strict JSON only.",
                temperature=marketing_temperature("creative"),
            )
            variants = [item for item in data.get("variants", []) if isinstance(item, dict)]
        except Exception:
            variants = []
    else:
        variants = []
    if len(variants) < 3:
        variants = [
            {"style": "hook-heavy", "headline": f"{novel}: Start Here", "blurb": f"A single impossible moment pulls the hero into a path where every choice matters. Start {novel} on Royal Road.", "bestFor": "Fast scrollers", "trackingNote": "Measure chapter-one clicks and follows."},
            {"style": "progression-system", "headline": f"{novel}: Power Has A Price", "blurb": f"For readers who like progression, dangerous trials, and characters forced to earn every step, {novel} begins with a path that refuses to stay simple.", "bestFor": "Progression fantasy readers", "trackingNote": "Measure follows from genre-driven traffic."},
            {"style": "synopsis", "headline": novel, "blurb": f"{novel} follows a rising journey through danger, secrets, and hard-won power. Begin with Chapter 1 and follow the story as the stakes climb.", "bestFor": "General readers", "trackingNote": "Use as the control blurb."},
        ]
    payload = {
        "kind": "royal_road_blurb_lab",
        "abbr": abbr,
        "novel": novel,
        "createdAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "variants": variants[:3],
        "instructions": "Rotate one blurb at a time for a fixed window, then record views/follows before changing again.",
    }
    state = load_royal_road_growth_state()
    state["blurbLabs"] = [item for item in state["blurbLabs"] if item.get("abbr") != abbr]
    state["blurbLabs"].append(payload)
    save_royal_road_growth_state(state)
    return payload


def strip_existing_post_chapter_author_note(text: str) -> str:
    value = str(text or "").rstrip()
    markers = [
        "A note from azure inkblade",
        "Author's Note",
        "Author\u2019s Note",
        "Author Note",
    ]
    lower = value.lower()
    positions = [lower.rfind(marker.lower()) for marker in markers]
    positions = [pos for pos in positions if pos >= 0]
    if not positions:
        return value
    cut = max(positions)
    tail = value[cut:].lower()
    if any(token in tail for token in ["patreon", "royal road", "youtube", "tiktok", "azure inkblade"]):
        return value[:cut].rstrip()
    return value


def append_post_chapter_author_note(text: str, current_abbr: str = "", chapter: int | str = "", title: str = "") -> str:
    text = text.rstrip()
    text = strip_existing_post_chapter_author_note(text)
    return f"{text}\n\n{enhanced_post_chapter_author_note(current_abbr, chapter, title, text).strip()}\n"
    if "✦ Author's Note ✦" in text or "✦ Author’s Note ✦" in text:
        return text + "\n"
    return f"{text}\n\n{post_chapter_author_note(current_abbr).strip()}\n"


def royal_road_editor_spacing(text: str) -> str:
    text = repair_text_encoding(str(text or "")).replace("\r\n", "\n").replace("\r", "\n")
    text = re.sub(r"[ \t]+\n", "\n", text)
    text = re.sub(r"\n[ \t]+", "\n", text)
    parts = [re.sub(r"\s+", " ", part).strip() for part in re.split(r"\n\s*\n+", text) if part.strip()]
    if not parts:
        return ""
    return "\n\n".join(parts).strip() + "\n"


def format_chapter_for_platform(title: str, raw_text: str, chapter: int, abbr: str = "", include_post_note: bool = True) -> str:
    body = remove_leading_chapter_heading(raw_text, title, chapter)
    body = repair_text_encoding(body)
    body = body.replace("\r\n", "\n").replace("\r", "\n")
    body = body.replace("\u2018", "'").replace("\u2019", "'").replace("\u201c", '"').replace("\u201d", '"')
    body = body.replace("\u2013", "-").replace("\u2014", "-")
    body = re.sub(r"[ \t]+", " ", body)
    body = re.sub(r"([.!?])(?=[A-Z\u201c\u2018\"'])", r"\1 ", body)
    body = re.sub(r"([a-z0-9])(?=(?:PATCH|System Message|Initializing|Syncing|Loading|New Realms|Legacy Classes|All Characters Reset)\b)", r"\1\n\n", body)
    body = re.sub(r"(All Characters Reset)(?=[A-Z])", r"\1\n\n", body)
    body = re.sub(r"\b(PATCH\s+\d+(?:\.\d+)*:\s*[^\n]+)", r"\n\n\1\n", body, flags=re.IGNORECASE)
    body = re.sub(r"\b(System Message:[^\n]+)", r"\n\n\1\n", body, flags=re.IGNORECASE)
    body = re.sub(r"\b(Initializing Avatar\.|Syncing Meridians\.|Loading Environment\.)", r"\n\n\1", body, flags=re.IGNORECASE)
    body = re.sub(r"\b(New Realms Unlocked|Legacy Classes Released|All Characters Reset)\b", r"\n\1", body)
    sentences = re.split(r"(?<=[.!?])\s+", body.strip())
    paragraphs: list[str] = []
    current: list[str] = []
    for sentence in sentences:
        sentence = sentence.strip()
        if not sentence:
            continue
        if "\n" in sentence:
            if current:
                paragraphs.append(" ".join(current).strip())
                current = []
            paragraphs.extend(part.strip() for part in sentence.splitlines() if part.strip())
            continue
        current.append(sentence)
        if len(" ".join(current)) > 520:
            paragraphs.append(" ".join(current).strip())
            current = []
    if current:
        paragraphs.append(" ".join(current).strip())
    cleaned = cleanup_platform_paragraphs(paragraphs)
    chapter_text = f"{title.strip()}\n\n" + "\n\n".join(cleaned).strip()
    if include_post_note:
        return append_post_chapter_author_note(chapter_text, abbr, chapter, title)
    return chapter_text.rstrip() + "\n"


