def clean_teaser_text(*args, **kwargs):
    return promo_copy.clean_teaser_text(*args, **kwargs)
def teaser_from_sentence(sentence: str) -> str:
    sentence = clean_teaser_text(sentence, limit=180, max_words=None)
    clauses = re.split(r"\s+(?:because|while|when|before|after|as|and realized|and knew|but)\s+|[,;:]", sentence, flags=re.IGNORECASE)
    candidates = [clean_teaser_text(clause, limit=72, max_words=12) for clause in clauses]
    candidates = [candidate for candidate in candidates if 4 <= len(candidate.split()) <= 12]
    if not candidates:
        return clean_teaser_text(sentence, limit=72, max_words=12)
    return max(candidates, key=visual_score)


def chapter_keywords(*args, **kwargs):
    return promo_copy.chapter_keywords(*args, **kwargs)
def visual_sentences(*args, **kwargs):
    return promo_copy.visual_sentences(*args, **kwargs)
def fallback_phrases(chapter: str, story: str = "") -> list[str]:
    sentences = sentence_split(chapter)
    if not sentences:
        return ["A new chapter begins", "The truth refuses to stay buried", "Everything changes now"]
    ranked = sorted(sentences, key=lambda item: visual_score(item, story), reverse=True)
    phrases: list[str] = []
    for sentence in ranked:
        phrase = teaser_from_sentence(sentence)
        if phrase not in phrases:
            phrases.append(phrase)
        if len(phrases) == 3:
            break
    while len(phrases) < 3:
        phrases.append("A moment readers will not forget")
    return phrases


def fallback_caption(title: str, phrases: list[str]) -> str:
    hook = phrases[rotation_next(f"FALLBACK_CAPTION_{slugify(title)}", max(1, len(phrases)))] if phrases else "A new chapter is ready."
    cta = focused_social_cta("", "weekly_general_promo", f"fallback_{slugify(title)}", "caption")
    return "\n".join(
        [
            f"{title or 'New chapter'} is ready for web novel readers.",
            "",
            hook,
            "",
            "Save this for your next serial fantasy read.",
            cta,
            "#webnovel #royalroad #serialfiction #progressionfantasy #booktok",
        ]
    )


def default_social_prompt() -> str:
    return textwrap.dedent(
        """
        Create reusable social copy for a daily web-novel promo image.

        Inputs:
        Novel: {novel}
        Abbreviation: {abbr}
        Day: {day}
        Image filename: {filename}

        Return JSON with:
        - instagram: an Instagram caption using this structure: fresh hook line, one engagement prompt, one link-in-bio CTA, hashtags
        - x: a concise X post under 260 characters with one link-in-bio CTA and 2-4 hashtags
        - facebook: a slightly fuller Facebook post with a fresh hook, one engagement prompt, one link-in-bio CTA, and hashtags
        - alt_text: accessible image alt text

        Style:
        - web novel reader audience
        - energetic but not spammy
        - no fake chapter number unless one is supplied
        - mention the novel name naturally
        - never include raw URLs or full links; use "link in bio" for the public hub CTA
        - rotate the CTA intent between start reading, read ahead, watch/listen, follow for next chapter, and comment with a prediction
        - do not include an X link in Instagram or Facebook copy
        """
    ).strip()


def social_prompt_template() -> str:
    prompt_file = ROOT / "social_prompt_template.txt"
    if not prompt_file.exists():
        prompt_file.write_text(default_social_prompt() + "\n", encoding="utf-8")
    return prompt_file.read_text(encoding="utf-8")


def list_daily_promo_images() -> list[dict[str, str]]:
    items: list[dict[str, str]] = []
    image_exts = {".png", ".jpg", ".jpeg", ".webp"}
    seen: set[str] = set()
    for root in [generated_weekly_promo_images_dir(), PROMO_IMAGES_DIR]:
        if not root.exists():
            continue
        for path in sorted(root.iterdir()):
            if not path.is_file() or path.suffix.lower() not in image_exts:
                continue
            match = re.match(r"^([A-Z]{2})_([A-Za-z]+)", path.stem)
            if not match:
                continue
            abbr, day = match.group(1), match.group(2)
            if day not in DAYS:
                continue
            key = f"{abbr}_{day}"
            if key in seen:
                continue
            seen.add(key)
            items.append(
                {
                    "abbr": abbr,
                    "novel": NOVEL_NAMES.get(abbr, abbr),
                    "day": day,
                    "filename": path.name,
                    "path": str(path),
                }
            )
    return items


def archive_generated_promo_image(source: Path, abbr: str = "", title: str = "", label: str = "") -> str:
    if not source.exists() or source.suffix.lower() not in IMAGE_EXTENSIONS:
        return ""
    abbr = abbr.upper().strip() or "GEN"
    story_dir = generated_promo_images_dir() / abbr
    story_dir.mkdir(parents=True, exist_ok=True)
    stem_parts = [
        abbr,
        slugify(title)[:46] if title else "promo",
        slugify(label)[:18] if label else time.strftime("%Y%m%d-%H%M%S"),
    ]
    target = story_dir / f"{'-'.join(part for part in stem_parts if part)}{source.suffix.lower()}"
    counter = 2
    while target.exists():
        target = story_dir / f"{'-'.join(part for part in stem_parts if part)}-{counter}{source.suffix.lower()}"
        counter += 1
    shutil.copy2(source, target)
    state = mark_image_used(target)
    save_promo_rotation_state(state)
    return str(target)


def load_promo_rotation_state() -> dict[str, Any]:
    # SQLite (state_snapshots kv) is the sole source of truth. The JSON mirror
    # is retired (Phase 1 retirement).
    data = load_state_snapshot_from_database("promoRotation")
    if isinstance(data, dict) and data:
        return data
    return {}


def save_promo_rotation_state(state: dict[str, Any]) -> None:
    try:
        mirror_state_snapshot_to_database("promoRotation", state)
    except Exception as exc:
        print(f"Database mirror failed for promo rotation: {exc}", file=sys.stderr)


def image_reuse_key(path: Path) -> str:
    try:
        return str(path.resolve()).lower()
    except Exception:
        return str(path).lower()


def recent_image_usage_days(path: Path, state: dict[str, Any] | None = None) -> float | None:
    state = state if state is not None else load_promo_rotation_state()
    usage = state.get("IMAGE_USAGE") if isinstance(state.get("IMAGE_USAGE"), dict) else {}
    timestamp = usage.get(image_reuse_key(path))
    if not timestamp:
        return None
    try:
        return (time.time() - float(timestamp)) / 86400
    except (TypeError, ValueError):
        return None


def recent_image_hash_usage_days(path: Path, state: dict[str, Any] | None = None) -> float | None:
    if not path.exists() or not path.is_file():
        return None
    state = state if state is not None else load_promo_rotation_state()
    usage = state.get("IMAGE_HASH_USAGE") if isinstance(state.get("IMAGE_HASH_USAGE"), dict) else {}
    timestamp = usage.get(image_file_fingerprint(path))
    if not timestamp:
        return None
    try:
        return (time.time() - float(timestamp)) / 86400
    except (TypeError, ValueError):
        return None


def image_is_in_cooldown(path: Path, state: dict[str, Any] | None = None) -> bool:
    path_days = recent_image_usage_days(path, state)
    hash_days = recent_image_hash_usage_days(path, state)
    return any(days is not None and days < IMAGE_REUSE_COOLDOWN_DAYS for days in (path_days, hash_days))


def mark_image_used(path: Path, state: dict[str, Any] | None = None) -> dict[str, Any]:
    state = state if state is not None else load_promo_rotation_state()
    usage = state.setdefault("IMAGE_USAGE", {})
    if isinstance(usage, dict):
        usage[image_reuse_key(path)] = time.time()
    hash_usage = state.setdefault("IMAGE_HASH_USAGE", {})
    if isinstance(hash_usage, dict) and path.exists() and path.is_file():
        hash_usage[image_file_fingerprint(path)] = time.time()
    return state


def eligible_reuse_images(paths: list[Path], *, abbr: str = "", require_bank: bool = True) -> list[Path]:
    state = load_promo_rotation_state()
    if require_bank and abbr:
        novel_bank_count = len([path for path in reusable_generated_promo_images(abbr) if path.exists()])
        if novel_bank_count < IMAGE_REUSE_MIN_BANK_PER_NOVEL:
            return []
    return [path for path in paths if path.exists() and not image_is_in_cooldown(path, state)]


def reusable_daily_promo_images(abbr: str = "") -> list[Path]:
    abbr = abbr.upper().strip()
    image_exts = {".png", ".jpg", ".jpeg", ".webp"}
    roots = [generated_weekly_promo_images_dir(), PROMO_IMAGES_DIR, SOCIAL_OUTPUT_DIR, GITHUB_MEDIA_DIR / "social-posts"]
    found: dict[str, Path] = {}
    for root in roots:
        if not root.exists():
            continue
        for path in root.rglob("*"):
            if not path.is_file() or path.suffix.lower() not in image_exts:
                continue
            match = re.match(r"^([A-Z]{2})_([A-Za-z]+)$", path.stem)
            if not match:
                continue
            image_abbr, day = match.group(1), match.group(2)
            if abbr and image_abbr != abbr:
                continue
            if day not in DAYS:
                continue
            found.setdefault(f"{image_abbr}_{day}", path)
    return [found[key] for key in sorted(found)]


def reusable_generated_promo_images(abbr: str = "") -> list[Path]:
    abbr = abbr.upper().strip()
    root_dir = generated_promo_images_dir()
    if not root_dir.exists():
        return []
    root = root_dir / abbr if abbr and (root_dir / abbr).exists() else root_dir
    images = [
        path
        for path in sorted(root.rglob("*"))
        if path.is_file() and path.suffix.lower() in IMAGE_EXTENSIONS
    ]
    if abbr:
        images = [
            path
            for path in images
            if path.name.upper().startswith((f"{abbr}-", f"{abbr}_")) or f"\\{abbr}\\" in str(path).upper()
        ]
    return images


def image_file_fingerprint(path: Path) -> str:
    signature = file_signature(path)
    if signature:
        cached = IMAGE_FINGERPRINT_CACHE.get(signature)
        if cached:
            return cached
    try:
        digest = hashlib.sha256()
        with path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        value = digest.hexdigest()
        if signature:
            if len(IMAGE_FINGERPRINT_CACHE) > 10000:
                IMAGE_FINGERPRINT_CACHE.clear()
            IMAGE_FINGERPRINT_CACHE[signature] = value
        return value
    except OSError:
        return str(path.resolve()).lower()


def has_unique_image_set(paths: list[Path], minimum: int = 3) -> bool:
    fingerprints = {image_file_fingerprint(path) for path in paths if path.exists() and path.is_file()}
    return len(fingerprints) >= minimum


def chapter_image_pack(abbr: str, chapter: str | int = "", title: str = "", minimum: int = 3) -> list[Path]:
    if not ALLOW_SAME_CHAPTER_IMAGE_REUSE:
        return []
    abbr = abbr.upper().strip()
    chapter_text = str(chapter or "").strip()
    title_slug = slugify(title).lower() if title else ""
    novel_slug = slugify(NOVEL_NAMES.get(abbr, abbr)).lower() if abbr else ""
    raster_exts = {".png", ".jpg", ".jpeg", ".webp"}
    if abbr and chapter_text:
        exact_tiktok = [TIKTOK_ASSET_DIR / f"{abbr}_{chapter_text}_{index}.png" for index in range(1, minimum + 1)]
        if all(path.exists() for path in exact_tiktok) and has_unique_image_set(exact_tiktok, minimum):
            return exact_tiktok
        exact_archived_tiktok = [
            generated_promo_images_dir() / abbr / f"{abbr}-{novel_slug}-chapter-{chapter_text}-tiktok-{index}.png"
            for index in range(1, minimum + 1)
        ]
        if all(path.exists() for path in exact_archived_tiktok) and has_unique_image_set(exact_archived_tiktok, minimum):
            return exact_archived_tiktok
    roots = [
        TIKTOK_ASSET_DIR,
        generated_promo_images_dir() / abbr if abbr else generated_promo_images_dir(),
        generated_promo_images_dir() / "PixabayTests",
        OUTPUT_DIR,
        GITHUB_MEDIA_DIR,
    ]
    seen: set[str] = set()
    scored: list[tuple[int, float, Path]] = []
    chapter_markers = []
    if chapter_text:
        normalized_chapter = re.sub(r"[^a-z0-9]+", "-", chapter_text.lower()).strip("-")
        chapter_markers = [
            f"chapter-{chapter_text}",
            f"ch{chapter_text}",
            f"chapter {chapter_text}",
            f"{abbr.lower()}-{normalized_chapter}" if abbr else "",
        ]
        chapter_markers = [marker for marker in chapter_markers if marker]
    for root in roots:
        if not root.exists():
            continue
        for path in root.rglob("*"):
            if not path.is_file() or path.suffix.lower() not in raster_exts:
                continue
            prefix_match = re.match(r"^(HP|EN|HA|SF)[-_]", path.name, re.IGNORECASE)
            if abbr and prefix_match and prefix_match.group(1).upper() != abbr:
                continue
            resolved = str(path.resolve())
            if resolved in seen:
                continue
            searchable = " ".join([path.stem, path.parent.name, path.parent.parent.name if path.parent.parent else ""]).lower()
            normalized = searchable.replace("_", "-").replace(" ", "-")
            tokens = {token for token in re.split(r"[^a-z0-9]+", searchable) if token}
            novel_matches = bool(
                not abbr
                or abbr.lower() in tokens
                or novel_slug in normalized
            )
            if not novel_matches:
                continue
            if chapter_markers and not any(marker.lower().replace("_", "-").replace(" ", "-") in normalized for marker in chapter_markers):
                if title_slug and title_slug not in normalized:
                    continue
                if not title_slug:
                    continue
            score = 0
            if abbr and path.name.upper().startswith(f"{abbr}_{chapter_text}_"):
                score += 50
            if abbr and path.name.upper().startswith(f"{abbr}-"):
                score += 25
            if title_slug and title_slug in normalized:
                score += 20
            if "tiktok" in normalized:
                score += 12
            if "campaign" in normalized or "promo" in normalized:
                score += 8
            if "pixabay" in normalized:
                score += 5
            seen.add(resolved)
            try:
                modified = path.stat().st_mtime
            except OSError:
                modified = 0
            scored.append((score, modified, path))
    if len(scored) < minimum:
        return []
    grouped: dict[str, dict[int, Path]] = {}
    for _, _, path in scored:
        normalized = path.stem.lower().replace("_", "-")
        group_key = ""
        index = 0
        match = re.search(r"^(?P<base>.+?)-(?:campaign|tiktok|pixabay|promo)-(?P<idx>[123])(?:-\d+)?$", normalized)
        if match:
            group_key = match.group("base")
            index = int(match.group("idx"))
        else:
            match = re.search(rf"^(?P<base>{abbr.lower()}-{re.escape(chapter_text)})-(?P<idx>[123])$", normalized) if abbr and chapter_text else None
            if match:
                group_key = match.group("base")
                index = int(match.group("idx"))
        if group_key and index:
            grouped.setdefault(group_key, {})[index] = path
    complete_groups = [
        group
        for group in grouped.values()
        if all(index in group for index in range(1, minimum + 1))
        and has_unique_image_set([group[index] for index in range(1, minimum + 1)], minimum)
    ]
    if complete_groups:
        best_group = max(
            complete_groups,
            key=lambda group: max(path.stat().st_mtime if path.exists() else 0 for path in group.values()),
        )
        return [best_group[index] for index in range(1, minimum + 1)]
    selected: list[Path] = []
    selected_keys: set[str] = set()
    selected_fingerprints: set[str] = set()
    for _, _, path in sorted(scored, key=lambda item: (item[0], item[1]), reverse=True):
        key = re.sub(r"[-_](?:campaign|tiktok|pixabay|current|improved|v\d+)?[-_]?\d+$", "", path.stem.lower())
        if key in selected_keys and len(scored) >= minimum + 2:
            continue
        fingerprint = image_file_fingerprint(path)
        if fingerprint in selected_fingerprints:
            continue
        selected_keys.add(key)
        selected_fingerprints.add(fingerprint)
        selected.append(path)
        if len(selected) >= minimum:
            break
    return selected[:minimum]


def choose_rotating_daily_promo_image(abbr: str = "") -> Path | None:
    images = (
        reusable_daily_promo_images(abbr)
        or reusable_daily_promo_images("")
        or reusable_generated_promo_images(abbr)
        or reusable_generated_promo_images("")
    )
    images = eligible_reuse_images(images, abbr=abbr, require_bank=False)
    if not images:
        return None
    keys = [str(path.resolve()) for path in images]
    state = load_promo_rotation_state()
    pool_key = abbr.upper().strip() or "ALL"
    used = [key for key in state.get(pool_key, []) if key in keys]
    available = [key for key in keys if key not in used]
    if not available:
        used = []
        available = keys[:]
    choice = random.choice(available)
    used.append(choice)
    state[pool_key] = used
    mark_image_used(Path(choice), state)
    save_promo_rotation_state(state)
    return Path(choice)


def weekly_promo_audio_files() -> list[Path]:
    weekly_dir = generated_weekly_promo_images_dir()
    if not weekly_dir.exists():
        return []
    return [
        path
        for path in sorted(weekly_dir.iterdir())
        if path.is_file() and path.suffix.lower() in AUDIO_EXTENSIONS
    ]


def choose_rotating_weekly_promo_audio() -> Path | None:
    sounds = weekly_promo_audio_files()
    if not sounds:
        return None
    keys = [str(path.resolve()) for path in sounds]
    # Phase 1 retirement: promo rotation lives in SQLite (state_snapshots kv).
    state: dict[str, Any] = load_state_snapshot_from_database("promoRotation") or {}
    if not isinstance(state, dict):
        state = {}
    pool_key = "WEEKLY_AUDIO"
    used = [key for key in state.get(pool_key, []) if key in keys]
    available = [key for key in keys if key not in used]
    if not available:
        used = []
        available = keys[:]
    choice = random.choice(available)
    used.append(choice)
    state[pool_key] = used
    try:
        mirror_state_snapshot_to_database("promoRotation", state)
    except Exception as exc:
        print(f"Database mirror failed for promo rotation: {exc}", file=sys.stderr)
    return Path(choice)


def list_tiktok_assets() -> dict[str, Any]:
    if not TIKTOK_ASSET_DIR.exists():
        return {"sounds": [], "imageGroups": [], "videos": []}
    sounds = [path for path in sorted(TIKTOK_ASSET_DIR.iterdir()) if path.is_file() and path.suffix.lower() in AUDIO_EXTENSIONS]
    videos = [path for path in sorted(TIKTOK_ASSET_DIR.iterdir()) if path.is_file() and path.suffix.lower() in VIDEO_EXTENSIONS]
    groups: dict[tuple[str, str], list[Path]] = {}
    raster_exts = {".png", ".jpg", ".jpeg", ".webp"}
    for path in sorted(TIKTOK_ASSET_DIR.iterdir()):
        if not path.is_file() or path.suffix.lower() not in raster_exts:
            continue
        match = re.match(r"^([A-Z]{2})_(\d+)_([123])$", path.stem)
        if not match:
            continue
        groups.setdefault((match.group(1), match.group(2)), []).append(path)
    image_groups = [
        {
            "abbr": abbr,
            "novel": NOVEL_NAMES.get(abbr, abbr),
            "chapter": chapter,
            "count": len(paths),
            "files": [str(path) for path in paths],
            # E1: surface each image's recorded style track (sidecar) so packs can lock one style.
            "tracks": [
                (path.with_name(f"{path.name}.track").read_text(encoding="utf-8").strip()
                 if (path.with_name(f"{path.name}.track")).exists() else "")
                for path in paths
            ],
        }
        for (abbr, chapter), paths in sorted(groups.items(), key=lambda item: (item[0][0], int(item[0][1])))
    ]
    return {
        "sounds": [{"name": path.name, "path": str(path)} for path in sounds],
        "imageGroups": image_groups,
        "videos": [{"name": path.name, "path": str(path)} for path in videos],
    }


def short_platform_intro(abbr_or_name: str, chapter: str, platform: str) -> str:
    profile = social_profile(abbr_or_name)
    abbr = story_key(abbr_or_name) or story_key(profile["name"])
    chapter_text = f" Chapter {chapter}" if chapter else ""
    platform = (platform or "").strip().lower()
    if platform == "tiktok":
        variants = [
            f"Stop here if you like fantasy where one bad choice changes the whole arc.",
            f"{profile['name']}{chapter_text}: one scene, one choice, and a problem that will not stay buried.",
            f"Readers who like progression fantasy with consequences, this is the kind of turn I built this for.",
        ]
    elif platform == "instagram-reel":
        variants = [
            f"{profile['name']}{chapter_text} in one reel: atmosphere, pressure, and the next turn.",
            f"If your next read needs systems, secrets, and momentum, start here.",
            f"A quick look at the chapter mood before the next update lands.",
        ]
    else:
        variants = [
            f"{profile['name']}{chapter_text} short chapter teaser.",
            "A fast chapter hook for serial fantasy readers.",
            "One scene from the Azure Inkblade release trail.",
        ]
    key = f"SHORT_INTRO_{platform}_{abbr}_{chapter}".upper()
    return variants[rotation_next(key, len(variants))]


def tiktok_caption(novel: str, chapter: str) -> str:
    profile = social_profile(novel)
    destination = short_destination_copy(novel, chapter, source="tiktok")
    hashtags = rotated_hashtags(novel, f"{novel}-{chapter}", chapter_text=chapter, limit=9)
    # Engagement question drives comments/shares (TikTok had 0 comments/0 shares).
    question = platform_engagement_prompt_line(story_key(novel), "short_reel", "tiktok", context=f"caption-{chapter}")
    # Plain novel name in the body for TikTok search indexing (viewers search book
    # names like 'soul forged novel', 'avure ink', 'Eternalnexus').
    return social_caption_link_in_bio("\n".join(
        [
            f"{profile['emoji']} {short_platform_intro(novel, chapter, 'tiktok')}",
            f"This is {profile['name']}.",
            destination["hook"],
            destination["links"],
            "",
            question,
            "",
            hashtags,
        ]
    ), "tiktok")


def instagram_reel_caption(novel: str, chapter: str) -> str:
    profile = social_profile(novel)
    destination = short_destination_copy(novel, chapter, source="instagram-reel")
    # Engagement question for IG too (saves/comments loop).
    question = platform_engagement_prompt_line(story_key(novel), "short_reel", "instagram", context=f"caption-{chapter}")
    return social_caption_link_in_bio("\n".join(
        [
            f"{profile['emoji']} {short_platform_intro(novel, chapter, 'instagram-reel')}",
            f"This is {profile['name']}.",
            destination["hook"],
            destination["links"],
            "",
            question,
            "",
            profile["hashtags"],
        ]
    ), "instagram")


def youtube_shorts_metadata(novel: str, chapter: str) -> dict[str, str]:
    profile = social_profile(novel)
    chapter_text = f" Chapter {chapter}" if chapter else ""
    abbr = story_key(novel) or next((k for k, v in NOVEL_NAMES.items() if v.lower() == str(novel).lower()), "")
    title = f"{profile['name']}{chapter_text} Promo #Shorts"
    hook = youtube_shorts_hook(abbr)
    destination = short_destination_copy(novel, chapter, source="youtube-shorts")
    # Lead with the proven hard hook (same pattern-interrupt that wins on TikTok) so the
    # Short's caption hooks in the feed and reinforces the frame-1 video opener. Plain
    # novel name is included for YouTube search indexing (viewers search book names).
    description = "\n".join(
        [
            hook,
            f"{profile['emoji']} {profile['name']}{chapter_text}.",
            destination["hook"],
            destination["links"],
            "",
            f"#Shorts #ShortsFeed {profile['name']} {profile['hashtags']}",
        ]
    )
    return {"title": title[:90], "description": description}


# Proven YouTube-Shorts hook format. These mirror the top-performing TikTok teasers
# ("Stop here if you like fantasy where one bad choice changes the whole arc...") that
# dominated the creator's Top Posts. YouTube Shorts retention was collapsing (92.7% skip)
# on the generic chapter-teaser openers, so Shorts now open with a hard pattern-interrupt
# hook instead of a slow chapter line. (2026-07-20, plan B.)
SHORT_HOOK_TEMPLATES = {
    "EN": "Stop here if you like cyberpunk fantasy where one bad choice rewrites reality.",
    "HA": "Stop here if you like cultivation where one bad choice changes the whole arc.",
    "SF": "Stop here if you like undercity fantasy where one forged choice changes everything.",
    "HP": "Stop here if you like xianxia where one small choice multiplies a hundredfold.",
}


def youtube_shorts_hook(abbr: str) -> str:
    """Hard pattern-interrupt opener for YouTube Shorts (frame-1 hook)."""
    abbr = story_key(abbr)
    return SHORT_HOOK_TEMPLATES.get(abbr, "Stop here if you like fantasy where one bad choice changes the whole arc.")


def tiktok_chapter_teaser_overlays(
    abbr: str,
    chapter: str | int,
    novel: str = "",
    *,
    chapter_text: str = "",
    fallback_text: str = "",
    platform: str = "tiktok",
) -> list[str]:
    abbr = story_key(abbr)
    novel = novel or NOVEL_NAMES.get(abbr, abbr)
    text = chapter_text
    chapter_value = str(chapter or "").strip()
    if not text and chapter_value.isdigit():
        try:
            text = str(docs_chapter_text(abbr, int(chapter_value)).get("text") or "")
        except Exception:
            text = ""
    candidates: list[str] = []
    for sentence in visual_sentences(text or fallback_text, 12, abbr or novel):
        cleaned = reel_overlay_text(sentence, limit=48)
        if cleaned and cleaned not in candidates:
            candidates.append(cleaned)
        if len(candidates) >= 3:
            break
    fallback_bits = [
        "A SECRET RISES FROM THE SHADOWS",
        "ONE CHOICE CHANGES EVERYTHING",
        "THE NEXT TRIAL BEGINS NOW",
    ]
    while len(candidates) < 3:
        candidates.append(fallback_bits[len(candidates)])
    # Lead every Short/Reel with the proven hard hook (frame-1 pattern-interrupt).
    # This is the creator's top-performing TikTok format, and it directly fights the
    # YouTube Shorts 92.7% skip rate that the slow chapter-teaser openers produced.
    candidates = [reel_overlay_text(youtube_shorts_hook(abbr), limit=48)] + candidates[:2]
    final = reel_overlay_text(f"READ {novel} ON ROYAL ROAD", limit=58)
    return candidates[:3] + [final]


def prepare_tiktok_outro_image(folder: Path, abbr: str, novel: str, chapter: str | int, style: str = "main-posts") -> str:
    pack_track = style if style in LORA_STYLE_TRACKS else "main-posts"
    target = folder / "novel-promo-card.png"
    # Only reuse a banked daily promo if its recorded track matches this pack's
    # track. Otherwise the outro card can mix a realistic/main promo into a
    # comic-style short (and vice versa). If no on-track banked image exists,
    # generate a fresh on-track outro instead of copying an off-style one.
    source = choose_rotating_daily_promo_image(abbr)
    if source and source.exists():
        sidecar = source.with_name(f"{source.name}.track")
        source_track = sidecar.read_text(encoding="utf-8").strip() if sidecar.exists() else ""
        if source_track == pack_track:
            shutil.copy2(source, target)
            target.with_name(f"{target.name}.track").write_text(pack_track, encoding="utf-8")
            return str(target)
    prompt = (
        f"Vertical 9:16 bold fantasy web novel promotional background for {novel} chapter {chapter}. "
        "Strong central composition, dramatic lighting, no text, no typography, no logo."
    )
    # Keep the outro on the same single pack track as the rest of the video (E).
    prompt = enhance_local_sd_prompt(prompt, orientation="vertical", lora_track=pack_track)
    create_prompt_fallback_image(prompt, target, 4, abbr, allow_banked=False, fresh=True)
    target.with_name(f"{target.name}.track").write_text(pack_track, encoding="utf-8")
    return str(target)


def make_tiktok_pack(*args, **kwargs):
    return promo_builder.make_tiktok_pack(*args, **kwargs)
def generate_tiktok_images(
    abbr: str,
    chapter: str,
    visual_prompt: str,
    force_new_images: bool = False,
    chapter_text: str = "",
    chapter_title: str = "",
    style: str = "main-posts",
) -> dict[str, Any]:
    # Single-style lock (Workstream E): every frame in a Shorts/Reels/TikTok pack must use
    # ONE LoRA track end-to-end. Default main-posts; caller may pass realistic-posts/comic-style.
    pack_track = style if style in LORA_STYLE_TRACKS else "main-posts"
    TIKTOK_ASSET_DIR.mkdir(parents=True, exist_ok=True)
    novel = NOVEL_NAMES.get(abbr, abbr)
    existing_pack = [] if force_new_images else chapter_image_pack(abbr, chapter, f"{novel} Chapter {chapter}")
    if len(existing_pack) >= 3:
        copied: list[str] = []
        for index, source in enumerate(existing_pack[:3], start=1):
            target = TIKTOK_ASSET_DIR / f"{abbr}_{chapter}_{index}.png"
            shutil.copy2(source, target)
            copied.append(str(target))
        return {
            "created": copied,
            "abbr": abbr,
            "chapter": chapter,
            "folder": str(TIKTOK_ASSET_DIR),
            "reused": [str(path) for path in existing_pack[:3]],
            "image_sources": [f"reused:{path}" for path in existing_pack[:3]],
            "image_prompts": [],
        }
    prompt_base = visual_prompt.strip() or f"{novel} chapter {chapter}, cinematic web novel promo art"
    scene_prompts: list[str] = []
    if chapter_text.strip():
        phrases = fallback_phrases(chapter_text, abbr)
        scene_prompts = make_chapter_image_prompts(chapter_title or f"Chapter {chapter}", chapter_text, phrases, novel)[:3]
    elif str(chapter).isdigit():
        try:
            chapter_data = docs_chapter_text(abbr, int(chapter))
            chapter_title = str(chapter_data.get("title") or f"Chapter {chapter}")
            chapter_text = str(chapter_data.get("text") or chapter_data.get("raw_text") or "")
            phrases = fallback_phrases(chapter_text, abbr)
            scene_prompts = make_chapter_image_prompts(chapter_title, chapter_text, phrases, novel)[:3]
        except Exception:
            scene_prompts = []
    created: list[str] = []
    image_sources: list[str] = []
    image_prompts: list[str] = []
    used_image_hashes: set[str] = set()
    for index in range(1, 4):
        target = TIKTOK_ASSET_DIR / f"{abbr}_{chapter}_{index}.png"
        scene_prompt = scene_prompts[index - 1] if index <= len(scene_prompts) else prompt_base
        prompt = (
            f"Vertical TikTok promo image {index} for {novel} chapter {chapter}. "
            f"{scene_prompt}. Cinematic, dramatic, readable composition, no text, 9:16 poster art."
        )
        # Bake the single pack_track into the prompt so generation stays on-style (E).
        prompt = enhance_local_sd_prompt(prompt, orientation="vertical", lora_track=pack_track)
        image_prompts.append(prompt)
        image_source = "openai"
        try:
            create_openai_image(prompt, target)
            if image_file_fingerprint(target) in used_image_hashes:
                image_source = create_unique_prompt_fallback_image(
                    prompt,
                    target,
                    index,
                    abbr,
                    used_hashes=used_image_hashes,
                    allow_banked=not force_new_images,
                    fresh=True,
                )
            else:
                used_image_hashes.add(image_file_fingerprint(target))
                state = mark_image_used(target)
                save_promo_rotation_state(state)
        except Exception:
            try:
                image_source = create_unique_prompt_fallback_image(
                    prompt,
                    target,
                    index,
                    abbr,
                    used_hashes=used_image_hashes,
                    allow_banked=not force_new_images,
                    fresh=force_new_images,
                )
            except Exception:
                source = None if force_new_images else choose_rotating_daily_promo_image(abbr)
                if not source:
                    raise
                shutil.copy2(source, target)
                image_source = f"rotating:{source}"
                fingerprint = image_file_fingerprint(target)
                if fingerprint in used_image_hashes:
                    raise RuntimeError("Fallback daily promo image matched an earlier generated image.")
                used_image_hashes.add(fingerprint)
                state = mark_image_used(target)
                save_promo_rotation_state(state)
        created.append(str(target))
        image_sources.append(image_source)
        archive_generated_promo_image(target, abbr, f"{novel} Chapter {chapter}", f"tiktok-{index}")
        # E1: record the pack track as a sidecar so list_tiktok_assets / make_tiktok_pack can
        # lock a single style per video even when reusing pre-generated assets.
        try:
            target.with_name(f"{target.name}.track").write_text(pack_track, encoding="utf-8")
        except Exception:
            pass
    return {
        "created": created,
        "abbr": abbr,
        "chapter": chapter,
        "folder": str(TIKTOK_ASSET_DIR),
        "image_sources": image_sources,
        "image_prompts": image_prompts,
    }


def make_or_generate_tiktok_pack(
    abbr: str,
    chapter: str,
    visual_prompt: str = "",
    force_new_images: bool = False,
    chapter_text: str = "",
    chapter_title: str = "",
    style: str = "main-posts",
) -> dict[str, Any]:
    if not abbr or not str(chapter).strip():
        raise RuntimeError("Choose a novel and enter a chapter number for TikTok.")
    assets = list_tiktok_assets()
    matching_groups = [group for group in assets["imageGroups"] if group["abbr"] == abbr and group["chapter"] == str(chapter)]
    complete = any(int(group.get("count", 0)) >= 3 for group in matching_groups)
    should_generate = force_new_images or not complete or not ALLOW_SAME_CHAPTER_IMAGE_REUSE
    generation: dict[str, Any] | None = None
    if should_generate:
        generation = generate_tiktok_images(
            abbr,
            str(chapter),
            visual_prompt,
            force_new_images=True,
            chapter_text=chapter_text,
            chapter_title=chapter_title,
            style=style,
        )
    result = make_tiktok_pack(
        abbr,
        str(chapter),
        force_new_images=should_generate,
        visual_prompt=visual_prompt,
        chapter_text=chapter_text,
        style=style,
    )
    if generation:
        result["image_sources"] = generation.get("image_sources", [])
        result["image_prompts"] = generation.get("image_prompts", [])
        metadata_path = Path(str(result.get("folder") or "")) / "metadata.json"
        if metadata_path.parent.exists():
            metadata_path.write_text(json.dumps(result, indent=2), encoding="utf-8")
    return result


def rebuild_normal_tiktok_video_from_metadata(target: Path, metadata: dict[str, Any]) -> dict[str, Any]:
    if not str(target.resolve()).startswith(str(TIKTOK_OUTPUT_DIR.resolve())):
        raise RuntimeError("Shorts/Reels folder is not valid.")
    abbr = story_key(str(metadata.get("abbr") or ""))
    chapter = str(metadata.get("chapter") or metadata.get("chapter_number") or "").strip()
    novel = str(metadata.get("novel") or NOVEL_NAMES.get(abbr, abbr or "Azure Inkblade"))
    images = [str(Path(str(item)).resolve()) for item in metadata.get("images", []) or [] if Path(str(item)).exists()]
    if len(images) < 3:
        raise RuntimeError("This Shorts/Reels pack needs at least three valid images before the MP4 can be rebuilt.")
    if len(images) < 4:
        rebuild_track = metadata.get("packTrack") or metadata.get("loraTrack") or "main-posts"
        images.append(prepare_tiktok_outro_image(target, abbr, novel, chapter or "", style=rebuild_track))
        metadata["images"] = images
    sound = Path(str(metadata.get("sound") or ""))
    if not sound.exists():
        sound = next((path for path in target.iterdir() if path.is_file() and path.suffix.lower() in AUDIO_EXTENSIONS), None)
    if not sound or not sound.exists():
        sounds = [
            Path(str(item.get("path") or ""))
            for item in list_tiktok_assets().get("sounds", [])
            if str(item.get("path") or "").strip() and Path(str(item.get("path") or "")).exists()
        ]
        if not sounds:
            raise RuntimeError("No Shorts/Reels audio file is available.")
        sound_source = random.choice(sounds)
        sound = target / sound_source.name
        shutil.copy2(sound_source, sound)
    overlays = list(metadata.get("video_overlays") or [])
    if len(overlays) < len(images):
        overlays = tiktok_chapter_teaser_overlays(abbr, chapter, novel, fallback_text=str(metadata.get("caption") or metadata.get("visual_prompt") or ""))
    # Voiceover narration over ducked music (local-first TTS; fail-soft to music-only).
    narration_text = tiktok_narration_text(metadata, overlays)
    narration_target = generate_deep_tiktok_narration(target, abbr, narration_text) if narration_text else None
    write_tiktok_video_helper(target, images[:4], sound, overlays=overlays[:4], narration=narration_target)
    build = run_generated_video_builder(target, "make_tiktok_video.py", "tiktok-video.mp4", timeout=900)
    video = target / "tiktok-video.mp4"
    metadata["sound"] = str(sound)
    metadata["video"] = str(video) if video.exists() else ""
    metadata["duration"] = media_duration_seconds(video) if video.exists() else 0.0
    metadata["video_build"] = build
    metadata["videoRebuiltAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    if build.get("created"):
        metadata["videoNeedsRebuild"] = False
        metadata["packStatusOverride"] = ""
        metadata.pop("github_media_publish", None)
        metadata.pop("public_media_urls", None)
        if abbr and chapter:
            try:
                update_chapter_ledger(
                    abbr,
                    chapter,
                    {
                        "shortsReelsBuilt": True,
                        "shortsPackBuilt": True,
                        "shortsNeedsRebuild": False,
                        "shortsMissingReason": "",
                        "shortsPackBuiltAt": time.strftime("%Y-%m-%d %H:%M:%S"),
                        "shortsFolder": str(target),
                        "folders": {"shorts": str(target)},
                    },
                )
            except Exception:
                pass
    else:
        metadata["videoNeedsRebuild"] = True
        metadata["packStatusOverride"] = "needs_video_build"
    metadata.update(normalize_pack_metadata(target, metadata, persist=False))
    write_json_atomic(target / "metadata.json", metadata)
    if not build.get("created"):
        raise RuntimeError(str(build.get("message") or "Shorts/Reels MP4 rebuild finished, but no valid video was created."))
    return build


def write_animated_reel_builder_script(
    folder: Path,
    images: list[str],
    sound: Path,
    overlays: list[str],
    *,
    target_duration: int,
    draw_overlays: bool = True,
    deep: bool = False,
    narration: Path | None = None,
) -> Path:
    sound = Path(sound).resolve()
    if not sound.is_file() or sound.suffix.lower() not in AUDIO_EXTENSIONS:
        raise RuntimeError("A valid audio file is required before building a TikTok/Reel video.")
    ffmpeg_exe = find_ffmpeg_executable()
    narration_ref = Path(narration).resolve() if narration and Path(narration).exists() else None
    narration_name = narration_ref.name if narration_ref else ""
    script = folder / "make_tiktok_video.py"
    slide_duration = max(5 if not deep else 7, math.ceil(target_duration / max(1, len(images))))
    script.write_text(
        f'''from pathlib import Path
import math
import subprocess
import wave
import audioop
import random
# PIL is only needed by the MoviePy renderer; the FFmpeg fallback (the renderer
# used in practice) does not need it. Import lazily/guarded so a broken PIL
# install does not crash the whole script before the FFmpeg path can run.
try:
    from PIL import Image
except Exception:
    Image = None

folder = Path(__file__).resolve().parent
images = {[Path(image).name for image in images]!r}
overlays = {overlays!r}
draw_overlays = {bool(draw_overlays)!r}
sound = folder / {sound.name!r}
narration_audio = folder / {narration_name!r} if {('True' if narration_ref else 'False')} else None
ffmpeg_exe = {ffmpeg_exe!r}
output = folder / "tiktok-video.mp4"
silent_output = folder / "tiktok-video-silent.mp4"
target_duration = {int(target_duration)}
cta_duration = 3
CTA_VARIANTS = [
    "Like & Subscribe!",
    "Subscribe for more!",
    "Like & follow for more!",
    "Hit Subscribe, more soon!",
    "Like & Subscribe for more!",
]
cta_text = random.choice(CTA_VARIANTS)
target_duration = target_duration + cta_duration
slide_duration = {slide_duration}
deep_mode = {bool(deep)!r}

def drawtext_escape(value):
    return value.replace("\\\\", "\\\\\\\\").replace(":", "\\\\:").replace("'", "\\\\'")

def safe_text(value, max_chars=118):
    value = " ".join(str(value or "").replace("\\n", " ").split())
    return value[:max_chars].rsplit(" ", 1)[0] if len(value) > max_chars and " " in value[:max_chars] else value[:max_chars]

def make_overlay_image(text, size=(1080, 1920), final=False):
    from PIL import ImageDraw, ImageFont
    overlay = Image.new("RGBA", size, (0, 0, 0, 0))
    if not text:
        return overlay
    draw = ImageDraw.Draw(overlay)
    font_candidates = [
        "C:/Windows/Fonts/impact.ttf",
        "C:/Windows/Fonts/bahnschrift.ttf",
        "C:/Windows/Fonts/segoeuib.ttf",
        "C:/Windows/Fonts/arialbd.ttf",
    ]
    font_size = 78 if final else (58 if deep_mode else 64)
    font = None
    for font_path in font_candidates:
        try:
            font = ImageFont.truetype(font_path, font_size)
            break
        except Exception:
            font = None
    if font is None:
        font = ImageFont.load_default()
    lines = []
    words = safe_text(text, 150).split()
    line = ""
    max_width = int(size[0] * 0.78)
    for word in words:
        test = (line + " " + word).strip()
        box = draw.textbbox((0, 0), test, font=font, stroke_width=2)
        if box[2] - box[0] <= max_width or not line:
            line = test
        else:
            lines.append(line)
            line = word
    if line:
        lines.append(line)
    lines = lines[:3]
    line_heights = []
    max_line_width = 0
    for value in lines:
        box = draw.textbbox((0, 0), value, font=font, stroke_width=2)
        max_line_width = max(max_line_width, box[2] - box[0])
        line_heights.append(box[3] - box[1])
    total_h = sum(line_heights) + max(0, len(lines) - 1) * 12
    y = int(size[1] * (0.70 if not final else 0.72))
    text_y = y
    for value, height in zip(lines, line_heights):
        box = draw.textbbox((0, 0), value, font=font, stroke_width=2)
        text_x = int((size[0] - (box[2] - box[0])) / 2)
        draw.text((text_x, text_y), value, font=font, fill=(255, 255, 255, 250), stroke_width=3, stroke_fill=(0, 0, 0, 225))
        text_y += height + 12
    return overlay

def normalize_audio_if_wav(path):
    if path.suffix.lower() != ".wav":
        return path
    try:
        with wave.open(str(path), "rb") as src:
            params = src.getparams()
            frames = src.readframes(src.getnframes())
        rms = audioop.rms(frames, params.sampwidth)
        if rms <= 0:
            return path
        target_rms = 2400
        factor = max(0.4, min(2.8, target_rms / rms))
        adjusted = audioop.mul(frames, params.sampwidth, factor)
        out = path.with_name(path.stem + "-normalized.wav")
        with wave.open(str(out), "wb") as dst:
            dst.setparams(params)
            dst.writeframes(adjusted)
        return out
    except Exception:
        return path

clean_images = []
for index, image in enumerate(images, start=1):
    source = folder / image
    clean = folder / f"animated-reel-clean-{{index}}.png"
    try:
        with Image.open(source) as im:
            im.convert("RGB").save(clean, "PNG")
        clean_images.append(clean.name)
    except Exception:
        clean_images.append(clean.name)
    except Exception:
        clean_images.append(image)

def render_with_moviepy():
    import numpy as np
    from moviepy import VideoClip, AudioFileClip, concatenate_videoclips
    from moviepy.audio.fx import AudioLoop
    clips = []
    size = (1080, 1920)
    for index, image_name in enumerate(clean_images, start=1):
        source = folder / image_name
        with Image.open(source) as im:
            im = im.convert("RGB")
            scale = max(size[0] / im.width, size[1] / im.height)
            base_w, base_h = int(im.width * scale), int(im.height * scale)
            im = im.resize((base_w, base_h), Image.Resampling.LANCZOS)
            base = im.copy()
        overlay_text = overlays[index - 1] if index - 1 < len(overlays) else ""
        overlay_image = make_overlay_image(overlay_text, size=size, final=(index == len(clean_images))) if draw_overlays else Image.new("RGBA", size, (0,0,0,0))
        drift = -1 if index % 2 else 1
        def make_frame(t, base=base, overlay_image=overlay_image, drift=drift, index=index):
            progress = min(1.0, max(0.0, t / max(slide_duration, 0.1)))
            zoom = 1.0 + (0.045 if deep_mode else 0.035) * progress
            frame_w = max(size[0], int(size[0] * zoom))
            frame_h = max(size[1], int(size[1] * zoom))
            resized = base.resize((max(frame_w, int(base.width * zoom)), max(frame_h, int(base.height * zoom))), Image.Resampling.LANCZOS)
            max_x = max(0, resized.width - size[0])
            max_y = max(0, resized.height - size[1])
            pan_x = int(max_x * (0.5 + drift * 0.18 * (progress - 0.5)))
            pan_y = int(max_y * (0.45 + 0.12 * math.sin((progress + index * 0.17) * math.pi)))
            composed = resized.crop((pan_x, pan_y, pan_x + size[0], pan_y + size[1])).convert("RGBA")
            fade = min(1.0, t / 0.35, (slide_duration - t) / 0.35 if slide_duration - t < 0.35 else 1.0)
            if fade < 1:
                veil = Image.new("RGBA", size, (0, 0, 0, int(255 * (1 - max(0, fade)))))
                composed.alpha_composite(veil)
            composed.alpha_composite(overlay_image)
            return np.array(composed.convert("RGB"))
        clips.append(VideoClip(make_frame, duration=slide_duration).with_fps(30))
    if not clips:
        raise RuntimeError("No image clips were available.")
    video = concatenate_videoclips(clips, method="compose")
    if sound.exists():
        audio_path = normalize_audio_if_wav(sound)
        music = AudioFileClip(str(audio_path))
        if music.duration < target_duration:
            music = music.with_effects([AudioLoop(duration=target_duration)])
        music = music.with_duration(target_duration)
        # Narration (if any) plays at natural length on top of ducked music.
        # NOTE: keep narration at its real duration -- do NOT stretch it to
        # target_duration (that slows the speech). The composite audio length
        # is set by `music` (looped to target_duration), so the video stays
        # target_duration long with the voiceover playing once at the start.
        if narration_audio and Path(narration_audio).exists():
            try:
                narration = AudioFileClip(str(narration_audio))
                video = video.with_audio(CompositeAudioClip([narration, music.volumex(0.22)]))
            except Exception as audio_exc:
                print(f"Narration mix failed, using music only: {{audio_exc}}")
                video = video.with_audio(music)
        else:
            video = video.with_audio(music)
    video = video.with_duration(target_duration)
    video.write_videofile(str(output), fps=30, codec="libx264", audio_codec="aac", bitrate="5000k", audio_bitrate="160k", preset="medium", threads=4, logger=None)

def render_with_ffmpeg_fallback():
    print("MoviePy animation unavailable; using FFmpeg fallback.")
    clips = []
    for index, image in enumerate(clean_images, start=1):
        source = folder / image
        overlay = overlays[index - 1] if index - 1 < len(overlays) else ""
        clip = folder / f"tiktok-slide-{{index}}.mp4"
        fade_out = max(0.0, slide_duration - 0.35)
        draw = (
            "scale=1200:2134:force_original_aspect_ratio=increase,crop=1200:2134,"
            "zoompan=z='min(zoom+0.00065,1.075)':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':"
            f"d={{slide_duration * 30}}:s=1080x1920:fps=30,"
            f"fade=t=in:st=0:d=0.35,fade=t=out:st={{fade_out}}:d=0.35"
        )
        if draw_overlays and overlay:
            fontsize = 80 if index == len(clean_images) else (56 if deep_mode else 62)
            draw += (
                ",drawtext=fontfile='C\\\\:/Windows/Fonts/impact.ttf':"
                "text='" + drawtext_escape(overlay) + "':"
                "fontcolor=white:fontsize=" + str(fontsize) + ":line_spacing=12:"
                "borderw=5:bordercolor=black@0.82:"
                "x=(w-text_w)/2:y=h*0.70"
            )
        subprocess.run([ffmpeg_exe, "-y", "-loop", "1", "-i", str(source), "-t", str(slide_duration), "-vf", draw, "-r", "30", "-an", "-pix_fmt", "yuv420p", str(clip)], check=False)
        if clip.exists():
            clips.append(clip)
    # CTA outro slide (Like & Subscribe) -- held/drifting frame from the last
    # image, darkened, with the CTA text centered. Appended as a fixed-length
    # outro so the concat + music/narration (keyed to target_duration,
    # which was bumped by cta_duration) cover it automatically.
    try:
        last_src = folder / clean_images[-1]
        cta_clip = folder / "tiktok-cta.mp4"
        cta_draw = (
            "scale=1200:2134:force_original_aspect_ratio=increase,crop=1200:2134,"
            "zoompan=z='min(zoom+0.0004,1.05)':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':"
            f"d={{cta_duration * 30}}:s=1080x1920:fps=30,"
            "eq=brightness=-0.28,"
            "fade=t=in:st=0:d=0.35,"
            "drawtext=fontfile='C\\\\:/Windows/Fonts/impact.ttf':"
            "text='" + drawtext_escape(cta_text) + "':"
            "fontcolor=white:fontsize=60:line_spacing=14:"
            "borderw=6:bordercolor=black@0.85:"
            "x=(w-text_w)/2:y=(h-text_h)/2"
        )
        subprocess.run([ffmpeg_exe, "-y", "-loop", "1", "-i", str(last_src), "-t", str(cta_duration), "-vf", cta_draw, "-r", "30", "-an", "-pix_fmt", "yuv420p", str(cta_clip)], check=False)
        if cta_clip.exists():
            clips.append(cta_clip)
        else:
            print(f"CTA slide not created; continuing without it.")
    except Exception as cta_exc:
        print(f"CTA slide skipped: {{cta_exc}}")
    if not clips:
        raise SystemExit("ffmpeg did not create any TikTok/Reel slides.")
    concat = folder / "tiktok-slides.txt"
    concat.write_text("\\n".join([f"file '{{clip}}'" for clip in clips]) + "\\n", encoding="utf-8")
    subprocess.run([ffmpeg_exe, "-y", "-f", "concat", "-safe", "0", "-i", str(concat), "-c:v", "libx264", "-pix_fmt", "yuv420p", str(silent_output)], check=False)
    subprocess.run([ffmpeg_exe, "-y", "-i", str(silent_output), "-stream_loop", "-1", "-i", str(sound), "-t", str(target_duration), "-map", "0:v:0", "-map", "1:a:0", "-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "160k", "-af", "volume=0.46,afade=t=in:st=0:d=1,afade=t=out:st=" + str(max(0, target_duration - 3)) + ":d=3", "-shortest", "-movflags", "+faststart", str(output)], check=False)
    # Narration (if present) mixed over ducked music for a voiced reel.
    if narration_audio and Path(narration_audio).exists():
        narrated = folder / "tiktok-video-narrated.mp4"
        music_duck = folder / "tiktok-music-ducked.m4a"
        subprocess.run([ffmpeg_exe, "-y", "-i", str(sound), "-t", str(target_duration), "-af", "volume=0.22,afade=t=in:st=0:d=1,afade=t=out:st=" + str(max(0, target_duration - 3)) + ":d=3", "-c:a", "aac", "-b:a", "128k", str(music_duck)], check=False)
        subprocess.run([ffmpeg_exe, "-y", "-i", str(output), "-i", str(narration_audio), "-i", str(music_duck) if music_duck.exists() else str(sound), "-map", "0:v:0", "-filter_complex", "[1:a][2:a]amix=inputs=2:duration=longest:dropout_transition=0[a]", "-map", "[a]", "-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "192k", "-t", str(target_duration), "-movflags", "+faststart", str(narrated)], check=False)
        if narrated.exists() and narrated.stat().st_size > 1024:
            import shutil as _shutil
            _shutil.move(str(narrated), str(output))

try:
    render_with_moviepy()
    print("Animated reel created with MoviePy motion renderer.")
except Exception as exc:
    print(f"MoviePy renderer failed: {{exc}}")
    render_with_ffmpeg_fallback()

print(f"TikTok video target: {{output}}")
''',
        encoding="utf-8",
    )
    (folder / "video-overlays.txt").write_text("\n".join(overlays) + "\n", encoding="utf-8")
    return script


def write_tiktok_video_helper(folder: Path, images: list[str], sound: Path, overlays: list[str] | None = None, narration: Path | None = None) -> None:
    overlay_values = overlays or ["", "", "", ""]
    write_animated_reel_builder_script(
        folder,
        images[:4],
        sound,
        overlay_values[:4],
        target_duration=20,
        draw_overlays=True,
        deep=False,
        narration=narration,
    )


def deep_tiktok_chapter_moments(chapter_text: str, abbr: str, count: int = 8) -> list[str]:
    sentences = [sentence for sentence in sentence_split(chapter_body_for_marketing(chapter_text)) if len(sentence.split()) >= 7]
    if not sentences:
        return ["A new trial begins and the balance of power changes."] * count
    moments: list[str] = []
    for index in range(count):
        start = math.floor(index * len(sentences) / count)
        end = max(start + 1, math.floor((index + 1) * len(sentences) / count))
        segment = sentences[start:end]
        chosen = max(segment, key=lambda sentence: visual_score(sentence, abbr))
        cleaned = clean_teaser_text(chosen, limit=180, max_words=28)
        if cleaned and cleaned not in moments:
            moments.append(cleaned)
    for sentence in sorted(sentences, key=lambda value: visual_score(value, abbr), reverse=True):
        cleaned = clean_teaser_text(sentence, limit=180, max_words=28)
        if cleaned and cleaned not in moments:
            moments.append(cleaned)
        if len(moments) >= count:
            break
    progression_fallbacks = [
        "The chapter opens with a choice that cannot be taken back.",
        "A hidden danger moves closer while the characters search for answers.",
        "The central conflict forces an alliance under pressure.",
        "A new revelation changes what the characters thought they understood.",
        "The cost of the confrontation becomes impossible to ignore.",
        "Power shifts as the chapter reaches its decisive moment.",
        "The immediate threat is answered, but a larger problem remains.",
        "The final scene leaves the next step hanging in the balance.",
    ]
    for fallback in progression_fallbacks:
        if len(moments) >= count:
            break
        if fallback not in moments:
            moments.append(fallback)
    return moments[:count]


DEEP_TIKTOK_BAD_OVERLAY_RE = re.compile(
    r"(establishing|world shot|wide shot|close[- ]?up|camera|scene focus|scene \d+|"
    r"visual beat|visual prompt|image prompt|prompt:|panel|frame|storyboard|"
    r"protagonist in motion|tense confrontation|intimate emotional beat|"
    r"startling revelation|dangerous environment|quiet character moment|haunting closing image|"
    r"realistic cinematic|promotional image|theme:|photorealistic|no text|"
    r"typography|logo|web novel|novel title|chapter title|chapter \d+ teaser)",
    re.IGNORECASE,
)


def sanitize_deep_tiktok_overlay(text: str, novel: str = "", fallback: str = "") -> str:
    cleaned = clean_teaser_text(str(text or ""), limit=110, max_words=12)
    lower = cleaned.lower()
    novel_lower = str(novel or "").strip().lower()
    if ":" in cleaned and DEEP_TIKTOK_BAD_OVERLAY_RE.search(cleaned.split(":", 1)[0]):
        cleaned = cleaned.split(":", 1)[1].strip()
        lower = cleaned.lower()
    invalid = (
        not cleaned
        or bool(DEEP_TIKTOK_BAD_OVERLAY_RE.search(cleaned))
        or (novel_lower and lower == novel_lower)
        or (novel_lower and lower.startswith(novel_lower))
        or len(cleaned.split()) < 3
    )
    if invalid:
        cleaned = fallback or "A hidden choice changes everything."
    if DEEP_TIKTOK_BAD_OVERLAY_RE.search(cleaned):
        cleaned = "A hidden choice changes everything."
    return reel_overlay_text(cleaned, limit=58)


def deep_tiktok_novel_overlay_fallbacks(novel: str, count: int = 8) -> list[str]:
    lines = [
        "A quiet moment turns into a test.",
        "The first clue refuses to stay buried.",
        "Power answers when fear runs out.",
        "One choice changes the path forward.",
        "The danger was closer than it looked.",
        "A hidden truth pushes into the light.",
        "The next step costs more than expected.",
        "The story is only getting sharper.",
    ]
    return lines[:count]


def deep_tiktok_caption(abbr: str, chapter: str, title: str, hook: str) -> str:
    novel = NOVEL_NAMES.get(abbr, abbr)
    profile = social_profile(abbr)
    chapter_label = "Prologue" if str(chapter).strip() in {"0", "prologue", "Prologue"} else f"Chapter {chapter}"
    title_tail = re.sub(rf"^{re.escape(chapter_label)}\s*[:.\-\u2013\u2014]?\s*", "", str(title or "").strip(), flags=re.IGNORECASE).strip()
    title_suffix = f": {title_tail}" if title_tail else ""
    return "\n".join(
        [
            f"A deeper look at {novel} {chapter_label}{title_suffix}",
            hook,
            "Watch the full story beat, then continue the chapter.",
            "Read now. Link in bio.",
            "",
            profile["hashtags"],
        ]
    )


def deep_tiktok_title(abbr: str, chapter: str, title: str) -> str:
    novel = NOVEL_NAMES.get(story_key(abbr), story_key(abbr) or "Azure Inkblade")
    chapter_label = "Prologue" if str(chapter).strip() in {"0", "prologue", "Prologue"} else f"Chapter {chapter}"
    cleaned_title = re.sub(r"\s+", " ", str(title or chapter_label)).strip()
    cleaned_title = re.sub(rf"^{re.escape(chapter_label)}\s*[:.\-\u2013\u2014]?\s*", "", cleaned_title, flags=re.IGNORECASE).strip()
    if not cleaned_title:
        return f"{novel} {chapter_label} | 60 Second Chapter Dive"[:95]
    return f"{novel} {chapter_label}: {cleaned_title} | 60 Second Chapter Dive"[:95]


def deep_tiktok_folder_selection(folder: Path, metadata: dict[str, Any] | None = None) -> tuple[str, str]:
    metadata = metadata or {}
    abbr = story_key(str(metadata.get("abbr") or ""))
    chapter = str(metadata.get("chapter") or metadata.get("chapter_number") or "").strip()
    if abbr and chapter:
        return abbr, chapter
    match = re.match(r"^(?P<abbr>en|ha|sf|hp)-(?P<chapter>\d+[a-z]?|prologue)-deep$", folder.name, re.IGNORECASE)
    if not match:
        return abbr, chapter
    abbr = abbr or match.group("abbr").upper()
    chapter = chapter or ("0" if match.group("chapter").lower() == "prologue" else match.group("chapter"))
    return abbr, chapter


def repair_deep_tiktok_metadata(folder: Path, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    metadata = dict(metadata or read_metadata(folder))
    abbr, chapter = deep_tiktok_folder_selection(folder, metadata)
    if not abbr or not chapter:
        return metadata
    title = str(metadata.get("title") or "").strip()
    chapter_text = ""
    try:
        chapter_data = docs_chapter_text(abbr, int(chapter))
        title = title or str(chapter_data.get("title") or chapter_data.get("heading") or f"Chapter {chapter}")
        chapter_text = str(chapter_data.get("text") or chapter_data.get("raw_text") or "")
    except Exception:
        title = title or ("Prologue" if str(chapter) == "0" else f"Chapter {chapter}")
    novel = NOVEL_NAMES.get(abbr, abbr)
    overlays_file = folder / "video-overlays.txt"
    overlays = [line.strip() for line in overlays_file.read_text(encoding="utf-8").splitlines() if line.strip()] if overlays_file.exists() else []
    scene_fallbacks = deep_tiktok_chapter_moments(chapter_text, abbr, max(8, len(overlays))) if chapter_text else []
    if not scene_fallbacks:
        scene_fallbacks = deep_tiktok_novel_overlay_fallbacks(novel, max(8, len(overlays) or 8))
    sanitized_overlays: list[str] = []
    for index, line in enumerate(overlays):
        fallback = scene_fallbacks[index % len(scene_fallbacks)] if scene_fallbacks else ""
        sanitized_overlays.append(sanitize_deep_tiktok_overlay(line, novel, fallback))
    if sanitized_overlays and sanitized_overlays != overlays:
        overlays = sanitized_overlays
        overlays_file.write_text("\n".join(overlays) + "\n", encoding="utf-8")
    if not overlays and chapter_text:
        overlays = [
            sanitize_deep_tiktok_overlay(moment, novel, deep_tiktok_novel_overlay_fallbacks(novel, 1)[0])
            for moment in deep_tiktok_chapter_moments(chapter_text, abbr, 8)
        ]
        overlays.append(reel_overlay_text("Read the next chapter. Link in bio.", limit=62))
        overlays_file.write_text("\n".join(overlays) + "\n", encoding="utf-8")
    hook = (overlays[0].replace("\n", " ") if overlays else f"A deeper look at {novel}").strip()
    chapter_label = "Prologue" if str(chapter).strip() in {"0", "prologue", "Prologue"} else f"Chapter {chapter}"
    caption = str(metadata.get("caption") or "").strip() or deep_tiktok_caption(abbr, str(chapter), title, hook)
    caption = social_caption_link_in_bio(caption, "tiktok")
    if f"{chapter_label}: {chapter_label}" in caption:
        caption = caption.replace(f"{chapter_label}: {chapter_label}", chapter_label)
    metadata["tiktok_title"] = deep_tiktok_title(abbr, str(chapter), title)
    metadata.update(
        {
            "kind": "deep_tiktok",
            "abbr": abbr,
            "novel": novel,
            "chapter": str(chapter),
            "title": title,
            "description": social_caption_link_in_bio(str(metadata.get("description") or "").strip() or caption, "tiktok"),
            "caption": caption,
            "tiktok_title": str(metadata.get("tiktok_title") or "").strip() or deep_tiktok_title(abbr, str(chapter), title),
            "video_overlays": overlays or metadata.get("video_overlays") or [],
            "duration_target": metadata.get("duration_target") or 68,
            "platforms": metadata.get("platforms") or ["tiktok"],
            "folder": str(folder),
            "youtube_shorts_disabled": True,
            "youtube_shorts_reason": "Deep chapter TikToks are reserved for TikTok growth testing.",
        }
    )
    if chapter_text:
        metadata.setdefault("source_hash", content_hash(chapter_text))
    images = list(metadata.get("images") or [])
    if not images:
        images = [str(path) for path in sorted(folder.glob("deep-scene-*.png"))]
        outro = folder / "tiktok-outro.png"
        if outro.exists():
            images.append(str(outro))
    if images:
        metadata["images"] = images
    candidate_images = [str(path) for path in sorted(folder.glob("deep-scene-*.png"), key=lambda path: [int(value) if value.isdigit() else value for value in re.split(r"(\d+)", path.name)])]
    promo_card = folder / "novel-promo-card.png"
    if promo_card.exists():
        candidate_images.append(str(promo_card))
    if candidate_images:
        metadata["candidate_images"] = candidate_images
    candidate_sources = list(metadata.get("candidate_image_sources") or [])
    if not candidate_sources and isinstance(metadata.get("image_sources"), list):
        candidate_sources = list(metadata.get("image_sources") or [])
    if len(candidate_sources) < len(candidate_images):
        candidate_sources.extend(["deep-tiktok-scene"] * (len(candidate_images) - len(candidate_sources)))
    if candidate_images:
        metadata["candidate_image_sources"] = candidate_sources[: len(candidate_images)]
    image_sources = list(metadata.get("image_sources") or [])
    if len(image_sources) < len(images):
        image_sources.extend(["deep-tiktok-scene"] * (len(images) - len(image_sources)))
        metadata["image_sources"] = image_sources
    if images and not metadata.get("image_prompts"):
        metadata["image_prompts"] = []
        scene_texts = (
            deep_tiktok_chapter_moments(chapter_text, abbr, len(images))
            if chapter_text and abbr
            else []
        )
        for index in range(len(images)):
            source = scene_texts[index] if index < len(scene_texts) else title or novel
            metadata["image_prompts"].append(
                f"Deep TikTok scene {index + 1} for {novel} {chapter_label}: {clean_teaser_text(str(source), limit=140, max_words=24)}"
            )
    approved = metadata.get("approved_images")
    if not isinstance(approved, list):
        approved = []
    if not metadata.get("approvalManual"):
        for path in images:
            name = Path(str(path)).name.lower()
            if re.search(r"deep-scene-(1|2|8)\.png$", name) or re.search(r"(novel-promo-card|tiktok-outro)\.png$", name):
                if str(path) not in approved:
                    approved.append(str(path))
    rejected = metadata.get("rejected_images")
    if not isinstance(rejected, list):
        rejected = []
    rejected_keys = {
        str(Path(str(path)).resolve()).lower()
        for path in rejected
        if str(path or "").strip() and Path(str(path)).exists()
    }
    if rejected_keys:
        approved = [path for path in approved if str(Path(str(path)).resolve()).lower() not in rejected_keys]
        images = [path for path in images if str(Path(str(path)).resolve()).lower() not in rejected_keys or Path(str(path)).name.lower() == "novel-promo-card.png"]
        metadata["images"] = images
        metadata["approved_images"] = approved
        metadata["rejected_images"] = [
            str(Path(str(path)).resolve())
            for path in rejected
            if str(path or "").strip() and Path(str(path)).exists()
        ]
    if approved:
        metadata["approved_images"] = approved
    sound = str(metadata.get("sound") or "").strip()
    if not sound:
        audio = next((path for path in folder.iterdir() if path.is_file() and path.suffix.lower() in AUDIO_EXTENSIONS), None)
        if audio:
            metadata["sound"] = str(audio)
    video = folder / "tiktok-video.mp4"
    if video.exists():
        metadata["video"] = str(video)
        metadata["duration"] = media_duration_seconds(video)
    (folder / "caption.txt").write_text(caption + "\n", encoding="utf-8")
    (folder / "description.txt").write_text(caption + "\n", encoding="utf-8")
    (folder / "tiktok-title.txt").write_text(metadata["tiktok_title"] + "\n", encoding="utf-8")
    metadata.update(normalize_pack_metadata(folder, metadata, persist=False))
    (folder / "metadata.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    return metadata


def generate_deep_tiktok_narration(folder: Path, abbr: str, caption: str) -> Path | None:
    """Local-first TTS narration for the deep TikTok (Chatterbox -> Windows -> SAPI -> OpenAI).

    Fail-soft: returns None on any failure so the pack still builds with music only.
    """
    try:
        import tts_service
        narration_text = caption.strip().split("\n\n")[0].strip()
        if not narration_text:
            return None
        result = tts_service.generate_post_audio(narration_text, folder, abbr=abbr)
        if result.get("status") == "ready" and result.get("path") and Path(result["path"]).exists():
            target = folder / "tiktok-narration.mp3"
            shutil.copy2(result["path"], target)
            return target
        print(f"[deep-tiktok-narration] TTS unavailable ({result.get('status')}); music only.", file=sys.stderr)
    except Exception as exc:
        print(f"[deep-tiktok-narration] failed: {exc}", file=sys.stderr)
    return None


def tiktok_narration_text(metadata: dict[str, Any] | None, overlays: list[str] | None = None) -> str:
    """Natural, speakable sentence for the short's voiceover.

    The on-screen overlay sticker (overlays[0]) is uppercase marketing shorthand
    like "STOP HERE IF YOU LIKE CULTIVATION..." -- NOT speakable. Use the post
    caption's first natural sentence(s) instead (emoji/newlines stripped).
    Falls back to the overlay only if no caption is available.
    """
    meta = metadata or {}
    caption = str(meta.get("caption") or meta.get("tiktok") or "").strip()
    if caption:
        # Drop emoji / leading symbols, collapse whitespace, take first 2 sentences.
        import unicodedata
        cleaned = "".join(ch for ch in caption if not unicodedata.category(ch).startswith("So"))
        cleaned = " ".join(cleaned.split())
        parts = [p.strip() for p in re.split(r"(?<=[.!?])\s+", cleaned) if p.strip()]
        spoken = " ".join(parts[:2])
        if spoken:
            return spoken
    if overlays:
        return overlays[0].replace("\n", " ").strip()
    return ""


def write_deep_tiktok_video_helper(
    folder: Path,
    images: list[str],
    sound: Path,
    overlays: list[str] | None = None,
    narration: Path | None = None,
    draw_overlays: bool = True,
) -> None:
    return write_animated_reel_builder_script(
        folder,
        images,
        sound,
        overlays,
        target_duration=68,
        draw_overlays=draw_overlays,
        deep=True,
        narration=narration,
    )


def load_deep_tiktok_rotation() -> dict[str, Any]:
    # SC-4 cutover: SQLite (state_snapshots.deepTikTokRotation) is the source of
    # truth. The chapter-ledger merge stays app-side; only JSON I/O moved to fsr.
    try:
        stored = fsr.load(ROOT)
        fresh_state = stored.version == 0
        data = stored.payload
    except Exception as exc:  # pragma: no cover - defensive fallback
        print(f"[deeptiktok] SQLite load failed, falling back to JSON: {exc}", file=sys.stderr)
        return _load_deep_tiktok_rotation_from_json()
    data.setdefault("schemaVersion", 1)
    data.setdefault("cycle", 1)
    data.setdefault("remainingNovels", [])
    data.setdefault("usedChapters", {abbr: [] for abbr in ["EN", "HA", "SF", "HP"]})
    data.setdefault("history", [])
    data.setdefault("pending", None)
    for abbr in ["EN", "HA", "SF", "HP"]:
        values = data["usedChapters"].setdefault(abbr, [])
        data["usedChapters"][abbr] = sorted({int(value) for value in values if str(value).lstrip("-").isdigit()})
    ledger = load_chapter_ledger()
    previously_built_novels: set[str] = set()
    for entry in ledger.get("chapters", {}).values():
        if not isinstance(entry, dict) or not entry.get("deepTikTokBuilt"):
            continue
        abbr = story_key(str(entry.get("abbr") or ""))
        try:
            chapter_number = int(entry.get("chapter"))
        except (TypeError, ValueError):
            continue
        if abbr in data["usedChapters"] and chapter_number not in data["usedChapters"][abbr]:
            data["usedChapters"][abbr].append(chapter_number)
            data["usedChapters"][abbr].sort()
        if abbr:
            previously_built_novels.add(abbr)
    if fresh_state and previously_built_novels and len(previously_built_novels) < 4:
        data["remainingNovels"] = [abbr for abbr in ["EN", "HA", "SF", "HP"] if abbr not in previously_built_novels]
    return data


def _load_deep_tiktok_rotation_from_json() -> dict[str, Any]:
    data = read_json_safe(DEEP_TIKTOK_ROTATION_FILE)
    if not isinstance(data, dict):
        data = {}
    data.setdefault("schemaVersion", 1)
    data.setdefault("cycle", 1)
    data.setdefault("remainingNovels", [])
    data.setdefault("usedChapters", {abbr: [] for abbr in ["EN", "HA", "SF", "HP"]})
    data.setdefault("history", [])
    data.setdefault("pending", None)
    for abbr in ["EN", "HA", "SF", "HP"]:
        values = data["usedChapters"].setdefault(abbr, [])
        data["usedChapters"][abbr] = sorted({int(value) for value in values if str(value).lstrip("-").isdigit()})
    ledger = load_chapter_ledger()
    previously_built_novels: set[str] = set()
    for entry in ledger.get("chapters", {}).values():
        if not isinstance(entry, dict) or not entry.get("deepTikTokBuilt"):
            continue
        abbr = story_key(str(entry.get("abbr") or ""))
        try:
            chapter_number = int(entry.get("chapter"))
        except (TypeError, ValueError):
            continue
        if abbr in data["usedChapters"] and chapter_number not in data["usedChapters"][abbr]:
            data["usedChapters"][abbr].append(chapter_number)
            data["usedChapters"][abbr].sort()
        if abbr:
            previously_built_novels.add(abbr)
    if not DEEP_TIKTOK_ROTATION_FILE.exists() and previously_built_novels and len(previously_built_novels) < 4:
        data["remainingNovels"] = [abbr for abbr in ["EN", "HA", "SF", "HP"] if abbr not in previously_built_novels]
    return data


def save_deep_tiktok_rotation(data: dict[str, Any]) -> None:
    data["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    data["history"] = list(data.get("history") or [])[-500:]
    # SC-4 cutover: persist to SQLite (state_snapshots.deepTikTokRotation).
    fsr.save(ROOT, data)


def deep_tiktok_public_chapter_cap(abbr: str) -> int:
    schedule = ensure_schedule_file()
    novels = schedule.get("novels") if isinstance(schedule, dict) and isinstance(schedule.get("novels"), list) else []
    for item in novels:
        if story_key(str(item.get("abbr") or "")) == abbr:
            try:
                return max(0, int(item.get("currentRoyalRoadChapter") or 0))
            except (TypeError, ValueError):
                break
    return 0


def deep_tiktok_eligible_chapters(abbr: str, used: set[int]) -> list[int]:
    index = docs_chapter_index(abbr)
    cap = deep_tiktok_public_chapter_cap(abbr)
    return sorted(
        {
            int(item.get("number"))
            for item in index.get("chapters", [])
            if str(item.get("number", "")).lstrip("-").isdigit()
            and int(item.get("number")) <= cap
            and int(item.get("number")) not in used
        }
    )


# Per-novel highlight prompt bank for the 60-75s "novel highlight" TikTok (2026-07-20
# redesign). No chapter is chosen -- we highlight the novel itself, rotating through
# these prompts so each build is different. Each prompt drives NEW realistic diffusers
# images (azink_real track) and feeds the Hermes agent post writer for the pack copy.
DEEP_TIKTOK_NOVEL_PROMPTS = {
    "EN": [
        "The Nexus awakens inside a dead server farm; a lone runner discovers the system is rewriting reality one echo at a time.",
        "A glitching city where memories are currency; the protagonist trades a forgotten name for one more hour of power.",
        "The interface offers a forbidden upgrade; taking it means erasing everyone who ever knew your real name.",
        "A silent antagonist encoded as a smiling avatar hunts the runner through mirrored data-temples.",
        "The Nexus speaks in the voice of someone the runner lost; trusting it is the only way out.",
    ],
    "HA": [
        "A dying cultivator inherits a broken ascension sigil and one season to master it before the sect exiles him.",
        "The heavens open a single door; every rival wants the same meridian, and only one can pass.",
        "A forbidden technique lets her hear the qi of the dying; the cost is hearing her own heart stop.",
        "The sect's golden library burns; a disciple must carry a single scroll of truth through the ash.",
        "A courtyard trial where the weak are forgotten by the Formation itself unless they carve their name in lightning.",
    ],
    "SF": [
        "Beneath the undercity, a soul-forge sings; the smith who listens too long begins to forget his own face.",
        "A choir of trapped souls powers the city's shields; freeing one means dooming the rest.",
        "An apprentice forges a blade that remembers every life it has cut, and it refuses to be quiet.",
        "The iron throne of the old empire wakes; the smith must decide whether to melt it or wear it.",
        "A flooded foundry where the dead communicate through hammer-strikes on the water's skin.",
    ],
    "HP": [
        "A mortal finds a path that multiplies each step a hundredfold; the first stride already echoes across the mountain.",
        "The sect opens its immortal gate to one outsider; the trial is to forget everything they love.",
        "A jade scroll reveals a forbidden realm; reading it halves the reader's remaining lifespan.",
        "A quiet disciple out-thinks a dynasty of swordsmen using only stillness and one falling leaf.",
        "The mountain itself tests the worthy; those who climb without fear are never seen again.",
    ],
}


def select_deep_tiktok_novel() -> dict[str, Any]:
    """Novel-only selection for the 60-75s TikTok (redesign): always available.

    Unlike select_random_deep_tiktok_chapter, this never requires an eligible
    public chapter. It rotates novels (remainingNovels) and, within a novel,
    rotates through DEEP_TIKTOK_NOVEL_PROMPTS indices (usedPrompts) so each
    build highlights a different theme and produces different files.
    """
    with DEEP_TIKTOK_ROTATION_LOCK:
        state = load_deep_tiktok_rotation()
        pending = state.get("pending")
        if isinstance(pending, dict) and str(pending.get("selectedAt", "")).strip():
            try:
                age_h = (time.time() - time.mktime(time.strptime(pending["selectedAt"], "%Y-%m-%d %H:%M:%S"))) / 3600
            except Exception:
                age_h = 0.0
            if age_h >= 1.0:
                state["pending"] = None
                save_deep_tiktok_rotation(state)
                pending = None
        if isinstance(pending, dict):
            raise RuntimeError("A 60-75 second TikTok selection is already being built. Wait for it to finish before starting another.")
        remaining = [story_key(str(v)) for v in state.get("remainingNovels", [])]
        remaining = [a for a in remaining if a in {"EN", "HA", "SF", "HP"}]
        if not remaining:
            remaining = ["EN", "HA", "SF", "HP"]
            state["cycle"] = max(1, int(state.get("cycle") or 1)) + 1
        used_prompts = {story_key(str(k)): list(v) for k, v in (state.get("usedPrompts") or {}).items()}
        # Prefer a novel with an unused prompt; else any remaining novel.
        chosen = None
        for abbr in remaining:
            prompts = DEEP_TIKTOK_NOVEL_PROMPTS.get(abbr, [])
            used = set(used_prompts.get(abbr, []))
            if len(prompts) > len(used):
                chosen = abbr
                break
        if not chosen:
            chosen = random.choice(remaining)
            used_prompts.setdefault(chosen, [])
        prompts = DEEP_TIKTOK_NOVEL_PROMPTS.get(chosen, [])
        used = set(used_prompts.get(chosen, []))
        available = [i for i in range(len(prompts)) if i not in used]
        prompt_index = random.choice(available) if available else random.randrange(len(prompts))
        used.add(prompt_index)
        used_prompts[chosen] = sorted(used)
        if len(used_prompts[chosen]) >= len(prompts):
            # This novel's prompts exhausted this cycle -> drop from remaining.
            remaining = [a for a in remaining if a != chosen]
        selection = {
            "abbr": chosen,
            "novel": NOVEL_NAMES.get(chosen, chosen),
            "chapter": "",
            "promptIndex": prompt_index,
            "prompt": prompts[prompt_index],
            "cycle": int(state.get("cycle") or 1),
            "selectedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
            "mode": "novel_highlight",
        }
        state["remainingNovels"] = remaining
        state["usedPrompts"] = used_prompts
        state["pending"] = selection
        save_deep_tiktok_rotation(state)
        return selection


def select_random_deep_tiktok_chapter() -> dict[str, Any]:

    with DEEP_TIKTOK_ROTATION_LOCK:
        state = load_deep_tiktok_rotation()
        # Self-heal: a "pending" selection that was never completed (app crash,
        # hard-kill, or abandoned build) wedges the guard below forever. A 60-75s
        # build never runs >1h, so treat anything older as orphaned and clear it.
        pending = state.get("pending")
        if isinstance(pending, dict) and str(pending.get("selectedAt", "")).strip():
            try:
                age_h = (time.time() - time.mktime(time.strptime(pending["selectedAt"], "%Y-%m-%d %H:%M:%S"))) / 3600
            except Exception:
                age_h = 0.0
            if age_h >= 1.0:
                state["pending"] = None
                save_deep_tiktok_rotation(state)
                pending = None
        if isinstance(pending, dict):
            raise RuntimeError("A 60-75 second TikTok selection is already being built. Wait for it to finish before starting another.")
        remaining = [story_key(str(value)) for value in state.get("remainingNovels", [])]
        remaining = [abbr for abbr in remaining if abbr in {"EN", "HA", "SF", "HP"}]
        if not remaining:
            remaining = ["EN", "HA", "SF", "HP"]
            state["cycle"] = max(1, int(state.get("cycle") or 1)) + (1 if state.get("history") else 0)
        attempted: set[str] = set()
        while remaining:
            available_novels = [abbr for abbr in remaining if abbr not in attempted]
            if not available_novels:
                break
            abbr = random.choice(available_novels)
            attempted.add(abbr)
            used = set(int(value) for value in state["usedChapters"].get(abbr, []))
            chapters = deep_tiktok_eligible_chapters(abbr, used)
            if not chapters:
                remaining = [value for value in remaining if value != abbr]
                continue
            chapter = random.choice(chapters)
            selection = {
                "abbr": abbr,
                "novel": NOVEL_NAMES.get(abbr, abbr),
                "chapter": chapter,
                "cycle": int(state.get("cycle") or 1),
                "selectedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
                "eligibleChapterCount": len(chapters),
                "publicChapterCap": deep_tiktok_public_chapter_cap(abbr),
            }
            state["remainingNovels"] = remaining
            state["pending"] = selection
            save_deep_tiktok_rotation(state)
            return selection
        state["remainingNovels"] = remaining
        save_deep_tiktok_rotation(state)
        raise RuntimeError("Every currently public chapter has already been used for a 60-75 second TikTok.")


def complete_random_deep_tiktok_selection(selection: dict[str, Any], success: bool, error: str = "") -> dict[str, Any]:
    with DEEP_TIKTOK_ROTATION_LOCK:
        state = load_deep_tiktok_rotation()
        abbr = story_key(str(selection.get("abbr") or ""))
        chapter = int(selection.get("chapter") or 0)
        event = {
            **selection,
            "status": "built" if success else "failed",
            "finishedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        }
        if error:
            event["error"] = error
        if success:
            # Novel-only builds (redesign) carry chapter="" and instead rotate
            # prompts via usedPrompts; only record a used chapter when one exists.
            if str(selection.get("chapter") or "").strip():
                used = state["usedChapters"].setdefault(abbr, [])
                if chapter not in used:
                    used.append(chapter)
                    used.sort()
                state["remainingNovels"] = [value for value in state.get("remainingNovels", []) if story_key(str(value)) != abbr]
        state.setdefault("history", []).append(event)
        state["pending"] = None
        save_deep_tiktok_rotation(state)
        return state


def make_random_deep_tiktok_pack(force_new_images: bool = True, style: str = "main-posts") -> dict[str, Any]:
    selection = select_deep_tiktok_novel()
    try:
        payload = make_deep_tiktok_novel_pack(
            str(selection["abbr"]),
            int(selection["promptIndex"]),
            force_new_images=force_new_images,
            style=style,
        )
        success = bool(payload.get("video")) and bool(payload.get("quality_gate", {}).get("ok")) and 60 <= float(payload.get("duration") or 0) <= 75
        state = complete_random_deep_tiktok_selection(
            selection,
            success,
            "" if success else "; ".join(payload.get("quality_gate", {}).get("errors", [])) or "Video did not pass the 60-75 second quality gate.",
        )
        payload["rotation"] = {
            **selection,
            "usedChapterRecorded": success,
            "remainingNovels": state.get("remainingNovels", []),
            "usedPrompts": state.get("usedPrompts", {}).get(selection["abbr"], []),
        }
        metadata_path = Path(str(payload.get("folder") or "")) / "metadata.json"
        if metadata_path.exists():
            metadata = read_metadata(metadata_path.parent)
            metadata["rotation"] = payload["rotation"]
            metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
        return payload
    except Exception as exc:
        complete_random_deep_tiktok_selection(selection, False, str(exc))
        raise


def make_deep_tiktok_pack(abbr: str, chapter: str, force_new_images: bool = True, style: str = "main-posts") -> dict[str, Any]:
    pack_track = style if style in LORA_STYLE_TRACKS else "main-posts"
    abbr = story_key(abbr)
    chapter = str(chapter or "").strip()
    if not abbr or not chapter:
        raise RuntimeError("Choose a novel and chapter for the deep TikTok.")
    chapter_data = docs_chapter_text(abbr, int(chapter))
    title = str(chapter_data.get("title") or chapter_data.get("heading") or f"Chapter {chapter}")
    chapter_text = str(chapter_data.get("text") or chapter_data.get("raw_text") or "")
    if not chapter_text.strip():
        raise RuntimeError("The selected GitHub chapter is empty.")
    novel = NOVEL_NAMES.get(abbr, abbr)
    source_hash = content_hash(chapter_text)
    folder = TIKTOK_OUTPUT_DIR / f"{abbr.lower()}-{slugify(chapter)}-deep"
    existing = reusable_pack_result(folder, expected_hash=source_hash, required_files=["caption.txt", "video-overlays.txt"])
    video = folder / "tiktok-video.mp4"
    if not force_new_images and existing and video.exists() and 60 <= media_duration_seconds(video) <= 75:
        return existing
    reset_generated_folder(folder)
    moments = deep_tiktok_chapter_moments(chapter_text, abbr, 8)
    keywords = ", ".join(chapter_keywords(title, chapter_text, 10))
    images: list[str] = []
    sources: list[str] = []
    prompts: list[str] = []
    used_hashes: set[str] = set()
    openai_images_enabled = True
    for index, moment in enumerate(moments, start=1):
        target = folder / f"deep-scene-{index}.png"
        prompt = (
            f"Vertical 9:16 cinematic fantasy scene for {novel}, {title}. "
            f"This is chronological scene {index} of {len(moments)}. Clearly depict this exact chapter moment: {moment}. "
            f"Recurring visual motifs: {keywords}. Strong character action and emotion, detailed setting, dramatic readable composition, "
            "no text, no typography, no logo, avoid a generic landscape unless the scene requires it."
        )
        prompts.append(prompt)
        # Bake the single pack_track into the prompt so deep scenes stay on-style (E).
        baked = enhance_local_sd_prompt(prompt, orientation="vertical", lora_track=pack_track)
        source = "openai"
        if openai_images_enabled:
            try:
                create_openai_image(baked, target)
                fingerprint = image_file_fingerprint(target)
                if fingerprint in used_hashes:
                    raise RuntimeError("Generated image duplicated an earlier scene.")
                used_hashes.add(fingerprint)
            except Exception as exc:
                if openai_rate_limited(exc):
                    openai_images_enabled = False
                source = create_unique_prompt_fallback_image(
                    prompt, target, index, abbr, used_hashes=used_hashes, allow_banked=False, fresh=True
                )
        else:
            source = create_unique_prompt_fallback_image(
                prompt, target, index, abbr, used_hashes=used_hashes, allow_banked=False, fresh=True
            )
        images.append(str(target))
        sources.append(source)
        archive_generated_promo_image(target, abbr, title, f"deep-tiktok-{index}")
    images.append(prepare_tiktok_outro_image(folder, abbr, novel, chapter, style=pack_track))
    sources.append("rotating-novel-card")
    overlays = [reel_overlay_text(moment, limit=58) for moment in moments]
    overlays.append(reel_overlay_text(f"READ {novel} ON ROYAL ROAD", limit=62))
    hook = overlays[0].replace("\n", " ") if overlays else f"A deeper look at {novel}"
    caption = social_caption_link_in_bio(deep_tiktok_caption(abbr, chapter, title, hook), "tiktok")
    # Voice the long/deep TikTok with the natural caption sentence (NOT the
    # overlay sticker). Fail-soft: if TTS is unavailable the video still
    # builds with music only.
    narration_target = generate_deep_tiktok_narration(folder, abbr, tiktok_narration_text({"caption": caption}, overlays)) if caption else None
    tiktok_title = deep_tiktok_title(abbr, chapter, title)
    sound_source = choose_rotating_weekly_promo_audio()
    if not sound_source:
        sounds = [Path(item["path"]) for item in list_tiktok_assets().get("sounds", []) if Path(item["path"]).exists()]
        sound_source = random.choice(sounds) if sounds else None
    if not sound_source or not sound_source.exists():
        raise RuntimeError("No promo audio is available for the deep TikTok video.")
    sound_target = folder / sound_source.name
    shutil.copy2(sound_source, sound_target)
    payload = {
        "kind": "deep_tiktok",
        "abbr": abbr,
        "novel": novel,
        "chapter": chapter,
        "pack_track": pack_track,
        "title": title,
        "source_hash": source_hash,
        "images": images,
        "image_sources": sources,
        "image_prompts": prompts,
        "sound": str(sound_target),
        "caption": caption,
        "description": caption,
        "tiktok_title": tiktok_title,
        "video_overlays": overlays,
        "duration_target": 68,
        "platforms": ["tiktok"],
        "folder": str(folder),
        "youtube_shorts_disabled": True,
        "youtube_shorts_reason": "Deep chapter TikToks are reserved for TikTok growth testing.",
    }
    (folder / "caption.txt").write_text(caption + "\n", encoding="utf-8")
    (folder / "description.txt").write_text(caption + "\n", encoding="utf-8")
    (folder / "tiktok-title.txt").write_text(tiktok_title + "\n", encoding="utf-8")
    (folder / "sound.txt").write_text(str(sound_target) + "\n", encoding="utf-8")
    (folder / "metadata.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")
    write_deep_tiktok_video_helper(folder, images, sound_target, overlays, narration=narration_target)
    build = run_generated_video_builder(folder, "make_tiktok_video.py", "tiktok-video.mp4", timeout=900)
    payload["video_build"] = build
    payload["video"] = str(video) if video.exists() else ""
    payload["duration"] = media_duration_seconds(video) if video.exists() else 0.0
    (folder / "metadata.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")
    payload = repair_deep_tiktok_metadata(folder, payload)
    payload["quality_gate"] = folder_quality_gate(str(folder), "tiktok")
    if payload["quality_gate"].get("ok"):
        update_chapter_ledger(
            abbr,
            chapter,
            {
                "deepTikTokBuilt": True,
                "deepTikTokBuiltAt": time.strftime("%Y-%m-%d %H:%M:%S"),
                "deepTikTokFolder": str(folder),
                "deepTikTokDuration": payload["duration"],
            },
        )
    (folder / "metadata.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")
    if not payload["quality_gate"].get("ok"):
        return payload
    return auto_publish_generated_media(folder, payload)


def make_deep_tiktok_novel_pack(abbr: str, prompt_index: int, force_new_images: bool = True, style: str = "main-posts") -> dict[str, Any]:
    """Novel-only 60-75s TikTok builder (2026-07-20 redesign).

    Highlights a novel (no chapter) from DEEP_TIKTOK_NOVEL_PROMPTS[prompt_index].
    Generates NEW realistic diffusers images (azink_real track) for each of the
    8 scenes, and lets the Hermes agent post writer produce the whole pack copy
    (caption, title, overlay text). Falls back to curated copy if the agent is
    off/unavailable so the build never breaks. Rotation of prompt_index makes
    every run highlight a different theme and produce different files.
    """
    pack_track = style if style in LORA_STYLE_TRACKS else "main-posts"
    abbr = story_key(abbr)
    prompts = DEEP_TIKTOK_NOVEL_PROMPTS.get(abbr, [])
    if not prompts:
        raise RuntimeError(f"No highlight prompts configured for {abbr}.")
    prompt_index = int(prompt_index) % len(prompts)
    prompt = prompts[prompt_index]
    novel = NOVEL_NAMES.get(abbr, abbr)
    run_id = time.strftime("%Y%m%d-%H%M%S")
    folder = TIKTOK_OUTPUT_DIR / f"{abbr.lower()}-nh{prompt_index}-{run_id}-deep"
    reset_generated_folder(folder)

    sub_themes = [
        "establishing world shot", "the protagonist in motion", "a tense confrontation",
        "an intimate emotional beat", "a startling revelation", "a dangerous environment",
        "a quiet character moment", "a haunting closing image",
    ]
    images: list[str] = []
    sources: list[str] = []
    image_prompts: list[str] = []
    used_hashes: set[str] = set()
    scene_count = 8
    for index in range(1, scene_count + 1):
        target = folder / f"deep-scene-{index}.png"
        sub = sub_themes[(index - 1) % len(sub_themes)]
        base_prompt = (
            f"Realistic cinematic fantasy promotional image for the web novel {novel}. "
            f"Theme: {prompt}. Scene focus: {sub}. "
            f"Detailed setting, dramatic readable composition, strong lighting, photorealistic, "
            f"no text, no typography, no logo."
        )
        baked = enhance_local_sd_prompt(base_prompt, orientation="vertical", lora_track="azink_real")
        seed = (prompt_index * 1000 + index * 7 + int(time.time()) % 1000) % (2 ** 31)
        try:
            create_local_stable_diffusion_image(baked, target, orientation="vertical", seed=seed)
            fingerprint = image_file_fingerprint(target)
            if fingerprint in used_hashes:
                raise RuntimeError("Generated image duplicated an earlier scene.")
            used_hashes.add(fingerprint)
            source = "diffusers-azink_real"
        except Exception as exc:
            print(f"[deep-tiktok-novel] realistic image failed for {abbr} scene {index}: {exc}", file=sys.stderr)
            source = create_unique_prompt_fallback_image(
                baked, target, index, abbr, used_hashes=used_hashes, allow_banked=False, fresh=True
            )
        images.append(str(target))
        sources.append(source)
        image_prompts.append(baked)
        archive_generated_promo_image(target, abbr, novel, f"deep-tiktok-novel-{index}")
    images.append(prepare_tiktok_outro_image(folder, abbr, novel, "", style=pack_track))
    sources.append("rotating-novel-card")

    hook = deep_tiktok_novel_overlay_fallbacks(novel, 1)[0]
    # Full per-novel discoverability hashtag set (BookTok/FantasyBooks/RoyalRoad/etc.),
    # rotated by prompt so repeated builds surface different tag orderings for reach.
    _profile = social_profile(abbr)
    seed = f"{abbr}-nh{prompt_index}-{run_id}"
    # Curated base set only (no prompt-derived keyword tags -- those produce junk like
    # "#Discovers"). rotated_hashtags rotates the ordering per seed for freshness.
    novel_tags = rotated_hashtags(abbr, seed, "", limit=14) or _profile.get("hashtags", "#AzureInkblade")
    # Guarantee the two anchor tags are always present.
    for _anchor in ("#AzureInkblade", "#TikTokBooks"):
        if _anchor.lower() not in novel_tags.lower():
            novel_tags = f"{novel_tags} {_anchor}".strip()
    rr_link = ""
    agent = None
    if str(os.environ.get("ENABLE_AGENT_POSTS", "0")).strip().lower() not in {"", "0", "false", "no", "off"}:
        try:
            from tools.agent_post_writer import generate_post_copy as _agent_gen
            agent = _agent_gen(abbr, novel, "", prompt, {"prompt": prompt, "mode": "novel_highlight"})
        except Exception as exc:
            print(f"[deep-tiktok-novel] agent post writer failed: {exc}", file=sys.stderr)
    if agent and agent.get("caption"):
        body = str(agent["caption"]).strip()
        cta = str(agent.get("cta") or "").strip()
        # Merge agent hashtags into the full discoverability set (dedupe, keep order).
        ag_seen = {t.lower() for t in re.findall(r"#\w+", novel_tags)}
        for t in re.findall(r"#\w+", " ".join(str(x) for x in (agent.get("hashtags") or []))):
            if t.lower() not in ag_seen:
                novel_tags = f"{novel_tags} {t}".strip()
                ag_seen.add(t.lower())
        tiktok_title = str(agent.get("tiktok_title") or agent.get("title") or f"{novel}: {prompt[:48]}").strip()
        ag_overlays = agent.get("overlays") or agent.get("video_overlays") or agent.get("moments") or []
        if isinstance(ag_overlays, str):
            ag_overlays = [line.strip() for line in ag_overlays.splitlines() if line.strip()]
    else:
        body = f"A deeper look at {novel}. {prompt[:120]}"
        cta = f"Continue {novel}. Link in bio."
        tiktok_title = f"{novel}: {prompt[:48]} | 60 Second Novel Highlight"
        ag_overlays = []

    # Rich multi-line description: hook/teaser, CTA + link, then the full tag block.
    caption = "\n\n".join(
        part for part in [
            body,
            f"{cta}\n👉 {rr_link}" if cta else f"👉 {rr_link}",
            novel_tags,
        ] if part and part.strip()
    ).strip()
    caption = social_caption_link_in_bio(caption, "tiktok")
    ag_tags = novel_tags

    fallback_overlays = deep_tiktok_novel_overlay_fallbacks(novel, scene_count)
    if ag_overlays and len(ag_overlays) >= 2:
        overlays = [
            sanitize_deep_tiktok_overlay(
                str(line),
                novel,
                fallback_overlays[index % len(fallback_overlays)],
            )
            for index, line in enumerate(ag_overlays[:scene_count])
        ]
    else:
        overlays = [sanitize_deep_tiktok_overlay(line, novel, line) for line in fallback_overlays]
    while len(overlays) < scene_count:
        fallback = fallback_overlays[len(overlays) % len(fallback_overlays)]
        overlays.append(sanitize_deep_tiktok_overlay(fallback, novel, fallback))
    overlays.append(reel_overlay_text(f"READ {novel} ON ROYAL ROAD", limit=62))
    hook_line = overlays[0].replace("\n", " ") if overlays else f"A deeper look at {novel}"

    sound_source = choose_rotating_weekly_promo_audio()
    if not sound_source:
        sounds = [Path(item["path"]) for item in list_tiktok_assets().get("sounds", []) if Path(item["path"]).exists()]
        sound_source = random.choice(sounds) if sounds else None
    if not sound_source or not sound_source.exists():
        raise RuntimeError("No promo audio is available for the deep TikTok video.")
    sound_target = folder / sound_source.name
    shutil.copy2(sound_source, sound_target)

    # Voiceover narration over ducked music (local-first TTS; fail-soft to music-only).
    narration_target = generate_deep_tiktok_narration(folder, abbr, caption)

    payload = {
        "kind": "deep_tiktok",
        "abbr": abbr,
        "novel": novel,
        "chapter": "",
        "mode": "novel_highlight",
        "prompt_index": prompt_index,
        "prompt": prompt,
        "pack_track": pack_track,
        "title": novel,
        "images": images,
        "image_sources": sources,
        "image_prompts": image_prompts,
        "sound": str(sound_target),
        "narration": str(narration_target) if narration_target else "",
        "caption": caption,
        "description": caption,
        "hashtags": ag_tags,
        "tiktok_title": tiktok_title,
        "video_overlays": overlays,
        "duration_target": 68,
        "platforms": ["tiktok"],
        "folder": str(folder),
        "youtube_shorts_disabled": True,
        "youtube_shorts_reason": "Deep chapter TikToks are reserved for TikTok growth testing.",
    }
    (folder / "caption.txt").write_text(caption + "\n", encoding="utf-8")
    (folder / "description.txt").write_text(caption + "\n", encoding="utf-8")
    (folder / "tiktok-title.txt").write_text(tiktok_title + "\n", encoding="utf-8")
    (folder / "sound.txt").write_text(str(sound_target) + "\n", encoding="utf-8")
    (folder / "metadata.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")
    write_deep_tiktok_video_helper(folder, images, sound_target, overlays, narration=narration_target)
    build = run_generated_video_builder(folder, "make_tiktok_video.py", "tiktok-video.mp4", timeout=900)
    payload["video_build"] = build
    video = folder / "tiktok-video.mp4"
    payload["video"] = str(video) if video.exists() else ""
    payload["duration"] = media_duration_seconds(video) if video.exists() else 0.0
    (folder / "metadata.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")
    payload["quality_gate"] = folder_quality_gate(str(folder), "tiktok")
    (folder / "metadata.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")
    if not payload["quality_gate"].get("ok"):
        return payload
    return auto_publish_generated_media(folder, payload)


def fallback_social_copy(*args, **kwargs):
    return promo_copy.fallback_social_copy(*args, **kwargs)
def docs_file_content(path: str) -> bytes:
    encoded = urllib.parse.quote(path, safe="/")
    if os.environ.get("GITHUB_TOKEN", "").strip():
        try:
            data = github_api_request("GET", f"/repos/{DOCS_REPO_OWNER}/{DOCS_REPO_NAME}/contents/{encoded}?ref={urllib.parse.quote(os.environ.get('GITHUB_DOCS_BRANCH', os.environ.get('GITHUB_BRANCH', 'main')).strip() or 'main')}")
            if data.get("content"):
                return base64.b64decode(data["content"])
            if data.get("sha"):
                blob = github_api_request("GET", f"/repos/{DOCS_REPO_OWNER}/{DOCS_REPO_NAME}/git/blobs/{data['sha']}")
                if blob.get("content"):
                    return base64.b64decode(blob["content"])
            download_url = data.get("download_url")
            if download_url:
                request = urllib.request.Request(download_url, headers={"User-Agent": "AutomationTool/1.0"})
                with urllib.request.urlopen(request, timeout=180) as response:
                    return response.read()
        except Exception:
            pass
    raw_url = f"https://raw.githubusercontent.com/{DOCS_REPO_OWNER}/{DOCS_REPO_NAME}/main/{encoded}"
    try:
        request = urllib.request.Request(raw_url, headers={"User-Agent": "AutomationTool/1.0"})
        with urllib.request.urlopen(request, timeout=180) as response:
            return response.read()
    except Exception:
        pass
    data = github_api_request("GET", f"/repos/{DOCS_REPO_OWNER}/{DOCS_REPO_NAME}/contents/{encoded}")
    if data.get("content"):
        return base64.b64decode(data["content"])
    download_url = data.get("download_url")
    if download_url:
        request = urllib.request.Request(download_url, headers={"User-Agent": "AutomationTool/1.0"})
        with urllib.request.urlopen(request, timeout=180) as response:
            return response.read()
    raise RuntimeError(f"Docs file did not include downloadable content: {path}")


def docx_paragraphs(raw: bytes) -> list[str]:
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        document_xml = archive.read("word/document.xml")
    root = ET.fromstring(document_xml)
    ns = {"w": "http://schemas.openxmlformats.org/wordprocessingml/2006/main"}
    word_ns = f"{{{ns['w']}}}"
    paragraphs: list[str] = []
    for paragraph in root.findall(".//w:p", ns):
        parts: list[str] = []
        for node in paragraph.iter():
            if node.tag == f"{word_ns}t":
                parts.append(node.text or "")
            elif node.tag in {f"{word_ns}br", f"{word_ns}cr"}:
                parts.append("\n")
            elif node.tag == f"{word_ns}tab":
                parts.append("\t")
        text = "".join(parts)
        for logical_paragraph in re.split(r"\n+", text):
            cleaned = logical_paragraph.strip()
            if cleaned:
                paragraphs.append(cleaned)
    return paragraphs


CHAPTER_MARKER_RE = re.compile(
    r"\bChapter\s+(?P<label>\d+[A-Za-z]?(?:\s+Part\s+\d+)?)\b(?P<tail>[^\n]{0,120})",
    re.IGNORECASE,
)
PROLOGUE_RE = re.compile(r"^\s*Prologue\s*$", re.IGNORECASE)


def chapter_number_from_label(label: str) -> int:
    match = re.search(r"\d+", label)
    if not match:
        raise RuntimeError(f"Chapter label has no number: {label}")
    return int(match.group(0))


def clean_chapter_title(label: str, tail: str) -> str:
    tail = re.split(r"\s{2,}", tail.strip(), maxsplit=1)[0].strip()
    tail = re.sub(r"^\s*[:.\-–]\s*", "", tail).strip()
    tail = re.sub(r"^(?:\s*[:.\-\u2013\u2014]\s*)+", "", tail).strip()
    patch_match = re.match(r"^(Patch\s+\d+(?:\.\d+)+)", tail, re.IGNORECASE)
    if patch_match:
        tail = patch_match.group(1)
    else:
        for boundary in re.finditer(r"(?<=[a-z0-9'\u2019])(?=[A-Z][a-z]{1,})", tail):
            title_candidate = tail[: boundary.start()].strip()
            prose_candidate = tail[boundary.start() :].strip()
            if not title_candidate or len(title_candidate.split()) > 16:
                continue
            if len(prose_candidate.split()) < 4:
                continue
            if not re.search(
                r"[,.!?;:]|\b(?:was|were|had|has|is|are|felt|stood|moved|walked|looked|clung|stretched|rose|sat|turned|stepped|opened|closed|woke|awoke|breathed|exhaled|ran|fell|came|carried|filled)\b",
                prose_candidate,
                re.IGNORECASE,
            ):
                continue
            tail = title_candidate
            break
    return f"Chapter {label}{(': ' + tail) if tail else ''}"


def chapter_heading_info(text: str) -> tuple[int, str] | None:
    if PROLOGUE_RE.match(text.strip()):
        return 0, "Prologue"
    match = re.match(r"^chapter\s+(?P<label>\d+[A-Za-z]?(?:\s+Part\s+\d+)?)\b(?P<tail>.*)$", text.strip(), re.IGNORECASE)
    if not match:
        return None
    label = match.group("label").strip()
    number = chapter_number_from_label(label)
    title = clean_chapter_title(label, match.group("tail") or "")
    return number, title


def docs_chapter_index(abbr: str) -> dict[str, Any]:
    abbr = abbr.upper().strip()
    if abbr not in DOCS_NOVEL_FILES:
        raise RuntimeError("Unknown Docs novel.")
    paragraphs = docx_paragraphs(docs_file_content(DOCS_NOVEL_FILES[abbr]))
    chapters: list[dict[str, Any]] = []
    for index, paragraph in enumerate(paragraphs):
        info = chapter_heading_info(paragraph)
        if info:
            number, title = info
            chapters.append({"number": number, "title": title, "heading": paragraph, "index": index})
    full_text = "\n\n".join(paragraphs)
    marker_chapters: list[dict[str, Any]] = []
    for match in CHAPTER_MARKER_RE.finditer(full_text):
        label = match.group("label").strip()
        title = clean_chapter_title(label, match.group("tail") or "")
        marker_chapters.append({"number": chapter_number_from_label(label), "title": title, "heading": title, "index": match.start()})
    if marker_chapters:
        unique_markers: list[dict[str, Any]] = []
        seen_numbers: set[int] = set()
        for chapter in marker_chapters:
            number = int(chapter["number"])
            if number in seen_numbers:
                continue
            seen_numbers.add(number)
            unique_markers.append(chapter)
        marker_chapters = unique_markers
    if len(marker_chapters) > len(chapters):
        chapters = marker_chapters
    unique_chapters: list[dict[str, Any]] = []
    seen_numbers: set[int] = set()
    for chapter in chapters:
        number = int(chapter["number"])
        if number in seen_numbers:
            continue
        seen_numbers.add(number)
        unique_chapters.append(chapter)
    chapters = unique_chapters
    return {
        "abbr": abbr,
        "novel": NOVEL_NAMES.get(abbr, abbr),
        "file": DOCS_NOVEL_FILES[abbr],
        "chapters": chapters,
        "nextSelections": {
            "promo": next_chapter_selection_for(abbr, chapters, "promo"),
            "royalRoad": next_chapter_selection_for(abbr, chapters, "royalRoad"),
            "variants": next_chapter_selection_for(abbr, chapters, "variants"),
            "write": next_chapter_selection_for(abbr, chapters, "write"),
        },
    }


def docs_chapter_payload(abbr: str, number: int, title: str, heading: str, raw_text: str) -> dict[str, Any]:
    cleaned_text = format_chapter_for_platform(title, raw_text, number, abbr, include_post_note=False).strip()
    return {
        "abbr": abbr,
        "novel": NOVEL_NAMES.get(abbr, abbr),
        "number": number,
        "title": title,
        "heading": heading,
        "text": cleaned_text,
        "raw_text": raw_text.strip(),
        "word_count": len(re.findall(r"\w+", cleaned_text)),
        "source_file": DOCS_NOVEL_FILES[abbr],
        "formatted": True,
    }


def docs_chapter_text(abbr: str, chapter_number: int) -> dict[str, Any]:
    abbr = abbr.upper().strip()
    paragraphs = docx_paragraphs(docs_file_content(DOCS_NOVEL_FILES[abbr]))
    full_text = "\n\n".join(paragraphs)
    markers = list(CHAPTER_MARKER_RE.finditer(full_text))
    starts: list[tuple[int, int, str, str]] = []
    for index, paragraph in enumerate(paragraphs):
        info = chapter_heading_info(paragraph)
        if info:
            number, title = info
            starts.append((index, number, title, paragraph))
    if markers and len(markers) >= len(starts):
        for position, marker in enumerate(markers):
            label = marker.group("label").strip()
            number = chapter_number_from_label(label)
            if number != int(chapter_number):
                continue
            end = markers[position + 1].start() if position + 1 < len(markers) else len(full_text)
            chapter_text = full_text[marker.start() : end].strip()
            title = clean_chapter_title(label, marker.group("tail") or "")
            return docs_chapter_payload(abbr, number, title, title, chapter_text)
    for position, (start_index, number, title, heading) in enumerate(starts):
        if number != int(chapter_number):
            continue
        end_index = starts[position + 1][0] if position + 1 < len(starts) else len(paragraphs)
        body = paragraphs[start_index + 1 : end_index]
        chapter_text = heading + "\n\n" + "\n\n".join(body)
        return docs_chapter_payload(abbr, number, title, heading, chapter_text)
    for position, marker in enumerate(markers):
        label = marker.group("label").strip()
        number = chapter_number_from_label(label)
        if number != int(chapter_number):
            continue
        end = markers[position + 1].start() if position + 1 < len(markers) else len(full_text)
        chapter_text = full_text[marker.start() : end].strip()
        title = clean_chapter_title(label, marker.group("tail") or "")
        return docs_chapter_payload(abbr, number, title, title, chapter_text)
    raise RuntimeError(f"Chapter {chapter_number} was not found for {abbr}.")


def docx_paragraph_xml(text: str, *, heading: bool = False) -> str:
    escaped = html.escape(text, quote=False)
    if heading:
        return (
            '<w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr>'
            f'<w:r><w:t xml:space="preserve">{escaped}</w:t></w:r></w:p>'
        )
    return f'<w:p><w:r><w:t xml:space="preserve">{escaped}</w:t></w:r></w:p>'


def append_chapter_to_docx(raw: bytes, title: str, chapter_text: str) -> bytes:
    title = title.strip() or "New Chapter"
    cleaned = normalize_story_text(chapter_text)
    if cleaned.lower().startswith(title.lower()):
        cleaned = cleaned[len(title) :].strip()
    paragraphs = [title] + [part.strip() for part in re.split(r"\n\s*\n+", chapter_text.strip()) if part.strip()]
    if len(paragraphs) > 1 and paragraphs[1].strip().lower() == title.lower():
        paragraphs.pop(1)
    insert_xml = "".join(docx_paragraph_xml(paragraph, heading=(index == 0)) for index, paragraph in enumerate(paragraphs))

    source = io.BytesIO(raw)
    output = io.BytesIO()
    with zipfile.ZipFile(source, "r") as zin, zipfile.ZipFile(output, "w", zipfile.ZIP_DEFLATED) as zout:
        for item in zin.infolist():
            data = zin.read(item.filename)
            if item.filename == "word/document.xml":
                xml = data.decode("utf-8")
                section_match = re.search(r"<w:sectPr[\s\S]*?</w:sectPr>\s*</w:body>", xml)
                if section_match:
                    xml = xml[: section_match.start()] + insert_xml + xml[section_match.start() :]
                else:
                    xml = xml.replace("</w:body>", insert_xml + "</w:body>")
                data = xml.encode("utf-8")
            zout.writestr(item, data)
    return output.getvalue()


def append_chapter_to_github_docs(abbr_or_novel: str, title: str, chapter_text: str) -> dict[str, Any]:
    abbr = story_key(abbr_or_novel)
    if not abbr:
        raise RuntimeError("Choose a known novel before uploading the chapter to GitHub Docs.")
    repo_path = DOCS_NOVEL_FILES.get(abbr)
    if not repo_path:
        raise RuntimeError(f"No GitHub Docs file is configured for {abbr}.")
    raw = docs_file_content(repo_path)
    updated = append_chapter_to_docx(raw, title, chapter_text)
    branch = os.environ.get("GITHUB_DOCS_BRANCH", os.environ.get("GITHUB_BRANCH", "main")).strip() or "main"
    result = upload_bytes_to_github(
        updated,
        repo_path,
        f"Add {NOVEL_NAMES.get(abbr, abbr)} {title}",
        owner=DOCS_REPO_OWNER,
        repo=DOCS_REPO_NAME,
        branch=branch,
    )
    return {
        "abbr": abbr,
        "novel": NOVEL_NAMES.get(abbr, abbr),
        "file": repo_path,
        "branch": branch,
        "upload": result,
    }


def social_copy_with_openai(prompt_template: str, novel: str, abbr: str, day: str, filename: str) -> dict[str, str]:
    prompt = prompt_template.format(novel=novel, abbr=abbr, day=day, filename=filename)
    result = openai_request(
        "chat/completions",
        {
            "model": os.environ.get("OPENAI_TEXT_MODEL", "gpt-4.1-mini"),
            "messages": [
                {"role": "system", "content": "You write compact, reusable social media copy. Return only valid JSON."},
                {"role": "user", "content": prompt},
            ],
            "temperature": 0.75,
            "response_format": {"type": "json_object"},
        },
    )
    return json.loads(result["choices"][0]["message"]["content"])


def make_social_post(*args, **kwargs):
    return promo_builder.make_social_post(*args, **kwargs)
def build_week_social_posts(*args, **kwargs):
    return promo_builder.build_week_social_posts(*args, **kwargs)
def next_planner_chapter(abbr: str, tool: str = "promo") -> int | None:
    try:
        index = docs_chapter_index(abbr)
        selection = index.get("nextSelections", {}).get(tool) or index.get("nextSelections", {}).get("promo") or {}
        chapter = selection.get("nextChapter")
        if chapter is not None and str(chapter).strip() != "":
            return int(chapter)
        chapters = index.get("chapters") or []
        return int(chapters[0]["number"]) if chapters else None
    except Exception:
        return None


def youtube_narration_available() -> tuple[bool, str]:
    if os.environ.get("OPENAI_API_KEY"):
        return True, "OpenAI narration is configured."
    if weekly_promo_audio_files():
        return True, "Reusable weekly audio is available."
    return False, "No OpenAI narration key or reusable weekly audio was found."


def weekly_growth_settings() -> dict[str, Any]:
    saved = _phase2_load_blob("weeklyGrowthSettings", WEEKLY_GROWTH_SETTINGS_FILE)
    if not isinstance(saved, dict):
        saved = {}
    return {
        "schemaVersion": 1,
        "weights": growth_scheduler.normalize_weights(saved.get("weights")),
        "linktreeUrl": linktree_url(),
        "qualityThreshold": 70,
        "updatedAt": str(saved.get("updatedAt") or ""),
    }


def save_weekly_growth_settings(weights: dict[str, Any] | None) -> dict[str, Any]:
    payload = {
        "schemaVersion": 1,
        "weights": growth_scheduler.normalize_weights(weights),
        "updatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    _phase2_save_blob("weeklyGrowthSettings", WEEKLY_GROWTH_SETTINGS_FILE, payload)
    return weekly_growth_settings()


def weekly_growth_chapter_context() -> dict[str, dict[str, Any]]:
    context: dict[str, dict[str, Any]] = {}
    for abbr in NOVEL_NAMES:
        chapter = active_chapter_path_next(abbr, "promo") or next_planner_chapter(abbr, "promo")
        row: dict[str, Any] = {"chapter": chapter, "title": "", "imageRef": ""}
        if chapter is not None:
            try:
                chapter_data = docs_chapter_text(abbr, chapter)
                row["title"] = str(chapter_data.get("title") or chapter_data.get("heading") or "").strip()
            except Exception as exc:
                row["contextWarning"] = f"Chapter title could not be refreshed: {exc}"
        context[abbr] = row
    return context


def build_weekly_growth_plan(week_start: str = "", weights: dict[str, Any] | None = None) -> dict[str, Any]:
    settings = save_weekly_growth_settings(weights) if isinstance(weights, dict) else weekly_growth_settings()
    monday = growth_scheduler.monday_for(week_start)
    before_date = monday.isoformat()
    history = automation_db.weekly_growth_history(ROOT, before_date, 80)
    history.extend(automation_db.recent_platform_post_history(ROOT, 120))
    chapter_path_before = {
        abbr: {tool: active_chapter_path_next(abbr, tool) for tool in ("promo", "social", "variants", "release")}
        for abbr in NOVEL_NAMES
    }
    plan = growth_scheduler.build_weekly_growth_plan(
        week_start=monday,
        weights=settings.get("weights"),
        novels=NOVEL_NAMES,
        chapter_context=weekly_growth_chapter_context(),
        history=history,
    )
    plan["createdAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    plan["settings"] = settings
    chapter_path_after = {
        abbr: {tool: active_chapter_path_next(abbr, tool) for tool in ("promo", "social", "variants", "release")}
        for abbr in NOVEL_NAMES
    }
    plan["pathIsolation"] = {
        "verified": chapter_path_before == chapter_path_after,
        "before": chapter_path_before,
        "after": chapter_path_after,
    }
    if chapter_path_before != chapter_path_after:
        raise RuntimeError("Weekly Planner changed a chapter path. The plan was not saved.")
    saved = automation_db.save_weekly_growth_plan(ROOT, plan)
    return saved


def weekly_growth_planner_dashboard(week_start: str = "") -> dict[str, Any]:
    monday = growth_scheduler.monday_for(week_start).isoformat()
    plan = automation_db.get_weekly_growth_plan(ROOT, monday)
    return {
        "ok": True,
        "settings": weekly_growth_settings(),
        "plan": plan or {},
        "weekStart": monday,
        "message": "Weekly growth plan loaded." if plan else "No weekly growth plan has been built for this week yet.",
    }


def build_this_week_plan(use_openai: bool = False) -> dict[str, Any]:
    result: dict[str, Any] = {
        "createdAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "weekdaySocial": {},
        "weekend": [],
        "shorts": [],
        "youtube": [],
        "releaseActions": [],
        "errors": [],
    }
    result["weekdaySocial"] = build_week_social_posts(use_openai, ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"])
    for day in ["Saturday", "Sunday"]:
        try:
            result["weekend"].append(make_weekend_posts(day))
        except Exception as exc:
            result["errors"].append({"step": "weekend", "day": day, "error": str(exc)})
    for abbr in NOVEL_NAMES:
        chapter = next_planner_chapter(abbr, "promo")
        if chapter is None:
            result["errors"].append({"step": "chapter-select", "abbr": abbr, "error": "No GitHub chapter was found."})
            continue
        try:
            chapter_data = docs_chapter_text(abbr, chapter)
        except Exception as exc:
            result["errors"].append({"step": "chapter-load", "abbr": abbr, "chapter": chapter, "error": str(exc)})
            continue
        try:
            visual_prompt = " - ".join(
                [
                    NOVEL_NAMES.get(abbr, abbr),
                    str(chapter_data.get("title") or ""),
                    "chapter-specific cinematic web novel promo art",
                ]
            )
            result["shorts"].append(
                make_or_generate_tiktok_pack(
                    abbr,
                    str(chapter),
                    visual_prompt,
                    chapter_text=str(chapter_data.get("text") or chapter_data.get("raw_text") or ""),
                    chapter_title=str(chapter_data.get("title") or chapter_data.get("heading") or ""),
                )
            )
        except Exception as exc:
            result["errors"].append({"step": "shorts", "abbr": abbr, "chapter": chapter, "error": str(exc)})
        result["youtube"].append({"abbr": abbr, "chapter": chapter, "skipped": True, "reason": "Full YouTube videos are handled by Create Daily YouTube Videos."})
        try:
            plan = release_plan_for_chapter(abbr, chapter)
            action = {"abbr": abbr, "chapter": chapter, "plan": plan, "created": None}
            decision = str(plan.get("decision") or "")
            if decision in {"patreon_ready", "patreon_only", "royal_road_ready", "update_existing"}:
                action["created"] = make_royal_road_chapter_pack(abbr, chapter)
            result["releaseActions"].append(action)
        except Exception as exc:
            result["errors"].append({"step": "release", "abbr": abbr, "chapter": chapter, "error": str(exc)})
    result["summary"] = {
        "weekdaySocial": len(result.get("weekdaySocial", {}).get("posts") or []),
        "weekendPosts": sum(len(item.get("posts") or []) for item in result["weekend"]),
        "shorts": len([item for item in result["shorts"] if not item.get("error")]),
        "youtubeCreated": len([item for item in result["youtube"] if not item.get("skipped")]),
        "youtubeSkipped": len([item for item in result["youtube"] if item.get("skipped")]),
        "releaseActions": len(result["releaseActions"]),
        "errors": len(result["errors"]) + len(result.get("weekdaySocial", {}).get("errors") or []),
    }
    return result


def rebuild_pack_section(folder: str, part: str, use_openai: bool = False) -> dict[str, Any]:
    target = Path(folder).resolve()
    metadata = read_metadata(target)
    abbr = str(metadata.get("abbr") or "").upper()
    chapter = str(metadata.get("chapter") or metadata.get("chapter_number") or "").strip()
    part = str(part or "").strip().lower()
    if str(target).startswith(str(SOCIAL_OUTPUT_DIR.resolve())) and str(metadata.get("kind") or "") != "royal-road":
        if part not in {"captions", "images"}:
            raise RuntimeError("This social post supports rebuilding captions or images.")
        rebuilt = make_social_post(
            abbr,
            str(metadata.get("day") or datetime.now().strftime("%A")),
            social_prompt_template(),
            use_openai,
            str(metadata.get("post_focus") or ""),
            chapter,
        )
        return {"message": "Daily social post rebuilt.", "post": rebuilt, "folder": rebuilt.get("folder", "")}
    if str(target).startswith(str(TIKTOK_OUTPUT_DIR.resolve())):
        if part not in {"captions", "images", "shorts"}:
            raise RuntimeError("This Shorts/Reels pack supports rebuilding captions, images, or shorts.")
        if str(metadata.get("kind") or "") == "deep_tiktok" or target.name.lower().endswith("-deep"):
            if part == "images":
                rebuilt = regenerate_weak_images(str(target), use_openai)
                return {"message": rebuilt.get("message") or "Deep TikTok images regenerated.", "post": rebuilt.get("post"), "folder": str(target)}
            metadata = repair_deep_tiktok_metadata(target, metadata)
            build = rebuild_deep_tiktok_video_from_metadata(target, metadata)
            refreshed = deep_tiktok_pack_from_folder(str(target))
            return {"message": "Deep TikTok MP4 rebuilt.", "post": refreshed, "folder": str(target), "build": build}
        if part == "images":
            rebuilt = regenerate_weak_images(str(target), use_openai)
            return {"message": rebuilt.get("message") or "Shorts/Reels images regenerated.", "post": rebuilt.get("post"), "folder": str(target), "qualityGate": rebuilt.get("qualityGate")}
        if part == "shorts":
            build = rebuild_normal_tiktok_video_from_metadata(target, metadata)
            refreshed = pack_preview(str(target))
            return {"message": "Shorts/Reels MP4 rebuilt in this pack.", "post": refreshed, "folder": str(target), "build": build}
        prompt = str(metadata.get("visual_prompt") or metadata.get("prompt") or "chapter-specific cinematic web novel promo art")
        rebuilt = make_or_generate_tiktok_pack(abbr, chapter, prompt, force_new_images=part in {"images", "shorts"})
        return {"message": "Shorts/Reels pack rebuilt.", "post": rebuilt, "folder": rebuilt.get("folder", "")}
    if str(target).startswith(str(YOUTUBE_OUTPUT_DIR.resolve())):
        if part not in {"captions", "youtube"}:
            raise RuntimeError("This YouTube pack supports rebuilding captions or YouTube files.")
        text_file = target / "chapter-text.txt"
        if not text_file.exists():
            raise RuntimeError("Saved chapter text was not found in this YouTube folder.")
        rebuilt = build_youtube_from_text(str(metadata.get("title") or ""), text_file.read_text(encoding="utf-8"), abbr, chapter)
        return {"message": "Full YouTube pack rebuilt.", "post": rebuilt, "folder": rebuilt.get("folder", "")}
    if str(target).startswith(str(OUTPUT_DIR.resolve())):
        if part not in {"captions", "images"}:
            raise RuntimeError("This promo pack supports rebuilding captions or images.")
        title = str(metadata.get("title") or metadata.get("chapter_title") or "Chapter Promo")
        text = str(metadata.get("chapter") or metadata.get("chapter_text") or "")
        if not text.strip() and abbr and chapter:
            text = str(docs_chapter_text(abbr, int(chapter)).get("text") or "")
        rebuilt = make_campaign(
            title,
            text,
            use_openai,
            abbr=abbr,
            novel=str(metadata.get("novel") or ""),
            chapter_number=chapter,
            force_new_images=part == "images",
        )
        return {"message": "Promo pack rebuilt.", "post": rebuilt, "folder": rebuilt.get("folder", "")}
    raise RuntimeError("This pack folder type is not supported.")


def rotating_weekend_hook(abbr: str, day: str) -> str:
    profile = social_profile(abbr)
    variants = [
        f"{profile['emoji']} Weekend reading starts here: discover {profile['name']} and step into the next arc.",
        f"{profile['emoji']} Looking for a new web novel to follow? {profile['name']} is waiting.",
        f"{profile['emoji']} Catch up this weekend with {profile['name']} from Azure Inkblade.",
        f"{profile['emoji']} New worlds, rising stakes, and serial fantasy momentum: start {profile['name']} today.",
        f"{profile['emoji']} Add {profile['name']} to the weekend reading queue.",
    ]
    # Phase 1 retirement: promo rotation lives in SQLite (state_snapshots kv).
    state: dict[str, Any] = load_state_snapshot_from_database("promoRotation") or {}
    if not isinstance(state, dict):
        state = {}
    key = f"WEEKEND_COPY_{abbr}_{day}".upper()
    index = int(state.get(key, -1)) + 1
    state[key] = index % len(variants)
    try:
        mirror_state_snapshot_to_database("promoRotation", state)
    except Exception as exc:
        print(f"Database mirror failed for promo rotation: {exc}", file=sys.stderr)
    return variants[state[key]]


def weekend_social_copy(abbr: str, day: str) -> dict[str, str]:
    profile = social_profile(abbr)
    hook = rotating_weekend_hook(abbr, day)
    focus = rotating_post_focus(abbr, f"weekend_{day}")
    cta = focused_social_cta(abbr, focus, f"weekend_{day}", "instagram")
    style = rotating_caption_style(abbr, f"weekend_{day}_{focus}")
    instagram_engagement = platform_engagement_prompt_line(abbr, style, "instagram", focus, f"weekend_{day}")
    facebook_cta = focused_social_cta(abbr, focus, f"weekend_{day}", "facebook")
    facebook_engagement = platform_engagement_prompt_line(abbr, style, "facebook", focus, f"weekend_{day}")
    instagram = "\n".join(
        [
            hook,
            "",
            instagram_engagement,
            "Find the novels, videos, early access, and author resources from one hub.",
            cta,
            "",
            profile["hashtags"],
        ]
    )
    x_link = focused_social_cta(abbr, focus, f"weekend_{day}", "x")
    x_text = "\n".join(
        [
            hook,
            x_link,
            profile["x_hashtags"],
        ]
    )
    if len(x_text) > 275:
        x_text = "\n".join([hook, "Read now: link in bio.", profile["x_hashtags"]])
    if len(x_text) > 275:
        x_text = x_text[:272].rsplit(" ", 1)[0].rstrip() + "..."
    facebook = "\n\n".join(
        [
            hook,
            facebook_engagement,
            "If you are catching up, this is a good weekend to start the series and follow future updates.",
            facebook_cta,
            profile["hashtags"],
        ]
    )
    return {
        "instagram": social_caption_link_in_bio(instagram, "instagram"),
        "x": social_caption_link_in_bio(x_text, "x"),
        "facebook": social_caption_link_in_bio(facebook, "facebook"),
        "alt_text": f"Weekend promotional image for {profile['name']}.",
        "post_focus": focus,
        "caption_style": style,
    }


def attach_post_audio(payload: dict[str, Any], abbr: str, text: str, folder: "Path") -> dict[str, Any]:
    """Attach a generated voiceover to a post payload (2026-07-20 plan §2).

    Gated by GENERATE_POST_AUDIO. When off, the payload keeps its existing
    (or empty) audio field and the post is unaffected. On any failure the post
    remains usable: status becomes 'failed'/'skipped' rather than raising.
    Synthesis is non-blocking by default (POST_AUDIO_BLOCKING=False) so the
    text post is never delayed by TTS; the audio status is merged into metadata.
    """
    import post_artifacts as pa
    if not GENERATE_POST_AUDIO:
        return payload
    status = {
        "status": "skipped", "path": "", "url": "", "engine": "",
        "voice_id": "", "duration_seconds": 0.0, "cache_hit": False,
        "content_hash": "", "error": "GENERATE_POST_AUDIO disabled",
    }
    if not POST_AUDIO_BLOCKING:
        # Deferred/non-blocking: record 'pending' so the UI can show
        # "Generating audio..." and a later pass fills it in.
        payload = pa.attach_audio_status(payload, {
            "status": "pending", "path": "", "url": "", "engine": "",
            "voice_id": "", "duration_seconds": 0.0, "cache_hit": False,
            "content_hash": "", "error": None,
        })
        # Best-effort synchronous generation now (non-blocking flag only means we
        # must not fail the post); wrap so exceptions never escape.
        try:
            result = generate_post_audio(text, folder, abbr=abbr)
            return pa.attach_audio_status(payload, result)
        except Exception as exc:
            return pa.attach_audio_status(payload, {
                "status": "failed", "path": "", "url": "", "engine": "",
                "voice_id": "", "duration_seconds": 0.0, "cache_hit": False,
                "content_hash": "", "error": str(exc),
            })
    try:
        result = generate_post_audio(text, folder, abbr=abbr)
        return pa.attach_audio_status(payload, result)
    except Exception as exc:
        return pa.attach_audio_status(payload, {**status, "error": str(exc)})


def make_weekend_social_post(abbr: str, day: str) -> dict[str, Any]:
    day = day if day in {"Saturday", "Sunday"} else "Saturday"
    matches = [
        item
        for item in list_daily_promo_images()
        if item["abbr"] == abbr and item["day"].lower() == day.lower()
    ]
    if not matches:
        raise RuntimeError(f"No weekend promo image found for {abbr} {day}.")
    item = matches[0]
    folder = SOCIAL_OUTPUT_DIR / f"weekend-{abbr.lower()}-{day.lower()}"
    reset_generated_folder(folder)
    # Weekend posts use the realistic diffusers workflow (azink_real track) by default,
    # matching vertical social orientation. Fail-soft: any generation failure falls back
    # to the stock promo image so the weekend build never breaks.
    _stock_source = Path(item["path"])
    image_source = _stock_source
    image_target = folder / _stock_source.name
    try:
        _gen_target = folder / f"{abbr}_{day}.png"
        _real_prompt = (
            f"realistic fantasy promotional image for the web novel {NOVEL_NAMES.get(abbr, abbr)}, "
            f"weekend reading theme, cinematic realism, dramatic character moment"
        )
        create_local_stable_diffusion_image(
            _real_prompt,
            _gen_target,
            orientation="vertical",
            seed=0,
        )
        if _gen_target.exists():
            image_source = _gen_target
            image_target = _gen_target
    except Exception as _img_exc:
        print(f"[weekend] realistic image gen failed for {abbr} {day}, using stock: {_img_exc}", file=sys.stderr)
    # Only copy when falling back to the stock image. When generation succeeded,
    # image_source == image_target == _gen_target (the file the generator subprocess
    # just wrote); copying it onto itself on Windows raises WinError 32 because the
    # subprocess may still hold the file handle. So skip the copy in that case.
    if image_target != image_source:
        shutil.copy2(image_source, image_target)
    copy = weekend_social_copy(abbr, day)
    # Optional Hermes agent post copy (dynamic, research-aware). Default OFF.
    # Flip ENABLE_AGENT_POSTS=1 to replace template prose with agent-generated copy.
    # Any failure -> keep the template copy (fail-soft).
    if str(os.environ.get("ENABLE_AGENT_POSTS", "0")).strip().lower() not in {"", "0", "false", "no", "off"}:
        try:
            from tools.agent_post_writer import generate_post_copy as _agent_gen
            _wk_hook = rotating_weekend_hook(abbr, day)
            _agent = _agent_gen(abbr, f"Weekend {day}", day, _wk_hook, {"abbr": abbr, "novel": NOVEL_NAMES.get(abbr, "")})
            if _agent and _agent.get("caption"):
                _ag_cap = str(_agent["caption"]).strip()
                _ag_cta = str(_agent.get("cta") or "").strip()
                _ag_tags = " ".join(str(t) for t in (_agent.get("hashtags") or []) if str(t).strip())
                if "#AzureInkblade" not in _ag_tags:
                    _ag_tags = f"#AzureInkblade {_ag_tags}".strip()
                _profile = social_profile(abbr)
                _novel_tag = next((t for t in re.findall(r"#\w+", _profile.get("hashtags", "")) if t.lower() != "#azureinkblade"), "")
                if _novel_tag and _novel_tag not in _ag_tags:
                    _ag_tags = f"{_ag_tags} {_novel_tag}".strip()
                _fb_body = _ag_cap + (f"\n\n{_ag_cta}" if _ag_cta else "")
                _ig_body = _ag_cap + (f"\n\n{_ag_cta}" if _ag_cta else "")
                # X: keep a real body (never collapse to tags-only). Trim cta first,
                # then caption, to fit 280 — mirrors weekend_social_copy's X handling.
                _x_full = f"{_ig_body}\n\n{_ag_tags}"
                if len(_x_full) > 280:
                    _x_full = f"{_ag_cap}\n\n{_ag_tags}"
                if len(_x_full) > 280:
                    _x_full = _ag_cap[:277].rsplit(" ", 1)[0].rstrip() + "...\n\n" + _ag_tags
                copy = {
                    "instagram": f"{_ig_body}\n\n{_ag_tags}",
                    "x": _x_full,
                    "facebook": f"{_fb_body}\n\n{_ag_tags}",
                    "alt_text": copy.get("alt_text", f"Weekend promotional image for {_profile.get('name', abbr)}."),
                    "post_focus": copy.get("post_focus", ""),
                    "caption_style": copy.get("caption_style", "") + "+agent",
                    "_agent_source": _agent.get("_source"),
                }
        except Exception as _agent_exc:
            copy.setdefault("warnings", []).append(f"agent_post_writer skipped: {_agent_exc}")
    payload = {
        **item,
        **copy,
        "source": "weekend-rotation",
        "kind": "weekend",
        "folder": str(folder),
        "image": str(image_target),
    }
    # §2 TTS: attach a voiceover to the post record (non-blocking; post stays
    # usable if audio generation fails). Uses the Instagram caption as the
    # narration source with hashtags removed.
    _narration = re.sub(r"#\w+", "", copy.get("instagram", "")).strip()
    payload = attach_post_audio(payload, abbr, _narration, folder)
    (folder / "instagram.txt").write_text(copy["instagram"].strip() + "\n", encoding="utf-8")
    (folder / "x.txt").write_text(copy["x"].strip() + "\n", encoding="utf-8")
    (folder / "facebook.txt").write_text(copy["facebook"].strip() + "\n", encoding="utf-8")
    (folder / "alt-text.txt").write_text(copy["alt_text"].strip() + "\n", encoding="utf-8")
    (folder / "metadata.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")
    return auto_publish_generated_media(folder, payload)


def make_weekend_posts(day: str = "") -> dict[str, Any]:
    if day not in {"Saturday", "Sunday"}:
        today = datetime.now().strftime("%A")
        day = today if today in {"Saturday", "Sunday"} else "Saturday"
    available = [item for item in list_daily_promo_images() if item["day"] == day]
    abbrs = [item["abbr"] for item in available]
    posts = []
    errors = []
    for abbr in sorted(set(abbrs)):
        try:
            posts.append(make_weekend_social_post(abbr, day))
        except Exception as exc:
            errors.append({"abbr": abbr, "error": str(exc)})
    if not posts:
        raise RuntimeError(f"No weekend posts could be created for {day}.")
    return {"day": day, "posts": posts, "errors": errors}


def load_release_status() -> dict[str, Any]:
    try:
        data = automation_db.load_release_status(ROOT)
        if isinstance(data, dict) and isinstance(data.get("chapters"), dict):
            return data
    except Exception as exc:
        print(f"Database read failed for release status: {exc}", file=sys.stderr)
    return {"chapters": {}}


def save_release_status(data: dict[str, Any]) -> None:
    data.setdefault("chapters", {})
    mirror_release_status_to_database(data)


def load_chapter_path_state() -> dict[str, Any]:
    # Phase 1 retirement: SQLite (state_snapshots kv) is the sole source of truth.
    data = load_state_snapshot_from_database("chapterPath")
    if not isinstance(data, dict):
        data = {"schemaVersion": 1, "active": False, "nextChapter": 17, "chaptersPerNovelPerWeek": 5, "novels": {}}
    data.setdefault("schemaVersion", 1)
    data.setdefault("active", False)
    data.setdefault("nextChapter", 17)
    data.setdefault("chaptersPerNovelPerWeek", 5)
    data.setdefault("releaseDays", CHAPTER_RELEASE_DAYS)
    novels = data.setdefault("novels", {})
    for abbr in NOVEL_NAMES:
        item = novels.setdefault(abbr, {})
        item.setdefault("abbr", abbr)
        item.setdefault("novel", NOVEL_NAMES[abbr])
        item.setdefault("nextChapter", int(data.get("nextChapter") or 17))
        item.setdefault("lastCompletedChapter", max(0, int(item.get("nextChapter") or 17) - 1))
    return data


def save_chapter_path_state(data: dict[str, Any]) -> None:
    data["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    mirror_state_snapshot_to_database("chapterPath", data)


def schedule_next_chapter_for(abbr: str) -> int | None:
    abbr = story_key(abbr)
    if not abbr:
        return None
    try:
        schedule = ensure_schedule_file()
        for novel in schedule.get("novels", []) if isinstance(schedule.get("novels"), list) else []:
            if story_key(str(novel.get("abbr") or "")) != abbr:
                continue
            next_chapter = int(novel.get("nextChapter") or 0)
            return next_chapter if next_chapter > 0 else None
    except Exception:
        return None
    return None


def active_chapter_path_next(abbr: str, tool: str = "") -> int | None:
    state = load_chapter_path_state()
    if not state.get("active"):
        return None
    abbr = story_key(abbr)
    item = state.get("novels", {}).get(abbr) if isinstance(state.get("novels"), dict) else {}
    if not isinstance(item, dict):
        schedule_next = schedule_next_chapter_for(abbr)
        return schedule_next if schedule_next else None
    try:
        next_chapter = int(item.get("nextChapter") or state.get("nextChapter") or 0)
    except (TypeError, ValueError):
        next_chapter = 0
    if next_chapter > 0:
        return next_chapter
    schedule_next = schedule_next_chapter_for(abbr)
    return schedule_next if schedule_next else None


def release_upload_next_chapter(abbr: str) -> int | None:
    abbr = story_key(abbr)
    if not abbr:
        return None
    status = load_release_status()
    release_upload = status.get("nextSelections", {}).get("releaseUpload", {})
    item = release_upload.get(abbr) if isinstance(release_upload, dict) else {}
    if isinstance(item, dict):
        try:
            value = int(item.get("nextChapter") or 0)
            if value > 0:
                return value
        except (TypeError, ValueError):
            pass
    try:
        schedule = ensure_schedule_file()
        for novel in schedule.get("novels", []) if isinstance(schedule.get("novels"), list) else []:
            if story_key(str(novel.get("abbr") or "")) != abbr:
                continue
            value = int(novel.get("nextUploadChapter") or novel.get("nextReleaseUploadChapter") or 0)
            return value if value > 0 else None
    except Exception:
        return None
    return None


def release_upload_next_inner_date(abbr: str) -> date | None:
    abbr = story_key(abbr)
    if not abbr:
        return None
    status = load_release_status()
    release_upload = status.get("nextSelections", {}).get("releaseUpload", {})
    item = release_upload.get(abbr) if isinstance(release_upload, dict) else {}
    if isinstance(item, dict):
        for key in ("nextInnerDiscipleDate", "nextPatreonInnerDate", "nextUploadDate"):
            value = str(item.get(key) or "").strip()
            if not value:
                continue
            try:
                return datetime.fromisoformat(value).date()
            except ValueError:
                continue
    return None


def release_upload_path_status() -> dict[str, Any]:
    status = load_release_status()
    release_upload = status.get("nextSelections", {}).get("releaseUpload", {})
    novels = []
    for abbr, novel in NOVEL_NAMES.items():
        item = release_upload.get(abbr) if isinstance(release_upload, dict) else {}
        if not isinstance(item, dict):
            item = {}
        novels.append({
            "abbr": abbr,
            "novel": novel,
            "nextChapter": release_upload_next_chapter(abbr) or "",
            "nextInnerDiscipleDate": str(item.get("nextInnerDiscipleDate") or ""),
            "nextPathInitiateDate": str(item.get("nextPathInitiateDate") or ""),
            "nextRoyalRoadDate": str(item.get("nextRoyalRoadDate") or ""),
            "postingNextChapter": active_chapter_path_next(abbr, "release-upload-status") or "",
            "updatedAt": item.get("updatedAt") or "",
            "note": item.get("note") or "",
        })
    return {
        "generatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "novels": novels,
        "note": "Upload path is independent from the daily promo/posting path.",
    }


def release_workflow_path_labels() -> dict[str, Any]:
    status = load_release_status()
    selections = status.get("nextSelections", {}) if isinstance(status.get("nextSelections"), dict) else {}
    def selection_label(tool: str) -> str:
        bucket = selections.get(tool, {}) if isinstance(selections.get(tool), dict) else {}
        parts = []
        for abbr in NOVEL_NAMES:
            item = bucket.get(abbr) if isinstance(bucket.get(abbr), dict) else {}
            value = item.get("nextChapter") if isinstance(item, dict) else ""
            if value:
                parts.append(f"{abbr}: Ch. {value}")
        return " | ".join(parts) if parts else "not set"
    posting = active_chapter_path_status()
    posting_label = " | ".join(
        f"{item.get('abbr')}: Ch. {item.get('nextChapter') or '?'}"
        for item in posting.get("novels", [])
    )
    upload = release_upload_path_status()
    upload_label = " | ".join(
        f"{item.get('abbr')}: Ch. {item.get('nextChapter') or '?'}"
        for item in upload.get("novels", [])
    )
    return {
        "dailyPromo": posting_label or "not set",
        "releaseUpload": upload_label or "not set",
        "fullYouTube": selection_label("youtube") or selection_label("fullYouTube"),
        "variants": selection_label("variants"),
    }


def set_release_upload_path(
    next_by_abbr: dict[str, int],
    reset_queue: bool = False,
    note: str = "",
    next_inner_dates: dict[str, str] | None = None,
) -> dict[str, Any]:
    status = load_release_status()
    selections = status.setdefault("nextSelections", {})
    release_upload = selections.setdefault("releaseUpload", {})
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    for raw_abbr, raw_chapter in next_by_abbr.items():
        abbr = story_key(str(raw_abbr))
        if not abbr:
            continue
        try:
            chapter = int(raw_chapter)
        except (TypeError, ValueError):
            continue
        if chapter <= 0:
            continue
        existing = release_upload.get(abbr) if isinstance(release_upload.get(abbr), dict) else {}
        entry = {
            **existing,
            "abbr": abbr,
            "novel": NOVEL_NAMES.get(abbr, abbr),
            "nextChapter": chapter,
            "updatedAt": now,
            "note": note or "Manual upload path reset.",
        }
        inner_text = str((next_inner_dates or {}).get(abbr) or "").strip()
        if inner_text:
            try:
                inner_date = datetime.fromisoformat(inner_text).date()
                entry["nextInnerDiscipleDate"] = inner_date.isoformat()
                entry["nextPathInitiateDate"] = (inner_date + timedelta(days=7)).isoformat()
                entry["nextRoyalRoadDate"] = (inner_date + timedelta(days=14)).isoformat()
            except ValueError:
                pass
        release_upload[abbr] = entry
    save_release_status(status)
    backup = ""
    if reset_queue:
        # Phase 1 retirement: the queue lives in SQLite. Back up its current
        # content to a timestamped JSON file for audit, then reset in DB.
        timestamp = time.strftime("%Y%m%d-%H%M%S")
        backup_path = CHAPTER_RELEASE_QUEUE_FILE.with_name(
            f"{CHAPTER_RELEASE_QUEUE_FILE.stem}.backup-upload-path-{timestamp}{CHAPTER_RELEASE_QUEUE_FILE.suffix}"
        )
        try:
            backup_path.write_text(
                json.dumps(load_chapter_release_queue(), indent=2, default=str),
                encoding="utf-8",
            )
            backup = str(backup_path)
        except Exception:
            backup = ""
        save_chapter_release_queue({
            "schemaVersion": 1,
            "rotationIndex": 0,
            "assignments": [],
            "errors": [],
            "scheduleMode": "release-upload-path-reset",
            "resetAt": now,
        })
    return {
        "ok": True,
        "resetQueue": bool(reset_queue),
        "backup": backup,
        "releaseUploadPath": release_upload_path_status(),
    }


def advance_release_upload_path(abbr: str, completed_chapter: int, note: str = "") -> None:
    abbr = story_key(abbr)
    if not abbr or completed_chapter <= 0:
        return
    current = release_upload_next_chapter(abbr) or 0
    if current and completed_chapter < current:
        return
    set_release_upload_path(
        {abbr: completed_chapter + 1},
        reset_queue=False,
        note=note or "Advanced after chapter entered the release upload pipeline.",
    )


def save_release_upload_calendar(rows: list[dict[str, Any]]) -> dict[str, Any]:
    next_by_abbr: dict[str, int] = {}
    next_inner_dates: dict[str, str] = {}
    errors: list[str] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        abbr = story_key(str(row.get("abbr") or ""))
        if not abbr:
            continue
        try:
            chapter = int(row.get("nextChapter") or row.get("chapter") or 0)
        except (TypeError, ValueError):
            errors.append(f"{abbr}: next chapter must be a number.")
            continue
        inner = str(row.get("innerDiscipleDate") or row.get("nextInnerDiscipleDate") or "").strip()
        path = str(row.get("pathInitiateDate") or row.get("nextPathInitiateDate") or "").strip()
        royal = str(row.get("royalRoadDate") or row.get("nextRoyalRoadDate") or "").strip()
        if chapter <= 0:
            errors.append(f"{abbr}: next chapter must be greater than zero.")
            continue
        if not inner:
            errors.append(f"{abbr}: Inner Disciple date is required.")
            continue
        try:
            inner_date = datetime.fromisoformat(inner).date()
        except ValueError:
            errors.append(f"{abbr}: Inner Disciple date is invalid.")
            continue
        expected_path = (inner_date + timedelta(days=7)).isoformat()
        expected_royal = (inner_date + timedelta(days=14)).isoformat()
        if path and path != expected_path:
            errors.append(f"{abbr}: Path Initiate should be {expected_path}.")
        if royal and royal != expected_royal:
            errors.append(f"{abbr}: Royal Road should be {expected_royal}.")
        next_by_abbr[abbr] = chapter
        next_inner_dates[abbr] = inner_date.isoformat()
    if errors:
        return {"ok": False, "errors": errors, "message": "Release calendar was not saved. Fix the listed date issues."}
    result = set_release_upload_path(
        next_by_abbr,
        reset_queue=True,
        note="Saved from Release Calendar UI.",
        next_inner_dates=next_inner_dates,
    )
    queue = chapter_release_upload_queue_status(refresh=True)
    return {
        "ok": True,
        "saved": len(next_by_abbr),
        "releaseUploadPath": result.get("releaseUploadPath"),
        "queue": queue,
        "message": f"Saved {len(next_by_abbr)} release calendar row(s) and rebuilt the upload queue.",
    }


def release_planner_chapter_indexes(abbrs: list[str]) -> tuple[dict[str, list[dict[str, Any]]], list[dict[str, Any]]]:
    indexes: dict[str, list[dict[str, Any]]] = {}
    errors: list[dict[str, Any]] = []
    for abbr in abbrs:
        try:
            data = docs_chapter_index(abbr)
            chapters = []
            for chapter in data.get("chapters", []) if isinstance(data.get("chapters"), list) else []:
                try:
                    number = int(chapter.get("number") or chapter.get("chapter") or 0)
                except (TypeError, ValueError):
                    continue
                if number <= 0:
                    continue
                chapters.append({
                    "number": number,
                    "title": str(chapter.get("title") or chapter.get("heading") or f"Chapter {number}"),
                    "path": str(chapter.get("path") or chapter.get("sourcePath") or chapter.get("file") or ""),
                })
            indexes[abbr] = chapters
        except Exception as exc:
            indexes[abbr] = []
            errors.append({"abbr": abbr, "error": str(exc)})
    return indexes, errors


def build_release_planner(payload: dict[str, Any]) -> dict[str, Any]:
    request = release_planner.ReleasePlanRequest.from_payload(payload)
    abbrs = list(NOVEL_NAMES) if request.novel == "ALL" else [request.novel]
    indexes, index_errors = release_planner_chapter_indexes(abbrs)
    current_upload = {abbr: release_upload_next_chapter(abbr) for abbr in abbrs}
    rows, warnings = release_planner.build_release_plan_rows(
        request,
        novel_names=NOVEL_NAMES,
        chapter_indexes=indexes,
        current_upload_chapters=current_upload,
    )
    row_dicts = [row.to_dict() for row in rows]
    saved = 0
    queue_result: dict[str, Any] | None = None
    if not request.dry_run:
        saved = automation_db.upsert_release_plan_rows(ROOT, row_dicts)
        first_by_abbr: dict[str, dict[str, Any]] = {}
        for row in row_dicts:
            abbr = story_key(str(row.get("abbr") or ""))
            if abbr and abbr not in first_by_abbr:
                first_by_abbr[abbr] = row
        if first_by_abbr:
            queue_result = save_release_upload_calendar([
                {
                    "abbr": abbr,
                    "nextChapter": row.get("chapterNumber"),
                    "innerDiscipleDate": row.get("innerDiscipleDate"),
                    "pathInitiateDate": row.get("pathInitiateDate"),
                    "royalRoadDate": row.get("royalRoadDate"),
                }
                for abbr, row in first_by_abbr.items()
            ])
    return {
        "ok": not index_errors,
        "dryRun": request.dry_run,
        "saved": saved,
        "rows": row_dicts,
        "warnings": warnings + index_errors,
        "currentUploadChapters": current_upload,
        "queue": queue_result,
        "message": f"Release Planner built {len(row_dicts)} row(s){' in dry run' if request.dry_run else ''}.",
    }


