def update_release_planner_stage_for_chapter(
    abbr: str,
    chapter: int,
    stage: str,
    status: str,
    *,
    last_error: str = "",
) -> dict[str, Any] | None:
    abbr = story_key(str(abbr or ""))
    chapter_number = int(chapter or 0)
    if not abbr or chapter_number <= 0:
        return None
    rows = automation_db.load_release_plan_rows(ROOT, abbr, limit=1000)
    row = next((item for item in rows if int(item.get("chapter") or item.get("chapterNumber") or 0) == chapter_number), None)
    if not row:
        return None
    return automation_db.update_release_plan_row_status(
        ROOT,
        str(row.get("releasePlanId") or ""),
        stage=stage,
        status=status,
        last_error=last_error,
    )


def update_release_planner_stages_from_upload_result(result: dict[str, Any]) -> list[dict[str, Any]]:
    assignment = result.get("assignment") if isinstance(result.get("assignment"), dict) else {}
    abbr = story_key(str(assignment.get("abbr") or ""))
    chapter = int(assignment.get("chapter") or 0)
    if not abbr or chapter <= 0:
        return []
    held_stages = {str(item.get("stage") or "") for item in result.get("held", []) if isinstance(item, dict)}
    prepared_stages = {
        str(stage or "").strip().lower().replace("-", "_")
        for stage in result.get("preparedStages", [])
    }
    updates: list[dict[str, Any]] = []
    stage_statuses = [
        ("inner_disciple", "inner_disciple" in prepared_stages and bool(result.get("playwright_launched")) and "patreon" not in held_stages),
        ("path_initiate", "path_initiate" in prepared_stages and bool(result.get("playwright_launched")) and "patreon" not in held_stages),
        ("royal_road", "royal_road" in prepared_stages and bool(result.get("royalRoadTab"))),
    ]
    for stage, prepared in stage_statuses:
        if stage not in prepared_stages:
            continue
        status = "draft_prepared" if prepared else "blocked"
        error = "" if prepared else "Browser helper did not confirm this draft was opened."
        try:
            row = update_release_planner_stage_for_chapter(abbr, chapter, stage, status, last_error=error)
            updates.append({"stage": stage, "status": status, "row": row, "error": error})
        except Exception as exc:
            updates.append({"stage": stage, "status": "blocked", "error": str(exc)})
    return updates


def automate_due_release_uploads(
    *,
    dry_run: bool = False,
    limit: int = 20,
    include_prepared: bool = False,
    include_scheduled: bool = True,
) -> dict[str, Any]:
    base_queue = ensure_chapter_release_queue()
    full_assignments = [release_queue_assignment_status(item) for item in base_queue.get("assignments", [])]
    queue = chapter_release_upload_queue_status(refresh=False)
    targets = release_planner.release_stage_due_targets(
        full_assignments,
        today=str(queue.get("today") or iso_today().isoformat()),
        include_prepared=include_prepared,
        include_scheduled=include_scheduled,
    )
    by_key: dict[str, list[dict[str, Any]]] = {}
    for target in targets:
        by_key.setdefault(str(target.get("key") or ""), []).append(target)
    all_keys = [key for key in by_key if key]
    keys = all_keys[: max(1, min(50, int(limit or 20)))]
    planned = [{"key": key, "stages": by_key[key]} for key in keys]
    if dry_run:
        return {
            "ok": True,
            "dryRun": True,
            "planned": planned,
            "results": [],
            "errors": [],
            "queue": queue,
            "remaining": max(0, len(all_keys) - len(keys)),
            "message": (
                f"Automation dry run found {len(all_keys)} scheduled chapter upload(s). "
                f"The next {len(planned)} are ready to open."
            ),
        }

    results: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    for key in keys:
        try:
            result = upload_chapter_review_tabs(
                key,
                stages=[str(item.get("stage") or "") for item in by_key.get(key, [])],
            )
            result["plannerStatusUpdates"] = update_release_planner_stages_from_upload_result(result)
            result["dueStages"] = by_key.get(key, [])
            results.append(result)
        except Exception as exc:
            assignment = next((item for item in full_assignments if str(item.get("key") or "") == key), {})
            abbr = story_key(str(assignment.get("abbr") or ""))
            chapter = int(assignment.get("chapter") or 0)
            for target in by_key.get(key, []):
                try:
                    update_release_planner_stage_for_chapter(abbr, chapter, str(target.get("stage") or ""), "blocked", last_error=str(exc))
                except Exception:
                    pass
            errors.append({"key": key, "stages": by_key.get(key, []), "error": str(exc)})
    final_queue = chapter_release_upload_queue_status(refresh=True)
    return {
        "ok": not errors,
        "dryRun": False,
        "planned": planned,
        "results": results,
        "errors": errors,
        "queue": final_queue,
        "remaining": max(0, len(all_keys) - len(keys)),
        "message": (
            f"One-click release automation opened {len(results)} chapter upload set(s). "
            f"{len(errors)} set(s) need attention. "
            f"{max(0, len(all_keys) - len(keys))} scheduled chapter set(s) remain for the next batch. "
            "Review each tab before publishing or saving."
        ),
    }


