def _release_job_already_complete(job: dict[str, Any]) -> bool:
    ledger = chapter_ledger_entry(str(job.get("abbr") or ""), int(job.get("chapter") or 0))
    stage = str(job.get("stage") or "")
    if stage == "inner_disciple":
        return bool(ledger.get("patreonInnerDisciplePosted") or ledger.get("postedToPatreon"))
    if stage == "path_initiate":
        return bool(ledger.get("patreonPathInitiatePosted"))
    return bool(ledger.get("postedToRoyalRoad")) and not bool(ledger.get("royalRoadReviewNeeded"))


def _patreon_result_row(result_path: Path, stage: str) -> dict[str, Any]:
    payload = read_json_safe(result_path)
    if not isinstance(payload, dict):
        raise RuntimeError("Patreon browser helper did not create a readable result.")
    if payload.get("error"):
        raise RuntimeError(f"Patreon browser helper failed: {payload.get('error')}")
    rows = payload.get("results") if isinstance(payload.get("results"), list) else []
    row = next((item for item in rows if isinstance(item, dict) and str(item.get("stage") or "") == stage), None)
    if not row:
        raise RuntimeError(f"Patreon browser helper did not return the {stage} result.")
    return row


def _verified_patreon_result(result_path: Path, stage: str) -> dict[str, Any]:
    row = _patreon_result_row(result_path, stage)
    verification = row.get("verification") if isinstance(row.get("verification"), dict) else {}
    submit = row.get("submitResult") if isinstance(row.get("submitResult"), dict) else {}
    if not row.get("ok") or not verification.get("ok") or not submit.get("verified"):
        raise RuntimeError("Patreon draft did not pass the pre-submit gate and verified-submit check.")
    return row


def _royal_road_result_row(result_path: Path) -> dict[str, Any]:
    payload = read_json_safe(result_path)
    if not isinstance(payload, list):
        raise RuntimeError("Royal Road browser helper did not create a readable result.")
    row = next(
        (
            item
            for item in reversed(payload)
            if isinstance(item, dict) and str(item.get("action") or "") == "royal_road_result"
        ),
        None,
    )
    if not row:
        raise RuntimeError("Royal Road browser helper did not return a final result.")
    return row


def _verified_royal_road_result(result_path: Path) -> dict[str, Any]:
    row = _royal_road_result_row(result_path)
    verification = row.get("verification") if isinstance(row.get("verification"), dict) else {}
    submit = row.get("submitResult") if isinstance(row.get("submitResult"), dict) else {}
    if not verification.get("ok"):
        raise RuntimeError("Royal Road pre-submit verification gate failed; the chapter was not submitted.")
    if not submit.get("verified"):
        raise RuntimeError("Royal Road submission outcome is uncertain and requires review before retrying.")
    return row


def reconcile_completed_release_job_results() -> dict[str, Any]:
    reconciled: list[str] = []
    errors: list[dict[str, str]] = []
    running_jobs = automation_db.list_release_jobs(ROOT, statuses=["running"], limit=5000)
    for job in running_jobs:
        job_id = str(job.get("jobId") or "")
        stage = str(job.get("stage") or "")
        abbr = story_key(str(job.get("abbr") or ""))
        chapter = int(job.get("chapter") or 0)
        assignment_key = str(job.get("assignmentKey") or job.get("key") or "")
        if not job_id or not assignment_key or not abbr or chapter <= 0:
            continue
        result_path = Path(str(job.get("resultPath") or "")) if job.get("resultPath") else None
        if not result_path or not result_path.exists():
            folder_name = f"royal-road-{abbr.lower()}-{chapter}" if stage == "royal_road" else f"release-{abbr.lower()}-{chapter}"
            candidate = ROOT / "social-posts" / folder_name / f"release-automation-{job_id}-result.json"
            result_path = candidate if candidate.exists() else None
        if not result_path:
            continue
        try:
            if stage == "royal_road":
                row = _verified_royal_road_result(result_path)
                submit = row.get("submitResult") if isinstance(row.get("submitResult"), dict) else {}
                dashboard = submit.get("dashboardVerification") if isinstance(submit.get("dashboardVerification"), dict) else {}
                remote_url = str(dashboard.get("editUrl") or submit.get("pageUrl") or row.get("url") or "")
            else:
                row = _verified_patreon_result(result_path, stage)
                remote_url = str(row.get("pageUrl") or "")
            completed = mark_chapter_release_stage_complete(assignment_key, stage)
            if not completed.get("completed") and not completed.get("alreadyCompleted"):
                raise RuntimeError(str(completed.get("message") or "Release ledger completion gate failed."))
            automation_db.update_release_job(
                ROOT,
                job_id,
                "verified",
                remoteUrl=remote_url,
                payloadUpdates={
                    "resultPath": str(result_path),
                    "completion": completed,
                    "verificationSource": "reconciled-browser-result",
                },
            )
            reconciled.append(job_id)
        except Exception as exc:
            errors.append({"jobId": job_id, "error": str(exc)})
    return {"reconciled": reconciled, "errors": errors}


def run_release_automation_job(job: dict[str, Any]) -> dict[str, Any]:
    job_id = str(job.get("jobId") or "")
    stage = str(job.get("stage") or "")
    assignment_key = str(job.get("assignmentKey") or job.get("key") or "")
    if not job_id or not assignment_key:
        raise RuntimeError("Release automation job identity is incomplete.")
    if _release_job_already_complete(job):
        if str(job.get("status") or "") == "verified":
            return {"ok": True, "alreadyCompleted": True, "job": job}
        completed = mark_chapter_release_stage_complete(assignment_key, stage)
        updated = automation_db.update_release_job(
            ROOT,
            job_id,
            "verified",
            payloadUpdates={"completion": completed, "verificationSource": "existing-ledger"},
        )
        return {"ok": True, "alreadyCompleted": True, "job": updated}
    if stage == "royal_road":
        abbr = story_key(str(job.get("abbr") or ""))
        chapter = int(job.get("chapter") or 0)
        pack = make_royal_road_chapter_pack(abbr, chapter)
        folder = Path(str(pack.get("folder") or "")).resolve()
        result_path = folder / f"release-automation-{job_id}-result.json"
        script_path = folder / f"release-automation-{job_id}.js"
        existing_target = str(job.get("editUrl") or job.get("remoteUrl") or "").strip()
        spec = royal_road_release_spec(
            folder,
            scheduled_release=str(job.get("scheduledFor") or job.get("date") or ""),
            auto_submit=True,
            target_url=existing_target,
        )
        write_manual_posts_playwright_script(
            folder,
            [spec],
            result_file=result_path,
            script_file=script_path,
        )
        update_chapter_ledger(abbr, chapter, {
            "royalRoadUploadPrepared": True,
            "royalRoadUploadPreparedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
            "royalRoadFolder": str(folder),
            "releaseQueueKey": assignment_key,
        })
        metadata = read_metadata(folder)
        metadata["royal_road_automation"] = {
            "jobId": job_id,
            "assignmentKey": assignment_key,
            "playwright_script": str(script_path),
            "playwright_result": str(result_path),
            "scheduled_release": spec.get("scheduled_release", ""),
            "edit_existing": bool(spec.get("edit_existing")),
            "target_url": spec.get("url", ""),
        }
        (folder / "metadata.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")
        result_path.unlink(missing_ok=True)
        process = subprocess.run(
            [str(bundled_node_executable()), str(script_path)],
            cwd=str(folder),
            env={**os.environ, "NODE_PATH": str(ROOT / "node_modules"), "PLAYWRIGHT_BROWSERS_PATH": str(ROOT / "ms-playwright")},
            capture_output=True,
            text=True,
            timeout=300,
            check=False,
        )
        if process.returncode != 0:
            detail = (process.stderr or process.stdout or "Royal Road browser helper exited with an error.").strip()
            if result_path.exists():
                try:
                    preliminary = _royal_road_result_row(result_path)
                    preliminary_submit = preliminary.get("submitResult") if isinstance(preliminary.get("submitResult"), dict) else {}
                    dashboard = preliminary_submit.get("dashboardVerification") if isinstance(preliminary_submit.get("dashboardVerification"), dict) else {}
                    preliminary_url = str(dashboard.get("editUrl") or preliminary_submit.get("pageUrl") or preliminary.get("url") or "").strip()
                    automation_db.update_release_job(
                        ROOT,
                        job_id,
                        str(job.get("status") or "in_progress"),
                        payloadUpdates={
                            "editUrl": preliminary_url if "/chapters/edit" in preliminary_url else existing_target,
                            "resultPath": str(result_path),
                            "lastBrowserUrl": preliminary_url,
                        },
                    )
                    _verified_royal_road_result(result_path)
                except Exception as verification_error:
                    detail = f"{detail}\n{verification_error}"
            raise RuntimeError(detail[-1800:])
        preliminary = _royal_road_result_row(result_path)
        preliminary_submit = preliminary.get("submitResult") if isinstance(preliminary.get("submitResult"), dict) else {}
        preliminary_dashboard = preliminary_submit.get("dashboardVerification") if isinstance(preliminary_submit.get("dashboardVerification"), dict) else {}
        preliminary_url = str(preliminary_dashboard.get("editUrl") or preliminary_submit.get("pageUrl") or preliminary.get("url") or "").strip()
        automation_db.update_release_job(
            ROOT,
            job_id,
            str(job.get("status") or "in_progress"),
            payloadUpdates={
                "editUrl": preliminary_url if "/chapters/edit" in preliminary_url else existing_target,
                "resultPath": str(result_path),
                "lastBrowserUrl": preliminary_url,
            },
        )
        row = _verified_royal_road_result(result_path)
        submit = row.get("submitResult") if isinstance(row.get("submitResult"), dict) else {}
        dashboard = submit.get("dashboardVerification") if isinstance(submit.get("dashboardVerification"), dict) else {}
        remote_url = str(dashboard.get("editUrl") or submit.get("pageUrl") or row.get("url") or "")
        metadata = read_metadata(folder)
        automation = metadata.get("royal_road_automation") if isinstance(metadata.get("royal_road_automation"), dict) else {}
        automation.update({"verified": True, "verifiedAt": time.strftime("%Y-%m-%d %H:%M:%S"), "remoteUrl": remote_url})
        metadata["royal_road_automation"] = automation
        (folder / "metadata.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")
        completed = mark_chapter_release_stage_complete(assignment_key, stage)
        if not completed.get("completed"):
            raise RuntimeError(str(completed.get("message") or "Royal Road completion gate failed."))
        updated = automation_db.update_release_job(
            ROOT,
            job_id,
            "verified",
            remoteUrl=remote_url,
            payloadUpdates={
                "editUrl": remote_url if "/chapters/edit" in remote_url else existing_target,
                "resultPath": str(result_path),
                "completion": completed,
                "verificationSource": "playwright-hard-gate",
            },
        )
        return {"ok": True, "alreadyCompleted": False, "result": row, "job": updated}

    result_name = f"release-automation-{job_id}-result.json"
    edit_urls = {}
    existing_edit_url = str(job.get("editUrl") or job.get("remoteUrl") or "").strip()
    if existing_edit_url:
        edit_urls[stage] = existing_edit_url
    prepared = upload_chapter_review_tabs(
        assignment_key,
        [stage],
        auto_submit=True,
        result_name=result_name,
        edit_urls=edit_urls,
        launch=False,
    )
    script_path = Path(str(prepared.get("playwright_script") or ""))
    result_path = Path(str(prepared.get("playwright_result") or ""))
    if not script_path.exists() or not result_path.parent.exists():
        raise RuntimeError("Patreon browser helper files were not prepared.")
    result_path.unlink(missing_ok=True)
    node = bundled_node_executable()
    process = subprocess.run(
        [str(node), str(script_path)],
        cwd=str(script_path.parent),
        env={**os.environ, "NODE_PATH": str(ROOT / "node_modules"), "PLAYWRIGHT_BROWSERS_PATH": str(ROOT / "ms-playwright")},
        capture_output=True,
        text=True,
        timeout=300,
        check=False,
    )
    if process.returncode != 0:
        detail = (process.stderr or process.stdout or "Browser helper exited with an error.").strip()
        if result_path.exists():
            try:
                preliminary = _patreon_result_row(result_path, stage)
                preliminary_url = str(preliminary.get("pageUrl") or "").strip()
                automation_db.update_release_job(
                    ROOT,
                    job_id,
                    str(job.get("status") or "in_progress"),
                    payloadUpdates={
                        "editUrl": preliminary_url,
                        "resultPath": str(result_path),
                        "lastBrowserUrl": preliminary_url,
                    },
                )
            except Exception:
                pass
        raise RuntimeError(detail[-1200:])
    preliminary = _patreon_result_row(result_path, stage)
    preliminary_url = str(preliminary.get("pageUrl") or "").strip()
    automation_db.update_release_job(
        ROOT,
        job_id,
        str(job.get("status") or "in_progress"),
        payloadUpdates={
            "editUrl": preliminary_url,
            "resultPath": str(result_path),
            "lastBrowserUrl": preliminary_url,
        },
    )
    row = _verified_patreon_result(result_path, stage)
    remote_url = str(row.get("pageUrl") or "")
    completed = mark_chapter_release_stage_complete(assignment_key, stage)
    if not completed.get("completed"):
        raise RuntimeError(str(completed.get("message") or "Release ledger completion gate failed."))
    updated = automation_db.update_release_job(
        ROOT,
        job_id,
        "verified",
        remoteUrl=remote_url,
        payloadUpdates={
            "editUrl": remote_url,
            "resultPath": str(result_path),
            "completion": completed,
            "verificationSource": "playwright-hard-gate",
        },
    )
    return {"ok": True, "alreadyCompleted": False, "result": row, "job": updated}


def release_automation_worker(worker_id: str, max_jobs: int = 0) -> None:
    processed = 0
    attempted = 0
    _save_release_automation_runtime(
        running=True,
        paused=False,
        workerId=worker_id,
        startedAt=time.strftime("%Y-%m-%d %H:%M:%S"),
        lastError="",
        failedJob={},
        attempted=0,
        processed=0,
    )
    try:
        automation_db.recover_stale_release_jobs(ROOT, (datetime.now() - timedelta(minutes=15)).strftime("%Y-%m-%d %H:%M:%S"))
        while not RELEASE_AUTOMATION_STOP.is_set():
            while RELEASE_AUTOMATION_PAUSE.is_set() and not RELEASE_AUTOMATION_STOP.is_set():
                _save_release_automation_runtime(running=True, paused=True, processed=processed)
                time.sleep(1)
            if RELEASE_AUTOMATION_STOP.is_set() or (max_jobs and attempted >= max_jobs):
                break
            job = automation_db.claim_next_release_job(ROOT, worker_id)
            if not job:
                break
            attempted += 1
            _save_release_automation_runtime(running=True, paused=False, processed=processed, current=job, lastError="")
            try:
                run_release_automation_job(job)
                processed += 1
            except Exception as exc:
                attempts = int(job.get("attemptCount") or 0)
                max_attempts = int(job.get("maxAttempts") or 3)
                error_text = str(exc).lower()
                uncertain_outcome = "outcome is uncertain" in error_text or "requires review before retrying" in error_text
                systemic_failure = any(marker in error_text for marker in (
                    "winerror 10013",
                    "chrome helper bridge is not configured",
                    "existing chrome is not reachable",
                    "connection refused",
                    "actively refused",
                ))
                retry = attempts < max_attempts and "not enabled yet" not in error_text and not uncertain_outcome
                next_attempt = (datetime.now() + timedelta(minutes=max(2, attempts * 3))).strftime("%Y-%m-%d %H:%M:%S")
                automation_db.update_release_job(
                    ROOT,
                    str(job.get("jobId") or ""),
                    "retrying" if retry else "blocked",
                    nextAttemptAt=next_attempt if retry else "",
                    lastError=str(exc)[:2000],
                )
                _save_release_automation_runtime(lastError=str(exc), failedJob=job, processed=processed, attempted=attempted)
                if not retry or systemic_failure:
                    break
    finally:
        _save_release_automation_runtime(
            running=False,
            paused=RELEASE_AUTOMATION_PAUSE.is_set(),
            stopped=RELEASE_AUTOMATION_STOP.is_set(),
            processed=processed,
            attempted=attempted,
            finishedAt=time.strftime("%Y-%m-%d %H:%M:%S"),
            current={},
        )


def start_release_automation(max_jobs: int = 0) -> dict[str, Any]:
    global RELEASE_AUTOMATION_THREAD
    with RELEASE_AUTOMATION_LOCK:
        if RELEASE_AUTOMATION_THREAD and RELEASE_AUTOMATION_THREAD.is_alive():
            return {"ok": True, "alreadyRunning": True, "status": release_automation_status()}
        reconciliation = reconcile_completed_release_job_results()
        automation_db.recover_stale_release_jobs(
            ROOT,
            (datetime.now() + timedelta(seconds=1)).strftime("%Y-%m-%d %H:%M:%S"),
        )
        backlog = build_release_automation_backlog(include_prepared=True)
        preflight = release_automation_preflight()
        if not preflight.get("ready"):
            return {
                "ok": False,
                "started": False,
                "preflight": preflight,
                "backlog": backlog,
                "reconciliation": reconciliation,
                "status": release_automation_status(),
                "message": "Release automation did not start because its browser preflight failed.",
            }
        if not int(preflight.get("pendingJobs") or 0):
            return {
                "ok": True,
                "started": False,
                "alreadyComplete": True,
                "preflight": preflight,
                "backlog": backlog,
                "reconciliation": reconciliation,
                "status": release_automation_status(),
                "message": "All release jobs are already complete.",
            }
        RELEASE_AUTOMATION_STOP.clear()
        RELEASE_AUTOMATION_PAUSE.clear()
        worker_id = f"release-{os.getpid()}-{int(time.time())}"
        RELEASE_AUTOMATION_THREAD = threading.Thread(
            target=release_automation_worker,
            args=(worker_id, max(0, int(max_jobs or 0))),
            daemon=True,
            name="release-automation",
        )
        RELEASE_AUTOMATION_THREAD.start()
    return {"ok": True, "started": True, "preflight": preflight, "backlog": backlog, "reconciliation": reconciliation, "status": release_automation_status()}


def control_release_automation(action: str) -> dict[str, Any]:
    action = str(action or "").strip().lower()
    if action == "pause":
        RELEASE_AUTOMATION_PAUSE.set()
    elif action == "resume":
        RELEASE_AUTOMATION_STOP.clear()
        RELEASE_AUTOMATION_PAUSE.clear()
        if not (RELEASE_AUTOMATION_THREAD and RELEASE_AUTOMATION_THREAD.is_alive()):
            return start_release_automation()
    elif action == "stop":
        RELEASE_AUTOMATION_STOP.set()
        RELEASE_AUTOMATION_PAUSE.clear()
    else:
        raise RuntimeError("Choose pause, resume, or stop.")
    return {"ok": True, "action": action, "status": release_automation_status()}


def item_is_experiment_pack(item: dict[str, Any]) -> bool:
    folder = Path(str(item.get("folder") or ""))
    if str(folder).startswith(str(EXPERIMENT_OUTPUT_DIR.resolve())):
        return True
    try:
        metadata = read_metadata(folder)
    except Exception:
        metadata = {}
    return bool(metadata.get("experimentId") or metadata.get("variantId"))


def is_chapter_upload_release_artifact(folder: Path, metadata: dict[str, Any]) -> bool:
    name = folder.name.lower()
    kind = str(metadata.get("kind") or "").strip().lower()
    return (
        name.startswith("release-")
        or kind in {"release-master", "chapter-release", "release-chapter"}
        or bool(metadata.get("releaseQueueKey"))
        or bool(metadata.get("patreon_stage_drafts"))
    )


def approval_item_matches_active_chapter(item: dict[str, Any], active_paths: dict[str, int | None] | None = None) -> bool:
    if item_is_experiment_pack(item):
        return True
    abbr = story_key(str(item.get("abbr") or ""))
    if not abbr:
        return True
    try:
        chapter = int(item.get("chapter") or 0)
    except (TypeError, ValueError):
        return True
    if chapter <= 0:
        return True
    active_next = active_paths.get(abbr) if isinstance(active_paths, dict) else active_chapter_path_next(abbr, "approval")
    return not active_next or chapter == active_next


def chapter_can_advance_active_path(abbr: str, chapter: int | str) -> bool:
    abbr = story_key(abbr)
    if not abbr:
        return False
    try:
        chapter_number = int(chapter)
    except (TypeError, ValueError):
        return False
    active_next = active_chapter_path_next(abbr, "advance")
    return not active_next or chapter_number == active_next


def apply_chapter_path_state(next_chapter: int = 17, start_date: str = "", *, reset_queue: bool = True) -> dict[str, Any]:
    next_chapter = max(1, int(next_chapter or 17))
    start = datetime.fromisoformat(start_date).date() if str(start_date or "").strip() else iso_today()
    start = next_weekday_on_or_after(start)
    last_completed = max(0, next_chapter - 1)
    state = {
        "schemaVersion": 1,
        "active": True,
        "nextChapter": next_chapter,
        "lastCompletedChapter": last_completed,
        "chaptersPerNovelPerWeek": 5,
        "releaseDays": CHAPTER_RELEASE_DAYS,
        "anchorDate": start.isoformat(),
        "note": "Chapter path lock. The app should build the next chapter for every novel from this pointer before advancing.",
        "novels": {
            abbr: {
                "abbr": abbr,
                "novel": NOVEL_NAMES[abbr],
                "nextChapter": next_chapter,
                "lastCompletedChapter": last_completed,
                "chaptersPerWeek": 5,
                "releaseDays": CHAPTER_RELEASE_DAYS,
            }
            for abbr in NOVEL_NAMES
        },
    }
    save_chapter_path_state(state)

    schedule = ensure_schedule_file()
    schedule["releaseQueueStartDate"] = start.isoformat()
    schedule["chapterReleaseDays"] = CHAPTER_RELEASE_DAYS
    for novel in schedule.get("novels", []):
        abbr = story_key(str(novel.get("abbr") or ""))
        if not abbr:
            continue
        novel["currentRoyalRoadChapter"] = last_completed
        novel["nextChapter"] = next_chapter
        novel["nextRoyalRoadDate"] = start.isoformat()
        novel["startDate"] = start.isoformat()
        novel["releaseDays"] = CHAPTER_RELEASE_DAYS
    # SC-3 cutover: persist to SQLite (state_snapshots.postingSchedule).
    sr.save(ROOT, schedule)

    status = load_release_status()
    next_selections = status.setdefault("nextSelections", {})
    for tool in ["promo", "royalRoad", "variants", "write", "patreon", "social"]:
        bucket = next_selections.setdefault(tool, {})
        for abbr in NOVEL_NAMES:
            bucket[abbr] = {
                "abbr": abbr,
                "lastChapter": last_completed,
                "nextChapter": next_chapter,
                "updatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
                "source": "chapter-path-lock",
            }
    save_release_status(status)

    if reset_queue:
        backup = {}
        # Phase 1 retirement: queue lives in SQLite. Back up current DB content
        # to a timestamped JSON file for audit, then reset in DB.
        backup_path = CHAPTER_RELEASE_QUEUE_FILE.with_name(
            f"chapter-release-queue.backup-{time.strftime('%Y%m%d-%H%M%S')}.json"
        )
        try:
            backup_path.write_text(
                json.dumps(load_chapter_release_queue(), indent=2, default=str),
                encoding="utf-8",
            )
            backup["queueBackup"] = str(backup_path)
        except Exception:
            backup = {}
        save_chapter_release_queue({"schemaVersion": 1, "rotationIndex": 0, "assignments": [], "errors": [], "scheduleMode": "chapter-path-reset"})
    else:
        backup = {}
    queue = ensure_chapter_release_queue(90)
    return {
        "ok": True,
        "chapterPath": state,
        "schedule": schedule,
        "queueCount": len(queue.get("assignments", [])),
        **backup,
        "message": f"Chapter path locked to Chapter {next_chapter} for all novels, Monday-Friday.",
    }


def record_chapter_tool_progress(tool: str, abbr: str, chapter: int | str) -> dict[str, Any]:
    abbr = story_key(abbr)
    if not abbr:
        return {}
    try:
        chapter_number = int(chapter)
    except (TypeError, ValueError):
        return {}
    status = load_release_status()
    progress = status.setdefault("nextSelections", {}).setdefault(tool, {})
    existing = progress.get(abbr) if isinstance(progress.get(abbr), dict) else {}
    try:
        existing_next = int(existing.get("nextChapter"))
    except (TypeError, ValueError):
        existing_next = -1
    candidate_next = chapter_number + 1
    if existing_next > candidate_next:
        return existing
    entry = {
        "abbr": abbr,
        "lastChapter": chapter_number,
        "nextChapter": candidate_next,
        "updatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    progress[abbr] = entry
    save_release_status(status)
    if tool in {"promo", "royalRoad", "patreon", "social"}:
        path_state = load_chapter_path_state()
        if path_state.get("active") and abbr in path_state.get("novels", {}):
            item = path_state["novels"][abbr]
            path_next = int(item.get("nextChapter") or path_state.get("nextChapter") or 0)
            if candidate_next > path_next:
                item["lastCompletedChapter"] = chapter_number
                item["nextChapter"] = candidate_next
                item["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
                save_chapter_path_state(path_state)
    return entry


def advance_completed_chapter(abbr: str, chapter: int | str, tool: str = "promo") -> dict[str, Any]:
    return record_chapter_tool_progress(tool, abbr, chapter)


def content_experiment_exists(abbr: str, chapter: int | str) -> bool:
    abbr = story_key(abbr)
    chapter_id = str(chapter).strip()
    if not abbr or not chapter_id:
        return False
    store = load_content_experiments()
    for item in store.get("experiments", []):
        if not isinstance(item, dict):
            continue
        if story_key(str(item.get("abbr") or "")) == abbr and str(item.get("chapter") or "").strip() == chapter_id:
            return True
    return False


def chapter_tool_complete(abbr: str, chapter: int, tool: str) -> bool:
    if tool == "variants":
        return content_experiment_exists(abbr, chapter)
    entry = chapter_ledger_entry(abbr, chapter)
    if not entry:
        return False
    if tool == "royalRoad":
        reviewed = bool(entry.get("postedToRoyalRoad") or entry.get("royalRoadReviewed"))
        if not reviewed:
            return False
        reviewed_hash = str(entry.get("royalRoadReviewedHash") or "").strip()
        if reviewed_hash:
            try:
                data = docs_chapter_text(abbr, chapter)
                current_hash = chapter_revision_hash(str(data.get("text") or data.get("raw_text") or ""))
                return reviewed_hash == current_hash
            except Exception:
                return reviewed
        return reviewed
    if tool == "write":
        return bool(entry.get("written") or entry.get("uploadedToGitHubDocs") or entry.get("githubDocsUploaded"))
    missing = missing_workflow_actions(abbr, chapter)
    return not missing


def next_chapter_selection_for(abbr: str, chapters: list[dict[str, Any]], tool: str) -> dict[str, Any]:
    abbr = story_key(abbr)
    numbers = sorted({int(chapter["number"]) for chapter in chapters if str(chapter.get("number", "")).lstrip("-").isdigit()})
    status = load_release_status()
    progress = status.get("nextSelections", {}).get(tool, {}).get(abbr, {}) if isinstance(status.get("nextSelections"), dict) else {}
    preferred = progress.get("nextChapter")
    try:
        preferred_int = int(preferred)
    except (TypeError, ValueError):
        preferred_int = numbers[0] if numbers else 0
    path_next = active_chapter_path_next(abbr, tool)
    if path_next:
        return {
            "tool": tool,
            "lastChapter": path_next - 1,
            "nextChapter": path_next,
            "chapterPathLocked": True,
            "pathNextChapter": path_next,
            "updatedAt": load_chapter_path_state().get("updatedAt", ""),
        }
    selected = preferred_int if preferred_int in numbers else next((number for number in numbers if number > int(progress.get("lastChapter", -1))), preferred_int)
    if numbers and selected not in numbers:
        selected = next((number for number in numbers if path_next and number >= path_next), numbers[0])
    original_selected = selected
    for number in numbers:
        if number < selected:
            continue
        if not chapter_tool_complete(abbr, number, tool):
            selected = number
            break
    else:
        selected = numbers[-1] if numbers else selected
    if selected != original_selected:
        progress = record_chapter_tool_progress(tool, abbr, selected - 1)
    return {
        "tool": tool,
        "lastChapter": progress.get("lastChapter", ""),
        "nextChapter": selected,
        "chapterPathLocked": bool(path_next),
        "pathNextChapter": path_next or "",
        "updatedAt": progress.get("updatedAt", ""),
    }


def chapter_revision_hash(text: str) -> str:
    normalized = normalize_story_text(text)
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest()


def chapter_revision_info(abbr: str, chapter: int, data: dict[str, Any]) -> dict[str, Any]:
    text = str(data.get("text") or "")
    current_hash = chapter_revision_hash(text)
    status = load_release_status()
    key = f"{abbr.upper()}-{chapter}"
    previous = status.get("chapters", {}).get(key, {})
    previous_hash = str(previous.get("contentHash") or "")
    return {
        "key": key,
        "contentHash": current_hash,
        "previousHash": previous_hash,
        "changed": bool(previous_hash and previous_hash != current_hash),
        "firstSeen": not bool(previous_hash),
        "wordCount": int(data.get("word_count") or len(re.findall(r"\w+", text))),
        "previous": previous,
    }


def remember_chapter_revision(abbr: str, chapter: int, data: dict[str, Any], revision: dict[str, Any]) -> None:
    status = load_release_status()
    key = revision.get("key") or f"{abbr.upper()}-{chapter}"
    entry = dict(status.get("chapters", {}).get(key, {}))
    entry.update(
        {
            "abbr": abbr.upper(),
            "chapter": chapter,
            "title": concise_release_title(data.get("title") or data.get("heading") or "", abbr, chapter),
            "contentHash": revision.get("contentHash", ""),
            "wordCount": revision.get("wordCount", 0),
            "lastChecked": time.strftime("%Y-%m-%d %H:%M:%S"),
        }
    )
    if revision.get("changed"):
        entry["changedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
        entry["previousContentHash"] = revision.get("previousHash", "")
    status.setdefault("chapters", {})[str(key)] = entry
    save_release_status(status)


def update_release_status_from_live(abbr: str, chapter: int, result: dict[str, Any]) -> dict[str, Any]:
    status = load_release_status()
    key = f"{abbr.upper()}-{chapter}"
    entry = dict(status.get("chapters", {}).get(key, {}))
    rr = result.get("royalRoad", {}) if isinstance(result, dict) else {}
    patreon = result.get("patreon", {}) if isinstance(result, dict) else {}
    if "exists" in rr:
        entry["royalRoadExists"] = bool(rr.get("exists"))
    if isinstance(rr.get("contentCompare"), dict):
        entry["royalRoadContentCompare"] = rr.get("contentCompare")
        entry["royalRoadContentStatus"] = str(rr.get("contentCompare", {}).get("status") or "")
        entry["royalRoadChapterUrl"] = str(rr.get("chapterUrl") or entry.get("royalRoadChapterUrl") or "")
    if "exists" in patreon:
        entry["patreonExists"] = bool(patreon.get("exists"))
    entry["lastLiveCheck"] = time.strftime("%Y-%m-%d %H:%M:%S")
    entry["lastLiveCheckResult"] = result
    status.setdefault("chapters", {})[key] = entry
    save_release_status(status)
    ledger_updates: dict[str, Any] = {
        "lastLiveCheck": entry["lastLiveCheck"],
    }
    if bool(patreon.get("exists")):
        ledger_updates["postedToPatreon"] = True
        ledger_updates["patreonDetectedAt"] = entry["lastLiveCheck"]
    if bool(rr.get("exists")):
        ledger_updates["postedToRoyalRoad"] = True
        ledger_updates["royalRoadDetectedAt"] = entry["lastLiveCheck"]
        if entry.get("royalRoadChapterUrl"):
            ledger_updates["royalRoadChapterUrl"] = entry.get("royalRoadChapterUrl")
    update_chapter_ledger(abbr, chapter, ledger_updates)
    return entry


def remember_release_dates(abbr: str, chapter: int, dates: dict[str, str], source: str = "schedule") -> dict[str, Any]:
    status = load_release_status()
    key = f"{abbr.upper()}-{chapter}"
    entry = dict(status.get("chapters", {}).get(key, {}))
    entry.update(
        {
            "abbr": abbr.upper(),
            "chapter": chapter,
            "innerDiscipleDate": dates.get("innerDiscipleDate", ""),
            "pathInitiateDate": dates.get("pathInitiateDate", ""),
            "royalRoadDate": dates.get("royalRoadDate", ""),
            "releaseDateSource": source,
            "lastDateTrackingUpdate": time.strftime("%Y-%m-%d %H:%M:%S"),
        }
    )
    status.setdefault("chapters", {})[key] = entry
    save_release_status(status)
    return entry


def load_chapter_ledger(*args, **kwargs):
    return release_state.load_chapter_ledger(*args, **kwargs)
def save_chapter_ledger(*args, **kwargs):
    return release_state.save_chapter_ledger(*args, **kwargs)
def chapter_ledger_default_entry(*args, **kwargs):
    return release_state.chapter_ledger_default_entry(*args, **kwargs)
def normalize_chapter_ledger_entry(*args, **kwargs):
    return release_state.normalize_chapter_ledger_entry(*args, **kwargs)
def chapter_ledger_updates_for_folder(*args, **kwargs):
    return release_state.chapter_ledger_updates_for_folder(*args, **kwargs)
def is_experiment_variant_metadata(metadata: dict[str, Any]) -> bool:
    return bool(str(metadata.get("experimentId") or "").strip() or str(metadata.get("variantId") or "").strip())


def post_progress_tool(metadata: dict[str, Any]) -> str:
    return "variants" if is_experiment_variant_metadata(metadata) else "promo"


def update_chapter_ledger(*args, **kwargs):
    return release_state.update_chapter_ledger(*args, **kwargs)
def continuity_file_for(abbr: str) -> Path:
    CONTINUITY_DIR.mkdir(parents=True, exist_ok=True)
    return CONTINUITY_DIR / f"{story_key(abbr)}-summary.json"


def normalize_continuity_list(value: Any) -> list[str]:
    if isinstance(value, list):
        return [str(item).strip() for item in value if str(item).strip()]
    if isinstance(value, str):
        parts = re.split(r"(?:\n|;|\s+\|\s+)", value)
        return [part.strip(" -\t") for part in parts if part.strip(" -\t")]
    return []


def normalize_continuity_snapshot(abbr: str, data: dict[str, Any] | None = None) -> dict[str, Any]:
    data = dict(data or {})
    abbr = story_key(abbr or str(data.get("abbr") or ""))
    return {
        "abbr": abbr,
        "novel": NOVEL_NAMES.get(abbr, abbr),
        "current_arc": str(data.get("current_arc") or data.get("currentArc") or "").strip(),
        "important_characters": normalize_continuity_list(data.get("important_characters") or data.get("importantCharacters") or data.get("mainCharacters")),
        "unresolved_plot_threads": normalize_continuity_list(data.get("unresolved_plot_threads") or data.get("unresolvedPlotThreads") or data.get("openThreads")),
        "last_chapter": data.get("last_chapter") or data.get("lastChapter") or "",
        "last_title": str(data.get("last_title") or data.get("lastTitle") or "").strip(),
        "last_chapter_summary": str(data.get("last_chapter_summary") or data.get("lastSummary") or "").strip(),
        "tone_style_notes": str(data.get("tone_style_notes") or data.get("styleNotes") or "").strip(),
        "next_chapter_setup": str(data.get("next_chapter_setup") or data.get("nextSetup") or "").strip(),
        "recent_chapters": data.get("recent_chapters") if isinstance(data.get("recent_chapters"), list) else [],
        "updatedAt": str(data.get("updatedAt") or "").strip(),
    }


def load_continuity_snapshot(abbr: str) -> dict[str, Any]:
    path = continuity_file_for(abbr)
    legacy_path = CONTINUITY_DIR / f"{story_key(abbr).lower()}-summary.json"
    if not path.exists() and legacy_path.exists():
        path = legacy_path
    if not path.exists():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8-sig"))
    except Exception:
        return {}
    return normalize_continuity_snapshot(abbr, data) if isinstance(data, dict) else {}


def save_continuity_snapshot(abbr: str, data: dict[str, Any]) -> Path:
    path = continuity_file_for(abbr)
    payload = normalize_continuity_snapshot(abbr, data)
    payload["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    return path


def latest_docs_chapter_number(abbr: str) -> int:
    chapters = docs_chapter_index(abbr).get("chapters", [])
    numbers = [int(chapter["number"]) for chapter in chapters if str(chapter.get("number", "")).lstrip("-").isdigit()]
    return max(numbers) if numbers else 0


def recent_docs_chapters(abbr: str, count: int = 3) -> list[dict[str, Any]]:
    index = docs_chapter_index(abbr)
    numbers = sorted({int(chapter["number"]) for chapter in index.get("chapters", []) if str(chapter.get("number", "")).lstrip("-").isdigit()})
    selected = numbers[-count:]
    chapters: list[dict[str, Any]] = []
    for number in selected:
        try:
            chapters.append(docs_chapter_text(abbr, number))
        except Exception:
            continue
    return chapters


def next_chapter_context(abbr: str, recent_count: int = 3) -> dict[str, Any]:
    abbr = story_key(abbr)
    if not abbr:
        raise RuntimeError("Choose a known novel.")
    latest = latest_docs_chapter_number(abbr)
    continuity = load_continuity_snapshot(abbr)
    recent = recent_docs_chapters(abbr, 1 if continuity else recent_count)
    return {
        "abbr": abbr,
        "novel": NOVEL_NAMES.get(abbr, abbr),
        "latestChapter": latest,
        "nextChapter": latest + 1,
        "recentChapters": recent,
        "continuity": continuity,
    }


def continuity_text_from_context(context: dict[str, Any], extra_notes: str = "") -> str:
    continuity = context.get("continuity") if isinstance(context.get("continuity"), dict) else {}
    lines = [
        f"Novel: {context.get('novel', '')}",
        f"Latest chapter in GitHub Docs: {context.get('latestChapter', '')}",
    ]
    if continuity:
        fields = [
            ("Current arc", continuity.get("current_arc")),
            ("Important characters", "; ".join(continuity.get("important_characters") or [])),
            ("Unresolved plot threads", "; ".join(continuity.get("unresolved_plot_threads") or [])),
            ("Last chapter summary", continuity.get("last_chapter_summary")),
            ("Tone/style notes", continuity.get("tone_style_notes")),
            ("Next chapter setup", continuity.get("next_chapter_setup")),
        ]
        for label, value in fields:
            if value:
                lines.append(f"{label}: {value}")
    for chapter in context.get("recentChapters", []):
        text = str(chapter.get("text") or chapter.get("raw_text") or "")
        limit = 700 if continuity else 2200
        excerpt = re.sub(r"\s+", " ", text).strip()[:limit]
        lines.append(f"Recent chapter check {chapter.get('number')}: {chapter.get('title')}\n{excerpt}")
    if extra_notes.strip():
        lines.append(f"User notes for this chapter:\n{extra_notes.strip()}")
    return "\n\n".join(line for line in lines if str(line).strip())


def update_continuity_from_written_chapter(abbr: str, chapter_number: int, title: str, data: dict[str, Any], prior: dict[str, Any]) -> dict[str, Any]:
    snapshot = normalize_continuity_snapshot(abbr, prior)
    generated = data.get("continuity_snapshot") if isinstance(data.get("continuity_snapshot"), dict) else {}
    if generated:
        generated = normalize_continuity_snapshot(abbr, {**snapshot, **generated})
        snapshot.update({key: value for key, value in generated.items() if value not in ("", [], None)})
    recent = list(snapshot.get("recent_chapters") or [])
    recent.append(
        {
            "chapter": chapter_number,
            "title": title,
            "summary": str(data.get("short_summary") or generated.get("last_chapter_summary") or snapshot.get("last_chapter_summary") or "").strip(),
        }
    )
    snapshot.update(
        {
            "last_chapter": chapter_number,
            "last_title": title,
            "last_chapter_summary": str(data.get("short_summary") or snapshot.get("last_chapter_summary") or "").strip(),
            "next_chapter_setup": str(data.get("continuity_notes") or snapshot.get("next_chapter_setup") or "").strip(),
            "recent_chapters": recent[-5:],
        }
    )
    save_continuity_snapshot(abbr, snapshot)
    return snapshot


def summarize_chapter_for_snapshot(text: str, limit: int = 650) -> str:
    body = normalize_story_text(chapter_body_for_marketing(text))
    sentences = [sentence.strip() for sentence in re.split(r"(?<=[.!?])\s+", body) if sentence.strip()]
    summary = " ".join(sentences[:4]).strip()
    if len(summary) > limit:
        summary = summary[:limit].rsplit(" ", 1)[0].rstrip() + "..."
    return summary


def next_setup_from_chapter_text(text: str, limit: int = 420) -> str:
    paragraphs = [normalize_story_text(part).strip() for part in re.split(r"\n\s*\n+", text) if normalize_story_text(part).strip()]
    candidate = paragraphs[-1] if paragraphs else summarize_chapter_for_snapshot(text, limit)
    if len(candidate) > limit:
        candidate = candidate[:limit].rsplit(" ", 1)[0].rstrip() + "..."
    return candidate


def bootstrap_continuity_snapshot(abbr: str) -> dict[str, Any]:
    abbr = story_key(abbr)
    if not abbr:
        raise RuntimeError("Choose a known novel.")
    latest = latest_docs_chapter_number(abbr)
    if latest <= 0:
        raise RuntimeError(f"No GitHub chapters were found for {abbr}.")
    chapter = docs_chapter_text(abbr, latest)
    snapshot = normalize_continuity_snapshot(
        abbr,
        {
            "last_chapter": latest,
            "last_title": chapter.get("title") or chapter.get("heading") or f"Chapter {latest}",
            "last_chapter_summary": summarize_chapter_for_snapshot(str(chapter.get("text") or chapter.get("raw_text") or "")),
            "next_chapter_setup": next_setup_from_chapter_text(str(chapter.get("text") or chapter.get("raw_text") or "")),
            "tone_style_notes": "Preserve the established prose style, pacing, POV discipline, character motivations, and current arc momentum.",
            "recent_chapters": [
                {
                    "chapter": latest,
                    "title": chapter.get("title") or chapter.get("heading") or f"Chapter {latest}",
                    "summary": summarize_chapter_for_snapshot(str(chapter.get("text") or chapter.get("raw_text") or ""), 420),
                }
            ],
        },
    )
    save_continuity_snapshot(abbr, snapshot)
    return snapshot


def openai_rate_limited(exc: Exception) -> bool:
    if isinstance(exc, urllib.error.HTTPError) and exc.code == 429:
        return True
    text = str(exc)
    return "429" in text and "Too Many Requests" in text


def save_next_chapter_retry_context(
    context: dict[str, Any],
    outline_text: str,
    continuity: str,
    target_words: int,
    exc: Exception,
) -> Path:
    CHAPTER_RETRY_DIR.mkdir(parents=True, exist_ok=True)
    abbr = story_key(str(context.get("abbr") or ""))
    chapter_number = int(context.get("nextChapter") or 0)
    timestamp = time.strftime("%Y%m%d-%H%M%S")
    path = CHAPTER_RETRY_DIR / f"{timestamp}-{abbr or 'novel'}-chapter-{chapter_number}-retry.json"
    payload = {
        "createdAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "reason": str(exc),
        "retryPath": "OpenAI is rate-limited. Retry Create Next Chapter after quota resets; the chapter was not marked written.",
        "abbr": abbr,
        "novel": context.get("novel") or NOVEL_NAMES.get(abbr, ""),
        "targetChapter": chapter_number,
        "latestChapter": context.get("latestChapter"),
        "outline": outline_text,
        "continuity": continuity,
        "targetWords": int(target_words or 3000),
        "recentChapters": context.get("recentChapters", []),
        "continuitySnapshot": context.get("continuity", {}),
    }
    path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    return path


def manual_next_chapter_prompt(
    abbr: str,
    outline: str = "",
    continuity_notes: str = "",
    target_words: int = 3000,
) -> dict[str, Any]:
    context = next_chapter_context(abbr)
    chapter_number = int(context["nextChapter"])
    continuity = continuity_text_from_context(context, continuity_notes)
    outline_text = outline.strip() or (
        "Continue naturally from the latest GitHub chapter. Resolve the immediate scene momentum, "
        "preserve character motivations, deepen the current arc, and end with a clear hook into the next chapter."
    )
    prompt = f"""Write the next chapter for the web novel {context['novel']}.

Chapter number: {chapter_number}
Chapter title: create a fitting chapter title unless the outline gives one
Target length: about {int(target_words or 3000)} words

Outline:
{outline_text}

Continuity and style notes:
{continuity}

Requirements:
- Preserve continuity and character motivations from the notes.
- Write polished prose, not an outline.
- Include one clear chapter title at the top.
- End with forward momentum into the next chapter.
- Do not include marketing copy, author notes, explanations, analysis, markdown tables, or code blocks.
- Use normal paragraph spacing.
- Use hyphens instead of em dashes.

Return only:
Title line
Chapter prose
"""
    CHAPTER_RETRY_DIR.mkdir(parents=True, exist_ok=True)
    path = CHAPTER_RETRY_DIR / f"{time.strftime('%Y%m%d-%H%M%S')}-{context['abbr']}-chapter-{chapter_number}-manual-prompt.txt"
    path.write_text(prompt, encoding="utf-8")
    update_chapter_ledger(
        context["abbr"],
        chapter_number,
        {
            "title": "",
            "written": False,
            "writePending": True,
            "writeMode": "codex_session",
            "manualPromptFile": str(path),
            "lastAttemptAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        },
    )
    return {
        "abbr": context["abbr"],
        "novel": context["novel"],
        "chapter_number": chapter_number,
        "latest_chapter": context["latestChapter"],
        "prompt": prompt,
        "prompt_file": str(path),
        "message": f"Codex writing context is ready for {context['abbr']} Chapter {chapter_number}. No OpenAI API request was made.",
        "recentChapters": [{"number": item.get("number"), "title": item.get("title")} for item in context.get("recentChapters", [])],
    }


def write_chatgpt_chapter_playwright_script(job_id: str, prompt: str, target_words: int) -> Path:
    CHATGPT_CHAPTER_SCRIPT_FILE.write_text(
        rf"""const fs = require('fs');
const {{ chromium }} = require('playwright');
const cdpUrl = {json.dumps(chrome_debug_url())};
const jobId = {json.dumps(job_id)};
const prompt = {json.dumps(prompt)};
const targetWords = {int(target_words or 3000)};
const outputPath = {json.dumps(str(CHATGPT_CHAPTER_RESULT_FILE))};

async function findEditor(page) {{
  const candidates = [
    page.locator('#prompt-textarea').first(),
    page.locator('[contenteditable="true"][data-lexical-editor="true"]').first(),
    page.locator('textarea[placeholder*="Message" i]').first(),
    page.locator('textarea').first(),
  ];
  for (const candidate of candidates) {{
    if (await candidate.count() && await candidate.isVisible().catch(() => false)) return candidate;
  }}
  return null;
}}

async function submitPrompt(page, text) {{
  const editor = await findEditor(page);
  if (!editor) throw new Error('ChatGPT prompt box was not found. Open chatgpt.com, sign in, and retry.');
  await editor.click();
  await page.keyboard.press('Control+A');
  await page.keyboard.insertText(text);
  const send = page.locator('button[data-testid="send-button"], button[aria-label*="Send" i]').last();
  if (await send.count() && await send.isEnabled().catch(() => false)) await send.click();
  else await page.keyboard.press('Enter');
}}

async function assistantMessages(page) {{
  const primary = page.locator('[data-message-author-role="assistant"]');
  if (await primary.count()) return primary;
  return page.locator('article[data-testid^="conversation-turn"]');
}}

async function waitForCompletedResponse(page, baseline) {{
  await page.waitForFunction(
    (start) => document.querySelectorAll('[data-message-author-role="assistant"]').length > start,
    baseline,
    {{ timeout: 240000 }}
  ).catch(() => null);
  let stableText = '';
  let stablePasses = 0;
  const deadline = Date.now() + 720000;
  while (Date.now() < deadline) {{
    const messages = await assistantMessages(page);
    const count = await messages.count();
    const parts = [];
    for (let index = baseline; index < count; index++) {{
      const value = (await messages.nth(index).innerText().catch(() => '')).trim();
      if (value) parts.push(value);
    }}
    const text = parts.join('\n\n').trim();
    const stopVisible = await page.locator('button[data-testid="stop-button"], button[aria-label*="Stop" i]').first().isVisible().catch(() => false);
    if (text.length > 300 && text === stableText && !stopVisible) stablePasses += 1;
    else stablePasses = 0;
    stableText = text;
    if (stablePasses >= 3) return stableText;
    await page.waitForTimeout(2000);
  }}
  throw new Error('ChatGPT did not finish the chapter before the 12-minute timeout. The conversation remains open for review.');
}}

(async () => {{
  const browser = await chromium.connectOverCDP(cdpUrl);
  const context = browser.contexts()[0] || await browser.newContext();
  let page = context.pages().find(candidate => {{
    try {{ return ['chatgpt.com', 'chat.openai.com'].includes(new URL(candidate.url()).hostname.replace(/^www\./, '')); }}
    catch (_) {{ return false; }}
  }});
  if (!page) {{
    page = await context.newPage();
    await page.goto('https://chatgpt.com/', {{ waitUntil: 'domcontentloaded', timeout: 45000 }});
  }}
  await page.bringToFront();
  await page.waitForLoadState('domcontentloaded', {{ timeout: 30000 }}).catch(() => null);
  await page.waitForTimeout(1500);
  const before = await assistantMessages(page);
  const baseline = await before.count();
  await submitPrompt(page, prompt);
  let chapterText = await waitForCompletedResponse(page, baseline);
  let words = chapterText.split(/\s+/).filter(Boolean).length;
  for (let continuation = 0; words < Math.floor(targetWords * 0.9) && continuation < 2; continuation++) {{
    const messages = await assistantMessages(page);
    const nextBaseline = await messages.count();
    await submitPrompt(page, `Continue the same chapter from the exact stopping point. Add enough polished prose to reach at least ${{targetWords}} total words. Do not repeat the title or earlier text. Return only the remaining chapter prose.`);
    const addition = await waitForCompletedResponse(page, nextBaseline);
    chapterText = `${{chapterText}}\n\n${{addition}}`.trim();
    words = chapterText.split(/\s+/).filter(Boolean).length;
  }}
  fs.writeFileSync(outputPath, JSON.stringify({{
    ok: true, jobId, chapterText, wordCount: words, sourceUrl: page.url(), completedAt: new Date().toISOString(), submitted: false
  }}, null, 2), 'utf8');
  process.exit(0);
}})().catch(error => {{
  fs.writeFileSync(outputPath, JSON.stringify({{ ok: false, jobId, error: error.message, stack: error.stack, completedAt: new Date().toISOString() }}, null, 2), 'utf8');
  process.exit(1);
}});
""",
        encoding="utf-8",
    )
    return CHATGPT_CHAPTER_SCRIPT_FILE


def chatgpt_chapter_worker(job: dict[str, Any]) -> None:
    try:
        run = subprocess.run(
            [str(bundled_node_executable()), str(CHATGPT_CHAPTER_SCRIPT_FILE)],
            cwd=str(ROOT),
            env={**os.environ, "NODE_PATH": str(ROOT / "node_modules"), "PLAYWRIGHT_BROWSERS_PATH": str(ROOT / "ms-playwright")},
            capture_output=True,
            text=True,
            timeout=1200,
            check=False,
            creationflags=subprocess.CREATE_NO_WINDOW if hasattr(subprocess, "CREATE_NO_WINDOW") else 0,
        )
        result = _phase2_load_blob("chatgptChapterResult", CHATGPT_CHAPTER_RESULT_FILE)
        if not isinstance(result, dict) or str(result.get("jobId") or "") != str(job.get("jobId") or ""):
            result = {"ok": False, "error": run.stderr.strip() or "ChatGPT browser helper did not return a result."}
        state = {
            **job,
            **result,
            "running": False,
            "ready": bool(result.get("ok") and result.get("chapterText")),
            "stdout": run.stdout.strip(),
            "stderr": run.stderr.strip(),
            "finishedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        }
        _phase2_save_blob("chatgptChapterStatus", CHATGPT_CHAPTER_STATUS_FILE, state)
    except Exception as exc:
        _phase2_save_blob("chatgptChapterStatus", CHATGPT_CHAPTER_STATUS_FILE, {**job, "running": False, "ready": False, "error": str(exc), "finishedAt": time.strftime("%Y-%m-%d %H:%M:%S")})
    finally:
        if CHATGPT_CHAPTER_LOCK.locked():
            CHATGPT_CHAPTER_LOCK.release()


def start_chatgpt_chapter_writer(abbr: str, outline: str = "", continuity_notes: str = "", target_words: int = 3000) -> dict[str, Any]:
    global CHATGPT_CHAPTER_THREAD
    if not CHATGPT_CHAPTER_LOCK.acquire(blocking=False):
        return {**chatgpt_chapter_writer_status(), "busy": True, "message": "A ChatGPT chapter is already being created."}
    try:
        chrome_ready, chrome_message = chrome_debug_available()
        if not chrome_ready:
            raise RuntimeError(chrome_message)
        if not playwright_available():
            raise RuntimeError("The bundled Playwright helper is unavailable.")
        context = manual_next_chapter_prompt(abbr, outline, continuity_notes, target_words)
        job_id = f"{time.strftime('%Y%m%d-%H%M%S')}-{context['abbr']}-{context['chapter_number']}"
        try:
            CHATGPT_CHAPTER_RESULT_FILE.unlink()
        except OSError:
            pass
        write_chatgpt_chapter_playwright_script(job_id, str(context.get("prompt") or ""), int(target_words or 3000))
        state = {
            "jobId": job_id,
            "abbr": context["abbr"],
            "novel": context["novel"],
            "chapterNumber": context["chapter_number"],
            "targetWords": int(target_words or 3000),
            "promptFile": context.get("prompt_file", ""),
            "running": True,
            "ready": False,
            "startedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
            "message": "ChatGPT is writing the chapter in helper Chrome. You can keep using the Automation Tool.",
        }
        _phase2_save_blob("chatgptChapterStatus", CHATGPT_CHAPTER_STATUS_FILE, state)
        CHATGPT_CHAPTER_THREAD = threading.Thread(target=chatgpt_chapter_worker, args=(state,), daemon=True, name="chatgpt-chapter-writer")
        CHATGPT_CHAPTER_THREAD.start()
        return {**state, "chromeMessage": chrome_message}
    except Exception:
        CHATGPT_CHAPTER_LOCK.release()
        raise


def chatgpt_chapter_writer_status() -> dict[str, Any]:
    state = _phase2_load_blob("chatgptChapterStatus", CHATGPT_CHAPTER_STATUS_FILE)
    if not isinstance(state, dict) or not state:
        return {"running": False, "ready": False, "message": "No ChatGPT website chapter is currently prepared."}
    return state


