def chapter_workflow_status(abbr: str = "") -> dict[str, Any]:
    ledger = load_chapter_ledger()
    chapters = ledger.get("chapters", {}) if isinstance(ledger.get("chapters"), dict) else {}
    wanted = story_key(abbr) if abbr else ""
    items: list[dict[str, Any]] = []
    for key, entry in chapters.items():
        if wanted and story_key(str(entry.get("abbr") or "")) != wanted:
            continue
        item = dict(entry)
        missing = []
        if not item.get("written"):
            missing.append("write")
        if not item.get("uploadedToGitHubDocs") and not item.get("githubDocsUploaded"):
            missing.append("github-docs")
        if not item.get("promoPackBuilt") and not item.get("promoBuilt"):
            missing.append("promo")
        if not item.get("shortsReelsBuilt") and not item.get("shortsPackBuilt"):
            missing.append("shorts")
        if not item.get("socialPostsQueued") and not item.get("instagramQueued"):
            missing.append("instagram")
        if not item.get("postedToRoyalRoad") and not item.get("royalRoadReviewed"):
            missing.append("royal-road")
        item["missing"] = missing
        item["complete"] = not missing
        items.append(item)
    items.sort(key=lambda item: (str(item.get("abbr", "")), int(item.get("chapter") or 0)))
    next_by_novel: dict[str, Any] = {}
    for novel_abbr in NOVEL_NAMES:
        try:
            context = next_chapter_context(novel_abbr, 1)
            next_by_novel[novel_abbr] = {
                "novel": NOVEL_NAMES[novel_abbr],
                "latestChapter": context["latestChapter"],
                "nextChapter": context["nextChapter"],
            }
        except Exception as exc:
            next_by_novel[novel_abbr] = {"novel": NOVEL_NAMES[novel_abbr], "error": str(exc)}
    return {
        "ledger": ledger,
        "items": items,
        "nextByNovel": next_by_novel,
    }


WORKFLOW_ACTION_ORDER = ["promo", "shorts", "royal-road", "instagram"]


def chapter_ledger_entry(*args, **kwargs):
    return release_state.chapter_ledger_entry(*args, **kwargs)
def missing_workflow_actions(abbr: str, chapter: int | str) -> list[str]:
    entry = chapter_ledger_entry(abbr, chapter)
    missing = []
    if not entry.get("promoPackBuilt") and not entry.get("promoBuilt"):
        missing.append("promo")
    shorts_built = bool(entry.get("shortsReelsBuilt") or entry.get("shortsPackBuilt"))
    shorts_queued = bool(
        entry.get("shortsReelsQueued")
        or entry.get("shortsQueued")
        or entry.get("tiktokQueued")
        or entry.get("instagramReelQueued")
        or entry.get("youtubeShortQueued")
    )
    if not shorts_built or not shorts_queued:
        missing.append("shorts")
    if not entry.get("postedToRoyalRoad") and not entry.get("royalRoadReviewed"):
        missing.append("royal-road")
    if not entry.get("socialPostsQueued") and not entry.get("instagramQueued") and not entry.get("dailySocialBuilt"):
        missing.append("instagram")
    return missing


def next_required_action(abbr: str, chapter: int | str) -> dict[str, Any]:
    abbr = story_key(abbr)
    if not abbr:
        raise RuntimeError("Choose a known novel.")
    chapter_number = int(chapter)
    missing = missing_workflow_actions(abbr, chapter_number)
    action = next((item for item in WORKFLOW_ACTION_ORDER if item in missing), "complete")
    return {
        "abbr": abbr,
        "novel": NOVEL_NAMES.get(abbr, abbr),
        "chapter": chapter_number,
        "action": action,
        "missing": missing,
        "entry": chapter_ledger_entry(abbr, chapter_number),
    }


def do_next_required_action(abbr: str, chapter: int | str, use_openai: bool = True) -> dict[str, Any]:
    info = next_required_action(abbr, chapter)
    abbr = info["abbr"]
    chapter_number = int(info["chapter"])
    action = info["action"]
    if action == "complete":
        return {**info, "message": "This chapter has no missing automated workflow steps."}
    if action == "promo":
        data = docs_chapter_text(abbr, chapter_number)
        result = make_campaign(
            data.get("title") or data.get("heading") or f"Chapter {chapter_number}",
            data.get("text") or data.get("raw_text") or "",
            use_openai,
            abbr=abbr,
            novel=data.get("novel") or NOVEL_NAMES.get(abbr, abbr),
            chapter_number=chapter_number,
            render_videos=False,
            force_new_images=True,
        )
        return {**info, "result": result, "message": "Promo pack built.", "folder": result.get("folder", "")}
    if action == "shorts":
        entry = chapter_ledger_entry(abbr, chapter_number)
        folders = entry.get("folders") if isinstance(entry.get("folders"), dict) else {}
        shorts_folder = str(folders.get("shorts") or entry.get("shortsFolder") or "").strip()
        if shorts_folder and (Path(shorts_folder) / "tiktok-video.mp4").exists():
            return {
                **info,
                "message": "TikTok / Reel / Short video already exists. Review it, then push the Shorts/Reels pack to Buffer.",
                "folder": shorts_folder,
                "needsBufferPush": True,
            }
        result = make_or_generate_tiktok_pack(abbr, str(chapter_number), "")
        return {**info, "result": result, "message": "TikTok / Reel / Short pack built.", "folder": result.get("folder", "")}
    if action == "youtube":
        data = docs_chapter_text(abbr, chapter_number)
        result = build_youtube_from_text(
            data.get("title") or data.get("heading") or f"Chapter {chapter_number}",
            data.get("text") or data.get("raw_text") or "",
            abbr,
            chapter_number,
        )
        return {**info, "result": result, "message": "YouTube video pack built.", "folder": result.get("folder", "")}
    if action == "royal-road":
        result = make_royal_road_chapter_pack(abbr, chapter_number)
        update_chapter_ledger(
            abbr,
            chapter_number,
            {
                "royalRoadReviewed": True,
                "royalRoadReviewedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
                "royalRoadFolder": result.get("folder", ""),
            },
        )
        return {**info, "result": result, "message": "Royal Road review pack built.", "folder": result.get("folder", "")}
    if action == "instagram":
        day = DAYS[datetime.now().weekday()]
        template = SOCIAL_PROMPT_FILE.read_text(encoding="utf-8") if SOCIAL_PROMPT_FILE.exists() else "{novel} {day}"
        result = make_social_post(abbr, day, template, use_openai)
        update_chapter_ledger(
            abbr,
            chapter_number,
            {
                "dailySocialBuilt": True,
                "dailySocialBuiltAt": time.strftime("%Y-%m-%d %H:%M:%S"),
                "dailySocialFolder": result.get("folder", ""),
            },
        )
        return {**info, "result": result, "message": "Daily social post pack built.", "folder": result.get("folder", "")}
    return {**info, "message": f"No handler exists for action: {action}"}


def run_missing_workflow_actions(abbr: str, chapter: int | str, use_openai: bool = True, limit: int = 5) -> dict[str, Any]:
    abbr = story_key(abbr)
    if not abbr:
        raise RuntimeError("Choose a known novel.")
    chapter_number = int(chapter)
    steps: list[dict[str, Any]] = []
    errors: list[dict[str, str]] = []
    limit = max(1, min(int(limit or 5), len(WORKFLOW_ACTION_ORDER)))
    for _ in range(limit):
        info = next_required_action(abbr, chapter_number)
        action = info.get("action")
        if action == "complete":
            return {
                "abbr": abbr,
                "novel": NOVEL_NAMES.get(abbr, abbr),
                "chapter": chapter_number,
                "complete": True,
                "steps": steps,
                "errors": errors,
                "message": "All automated workflow steps are complete.",
            }
        try:
            result = do_next_required_action(abbr, chapter_number, use_openai)
            steps.append({
                "action": action,
                "message": result.get("message", ""),
                "folder": result.get("folder", ""),
                "missingAfter": result.get("missing", []),
            })
        except Exception as exc:
            errors.append({"action": str(action), "error": str(exc)})
            break
    final_info = next_required_action(abbr, chapter_number)
    return {
        "abbr": abbr,
        "novel": NOVEL_NAMES.get(abbr, abbr),
        "chapter": chapter_number,
        "complete": final_info.get("action") == "complete",
        "steps": steps,
        "errors": errors,
        "missing": final_info.get("missing", []),
        "nextAction": final_info.get("action"),
        "message": "Workflow pass finished. Review any remaining items before posting.",
    }


def parse_chapter_selection(value: str) -> list[int]:
    chapters: set[int] = set()
    for part in re.split(r"[,;\s]+", value.strip()):
        if not part:
            continue
        match = re.match(r"^(\d+)\s*[-:]\s*(\d+)$", part)
        if match:
            start, end = int(match.group(1)), int(match.group(2))
            if end < start:
                start, end = end, start
            chapters.update(range(start, end + 1))
            continue
        if part.isdigit():
            chapters.add(int(part))
    return sorted(chapters)


def novel_schedule_entry(abbr: str) -> dict[str, Any]:
    config = ensure_schedule_file()
    abbr = abbr.upper().strip()
    for novel in config.get("novels", []):
        if str(novel.get("abbr", "")).upper() == abbr:
            return novel
    return {
        "abbr": abbr,
        "name": NOVEL_NAMES.get(abbr, abbr),
        "currentRoyalRoadChapter": 0,
        "nextRoyalRoadDate": iso_today().isoformat(),
        "releaseDays": CHAPTER_RELEASE_DAYS,
    }


def chapter_release_dates(abbr: str, chapter: int) -> dict[str, str]:
    novel = novel_schedule_entry(abbr)
    current_rr = int(novel.get("currentRoyalRoadChapter", 0))
    next_chapter = current_rr + 1
    if chapter <= current_rr:
        return {"royalRoadDate": "", "innerDiscipleDate": "", "pathInitiateDate": ""}
    next_rr = datetime.fromisoformat(str(novel.get("nextRoyalRoadDate") or iso_today().isoformat())).date()
    release_days = novel.get("releaseDays") or CHAPTER_RELEASE_DAYS
    offset = max(0, chapter - next_chapter)
    royal_date = next_dates(next_rr, release_days, offset + 1)[offset]
    return {
        "royalRoadDate": royal_date.isoformat(),
        "innerDiscipleDate": (royal_date - timedelta(days=14)).isoformat(),
        "pathInitiateDate": (royal_date - timedelta(days=7)).isoformat(),
    }


def release_status_for_chapter(*args, **kwargs):
    return release_state.release_status_for_chapter(*args, **kwargs)
def release_plan_for_chapter(abbr: str, chapter: int | str) -> dict[str, Any]:
    abbr = story_key(abbr)
    if not abbr:
        raise RuntimeError("Choose a known novel.")
    chapter_number = int(chapter)
    status = release_status_for_chapter(abbr, chapter_number)
    decision, reason = decision_from_status(status)
    remember_release_dates(abbr, chapter_number, status.get("dates", {}) if isinstance(status.get("dates"), dict) else {}, "release-plan-preview")
    return {
        "abbr": abbr,
        "novel": NOVEL_NAMES.get(abbr, abbr),
        "chapter": chapter_number,
        "decision": decision,
        "reason": reason,
        "status": status,
        "ledger": chapter_ledger_entry(abbr, chapter_number),
        "missingWorkflow": missing_workflow_actions(abbr, chapter_number),
    }


def load_chapter_release_queue() -> dict[str, Any]:
    # Phase 1 retirement: SQLite (state_snapshots kv) is the sole source of truth.
    data = load_state_snapshot_from_database("chapterReleaseQueue")
    if not isinstance(data, dict):
        data = {"schemaVersion": 1, "rotationIndex": 0, "assignments": [], "errors": []}
    data.setdefault("schemaVersion", 1)
    data.setdefault("rotationIndex", 0)
    data.setdefault("assignments", [])
    data.setdefault("errors", [])
    return data


def save_chapter_release_queue(data: dict[str, Any]) -> None:
    data["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    mirror_state_snapshot_to_database("chapterReleaseQueue", data)


def next_weekday_on_or_after(day: date) -> date:
    cursor = day
    while cursor.weekday() >= 5:
        cursor += timedelta(days=1)
    return cursor


def sync_release_queue_artifact_dates(assignments: list[dict[str, Any]]) -> None:
    assignment_map = {str(item.get("key") or ""): item for item in assignments}
    for key, item in assignment_map.items():
        abbr = story_key(str(item.get("abbr") or ""))
        chapter = int(item.get("chapter") or 0)
        if not abbr or chapter <= 0:
            continue
        dates = {
            "innerDiscipleDate": str(item.get("innerDiscipleDate") or ""),
            "pathInitiateDate": str(item.get("pathInitiateDate") or ""),
            "royalRoadDate": str(item.get("royalRoadDate") or ""),
        }
        for folder_name in (f"release-{abbr.lower()}-{chapter}", f"royal-road-{abbr.lower()}-{chapter}"):
            metadata_path = SOCIAL_OUTPUT_DIR / folder_name / "metadata.json"
            if not metadata_path.exists():
                continue
            metadata = read_metadata(metadata_path.parent)
            release_status = dict(metadata.get("release_status") or {})
            if release_status.get("dates") == dates:
                continue
            release_status["dates"] = dates
            metadata["release_status"] = release_status
            patreon_draft = metadata.get("patreon_draft") if isinstance(metadata.get("patreon_draft"), dict) else None
            if patreon_draft is not None:
                tier_stage = str(patreon_draft.get("tier_stage") or metadata.get("patreonTierStage") or "inner_disciple")
                patreon_draft["publish_date"] = dates["pathInitiateDate"] if tier_stage == "path_initiate" else dates["innerDiscipleDate"]
                patreon_draft["path_initiate_date"] = dates["pathInitiateDate"]
                patreon_draft["royal_road_date"] = dates["royalRoadDate"]
            metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")

    pending = _phase2_load_blob("patreonPendingDraft", PATREON_PENDING_DRAFT_FILE)
    if not isinstance(pending, dict):
        return
    pending_metadata = pending.get("metadata") if isinstance(pending.get("metadata"), dict) else {}
    pending_key = str(pending_metadata.get("releaseQueueKey") or "")
    assignment = assignment_map.get(pending_key)
    if not assignment:
        return
    dates = {
        "innerDiscipleDate": str(assignment.get("innerDiscipleDate") or ""),
        "pathInitiateDate": str(assignment.get("pathInitiateDate") or ""),
        "royalRoadDate": str(assignment.get("royalRoadDate") or ""),
    }
    release_status = dict(pending_metadata.get("release_status") or {})
    release_status["dates"] = dates
    pending_metadata["release_status"] = release_status
    tier_stage = str(pending.get("tier_stage") or pending_metadata.get("patreonTierStage") or "inner_disciple")
    publish_date = dates["pathInitiateDate"] if tier_stage == "path_initiate" else dates["innerDiscipleDate"]
    pending["metadata"] = pending_metadata
    pending["publish_date"] = publish_date
    pending["path_initiate_date"] = dates["pathInitiateDate"]
    pending["royal_road_date"] = dates["royalRoadDate"]
    pending["tier_schedule"] = [{"tier": (pending.get("tiers") or ["Inner Disciple"])[0], "date": publish_date}]
    _phase2_save_blob("patreonPendingDraft", PATREON_PENDING_DRAFT_FILE, pending)


def ensure_chapter_release_queue(days_ahead: int = 90) -> dict[str, Any]:
    queue = load_chapter_release_queue()
    assignments = [item for item in queue.get("assignments", []) if isinstance(item, dict)]
    schedule = ensure_schedule_file()
    configured_start = str(schedule.get("releaseQueueStartDate") or "").strip()
    try:
        queue_start = next_weekday_on_or_after(datetime.fromisoformat(configured_start).date()) if configured_start else next_weekday_on_or_after(iso_today())
    except ValueError:
        queue_start = next_weekday_on_or_after(iso_today())

    schedule_mode = "daily-novel-rounds-v2"
    if assignments and queue.get("scheduleMode") != schedule_mode:
        for abbr in NOVEL_NAMES:
            novel_assignments = sorted(
                [item for item in assignments if story_key(str(item.get("abbr") or "")) == abbr],
                key=lambda item: int(item.get("chapter") or 0),
            )
            round_dates = next_dates(queue_start, CHAPTER_RELEASE_DAYS, len(novel_assignments))
            for index, item in enumerate(novel_assignments):
                previous_dates = {
                    "innerDiscipleDate": str(item.get("innerDiscipleDate") or ""),
                    "pathInitiateDate": str(item.get("pathInitiateDate") or ""),
                    "royalRoadDate": str(item.get("royalRoadDate") or ""),
                }
                inner_date = round_dates[index]
                path_date = inner_date + timedelta(days=7)
                royal_date = inner_date + timedelta(days=14)
                year, week, _ = inner_date.isocalendar()
                item.update({
                    "innerDiscipleDate": inner_date.isoformat(),
                    "pathInitiateDate": path_date.isoformat(),
                    "royalRoadDate": royal_date.isoformat(),
                    "releaseWeek": f"{year}-W{week:02d}",
                })
                dates = {
                    "innerDiscipleDate": item["innerDiscipleDate"],
                    "pathInitiateDate": item["pathInitiateDate"],
                    "royalRoadDate": item["royalRoadDate"],
                }
                remember_release_dates(abbr, int(item.get("chapter") or 0), dates, "daily-novel-release-round")
                ledger = chapter_ledger_entry(abbr, int(item.get("chapter") or 0))
                ledger_updates = {
                    **dates,
                    "releaseQueueDate": item["innerDiscipleDate"],
                }
                if previous_dates != dates:
                    if not ledger.get("patreonInnerDisciplePosted") and not ledger.get("postedToPatreon"):
                        ledger_updates["patreonInnerDiscipleDraftPrepared"] = False
                    if not ledger.get("patreonPathInitiatePosted"):
                        ledger_updates["patreonPathInitiateDraftPrepared"] = False
                    if not ledger.get("postedToRoyalRoad"):
                        ledger_updates["royalRoadUploadPrepared"] = False
                update_chapter_ledger(abbr, int(item.get("chapter") or 0), ledger_updates)
        queue["scheduleMode"] = schedule_mode

    for item in assignments:
        abbr = story_key(str(item.get("abbr") or ""))
        try:
            number = int(item.get("chapter") or 0)
        except (TypeError, ValueError):
            number = 0
        ledger = chapter_ledger_entry(abbr, number) if abbr and number else {}
        existing_rr = bool(
            ledger.get("postedToRoyalRoad")
            or ledger.get("royalRoadReviewed")
            or ledger.get("royalRoadChapterUrl")
            or item.get("existingRoyalRoad")
        )
        if existing_rr:
            item["existingRoyalRoad"] = True
            item["royalRoadMode"] = "update_existing"
            item["releaseAction"] = "review_existing_royal_road"
            if ledger.get("royalRoadChapterUrl"):
                item["royalRoadChapterUrl"] = ledger.get("royalRoadChapterUrl")
            item["releaseNote"] = "Existing Royal Road chapter. Review and update from rewritten GitHub text."
        else:
            item.setdefault("existingRoyalRoad", False)
            item.setdefault("royalRoadMode", "create_new")
            item.setdefault("releaseAction", "new_release")

    existing_keys = {str(item.get("key") or "") for item in assignments}
    occupied_slots = {
        (story_key(str(item.get("abbr") or "")), str(item.get("innerDiscipleDate") or ""))
        for item in assignments
    }
    weekly_counts: dict[str, int] = {}
    for item in assignments:
        abbr = story_key(str(item.get("abbr") or ""))
        try:
            assigned_date = datetime.fromisoformat(str(item.get("innerDiscipleDate") or "")).date()
        except ValueError:
            continue
        year, week, _ = assigned_date.isocalendar()
        week_key = f"{year}-W{week:02d}"
        novel_week_key = f"{abbr}:{week_key}"
        weekly_counts[novel_week_key] = weekly_counts.get(novel_week_key, 0) + 1
        item.setdefault("releaseWeek", week_key)
    scheduled_by_novel: dict[str, set[int]] = {abbr: set() for abbr in NOVEL_NAMES}
    for item in assignments:
        abbr = story_key(str(item.get("abbr") or ""))
        if abbr and str(item.get("chapter") or "").isdigit():
            scheduled_by_novel[abbr].add(int(item["chapter"]))

    upload_start_dates = {abbr: release_upload_next_inner_date(abbr) for abbr in NOVEL_NAMES}
    available: dict[str, list[dict[str, Any]]] = {}
    errors: list[dict[str, str]] = []
    for abbr in NOVEL_NAMES:
        try:
            index = docs_chapter_index(abbr)
            current_rr = int(novel_schedule_entry(abbr).get("currentRoyalRoadChapter") or 0)
            path_next = release_upload_next_chapter(abbr)
            rows = []
            for chapter in index.get("chapters", []) or []:
                raw_number = str(chapter.get("number") or "")
                if not raw_number.isdigit():
                    continue
                number = int(raw_number)
                ledger = chapter_ledger_entry(abbr, number)
                existing_rr = bool(
                    ledger.get("postedToRoyalRoad")
                    or ledger.get("royalRoadReviewed")
                    or ledger.get("royalRoadChapterUrl")
                )
                if path_next and number < path_next:
                    continue
                if number <= current_rr and not (path_next and existing_rr):
                    continue
                if number in scheduled_by_novel[abbr]:
                    continue
                if not path_next and ledger.get("postedToRoyalRoad"):
                    continue
                rows.append({"number": number, "title": str(chapter.get("title") or chapter.get("heading") or f"Chapter {number}")})
            available[abbr] = sorted(rows, key=lambda item: item["number"])
        except Exception as exc:
            available[abbr] = []
            errors.append({"abbr": abbr, "error": str(exc)})

    rotation = list(NOVEL_NAMES)
    cursor = queue_start
    end = max(queue_start, iso_today()) + timedelta(days=max(14, int(days_ahead)))
    while cursor <= end:
        date_text = cursor.isoformat()
        year, week, _ = cursor.isocalendar()
        week_key = f"{year}-W{week:02d}"
        if cursor.weekday() < 5:
            for abbr in rotation:
                upload_start = upload_start_dates.get(abbr)
                if upload_start and cursor < upload_start:
                    continue
                novel_week_key = f"{abbr}:{week_key}"
                if (abbr, date_text) in occupied_slots or weekly_counts.get(novel_week_key, 0) >= 5 or not available.get(abbr):
                    continue
                chapter = available[abbr].pop(0)
                number = int(chapter["number"])
                key = f"{abbr}-{number}"
                if key not in existing_keys:
                    ledger = chapter_ledger_entry(abbr, number)
                    existing_rr = bool(
                        ledger.get("postedToRoyalRoad")
                        or ledger.get("royalRoadReviewed")
                        or ledger.get("royalRoadChapterUrl")
                    )
                    path_date = cursor + timedelta(days=7)
                    rr_date = cursor + timedelta(days=14)
                    assignment = {
                        "key": key,
                        "abbr": abbr,
                        "novel": NOVEL_NAMES.get(abbr, abbr),
                        "chapter": number,
                        "title": chapter["title"],
                        "innerDiscipleDate": cursor.isoformat(),
                        "pathInitiateDate": path_date.isoformat(),
                        "royalRoadDate": rr_date.isoformat(),
                        "releaseWeek": week_key,
                        "existingRoyalRoad": existing_rr,
                        "royalRoadMode": "update_existing" if existing_rr else "create_new",
                        "releaseAction": "review_existing_royal_road" if existing_rr else "new_release",
                        "royalRoadChapterUrl": ledger.get("royalRoadChapterUrl") if existing_rr else "",
                        "releaseNote": "Existing Royal Road chapter. Review and update from rewritten GitHub text." if existing_rr else "",
                        "createdAt": time.strftime("%Y-%m-%d %H:%M:%S"),
                    }
                    assignments.append(assignment)
                    existing_keys.add(key)
                    occupied_slots.add((abbr, date_text))
                    weekly_counts[novel_week_key] = weekly_counts.get(novel_week_key, 0) + 1
                    scheduled_by_novel[abbr].add(number)
                    remember_release_dates(abbr, number, {
                        "innerDiscipleDate": assignment["innerDiscipleDate"],
                        "pathInitiateDate": assignment["pathInitiateDate"],
                        "royalRoadDate": assignment["royalRoadDate"],
                    }, "weekday-release-queue")
                    update_chapter_ledger(abbr, number, {
                        "innerDiscipleDate": assignment["innerDiscipleDate"],
                        "pathInitiateDate": assignment["pathInitiateDate"],
                        "royalRoadDate": assignment["royalRoadDate"],
                        "releaseQueueDate": assignment["innerDiscipleDate"],
                    })
        cursor += timedelta(days=1)
        if not any(available.values()):
            break
    novel_order = {abbr: index for index, abbr in enumerate(NOVEL_NAMES)}
    assignments.sort(key=lambda item: (
        str(item.get("innerDiscipleDate") or ""),
        novel_order.get(story_key(str(item.get("abbr") or "")), len(novel_order)),
    ))
    sync_release_queue_artifact_dates(assignments)
    queue["assignments"] = assignments
    queue["rotationIndex"] = 0
    queue["scheduleMode"] = schedule_mode
    queue["errors"] = errors
    queue["releaseDays"] = CHAPTER_RELEASE_DAYS
    queue["tierDelayDays"] = 7
    queue["royalRoadDelayDays"] = 14
    save_chapter_release_queue(queue)
    return queue


def release_queue_assignment_status(item: dict[str, Any]) -> dict[str, Any]:
    abbr = story_key(str(item.get("abbr") or ""))
    chapter = int(item.get("chapter") or 0)
    ledger = chapter_ledger_entry(abbr, chapter)
    existing_rr = bool(
        item.get("existingRoyalRoad")
        or item.get("royalRoadMode") == "update_existing"
        or ledger.get("postedToRoyalRoad")
        or ledger.get("royalRoadReviewed")
        or ledger.get("royalRoadChapterUrl")
    )
    reviewed_hash = str(ledger.get("royalRoadReviewedHash") or "").strip()
    existing_rr_needs_review = False
    if existing_rr:
        # Derive the review need from the ledger flag rather than recomputing a
        # chapter-text hash on every queue-status poll. Recomputing docs_chapter_text
        # per RR-existing assignment (97 of 163) added ~45s of blocking I/O and timed
        # out the endpoint. The hash re-check on text change belongs to the explicit
        # review action, not the status read.
        existing_rr_needs_review = not bool(ledger.get("royalRoadReviewed"))
    return {
        **item,
        "innerPosted": bool(ledger.get("patreonInnerDisciplePosted") or ledger.get("postedToPatreon")),
        "innerPrepared": bool(ledger.get("patreonInnerDiscipleDraftPrepared")),
        "pathPosted": bool(ledger.get("patreonPathInitiatePosted")),
        "pathPrepared": bool(ledger.get("patreonPathInitiateDraftPrepared")),
        "existingRoyalRoad": existing_rr,
        "royalRoadMode": "update_existing" if existing_rr else str(item.get("royalRoadMode") or "create_new"),
        "releaseAction": "review_existing_royal_road" if existing_rr else str(item.get("releaseAction") or "new_release"),
        "royalRoadPosted": bool(ledger.get("postedToRoyalRoad")),
        "royalRoadPrepared": bool(ledger.get("royalRoadUploadPrepared")),
        "needsInnerReview": bool(ledger.get("patreonInnerDiscipleDraftPrepared")) and not bool(ledger.get("patreonInnerDisciplePosted") or ledger.get("postedToPatreon")),
        "needsPathReview": bool(ledger.get("patreonPathInitiateDraftPrepared")) and not bool(ledger.get("patreonPathInitiatePosted")),
        "needsRoyalRoadReview": existing_rr_needs_review or (bool(ledger.get("royalRoadUploadPrepared")) and not bool(ledger.get("postedToRoyalRoad"))),
        "ledger": ledger,
    }


def chapter_release_upload_queue_status(refresh: bool = True) -> dict[str, Any]:
    queue = ensure_chapter_release_queue() if refresh else load_chapter_release_queue()
    today = iso_today()
    assignments = [release_queue_assignment_status(item) for item in queue.get("assignments", [])]
    due: list[dict[str, Any]] = []
    stage_rules = [
        ("inner_disciple", "innerDiscipleDate", "innerPosted", "innerPrepared"),
        ("path_initiate", "pathInitiateDate", "pathPosted", "pathPrepared"),
        ("royal_road", "royalRoadDate", "royalRoadPosted", "royalRoadPrepared"),
    ]
    for stage, date_key, posted_key, prepared_key in stage_rules:
        candidates = [
            item for item in assignments
            if item.get(date_key) and datetime.fromisoformat(str(item[date_key])).date() <= today
            and (not item.get(posted_key) or (stage == "royal_road" and item.get("needsRoyalRoadReview")))
        ]
        if candidates:
            due.append({
                "stage": stage,
                "assignment": sorted(candidates, key=lambda item: (
                    str(item.get(date_key) or ""),
                    0 if item.get(prepared_key) else 1,
                    story_key(str(item.get("abbr") or "")),
                    int(item.get("chapter") or 0),
                ))[0],
            })
    next_batches: dict[str, list[dict[str, Any]]] = {}
    for stage, date_key, posted_key, prepared_key in stage_rules:
        candidates = [
            item for item in assignments
            if item.get(date_key)
            and (not item.get(posted_key) or (stage == "royal_road" and item.get("needsRoyalRoadReview")))
        ]
        candidates.sort(key=lambda item: (
            0 if item.get(prepared_key) else 1,
            str(item.get(date_key) or ""),
            story_key(str(item.get("abbr") or "")),
            int(item.get("chapter") or 0),
        ))
        next_batches[stage] = candidates[:5]
    actionable_assignments = [
        item for item in assignments
        if not (
            item.get("innerPosted")
            and item.get("pathPosted")
            and item.get("royalRoadPosted")
            and not item.get("needsRoyalRoadReview")
        )
    ]
    actionable_assignments.sort(
        key=lambda item: (
            0 if item.get("needsInnerReview") or item.get("needsPathReview") or item.get("needsRoyalRoadReview") else 1,
            0 if not item.get("innerPosted") and not item.get("innerPrepared") else 1,
            0 if not item.get("pathPosted") and not item.get("pathPrepared") else 1,
            0 if not item.get("royalRoadPosted") and not item.get("royalRoadPrepared") else 1,
            str(item.get("innerDiscipleDate") or ""),
            story_key(str(item.get("abbr") or "")),
            int(item.get("chapter") or 0),
        )
    )
    next_by_novel: dict[str, dict[str, Any]] = {}
    for item in actionable_assignments:
        abbr = story_key(str(item.get("abbr") or ""))
        if abbr and abbr not in next_by_novel:
            next_by_novel[abbr] = item
    guardrails = release_queue_guardrails(assignments, next_by_novel)
    upcoming = [item for item in assignments if datetime.fromisoformat(str(item.get("royalRoadDate") or item.get("innerDiscipleDate"))).date() >= today - timedelta(days=14)]
    occupied = {
        (story_key(str(item.get("abbr") or "")), str(item.get("innerDiscipleDate") or ""))
        for item in assignments
    }
    weekly_counts: dict[str, int] = {}
    for item in assignments:
        try:
            assigned = datetime.fromisoformat(str(item.get("innerDiscipleDate") or "")).date()
        except ValueError:
            continue
        year, week, _ = assigned.isocalendar()
        abbr = story_key(str(item.get("abbr") or ""))
        key = f"{abbr}:{year}-W{week:02d}"
        weekly_counts[key] = weekly_counts.get(key, 0) + 1
    next_available = next_weekday_on_or_after(today)
    while True:
        year, week, _ = next_available.isocalendar()
        week_key = f"{year}-W{week:02d}"
        has_open_novel_slot = any(
            (abbr, next_available.isoformat()) not in occupied
            and weekly_counts.get(f"{abbr}:{week_key}", 0) < 5
            for abbr in NOVEL_NAMES
        )
        if next_available.weekday() < 5 and has_open_novel_slot:
            break
        next_available = next_weekday_on_or_after(next_available + timedelta(days=1))
    return {
        "generatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "today": today.isoformat(),
        "releaseDays": CHAPTER_RELEASE_DAYS,
        "weeklyChapterLimit": 5,
        "weeklyLimitScope": "per novel",
        "releaseUploadPath": release_upload_path_status(),
        "postingPath": active_chapter_path_status(),
        "workflowPaths": release_workflow_path_labels(),
        "nextAvailableDate": next_available.isoformat(),
        "due": due,
        "guardrails": guardrails,
        "assignments": actionable_assignments[:40],
        "nextByNovel": next_by_novel,
        "upcoming": upcoming[:40],
        "nextBatches": next_batches,
        "errors": queue.get("errors", []),
        "file": str(CHAPTER_RELEASE_QUEUE_FILE),
    }


def release_week_key(abbr: str, chapter: int) -> str:
    dates = chapter_release_dates(abbr, chapter)
    text = dates.get("royalRoadDate") or iso_today().isoformat()
    target = datetime.fromisoformat(text).date()
    year, week, _ = target.isocalendar()
    return f"{year}-W{week:02d}"


def decision_from_status(status: dict[str, Any], revision: dict[str, Any] | None = None) -> tuple[str, str]:
    revision = revision or {}
    if revision.get("changed") and (status.get("patreonExists") or status.get("royalRoadExists")):
        return "update_existing", "Latest GitHub chapter text differs from the remembered built version."
    if status.get("royalRoadExists") and status.get("royalRoadContentStatus") == "different":
        return "update_existing", "Royal Road chapter exists, but its online text differs from the GitHub chapter."
    if status.get("royalRoadExists") and status.get("royalRoadContentStatus") == "unknown":
        return "update_existing", "Royal Road chapter exists, but the checker could not confirm the online text matches GitHub."
    if status.get("royalRoadExists"):
        return "social_only", "Chapter already exists on Royal Road."
    if status.get("patreonExists") and status.get("royalRoadDue"):
        return "royal_road_ready", "Chapter exists on Patreon and the Royal Road date has passed."
    if status.get("patreonExists"):
        return "patreon_only", "Chapter exists on Patreon, but the Royal Road date has not arrived yet."
    if status.get("patreonDue"):
        return "patreon_ready", "Chapter does not exist on Patreon and the Inner Disciple date has arrived."
    return "blocked", "Not on Patreon yet, so Royal Road/social posting is held."


def release_copy(abbr: str, chapter: int, title: str, decision: str) -> dict[str, str]:
    profile = social_profile(abbr)
    rr = royal_road_url_for_story(abbr)
    if decision == "update_existing":
        hook = f"{profile['emoji']} {profile['name']} Chapter {chapter} has an updated version ready."
        instagram = "\n".join([hook, title, "Latest text is ready for platform review.", "Read now. Link in bio.", "", profile["hashtags"]])
        x_text = f"{profile['emoji']} {profile['name']} Ch. {chapter} has been refreshed.\nRead now: link in bio.\n{profile['x_hashtags']}"
    elif decision in {"social_only", "royal_road_ready"}:
        hook = f"{profile['emoji']} {profile['name']} Chapter {chapter} is live on Royal Road!"
        instagram = "\n".join([hook, title, "Read now. Link in bio.", "", profile["hashtags"]])
        x_text = f"{profile['emoji']} {profile['name']} Ch. {chapter} is live on Royal Road.\nRead now: link in bio.\n{profile['x_hashtags']}"
    elif decision in {"patreon_only", "patreon_ready"}:
        hook = f"{profile['emoji']} {profile['name']} Chapter {chapter} is available early on Patreon."
        instagram = "\n".join([hook, title, "Read ahead. Link in bio.", "", profile["hashtags"]])
        x_text = f"{profile['emoji']} {profile['name']} Ch. {chapter} is on Patreon early.\nRead ahead: link in bio.\n{profile['x_hashtags']}"
    else:
        hook = f"{profile['emoji']} {profile['name']} Chapter {chapter} is not ready for public posting yet."
        instagram = "\n".join([hook, "Hold this post until Patreon/Royal Road status is ready."])
        x_text = f"{profile['name']} Ch. {chapter} is queued for a later release check."
    if len(x_text) > 275:
        x_text = x_text[:272].rsplit(" ", 1)[0].rstrip() + "..."
    facebook = "\n\n".join([instagram.split("\n\n")[0], "Follow the story updates through the link in bio.", profile["hashtags"]])
    return {
        "instagram": with_instagram_links(instagram, abbr),
        "x": x_text,
        "facebook": facebook,
        "alt_text": f"Promotional image for {profile['name']} Chapter {chapter}.",
    }


def concise_release_title(raw_title: str, abbr: str, chapter: int) -> str:
    title = re.sub(r"\s+", " ", raw_title or "").strip()
    if not title:
        return f"Chapter {chapter}"
    title = re.sub(r"^(?:\s*[:.\-\u2013\u2014]\s*)+", "", title).strip()
    glued = re.search(r"(?<=[a-z])(?=[A-Z][a-z])", title)
    if glued:
        title = title[: glued.start()].strip()
    if len(title) <= 90:
        return title
    match = re.match(rf"^(Chapter\s+{chapter}[A-Za-z]?(?:\s+Part\s+\d+)?(?:\s*[:.\-]\s*)?.{{0,60}})", title, re.IGNORECASE)
    if match:
        candidate = match.group(1).strip()
        if len(candidate) <= 90:
            return candidate
    return f"Chapter {chapter}"


def make_release_chapter_pack(
    abbr: str,
    chapter: int,
    decision: str,
    status: dict[str, Any],
    data: dict[str, Any] | None = None,
    revision: dict[str, Any] | None = None,
) -> dict[str, Any]:
    data = data or docs_chapter_text(abbr, chapter)
    revision = revision or chapter_revision_info(abbr, chapter, data)
    title = concise_release_title(data.get("title") or data.get("heading") or "", abbr, chapter)
    folder = SOCIAL_OUTPUT_DIR / f"release-{abbr.lower()}-{chapter}"
    reset_generated_folder(folder)
    copy = release_copy(abbr, chapter, title, decision)
    image_target_path = folder / f"{abbr}_{chapter}_release.png"
    image_source = create_fresh_social_image_from_caption(
        image_target_path,
        abbr=abbr,
        novel=NOVEL_NAMES.get(abbr, abbr),
        title=title,
        caption=copy["instagram"],
        hook=copy.get("x", ""),
        index=chapter,
    )
    payload = {
        **copy,
        "abbr": abbr,
        "novel": NOVEL_NAMES.get(abbr, abbr),
        "chapter": chapter,
        "title": title,
        "kind": "release-master",
        "decision": decision,
        "release_status": status,
        "revision": {
            "contentHash": revision.get("contentHash", ""),
            "previousHash": revision.get("previousHash", ""),
            "changed": bool(revision.get("changed")),
            "firstSeen": bool(revision.get("firstSeen")),
            "wordCount": revision.get("wordCount", 0),
        },
        "folder": str(folder),
        "image": str(image_target_path),
        "image_source": image_source,
    }
    remember_release_dates(abbr, chapter, status.get("dates", {}) if isinstance(status.get("dates"), dict) else {}, "master-release-build")
    (folder / "instagram.txt").write_text(copy["instagram"].strip() + "\n", encoding="utf-8")
    (folder / "x.txt").write_text(copy["x"].strip() + "\n", encoding="utf-8")
    (folder / "facebook.txt").write_text(copy["facebook"].strip() + "\n", encoding="utf-8")
    (folder / "alt-text.txt").write_text(copy["alt_text"].strip() + "\n", encoding="utf-8")
    platform_source_text = str(data.get("raw_text") or data["text"])
    platform_text = format_chapter_for_platform(title, platform_source_text, chapter, abbr)
    royal_road_text = format_chapter_for_platform(title, platform_source_text, chapter, abbr, include_post_note=False)
    royal_road_post_note = enhanced_post_chapter_author_note(abbr, chapter, title, platform_source_text).strip() + "\n"
    if decision in {"royal_road_ready", "update_existing"}:
        (folder / "royal-road.txt").write_text(royal_road_editor_spacing(royal_road_text), encoding="utf-8")
        (folder / "royal-road-post-note.txt").write_text(royal_road_editor_spacing(royal_road_post_note), encoding="utf-8")
    if decision in {"patreon_ready", "blocked", "update_existing"} or not status.get("patreonExists", False):
        (folder / "patreon.txt").write_text(platform_text, encoding="utf-8")
    (folder / "metadata.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")
    remember_chapter_revision(abbr, chapter, data, revision)
    return auto_publish_generated_media(folder, payload)


def write_live_release_check_script(post_folder: Path, metadata: dict[str, Any]) -> Path:
    script = post_folder / "live-release-check.js"
    abbr = str(metadata.get("abbr") or "").upper()
    chapter = int(metadata.get("chapter") or 0)
    title = str(metadata.get("title") or f"Chapter {chapter}")
    expected_text = ""
    try:
        chapter_data = docs_chapter_text(abbr, chapter)
        expected_text = royal_road_editor_spacing(format_chapter_for_platform(
            title,
            str(chapter_data.get("raw_text") or chapter_data.get("text") or ""),
            chapter,
            abbr,
            include_post_note=False,
        ))
    except Exception:
        local_text = post_folder / "royal-road.txt"
        expected_text = local_text.read_text(encoding="utf-8") if local_text.exists() else ""
    payload = {
        "abbr": abbr,
        "chapter": chapter,
        "title": title,
        "expectedText": expected_text,
        "royalRoadUrl": royal_road_url_for_story(abbr),
        "royalRoadSyndicationUrl": royal_road_syndication_url(abbr),
        "patreonUrl": f"{PATREON_URL}/posts",
        "chromeDebugUrl": chrome_debug_url(),
        "profileDir": str((ROOT / ".playwright-profile").resolve()),
        "output": str((post_folder / "live-release-check-result.json").resolve()),
    }
    script.write_text(
        f"""const {{ chromium }} = require('playwright');
const fs = require('fs');
const check = {json.dumps(payload, ensure_ascii=False, indent=2)};

function compact(text) {{
  return String(text || '').replace(/\\s+/g, ' ').trim();
}}

function hasChapter(text, title, chapter) {{
  const lower = compact(text).toLowerCase();
  const titleLower = compact(title).toLowerCase();
  if (lower.includes(`chapter ${{chapter}}`) || lower.includes(`ch. ${{chapter}}`) || lower.includes(`ch ${{chapter}}`)) return true;
  if (titleLower && lower.includes(titleLower.slice(0, 80))) return true;
  const patterns = [
    /(?:chapter|chapters|ch\\.?|chs\\.?)\\s*(\\d+)\\s*[-–—]\\s*(\\d+)/gi,
    /\\b(\\d+)\\s*[-–—]\\s*(\\d+)\\b/g
  ];
  for (const pattern of patterns) {{
    for (const match of lower.matchAll(pattern)) {{
      const start = Number(match[1]);
      const end = Number(match[2]);
      if (Number.isFinite(start) && Number.isFinite(end) && chapter >= Math.min(start, end) && chapter <= Math.max(start, end)) {{
        return true;
      }}
    }}
  }}
  return false;
}}

function stripAuthorNote(text) {{
  return String(text || '')
    .replace(/A note from azure inkblade[\\s\\S]*$/i, '')
    .replace(/✦\\s*Author['’]s Note\\s*✦[\\s\\S]*$/i, '')
    .trim();
}}

function normalizeForCompare(text, title, chapter) {{
  let value = stripAuthorNote(text);
  value = value.replace(new RegExp('^\\\\s*' + String(title || '').replace(/[.*+?^${{}}()|[\\]\\\\]/g, '\\\\$&') + '\\\\s*', 'i'), '');
  value = value.replace(new RegExp('^\\\\s*chapter\\\\s+' + chapter + '[a-z]?\\\\s*[:.\\\\-–—]?\\\\s*', 'i'), '');
  return value
    .toLowerCase()
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/[–—]/g, '-')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\\s+/g, ' ')
    .trim();
}}

function compareChapterText(liveText, expectedText, title, chapter) {{
  const live = normalizeForCompare(liveText, title, chapter);
  const expected = normalizeForCompare(expectedText, title, chapter);
  if (!expected) return {{ status: 'unknown', reason: 'No GitHub chapter text was available for comparison.', score: 0, liveLength: live.length, expectedLength: 0 }};
  if (!live) return {{ status: 'not_found', reason: 'Could not extract online chapter text.', score: 0, liveLength: 0, expectedLength: expected.length }};
  if (live.includes(expected) || expected.includes(live)) {{
    return {{ status: 'same', reason: 'Online chapter text matches the GitHub chapter text after cleanup.', score: 1, liveLength: live.length, expectedLength: expected.length }};
  }}
  const liveWords = live.split(' ').filter(Boolean);
  const expectedWords = expected.split(' ').filter(Boolean);
  const liveCounts = new Map();
  for (const word of liveWords) liveCounts.set(word, (liveCounts.get(word) || 0) + 1);
  let overlap = 0;
  for (const word of expectedWords) {{
    const count = liveCounts.get(word) || 0;
    if (count > 0) {{
      overlap += 1;
      liveCounts.set(word, count - 1);
    }}
  }}
  const score = expectedWords.length ? overlap / expectedWords.length : 0;
  return {{
    status: score >= 0.985 ? 'same' : 'different',
    reason: score >= 0.985 ? 'Online chapter is effectively the same as GitHub.' : 'Online chapter differs from the GitHub chapter text.',
    score,
    liveLength: live.length,
    expectedLength: expected.length,
    liveWords: liveWords.length,
    expectedWords: expectedWords.length,
  }};
}}

async function extractRoyalRoadChapterText(page) {{
  const selectors = [
    '.chapter-content',
    '.chapter-inner',
    '.fiction-chapter',
    '#chapter-content',
    'article',
    '.portlet-body',
    'body'
  ];
  for (const selector of selectors) {{
    try {{
      const locator = page.locator(selector).first();
      if (await locator.count() < 1) continue;
      const text = await locator.innerText({{ timeout: 12000 }});
      if (compact(text).length > 500) return {{ text, selector }};
    }} catch (_) {{}}
  }}
  return {{ text: '', selector: '' }};
}}

async function findRoyalRoadChapterUrl(page, title, chapter) {{
  const titleLower = compact(title).toLowerCase().replace(/^chapter\\s+\\d+[a-z]?\\s*[:\\-–—]?\\s*/i, '');
  const anchors = await page.evaluate(() => [...document.querySelectorAll('a[href*="/chapter/"]')].map(a => ({{
    href: a.href,
    text: (a.innerText || a.textContent || '').trim()
  }})));
  let best = null;
  let bestScore = 0;
  for (const anchor of anchors) {{
    const text = compact(anchor.text).toLowerCase();
    let score = 0;
    if (text.includes(`chapter ${{chapter}}`) || text.includes(`ch. ${{chapter}}`) || text.includes(`ch ${{chapter}}`)) score += 6;
    if (new RegExp(`(^|\\\\D)${{chapter}}($|\\\\D)`).test(text)) score += 2;
    if (titleLower && text.includes(titleLower.slice(0, 45))) score += 5;
    if (hasChapter(text, title, chapter)) score += 3;
    if (score > bestScore) {{
      best = anchor;
      bestScore = score;
    }}
  }}
  return bestScore > 0 && best ? {{ url: best.href, text: best.text, score: bestScore }} : null;
}}

async function findRoyalRoadChapterInDashboard(page, title, chapter, fictionUrl) {{
  const fictionId = (String(fictionUrl || '').match(new RegExp('fiction/([0-9]+)')) || [])[1] || '';
  if (!fictionId) return null;
  for (let pageNumber = 1; pageNumber <= 20; pageNumber += 1) {{
    const url = `https://www.royalroad.com/author-dashboard/chapters/list/${{fictionId}}?page=${{pageNumber}}`;
    try {{
      await page.goto(url, {{ waitUntil: 'domcontentloaded', timeout: 60000 }});
      await page.waitForTimeout(900);
      if (!page.url().includes('/author-dashboard/chapters/list/')) return null;
      const hit = await findRoyalRoadChapterUrl(page, title, chapter);
      if (hit) return {{ ...hit, method: `author chapter list page ${{pageNumber}}` }};
      const hasNext = await page.locator(`a[href*="chapters/list/${{fictionId}}?page=${{pageNumber + 1}}"]`).count().catch(() => 0);
      if (!hasNext) break;
    }} catch (_) {{
      return null;
    }}
  }}
  return null;
}}

async function readPageForChapter(page, title, chapter, label) {{
  let text = '';
  try {{
    text = await page.locator('body').innerText({{ timeout: 15000 }});
    if (hasChapter(text, title, chapter)) return {{ exists: true, method: `${{label}} initial page` }};
  }} catch (_) {{}}
  for (let index = 0; index < 5; index += 1) {{
    try {{
      await page.mouse.wheel(0, 2200);
      await page.waitForTimeout(1200);
      text += '\\n' + await page.locator('body').innerText({{ timeout: 10000 }});
      if (hasChapter(text, title, chapter)) return {{ exists: true, method: `${{label}} scroll ${{index + 1}}` }};
    }} catch (_) {{}}
  }}
  return {{ exists: false, method: `${{label}} visible text`, sampleLength: text.length }};
}}

async function searchPatreon(page, title, chapter) {{
  const terms = [
    `Chapter ${{chapter}}`,
    `Ch. ${{chapter}}`,
    String(chapter),
    compact(title).replace(/^chapter\\s+\\d+\\s*[:\\-–—]?\\s*/i, '').slice(0, 80)
  ].filter(Boolean);
  for (const term of terms) {{
    const selectors = [
      'input[type="search"]',
      'input[placeholder*="Search" i]',
      'input[aria-label*="Search" i]',
      '[contenteditable="true"][aria-label*="Search" i]',
      '[role="searchbox"]'
    ];
    for (const selector of selectors) {{
      const target = page.locator(selector).first();
      try {{
        if (await target.count() < 1) continue;
        await target.click({{ timeout: 3000 }});
        await page.keyboard.press(process.platform === 'darwin' ? 'Meta+A' : 'Control+A');
        await page.keyboard.insertText(term);
        await page.keyboard.press('Enter');
        await page.waitForTimeout(3500);
        const checkResult = await readPageForChapter(page, title, chapter, `patreon search "${{term}}"`);
        if (checkResult.exists) return checkResult;
      }} catch (_) {{}}
    }}
  }}
  return {{ exists: false, method: 'patreon search unavailable or no match' }};
}}

(async () => {{
  let browser = null;
  let ownsContext = false;
  let context = null;
  if (check.chromeDebugUrl) {{
    try {{
      browser = await chromium.connectOverCDP(check.chromeDebugUrl);
      context = browser.contexts()[0] || null;
    }} catch (_) {{}}
  }}
  if (!context) {{
    context = await chromium.launchPersistentContext(check.profileDir, {{
      headless: false,
      viewport: {{ width: 1440, height: 1000 }}
    }});
    ownsContext = true;
  }}
  let rrPage = null;
  let patreonPage = null;
  const result = {{
    checkedAt: new Date().toISOString(),
    abbr: check.abbr,
    chapter: check.chapter,
    title: check.title,
    royalRoad: {{ url: check.royalRoadUrl, exists: false, error: '' }},
    patreon: {{ url: check.patreonUrl, exists: false, error: '' }}
  }};

  if (check.royalRoadUrl) {{
    if (check.royalRoadSyndicationUrl) {{
      try {{
        const response = await fetch(check.royalRoadSyndicationUrl, {{ headers: {{ 'User-Agent': 'AutomationTool/1.0' }} }});
        const rss = await response.text();
        result.royalRoad.syndicationUrl = check.royalRoadSyndicationUrl;
        result.royalRoad.exists = hasChapter(rss, check.title, check.chapter);
      }} catch (error) {{
        result.royalRoad.syndicationError = String(error && error.message || error);
      }}
    }}
    rrPage = await context.newPage();
    try {{
      await rrPage.goto(check.royalRoadUrl, {{ waitUntil: 'domcontentloaded', timeout: 60000 }});
      await rrPage.waitForTimeout(2500);
      const text = await rrPage.locator('body').innerText({{ timeout: 15000 }});
      result.royalRoad.exists = result.royalRoad.exists || hasChapter(text, check.title, check.chapter);
      result.royalRoad.pageTitle = await rrPage.title();
      let chapterHit = await findRoyalRoadChapterUrl(rrPage, check.title, check.chapter);
      if (!chapterHit) {{
        chapterHit = await findRoyalRoadChapterInDashboard(rrPage, check.title, check.chapter, check.royalRoadUrl);
        if (chapterHit) result.royalRoad.lookupMethod = chapterHit.method;
      }}
      if (chapterHit) {{
        result.royalRoad.exists = true;
        result.royalRoad.chapterUrl = chapterHit.url;
        result.royalRoad.chapterLinkText = chapterHit.text;
        result.royalRoad.chapterLinkScore = chapterHit.score;
        await rrPage.goto(chapterHit.url, {{ waitUntil: 'domcontentloaded', timeout: 60000 }});
        await rrPage.waitForTimeout(2500);
        const extracted = await extractRoyalRoadChapterText(rrPage);
        result.royalRoad.contentSelector = extracted.selector;
        result.royalRoad.contentSampleLength = extracted.text.length;
        result.royalRoad.contentCompare = compareChapterText(extracted.text, check.expectedText, check.title, check.chapter);
      }} else if (result.royalRoad.exists) {{
        result.royalRoad.contentCompare = {{
          status: 'unknown',
          reason: 'Chapter appears to exist, but the checker could not find a public chapter link to compare text.',
          score: 0,
        }};
      }} else {{
        result.royalRoad.contentCompare = {{
          status: 'not_found',
          reason: 'Chapter was not found on the public Royal Road fiction page.',
          score: 0,
        }};
      }}
    }} catch (error) {{
      result.royalRoad.error = String(error && error.message || error);
      result.royalRoad.contentCompare = {{
        status: 'unknown',
        reason: result.royalRoad.error,
        score: 0,
      }};
    }}
  }}

  patreonPage = await context.newPage();
  try {{
    await patreonPage.goto(check.patreonUrl, {{ waitUntil: 'domcontentloaded', timeout: 60000 }});
    await patreonPage.waitForTimeout(3500);
    const visible = await readPageForChapter(patreonPage, check.title, check.chapter, 'patreon');
    result.patreon.exists = visible.exists;
    result.patreon.method = visible.method;
    if (!result.patreon.exists) {{
      const searched = await searchPatreon(patreonPage, check.title, check.chapter);
      result.patreon.exists = searched.exists;
      result.patreon.method = searched.method;
    }}
    result.patreon.pageTitle = await patreonPage.title();
  }} catch (error) {{
    result.patreon.error = String(error && error.message || error);
  }}

  fs.writeFileSync(check.output, JSON.stringify(result, null, 2), 'utf8');
  console.log(JSON.stringify(result, null, 2));
  if (rrPage) await rrPage.close().catch(() => {{}});
  if (patreonPage) await patreonPage.close().catch(() => {{}});
  if (ownsContext) await context.close();
  process.exit(0);
}})().catch(error => {{
  fs.writeFileSync(check.output, JSON.stringify({{ error: String(error && error.message || error) }}, null, 2), 'utf8');
  console.error(error);
  process.exit(1);
}});
""",
        encoding="utf-8",
    )
    return script


def live_release_check(folder: str) -> dict[str, Any]:
    post_folder = Path(folder).resolve()
    if not str(post_folder).startswith(str(SOCIAL_OUTPUT_DIR.resolve())):
        raise RuntimeError("Release post folder is not valid.")
    metadata_path = post_folder / "metadata.json"
    if not metadata_path.exists():
        raise RuntimeError("This release pack does not contain metadata.")
    metadata = read_metadata(post_folder)
    script = write_live_release_check_script(post_folder, metadata)
    ready = playwright_available()
    if not ready:
        raise RuntimeError("Playwright is not available. Install or reconnect Playwright before running live checks.")
    node = bundled_node_executable()
    run = subprocess.run(
        [str(node), str(script)],
        cwd=str(post_folder),
        env={**os.environ, "NODE_PATH": str(ROOT / "node_modules"), "PLAYWRIGHT_BROWSERS_PATH": str(ROOT / "ms-playwright")},
        capture_output=True,
        text=True,
        timeout=120,
        check=False,
    )
    result_path = post_folder / "live-release-check-result.json"
    result = json.loads(result_path.read_text(encoding="utf-8")) if result_path.exists() else {}
    if run.returncode != 0 and not result:
        raise RuntimeError((run.stdout + "\n" + run.stderr).strip() or "Live release check failed.")
    abbr = str(metadata.get("abbr") or result.get("abbr") or "").upper()
    chapter = int(metadata.get("chapter") or result.get("chapter") or 0)
    if abbr and chapter:
        update_release_status_from_live(abbr, chapter, result)
        data = docs_chapter_text(abbr, chapter)
        revision = chapter_revision_info(abbr, chapter, data)
        status = release_status_for_chapter(abbr, chapter)
        status["revision"] = {
            "changed": bool(revision.get("changed")),
            "firstSeen": bool(revision.get("firstSeen")),
            "wordCount": revision.get("wordCount", 0),
            "previousHash": revision.get("previousHash", ""),
            "contentHash": revision.get("contentHash", ""),
        }
        refreshed_decision, refreshed_reason = decision_from_status(status, revision)
        metadata["decision"] = refreshed_decision
        metadata["decision_reason"] = refreshed_reason
        metadata["release_status"] = status
        metadata["revision"] = status["revision"]
    metadata["live_release_check"] = result
    metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    return {
        "folder": str(post_folder),
        "script": str(script),
        "result": result,
        "decision": metadata.get("decision", ""),
        "decision_reason": metadata.get("decision_reason", ""),
        "message": "Live check complete. Nothing was posted.",
    }


def make_royal_road_chapter_pack(abbr: str, chapter: int) -> dict[str, Any]:
    abbr = story_key(abbr)
    if not abbr:
        raise RuntimeError("Choose a known novel before building a Royal Road pack.")
    post_folder = SOCIAL_OUTPUT_DIR / f"royal-road-{abbr.lower()}-{chapter}"
    metadata_path = post_folder / "metadata.json"
    metadata = read_metadata(post_folder) if metadata_path.exists() else {}
    try:
        data = docs_chapter_text(abbr, chapter)
        revision = chapter_revision_info(abbr, chapter, data)
        status = release_status_for_chapter(abbr, chapter)
        status["revision"] = {
            "changed": bool(revision.get("changed")),
            "firstSeen": bool(revision.get("firstSeen")),
            "wordCount": revision.get("wordCount", 0),
            "previousHash": revision.get("previousHash", ""),
            "contentHash": revision.get("contentHash", ""),
        }
    except Exception as exc:
        if str(metadata.get("kind") or "") != "royal-road" or not (post_folder / "royal-road.txt").exists():
            raise
        status = release_status_for_chapter(abbr, chapter)
        revision = metadata.get("revision") if isinstance(metadata.get("revision"), dict) else {}
        status["revision"] = {
            "changed": bool(revision.get("changed")),
            "firstSeen": bool(revision.get("firstSeen")),
            "wordCount": revision.get("wordCount", 0),
            "previousHash": revision.get("previousHash", ""),
            "contentHash": revision.get("contentHash", ""),
        }
        decision, reason = decision_from_status(status, status["revision"])
        metadata["decision"] = decision
        metadata["decision_reason"] = reason
        metadata["release_status"] = status
        metadata["revision"] = status["revision"]
        metadata["royalRoadChapterUrl"] = str(status.get("royalRoadChapterUrl") or metadata.get("royalRoadChapterUrl") or "")
        metadata["editExistingRoyalRoadChapter"] = bool(status.get("royalRoadExists") or metadata.get("royalRoadChapterUrl") or decision == "update_existing")
        metadata["folder"] = str(post_folder)
        metadata["royal_road_file"] = str(post_folder / "royal-road.txt")
        metadata["royal_road_post_note_file"] = str(post_folder / "royal-road-post-note.txt")
        metadata["royalRoadAuthorNoteUpgraded"] = True
        metadata["royalRoadAuthorNoteUpgradedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
        metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
        return {
            "applied": True,
            "folder": str(post_folder),
            "decision": decision,
            "reason": reason,
            "status": status,
            "post": metadata,
            "message": f"Royal Road check applied to the current review pack. GitHub text refresh was skipped: {exc}",
        }
    decision, reason = decision_from_status(status, revision)
    title = concise_release_title(data.get("title") or data.get("heading") or "", abbr, chapter)
    folder = post_folder
    reset_generated_folder(folder)
    source_text = str(data.get("raw_text") or data.get("text") or "")
    chapter_text = format_chapter_for_platform(title, source_text, chapter, abbr, include_post_note=False)
    post_note = enhanced_post_chapter_author_note(abbr, chapter, title, source_text).strip() + "\n"
    (folder / "royal-road.txt").write_text(royal_road_editor_spacing(chapter_text), encoding="utf-8")
    (folder / "royal-road-post-note.txt").write_text(royal_road_editor_spacing(post_note), encoding="utf-8")
    payload = {
        "kind": "royal-road",
        "abbr": abbr,
        "novel": NOVEL_NAMES.get(abbr, abbr),
        "chapter": chapter,
        "title": title,
        "decision": decision,
        "decision_reason": reason,
        "release_status": status,
        "revision": status["revision"],
        "royalRoadUrl": royal_road_url_for_story(abbr),
        "royalRoadChapterUrl": str(status.get("royalRoadChapterUrl") or ""),
        "editExistingRoyalRoadChapter": bool(status.get("royalRoadExists") or status.get("royalRoadChapterUrl") or decision == "update_existing"),
        "royalRoadSyndicationUrl": royal_road_syndication_url(abbr),
        "folder": str(folder),
        "royal_road_file": str(folder / "royal-road.txt"),
        "royal_road_post_note_file": str(folder / "royal-road-post-note.txt"),
        "royalRoadAuthorNoteUpgraded": True,
        "royalRoadAuthorNoteUpgradedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    (folder / "metadata.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")
    if payload["editExistingRoyalRoadChapter"]:
        record_recovery_event(
            "royal_road_pack",
            "Chapter already exists online or needs update, so the app prepared the edit workflow instead of create-new.",
            error_type="chapter_exists_online",
            folder=folder,
            abbr=abbr,
            chapter=chapter,
            details={
                "decision": decision,
                "reason": reason,
                "royalRoadChapterUrl": payload.get("royalRoadChapterUrl", ""),
            },
        )
    remember_release_dates(abbr, chapter, status.get("dates", {}) if isinstance(status.get("dates"), dict) else {}, "royal-road-review")
    remember_chapter_revision(abbr, chapter, data, revision)
    return payload


def apply_live_release_check(folder: str) -> dict[str, Any]:
    post_folder = Path(folder).resolve()
    if not str(post_folder).startswith(str(SOCIAL_OUTPUT_DIR.resolve())):
        raise RuntimeError("Release post folder is not valid.")
    metadata_path = post_folder / "metadata.json"
    if not metadata_path.exists():
        raise RuntimeError("This release pack does not contain metadata.")
    metadata = read_metadata(post_folder)
    abbr = str(metadata.get("abbr") or "").upper()
    raw_chapter = metadata.get("chapter")
    if raw_chapter is None or str(raw_chapter).strip() == "":
        raise RuntimeError("This release pack is missing novel/chapter metadata.")
    chapter = int(raw_chapter)
    if not abbr:
        raise RuntimeError("This release pack is missing novel/chapter metadata.")
    live_result = metadata.get("live_release_check") or live_release_check(str(post_folder)).get("result", {})
    if live_result:
        update_release_status_from_live(abbr, chapter, live_result)
    try:
        data = docs_chapter_text(abbr, chapter)
        revision = chapter_revision_info(abbr, chapter, data)
        status = release_status_for_chapter(abbr, chapter)
        status["revision"] = {
            "changed": bool(revision.get("changed")),
            "firstSeen": bool(revision.get("firstSeen")),
            "wordCount": revision.get("wordCount", 0),
            "previousHash": revision.get("previousHash", ""),
            "contentHash": revision.get("contentHash", ""),
        }
    except Exception as exc:
        if str(metadata.get("kind") or "") != "royal-road" or not (post_folder / "royal-road.txt").exists():
            raise
        status = release_status_for_chapter(abbr, chapter)
        revision = metadata.get("revision") if isinstance(metadata.get("revision"), dict) else {}
        status["revision"] = {
            "changed": bool(revision.get("changed")),
            "firstSeen": bool(revision.get("firstSeen")),
            "wordCount": revision.get("wordCount", 0),
            "previousHash": revision.get("previousHash", ""),
            "contentHash": revision.get("contentHash", ""),
        }
        decision, reason = decision_from_status(status, status["revision"])
        metadata["decision"] = decision
        metadata["decision_reason"] = reason
        metadata["release_status"] = status
        metadata["revision"] = status["revision"]
        metadata["royalRoadChapterUrl"] = str(status.get("royalRoadChapterUrl") or metadata.get("royalRoadChapterUrl") or "")
        metadata["editExistingRoyalRoadChapter"] = bool(status.get("royalRoadExists") or metadata.get("royalRoadChapterUrl") or decision == "update_existing")
        metadata["folder"] = str(post_folder)
        metadata["royal_road_file"] = str(post_folder / "royal-road.txt")
        metadata["royal_road_post_note_file"] = str(post_folder / "royal-road-post-note.txt")
        metadata["royalRoadAuthorNoteUpgraded"] = True
        metadata["royalRoadAuthorNoteUpgradedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
        metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
        return {
            "applied": True,
            "decision": decision,
            "reason": reason,
            "status": status,
            "post": metadata,
            "message": f"Royal Road check applied to the current review pack. GitHub text refresh was skipped: {exc}",
        }
    decision, reason = decision_from_status(status, revision)
    if str(metadata.get("kind") or "") == "royal-road":
        rebuilt = make_royal_road_chapter_pack(abbr, chapter)
        return {
            "applied": True,
            "decision": decision,
            "reason": reason,
            "status": status,
            "post": rebuilt,
            "message": "Royal Road check applied and a fresh review pack was created.",
        }
    if decision == "blocked":
        return {
            "applied": False,
            "decision": decision,
            "reason": reason,
            "status": status,
            "message": "Live check applied, but the chapter is still held.",
        }
    rebuilt = make_release_chapter_pack(abbr, chapter, decision, status, data, revision)
    return {
        "applied": True,
        "decision": decision,
        "reason": reason,
        "status": status,
        "post": rebuilt,
        "message": "Live check applied and a fresh release pack was created.",
    }


def royal_road_diff_and_edit(folder: str) -> dict[str, Any]:
    check = live_release_check(folder)
    applied = apply_live_release_check(folder)
    target_folder = str(applied.get("folder") or folder)
    post = applied.get("post") if isinstance(applied.get("post"), dict) else read_metadata(Path(target_folder).resolve())
    rr = check.get("result", {}).get("royalRoad", {}) if isinstance(check.get("result"), dict) else {}
    compare = rr.get("contentCompare", {}) if isinstance(rr, dict) else {}
    status = str(compare.get("status") or "").lower()
    should_open = status in {"different", "missing", "unknown"} or bool(post.get("editExistingRoyalRoadChapter"))
    assist = social_post_preview(target_folder, True) if should_open else None
    return {
        "folder": target_folder,
        "check": check,
        "applied": applied,
        "compare": compare,
        "opened": bool(assist),
        "assist": assist,
        "message": "Royal Road diff complete. Edit draft opened for review." if assist else "Royal Road diff complete. Online text matches GitHub.",
    }


def mark_royal_road_review_complete(folder: str, outcome: str = "saved") -> dict[str, Any]:
    post_folder = Path(folder).resolve()
    if not str(post_folder).startswith(str(SOCIAL_OUTPUT_DIR.resolve())):
        raise RuntimeError("Royal Road review folder is not valid.")
    metadata_path = post_folder / "metadata.json"
    metadata = read_metadata(post_folder)
    if str(metadata.get("kind") or "") != "royal-road":
        raise RuntimeError("This folder is not a Royal Road chapter review.")
    abbr = story_key(str(metadata.get("abbr") or ""))
    chapter = int(metadata.get("chapter") or 0)
    if not abbr or chapter < 0:
        raise RuntimeError("Royal Road review metadata is missing its novel or chapter.")
    normalized_outcome = str(outcome or "saved").strip().lower().replace("-", "_").replace(" ", "_")
    if normalized_outcome not in {"saved", "same", "no_changes", "unchanged"}:
        raise RuntimeError("Royal Road review outcome must be saved or unchanged.")
    reviewed_hash = str((metadata.get("revision") or {}).get("contentHash") or "").strip()
    if not reviewed_hash:
        try:
            data = docs_chapter_text(abbr, chapter)
            reviewed_hash = chapter_revision_hash(str(data.get("text") or data.get("raw_text") or ""))
        except Exception:
            reviewed_hash = ""
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    metadata["royal_road_review"] = {
        "outcome": normalized_outcome,
        "completed_at": now,
        "content_hash": reviewed_hash,
    }
    metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    updates = {
        "royalRoadReviewed": True,
        "royalRoadReviewedAt": now,
        "royalRoadReviewOutcome": normalized_outcome,
        "royalRoadReviewedHash": reviewed_hash,
        "royalRoadFolder": str(post_folder),
        "folders": {"royalRoad": str(post_folder)},
    }
    if normalized_outcome == "saved":
        updates["postedToRoyalRoad"] = True
        updates["royalRoadPostedAt"] = now
    update_chapter_ledger(abbr, chapter, updates)
    progress = advance_completed_chapter(abbr, chapter, "royalRoad")
    clickup_sync = {}
    if normalized_outcome == "saved":
        try:
            clickup_sync = sync_clickup_manual_publish(post_folder, "royal-road", metadata, contentType="chapter-release")
        except Exception as exc:
            record_recovery_event("clickup_publish_sync", f"ClickUp Royal Road sync failed: {exc}", error_type="clickup_publish_sync_failed", folder=post_folder)
            clickup_sync = {"ok": False, "error": str(exc)}
    return {
        "completed": True,
        "abbr": abbr,
        "chapter": chapter,
        "outcome": normalized_outcome,
        "contentHash": reviewed_hash,
        "nextChapter": progress.get("nextChapter", chapter + 1),
        "folder": str(post_folder),
        "clickup": clickup_sync,
    }


def prepare_chapter_release_stage(assignment_key: str, stage: str) -> dict[str, Any]:
    stage = str(stage or "").strip().lower().replace("-", "_")
    if stage not in {"inner_disciple", "path_initiate", "royal_road"}:
        raise RuntimeError("Choose Inner Disciple, Path Initiate, or Royal Road.")
    queue = ensure_chapter_release_queue()
    assignment = next((item for item in queue.get("assignments", []) if str(item.get("key") or "") == str(assignment_key)), None)
    if not assignment:
        raise RuntimeError("Release queue assignment was not found.")
    abbr = story_key(str(assignment.get("abbr") or ""))
    chapter = int(assignment.get("chapter") or 0)
    dates = {
        "innerDiscipleDate": str(assignment.get("innerDiscipleDate") or ""),
        "pathInitiateDate": str(assignment.get("pathInitiateDate") or ""),
        "royalRoadDate": str(assignment.get("royalRoadDate") or ""),
    }
    remember_release_dates(abbr, chapter, dates, "weekday-release-upload")
    data = docs_chapter_text(abbr, chapter)
    if stage in {"inner_disciple", "path_initiate"}:
        status = release_status_for_chapter(abbr, chapter)
        status["dates"] = dates
        pack = make_release_chapter_pack(abbr, chapter, "patreon_ready", {**status, "patreonExists": False}, data)
        folder = Path(str(pack.get("folder") or ""))
        metadata = read_metadata(folder)
        metadata["patreonTierStage"] = stage
        metadata["releaseQueueKey"] = assignment_key
        metadata["release_status"] = {**status, "dates": dates}
        (folder / "metadata.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")
        draft = build_patreon_draft(str(folder), ignore_existing=True, tier_stage_override=stage)
        ledger_updates: dict[str, Any] = {"releaseQueueKey": assignment_key}
        if draft.get("playwright_launched") and not draft.get("skipped"):
            ledger_updates[
                "patreonInnerDiscipleDraftPrepared" if stage == "inner_disciple" else "patreonPathInitiateDraftPrepared"
            ] = True
        else:
            record_recovery_event(
                "chapter_release_prepare",
                draft.get("reason") or draft.get("message") or "Patreon browser helper did not launch.",
                error_type="patreon_helper_not_launched",
                folder=folder,
                abbr=abbr,
                chapter=chapter,
                details={"stage": stage, "draft": draft},
            )
        update_chapter_ledger(abbr, chapter, ledger_updates)
        return {
            "stage": stage,
            "assignment": release_queue_assignment_status(assignment),
            "folder": str(folder),
            "draft": draft,
            "queue": chapter_release_upload_queue_status(),
            "message": f"{NOVEL_NAMES.get(abbr, abbr)} Chapter {chapter} {early_access_label(14 if stage == 'inner_disciple' else 7)} draft prepared for review.",
        }
    pack = make_royal_road_chapter_pack(abbr, chapter)
    folder = str(pack.get("folder") or "")
    preview = social_post_preview(folder, True, ["royal-road"])
    update_chapter_ledger(abbr, chapter, {
        "royalRoadUploadPrepared": True,
        "royalRoadUploadPreparedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "releaseQueueKey": assignment_key,
    })
    return {
        "stage": stage,
        "assignment": release_queue_assignment_status(assignment),
        "folder": folder,
        "preview": preview,
        "queue": chapter_release_upload_queue_status(),
        "message": f"{NOVEL_NAMES.get(abbr, abbr)} Chapter {chapter} Royal Road draft prepared for review.",
    }


def release_stage_folder(abbr: str, chapter: int, stage: str, ledger: dict[str, Any] | None = None) -> Path:
    ledger = ledger or chapter_ledger_entry(abbr, chapter)
    if stage in {"inner_disciple", "path_initiate"}:
        folder_text = str(ledger.get("patreonDraftFolder") or "").strip()
        if folder_text:
            return Path(folder_text).resolve()
        return (SOCIAL_OUTPUT_DIR / f"release-{abbr.lower()}-{chapter}").resolve()
    folder_text = str(ledger.get("royalRoadFolder") or "").strip()
    if folder_text:
        return Path(folder_text).resolve()
    return (SOCIAL_OUTPUT_DIR / f"royal-road-{abbr.lower()}-{chapter}").resolve()


def release_stage_completion_gate(assignment: dict[str, Any], stage: str) -> dict[str, Any]:
    abbr = story_key(str(assignment.get("abbr") or ""))
    chapter = int(assignment.get("chapter") or 0)
    ledger = chapter_ledger_entry(abbr, chapter)
    folder = release_stage_folder(abbr, chapter, stage, ledger)
    errors: list[str] = []
    warnings: list[str] = []
    details: dict[str, Any] = {"folder": str(folder)}
    if not folder.exists():
        errors.append(f"Release folder was not found: {folder}")
        return {"ok": False, "errors": errors, "warnings": warnings, "details": details}
    metadata = read_metadata(folder)
    if stage in {"inner_disciple", "path_initiate"}:
        expected_tier = "Path Initiate" if stage == "path_initiate" else "Inner Disciple"
        draft = metadata.get("patreon_draft") if isinstance(metadata.get("patreon_draft"), dict) else {}
        stage_drafts = metadata.get("patreon_stage_drafts") if isinstance(metadata.get("patreon_stage_drafts"), dict) else {}
        stage_draft = stage_drafts.get(stage) if isinstance(stage_drafts.get(stage), dict) else {}
        if stage_draft:
            draft = stage_draft
        if not draft or draft.get("skipped"):
            errors.append("Patreon draft was not prepared for this stage.")
        if str(draft.get("tier_stage") or metadata.get("patreonTierStage") or "").strip().lower() != stage:
            errors.append(f"Patreon draft stage does not match {stage}.")
        if not str(draft.get("title") or "").strip():
            errors.append("Patreon draft title is missing.")
        text_file = Path(str(draft.get("text_file") or folder / "patreon.txt"))
        if not text_file.exists():
            errors.append("Patreon draft text file is missing.")
        else:
            try:
                if len(text_file.read_text(encoding="utf-8").strip()) < 100:
                    errors.append("Patreon draft text is blank or too short.")
            except OSError as exc:
                errors.append(f"Could not read Patreon draft text: {exc}")
        publish_date = str(draft.get("publish_date") or "").strip()
        if not publish_date:
            errors.append("Patreon publish date is missing.")
        expected_date = str(assignment.get("pathInitiateDate" if stage == "path_initiate" else "innerDiscipleDate") or "")
        if expected_date and publish_date != expected_date:
            errors.append(f"Patreon publish date should be {expected_date}, but draft has {publish_date}.")
        result_path = Path(str(draft.get("playwright_result") or folder / "patreon-draft-result.json"))
        result = read_json_safe(result_path)
        details["playwrightResult"] = str(result_path)
        if not isinstance(result, dict):
            errors.append("Patreon helper has not produced a result yet. Wait for the browser helper to finish, then retry Mark Posted.")
        elif result.get("error"):
            errors.append(f"Patreon helper failed: {result.get('error')}")
        else:
            if stage_draft and isinstance(result.get("results"), list):
                result = next((item for item in result.get("results", []) if str(item.get("stage") or "") == stage), {})
                if not result:
                    errors.append(f"Patreon helper did not produce a result for {stage}.")
                    return {"ok": False, "errors": errors, "warnings": warnings, "details": details}
            verification = result.get("verification") if isinstance(result.get("verification"), dict) else {}
            checks = verification.get("checks") if isinstance(verification.get("checks"), dict) else {}
            title_ok = bool(result.get("titleFilled") or checks.get("title"))
            body_ok = bool(result.get("bodyFilled") or checks.get("body"))
            if not title_ok:
                errors.append("Patreon helper did not confirm the title was filled.")
            if not body_ok:
                errors.append("Patreon helper did not confirm the body was filled.")
            actions = "\n".join(str(item) for item in result.get("audienceActions", []) or [])
            tier_states = checks.get("tierStates") if isinstance(checks.get("tierStates"), dict) else {}
            exact_tier_ok = (
                bool(tier_states)
                and bool(tier_states.get("Inner Disciple")) == (stage == "inner_disciple")
                and bool(tier_states.get("Path Initiate")) == (stage == "path_initiate")
            )
            if not exact_tier_ok and (expected_tier not in actions or "verified" not in actions):
                errors.append(f"Patreon helper did not confirm {expected_tier} was selected.")
            schedule_actions = "\n".join(str(item) for item in result.get("scheduleActions", []) or [])
            if publish_date > iso_today().isoformat() and not checks.get("date") and publish_date not in schedule_actions:
                errors.append("Patreon helper did not confirm the scheduled publish date.")
            media = result.get("mediaResult") if isinstance(result.get("mediaResult"), dict) else {}
            if not (media.get("attached") or checks.get("media")):
                warnings.append("Patreon helper did not confirm an image was attached.")
            if result.get("submitResult") and not bool((result.get("submitResult") or {}).get("verified")):
                errors.append("Patreon helper submitted the form but could not verify the schedule or publish result.")
    else:
        if not ledger.get("royalRoadUploadPrepared"):
            errors.append("Royal Road draft was not prepared yet.")
        body_candidates = [folder / "royal-road.txt", folder / "royal-road-chapter.txt", folder / "chapter.txt", folder / "chapter-content.txt"]
        if not any(path.exists() and path.stat().st_size > 100 for path in body_candidates):
            errors.append("Could not verify a Royal Road chapter text file in the release folder.")
        automation = metadata.get("royal_road_automation") if isinstance(metadata.get("royal_road_automation"), dict) else {}
        result_path = Path(str(automation.get("playwright_result") or folder / "manual-posts-playwright-result.json"))
        details["playwrightResult"] = str(result_path)
        result = read_json_safe(result_path)
        if not isinstance(result, list):
            errors.append("Royal Road helper has not produced a verified result yet.")
        else:
            final = next(
                (
                    item
                    for item in reversed(result)
                    if isinstance(item, dict) and str(item.get("action") or "") == "royal_road_result"
                ),
                {},
            )
            verification = final.get("verification") if isinstance(final.get("verification"), dict) else {}
            submit = final.get("submitResult") if isinstance(final.get("submitResult"), dict) else {}
            if not verification.get("ok"):
                errors.append("Royal Road helper did not verify the exact title, chapter body, author note, date, and editor mode.")
            if not submit.get("verified"):
                errors.append("Royal Road helper did not verify that the chapter was saved or scheduled.")
    return {"ok": not errors, "errors": errors, "warnings": warnings, "details": details}


def check_release_stage_exists_before_post(folder: Path, stage: str, assignment_key: str = "") -> dict[str, Any]:
    metadata = read_metadata(folder)
    abbr = story_key(str(metadata.get("abbr") or ""))
    chapter = int(metadata.get("chapter") or 0)
    if not abbr or chapter <= 0:
        return {"exists": False, "checked": False, "reason": "Missing release metadata."}
    try:
        check = live_release_check(str(folder))
        result = check.get("result") if isinstance(check.get("result"), dict) else {}
    except Exception as exc:
        record_recovery_event(
            "release_exists_check",
            f"Could not check whether the chapter already exists before posting: {exc}",
            error_type="live_check_failed",
            folder=folder,
            abbr=abbr,
            chapter=chapter,
            details={"stage": stage, "assignmentKey": assignment_key},
        )
        return {"exists": False, "checked": False, "error": str(exc)}
    patreon = result.get("patreon") if isinstance(result.get("patreon"), dict) else {}
    royal_road = result.get("royalRoad") if isinstance(result.get("royalRoad"), dict) else {}
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    if stage in {"inner_disciple", "path_initiate"} and patreon.get("exists"):
        updates: dict[str, Any] = {
            "releaseQueueKey": assignment_key,
            "patreonDetectedAt": now,
            "postedToPatreon": True,
        }
        if stage == "inner_disciple":
            updates["patreonInnerDisciplePosted"] = True
            updates["patreonInnerDisciplePostedAt"] = now
        else:
            updates["patreonPathInitiatePosted"] = True
            updates["patreonPathInitiatePostedAt"] = now
        update_chapter_ledger(abbr, chapter, updates)
        release_status = load_release_status()
        entry = dict(release_status.get("chapters", {}).get(f"{abbr}-{chapter}", {}))
        entry["patreonExists"] = True
        if stage == "inner_disciple":
            entry["patreonInnerDisciplePosted"] = True
        else:
            entry["patreonPathInitiatePosted"] = True
        entry["lastExistingCheckBeforePost"] = now
        release_status.setdefault("chapters", {})[f"{abbr}-{chapter}"] = entry
        save_release_status(release_status)
        return {"exists": True, "checked": True, "platform": "patreon", "result": result, "message": "Chapter already exists on Patreon; posting helper was not launched."}
    if stage == "royal_road" and royal_road.get("exists"):
        updates = {
            "releaseQueueKey": assignment_key,
            "royalRoadDetectedAt": now,
            "postedToRoyalRoad": True,
            "royalRoadPostedAt": now,
        }
        if royal_road.get("chapterUrl"):
            updates["royalRoadChapterUrl"] = str(royal_road.get("chapterUrl"))
        update_chapter_ledger(abbr, chapter, updates)
        release_status = load_release_status()
        entry = dict(release_status.get("chapters", {}).get(f"{abbr}-{chapter}", {}))
        entry["royalRoadExists"] = True
        entry["lastExistingCheckBeforePost"] = now
        if royal_road.get("chapterUrl"):
            entry["royalRoadChapterUrl"] = str(royal_road.get("chapterUrl"))
        release_status.setdefault("chapters", {})[f"{abbr}-{chapter}"] = entry
        save_release_status(release_status)
        return {"exists": True, "checked": True, "platform": "royal_road", "result": result, "message": "Chapter already exists on Royal Road; posting helper was not launched."}
    return {"exists": False, "checked": True, "result": result}


def write_chapter_upload_tabs_playwright_script(
    folder: Path,
    payloads: list[dict[str, Any]],
    *,
    result_file: Path | None = None,
    script_file: Path | None = None,
) -> Path:
    script = script_file or (folder / "chapter-upload-tabs-playwright.js")
    result_file = result_file or (folder / "chapter-upload-tabs-result.json")
    script.write_text(
        f"""const fs = require('fs');
const {{ chromium }} = require('playwright');

const payloads = {json.dumps(payloads, ensure_ascii=False, indent=2)};
const resultFile = {json.dumps(str(result_file.resolve()))};
const cdpUrl = {json.dumps(chrome_debug_url())};

function save(results) {{
  fs.writeFileSync(resultFile, JSON.stringify({{ finishedAt: new Date().toISOString(), results }}, null, 2), 'utf8');
}}

async function firstVisible(page, selectors, timeout = 2500) {{
  for (const selector of selectors) {{
    const locator = page.locator(selector).first();
    try {{
      await locator.waitFor({{ state: 'visible', timeout }});
      return locator;
    }} catch (_) {{}}
  }}
  return null;
}}

async function setText(page, locator, text) {{
  await locator.click({{ timeout: 5000 }});
  await page.keyboard.press(process.platform === 'darwin' ? 'Meta+A' : 'Control+A').catch(() => null);
  await page.keyboard.press('Backspace').catch(() => null);
  await page.keyboard.insertText(String(text || ''));
}}

async function clickIfVisible(page, texts) {{
  for (const text of texts) {{
    try {{
      const locator = page.getByText(text, {{ exact: false }}).first();
      await locator.waitFor({{ state: 'visible', timeout: 1800 }});
      await locator.click({{ timeout: 1800 }});
      return true;
    }} catch (_) {{}}
  }}
  return false;
}}

async function setTierSelection(page, tier, shouldSelect) {{
  const control = page.getByRole('menuitemcheckbox').filter({{ hasText: tier }}).first();
  if (!(await control.count().catch(() => 0))) return {{ found: false, verified: false }};
  try {{
    await control.scrollIntoViewIfNeeded().catch(() => null);
    let checked = (await control.getAttribute('aria-checked')) === 'true';
    if (checked !== shouldSelect) {{
      await control.click({{ force: true }});
      await page.waitForTimeout(400);
      checked = (await control.getAttribute('aria-checked')) === 'true';
    }}
    return {{
      found: true,
      verified: checked === shouldSelect,
      finalChecked: checked,
      selector: `menuitemcheckbox:${{tier}}`
    }};
  }} catch (error) {{
    return {{
      found: true,
      verified: false,
      error: String(error.message || error).slice(0, 400),
      selector: `menuitemcheckbox:${{tier}}`
    }};
  }}
}}

async function fillTitle(page, draft) {{
  const target = await firstVisible(page, [
    'input[placeholder*="title" i]',
    'textarea[placeholder*="title" i]',
    '[aria-label*="title" i]',
    '[data-testid*="title" i] input',
    '[data-testid*="title" i] textarea'
  ], 8000);
  if (!target) return false;
  await setText(page, target, draft.title);
  return true;
}}

async function fillBody(page, draft) {{
  const target = await firstVisible(page, [
    '.ProseMirror[contenteditable="true"]',
    '[contenteditable="true"][role="textbox"]',
    '[contenteditable="true"]',
    'textarea[placeholder*="body" i]',
    'textarea[placeholder*="post" i]'
  ], 9000);
  if (!target) return false;
  await setText(page, target, draft.body);
  return true;
}}

async function tryConfigureAudience(page, draft) {{
  const actions = [];
  const accessLevel = (draft.access_level || 'paid').toLowerCase();
  if (accessLevel === 'free') {{
    const free = page.locator('input[type="radio"][value="free"]:visible').first();
    if (await free.count().catch(() => 0)) {{
      await free.check({{ force: true }}).catch(async () => {{
        await free.locator('xpath=ancestor::label[1]').click({{ force: true }});
      }});
      actions.push('selected Free access');
    }} else {{
      const clickedFree = await clickIfVisible(page, ['Free', 'Everyone', 'Public', 'Who can see this post?']);
      actions.push(clickedFree ? 'selected Free access by label' : 'Free access control not found');
    }}
    await page.waitForTimeout(600);
    return actions;
  }}
  const paid = page.locator('input[type="radio"][value="paid"]:visible').first();
  if (await paid.count().catch(() => 0)) {{
    await paid.check({{ force: true }}).catch(async () => {{
      await paid.locator('xpath=ancestor::label[1]').click({{ force: true }});
    }});
    actions.push('selected Paid access');
    await page.waitForTimeout(600);
  }} else {{
    const clickedPaid = await clickIfVisible(page, ['Paid members only', 'Paid patrons only', 'Paid only', 'Select tiers', 'Who can see this post?']);
    actions.push(clickedPaid ? 'selected Paid access by label' : 'Paid access control not found');
    await page.waitForTimeout(600);
  }}
  const desired = new Set(draft.tiers || []);
  const tierAccessToggle = page.locator('input[type="checkbox"][aria-label="Toggle tier selection"]:visible').first();
  if (desired.size > 0) {{
    if (!(await tierAccessToggle.count().catch(() => 0))) {{
      actions.push('missing paid-member tier access toggle');
      return actions;
    }}
    await tierAccessToggle.check({{ force: true }}).catch(() => null);
    await page.waitForTimeout(500);
    if (!(await tierAccessToggle.isChecked().catch(() => false))) {{
      actions.push('failed to enable paid-member tier access');
      return actions;
    }}
    actions.push('verified paid-member tier access enabled');
  }}
  const tierButton = page.getByRole('button', {{ name: 'Select tiers' }}).first();
  if (!(await tierButton.count().catch(() => 0))) {{
    actions.push('missing Select tiers control');
    return actions;
  }}
  if ((await tierButton.getAttribute('aria-expanded').catch(() => 'false')) !== 'true') {{
    await tierButton.click({{ force: true }}).catch(() => null);
    await page.waitForTimeout(500);
  }}
  if ((await tierButton.getAttribute('aria-expanded').catch(() => 'false')) !== 'true') {{
    actions.push('failed to open tier menu');
    return actions;
  }}
  actions.push('opened tier menu');
  for (const tier of ['Inner Disciple', 'Path Initiate']) {{
    const desiredState = desired.has(tier);
    const selected = await setTierSelection(page, tier, desiredState);
    if (selected.found && selected.verified) {{
      actions.push(`verified ${{tier}} ${{desiredState ? 'selected' : 'cleared'}}`);
    }} else if (selected.found) {{
      actions.push(`failed ${{tier}} ${{desiredState ? 'selected' : 'cleared'}} via ${{selected.selector || 'unknown control'}}`);
    }} else if (desiredState) {{
      actions.push(`missing ${{tier}} control`);
    }} else {{
      actions.push(`missing ${{tier}} control to clear`);
    }}
  }}
  await page.keyboard.press('Escape').catch(() => null);
  return actions;
}}

async function tryConfigureSchedule(page, draft) {{
  const actions = [];
  if (!draft.publish_date) return actions;
  const today = new Date();
  const localDate = `${{today.getFullYear()}}-${{String(today.getMonth() + 1).padStart(2, '0')}}-${{String(today.getDate()).padStart(2, '0')}}`;
  if (draft.publish_date <= localDate) {{
    actions.push(`ready to publish today (${{draft.publish_date}})`);
    return actions;
  }}
  const toggle = page.locator('#scheduled-for-toggle').first();
  if (await toggle.count().catch(() => 0)) {{
    if (await toggle.getAttribute('aria-checked') !== 'true') await toggle.click({{ force: true }}).catch(() => null);
    await page.waitForTimeout(500);
  }}
  const dateInput = page.locator('input[type="date"]').first();
  if (await dateInput.count().catch(() => 0)) {{
    await dateInput.fill(draft.publish_date).then(() => actions.push(`set date ${{draft.publish_date}}`)).catch(() => null);
  }}
  const timeInput = page.locator('input[type="time"]').first();
  if (await timeInput.count().catch(() => 0)) {{
    const publishTime = String(draft.publish_time || '09:00');
    await timeInput.fill(publishTime).then(() => actions.push(`set time ${{publishTime}}`)).catch(() => null);
  }}
  return actions;
}}

async function attachMedia(page, draft) {{
  const mediaPath = String(draft.media_path || '');
  if (!mediaPath || !fs.existsSync(mediaPath)) return {{ attached: false, reason: 'media missing', mediaPath }};
  if (draft.edit_url) {{
    const existingMedia = page.locator('button[aria-label*="edit cover image media" i], img[alt*="preview" i], img[alt*="uploaded" i]').first();
    if (await existingMedia.count().catch(() => 0)) {{
      return {{ attached: true, reason: 'existing draft media verified', mediaPath }};
    }}
  }}
  const beforeImages = await page.locator('img').count().catch(() => 0);
  await page.getByRole('button', {{ name: /^Image$/ }}).click({{ timeout: 5000 }}).catch(async () => {{
    await page.getByText('Image', {{ exact: true }}).click({{ timeout: 5000 }}).catch(() => null);
  }});
  await page.waitForTimeout(1000);
  const inputs = page.locator('input[type="file"]');
  const count = await inputs.count().catch(() => 0);
  for (let i = count - 1; i >= 0; i--) {{
    const input = inputs.nth(i);
    const accept = await input.evaluate(el => el.getAttribute('accept') || '').catch(() => '');
    const loweredAccept = String(accept || '').toLowerCase();
    const acceptsImage = !loweredAccept || loweredAccept.includes('image') || loweredAccept.includes('.png') || loweredAccept.includes('.jpg') || loweredAccept.includes('.jpeg') || loweredAccept.includes('.webp');
    if (!acceptsImage) continue;
    try {{
      await input.setInputFiles(mediaPath, {{ timeout: 12000 }});
      await page.waitForTimeout(8000);
      const afterImages = await page.locator('img').count().catch(() => 0);
      return {{ attached: afterImages > beforeImages, mediaPath, index: i, beforeImages, afterImages }};
    }} catch (_) {{}}
  }}
  return {{ attached: false, reason: 'no working image input', inputCount: count }};
}}

async function verifyPatreonDraft(page, draft, row) {{
  const checks = {{}};
  const titleInput = await firstVisible(page, [
    'input[placeholder*="title" i]',
    'textarea[placeholder*="title" i]',
    '[aria-label*="title" i]'
  ], 3000);
  const titleValue = titleInput
    ? await titleInput.inputValue().catch(() => '')
    : '';
  checks.title = String(titleValue || '').trim() === String(draft.title || '').trim();

  const bodyEditor = await firstVisible(page, [
    '.ProseMirror[contenteditable="true"]',
    '[contenteditable="true"][role="textbox"]',
    '[contenteditable="true"]'
  ], 3000);
  const bodyText = bodyEditor
    ? await bodyEditor.innerText().catch(() => '')
    : '';
  const expectedBody = String(draft.body || '').trim();
  checks.body = expectedBody.length > 0 && String(bodyText || '').trim().length >= Math.min(500, Math.floor(expectedBody.length * 0.8));
  checks.media = Boolean(row.mediaResult && row.mediaResult.attached);

  const paid = page.locator('input[type="radio"][value="paid"]:visible').first();
  checks.paidAccess = Boolean(await paid.isChecked().catch(() => false));
  const tierAccessToggle = page.locator('input[type="checkbox"][aria-label="Toggle tier selection"]:visible').first();
  checks.tierAccess = Boolean(await tierAccessToggle.isChecked().catch(() => false));

  const tierButton = page.getByRole('button', {{ name: 'Select tiers' }}).first();
  checks.tierMenu = Boolean(await tierButton.count().catch(() => 0));
  checks.tiers = false;
  if (checks.tierMenu) {{
    if ((await tierButton.getAttribute('aria-expanded').catch(() => 'false')) !== 'true') {{
      await tierButton.click({{ force: true }}).catch(() => null);
      await page.waitForTimeout(400);
    }}
    const desired = new Set(draft.tiers || []);
    let allMatched = true;
    const states = {{}};
    for (const tier of ['Inner Disciple', 'Path Initiate']) {{
      const control = page.getByRole('menuitemcheckbox').filter({{ hasText: tier }}).first();
      if (!(await control.count().catch(() => 0))) {{
        states[tier] = null;
        allMatched = false;
        continue;
      }}
      const checked = (await control.getAttribute('aria-checked')) === 'true';
      states[tier] = checked;
      if (checked !== desired.has(tier)) allMatched = false;
    }}
    checks.tierStates = states;
    checks.tiers = allMatched;
    await page.keyboard.press('Escape').catch(() => null);
    await page.waitForTimeout(250);
  }}

  const today = new Date();
  const localDate = `${{today.getFullYear()}}-${{String(today.getMonth() + 1).padStart(2, '0')}}-${{String(today.getDate()).padStart(2, '0')}}`;
  if (draft.publish_date && draft.publish_date > localDate) {{
    const dateInput = page.locator('input[type="date"]:visible').first();
    const timeInput = page.locator('input[type="time"]:visible').first();
    checks.date = (await dateInput.inputValue().catch(() => '')) === draft.publish_date;
    checks.time = (await timeInput.inputValue().catch(() => '')).slice(0, 5) === String(draft.publish_time || '09:00').slice(0, 5);
    const scheduleAction = page.getByRole('button', {{ name: 'Schedule', exact: true }}).first();
    const taggedPublishAction = page.locator('button[data-tag="make-a-post-action-publish"]:visible').first();
    const publishAction = await taggedPublishAction.count().catch(() => 0)
      ? taggedPublishAction
      : page.getByRole('button', {{ name: /publish now|publish/i }}).first();
    const scheduleReady = Boolean(await scheduleAction.count().catch(() => 0)) && !(await scheduleAction.isDisabled().catch(() => true));
    const publishReady = Boolean(await publishAction.count().catch(() => 0)) && !(await publishAction.isDisabled().catch(() => true));
    checks.action = scheduleReady || publishReady;
    checks.actionName = scheduleReady ? 'Schedule' : 'PublishForSchedule';
  }} else {{
    checks.date = true;
    checks.time = true;
    const action = page.getByRole('button', {{ name: /publish now|publish/i }}).first();
    checks.action = Boolean(await action.count().catch(() => 0)) && !(await action.isDisabled().catch(() => true));
    checks.actionName = 'Publish';
  }}
  const required = ['title', 'body', 'media', 'paidAccess', 'tierAccess', 'tiers', 'date', 'time', 'action'];
  return {{ ok: required.every(key => checks[key] === true), checks, required }};
}}

async function submitPatreonDraft(page, verification) {{
  if (!verification || !verification.ok) return {{ submitted: false, verified: false, reason: 'pre-submit verification failed' }};
  const scheduled = ['Schedule', 'PublishForSchedule'].includes(verification.checks.actionName);
  const name = verification.checks.actionName === 'Schedule' ? 'Schedule' : /publish now|publish/i;
  const taggedPublishAction = page.locator('button[data-tag="make-a-post-action-publish"]:visible').first();
  const publishAction = await taggedPublishAction.count().catch(() => 0)
    ? taggedPublishAction
    : page.getByRole('button', {{ name: /publish now|publish/i }}).first();
  const action = verification.checks.actionName === 'PublishForSchedule'
    ? publishAction
    : page.getByRole('button', {{ name, exact: name === 'Schedule' }}).first();
  if (!(await action.count().catch(() => 0)) || await action.isDisabled().catch(() => true)) {{
    return {{ submitted: false, verified: false, reason: 'final action is unavailable' }};
  }}
  const beforeUrl = page.url();
  await action.click({{ timeout: 10000 }});
  await page.waitForTimeout(1800);
  const confirm = page.getByRole('button', {{ name: scheduled ? 'Schedule' : /publish now|publish/i, exact: scheduled }}).last();
  if (await confirm.count().catch(() => 0)) {{
    const enabled = !(await confirm.isDisabled().catch(() => true));
    if (enabled && (await page.getByRole('dialog').count().catch(() => 0))) {{
      await confirm.click({{ timeout: 10000 }}).catch(() => null);
      await page.waitForTimeout(2500);
    }}
  }}
  const afterUrl = page.url();
  const body = await page.locator('body').innerText().catch(() => '');
  const successText = /scheduled|published|your post is live|post scheduled/i.test(body);
  const leftEditor = !(afterUrl.includes('/edit') || afterUrl.includes('/posts/new'));
  if (successText || leftEditor || afterUrl !== beforeUrl) {{
    const successDialog = page.getByRole('dialog').last();
    if (await successDialog.count().catch(() => 0)) {{
      const dismiss = successDialog.getByRole('button', {{ name: /^(okay|ok|done|close)$/i }}).last();
      if (await dismiss.count().catch(() => 0)) {{
        await dismiss.click({{ timeout: 5000 }}).catch(() => null);
        await page.waitForTimeout(500);
      }}
    }}
  }}
  return {{
    submitted: true,
    verified: Boolean(successText || leftEditor || afterUrl !== beforeUrl),
    beforeUrl,
    afterUrl,
    successText
  }};
}}

function patreonPostId(url) {{
  const match = String(url || '').match(/posts\\/(?:[^/]*-)?(\\d+)(?:\\/edit)?(?:[?#].*)?$/i);
  return match ? match[1] : '';
}}

async function findReusablePatreonPage(context, editUrl) {{
  const targetId = patreonPostId(editUrl);
  if (!targetId) return context.pages().find(candidate => candidate.url() === editUrl) || null;
  const matches = context.pages().filter(candidate => patreonPostId(candidate.url()) === targetId);
  if (!matches.length) return null;
  const page = matches[matches.length - 1];
  for (const duplicate of matches.slice(0, -1)) {{
    await duplicate.close().catch(() => null);
  }}
  await page.reload({{ waitUntil: 'domcontentloaded', timeout: 60000 }}).catch(() => null);
  await page.waitForTimeout(1200);
  return page;
}}

(async () => {{
  if (!cdpUrl) throw new Error('Chrome helper bridge URL is missing.');
  const browser = await chromium.connectOverCDP(cdpUrl);
  const context = browser.contexts()[0] || await browser.newContext({{ viewport: {{ width: 1440, height: 1000 }} }});
  const results = [];
  for (const draft of payloads) {{
    let page = null;
    let createdPage = false;
    if (draft.edit_url) {{
      page = await findReusablePatreonPage(context, draft.edit_url);
    }}
    if (!page) {{
      page = await context.newPage();
      createdPage = true;
    }}
    const row = {{ stage: draft.tier_stage, title: draft.title, publish_date: draft.publish_date, ok: false }};
    try {{
      const targetUrl = draft.edit_url || 'https://www.patreon.com/posts/new';
      if (page.url() !== targetUrl) await page.goto(targetUrl, {{ waitUntil: 'domcontentloaded', timeout: 60000 }});
      await page.waitForTimeout(3000);
      row.titleFilled = await fillTitle(page, draft);
      row.bodyFilled = await fillBody(page, draft);
      row.mediaResult = await attachMedia(page, draft);
      row.audienceActions = await tryConfigureAudience(page, draft);
      row.scheduleActions = await tryConfigureSchedule(page, draft);
      await page.waitForTimeout(1200);
      row.pageUrl = page.url();
      row.verification = await verifyPatreonDraft(page, draft, row);
      if (draft.auto_submit) row.submitResult = await submitPatreonDraft(page, row.verification);
      row.pageUrl = page.url();
      row.ok = Boolean(row.verification && row.verification.ok && (!draft.auto_submit || (row.submitResult && row.submitResult.verified)));
    }} catch (error) {{
      row.error = error.message;
    }}
    results.push(row);
    save(results);
    if (draft.auto_submit && row.ok && createdPage) {{
      await page.close().catch(() => null);
    }}
  }}
  save(results);
  process.exit(0);
}})().catch((error) => {{
  fs.writeFileSync(resultFile, JSON.stringify({{ finishedAt: new Date().toISOString(), error: error.message, stack: error.stack, results: [] }}, null, 2), 'utf8');
  process.exit(1);
}});
""",
        encoding="utf-8",
    )
    return script


def upload_chapter_review_tabs(
    assignment_key: str,
    stages: list[str] | None = None,
    *,
    auto_submit: bool = False,
    result_name: str = "",
    edit_urls: dict[str, str] | None = None,
    launch: bool = True,
) -> dict[str, Any]:
    queue = ensure_chapter_release_queue()
    assignment = next((item for item in queue.get("assignments", []) if str(item.get("key") or "") == str(assignment_key)), None)
    if not assignment:
        raise RuntimeError("Release queue assignment was not found.")
    abbr = story_key(str(assignment.get("abbr") or ""))
    chapter = int(assignment.get("chapter") or 0)
    requested_stages = {
        str(stage or "").strip().lower().replace("-", "_")
        for stage in (stages or ["inner_disciple", "path_initiate", "royal_road"])
    }
    requested_stages &= {"inner_disciple", "path_initiate", "royal_road"}
    if not requested_stages:
        raise RuntimeError("No valid release stages were selected for this chapter.")
    assignment_status = release_queue_assignment_status(assignment)
    dates = {
        "innerDiscipleDate": str(assignment.get("innerDiscipleDate") or ""),
        "pathInitiateDate": str(assignment.get("pathInitiateDate") or ""),
        "royalRoadDate": str(assignment.get("royalRoadDate") or ""),
    }
    data = docs_chapter_text(abbr, chapter)
    status = release_status_for_chapter(abbr, chapter)
    status["dates"] = dates
    pack = make_release_chapter_pack(abbr, chapter, "patreon_ready", {**status, "patreonExists": False}, data)
    folder = Path(str(pack.get("folder") or "")).resolve()
    metadata = read_metadata(folder)
    metadata["releaseQueueKey"] = assignment_key
    metadata["release_status"] = {**status, "dates": dates}
    metadata.setdefault("patreon_stage_drafts", {})
    (folder / "metadata.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")

    patreon_payloads: list[dict[str, Any]] = []
    safe_result_name = re.sub(r"[^A-Za-z0-9_.-]+", "-", str(result_name or "").strip()).strip(".-")
    playwright_result = folder / (safe_result_name or "chapter-upload-tabs-result.json")
    script_file = folder / ((Path(safe_result_name).stem + "-playwright.js") if safe_result_name else "chapter-upload-tabs-playwright.js")
    skipped: list[dict[str, Any]] = []
    held: list[dict[str, Any]] = []
    for stage in ["inner_disciple", "path_initiate"]:
        if stage not in requested_stages:
            continue
        if stage == "inner_disciple" and assignment_status.get("innerPosted"):
            skipped.append({"stage": stage, "reason": "Already marked posted."})
            continue
        if stage == "path_initiate" and assignment_status.get("pathPosted"):
            skipped.append({"stage": stage, "reason": "Already marked posted."})
            continue
        metadata = read_metadata(folder)
        metadata["patreonTierStage"] = stage
        metadata["releaseQueueKey"] = assignment_key
        metadata["release_status"] = {**status, "dates": dates}
        (folder / "metadata.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")
        payload = patreon_draft_payload(str(folder), ignore_existing=True, tier_stage_override=stage)
        payload["id"] = hashlib.sha256(f"{folder}|{stage}|{payload.get('title')}|{time.time()}".encode("utf-8")).hexdigest()[:16]
        payload["tier_stage"] = stage
        payload["auto_submit"] = bool(auto_submit)
        if isinstance(edit_urls, dict) and edit_urls.get(stage):
            payload["edit_url"] = str(edit_urls.get(stage) or "")
        patreon_payloads.append(payload)
        metadata = read_metadata(folder)
        metadata.setdefault("patreon_stage_drafts", {})[stage] = {
            "prepared_at": time.strftime("%Y-%m-%d %H:%M:%S"),
            "draft_id": payload["id"],
            "title": payload["title"],
            "text_file": payload["text_file"],
            "media_path": payload["media_path"],
            "media_name": payload["media_name"],
            "publish_date": payload["publish_date"],
            "path_initiate_date": payload["path_initiate_date"],
            "royal_road_date": payload["royal_road_date"],
            "tier_stage": stage,
            "playwright_result": str(playwright_result),
        }
        (folder / "metadata.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")

    playwright_launched = False
    playwright_script = ""
    if patreon_payloads:
        if not (playwright_available() and chrome_debug_available()[0]):
            held.append({"stage": "patreon", "reason": "Chrome helper or Playwright is not available."})
        else:
            script = write_chapter_upload_tabs_playwright_script(
                folder,
                patreon_payloads,
                result_file=playwright_result,
                script_file=script_file,
            )
            node = bundled_node_executable()
            if launch:
                subprocess.Popen(
                    [str(node), str(script)],
                    cwd=str(folder),
                    env={**os.environ, "NODE_PATH": str(ROOT / "node_modules"), "PLAYWRIGHT_BROWSERS_PATH": str(ROOT / "ms-playwright")},
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                )
                playwright_launched = True
            playwright_script = str(script)
            ledger_updates = {"releaseQueueKey": assignment_key, "patreonDraftFolder": str(folder)}
            if any(item.get("tier_stage") == "inner_disciple" for item in patreon_payloads):
                ledger_updates["patreonInnerDiscipleDraftPrepared"] = True
                ledger_updates["patreonInnerDiscipleDraftPreparedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
            if any(item.get("tier_stage") == "path_initiate" for item in patreon_payloads):
                ledger_updates["patreonPathInitiateDraftPrepared"] = True
                ledger_updates["patreonPathInitiateDraftPreparedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
            update_chapter_ledger(abbr, chapter, ledger_updates)

    rr_preview: dict[str, Any] | None = None
    if "royal_road" in requested_stages:
        if assignment_status.get("royalRoadPosted") and not assignment_status.get("needsRoyalRoadReview"):
            skipped.append({"stage": "royal_road", "reason": "Already marked posted."})
        else:
            rr_pack = make_royal_road_chapter_pack(abbr, chapter)
            rr_folder = Path(str(rr_pack.get("folder") or "")).resolve()
            rr_preview = social_post_preview(str(rr_folder), True, ["royal-road"])
            update_chapter_ledger(abbr, chapter, {
                "royalRoadUploadPrepared": True,
                "royalRoadUploadPreparedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
                "royalRoadFolder": str(rr_folder),
                "releaseQueueKey": assignment_key,
            })
    return {
        "ok": True,
        "assignment": release_queue_assignment_status(assignment),
        "folder": str(folder),
        "patreonTabs": len(patreon_payloads),
        "royalRoadTab": bool(rr_preview),
        "preparedStages": [
            *[str(item.get("tier_stage") or "") for item in patreon_payloads],
            *(["royal_road"] if rr_preview else []),
        ],
        "skipped": skipped,
        "held": held,
        "playwright_launched": playwright_launched,
        "playwright_script": playwright_script,
        "playwright_result": str(playwright_result) if patreon_payloads else "",
        "royalRoad": rr_preview,
        "queue": chapter_release_upload_queue_status(),
        "message": f"Upload Chapter prepared {len(patreon_payloads)} Patreon tab(s) and {'1' if rr_preview else '0'} Royal Road tab(s) for review.",
    }


def prepare_due_chapter_releases() -> dict[str, Any]:
    status = chapter_release_upload_queue_status()
    prepared = []
    errors = []
    patreon_stage_started = False
    for item in status.get("due", []):
        assignment = item.get("assignment") if isinstance(item.get("assignment"), dict) else {}
        stage = str(item.get("stage") or "")
        if stage in {"inner_disciple", "path_initiate"} and patreon_stage_started:
            errors.append({
                "key": assignment.get("key"),
                "stage": stage,
                "error": "Waiting for the first Patreon draft to be reviewed before opening another Patreon editor.",
            })
            continue
        try:
            prepared.append(prepare_chapter_release_stage(str(assignment.get("key") or ""), stage))
            if stage in {"inner_disciple", "path_initiate"}:
                patreon_stage_started = True
        except Exception as exc:
            errors.append({"key": assignment.get("key"), "stage": stage, "error": str(exc)})
    return {
        "prepared": prepared,
        "errors": errors,
        "queue": chapter_release_upload_queue_status(),
        "message": f"Prepared {len(prepared)} due release stage(s). {len(errors)} stage(s) are waiting or need attention. Review each platform before publishing.",
    }


def prepare_next_chapter_release_batch(stage: str = "inner_disciple", limit: int = 5) -> dict[str, Any]:
    stage = str(stage or "inner_disciple").strip().lower().replace("-", "_")
    if stage not in {"inner_disciple", "path_initiate", "royal_road"}:
        raise RuntimeError("Choose Inner Disciple, Path Initiate, or Royal Road.")
    status = chapter_release_upload_queue_status()
    candidates = list((status.get("nextBatches") or {}).get(stage) or [])
    prepared = []
    errors = []
    patreon_stage_started = False
    for assignment in candidates[: max(1, min(10, int(limit or 5)))]:
        if stage in {"inner_disciple", "path_initiate"} and patreon_stage_started:
            errors.append({
                "key": assignment.get("key"),
                "stage": stage,
                "error": "Waiting for the first Patreon draft to be reviewed before opening another Patreon editor.",
            })
            continue
        try:
            prepared.append(prepare_chapter_release_stage(str(assignment.get("key") or ""), stage))
            if stage in {"inner_disciple", "path_initiate"}:
                patreon_stage_started = True
        except Exception as exc:
            errors.append({"key": assignment.get("key"), "stage": stage, "error": str(exc)})
    return {
        "stage": stage,
        "prepared": prepared,
        "errors": errors,
        "queue": chapter_release_upload_queue_status(),
        "message": f"Prepared {len(prepared)} next {stage.replace('_', ' ')} item(s). {len(errors)} item(s) are waiting or need attention.",
    }


def mark_chapter_release_stage_complete(assignment_key: str, stage: str) -> dict[str, Any]:
    stage = str(stage or "").strip().lower().replace("-", "_")
    if stage not in {"inner_disciple", "path_initiate", "royal_road"}:
        raise RuntimeError("Choose Inner Disciple, Path Initiate, or Royal Road.")
    queue = load_chapter_release_queue()
    if not queue.get("assignments"):
        queue = ensure_chapter_release_queue()
    assignment = next((item for item in queue.get("assignments", []) if str(item.get("key") or "") == str(assignment_key)), None)
    if not assignment:
        raise RuntimeError("Release queue assignment was not found.")
    abbr = story_key(str(assignment.get("abbr") or ""))
    chapter = int(assignment.get("chapter") or 0)
    existing_ledger = chapter_ledger_entry(abbr, chapter)
    already_completed = (
        (stage == "inner_disciple" and bool(existing_ledger.get("patreonInnerDisciplePosted") or existing_ledger.get("postedToPatreon")))
        or (stage == "path_initiate" and bool(existing_ledger.get("patreonPathInitiatePosted")))
        or (
            stage == "royal_road"
            and bool(existing_ledger.get("postedToRoyalRoad"))
            and not release_queue_assignment_status(assignment).get("needsRoyalRoadReview")
        )
    )
    if already_completed:
        if stage == "inner_disciple":
            advance_release_upload_path(abbr, chapter, "Confirmed already uploaded to Inner Disciple.")
        return {
            "completed": True,
            "alreadyCompleted": True,
            "stage": stage,
            "assignment": release_queue_assignment_status(assignment),
            "queue": chapter_release_upload_queue_status(refresh=False),
            "message": f"{NOVEL_NAMES.get(abbr, abbr)} Chapter {chapter} was already marked posted.",
        }
    gate = release_stage_completion_gate(assignment, stage)
    if not gate.get("ok"):
        return {
            "completed": False,
            "stage": stage,
            "assignment": release_queue_assignment_status(assignment),
            "queue": chapter_release_upload_queue_status(refresh=False),
            "gate": gate,
            "message": "This release stage is not ready to mark posted yet. Fix the listed draft issues and retry.",
        }
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    updates: dict[str, Any] = {"releaseQueueKey": assignment_key}
    release_status = load_release_status()
    status_entry = dict(release_status.get("chapters", {}).get(f"{abbr}-{chapter}", {}))
    if stage == "inner_disciple":
        updates.update({
            "patreonInnerDisciplePosted": True,
            "patreonInnerDisciplePostedAt": now,
            "postedToPatreon": True,
            "patreonPostedAt": now,
        })
        status_entry["patreonExists"] = True
        status_entry["patreonInnerDisciplePosted"] = True
    elif stage == "path_initiate":
        updates.update({"patreonPathInitiatePosted": True, "patreonPathInitiatePostedAt": now})
        status_entry["patreonPathInitiatePosted"] = True
    else:
        reviewed_hash = ""
        try:
            data = docs_chapter_text(abbr, chapter)
            reviewed_hash = chapter_revision_hash(str(data.get("text") or data.get("raw_text") or ""))
        except Exception:
            reviewed_hash = str(existing_ledger.get("royalRoadReviewedHash") or "")
        updates.update({
            "postedToRoyalRoad": True,
            "royalRoadReviewed": True,
            "royalRoadPostedAt": now,
            "royalRoadReviewedAt": now,
            "royalRoadReviewOutcome": "saved",
            "royalRoadReviewedHash": reviewed_hash,
        })
        status_entry["royalRoadExists"] = True
        release_upload = release_status.setdefault("nextSelections", {}).setdefault("releaseUpload", {})
        upload_entry = release_upload.get(abbr) if isinstance(release_upload.get(abbr), dict) else {}
        upload_entry = {
            **upload_entry,
            "abbr": abbr,
            "novel": NOVEL_NAMES.get(abbr, abbr),
            "lastRoyalRoadChapter": max(int(upload_entry.get("lastRoyalRoadChapter") or 0), chapter),
            "lastRoyalRoadCompletedAt": now,
        }
        release_upload[abbr] = upload_entry
    status_entry["lastReleaseQueueConfirmation"] = now
    release_status.setdefault("chapters", {})[f"{abbr}-{chapter}"] = status_entry
    save_release_status(release_status)
    if stage == "inner_disciple":
        advance_release_upload_path(abbr, chapter)
    update_chapter_ledger(abbr, chapter, updates)
    return {
        "completed": True,
        "alreadyCompleted": False,
        "stage": stage,
        "assignment": release_queue_assignment_status(assignment),
        "queue": chapter_release_upload_queue_status(refresh=False),
        "message": f"{NOVEL_NAMES.get(abbr, abbr)} Chapter {chapter} {stage.replace('_', ' ')} marked posted.",
    }


def reconcile_skipped_release_uploads(apply: bool = False) -> dict[str, Any]:
    queue = ensure_chapter_release_queue()
    assignments = [release_queue_assignment_status(item) for item in queue.get("assignments", []) if isinstance(item, dict)]
    review_needed: list[dict[str, Any]] = []
    suspicious_completed: list[dict[str, Any]] = []
    reopened: list[dict[str, Any]] = []
    stage_specs = [
        ("inner_disciple", "innerPrepared", "innerPosted", "patreonInnerDisciplePosted"),
        ("path_initiate", "pathPrepared", "pathPosted", "patreonPathInitiatePosted"),
        ("royal_road", "royalRoadPrepared", "royalRoadPosted", "postedToRoyalRoad"),
    ]
    for item in assignments:
        abbr = story_key(str(item.get("abbr") or ""))
        chapter = int(item.get("chapter") or 0)
        if not abbr or chapter <= 0:
            continue
        for stage, prepared_key, posted_key, ledger_posted_key in stage_specs:
            if item.get(prepared_key) and not item.get(posted_key):
                review_needed.append({
                    "key": item.get("key"),
                    "stage": stage,
                    "abbr": abbr,
                    "novel": item.get("novel"),
                    "chapter": chapter,
                    "title": item.get("title"),
                    "folder": str(release_stage_folder(abbr, chapter, stage, item.get("ledger") or {})),
                    "reason": "Prepared but not marked posted. Reopen and finish this stage before moving on.",
                })
            if item.get(posted_key):
                release_status = load_release_status()
                status_entry = dict(release_status.get("chapters", {}).get(f"{abbr}-{chapter}", {}))
                if status_entry.get("lastReleaseQueueConfirmation"):
                    continue
                gate = release_stage_completion_gate(item, stage)
                if not gate.get("ok"):
                    suspicious_completed.append({
                        "key": item.get("key"),
                        "stage": stage,
                        "abbr": abbr,
                        "novel": item.get("novel"),
                        "chapter": chapter,
                        "title": item.get("title"),
                        "errors": gate.get("errors", []),
                        "warnings": gate.get("warnings", []),
                        "folder": gate.get("details", {}).get("folder", ""),
                    })
                    if apply:
                        ledger = chapter_ledger_entry(abbr, chapter)
                        updates = {
                            ledger_posted_key: False,
                            "releaseReopenedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
                            "releaseReopenReason": "Reopened by skipped upload reconciliation because completion evidence was missing.",
                        }
                        if stage == "inner_disciple":
                            updates["postedToPatreon"] = False
                        update_chapter_ledger(abbr, chapter, updates)
                        release_status = load_release_status()
                        entry = dict(release_status.get("chapters", {}).get(f"{abbr}-{chapter}", {}))
                        if stage == "inner_disciple":
                            entry["patreonInnerDisciplePosted"] = False
                            entry["patreonExists"] = False
                        elif stage == "path_initiate":
                            entry["patreonPathInitiatePosted"] = False
                        else:
                            entry["royalRoadExists"] = False
                        entry["releaseReopenedAt"] = updates["releaseReopenedAt"]
                        release_status.setdefault("chapters", {})[f"{abbr}-{chapter}"] = entry
                        save_release_status(release_status)
                        reopened.append({"key": item.get("key"), "stage": stage})
    return {
        "ok": True,
        "applied": apply,
        "reviewNeeded": review_needed,
        "suspiciousCompleted": suspicious_completed,
        "reopened": reopened,
        "queue": chapter_release_upload_queue_status(refresh=True),
        "message": f"Found {len(review_needed)} prepared stage(s) still needing review and {len(suspicious_completed)} suspicious completed stage(s).",
    }


def release_stage_posted_flags(stage: str) -> tuple[list[str], list[str]]:
    stage = str(stage or "").strip().lower().replace("-", "_")
    if stage == "inner_disciple":
        return ["patreonInnerDisciplePosted", "postedToPatreon"], ["patreonExists", "patreonInnerDisciplePosted"]
    if stage == "path_initiate":
        return ["patreonPathInitiatePosted"], ["patreonPathInitiatePosted"]
    if stage == "royal_road":
        return ["postedToRoyalRoad", "royalRoadReviewed"], ["royalRoadExists"]
    if stage == "all":
        return (
            ["patreonInnerDisciplePosted", "postedToPatreon", "patreonPathInitiatePosted", "postedToRoyalRoad", "royalRoadReviewed"],
            ["patreonExists", "patreonInnerDisciplePosted", "patreonPathInitiatePosted", "royalRoadExists"],
        )
    raise RuntimeError("Choose Inner Disciple, Path Initiate, Royal Road, or all.")


def reopen_release_chapter_stage(abbr: str, chapter: int | str, stage: str = "all") -> dict[str, Any]:
    abbr = story_key(str(abbr or ""))
    try:
        chapter_number = int(chapter)
    except (TypeError, ValueError):
        chapter_number = 0
    if not abbr or chapter_number <= 0:
        raise RuntimeError("Choose a valid novel and chapter to reopen.")
    stage = str(stage or "all").strip().lower().replace("-", "_")
    ledger_keys, status_keys = release_stage_posted_flags(stage)
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    ledger_updates = {key: False for key in ledger_keys}
    if stage in {"royal_road", "all"}:
        ledger_updates.update({
            "royalRoadReviewOutcome": "reopened",
            "royalRoadReviewedHash": "",
        })
    ledger_updates.update({
        "releaseReopenedAt": now,
        "releaseReopenReason": f"Manually reopened {stage.replace('_', ' ')} from release guardrails.",
    })
    update_chapter_ledger(abbr, chapter_number, ledger_updates)
    release_status = load_release_status()
    entry = dict(release_status.get("chapters", {}).get(f"{abbr}-{chapter_number}", {}))
    for key in status_keys:
        entry[key] = False
    entry["releaseReopenedAt"] = now
    entry["releaseReopenReason"] = ledger_updates["releaseReopenReason"]
    release_status.setdefault("chapters", {})[f"{abbr}-{chapter_number}"] = entry
    save_release_status(release_status)
    current = release_upload_next_chapter(abbr) or 0
    if not current or chapter_number < current:
        next_inner = str(entry.get("innerDiscipleDate") or "")
        set_release_upload_path(
            {abbr: chapter_number},
            reset_queue=True,
            note=f"Reopened {NOVEL_NAMES.get(abbr, abbr)} Chapter {chapter_number}.",
            next_inner_dates={abbr: next_inner} if next_inner else None,
        )
    return {
        "ok": True,
        "abbr": abbr,
        "chapter": chapter_number,
        "stage": stage,
        "queue": chapter_release_upload_queue_status(refresh=True),
        "message": f"{NOVEL_NAMES.get(abbr, abbr)} Chapter {chapter_number} reopened for {stage.replace('_', ' ')} review.",
    }


def release_queue_guardrails(assignments: list[dict[str, Any]], next_by_novel: dict[str, dict[str, Any]]) -> list[dict[str, Any]]:
    assignment_by_key = {str(item.get("key") or ""): item for item in assignments if isinstance(item, dict)}
    guardrails: list[dict[str, Any]] = []
    upload_status = release_upload_path_status()
    for item in upload_status.get("novels", []):
        abbr = story_key(str(item.get("abbr") or ""))
        try:
            expected_chapter = int(item.get("nextChapter") or 0)
        except (TypeError, ValueError):
            expected_chapter = 0
        if not abbr or expected_chapter <= 0:
            guardrails.append({
                "severity": "blocked",
                "abbr": abbr,
                "novel": item.get("novel"),
                "message": f"{item.get('novel') or abbr}: upload path is not set.",
                "action": "Set this novel in the Release Calendar.",
            })
            continue
        key = f"{abbr}-{expected_chapter}"
        assignment = assignment_by_key.get(key)
        actionable = next_by_novel.get(abbr)
        if not assignment:
            ledger = chapter_ledger_entry(abbr, expected_chapter)
            if any(ledger.get(flag) for flag in ["patreonInnerDisciplePosted", "postedToPatreon", "patreonPathInitiatePosted", "postedToRoyalRoad", "royalRoadReviewed"]):
                guardrails.append({
                    "severity": "warning",
                    "abbr": abbr,
                    "chapter": expected_chapter,
                    "novel": item.get("novel"),
                    "message": f"{abbr} Chapter {expected_chapter} is the calendar target but is hidden by posted/reviewed status.",
                    "action": "Reopen it if this was marked complete by mistake.",
                    "canReopen": True,
                    "stage": "all",
                    "posted": {
                        "innerDisciple": bool(ledger.get("patreonInnerDisciplePosted") or ledger.get("postedToPatreon")),
                        "pathInitiate": bool(ledger.get("patreonPathInitiatePosted")),
                        "royalRoad": bool(ledger.get("postedToRoyalRoad") or ledger.get("royalRoadReviewed")),
                    },
                })
            continue
        if actionable and int(actionable.get("chapter") or 0) != expected_chapter:
            guardrails.append({
                "severity": "warning",
                "abbr": abbr,
                "chapter": expected_chapter,
                "novel": item.get("novel"),
                "message": f"{abbr} calendar target is Chapter {expected_chapter}, but the next actionable row is Chapter {actionable.get('chapter')}.",
                "action": "Review posted flags or reopen the calendar target if it still needs work.",
                "canReopen": True,
                "stage": "all",
            })
    return guardrails


def audit_existing_release_alignment(limit: int = 250) -> dict[str, Any]:
    queue = ensure_chapter_release_queue()
    assignments = [item for item in queue.get("assignments", []) if isinstance(item, dict)]
    assignments.sort(key=lambda item: (
        story_key(str(item.get("abbr") or "")),
        int(item.get("chapter") or 0),
    ))
    rows: list[dict[str, Any]] = []
    missing_chapters: list[dict[str, Any]] = []
    summary = {"ok": 0, "warning": 0, "blocked": 0}
    queue_numbers_by_abbr: dict[str, set[int]] = {abbr: set() for abbr in NOVEL_NAMES}
    known_numbers_by_abbr: dict[str, set[int]] = {abbr: set() for abbr in NOVEL_NAMES}
    for item in assignments:
        abbr = story_key(str(item.get("abbr") or ""))
        try:
            chapter = int(item.get("chapter") or 0)
        except (TypeError, ValueError):
            chapter = 0
        if abbr and chapter > 0:
            queue_numbers_by_abbr.setdefault(abbr, set()).add(chapter)
            known_numbers_by_abbr.setdefault(abbr, set()).add(chapter)
    status_data = load_release_status()
    for key, saved in (status_data.get("chapters", {}) or {}).items():
        if not isinstance(saved, dict):
            continue
        abbr = story_key(str(saved.get("abbr") or key.split("-", 1)[0]))
        try:
            chapter = int(saved.get("chapter") or key.rsplit("-", 1)[-1])
        except (TypeError, ValueError):
            continue
        if abbr and chapter > 0:
            known_numbers_by_abbr.setdefault(abbr, set()).add(chapter)
    ledger_data = load_chapter_ledger()
    for key, saved in (ledger_data.get("chapters", {}) or {}).items():
        if not isinstance(saved, dict):
            continue
        abbr = story_key(str(saved.get("abbr") or key.split("-", 1)[0]))
        try:
            chapter = int(saved.get("chapter") or key.rsplit("-", 1)[-1])
        except (TypeError, ValueError):
            continue
        if abbr and chapter > 0:
            known_numbers_by_abbr.setdefault(abbr, set()).add(chapter)
    for abbr, numbers in known_numbers_by_abbr.items():
        if len(numbers) < 2:
            continue
        minimum = min(numbers)
        maximum = max(numbers)
        for chapter in range(minimum, maximum + 1):
            if chapter in numbers:
                continue
            previous_known = chapter - 1 in numbers
            next_known = chapter + 1 in numbers
            if not (previous_known or next_known):
                continue
            missing_chapters.append({
                "abbr": abbr,
                "novel": NOVEL_NAMES.get(abbr, abbr),
                "chapter": chapter,
                "between": f"{chapter - 1} / {chapter + 1}",
                "reason": f"Chapter {chapter - 1 if previous_known else '?'} and/or {chapter + 1 if next_known else '?'} exists in release tracking, but Chapter {chapter} does not.",
                "inQueue": chapter in queue_numbers_by_abbr.get(abbr, set()),
            })
    for item in assignments[: max(1, int(limit or 250))]:
        abbr = story_key(str(item.get("abbr") or ""))
        try:
            chapter = int(item.get("chapter") or 0)
        except (TypeError, ValueError):
            chapter = 0
        if not abbr or chapter <= 0:
            continue
        key = f"{abbr}-{chapter}"
        status = release_status_for_chapter(abbr, chapter)
        ledger = chapter_ledger_entry(abbr, chapter)
        saved = load_release_status().get("chapters", {}).get(key, {})
        issues: list[str] = []
        warnings: list[str] = []
        expected_dates = {
            "innerDiscipleDate": str(item.get("innerDiscipleDate") or ""),
            "pathInitiateDate": str(item.get("pathInitiateDate") or ""),
            "royalRoadDate": str(item.get("royalRoadDate") or ""),
        }
        status_dates = status.get("dates") if isinstance(status.get("dates"), dict) else {}
        for date_key, expected in expected_dates.items():
            actual = str(status_dates.get(date_key) or saved.get(date_key) or "")
            if expected and actual and actual != expected:
                issues.append(f"{date_key} mismatch: queue {expected}, status {actual}")
            elif expected and not actual:
                warnings.append(f"{date_key} is missing from release status.")
        inner_posted = bool(ledger.get("patreonInnerDisciplePosted") or ledger.get("postedToPatreon") or saved.get("patreonInnerDisciplePosted"))
        path_posted = bool(ledger.get("patreonPathInitiatePosted") or saved.get("patreonPathInitiatePosted"))
        rr_posted = bool(ledger.get("postedToRoyalRoad") or saved.get("royalRoadExists") or status.get("royalRoadExists"))
        today = iso_today()
        date_checks = [
            ("Inner Disciple", expected_dates["innerDiscipleDate"], inner_posted),
            ("Path Initiate", expected_dates["pathInitiateDate"], path_posted),
            ("Royal Road", expected_dates["royalRoadDate"], rr_posted),
        ]
        for label, date_text, posted in date_checks:
            if not date_text:
                continue
            try:
                due = datetime.fromisoformat(date_text).date() <= today
            except ValueError:
                issues.append(f"{label} date is invalid: {date_text}")
                continue
            if due and not posted:
                warnings.append(f"{label} is due or past due but not marked posted.")
            if not due and posted:
                warnings.append(f"{label} is marked posted before its scheduled date.")
        if expected_dates["innerDiscipleDate"] and expected_dates["pathInitiateDate"]:
            try:
                if datetime.fromisoformat(expected_dates["pathInitiateDate"]).date() != datetime.fromisoformat(expected_dates["innerDiscipleDate"]).date() + timedelta(days=7):
                    issues.append("Path Initiate date is not 7 days after Inner Disciple.")
            except ValueError:
                pass
        if expected_dates["innerDiscipleDate"] and expected_dates["royalRoadDate"]:
            try:
                if datetime.fromisoformat(expected_dates["royalRoadDate"]).date() != datetime.fromisoformat(expected_dates["innerDiscipleDate"]).date() + timedelta(days=14):
                    issues.append("Royal Road date is not 14 days after Inner Disciple.")
            except ValueError:
                pass
        if issues:
            state = "blocked"
        elif warnings:
            state = "warning"
        else:
            state = "ok"
        summary[state] += 1
        rows.append({
            "key": key,
            "abbr": abbr,
            "novel": NOVEL_NAMES.get(abbr, abbr),
            "chapter": chapter,
            "title": item.get("title") or "",
            "state": state,
            "dates": expected_dates,
            "posted": {
                "innerDisciple": inner_posted,
                "pathInitiate": path_posted,
                "royalRoad": rr_posted,
            },
            "issues": issues,
            "warnings": warnings,
            "source": status.get("source", ""),
        })
    return {
        "ok": summary["blocked"] == 0 and not missing_chapters,
        "generatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        "summary": summary,
        "missingChapters": missing_chapters,
        "rows": rows,
        "queue": chapter_release_upload_queue_status(refresh=False),
        "message": f"Release alignment audit complete: {summary['blocked']} blocked, {summary['warning']} warning, {summary['ok']} ok, {len(missing_chapters)} missing chapter gap(s).",
    }


def mark_release_stage_exists(assignment_key: str, stage: str) -> dict[str, Any]:
    stage = str(stage or "").strip().lower().replace("-", "_")
    if stage not in {"inner_disciple", "path_initiate", "royal_road"}:
        raise RuntimeError("Choose Inner Disciple, Path Initiate, or Royal Road.")
    queue = load_chapter_release_queue()
    if not queue.get("assignments"):
        queue = ensure_chapter_release_queue()
    assignment = next((item for item in queue.get("assignments", []) if str(item.get("key") or "") == str(assignment_key)), None)
    if not assignment:
        raise RuntimeError("Release queue assignment was not found.")
    abbr = story_key(str(assignment.get("abbr") or ""))
    chapter = int(assignment.get("chapter") or 0)
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    updates: dict[str, Any] = {"releaseQueueKey": assignment_key}
    release_status = load_release_status()
    status_entry = dict(release_status.get("chapters", {}).get(f"{abbr}-{chapter}", {}))
    status_entry.update({
        "abbr": abbr,
        "chapter": chapter,
        "innerDiscipleDate": str(assignment.get("innerDiscipleDate") or status_entry.get("innerDiscipleDate") or ""),
        "pathInitiateDate": str(assignment.get("pathInitiateDate") or status_entry.get("pathInitiateDate") or ""),
        "royalRoadDate": str(assignment.get("royalRoadDate") or status_entry.get("royalRoadDate") or ""),
        "lastExistingManualMark": now,
    })
    if stage == "inner_disciple":
        updates.update({
            "postedToPatreon": True,
            "patreonInnerDisciplePosted": True,
            "patreonInnerDisciplePostedAt": now,
            "patreonDetectedAt": now,
        })
        status_entry["patreonExists"] = True
        status_entry["patreonInnerDisciplePosted"] = True
    elif stage == "path_initiate":
        updates.update({
            "patreonPathInitiatePosted": True,
            "patreonPathInitiatePostedAt": now,
        })
        status_entry["patreonExists"] = True
        status_entry["patreonPathInitiatePosted"] = True
    else:
        updates.update({
            "postedToRoyalRoad": True,
            "royalRoadReviewed": True,
            "royalRoadPostedAt": now,
            "royalRoadReviewedAt": now,
            "royalRoadReviewOutcome": "exists_manual",
        })
        status_entry["royalRoadExists"] = True
    release_status.setdefault("chapters", {})[f"{abbr}-{chapter}"] = status_entry
    save_release_status(release_status)
    update_chapter_ledger(abbr, chapter, updates)
    return {
        "ok": True,
        "stage": stage,
        "assignment": release_queue_assignment_status(assignment),
        "queue": chapter_release_upload_queue_status(refresh=True),
        "audit": audit_existing_release_alignment(250),
        "message": f"{NOVEL_NAMES.get(abbr, abbr)} Chapter {chapter} marked existing for {stage.replace('_', ' ')}. The upload calendar was not advanced.",
    }


def rebuild_release_dates_from_assignment(assignment_key: str) -> dict[str, Any]:
    queue = load_chapter_release_queue()
    assignment = next((item for item in queue.get("assignments", []) if str(item.get("key") or "") == str(assignment_key)), None)
    if not assignment:
        raise RuntimeError("Release queue assignment was not found.")
    abbr = story_key(str(assignment.get("abbr") or ""))
    chapter = int(assignment.get("chapter") or 0)
    inner = str(assignment.get("innerDiscipleDate") or "").strip()
    if not abbr or chapter <= 0 or not inner:
        raise RuntimeError("This release row is missing its novel, chapter, or Inner Disciple date.")
    return save_release_upload_calendar([{
        "abbr": abbr,
        "nextChapter": chapter,
        "innerDiscipleDate": inner,
        "pathInitiateDate": str(assignment.get("pathInitiateDate") or ""),
        "royalRoadDate": str(assignment.get("royalRoadDate") or ""),
    }])


def prepare_this_week_chapter_uploads() -> dict[str, Any]:
    audit = audit_existing_release_alignment(250)
    if audit.get("summary", {}).get("blocked", 0):
        return {
            "ok": False,
            "audit": audit,
            "queue": audit.get("queue"),
            "prepared": [],
            "errors": [{"reason": "Resolve blocked date mismatches before preparing this week."}],
            "message": "This week's upload prep is blocked by the Exists / Date Audit.",
        }
    queue = ensure_chapter_release_queue()
    assignments = [release_queue_assignment_status(item) for item in queue.get("assignments", []) if isinstance(item, dict)]
    today = iso_today()
    week_start = today - timedelta(days=today.weekday())
    week_end = week_start + timedelta(days=6)
    stage_specs = [
        ("inner_disciple", "innerDiscipleDate", "innerPosted", "innerPrepared"),
        ("path_initiate", "pathInitiateDate", "pathPosted", "pathPrepared"),
        ("royal_road", "royalRoadDate", "royalRoadPosted", "royalRoadPrepared"),
    ]
    prepared: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    grouped: dict[str, list[dict[str, Any]]] = {stage: [] for stage, *_ in stage_specs}
    patreon_started = False
    for stage, date_key, posted_key, prepared_key in stage_specs:
        due = []
        for item in assignments:
            if item.get(posted_key) or item.get(prepared_key):
                continue
            date_text = str(item.get(date_key) or "")
            if not date_text:
                continue
            try:
                target_date = datetime.fromisoformat(date_text).date()
            except ValueError:
                continue
            if week_start <= target_date <= week_end:
                due.append(item)
        due.sort(key=lambda item: (str(item.get(date_key) or ""), story_key(str(item.get("abbr") or "")), int(item.get("chapter") or 0)))
        for item in due:
            if stage in {"inner_disciple", "path_initiate"} and patreon_started:
                errors.append({
                    "key": item.get("key"),
                    "stage": stage,
                    "reason": "Waiting for the current Patreon helper tab to finish before opening another Patreon draft.",
                })
                continue
            try:
                result = prepare_chapter_release_stage(str(item.get("key") or ""), stage)
                prepared.append(result)
                grouped[stage].append(result.get("assignment") or item)
                if stage in {"inner_disciple", "path_initiate"}:
                    patreon_started = True
            except Exception as exc:
                errors.append({"key": item.get("key"), "stage": stage, "reason": str(exc)})
    return {
        "ok": not errors,
        "weekStart": week_start.isoformat(),
        "weekEnd": week_end.isoformat(),
        "prepared": prepared,
        "grouped": grouped,
        "errors": errors,
        "audit": audit,
        "queue": chapter_release_upload_queue_status(refresh=True),
        "message": f"Prepared {len(prepared)} upload draft(s) for {week_start.isoformat()} through {week_end.isoformat()}. {len(errors)} item(s) need attention.",
    }


def build_master_release_posts(selections: dict[str, Any]) -> dict[str, Any]:
    weekly_rr_counts: dict[str, int] = {}
    posts: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    for abbr in NOVEL_NAMES:
        chapters = parse_chapter_selection(str(selections.get(abbr) or ""))
        for chapter in chapters:
            try:
                status = release_status_for_chapter(abbr, chapter)
                data = docs_chapter_text(abbr, chapter)
                revision = chapter_revision_info(abbr, chapter, data)
                status["revision"] = {
                    "changed": bool(revision.get("changed")),
                    "firstSeen": bool(revision.get("firstSeen")),
                    "wordCount": revision.get("wordCount", 0),
                    "previousHash": revision.get("previousHash", ""),
                    "contentHash": revision.get("contentHash", ""),
                }
                decision, reason = decision_from_status(status, revision)
                if decision == "royal_road_ready":
                    week_key = release_week_key(abbr, chapter)
                    if weekly_rr_counts.get(week_key, 0) >= 4:
                        decision = "blocked"
                        skipped.append({**status, "decision": decision, "reason": "Royal Road cap reached for this week."})
                        continue
                    weekly_rr_counts[week_key] = weekly_rr_counts.get(week_key, 0) + 1
                elif decision == "blocked":
                    skipped.append({**status, "decision": decision, "reason": reason})
                    continue
                posts.append(make_release_chapter_pack(abbr, chapter, decision, status, data, revision))
            except Exception as exc:
                errors.append({"abbr": abbr, "chapter": chapter, "error": str(exc)})
    return {
        "posts": posts,
        "skipped": skipped,
        "errors": errors,
        "royalRoadWeeklyCounts": weekly_rr_counts,
        "createdAt": time.strftime("%Y-%m-%d %H:%M:%S"),
    }


def openai_request(path: str, payload: dict[str, Any]) -> dict[str, Any]:
    if not EXTERNAL_AI_ENABLED:
        raise RuntimeError("External AI disabled (ENABLE_EXTERNAL_AI not set); using local/fallback path.")
    key = os.environ.get("OPENAI_API_KEY")
    if not key:
        raise RuntimeError("OPENAI_API_KEY is not configured.")
    data = json.dumps(payload).encode("utf-8")
    request = urllib.request.Request(
        f"https://api.openai.com/v1/{path}",
        data=data,
        headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=120) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        detail = ""
        try:
            raw = exc.read().decode("utf-8", errors="replace")
            parsed = json.loads(raw) if raw else {}
            if isinstance(parsed, dict):
                error = parsed.get("error") if isinstance(parsed.get("error"), dict) else parsed
                detail = str(error.get("message") or raw)
            else:
                detail = raw
        except Exception:
            detail = str(exc)
        raise RuntimeError(f"OpenAI {path} failed HTTP {exc.code}: {detail}") from exc


def form_request(url: str, payload: dict[str, Any]) -> dict[str, Any]:
    data = urllib.parse.urlencode(payload).encode("utf-8")
    request = urllib.request.Request(url, data=data, method="POST")
    with urllib.request.urlopen(request, timeout=120) as response:
        return json.loads(response.read().decode("utf-8"))


def graph_get(path: str, params: dict[str, str]) -> dict[str, Any]:
    query = urllib.parse.urlencode(params)
    url = f"https://graph.facebook.com/{META_GRAPH_API_VERSION}/{path}?{query}"
    request = urllib.request.Request(url, method="GET")
    with urllib.request.urlopen(request, timeout=120) as response:
        return json.loads(response.read().decode("utf-8"))


def bearer_json_request(url: str, token: str, payload: dict[str, Any]) -> dict[str, Any]:
    data = json.dumps(payload).encode("utf-8")
    request = urllib.request.Request(
        url,
        data=data,
        headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=120) as response:
        return json.loads(response.read().decode("utf-8"))


def buffer_graphql(*args, **kwargs):
    return buffer_publish.buffer_graphql(*args, **kwargs)
def buffer_connection_diagnostics() -> dict[str, Any]:
    key_saved = bool(os.environ.get("BUFFER_API_KEY", "").strip())
    diagnostics: dict[str, Any] = {
        "keySaved": key_saved,
        "networkReachable": False,
        "authenticated": False,
        "channelCount": 0,
        "channels": [],
    }
    if not key_saved:
        diagnostics["error"] = "No Buffer API key is saved."
        return diagnostics
    try:
        account = buffer_graphql(
            """
            query Account {
              account { id email organizations { id name } }
            }
            """
        )
        diagnostics["networkReachable"] = True
        diagnostics["authenticated"] = True
        diagnostics["account"] = account.get("data", {}).get("account", {})
        try:
            channels = buffer_channels().get("channels", [])
        except Exception as exc:
            diagnostics["channelLookupError"] = str(exc)
            channels = configured_buffer_channels()
        if not channels:
            saved_channels = configured_buffer_channels()
            if saved_channels:
                diagnostics["channelLookupFallback"] = "saved"
                channels = saved_channels
        diagnostics["channels"] = channels
        diagnostics["channelCount"] = len(channels)
        return diagnostics
    except urllib.error.HTTPError as exc:
        diagnostics["networkReachable"] = True
        diagnostics["errorType"] = "http"
        diagnostics["status"] = exc.code
        diagnostics["error"] = exc.read().decode("utf-8", errors="replace")
        if diagnostics.get("authenticated"):
            channels = configured_buffer_channels()
            diagnostics["channels"] = channels
            diagnostics["channelCount"] = len(channels)
            diagnostics["channelLookupFallback"] = "saved"
        return diagnostics
    except urllib.error.URLError as exc:
        diagnostics["errorType"] = "network"
        diagnostics["error"] = str(exc)
        if diagnostics.get("authenticated"):
            channels = configured_buffer_channels()
            diagnostics["channels"] = channels
            diagnostics["channelCount"] = len(channels)
            diagnostics["channelLookupFallback"] = "saved"
        return diagnostics
    except Exception as exc:
        diagnostics["networkReachable"] = True
        diagnostics["errorType"] = "application"
        diagnostics["error"] = str(exc)
        return diagnostics


def powershell_buffer_test() -> dict[str, Any]:
    key = os.environ.get("BUFFER_API_KEY", "").strip()
    if not key:
        return {"keySaved": False, "error": "No Buffer API key is saved."}
    query = '{ "query": "query Account { account { id email organizations { id name } } }" }'
    ps = f"""
$Headers = @{{ Authorization = 'Bearer {key}'; 'Content-Type' = 'application/json' }}
$Body = @'
{query}
'@
try {{
  $Result = Invoke-RestMethod -Uri 'https://api.buffer.com' -Method Post -Headers $Headers -Body $Body
  $Result | ConvertTo-Json -Depth 20
}} catch {{
  $_.Exception.Message
  if ($_.ErrorDetails) {{ $_.ErrorDetails.Message }}
  exit 1
}}
"""
    run = subprocess.run(["powershell", "-NoProfile", "-Command", ps], capture_output=True, text=True, timeout=120)
    if run.returncode != 0:
        return {"keySaved": True, "networkReachable": False, "authenticated": False, "error": (run.stdout + run.stderr).strip()}
    try:
        payload = json.loads(run.stdout)
    except Exception:
        return {"keySaved": True, "networkReachable": True, "authenticated": False, "raw": run.stdout}
    if payload.get("errors"):
        return {"keySaved": True, "networkReachable": True, "authenticated": False, "error": payload["errors"]}
    return {"keySaved": True, "networkReachable": True, "authenticated": True, "account": payload.get("data", {}).get("account", {})}


def buffer_channels() -> dict[str, Any]:
    account = buffer_graphql(
        """
        query Account {
          account {
            id
            organizations { id name }
          }
        }
        """
    )
    orgs = account.get("data", {}).get("account", {}).get("organizations", [])
    channels: list[dict[str, Any]] = []
    for org in orgs:
        result = buffer_graphql(
            """
            query Channels($organizationId: OrganizationId!) {
              channels(input: { organizationId: $organizationId }) {
                id
                name
                service
              }
            }
            """,
            {"organizationId": org["id"]},
        )
        for channel in result.get("data", {}).get("channels", []):
            channel["organizationId"] = org["id"]
            channel["organizationName"] = org.get("name", "")
            channels.append(channel)
    return {"organizations": orgs, "channels": channels}


