def github_commit_media_url_for_file(path: Path) -> str:
    metadata_path = path.resolve().parent / "metadata.json"
    if not metadata_path.exists():
        return ""
    metadata = read_json_safe(metadata_path)
    if not isinstance(metadata, dict):
        return ""
    repo_path = f"media/{media_key_for_generated_file(path)}"
    publishes = metadata.get("buffer_media_publishes") if isinstance(metadata.get("buffer_media_publishes"), list) else []
    for publish in reversed(publishes):
        uploaded = publish.get("uploaded") if isinstance(publish, dict) and isinstance(publish.get("uploaded"), list) else []
        for item in reversed(uploaded):
            if str(item.get("path") or "") != repo_path or not item.get("commit"):
                continue
            owner, repo = github_media_repo_parts()
            encoded_path = urllib.parse.quote(repo_path, safe="/")
            return f"https://raw.githubusercontent.com/{owner}/{repo}/{item['commit']}/{encoded_path}"
    return ""


def published_public_url_for_file(path: Path) -> str:
    metadata_path = path.resolve().parent / "metadata.json"
    if not metadata_path.exists():
        return ""
    metadata = read_json_safe(metadata_path)
    if not isinstance(metadata, dict):
        return ""
    candidates = [
        metadata.get("cloudflare_r2_uploads"),
        metadata.get("buffer_media_publishes"),
        metadata.get("github_media_publish"),
        metadata.get("github_media_git_publishes"),
    ]
    path_key = media_key_for_generated_file(path)
    path_names = {str(path.resolve()).lower(), path.name.lower()}
    for group in candidates:
        groups = group if isinstance(group, list) else [group]
        for entry in reversed([item for item in groups if isinstance(item, dict)]):
            files = entry.get("files") or entry.get("uploaded") or entry.get("copied") or []
            if not isinstance(files, list):
                continue
            for item in reversed([file for file in files if isinstance(file, dict)]):
                item_path = str(item.get("source") or item.get("path") or item.get("repo_path") or "").strip()
                item_key = str(item.get("key") or "").strip()
                item_url = str(item.get("url") or "").strip()
                if not item_url:
                    continue
                if item_key == path_key or item_path.lower() in path_names or Path(item_path).name.lower() == path.name.lower():
                    return item_url
    return ""


def public_url_for_generated_file(path: Path) -> str | None:
    media_roots = [
        SOCIAL_OUTPUT_DIR.resolve(),
        TIKTOK_OUTPUT_DIR.resolve(),
        EXPERIMENT_OUTPUT_DIR.resolve(),
        OUTPUT_DIR.resolve(),
        YOUTUBE_OUTPUT_DIR.resolve(),
        CHAPTER_OUTPUT_DIR.resolve(),
    ]
    published_url = published_public_url_for_file(path)
    if published_url:
        return published_url
    if github_auto_publish_media():
        resolved = path.resolve()
        if any(str(resolved).startswith(str(root)) for root in media_roots):
            return github_commit_media_url_for_file(path) or github_media_url_for_key(media_key_for_generated_file(path))
    base = ""
    if not base:
        base = normalize_public_base_url(os.environ.get("BUFFER_PUBLIC_BASE_URL", ""))
    if not base:
        base = normalize_public_base_url(os.environ.get("CLOUDFLARE_R2_PUBLIC_BASE_URL", ""))
    if not base:
        base = normalize_public_base_url(os.environ.get("INSTAGRAM_PUBLIC_BASE_URL", ""))
    if not base:
        base = github_pages_media_base_url()
    if not base:
        return None
    resolved = path.resolve()
    for root in media_roots:
        if str(resolved).startswith(str(root)):
            relative = resolved.relative_to(root).as_posix()
            return f"{base}/{urllib.parse.quote(relative, safe='/')}"
    return None


def github_public_media_base_url() -> str:
    return normalize_public_base_url(
        os.environ.get(
            "GITHUB_PUBLIC_MEDIA_BASE_URL",
            os.environ.get("GITHUB_PAGES_MEDIA_BASE_URL", DEFAULT_GITHUB_PUBLIC_MEDIA_BASE_URL),
        )
    )


def github_pages_media_base_url() -> str:
    return github_public_media_base_url()


def github_auto_publish_media() -> bool:
    value = os.environ.get("GITHUB_AUTO_PUBLISH_MEDIA", "1").strip().lower()
    return value not in {"0", "false", "no", "off"}


def auto_render_videos() -> bool:
    value = os.environ.get("AUTO_RENDER_VIDEOS", "1").strip().lower()
    return value not in {"0", "false", "no", "off"}


def media_key_for_generated_file(path: Path) -> str:
    resolved = path.resolve()
    for root_name, root in [
        ("social-posts", SOCIAL_OUTPUT_DIR.resolve()),
        ("tiktok-posts", TIKTOK_OUTPUT_DIR.resolve()),
        ("experiment-post-packs", EXPERIMENT_OUTPUT_DIR.resolve()),
        ("campaigns", OUTPUT_DIR.resolve()),
        ("youtube-videos", YOUTUBE_OUTPUT_DIR.resolve()),
        ("chapters", CHAPTER_OUTPUT_DIR.resolve()),
    ]:
        if str(resolved).startswith(str(root)):
            return f"{root_name}/{resolved.relative_to(root).as_posix()}"
    return f"uploads/{path.name}"


def github_media_url_for_key(key: str) -> str:
    base = github_public_media_base_url().rstrip("/")
    return f"{base}/{urllib.parse.quote(key, safe='/')}"


def github_repo_parts() -> tuple[str, str]:
    remote = os.environ.get("GITHUB_REMOTE_URL", GITHUB_REMOTE_URL).strip() or GITHUB_REMOTE_URL
    remote = remote.removesuffix(".git").rstrip("/")
    match = re.search(r"github\.com[:/](?P<owner>[^/]+)/(?P<repo>[^/]+)$", remote)
    if not match:
        raise RuntimeError("GITHUB_REMOTE_URL must point to a GitHub repository.")
    return match.group("owner"), match.group("repo")


def github_media_repo_parts() -> tuple[str, str]:
    remote = os.environ.get("GITHUB_MEDIA_REMOTE_URL", GITHUB_MEDIA_REMOTE_URL).strip() or GITHUB_MEDIA_REMOTE_URL
    remote = remote.removesuffix(".git").rstrip("/")
    match = re.search(r"github\.com[:/](?P<owner>[^/]+)/(?P<repo>[^/]+)$", remote)
    if not match:
        raise RuntimeError("GITHUB_MEDIA_REMOTE_URL must point to a GitHub repository.")
    return match.group("owner"), match.group("repo")


def github_api_request(method: str, path: str, payload: dict[str, Any] | None = None) -> dict[str, Any]:
    token = os.environ.get("GITHUB_TOKEN", "").strip()
    if not token:
        raise RuntimeError("Save a GitHub token in Connections first.")
    data = json.dumps(payload).encode("utf-8") if payload is not None else None
    request = urllib.request.Request(
        f"https://api.github.com{path}",
        data=data,
        headers={
            "Authorization": f"Bearer {token}",
            "Accept": "application/vnd.github+json",
            "Content-Type": "application/json",
            "User-Agent": "AutomationTool/1.0",
            "X-GitHub-Api-Version": "2022-11-28",
        },
        method=method,
    )
    try:
        with urllib.request.urlopen(request, timeout=180) as response:
            body = response.read().decode("utf-8")
            return json.loads(body) if body else {}
    except urllib.error.HTTPError as exc:
        if exc.code == 404:
            if "/contents/" in path:
                raise FileNotFoundError(path) from exc
            if path.startswith("/repos/"):
                raise RuntimeError(
                    "GitHub could not see the configured repository. "
                    "For a private repo, edit the saved fine-grained token so it has access to that repository "
                    "and Contents read/write permission."
                ) from exc
            raise FileNotFoundError(path) from exc
        detail = exc.read().decode("utf-8", errors="replace")
        raise GitHubApiError(method, path, exc.code, detail) from exc


def github_existing_sha(owner: str, repo: str, path: str, branch: str) -> str | None:
    encoded_path = urllib.parse.quote(path, safe="/")
    try:
        data = github_api_request("GET", f"/repos/{owner}/{repo}/contents/{encoded_path}?ref={urllib.parse.quote(branch)}")
    except FileNotFoundError:
        return None
    return str(data.get("sha") or "") or None


def upload_bytes_to_github(
    content: bytes,
    repo_path: str,
    message: str,
    *,
    owner: str,
    repo: str,
    branch: str | None = None,
) -> dict[str, Any]:
    branch = branch or os.environ.get("GITHUB_BRANCH", "main").strip() or "main"
    sha = github_existing_sha(owner, repo, repo_path, branch)
    payload: dict[str, Any] = {
        "message": message,
        "content": base64.b64encode(content).decode("ascii"),
        "branch": branch,
    }
    if sha:
        payload["sha"] = sha
    encoded_path = urllib.parse.quote(repo_path, safe="/")
    recovered_from_conflict = False
    for attempt in range(3):
        try:
            result = github_api_request("PUT", f"/repos/{owner}/{repo}/contents/{encoded_path}", payload)
            break
        except GitHubApiError as exc:
            if exc.status != 409 or attempt >= 2:
                raise
            recovered_from_conflict = True
            record_recovery_event(
                "github_upload",
                f"GitHub content conflict while uploading {repo_path}; refreshing remote version and retrying.",
                error_type="github_conflict",
                details={"owner": owner, "repo": repo, "path": repo_path, "branch": branch, "attempt": attempt + 1},
            )
            latest_sha = github_existing_sha(owner, repo, repo_path, branch)
            if latest_sha:
                payload["sha"] = latest_sha
            else:
                payload.pop("sha", None)
            time.sleep(0.75 + attempt)
    else:
        raise RuntimeError(f"GitHub upload failed for {repo_path}.")
    return {
        "path": repo_path,
        "sha": result.get("content", {}).get("sha", ""),
        "commit": result.get("commit", {}).get("sha", ""),
        "html_url": result.get("content", {}).get("html_url", ""),
        "recovered_from_conflict": recovered_from_conflict or bool(sha and payload.get("sha") != sha),
    }


def upload_file_to_github(path: Path, repo_path: str, message: str, *, media_repo: bool = False) -> dict[str, Any]:
    owner, repo = github_media_repo_parts() if media_repo else github_repo_parts()
    branch = os.environ.get("GITHUB_BRANCH", "main").strip() or "main"
    return upload_bytes_to_github(path.read_bytes(), repo_path, message, owner=owner, repo=repo, branch=branch)


def publish_folder_media_to_github_api(folder: str) -> dict[str, Any]:
    copied = copy_folder_media_to_github(folder)
    uploaded = []
    r2_uploaded = []
    skipped_large = []
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    nojekyll = ROOT / "docs" / ".nojekyll"
    nojekyll.parent.mkdir(parents=True, exist_ok=True)
    nojekyll.touch(exist_ok=True)
    for item in copied.get("copied", []):
        local_path = Path(item["repo_path"])
        source_path = Path(str(item.get("source") or local_path))
        file_size = source_path.stat().st_size if source_path.exists() else local_path.stat().st_size
        if file_size > GITHUB_CONTENT_API_SAFE_LIMIT_BYTES:
            if r2_configured():
                r2_item = upload_file_to_r2(source_path if source_path.exists() else local_path)
                item["url"] = r2_item["url"]
                item["large_media_provider"] = "cloudflare-r2"
                item["size"] = str(file_size)
                r2_uploaded.append(r2_item)
                continue
            skipped_large.append(
                {
                    "path": str(source_path if source_path.exists() else local_path),
                    "repo_path": f"media/{item['key']}",
                    "size": file_size,
                    "reason": "File is too large for the GitHub Contents API and Cloudflare R2 is not configured.",
                }
            )
            continue
        uploaded.append(
            upload_file_to_github(
                local_path,
                f"media/{item['key']}",
                f"Publish automation media {timestamp}",
                media_repo=True,
            )
        )
    if skipped_large:
        raise RuntimeError(
            "Large media needs Cloudflare R2 or a local git push path before Buffer can use it: "
            + "; ".join(f"{Path(item['path']).name} ({int(item['size']) // (1024 * 1024)} MB)" for item in skipped_large)
        )
    copied["copied"] = copied.get("copied", [])
    return {
        **copied,
        "published": True,
        "method": "github-api+r2-large-media" if r2_uploaded else "github-api",
        "uploaded": uploaded,
        "r2_uploaded": r2_uploaded,
    }


def r2_configured() -> bool:
    required = [
        "CLOUDFLARE_R2_ACCOUNT_ID",
        "CLOUDFLARE_R2_ACCESS_KEY_ID",
        "CLOUDFLARE_R2_SECRET_ACCESS_KEY",
        "CLOUDFLARE_R2_BUCKET",
        "CLOUDFLARE_R2_PUBLIC_BASE_URL",
    ]
    return all(os.environ.get(key, "").strip() for key in required)


def signing_key(secret: str, date_stamp: str, region: str = "auto", service: str = "s3") -> bytes:
    key = ("AWS4" + secret).encode("utf-8")
    date_key = hmac.new(key, date_stamp.encode("utf-8"), hashlib.sha256).digest()
    region_key = hmac.new(date_key, region.encode("utf-8"), hashlib.sha256).digest()
    service_key = hmac.new(region_key, service.encode("utf-8"), hashlib.sha256).digest()
    return hmac.new(service_key, b"aws4_request", hashlib.sha256).digest()


def r2_object_key(path: Path) -> str:
    return media_key_for_generated_file(path)


def r2_public_url_for_key(key: str) -> str:
    base = normalize_public_base_url(os.environ["CLOUDFLARE_R2_PUBLIC_BASE_URL"])
    return f"{base}/{urllib.parse.quote(key, safe='/')}"


def upload_file_to_r2(path: Path) -> dict[str, str]:
    if not r2_configured():
        raise RuntimeError("Cloudflare R2 is not configured in Connections.")
    account_id = os.environ["CLOUDFLARE_R2_ACCOUNT_ID"].strip()
    access_key = os.environ["CLOUDFLARE_R2_ACCESS_KEY_ID"].strip()
    secret_key = os.environ["CLOUDFLARE_R2_SECRET_ACCESS_KEY"].strip()
    bucket = os.environ["CLOUDFLARE_R2_BUCKET"].strip()
    key = r2_object_key(path)
    body = path.read_bytes()
    payload_hash = hashlib.sha256(body).hexdigest()
    now = datetime.utcnow()
    amz_date = now.strftime("%Y%m%dT%H%M%SZ")
    date_stamp = now.strftime("%Y%m%d")
    host = f"{account_id}.r2.cloudflarestorage.com"
    encoded_key = urllib.parse.quote(key, safe="/")
    canonical_uri = f"/{bucket}/{encoded_key}"
    content_type = mimetypes.guess_type(path.name)[0] or "application/octet-stream"
    canonical_headers = (
        f"content-type:{content_type}\n"
        f"host:{host}\n"
        f"x-amz-content-sha256:{payload_hash}\n"
        f"x-amz-date:{amz_date}\n"
    )
    signed_headers = "content-type;host;x-amz-content-sha256;x-amz-date"
    canonical_request = "\n".join(
        ["PUT", canonical_uri, "", canonical_headers, signed_headers, payload_hash]
    )
    credential_scope = f"{date_stamp}/auto/s3/aws4_request"
    string_to_sign = "\n".join(
        [
            "AWS4-HMAC-SHA256",
            amz_date,
            credential_scope,
            hashlib.sha256(canonical_request.encode("utf-8")).hexdigest(),
        ]
    )
    signature = hmac.new(signing_key(secret_key, date_stamp), string_to_sign.encode("utf-8"), hashlib.sha256).hexdigest()
    authorization = (
        f"AWS4-HMAC-SHA256 Credential={access_key}/{credential_scope}, "
        f"SignedHeaders={signed_headers}, Signature={signature}"
    )
    request = urllib.request.Request(
        f"https://{host}{canonical_uri}",
        data=body,
        headers={
            "Authorization": authorization,
            "Content-Type": content_type,
            "x-amz-content-sha256": payload_hash,
            "x-amz-date": amz_date,
        },
        method="PUT",
    )
    with urllib.request.urlopen(request, timeout=300) as response:
        response.read()
    return {"path": str(path), "key": key, "url": r2_public_url_for_key(key)}


def media_files_for_folder(folder: Path) -> list[Path]:
    metadata_path = folder / "metadata.json"
    metadata = json.loads(metadata_path.read_text(encoding="utf-8")) if metadata_path.exists() else {}
    candidates: list[Path] = []
    for value in [metadata.get("image"), metadata.get("sound"), metadata.get("reels_outro_image")]:
        if value:
            path = Path(value)
            local_path = folder / path.name
            if local_path.exists():
                candidates.append(local_path)
            else:
                candidates.append(path)
    for value in metadata.get("images", []) or []:
        path = Path(value)
        local_path = folder / path.name
        if local_path.exists():
            candidates.append(local_path)
        else:
            candidates.append(path)
    for name in ["tiktok-video.mp4", "promo-video.mp4", "youtube-thumbnail.png"]:
        path = folder / name
        if path.exists():
            candidates.append(path)
    seen: set[str] = set()
    files: list[Path] = []
    for path in candidates:
        resolved = path.resolve()
        if resolved.exists() and str(resolved) not in seen:
            seen.add(str(resolved))
            files.append(resolved)
    return files


def upload_folder_media_to_r2(folder: str) -> dict[str, Any]:
    target = Path(folder).resolve()
    allowed_roots = [SOCIAL_OUTPUT_DIR.resolve(), TIKTOK_OUTPUT_DIR.resolve(), EXPERIMENT_OUTPUT_DIR.resolve(), OUTPUT_DIR.resolve(), YOUTUBE_OUTPUT_DIR.resolve(), CHAPTER_OUTPUT_DIR.resolve()]
    if not any(str(target).startswith(str(root)) for root in allowed_roots):
        raise RuntimeError("Folder is not valid for media upload.")
    uploaded = [upload_file_to_r2(path) for path in media_files_for_folder(target)]
    metadata_path = target / "metadata.json"
    if metadata_path.exists():
        metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
        metadata.setdefault("cloudflare_r2_uploads", []).append(
            {"uploaded_at": time.strftime("%Y-%m-%d %H:%M:%S"), "files": uploaded}
        )
        metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    return {"uploaded": uploaded}


def copy_folder_media_to_github(folder: str) -> dict[str, Any]:
    target = Path(folder).resolve()
    allowed_roots = [
        SOCIAL_OUTPUT_DIR.resolve(),
        TIKTOK_OUTPUT_DIR.resolve(),
        EXPERIMENT_OUTPUT_DIR.resolve(),
        OUTPUT_DIR.resolve(),
        YOUTUBE_OUTPUT_DIR.resolve(),
        CHAPTER_OUTPUT_DIR.resolve(),
    ]
    if not any(str(target).startswith(str(root)) for root in allowed_roots):
        raise RuntimeError("Folder is not valid for GitHub media storage.")
    GITHUB_MEDIA_DIR.mkdir(parents=True, exist_ok=True)
    copied: list[dict[str, str]] = []
    for source in media_files_for_folder(target):
        key = media_key_for_generated_file(source)
        destination = GITHUB_MEDIA_DIR / Path(key)
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, destination)
        copied.append(
            {
                "source": str(source),
                "repo_path": str(destination),
                "key": key,
                "url": github_media_url_for_key(key),
            }
        )
    metadata_path = target / "metadata.json"
    if metadata_path.exists():
        metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
        metadata.setdefault("github_media_copies", []).append(
            {"copied_at": time.strftime("%Y-%m-%d %H:%M:%S"), "files": copied}
        )
        if copied:
            metadata["public_media_urls"] = [item["url"] for item in copied]
            first_image = next((item["url"] for item in copied if Path(item["key"]).suffix.lower() in IMAGE_EXTENSIONS), None)
            if first_image:
                metadata["public_image_url"] = first_image
        metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    return {"copied": copied, "media_dir": str(GITHUB_MEDIA_DIR), "base_url": github_public_media_base_url()}


def run_git(args: list[str], timeout: int = 120) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        ["git", "-c", f"safe.directory={ROOT.as_posix()}", *args],
        cwd=str(ROOT),
        capture_output=True,
        text=True,
        timeout=timeout,
        check=False,
    )


def git_output(run: subprocess.CompletedProcess[str]) -> str:
    return (run.stdout + "\n" + run.stderr).strip()


def run_media_git(args: list[str], timeout: int = 300) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        ["git", "-c", f"safe.directory={GITHUB_MEDIA_REPO_DIR.resolve().as_posix()}", *args],
        cwd=str(GITHUB_MEDIA_REPO_DIR),
        capture_output=True,
        text=True,
        timeout=timeout,
        check=False,
    )


def folder_has_large_github_api_media(folder: str | Path) -> bool:
    return any(path.stat().st_size > GITHUB_CONTENT_API_SAFE_LIMIT_BYTES for path in media_files_for_folder(Path(folder).resolve()))


def ensure_github_media_repo_clone() -> list[dict[str, Any]]:
    steps: list[dict[str, Any]] = []
    branch = os.environ.get("GITHUB_BRANCH", "main").strip() or "main"
    remote_url = os.environ.get("GITHUB_MEDIA_REMOTE_URL", GITHUB_MEDIA_REMOTE_URL).strip() or GITHUB_MEDIA_REMOTE_URL
    if not (GITHUB_MEDIA_REPO_DIR / ".git").exists():
        GITHUB_MEDIA_REPO_DIR.parent.mkdir(parents=True, exist_ok=True)
        run = subprocess.run(
            ["git", "clone", "--branch", branch, remote_url, str(GITHUB_MEDIA_REPO_DIR)],
            cwd=str(ROOT),
            capture_output=True,
            text=True,
            timeout=300,
            check=False,
        )
        steps.append({"command": "git clone media repo", "returncode": run.returncode, "output": git_output(run)})
        if run.returncode != 0:
            run = subprocess.run(
                ["git", "clone", remote_url, str(GITHUB_MEDIA_REPO_DIR)],
                cwd=str(ROOT),
                capture_output=True,
                text=True,
                timeout=300,
                check=False,
            )
            steps.append({"command": "git clone media repo fallback", "returncode": run.returncode, "output": git_output(run)})
            if run.returncode != 0:
                raise RuntimeError(git_output(run) or "Git could not clone the media repository.")
    remote = run_media_git(["remote", "get-url", "origin"])
    if remote.returncode == 0 and remote.stdout.strip() != remote_url:
        run = run_media_git(["remote", "set-url", "origin", remote_url])
        steps.append({"command": "git remote set-url origin", "returncode": run.returncode, "output": git_output(run)})
    fetch = run_media_git(["fetch", "origin", branch], timeout=300)
    steps.append({"command": "git fetch media repo", "returncode": fetch.returncode, "output": git_output(fetch)})
    checkout = run_media_git(["checkout", branch])
    steps.append({"command": "git checkout media branch", "returncode": checkout.returncode, "output": git_output(checkout)})
    if checkout.returncode != 0:
        checkout = run_media_git(["checkout", "-B", branch])
        steps.append({"command": "git checkout -B media branch", "returncode": checkout.returncode, "output": git_output(checkout)})
        if checkout.returncode != 0:
            raise RuntimeError(git_output(checkout) or "Git could not checkout the media branch.")
    pull = run_media_git(["pull", "--ff-only", "origin", branch], timeout=300)
    steps.append({"command": "git pull media repo", "returncode": pull.returncode, "output": git_output(pull)})
    return steps


def publish_folder_media_to_github_git_repo(folder: str) -> dict[str, Any]:
    target = Path(folder).resolve()
    allowed_roots = [
        SOCIAL_OUTPUT_DIR.resolve(),
        TIKTOK_OUTPUT_DIR.resolve(),
        EXPERIMENT_OUTPUT_DIR.resolve(),
        OUTPUT_DIR.resolve(),
        YOUTUBE_OUTPUT_DIR.resolve(),
        CHAPTER_OUTPUT_DIR.resolve(),
    ]
    if not any(str(target).startswith(str(root)) for root in allowed_roots):
        raise RuntimeError("Folder is not valid for GitHub media storage.")
    steps = ensure_github_media_repo_clone()
    branch = os.environ.get("GITHUB_BRANCH", "main").strip() or "main"
    copied: list[dict[str, str]] = []
    for source in media_files_for_folder(target):
        key = media_key_for_generated_file(source)
        destination = GITHUB_MEDIA_REPO_DIR / "media" / Path(key)
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, destination)
        copied.append(
            {
                "source": str(source),
                "repo_path": str(destination),
                "key": key,
                "url": github_media_url_for_key(key),
                "size": str(source.stat().st_size),
            }
        )
    add = run_media_git(["add", "media"], timeout=300)
    steps.append({"command": "git add media", "returncode": add.returncode, "output": git_output(add)})
    if add.returncode != 0:
        raise RuntimeError(git_output(add) or "Git could not stage media files.")
    status = run_media_git(["status", "--porcelain", "--", "media"])
    changed = bool(status.stdout.strip())
    commit_created = False
    commit_sha = ""
    if changed:
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
        commit = run_media_git(["commit", "-m", f"Publish automation media {timestamp}"], timeout=300)
        steps.append({"command": "git commit media", "returncode": commit.returncode, "output": git_output(commit)})
        if commit.returncode != 0:
            raise RuntimeError(git_output(commit) or "Git could not commit media files.")
        commit_created = True
    rev = run_media_git(["rev-parse", "HEAD"])
    if rev.returncode == 0:
        commit_sha = rev.stdout.strip()
        owner, repo = github_media_repo_parts()
        for item in copied:
            encoded_path = urllib.parse.quote(f"media/{item['key']}", safe="/")
            item["url"] = f"https://raw.githubusercontent.com/{owner}/{repo}/{commit_sha}/{encoded_path}"
            item["commit"] = commit_sha
    push = run_media_git(["push", "-u", "origin", branch], timeout=600)
    steps.append({"command": "git push media repo", "returncode": push.returncode, "output": git_output(push)})
    if push.returncode != 0:
        raise RuntimeError(git_output(push) or "Git could not push media files.")
    metadata_path = target / "metadata.json"
    if metadata_path.exists():
        metadata = read_json_safe(metadata_path)
        if not isinstance(metadata, dict):
            metadata = {}
        metadata.setdefault("github_media_git_publishes", []).append(
            {
                "published_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                "files": copied,
                "commit": commit_sha,
                "commit_created": commit_created,
            }
        )
        metadata["public_media_urls"] = [item["url"] for item in copied]
        first_image = next((item["url"] for item in copied if Path(item["key"]).suffix.lower() in IMAGE_EXTENSIONS), None)
        if first_image:
            metadata["public_image_url"] = first_image
        metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    return {
        "copied": copied,
        "published": True,
        "method": "github-git-media-repo",
        "commitCreated": commit_created,
        "commit": commit_sha,
        "git": steps,
        "base_url": github_public_media_base_url(),
    }


def ensure_github_repo() -> list[dict[str, Any]]:
    steps: list[dict[str, Any]] = []
    if not (ROOT / ".git").exists():
        run = run_git(["init", "-b", "main"])
        steps.append({"command": "git init -b main", "returncode": run.returncode, "output": git_output(run)})
        if run.returncode != 0:
            raise RuntimeError(git_output(run) or "Git init failed.")

    branch = run_git(["branch", "--show-current"])
    if branch.returncode == 0 and branch.stdout.strip() != "main":
        run = run_git(["branch", "-M", "main"])
        steps.append({"command": "git branch -M main", "returncode": run.returncode, "output": git_output(run)})

    remote_url = os.environ.get("GITHUB_REMOTE_URL", GITHUB_REMOTE_URL).strip() or GITHUB_REMOTE_URL
    remote = run_git(["remote", "get-url", "origin"])
    if remote.returncode != 0:
        run = run_git(["remote", "add", "origin", remote_url])
        steps.append({"command": "git remote add origin", "returncode": run.returncode, "output": git_output(run)})
    elif remote.stdout.strip() != remote_url:
        run = run_git(["remote", "set-url", "origin", remote_url])
        steps.append({"command": "git remote set-url origin", "returncode": run.returncode, "output": git_output(run)})
    return steps


def publish_folder_media_to_github(folder: str) -> dict[str, Any]:
    if folder_has_large_github_api_media(folder):
        if r2_configured():
            return publish_folder_media_to_github_api(folder)
        return publish_folder_media_to_github_git_repo(folder)
    if os.environ.get("GITHUB_TOKEN", "").strip():
        return publish_folder_media_to_github_api(folder)
    copied = copy_folder_media_to_github(folder)
    steps = ensure_github_repo()
    paths = ["docs/.nojekyll", "docs/media"]
    add = run_git(["add", *paths])
    steps.append({"command": "git add docs media", "returncode": add.returncode, "output": git_output(add)})
    if add.returncode != 0:
        raise RuntimeError(git_output(add) or "Git could not stage media files.")

    status = run_git(["status", "--porcelain", "--", *paths])
    changed = bool(status.stdout.strip())
    commit_created = False
    if changed:
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
        commit = run_git(["commit", "-m", f"Publish automation media {timestamp}"])
        steps.append({"command": "git commit media", "returncode": commit.returncode, "output": git_output(commit)})
        if commit.returncode != 0:
            raise RuntimeError(git_output(commit) or "Git could not commit media files.")
        commit_created = True

    push = run_git(["push", "-u", "origin", "main"], timeout=300)
    steps.append({"command": "git push origin main", "returncode": push.returncode, "output": git_output(push)})
    if push.returncode != 0:
        raise RuntimeError(git_output(push) or "Git could not push media files.")

    return {**copied, "published": True, "commitCreated": commit_created, "git": steps}


def auto_publish_generated_media(folder: Path, payload: dict[str, Any]) -> dict[str, Any]:
    payload.update(normalize_pack_metadata(folder, payload, persist=False))
    if not github_auto_publish_media():
        metadata_path = folder / "metadata.json"
        if metadata_path.exists():
            metadata_path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
        return payload
    try:
        published = publish_folder_media_to_github(str(folder))
        payload["github_media_publish"] = {
            "published_at": time.strftime("%Y-%m-%d %H:%M:%S"),
            "files": published.get("copied", []),
            "base_url": published.get("base_url"),
            "commit_created": published.get("commitCreated", False),
        }
        urls = [item["url"] for item in published.get("copied", [])]
        if urls:
            payload["public_media_urls"] = urls
            first_image = next((url for url in urls if Path(urllib.parse.urlparse(url).path).suffix.lower() in IMAGE_EXTENSIONS), None)
            if first_image:
                payload["public_image_url"] = first_image
    except Exception as exc:
        payload.setdefault("automation_warnings", []).append(f"GitHub media publish failed: {exc}")
    metadata_path = folder / "metadata.json"
    if metadata_path.exists():
        payload.update(normalize_pack_metadata(folder, payload, persist=False))
        metadata_path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    return payload


def manual_buffer_assist(folder: str, text_kind: str = "instagram") -> dict[str, Any]:
    post_folder = Path(folder).resolve()
    allowed_roots = [SOCIAL_OUTPUT_DIR.resolve(), TIKTOK_OUTPUT_DIR.resolve(), OUTPUT_DIR.resolve(), YOUTUBE_OUTPUT_DIR.resolve()]
    if not any(str(post_folder).startswith(str(root)) for root in allowed_roots):
        raise RuntimeError("Folder is not valid for Buffer assist.")
    metadata_path = post_folder / "metadata.json"
    if not metadata_path.exists():
        raise RuntimeError("This folder does not contain metadata.")
    metadata = read_metadata(post_folder)
    if str(post_folder).startswith(str(TIKTOK_OUTPUT_DIR.resolve())):
        text = metadata.get("caption", "")
        text_file = post_folder / "caption.txt"
    elif str(post_folder).startswith(str(SOCIAL_OUTPUT_DIR.resolve())):
        text = metadata.get("instagram" if text_kind == "instagram" else "x", "")
        text_file = post_folder / ("instagram.txt" if text_kind == "instagram" else "x.txt")
    elif str(post_folder).startswith(str(YOUTUBE_OUTPUT_DIR.resolve())):
        text = metadata.get("description", "")
        text_file = post_folder / "youtube-description.txt"
    else:
        text = metadata.get("caption") or metadata.get("patreon_note") or metadata.get("royal_road_note") or ""
        text_file = post_folder / "caption.txt"
        if not text_file.exists():
            text_file.write_text(text + "\n", encoding="utf-8")
    try:
        subprocess.run(["powershell", "-NoProfile", "-Command", f"Get-Content -Raw -LiteralPath '{text_file}' | Set-Clipboard"], check=False)
    except Exception:
        pass
    try:
        os.startfile(str(post_folder))
    except Exception:
        pass
    try:
        open_url_once("https://publish.buffer.com/calendar")
    except Exception:
        pass
    metadata.setdefault("manual_buffer_assists", []).append(
        {
            "opened_at": time.strftime("%Y-%m-%d %H:%M:%S"),
            "text_kind": text_kind,
            "text_file": str(text_file),
            "folder": str(post_folder),
        }
    )
    metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    return {
        "message": "Opened Buffer and the media folder. Caption copied to clipboard.",
        "folder": str(post_folder),
        "text_file": str(text_file),
        "text": text,
    }


def mark_buffer_queued(folder: str) -> dict[str, Any]:
    post_folder = Path(folder).resolve()
    allowed_roots = [SOCIAL_OUTPUT_DIR.resolve(), TIKTOK_OUTPUT_DIR.resolve(), OUTPUT_DIR.resolve(), YOUTUBE_OUTPUT_DIR.resolve()]
    if not any(str(post_folder).startswith(str(root)) for root in allowed_roots):
        raise RuntimeError("Folder is not valid for Buffer status.")
    metadata_path = post_folder / "metadata.json"
    metadata = json.loads(metadata_path.read_text(encoding="utf-8")) if metadata_path.exists() else {}
    metadata["manual_buffer_queued"] = {
        "queued_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        "status": "confirmed_by_user",
    }
    metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    (post_folder / "manual-buffer-queued.txt").write_text(
        f"Buffer post manually marked queued at {metadata['manual_buffer_queued']['queued_at']}\n",
        encoding="utf-8",
    )
    abbr, chapter_number, updates = chapter_ledger_updates_for_folder(post_folder, metadata, "socialPostsQueued")
    if abbr and chapter_number:
        progress_tool = post_progress_tool(metadata)
        if progress_tool == "promo":
            updates.update(
                {
                    "bufferQueued": True,
                    "bufferQueuedAt": metadata["manual_buffer_queued"]["queued_at"],
                }
            )
            if str(post_folder).startswith(str(TIKTOK_OUTPUT_DIR.resolve())):
                updates["shortsReelsQueued"] = True
                updates["shortsReelsQueuedAt"] = metadata["manual_buffer_queued"]["queued_at"]
                if str(metadata.get("kind") or "") == "deep_tiktok" or post_folder.name.lower().endswith("-deep"):
                    updates["deepTikTokQueued"] = True
                    updates["deepTikTokQueuedAt"] = metadata["manual_buffer_queued"]["queued_at"]
            update_chapter_ledger(abbr, chapter_number, updates)
        if chapter_can_advance_active_path(abbr, chapter_number):
            advance_completed_chapter(abbr, chapter_number, progress_tool)
    return {"queued": True, "folder": str(post_folder)}


def buffer_asset_for_file(path: Path) -> dict[str, Any] | None:
    url = public_url_for_generated_file(path)
    if not url:
        return None
    if path.suffix.lower() in VIDEO_EXTENSIONS:
        return {"video": {"url": url}}
    if path.suffix.lower() in IMAGE_EXTENSIONS:
        return {"image": {"url": url}}
    return None


def verify_public_media_url(url: str, attempts: int = 6) -> None:
    last_error: Exception | None = None
    for attempt in range(max(1, attempts)):
        for method in ("HEAD", "GET"):
            request = urllib.request.Request(url, method=method, headers={"User-Agent": "AutomationTool/1.0"})
            try:
                with urllib.request.urlopen(request, timeout=30) as response:
                    if response.status >= 400:
                        raise RuntimeError(f"Media URL returned HTTP {response.status}.")
                    if method == "GET":
                        response.read(1)
                    return
            except Exception as exc:
                last_error = exc
        if attempt < attempts - 1:
            time.sleep(min(12, 1.5 * (2 ** attempt)))
    raise RuntimeError(
        f"Buffer cannot fetch the media URL after {attempts} checks: {url}. "
        "The GitHub media file may still be propagating or the repository may not be public."
    ) from last_error


def normalize_buffer_metadata(metadata: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(metadata, dict):
        return {}
    normalized = json.loads(json.dumps(metadata))
    youtube = normalized.get("youtube")
    if isinstance(youtube, dict):
        for key in ["categoryId"]:
            if key in youtube:
                youtube[key] = str(youtube[key]).strip()
        for key in ["notifySubscribers", "embeddable", "madeForKids"]:
            if key in youtube and isinstance(youtube[key], str):
                youtube[key] = youtube[key].strip().lower() in {"1", "true", "yes", "on"}
    instagram = normalized.get("instagram")
    if isinstance(instagram, dict):
        if "type" in instagram:
            instagram["type"] = str(instagram["type"] or "").strip().lower()
        for key in ["shouldShareToFeed"]:
            if key in instagram and isinstance(instagram[key], str):
                instagram[key] = instagram[key].strip().lower() in {"1", "true", "yes", "on"}
    return normalized


def buffer_metadata_for_channel(
    channel_id: str,
    assets: list[dict[str, Any]],
    metadata: dict[str, Any] | None,
) -> dict[str, Any]:
    """Normalize provider metadata and fill required platform defaults."""
    normalized = normalize_buffer_metadata(metadata)
    if buffer_channel_service(channel_id) != "instagram":
        return normalized

    instagram = normalized.setdefault("instagram", {})
    if not isinstance(instagram, dict):
        instagram = {}
        normalized["instagram"] = instagram
    post_type = str(instagram.get("type") or "").strip().lower()
    if post_type not in {"post", "story", "reel"}:
        has_video = any(isinstance(asset, dict) and isinstance(asset.get("video"), dict) for asset in assets)
        instagram["type"] = "reel" if has_video else "post"
    instagram.setdefault("shouldShareToFeed", True)
    return normalized


def create_buffer_post(
    channel_id: str,
    text: str,
    media_paths: list[str],
    mode: str = "addToQueue",
    metadata: dict[str, Any] | None = None,
    scheduled_at: str | None = None,
) -> dict[str, Any]:
    save_to_draft = mode == "draft"
    share_mode = "customScheduled" if scheduled_at and not save_to_draft else ("addToQueue" if save_to_draft else mode)
    assets = []
    for media_path in media_paths:
        asset = buffer_asset_for_file(Path(media_path))
        if asset:
            assets.append(asset)
    if media_paths and not assets:
        raise RuntimeError("Buffer needs public HTTPS media URLs. Set BUFFER_PUBLIC_BASE_URL to where generated media is hosted.")
    for asset in assets:
        url = asset.get("image", {}).get("url") or asset.get("video", {}).get("url")
        if url:
            verify_public_media_url(url)
    input_payload = {
        "text": text,
        "channelId": channel_id,
        "schedulingType": "automatic",
        "mode": share_mode,
        "saveToDraft": save_to_draft,
        "assets": assets,
        "metadata": buffer_metadata_for_channel(channel_id, assets, metadata),
    }
    youtube_metadata = input_payload.get("metadata", {}).get("youtube")
    if isinstance(youtube_metadata, dict) and "categoryId" in youtube_metadata:
        youtube_metadata["categoryId"] = str(youtube_metadata["categoryId"]).strip()
    if scheduled_at and not save_to_draft:
        input_payload["dueAt"] = scheduled_at
    try:
        (ROOT / "buffer-last-payload.json").write_text(
            json.dumps(
                {
                    "createdAt": datetime.now(timezone.utc).isoformat(),
                    "input": input_payload,
                },
                indent=2,
                ensure_ascii=False,
            ),
            encoding="utf-8",
        )
    except Exception:
        pass
    result = buffer_graphql(
        """
        mutation CreatePost($input: CreatePostInput!) {
          createPost(input: $input) {
            ... on PostActionSuccess {
              post { id text dueAt channelId assets { id mimeType } }
            }
            ... on MutationError { message }
          }
        }
        """,
        {
            "input": input_payload
        },
    )
    response = result.get("data", {}).get("createPost", {})
    if response.get("message"):
        raise RuntimeError(response["message"])
    return response


def buffer_queue_full_error(error: Exception) -> bool:
    message = str(error).lower()
    return any(
        phrase in message
        for phrase in [
            "queue full",
            "queue is full",
            "queued posts limit",
            "scheduled posts limit",
            "maximum scheduled",
            "max scheduled",
            "10 scheduled",
            "limit of 10",
        ]
    )


def launch_playwright_script(script: Path, cwd: Path) -> bool:
    if not playwright_available():
        return False
    node = bundled_node_executable()
    subprocess.Popen(
        [str(node), str(script)],
        cwd=str(cwd),
        env={
            **os.environ,
            "NODE_PATH": str(ROOT / "node_modules"),
            "PLAYWRIGHT_BROWSERS_PATH": str(ROOT / "ms-playwright"),
        },
        creationflags=subprocess.CREATE_NO_WINDOW if hasattr(subprocess, "CREATE_NO_WINDOW") else 0,
    )
    return True


def write_buffer_fallback_cockpit(post_folder: Path, fallbacks: list[dict[str, Any]]) -> Path:
    cards = []
    for index, item in enumerate(fallbacks, start=1):
        media = "\n".join(str(path) for path in item.get("media", []) if path)
        cards.append(
            f"""
            <section class="card">
              <div class="card-head">
                <h2>{html.escape(item.get('service', 'Buffer').title())}</h2>
                <a href="https://publish.buffer.com/calendar" target="_blank" rel="noreferrer">Open Buffer</a>
              </div>
              <p><strong>Channel:</strong> <code>{html.escape(item.get('channelId', ''))}</code></p>
              <p><strong>Media:</strong></p>
              <pre>{html.escape(media or 'No media file found')}</pre>
              <textarea id="bufferText{index}">{html.escape(item.get('text', ''))}</textarea>
              <button type="button" data-copy="bufferText{index}">Copy Text</button>
            </section>
            """
        )
    target = post_folder / "buffer-fallback.html"
    target.write_text(
        f"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Buffer Queue Fallback</title>
  <style>
    body {{ margin: 0; font-family: Arial, Helvetica, sans-serif; background: #f5f7fa; color: #18212a; }}
    main {{ max-width: 1100px; margin: 0 auto; padding: 24px; }}
    h1 {{ font-size: 28px; margin: 0 0 8px; }}
    .note {{ margin: 0 0 20px; color: #4a5563; }}
    .grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 16px; }}
    .card {{ background: #fff; border: 1px solid #d8e0e8; border-radius: 8px; padding: 16px; }}
    .card-head {{ display: flex; justify-content: space-between; align-items: center; gap: 12px; }}
    h2 {{ font-size: 18px; margin: 0; }}
    a, button {{ background: #1f6feb; color: #fff; border: 0; border-radius: 6px; padding: 9px 12px; text-decoration: none; cursor: pointer; }}
    textarea {{ width: 100%; min-height: 220px; box-sizing: border-box; margin: 10px 0; padding: 10px; font: 14px/1.45 Consolas, monospace; }}
    pre, code {{ white-space: pre-wrap; word-break: break-all; }}
  </style>
</head>
<body>
  <main>
    <h1>Buffer Queue Fallback</h1>
    <p class="note">Buffer reported a full queue. Use this review page to manually schedule or save drafts in Buffer.</p>
    <div class="grid">{''.join(cards)}</div>
  </main>
  <script>
    document.querySelectorAll('[data-copy]').forEach(button => {{
      button.addEventListener('click', async () => {{
        await navigator.clipboard.writeText(document.getElementById(button.dataset.copy).value);
        button.textContent = 'Copied';
        setTimeout(() => button.textContent = 'Copy Text', 1200);
      }});
    }});
  </script>
</body>
</html>
""",
        encoding="utf-8",
    )
    return target


def write_buffer_fallback_playwright_script(post_folder: Path, cockpit: Path) -> Path:
    script = post_folder / "buffer-fallback-playwright.js"
    script.write_text(
        f"""const {{ chromium }} = require('playwright');

(async () => {{
  const context = await chromium.launchPersistentContext(
    {json.dumps(str((ROOT / ".playwright-profile").resolve()))},
    {{ headless: false, viewport: {{ width: 1440, height: 1000 }} }}
  );
  const buffer = await context.newPage();
  await buffer.goto('https://publish.buffer.com/calendar', {{ waitUntil: 'domcontentloaded', timeout: 60000 }});
  const cockpit = await context.newPage();
  await cockpit.goto({json.dumps(cockpit.resolve().as_uri())});
  console.log('Buffer fallback opened. Schedule manually after review.');
}})().catch(error => {{
  console.error(error);
  process.exit(1);
}});
""",
        encoding="utf-8",
    )
    return script


def buffer_queue_full_fallback(post_folder: Path, item: dict[str, Any], error: Exception) -> dict[str, Any]:
    cockpit = write_buffer_fallback_cockpit(post_folder, [item])
    script = write_buffer_fallback_playwright_script(post_folder, cockpit)
    launched = launch_playwright_script(script, post_folder)
    record_recovery_event(
        "buffer_push",
        str(error),
        error_type="buffer_queue_full",
        folder=post_folder,
        details={
            "service": item.get("service", "buffer"),
            "channelId": item.get("channelId", ""),
            "cockpit": str(cockpit),
            "playwrightScript": str(script),
            "playwrightLaunched": launched,
        },
    )
    try:
        open_url_once(str(cockpit))
    except Exception:
        pass
    return {
        "fallback": "buffer_queue_full",
        "service": item.get("service", "buffer"),
        "channelId": item.get("channelId", ""),
        "error": str(error),
        "cockpit": str(cockpit),
        "playwright_script": str(script),
        "playwright_launched": launched,
        "message": "Buffer queue is full. Opened a fallback scheduling cockpit for manual review.",
    }


def cleanup_generated_folder(folder: Path) -> dict[str, Any]:
    patterns = [
        "promo-slide-*.mp4",
        "promo-slides.txt",
        "promo-video-silent.mp4",
        "youtube-bg-*.mp4",
        "youtube-clips.txt",
        "youtube-audio-parts.txt",
        "youtube-voiceover-part-*.mp3",
        "youtube-voiceover.wav",
        "youtube-voiceover.mp3",
        "youtube-voiceover-clean.m4a",
        "make_video.py",
        "make_youtube_video.py",
        "build_youtube_video.py",
        "youtube-project-notes.txt",
        "openshot-notes.txt",
        "overlay-preview.jpg",
        "tiktok-clean-*.png",
        "tiktok-slides.txt",
    ]
    removed: list[str] = []
    errors: list[str] = []
    for pattern in patterns:
        for path in folder.glob(pattern):
            if not path.is_file():
                continue
            try:
                path.unlink()
                removed.append(path.name)
            except Exception as exc:
                errors.append(f"{path.name}: {exc}")

    metadata_path = folder / "metadata.json"
    if metadata_path.exists():
        try:
            metadata = json.loads(metadata_path.read_text(encoding="utf-8-sig"))
            reels_audio = metadata.get("reels_audio")
            if reels_audio:
                audio_path = folder / Path(reels_audio).name
                if audio_path.exists() and audio_path.is_file():
                    audio_path.unlink()
                    removed.append(audio_path.name)
                metadata.pop("reels_audio", None)
            metadata["cleanup"] = {
                "cleaned_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                "removed": removed,
                "errors": errors,
            }
            metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
        except Exception as exc:
            errors.append(f"metadata.json: {exc}")

    return {"removed": removed, "errors": errors}


def generated_folder_key(root_name: str, folder: Path, metadata: dict[str, Any]) -> str:
    abbr = str(metadata.get("abbr") or "").strip().upper()
    chapter = str(metadata.get("chapter") or "").strip()
    title = str(metadata.get("title") or "").strip()
    if not abbr and root_name == "tiktok-posts":
        match = re.search(r"(?:\d{8}-\d{6}-)?([a-z]{2})-(\d+[a-z]?)$", folder.name, re.IGNORECASE)
        if match:
            abbr = match.group(1).upper()
            chapter = chapter or match.group(2)
    if not title and root_name in {"campaigns", "youtube-videos"}:
        title = re.sub(r"^\d{8}-\d{6}-", "", folder.name)
    if root_name == "tiktok-posts":
        return f"{root_name}:{abbr}:{chapter}"
    return f"{root_name}:{abbr or 'manual'}:{chapter or 'chapter'}:{slugify(title)}"


def is_timestamped_generated_folder(folder: Path) -> bool:
    return bool(re.match(r"^\d{8}-\d{6}-", folder.name))


def remote_cleanup_targets() -> list[dict[str, Any]]:
    media_owner, media_repo = github_media_repo_parts()
    app_owner, app_repo = github_repo_parts()
    targets = [
        {"repoKind": "media", "owner": media_owner, "repo": media_repo, "base": "media"},
    ]
    if (app_owner, app_repo) != (media_owner, media_repo):
        targets.append({"repoKind": "app", "owner": app_owner, "repo": app_repo, "base": "docs/media"})
    else:
        targets.append({"repoKind": "app", "owner": app_owner, "repo": app_repo, "base": "docs/media"})
    return targets


def github_list_content_in_repo(owner: str, repo: str, path: str) -> Any:
    branch = os.environ.get("GITHUB_BRANCH", "main").strip() or "main"
    try:
        return github_api_request("GET", f"/repos/{owner}/{repo}/contents/{urllib.parse.quote(path, safe='/')}?ref={urllib.parse.quote(branch)}")
    except FileNotFoundError:
        return []


def remote_orphan_media_plan() -> list[dict[str, Any]]:
    remote_orphans: list[dict[str, Any]] = []
    for target in remote_cleanup_targets():
        for root_name, local_root in [("campaigns", OUTPUT_DIR), ("youtube-videos", YOUTUBE_OUTPUT_DIR), ("tiktok-posts", TIKTOK_OUTPUT_DIR)]:
            remote_root = f"{target['base']}/{root_name}"
            entries = github_list_content_in_repo(target["owner"], target["repo"], remote_root)
            for entry in entries if isinstance(entries, list) else []:
                if entry.get("type") != "dir":
                    continue
                name = str(entry.get("name") or Path(str(entry.get("path") or "")).name)
                if not name:
                    continue
                local_folder = local_root / name
                if not local_folder.exists():
                    remote_orphans.append(
                        {
                            "root": root_name,
                            "name": name,
                            "repoKind": target["repoKind"],
                            "owner": target["owner"],
                            "repo": target["repo"],
                            "remotePrefix": f"{remote_root}/{name}",
                            "localFolder": str(local_folder),
                        }
                    )
    return remote_orphans


def duplicate_generated_media_plan(remote: bool = False) -> dict[str, Any]:
    roots = [
        ("campaigns", OUTPUT_DIR),
        ("youtube-videos", YOUTUBE_OUTPUT_DIR),
        ("tiktok-posts", TIKTOK_OUTPUT_DIR),
    ]
    groups: dict[str, list[dict[str, Any]]] = {}
    for root_name, root in roots:
        if not root.exists():
            continue
        for folder in root.iterdir():
            if not folder.is_dir():
                continue
            metadata = read_metadata(folder)
            if not metadata:
                continue
            key = generated_folder_key(root_name, folder, metadata)
            groups.setdefault(key, []).append(
                {
                    "root": root_name,
                    "folder": str(folder),
                    "name": folder.name,
                    "timestamped": is_timestamped_generated_folder(folder),
                    "mtime": folder.stat().st_mtime,
                    "metadata": {k: metadata.get(k) for k in ["abbr", "novel", "chapter", "title", "chapter_hash"]},
                }
            )

    duplicates: list[dict[str, Any]] = []
    for key, items in groups.items():
        if len(items) < 2:
            continue
        keep = sorted(items, key=lambda item: (item["timestamped"], item["mtime"]), reverse=False)[0]
        stable_items = [item for item in items if not item["timestamped"]]
        if stable_items:
            keep = sorted(stable_items, key=lambda item: item["mtime"], reverse=True)[0]
        else:
            keep = sorted(items, key=lambda item: item["mtime"], reverse=True)[0]
        for item in items:
            if item["folder"] == keep["folder"]:
                continue
            media_folder = GITHUB_MEDIA_DIR / item["root"] / item["name"]
            duplicates.append(
                {
                    "key": key,
                    "keep": keep["folder"],
                    "remove": item["folder"],
                    "name": item["name"],
                    "root": item["root"],
                    "mediaFolder": str(media_folder),
                    "remotePrefix": f"media/{item['root']}/{item['name']}",
                    "metadata": item["metadata"],
                }
            )
    orphan_media: list[dict[str, Any]] = []
    for root_name, root in [("campaigns", OUTPUT_DIR), ("youtube-videos", YOUTUBE_OUTPUT_DIR), ("tiktok-posts", TIKTOK_OUTPUT_DIR)]:
        media_root = GITHUB_MEDIA_DIR / root_name
        if not media_root.exists():
            continue
        for media_folder in media_root.iterdir():
            if not media_folder.is_dir():
                continue
            local_folder = root / media_folder.name
            if not local_folder.exists():
                orphan_media.append(
                    {
                        "root": root_name,
                        "mediaFolder": str(media_folder),
                        "remotePrefix": f"media/{root_name}/{media_folder.name}",
                    }
                )
    remote_orphans: list[dict[str, Any]] = []
    if remote and os.environ.get("GITHUB_TOKEN", "").strip():
        remote_orphans = remote_orphan_media_plan()
    return {"groups": len(groups), "duplicates": duplicates, "orphanMedia": orphan_media, "remoteOrphanMedia": remote_orphans}


def github_delete_content(path: str, message: str, owner: str | None = None, repo: str | None = None) -> dict[str, Any]:
    if not owner or not repo:
        owner, repo = github_media_repo_parts()
    branch = os.environ.get("GITHUB_BRANCH", "main").strip() or "main"
    sha = github_existing_sha(owner, repo, path, branch)
    if not sha:
        return {"repo": f"{owner}/{repo}", "path": path, "deleted": False, "reason": "not found"}
    payload = {"message": message, "sha": sha, "branch": branch}
    result = github_api_request("DELETE", f"/repos/{owner}/{repo}/contents/{urllib.parse.quote(path, safe='/')}", payload)
    return {"repo": f"{owner}/{repo}", "path": path, "deleted": True, "commit": result.get("commit", {}).get("sha", "")}


def github_list_content(path: str) -> Any:
    owner, repo = github_media_repo_parts()
    return github_list_content_in_repo(owner, repo, path)


def github_delete_media_tree(prefix: str, message: str, owner: str | None = None, repo: str | None = None) -> list[dict[str, Any]]:
    if not owner or not repo:
        owner, repo = github_media_repo_parts()
    entries = github_list_content_in_repo(owner, repo, prefix)
    if isinstance(entries, dict) and entries.get("type") == "file":
        return [github_delete_content(str(entries.get("path") or prefix), message, owner, repo)]
    deleted: list[dict[str, Any]] = []
    for entry in entries if isinstance(entries, list) else []:
        entry_type = entry.get("type")
        entry_path = str(entry.get("path") or "")
        if not entry_path:
            continue
        if entry_type == "dir":
            deleted.extend(github_delete_media_tree(entry_path, message, owner, repo))
        elif entry_type == "file":
            deleted.append(github_delete_content(entry_path, message, owner, repo))
    return deleted


def cleanup_duplicate_generated_media(apply: bool = False, remote: bool = False) -> dict[str, Any]:
    plan = duplicate_generated_media_plan(remote)
    removed: list[str] = []
    removed_media: list[str] = []
    remote_removed: list[dict[str, Any]] = []
    errors: list[str] = []
    if apply:
        for item in plan["duplicates"]:
            folder = Path(item["remove"]).resolve()
            media_folder = Path(item["mediaFolder"]).resolve()
            try:
                if folder.exists() and any(str(folder).startswith(str(root.resolve())) for root in [OUTPUT_DIR, YOUTUBE_OUTPUT_DIR, TIKTOK_OUTPUT_DIR]):
                    shutil.rmtree(folder)
                    removed.append(str(folder))
            except Exception as exc:
                errors.append(f"{folder}: {exc}")
            try:
                if media_folder.exists() and str(media_folder).startswith(str(GITHUB_MEDIA_DIR.resolve())):
                    shutil.rmtree(media_folder)
                    removed_media.append(str(media_folder))
            except Exception as exc:
                errors.append(f"{media_folder}: {exc}")
            if remote and os.environ.get("GITHUB_TOKEN", "").strip():
                for target in remote_cleanup_targets():
                    prefix = f"{target['base']}/{item['root']}/{item['name']}"
                    try:
                        remote_removed.extend(github_delete_media_tree(prefix, f"Remove duplicate automation media {time.strftime('%Y-%m-%d %H:%M:%S')}", target["owner"], target["repo"]))
                    except Exception as exc:
                        errors.append(f"{target['owner']}/{target['repo']} {prefix}: {exc}")
        for item in plan.get("orphanMedia", []):
            media_folder = Path(item["mediaFolder"]).resolve()
            try:
                if media_folder.exists() and str(media_folder).startswith(str(GITHUB_MEDIA_DIR.resolve())):
                    shutil.rmtree(media_folder)
                    removed_media.append(str(media_folder))
            except Exception as exc:
                errors.append(f"{media_folder}: {exc}")
            if remote and os.environ.get("GITHUB_TOKEN", "").strip():
                for target in remote_cleanup_targets():
                    prefix = f"{target['base']}/{item['root']}/{Path(item['mediaFolder']).name}"
                    try:
                        remote_removed.extend(github_delete_media_tree(prefix, f"Remove orphan automation media {time.strftime('%Y-%m-%d %H:%M:%S')}", target["owner"], target["repo"]))
                    except Exception as exc:
                        errors.append(f"{target['owner']}/{target['repo']} {prefix}: {exc}")
        for item in plan.get("remoteOrphanMedia", []):
            if remote and os.environ.get("GITHUB_TOKEN", "").strip():
                try:
                    remote_removed.extend(github_delete_media_tree(item["remotePrefix"], f"Remove remote orphan automation media {time.strftime('%Y-%m-%d %H:%M:%S')}", item.get("owner"), item.get("repo")))
                except Exception as exc:
                    errors.append(f"{item.get('owner')}/{item.get('repo')} {item['remotePrefix']}: {exc}")
    report = {
        "scanned_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        "apply": apply,
        "remote": remote,
        **plan,
        "removed": removed,
        "removedMedia": removed_media,
        "remoteRemoved": remote_removed,
        "errors": errors,
    }
    DUPLICATE_CLEANUP_REPORT_FILE.write_text(json.dumps(report, indent=2), encoding="utf-8")
    return report


def buffer_post_from_folder(*args, **kwargs):
    return buffer_publish.buffer_post_from_folder(*args, **kwargs)
def buffer_dry_run_from_folder(folder: str, text_kind: str = "", mode: str = "addToQueue") -> dict[str, Any]:
    post_folder = Path(folder).resolve()
    def clean_messages(values: list[Any]) -> list[str]:
        seen: set[str] = set()
        output: list[str] = []
        for value in values:
            text = str(value or "").strip()
            if not text or text in seen:
                continue
            seen.add(text)
            output.append(text)
        return output

    metadata_path = post_folder / "metadata.json"
    if not metadata_path.exists() or not path_is_within(post_folder, approved_daily_upload_roots()):
        return {
            "ok": False,
            "folder": str(post_folder),
            "errors": ["This folder is not a valid Buffer-ready post pack."],
            "routes": [],
        }
    metadata = read_metadata(post_folder)
    text_kind = str(text_kind or daily_upload_text_kind(post_folder, metadata) or "instagram")
    health = pack_health_item(post_folder, fast=False)
    quality = folder_quality_gate(str(post_folder), text_kind, full_duplicate_scan=False)
    media = media_files_for_folder(post_folder)
    channels = configured_buffer_channels()
    errors = list(health.get("errors") or []) + list(quality.get("errors") or [])
    warnings = list(health.get("warnings") or []) + list(quality.get("warnings") or [])
    if not channels:
        errors.append("No saved Buffer channels are configured.")
    if not media:
        errors.append("No media file was found.")
    public_urls = []
    missing_public_urls = []
    for path in media:
        url = public_url_for_generated_file(path)
        if url:
            public_urls.append({"path": str(path), "url": url})
        else:
            missing_public_urls.append(path.name)
    if missing_public_urls:
        warnings.append("Media has no public URL yet: " + ", ".join(missing_public_urls[:8]))

    routes: list[dict[str, Any]] = []
    for channel in channels:
        service = str(channel.get("service") or "buffer").lower()
        channel_id = str(channel.get("id") or "")
        route: dict[str, Any] = {
            "service": service,
            "channelId": channel_id,
            "name": channel.get("name") or service,
            "wouldSend": False,
            "reason": "",
            "metadata": {},
        }
        if path_is_within(post_folder, [SOCIAL_OUTPUT_DIR.resolve()]) or (
            path_is_within(post_folder, [EXPERIMENT_OUTPUT_DIR.resolve()])
            and metadata.get("kind") == "experiment_social_pack"
        ):
            route["wouldSend"] = service == "instagram"
            route["reason"] = "Daily image posts only route to Instagram." if service != "instagram" else "Instagram image post."
            route["textLength"] = len(str(metadata.get("instagram") or metadata.get("caption") or ""))
            route["metadata"] = {"instagram": {"type": "post", "shouldShareToFeed": True}} if service == "instagram" else {}
        elif path_is_within(post_folder, [TIKTOK_OUTPUT_DIR.resolve()]):
            is_deep = str(metadata.get("kind") or "") == "deep_tiktok" or post_folder.name.lower().endswith("-deep")
            if is_deep:
                route["wouldSend"] = service == "tiktok"
                route["reason"] = "Deep chapter videos only route to TikTok." if service != "tiktok" else "Deep TikTok video."
            else:
                route["wouldSend"] = service in {"tiktok", "instagram", "youtube"}
                route["reason"] = "Shorts/Reels route to TikTok, Instagram Reels, and YouTube Shorts." if route["wouldSend"] else "Unsupported Buffer service."
            if service == "youtube":
                route["metadata"] = {
                    "youtube": {
                        "title": metadata.get("youtube_shorts_title") or f"{metadata.get('novel', 'Chapter')} #{metadata.get('chapter', '')} #Shorts",
                        "categoryId": "22",
                        "privacy": "private",
                        "madeForKids": False,
                    }
                }
                route["textLength"] = len(str(metadata.get("youtube_shorts_description") or metadata.get("caption") or ""))
            elif service == "instagram":
                route["metadata"] = {"instagram": {"type": "reel", "shouldShareToFeed": True}}
                route["textLength"] = len(str(metadata.get("instagram_reel_caption") or metadata.get("caption") or ""))
            else:
                route["textLength"] = len(str(metadata.get("caption") or ""))
        elif path_is_within(post_folder, [OUTPUT_DIR.resolve()]):
            route["wouldSend"] = service in {"instagram", "tiktok"}
            route["reason"] = "Campaign promo media routes to Instagram/TikTok only." if route["wouldSend"] else "Full YouTube is handled by the browser helper, not Buffer."
            route["textLength"] = len(str(metadata.get("caption") or metadata.get("instagram") or ""))
            if service == "instagram":
                route["metadata"] = {"instagram": {"type": "reel" if any(path.suffix.lower() in VIDEO_EXTENSIONS for path in media) else "post", "shouldShareToFeed": True}}
        else:
            route["reason"] = "Unsupported post folder for Buffer."
        if route["wouldSend"] and not route.get("textLength"):
            route["wouldSend"] = False
            route["reason"] = "Post text/caption is blank."
        routes.append(route)

    send_routes = [route for route in routes if route.get("wouldSend")]
    if not send_routes:
        errors.append("No Buffer channel would receive this pack.")
    return {
        "ok": not errors and bool(send_routes),
        "folder": str(post_folder),
        "mode": mode,
        "textKind": text_kind,
        "packStatus": health.get("packStatus"),
        "canPushToBuffer": health.get("canPushToBuffer"),
        "mediaCount": len(media),
        "publicUrlCount": len(public_urls),
        "missingPublicUrls": missing_public_urls,
        "routes": routes,
        "qualityGate": quality,
        "health": health,
        "errors": clean_messages(errors),
        "warnings": clean_messages(warnings),
        "message": "Dry run only. No Buffer post was created.",
    }


def approved_daily_upload_roots() -> list[Path]:
    return [OUTPUT_DIR.resolve(), SOCIAL_OUTPUT_DIR.resolve(), TIKTOK_OUTPUT_DIR.resolve(), EXPERIMENT_OUTPUT_DIR.resolve()]


def resolve_approved_daily_upload_folder(folder: str) -> Path:
    post_folder = Path(folder).resolve()
    if not path_is_within(post_folder, approved_daily_upload_roots()):
        raise RuntimeError("Post folder is not valid for daily upload.")
    if not (post_folder / "metadata.json").exists():
        raise RuntimeError("This post folder does not contain metadata.")
    return post_folder


def daily_upload_text_kind(post_folder: Path, metadata: dict[str, Any]) -> str:
    if str(post_folder).startswith(str(TIKTOK_OUTPUT_DIR.resolve())):
        return "tiktok"
    return "instagram"


def approved_image_upload_gate(post_folder: Path, metadata: dict[str, Any], text_kind: str) -> dict[str, Any]:
    gate = folder_quality_gate(str(post_folder), text_kind, full_duplicate_scan=False)
    errors = list(gate.get("errors") or [])
    warnings = list(gate.get("warnings") or [])
    if metadata.get("imageReviewApprovedAt") or metadata.get("imageReviewOverrideAt"):
        errors = [item for item in errors if "image quality" not in str(item).lower()]
        warnings = [item for item in warnings if "image quality" not in str(item).lower()]
    approved = {
        Path(str(item)).name.lower()
        for item in metadata.get("approved_images", []) or []
        if str(item or "").strip()
    }
    rejected = {
        Path(str(item)).name.lower()
        for item in metadata.get("rejected_images", []) or []
        if str(item or "").strip()
    }
    selected = [
        Path(str(item)).name.lower()
        for item in metadata.get("images", []) or []
        if str(item or "").strip()
    ]
    is_deep_tiktok = str(metadata.get("kind") or "") == "deep_tiktok" or post_folder.name.lower().endswith("-deep")
    selected_rejected = [name for name in selected if name in rejected]
    if selected_rejected:
        errors.append("Rejected images are still selected for the post: " + ", ".join(selected_rejected[:4]))
    if is_deep_tiktok:
        missing_approval = [name for name in selected if name and name not in approved]
        if missing_approval:
            errors.append("Review and approve every Deep TikTok image before one-click upload: " + ", ".join(missing_approval[:4]))
        if metadata.get("videoNeedsRebuild"):
            errors.append("The video was not rebuilt after image changes.")
    return {
        **gate,
        "ok": not errors,
        "errors": errors,
        "warnings": warnings,
        "approvedImageCount": len(approved),
        "rejectedImageCount": len(rejected),
    }


def image_review_required_for_buffer(post_folder: Path, metadata: dict[str, Any], gate: dict[str, Any]) -> dict[str, Any]:
    if metadata.get("imageReviewApprovedAt") or metadata.get("imageReviewOverrideAt"):
        return {"required": False, "reason": "Images were manually reviewed.", "score": gate.get("imageQuality", {}).get("score", 0)}
    image_quality = gate.get("imageQuality") if isinstance(gate.get("imageQuality"), dict) else {}
    score = float(image_quality.get("score") or 0)
    items = image_quality.get("items") if isinstance(image_quality.get("items"), list) else []
    weak_items = [
        item for item in items
        if float(item.get("score") or 0) < IMAGE_PASSABLE_SCORE
    ]
    passable_items = [
        item for item in items
        if IMAGE_PASSABLE_SCORE <= float(item.get("score") or 0) < IMAGE_TRAINING_SCORE
    ]
    stock_items = [
        item for item in items
        if any(provider in str(item.get("source") or "").lower() for provider in ["pexels", "pixabay", "bank:"])
        and float(item.get("score") or 0) < IMAGE_TRAINING_SCORE
    ]
    warnings = [str(item) for item in gate.get("warnings") or [] if "Image quality" in str(item)]
    required = bool(score and score < IMAGE_PASSABLE_SCORE) or bool(weak_items)
    if required:
        return {
            "required": True,
            "score": score,
            "folder": str(post_folder),
            "reason": f"Image score is below the passable threshold ({IMAGE_PASSABLE_SCORE}/100). Review or regenerate before Buffer.",
            "weakImages": [
                {"image": Path(str(item.get("image") or "")).name, "path": str(item.get("image") or ""), "score": item.get("score"), "reasons": item.get("reasons", [])}
                for item in weak_items[:6]
            ],
            "warnings": warnings,
            "nextAction": "Open the pack, approve/regenerate the images, then run upload again.",
        }
    if passable_items or stock_items or warnings:
        return {
            "required": False,
            "score": score,
            "folder": str(post_folder),
            "reason": f"Image is passable for posting but below the training threshold ({IMAGE_TRAINING_SCORE}/100). Review is recommended before posting.",
            "warnings": warnings,
            "passableImages": [
                {"image": Path(str(item.get("image") or "")).name, "path": str(item.get("image") or ""), "score": item.get("score"), "reasons": item.get("reasons", [])}
                for item in (passable_items or stock_items)[:6]
            ],
        }
    return {"required": False, "score": score, "folder": str(post_folder), "reason": "Image score passed."}


def pack_review_images(post_folder: Path, metadata: dict[str, Any]) -> list[str]:
    images: list[str] = []

    def add_image(value: Any) -> None:
        if not str(value or "").strip():
            return
        path = Path(str(value))
        if not path.exists() and not path.is_absolute():
            path = post_folder / path.name
        if path.exists() and path.is_file() and path.suffix.lower() in IMAGE_EXTENSIONS:
            resolved = str(path.resolve())
            if resolved not in images:
                images.append(resolved)

    add_image(metadata.get("image"))
    add_image(metadata.get("reels_outro_image"))
    for item in metadata.get("images", []) or []:
        add_image(item)
    for key in ["candidate_images", "promo_images", "image_paths"]:
        for item in metadata.get(key, []) or []:
            add_image(item)

    if images:
        return images

    ignored_names = {
        "youtube-thumbnail.png",
        "overlay-preview.jpg",
        "thumbnail.png",
    }
    ignored_prefixes = (
        "tiktok-clean-",
        "frame-",
        "thumb-",
    )
    for path in sorted(post_folder.iterdir()):
        if not path.is_file() or path.suffix.lower() not in IMAGE_EXTENSIONS:
            continue
        name = path.name.lower()
        if name in ignored_names or any(name.startswith(prefix) for prefix in ignored_prefixes):
            continue
        resolved = str(path.resolve())
        if resolved not in images:
            images.append(resolved)
    return images


def mark_image_review_approved(folder: str) -> dict[str, Any]:
    post_folder = resolve_approved_daily_upload_folder(folder)
    metadata = read_metadata(post_folder)
    text_kind = daily_upload_text_kind(post_folder, metadata)
    gate = folder_quality_gate(str(post_folder), text_kind)
    image_quality = gate.get("imageQuality") if isinstance(gate.get("imageQuality"), dict) else {}
    images = pack_review_images(post_folder, metadata)
    rejected_keys = {
        str(Path(str(item)).resolve()).lower()
        for item in metadata.get("rejected_images", []) or []
        if str(item or "").strip() and Path(str(item)).exists()
    }
    approved_images: list[str] = []
    seen_approved: set[str] = set()
    for item in metadata.get("approved_images", []) or []:
        if not str(item or "").strip() or not Path(str(item)).exists():
            continue
        key = str(Path(str(item)).resolve()).lower()
        if key in seen_approved or key in rejected_keys:
            continue
        seen_approved.add(key)
        approved_images.append(str(Path(str(item)).resolve()))
    newly_approved: list[str] = []
    for image in images:
        key = str(Path(image).resolve()).lower()
        if key in rejected_keys or key in seen_approved:
            continue
        seen_approved.add(key)
        approved_images.append(str(Path(image).resolve()))
        newly_approved.append(str(Path(image).resolve()))
    metadata["approved_images"] = approved_images
    metadata["rejected_images"] = [
        str(Path(str(item)).resolve())
        for item in metadata.get("rejected_images", []) or []
        if str(item or "").strip() and Path(str(item)).exists()
    ]
    metadata["imageReviewApprovedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    metadata["imageReviewScore"] = image_quality.get("score", 0)
    metadata["imageReviewGateWarnings"] = gate.get("warnings", [])
    metadata["approvalManual"] = True
    metadata["approvedImageCount"] = len(approved_images)
    metadata["lastApprovalAction"] = {
        "image": "pack",
        "approved": True,
        "approvedCount": len(newly_approved),
        "rejectedCount": len(rejected_keys),
        "updatedAt": metadata["imageReviewApprovedAt"],
    }
    if str(post_folder).startswith(str(TIKTOK_OUTPUT_DIR.resolve())):
        metadata["packStatus"] = "ready_to_queue" if (post_folder / "tiktok-video.mp4").exists() else "needs_video_build"
        metadata["packStatusOverride"] = metadata["packStatus"]
    elif str(post_folder).startswith(str(SOCIAL_OUTPUT_DIR.resolve())):
        metadata["packStatus"] = "ready_to_queue"
        metadata["packStatusOverride"] = metadata["packStatus"]
    else:
        metadata["packStatus"] = "manual_review_ready"
        metadata["packStatusOverride"] = metadata["packStatus"]
    metadata["packStatusUpdatedAt"] = metadata["imageReviewApprovedAt"]
    write_json_atomic(post_folder / "metadata.json", metadata)
    return {
        "ok": True,
        "folder": str(post_folder),
        "score": metadata["imageReviewScore"],
        "packStatus": metadata["packStatus"],
        "approvedImageCount": len(approved_images),
        "rejectedImageCount": len(rejected_keys),
        "message": (
            f"{len(approved_images)} image(s) are approved for this pack; {len(newly_approved)} changed in this action."
            + (" Rejected images were left out and must be regenerated before posting." if rejected_keys else " Buffer upload can continue after other pack requirements pass.")
        ),
    }


def pack_preview(folder: str) -> dict[str, Any]:
    post_folder = resolve_approved_daily_upload_folder(folder)
    metadata = read_metadata(post_folder)
    images = pack_review_images(post_folder, metadata)
    videos = []
    for name in ["tiktok-video.mp4", "promo-video.mp4", "youtube-video.mp4"]:
        candidate = post_folder / name
        if candidate.exists():
            videos.append(str(candidate))
    gate = folder_quality_gate(str(post_folder), daily_upload_text_kind(post_folder, metadata), full_duplicate_scan=False)
    health = pack_health_item(post_folder) if (post_folder / "metadata.json").exists() else {}
    review_required = health.get("imageReviewRequired") if isinstance(health.get("imageReviewRequired"), dict) else {}
    preflight_errors = list(health.get("errors") or [])
    preflight_warnings = list(health.get("warnings") or [])
    if review_required.get("required"):
        preflight_errors.append(str(review_required.get("reason") or "Image review is required before Buffer."))
    elif review_required.get("reason"):
        preflight_warnings.append(str(review_required.get("reason")))
    buffer_preflight = {
        "canPush": bool(health.get("canPushToBuffer")),
        "status": str(health.get("packStatus") or ""),
        "nextAction": str(health.get("nextAction") or ""),
        "errors": preflight_errors,
        "warnings": preflight_warnings,
        "imageReviewRequired": review_required,
        "mediaCount": health.get("mediaCount", 0),
        "publicUrlCount": health.get("publicUrlCount", 0),
        "chapterPathMatch": health.get("chapterPathMatch", True),
        "activeChapter": health.get("activeChapter", ""),
    }
    approved_names = {
        Path(str(item)).name.lower()
        for item in metadata.get("approved_images", []) or []
        if str(item or "").strip()
    }
    rejected_names = {
        Path(str(item)).name.lower()
        for item in metadata.get("rejected_images", []) or []
        if str(item or "").strip()
    }
    quality_items_by_name = {
        Path(str(item.get("image") or "")).name.lower(): item
        for item in ((gate.get("imageQuality") or {}).get("items", []) if isinstance(gate.get("imageQuality"), dict) else [])
        if isinstance(item, dict)
    }
    image_cards = []
    for image in images:
        name = Path(image).name.lower()
        quality = quality_items_by_name.get(name, {})
        provider_trace = read_image_provider_trace(image)
        image_cards.append(
            {
                "image": image,
                "name": Path(image).name,
                "score": quality.get("score", ""),
                "reasons": quality.get("reasons", []),
                "source": quality.get("source", ""),
                "providerTrace": provider_trace,
                "approved": name in approved_names,
                "rejected": name in rejected_names,
            }
        )
    return {
        "ok": True,
        "folder": str(post_folder),
        "title": str(metadata.get("title") or metadata.get("chapter_title") or post_folder.name),
        "caption": str(metadata.get("instagram") or metadata.get("caption") or metadata.get("instagram_reel_caption") or ""),
        "images": images,
        "imageCards": image_cards,
        "videos": videos,
        "qualityGate": gate,
        "health": health,
        "bufferPreflight": buffer_preflight,
        "canPushToBuffer": bool(health.get("canPushToBuffer")),
        "bufferTextKind": str(health.get("bufferTextKind") or daily_upload_text_kind(post_folder, metadata)),
        "bufferLabel": str(health.get("bufferLabel") or "Push to Buffer"),
        "packStatus": str(health.get("packStatus") or ""),
        "videoNeedsRebuild": bool(metadata.get("videoNeedsRebuild")),
        "lastApprovalAction": metadata.get("lastApprovalAction", {}),
        "lastImageFeedback": metadata.get("lastImageFeedback", {}),
        "metadata": {key: metadata.get(key) for key in ["abbr", "chapter", "kind", "image_source", "image_sources"] if key in metadata},
    }


def one_click_daily_upload(folder: str, mode: str = "addToQueue") -> dict[str, Any]:
    post_folder = resolve_approved_daily_upload_folder(folder)
    metadata = read_metadata(post_folder)
    if str(post_folder).startswith(str(TIKTOK_OUTPUT_DIR.resolve())) and (
        str(metadata.get("kind") or "") == "deep_tiktok" or post_folder.name.lower().endswith("-deep")
    ):
        metadata = repair_deep_tiktok_metadata(post_folder, metadata)
    family = daily_upload_family(post_folder)
    steps: list[dict[str, Any]] = []
    gates: dict[str, Any] = {}
    configured_channels = configured_buffer_channels()
    instagram_channels = [channel["id"] for channel in configured_channels if channel.get("id") and channel.get("service") == "instagram"]
    shorts_channels = [
        channel["id"]
        for channel in configured_channels
        if channel.get("id") and channel.get("service") in {"instagram", "tiktok", "youtube"}
    ]
    if not instagram_channels and not shorts_channels:
        raise RuntimeError("Add Instagram, TikTok, and YouTube Shorts Buffer channel IDs in Connections first.")

    buffer_result: dict[str, Any] = {"posts": [], "skipped": True, "message": "No primary single-folder Buffer push was run; daily bundle mode handled the matching packs."}
    extra_buffer_results: list[dict[str, Any]] = []
    social_folder = Path(family["social"]["folder"]).resolve() if family["social"].get("folder") else None
    social_metadata = family["social"].get("metadata") if isinstance(family["social"].get("metadata"), dict) else {}
    shorts_folder = Path(family["shorts"]["folder"]).resolve() if family["shorts"].get("folder") else None
    shorts_metadata = family["shorts"].get("metadata") if isinstance(family["shorts"].get("metadata"), dict) else {}
    campaign_folder = Path(family["campaign"]["folder"]).resolve() if family["campaign"].get("folder") else None
    campaign_metadata = family["campaign"].get("metadata") if isinstance(family["campaign"].get("metadata"), dict) else {}

    if social_folder and social_folder.exists():
        social_gate = approved_image_upload_gate(social_folder, social_metadata, "instagram")
        gates["social"] = social_gate
        social_review = image_review_required_for_buffer(social_folder, social_metadata, social_gate)
        gates["socialImageReview"] = social_review
        if not social_gate.get("ok"):
            steps.append(daily_upload_step("instagram_daily", "blocked", "Daily Instagram image needs review.", errors=social_gate.get("errors", []), folder=str(social_folder)))
        elif social_review.get("required"):
            steps.append(daily_upload_step("instagram_daily", "blocked", social_review.get("reason") or "Daily Instagram image needs review before Buffer.", imageScore=social_review.get("score"), weakImages=social_review.get("weakImages", []), folder=str(social_folder), openPack=True))
        elif folder_has_successful_buffer_post(social_folder):
            steps.append(daily_upload_step("instagram_daily", "already_done", "Daily Instagram image already has a successful Buffer post recorded.", folder=str(social_folder)))
        elif instagram_channels:
            result = buffer_post_from_folder(str(social_folder), instagram_channels, "instagram", mode, advance_path=False)
            extra_buffer_results.append({"folder": str(social_folder), "kind": "daily_instagram_image", "result": result})
            count = buffer_success_count(result)
            steps.append(daily_upload_step("instagram_daily", "queued" if count else "skipped", f"{count} Instagram daily post(s) sent to Buffer.", folder=str(social_folder), posts=result.get("posts", [])))
        else:
            steps.append(daily_upload_step("instagram_daily", "skipped", "No Instagram Buffer channel is configured.", folder=str(social_folder)))
    else:
        steps.append(daily_upload_step("instagram_daily", "missing", "No matching daily social image pack was found."))

    if shorts_folder and shorts_folder.exists():
        shorts_gate = approved_image_upload_gate(shorts_folder, shorts_metadata, "tiktok")
        gates["shorts"] = shorts_gate
        shorts_review = image_review_required_for_buffer(shorts_folder, shorts_metadata, shorts_gate)
        gates["shortsImageReview"] = shorts_review
        if not shorts_gate.get("ok"):
            steps.append(daily_upload_step("shorts_reels", "blocked", "Short/Reel video needs review or rebuild.", errors=shorts_gate.get("errors", []), folder=str(shorts_folder)))
        elif shorts_review.get("required"):
            steps.append(daily_upload_step("shorts_reels", "blocked", shorts_review.get("reason") or "Short/Reel image score needs review before Buffer.", imageScore=shorts_review.get("score"), weakImages=shorts_review.get("weakImages", []), folder=str(shorts_folder), openPack=True))
        elif folder_has_successful_buffer_post(shorts_folder):
            steps.append(daily_upload_step("shorts_reels", "already_done", "Short/Reel pack already has a successful Buffer post recorded.", folder=str(shorts_folder)))
        elif shorts_channels:
            result = buffer_post_from_folder(str(shorts_folder), shorts_channels, "tiktok", mode, advance_path=False)
            extra_buffer_results.append({"folder": str(shorts_folder), "kind": "shorts_reels_video", "result": result})
            count = buffer_success_count(result)
            steps.append(daily_upload_step("shorts_reels", "queued" if count else "skipped", f"{count} TikTok/Reel/Short post(s) sent to Buffer.", folder=str(shorts_folder), posts=result.get("posts", [])))
        else:
            steps.append(daily_upload_step("shorts_reels", "skipped", "No TikTok/Instagram/YouTube Shorts Buffer channels are configured.", folder=str(shorts_folder)))
    else:
        steps.append(daily_upload_step("shorts_reels", "missing", "No matching short/reel pack was found."))

    manual_results: list[dict[str, Any]] = []
    manual_errors: list[str] = []
    if campaign_folder and campaign_folder.exists():
        try:
            patreon_result = build_patreon_draft(str(campaign_folder))
            manual_results.append({"platform": "patreon", **patreon_result})
            steps.append(daily_upload_step("patreon", "prepared" if not patreon_result.get("skip") else "skipped", patreon_result.get("message") or "Patreon draft prepared for review.", folder=str(campaign_folder)))
        except Exception as exc:
            manual_errors.append(f"patreon: {exc}")
            steps.append(daily_upload_step("patreon", "failed", str(exc), folder=str(campaign_folder)))
    else:
        steps.append(daily_upload_step("patreon", "missing", "No matching Patreon campaign pack was found."))

    manual_social_folder = social_folder if social_folder and social_folder.exists() else campaign_folder
    if manual_social_folder and manual_social_folder.exists():
        if path_is_within(manual_social_folder, [SOCIAL_OUTPUT_DIR.resolve(), EXPERIMENT_OUTPUT_DIR.resolve()]):
            try:
                preview = social_post_preview(
                    str(manual_social_folder),
                    use_playwright=True,
                    platforms=["x", "facebook"],
                )
                prepared_platforms = {
                    str(item.get("key") or "").strip().lower(): item
                    for item in preview.get("platforms", [])
                    if isinstance(item, dict)
                }
                helper_ready = bool(
                    preview.get("playwright_launched")
                    and preview.get("playwright_returncode") == 0
                )
                for label in ["x", "facebook"]:
                    platform_spec = prepared_platforms.get(label)
                    if not platform_spec:
                        message = f"No {label.title()} text was available in this daily post pack."
                        manual_errors.append(f"{label}: {message}")
                        steps.append(daily_upload_step(label, "failed", message, folder=str(manual_social_folder)))
                        continue
                    item = {
                        **preview,
                        "platform": platform_spec.get("label") or label.title(),
                        "image": platform_spec.get("media_path") or "",
                        "text": platform_spec.get("text") or "",
                        "message": (
                            f"{platform_spec.get('label') or label.title()} draft filled in the Chrome helper for review."
                            if helper_ready
                            else f"{platform_spec.get('label') or label.title()} page opened, but the Chrome helper was not available."
                        ),
                    }
                    manual_results.append(item)
                    steps.append(
                        daily_upload_step(
                            label,
                            "prepared" if helper_ready else "failed",
                            item["message"],
                            folder=str(manual_social_folder),
                            helperLaunched=helper_ready,
                        )
                    )
                    if not helper_ready:
                        manual_errors.append(f"{label}: Chrome helper did not launch.")
            except Exception as exc:
                for label in ["x", "facebook"]:
                    manual_errors.append(f"{label}: {exc}")
                    steps.append(daily_upload_step(label, "failed", str(exc), folder=str(manual_social_folder)))
        elif path_is_within(manual_social_folder, [OUTPUT_DIR.resolve()]):
            for platform in ["x", "facebook"]:
                try:
                    item = manual_text_platform_assist(str(manual_social_folder), platform)
                    manual_results.append(item)
                    steps.append(daily_upload_step(platform, "prepared", item.get("message") or f"{platform} opened for review.", folder=str(manual_social_folder)))
                except Exception as exc:
                    manual_errors.append(f"{platform}: {exc}")
                    steps.append(daily_upload_step(platform, "failed", str(exc), folder=str(manual_social_folder)))
    else:
        for platform in ["x", "facebook"]:
            steps.append(daily_upload_step(platform, "missing", "No social/campaign folder was available for manual review."))

    abbr = str(family.get("abbr") or "")
    chapter = int(family.get("chapter") or 0)
    blocked_steps = [step for step in steps if step.get("status") in {"blocked", "failed"}]
    buffer_queued = any(step.get("status") in {"queued", "already_done"} for step in steps)
    if abbr and chapter and buffer_queued and not blocked_steps:
        now = time.strftime("%Y-%m-%d %H:%M:%S")
        update_chapter_ledger(
            abbr,
            chapter,
            {
                "dailyOneClickUploadPrepared": True,
                "dailyOneClickUploadPreparedAt": now,
                "socialPostsQueued": bool(social_folder),
                "socialPostsQueuedAt": now if social_folder else "",
                "shortsReelsQueued": bool(shorts_folder),
                "shortsReelsQueuedAt": now if shorts_folder else "",
                "manualDraftsPrepared": True,
                "manualDraftsPreparedAt": now,
            },
        )
        if chapter_can_advance_active_path(abbr, chapter):
            try:
                advance_completed_chapter(abbr, chapter, "promo")
                steps.append(daily_upload_step("chapter_path", "advanced", f"{abbr} advanced after daily upload bundle completed.", chapter=chapter))
            except Exception as exc:
                manual_errors.append(f"chapter path: {exc}")
                steps.append(daily_upload_step("chapter_path", "failed", str(exc), chapter=chapter))
    elif blocked_steps:
        steps.append(daily_upload_step("chapter_path", "held", "Chapter path was not advanced because at least one required step was blocked or failed.", chapter=chapter))
    else:
        steps.append(daily_upload_step("chapter_path", "held", "Chapter path was not advanced because no Buffer posts were queued.", chapter=chapter))

    run_record = {
        "uploaded_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        "mode": mode,
        "family": {key: value for key, value in family.items() if key not in {"selected", "campaign", "social", "shorts"}},
        "selectedFolder": str(post_folder),
        "campaignFolder": str(campaign_folder) if campaign_folder else "",
        "socialFolder": str(social_folder) if social_folder else "",
        "shortsFolder": str(shorts_folder) if shorts_folder else "",
        "steps": steps,
        "manual_errors": manual_errors,
    }
    touched_folders = [folder_path for folder_path in [post_folder, campaign_folder, social_folder, shorts_folder] if folder_path and folder_path.exists()]
    for touched in {str(path): path for path in touched_folders}.values():
        touched_metadata = read_metadata(touched)
        touched_metadata.setdefault("one_click_daily_uploads", []).append(run_record)
        write_json_atomic(touched / "metadata.json", touched_metadata)
    return {
        "ok": not blocked_steps,
        "folder": str(post_folder),
        "family": {
            "abbr": abbr,
            "novel": family.get("novel"),
            "chapter": chapter,
            "campaignFolder": str(campaign_folder) if campaign_folder else "",
            "socialFolder": str(social_folder) if social_folder else "",
            "shortsFolder": str(shorts_folder) if shorts_folder else "",
        },
        "textKind": daily_upload_text_kind(post_folder, metadata),
        "qualityGate": gates,
        "buffer": buffer_result,
        "extraBuffer": extra_buffer_results,
        "manual": manual_results,
        "manualErrors": manual_errors,
        "steps": steps,
        "message": "Daily upload bundle finished." if not blocked_steps else "Daily upload bundle needs review before it can be considered complete.",
    }


def multipart_bearer_request(url: str, token: str, fields: dict[str, str], files: dict[str, Path]) -> dict[str, Any]:
    boundary = f"----AutomationTool{int(time.time() * 1000)}"
    chunks: list[bytes] = []
    for name, value in fields.items():
        chunks.extend(
            [
                f"--{boundary}\r\n".encode("utf-8"),
                f'Content-Disposition: form-data; name="{name}"\r\n\r\n'.encode("utf-8"),
                str(value).encode("utf-8"),
                b"\r\n",
            ]
        )
    for name, path in files.items():
        filename = path.name
        content_type = "image/png" if path.suffix.lower() == ".png" else "application/octet-stream"
        chunks.extend(
            [
                f"--{boundary}\r\n".encode("utf-8"),
                f'Content-Disposition: form-data; name="{name}"; filename="{filename}"\r\n'.encode("utf-8"),
                f"Content-Type: {content_type}\r\n\r\n".encode("utf-8"),
                path.read_bytes(),
                b"\r\n",
            ]
        )
    chunks.append(f"--{boundary}--\r\n".encode("utf-8"))
    body = b"".join(chunks)
    request = urllib.request.Request(
        url,
        data=body,
        headers={"Authorization": f"Bearer {token}", "Content-Type": f"multipart/form-data; boundary={boundary}"},
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=180) as response:
        return json.loads(response.read().decode("utf-8"))


def discover_instagram_accounts() -> dict[str, Any]:
    token = os.environ.get("INSTAGRAM_ACCESS_TOKEN", "").strip()
    if not token:
        raise RuntimeError("Save an access token first.")
    return graph_get(
        "me/accounts",
        {
            "fields": "id,name,instagram_business_account{id,username,name}",
            "access_token": token,
        },
    )


def public_social_image_url(folder: Path, image: Path) -> str | None:
    base = normalize_public_base_url(os.environ.get("INSTAGRAM_PUBLIC_BASE_URL", ""))
    if not base:
        return None
    relative = image.relative_to(SOCIAL_OUTPUT_DIR).as_posix()
    return f"{base}/{urllib.parse.quote(relative, safe='/')}"


def publish_instagram_image(folder: str) -> dict[str, Any]:
    token = os.environ.get("INSTAGRAM_ACCESS_TOKEN", "").strip()
    ig_user_id = os.environ.get("INSTAGRAM_ACCOUNT_ID", "").strip()
    if not token or not ig_user_id:
        raise RuntimeError("Instagram is not configured. Add INSTAGRAM_ACCOUNT_ID and INSTAGRAM_ACCESS_TOKEN to .env.local.")

    post_folder = Path(folder).resolve()
    if not str(post_folder).startswith(str(SOCIAL_OUTPUT_DIR.resolve())):
        raise RuntimeError("Social post folder is not valid.")
    metadata_path = post_folder / "metadata.json"
    if not metadata_path.exists():
        raise RuntimeError("This folder does not contain social post metadata.")
    metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
    image_path = Path(metadata["image"]).resolve()
    image_url = metadata.get("public_image_url") or public_social_image_url(post_folder, image_path)
    if not image_url:
        raise RuntimeError(
            "Instagram needs a public HTTPS image URL. Set INSTAGRAM_PUBLIC_BASE_URL in .env.local "
            "to the public URL where social-posts is hosted."
        )
    if not image_url.lower().startswith("https://"):
        raise RuntimeError("INSTAGRAM_PUBLIC_BASE_URL must start with https:// for Instagram publishing.")

    graph = f"https://graph.facebook.com/{META_GRAPH_API_VERSION}"
    container = form_request(
        f"{graph}/{ig_user_id}/media",
        {
            "image_url": image_url,
            "caption": metadata.get("instagram", ""),
            "alt_text": metadata.get("alt_text", ""),
            "access_token": token,
        },
    )
    creation_id = container.get("id")
    if not creation_id:
        raise RuntimeError(f"Instagram did not return a media container id: {container}")
    published = form_request(
        f"{graph}/{ig_user_id}/media_publish",
        {"creation_id": creation_id, "access_token": token},
    )
    metadata["instagram_publish"] = {
        "container_id": creation_id,
        "publish_response": published,
        "published_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        "image_url": image_url,
    }
    metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    return {"container_id": creation_id, "publish_response": published, "image_url": image_url}


def manual_instagram_assist(folder: str) -> dict[str, Any]:
    post_folder = Path(folder).resolve()
    if not str(post_folder).startswith(str(SOCIAL_OUTPUT_DIR.resolve())):
        raise RuntimeError("Social post folder is not valid.")
    ensure_quality_gate(str(post_folder), "instagram")
    metadata_path = post_folder / "metadata.json"
    if not metadata_path.exists():
        raise RuntimeError("This folder does not contain social post metadata.")
    metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
    caption = metadata.get("instagram", "")
    image_path = Path(metadata["image"]).resolve()
    caption_file = post_folder / "instagram.txt"

    try:
        subprocess.run(["powershell", "-NoProfile", "-Command", f"Get-Content -Raw -LiteralPath '{caption_file}' | Set-Clipboard"], check=False)
    except Exception:
        pass
    try:
        os.startfile(str(post_folder))
    except Exception:
        pass
    try:
        open_url_once("https://www.instagram.com/")
    except Exception:
        pass

    metadata["manual_instagram_assist"] = {
        "opened_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        "image": str(image_path),
        "caption_file": str(caption_file),
    }
    metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    return {
        "image": str(image_path),
        "caption": caption,
        "caption_file": str(caption_file),
        "folder": str(post_folder),
        "message": "Opened Instagram and the post folder. Caption copied to clipboard.",
    }


def mark_manual_instagram_posted(folder: str) -> dict[str, Any]:
    post_folder = Path(folder).resolve()
    if not str(post_folder).startswith(str(SOCIAL_OUTPUT_DIR.resolve())):
        raise RuntimeError("Social post folder is not valid.")
    metadata_path = post_folder / "metadata.json"
    if not metadata_path.exists():
        raise RuntimeError("This folder does not contain social post metadata.")
    metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
    metadata["manual_instagram_posted"] = {
        "posted_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        "status": "confirmed_by_user",
    }
    metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    (post_folder / "manual-posted.txt").write_text(
        f"Instagram post manually marked complete at {metadata['manual_instagram_posted']['posted_at']}\n",
        encoding="utf-8",
    )
    abbr, chapter_number, updates = chapter_ledger_updates_for_folder(post_folder, metadata, "socialPostsQueued")
    if abbr and chapter_number:
        progress_tool = post_progress_tool(metadata)
        if progress_tool == "promo":
            updates.update(
                {
                    "instagramQueued": True,
                    "socialPostsQueuedAt": metadata["manual_instagram_posted"]["posted_at"],
                }
            )
            update_chapter_ledger(abbr, chapter_number, updates)
        if chapter_can_advance_active_path(abbr, chapter_number):
            advance_completed_chapter(abbr, chapter_number, progress_tool)
    clickup_sync = {}
    try:
        clickup_sync = sync_clickup_manual_publish(post_folder, "instagram", metadata, contentType="daily-social-post")
    except Exception as exc:
        record_recovery_event("clickup_publish_sync", f"ClickUp Instagram sync failed: {exc}", error_type="clickup_publish_sync_failed", folder=post_folder)
        clickup_sync = {"ok": False, "error": str(exc)}
    return {"posted": True, "folder": str(post_folder), "clickup": clickup_sync}


def manual_x_assist(folder: str) -> dict[str, Any]:
    post_folder = Path(folder).resolve()
    if not (
        str(post_folder).startswith(str(SOCIAL_OUTPUT_DIR.resolve()))
        or str(post_folder).startswith(str(EXPERIMENT_OUTPUT_DIR.resolve()))
    ):
        raise RuntimeError("Social post folder is not valid.")
    ensure_quality_gate(str(post_folder), "x")
    metadata_path = post_folder / "metadata.json"
    if not metadata_path.exists():
        raise RuntimeError("This folder does not contain social post metadata.")
    metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
    image_path = Path(metadata["image"]).resolve()
    x_file = post_folder / "x.txt"
    try:
        subprocess.run(["powershell", "-NoProfile", "-Command", f"Get-Content -Raw -LiteralPath '{x_file}' | Set-Clipboard"], check=False)
    except Exception:
        pass
    try:
        os.startfile(str(post_folder))
    except Exception:
        pass
    try:
        open_url_once("https://x.com/compose/post")
    except Exception:
        pass
    metadata["manual_x_assist"] = {
        "opened_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        "image": str(image_path),
        "x_file": str(x_file),
    }
    metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    return {
        "image": str(image_path),
        "text": metadata.get("x", ""),
        "x_file": str(x_file),
        "folder": str(post_folder),
        "message": "Opened X and the post folder. X text copied to clipboard.",
    }


