concat = folder / "youtube-clips.txt"
concat.write_text("\\n".join([ffconcat_line(clip) for clip in clips]) + "\\n", encoding="utf-8")

command = [ffmpeg_exe, "-hide_banner", "-loglevel", "error", "-y", "-f", "concat", "-safe", "0", "-i", str(concat)]
if audio_source.exists():
    command += ["-i", str(audio_source), "-shortest"]
