def run_generated_video_builder(folder: Path, script_name: str, output_name: str, timeout: int = 900) -> dict[str, Any]:
    script = folder / script_name
    output = folder / output_name
    if not script.exists():
        return {"script": script_name, "output": output_name, "created": False, "message": "Builder file was not created."}
    started = time.strftime("%Y-%m-%d %H:%M:%S")
    try:
        with HeavyJobLimiter():
            run = subprocess.run(
                [sys.executable, str(script)],
                cwd=str(folder),
                capture_output=True,
                text=True,
                timeout=timeout,
                check=False,
            )
        message = (run.stdout + "\n" + run.stderr).strip()
        if output.suffix.lower() in VIDEO_EXTENSIONS:
            created, duration = wait_for_video_ready(output, 0.0, 30.0)
        else:
            created = output.exists()
            duration = 0.0
        minimum_duration = expected_youtube_min_duration(folder) if output.name == "youtube-video.mp4" else 0.0
        if created and minimum_duration and duration < minimum_duration:
            created = False
            message = (
                f"Generated video is too short for the full chapter: {duration:.2f}s. "
                f"Expected at least {minimum_duration:.2f}s. Rebuild after refreshing the YouTube builder.\n\n"
                + message
            ).strip()
        if "OpenAI TTS failed" in message or "Too Many Requests" in message:
            record_recovery_event(
                script_name,
                "OpenAI TTS failed during video build; fallback audio path was used or attempted.",
                error_type="openai_tts_quota",
                folder=folder,
                details={
                    "script": script_name,
                    "output": str(output),
                    "created": created,
                    "message": message[-1200:],
                },
            )
        return {
            "script": script_name,
            "output": str(output),
            "created": created,
            "duration": duration,
            "minimum_duration": minimum_duration,
            "returncode": run.returncode,
            "started_at": started,
            "finished_at": time.strftime("%Y-%m-%d %H:%M:%S"),
            "message": message[-4000:] if message else "Builder finished.",
        }
    except Exception as exc:
        record_recovery_event(
            script_name,
            str(exc),
            folder=folder,
            details={"script": script_name, "output": str(output)},
        )
        return {
            "script": script_name,
            "output": str(output),
            "created": media_file_valid(output, "v:0") if output.suffix.lower() in VIDEO_EXTENSIONS else output.exists(),
            "started_at": started,
            "finished_at": time.strftime("%Y-%m-%d %H:%M:%S"),
            "error": str(exc),
        }


def render_campaign_videos(folder: Path) -> dict[str, Any]:
    builds = [
        run_generated_video_builder(folder, "make_video.py", "promo-video.mp4"),
        run_generated_video_builder(folder, "make_youtube_video.py", "youtube-video.mp4"),
    ]
    return {
        "auto": True,
        "builds": builds,
        "created": [build["output"] for build in builds if build.get("created")],
    }


def normalize_youtube_video_for_buffer(post_folder: Path) -> dict[str, Any] | None:
    post_folder = post_folder.resolve()
    source = post_folder / "youtube-video.mp4"
    target = post_folder / "youtube-buffer.mp4"
    if not media_file_valid(source, "v:0"):
        return None
    if media_file_valid(target, "v:0") and target.stat().st_mtime >= source.stat().st_mtime:
        return {"created": True, "output": str(target), "already_exists": True, "buffer_safe": True}
    started = time.strftime("%Y-%m-%d %H:%M:%S")
    try:
        run = subprocess.run(
            [
                find_ffmpeg_executable(),
                "-y",
                "-i",
                str(source),
                "-map",
                "0:v:0",
                "-map",
                "0:a:0?",
                "-vf",
                "scale=1920:1080:force_original_aspect_ratio=increase,crop=1920:1080,fps=30,setsar=1,setdar=16/9,format=yuv420p",
                "-c:v",
                "libx264",
                "-profile:v",
                "high",
                "-level",
                "4.1",
                "-preset",
                "veryfast",
                "-crf",
                "30",
                "-maxrate",
                "1500k",
                "-bufsize",
                "3000k",
                "-c:a",
                "aac",
                "-b:a",
                "128k",
                "-movflags",
                "+faststart",
                "-metadata:s:v:0",
                "rotate=0",
                str(target),
            ],
            cwd=str(post_folder),
            capture_output=True,
            text=True,
            timeout=1200,
            check=False,
        )
        message = (run.stdout + "\n" + run.stderr).strip()
        return {
            "script": "normalize_youtube_video_for_buffer",
            "source": str(source),
            "output": str(target),
            "created": media_file_valid(target, "v:0") and run.returncode == 0,
            "returncode": run.returncode,
            "started_at": started,
            "finished_at": time.strftime("%Y-%m-%d %H:%M:%S"),
            "message": message[-4000:] if message else "Buffer-safe YouTube video created.",
            "buffer_safe": True,
        }
    except Exception as exc:
        return {
            "script": "normalize_youtube_video_for_buffer",
            "source": str(source),
            "output": str(target),
            "created": media_file_valid(target, "v:0"),
            "started_at": started,
            "finished_at": time.strftime("%Y-%m-%d %H:%M:%S"),
            "error": str(exc),
            "buffer_safe": True,
        }


def ensure_buffer_video(post_folder: Path, text_kind: str = "") -> dict[str, Any] | None:
    if str(post_folder).startswith(str(TIKTOK_OUTPUT_DIR.resolve())):
        output = post_folder / "tiktok-video.mp4"
        if video_meets_minimum_duration(output, 3.0):
            return {"created": True, "output": str(output), "already_exists": True, "duration": media_duration_seconds(output)}
        if output.exists():
            try:
                output.unlink()
            except OSError:
                pass
        return run_generated_video_builder(post_folder, "make_tiktok_video.py", "tiktok-video.mp4", timeout=600)
    if str(post_folder).startswith(str(YOUTUBE_OUTPUT_DIR.resolve())):
        buffer_output = post_folder / "youtube-buffer.mp4"
        if media_file_valid(buffer_output, "v:0"):
            return {"created": True, "output": str(buffer_output), "already_exists": True, "buffer_safe": True}
        output = post_folder / "youtube-video.mp4"
        if not media_file_valid(output, "v:0"):
            build = run_generated_video_builder(post_folder, "build_youtube_video.py", "youtube-video.mp4", timeout=1200)
            if not build.get("created") and not media_file_valid(output, "v:0"):
                return build
        return normalize_youtube_video_for_buffer(post_folder)
    if text_kind == "youtube":
        buffer_output = post_folder / "youtube-buffer.mp4"
        if media_file_valid(buffer_output, "v:0"):
            return {"created": True, "output": str(buffer_output), "already_exists": True, "buffer_safe": True}
        output = post_folder / "youtube-video.mp4"
        if not media_file_valid(output, "v:0"):
            build = run_generated_video_builder(post_folder, "make_youtube_video.py", "youtube-video.mp4", timeout=1200)
            if not build.get("created") and not media_file_valid(output, "v:0"):
                return build
        return normalize_youtube_video_for_buffer(post_folder)
    return None


def find_examples() -> list[dict[str, str]]:
    roots = [ROOT.parent, ROOT]
    patterns = {".png", ".jpg", ".jpeg", ".webp", ".mp4", ".txt", ".md"}
    found: list[dict[str, str]] = []
    for root in roots:
        if not root.exists():
            continue
        for path in root.rglob("*"):
            if len(found) >= 80:
                return found
            if path.is_file() and path.suffix.lower() in patterns:
                if any(part.lower() in {"node_modules", ".git", "__pycache__", "campaigns"} for part in path.parts):
                    continue
                found.append({"name": path.name, "path": str(path)})
    return found


